--
-- Name: _search_simple_dataset_latest(regclass, text, jsonb, bigint, bigint, text, text, uuid, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api._search_simple_dataset_latest(p_table regclass, query_text text, filter_condition jsonb DEFAULT '{}'::jsonb, page_size bigint DEFAULT 10, page_current bigint DEFAULT 1, data_source text DEFAULT 'tg'::text, this_user_id text DEFAULT ''::text, team_id_filter uuid DEFAULT NULL::uuid, state_code_filter integer DEFAULT NULL::integer) RETURNS TABLE(rank bigint, id uuid, "json" jsonb, version character, modified_at timestamp with time zone, team_id uuid, total_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    SET statement_timeout TO '60s'
    AS $_$
declare
  normalized_page_size bigint;
  normalized_page_current bigint;
  normalized_this_user_id uuid;
  exact_query_id uuid;
  filter_condition_jsonb jsonb;
  json_filter_clause text;
  v_sql text;
begin
  normalized_page_size := greatest(coalesce(page_size, 10), 1);
  normalized_page_current := greatest(coalesce(page_current, 1), 1);
  normalized_this_user_id := case
    when coalesce(btrim(this_user_id) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', false)
      then btrim(this_user_id)::uuid
    else null::uuid
  end;
  exact_query_id := case
    when coalesce(btrim(query_text) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', false)
      then btrim(query_text)::uuid
    else null::uuid
  end;
  filter_condition_jsonb := coalesce(filter_condition, '{}'::jsonb);
  json_filter_clause := case
    when filter_condition_jsonb = '{}'::jsonb then ''
    else 'and d.json @> $8'
  end;

  if exact_query_id is not null then
    v_sql := format($sql$
      with matched_ids as (
        select d.id, 1.0::double precision as search_score
        from %1$s d
        where d.id = $1
          and (
            ($4 = 'tg' and d.state_code = 100 and ($6 is null or d.team_id = $6))
            or ($4 = 'co' and d.state_code = 200 and ($6 is null or d.team_id = $6))
            or ($4 = 'my' and $5 is not null and d.user_id = $5 and ($7 is null or d.state_code = $7))
            or ($4 = 'te' and $6 is not null and d.team_id = $6 and ($7 is null or d.state_code = $7))
          )
          %2$s
        group by d.id
      ),
      latest_rows as (
        select matched_ids.id, latest_row.json, latest_row.version, latest_row.modified_at, latest_row.team_id, matched_ids.search_score
        from matched_ids
        join lateral (
          select d2.json, d2.version, d2.modified_at, d2.team_id
          from %1$s d2
          where d2.id = matched_ids.id
            and (
              ($4 = 'tg' and d2.state_code = 100 and ($6 is null or d2.team_id = $6))
              or ($4 = 'co' and d2.state_code = 200 and ($6 is null or d2.team_id = $6))
              or ($4 = 'my' and $5 is not null and d2.user_id = $5 and ($7 is null or d2.state_code = $7))
              or ($4 = 'te' and $6 is not null and d2.team_id = $6 and ($7 is null or d2.state_code = $7))
            )
          order by d2.version desc, d2.modified_at desc
          limit 1
        ) latest_row on true
      ),
      counted_rows as (
        select latest_rows.*, count(*) over()::bigint as total_count
        from latest_rows
      )
      select 1::bigint as rank, counted_rows.id, counted_rows.json, counted_rows.version, counted_rows.modified_at, counted_rows.team_id, counted_rows.total_count
      from counted_rows
      order by rank, counted_rows.id
      limit $2
      offset ($3 - 1) * $2
    $sql$, p_table, json_filter_clause);

    return query execute v_sql
      using exact_query_id, normalized_page_size, normalized_page_current,
            data_source, normalized_this_user_id, team_id_filter, state_code_filter,
            filter_condition_jsonb;
    return;
  end if;

  json_filter_clause := case
    when filter_condition_jsonb = '{}'::jsonb then ''
    else 'and d.json @> $2'
  end;

  v_sql := format($sql$
    with text_matches as materialized (
      select d.id,
             d.json,
             d.state_code,
             d.team_id,
             d.user_id,
             pgroonga_score(d.tableoid, d.ctid) as search_score
      from %1$s d
      where d.search_text &@~ $1
    ),
    matched_ids as (
      select d.id, max(d.search_score) as search_score
      from text_matches d
      where (
          ($5 = 'tg' and d.state_code = 100 and ($7 is null or d.team_id = $7))
          or ($5 = 'co' and d.state_code = 200 and ($7 is null or d.team_id = $7))
          or ($5 = 'my' and $6 is not null and d.user_id = $6 and ($8 is null or d.state_code = $8))
          or ($5 = 'te' and $7 is not null and d.team_id = $7 and ($8 is null or d.state_code = $8))
        )
        %2$s
      group by d.id
    ),
    latest_rows as (
      select matched_ids.id, latest_row.json, latest_row.version, latest_row.modified_at, latest_row.team_id, matched_ids.search_score
      from matched_ids
      join lateral (
        select d2.json, d2.version, d2.modified_at, d2.team_id
        from %1$s d2
        where d2.id = matched_ids.id
          and (
            ($5 = 'tg' and d2.state_code = 100 and ($7 is null or d2.team_id = $7))
            or ($5 = 'co' and d2.state_code = 200 and ($7 is null or d2.team_id = $7))
            or ($5 = 'my' and $6 is not null and d2.user_id = $6 and ($8 is null or d2.state_code = $8))
            or ($5 = 'te' and $7 is not null and d2.team_id = $7 and ($8 is null or d2.state_code = $8))
          )
        order by d2.version desc, d2.modified_at desc
        limit 1
      ) latest_row on true
    ),
    counted_rows as (
      select latest_rows.*, count(*) over()::bigint as total_count
      from latest_rows
    ),
    ranked_rows as (
      select rank() over (order by counted_rows.search_score desc, counted_rows.modified_at desc, counted_rows.id)::bigint as rank,
             counted_rows.*
      from counted_rows
    )
    select ranked_rows.rank, ranked_rows.id, ranked_rows.json, ranked_rows.version, ranked_rows.modified_at, ranked_rows.team_id, ranked_rows.total_count
    from ranked_rows
    order by ranked_rows.rank, ranked_rows.id
    limit $3
    offset ($4 - 1) * $3
  $sql$, p_table, json_filter_clause);

  return query execute v_sql
    using query_text, filter_condition_jsonb, normalized_page_size, normalized_page_current,
          data_source, normalized_this_user_id, team_id_filter, state_code_filter;
end;
$_$;


ALTER FUNCTION api._search_simple_dataset_latest(p_table regclass, query_text text, filter_condition jsonb, page_size bigint, page_current bigint, data_source text, this_user_id text, team_id_filter uuid, state_code_filter integer) OWNER TO postgres;

--
-- Name: assert_lca_release_manager(); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.assert_lca_release_manager() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    return private.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not private.lca_release_is_manager() then
    return private.lca_release_error(
      'not_data_product_manager',
      403,
      'Data product manager role is required'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'userId', v_actor,
      'role', 'data_product_manager'
    )
  );
end;
$$;


ALTER FUNCTION api.assert_lca_release_manager() OWNER TO postgres;

--
-- Name: cmd_dataset_alias_execution_admit_guarded(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_alias_execution_admit_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '10s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_schema_version constant text := 'dataset-alias-execution-admit.v1';
  v_request_id uuid;
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_token text;
  v_gate_results jsonb;
  v_gate jsonb;
  v_gate_receipt util.dataset_alias_execution_gate_receipts%rowtype;
  v_gate_name text;
  v_expectation_name text;
  v_captured_at timestamp with time zone;
  v_now timestamp with time zone;
  v_gate_results_sha256 text;
  v_admission_request_sha256 text;
  v_nonce text;
  v_nonce_sha256 text;
  v_service_key text;
  v_net_request_id bigint;
  v_dispatch_error jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request is not null and pg_column_size(p_request) > 65536 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ADMISSION_TOO_LARGE',
      'status', 413,
      'message', 'Protected admission request exceeds 64 KiB'
    );
  end if;

  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array[
      'schema_version',
      'request_id',
      'preflight_token',
      'preflight_proof_sha256',
      'gate_results'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_request) as request_key(key)
      where request_key.key <> all (array[
        'schema_version',
        'request_id',
        'preflight_token',
        'preflight_proof_sha256',
        'gate_results'
      ])
    )
    or p_request->>'schema_version' is distinct from v_schema_version
    or jsonb_typeof(p_request->'request_id') is distinct from 'string'
    or (p_request->>'request_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(p_request->'preflight_token') is distinct from 'string'
    or (p_request->>'preflight_token') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_request->'preflight_proof_sha256') is distinct from 'string'
    or (p_request->>'preflight_proof_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_request->'gate_results') is distinct from 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ADMISSION_INVALID_REQUEST',
      'status', 400,
      'message', 'Admission request must match dataset-alias-execution-admit.v1 exactly'
    );
  end if;

  v_request_id := (p_request->>'request_id')::uuid;
  v_token := p_request->>'preflight_token';
  v_gate_results := p_request->'gate_results';

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text || ':' || v_request_id::text, 0)
  );

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = v_request_id
    and preflight.actor_user_id = v_actor
  for update;

  if v_preflight.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_NOT_FOUND',
      'status', 404,
      'message', 'No actor-owned protected preflight exists for this request ID'
    );
  end if;

  v_now := pg_catalog.clock_timestamp();

  if v_preflight.consumed_at is not null
    or exists (
      select 1
      from util.dataset_alias_execution_requests as request
      where request.id = v_request_id
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ATTEMPT_ALREADY_CONSUMED',
      'status', 409,
      'message', 'The protected attempt was already consumed; use status/readback only'
    );
  end if;

  if v_now > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_EXPIRED',
      'status', 409,
      'message', 'The 180-second server preflight window expired before admission'
    );
  end if;

  if util.dataset_alias_execution_sha256(v_token)
      is distinct from v_preflight.token_sha256
    or p_request->>'preflight_proof_sha256'
      is distinct from v_preflight.preflight_proof_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_PROOF_MISMATCH',
      'status', 409,
      'message', 'Preflight token or proof does not match the durable server record'
    );
  end if;

  if not (v_gate_results ?& array[
      'primary_support_plan',
      'execution_unused',
      'derivative_quiescence'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_gate_results) as gate_key(key)
      where gate_key.key <> all (array[
        'primary_support_plan',
        'execution_unused',
        'derivative_quiescence'
      ])
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_SET_MISMATCH',
      'status', 400,
      'message', 'Exactly three protected gate results are required'
    );
  end if;

  for v_gate_name, v_expectation_name in
    select *
    from (values
      ('primary_support_plan'::text, 'primary_support_plan_sha256'::text),
      ('execution_unused'::text, 'execution_unused_sha256'::text),
      ('derivative_quiescence'::text, 'derivative_quiescence_sha256'::text)
    ) as gate_map(gate_name, expectation_name)
  loop
    v_gate := v_gate_results->v_gate_name;
    v_gate_receipt := null;

    select receipt.*
    into v_gate_receipt
    from util.dataset_alias_execution_gate_receipts as receipt
    where receipt.preflight_id = v_request_id
      and receipt.actor_user_id = v_actor
      and receipt.gate_name = v_gate_name;

    if jsonb_typeof(v_gate) is distinct from 'object'
      or not (v_gate ?& array[
        'expected_sha256',
        'observed_sha256',
        'status',
        'captured_at'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_gate) as gate_field(key)
        where gate_field.key <> all (array[
          'expected_sha256',
          'observed_sha256',
          'status',
          'captured_at'
        ])
      )
      or v_gate_receipt.preflight_id is null
      or v_gate->>'expected_sha256'
        is distinct from v_gate_receipt.expected_sha256
      or v_gate->>'observed_sha256'
        is distinct from v_gate_receipt.observed_sha256
      or v_gate->>'status' is distinct from v_gate_receipt.status
      or v_gate_receipt.expected_sha256
        is distinct from v_preflight.gate_expectations->>v_expectation_name
      or jsonb_typeof(v_gate->'captured_at') is distinct from 'string' then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_GATE_FAILED',
        'status', 409,
        'message', 'A protected gate is missing, failed, or bound to the wrong digest',
        'gate', v_gate_name
      );
    end if;

    begin
      v_captured_at := (v_gate->>'captured_at')::timestamp with time zone;
    exception
      when others then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_EXECUTION_GATE_TIMESTAMP_INVALID',
          'status', 400,
          'message', 'A protected gate timestamp is invalid',
          'gate', v_gate_name
        );
    end;

    if v_captured_at is distinct from v_gate_receipt.captured_at
      or v_captured_at < v_preflight.completed_at
      or v_captured_at > v_now + interval '5 seconds'
      or v_captured_at > v_preflight.expires_at then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_GATE_OUTSIDE_WINDOW',
        'status', 409,
        'message', 'All gate evidence must be captured inside the server preflight window',
        'gate', v_gate_name
      );
    end if;
  end loop;

  if pg_catalog.clock_timestamp() > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_EXPIRED',
      'status', 409,
      'message', 'The 180-second server preflight window expired during admission validation'
    );
  end if;

  v_gate_results_sha256 :=
    util.dataset_alias_execution_sha256(v_gate_results::text);
  v_admission_request_sha256 :=
    util.dataset_alias_execution_sha256(p_request::text);
  v_nonce := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  v_nonce_sha256 := util.dataset_alias_execution_sha256(v_nonce);

  insert into util.dataset_alias_execution_requests (
    id,
    actor_user_id,
    plan_sha256,
    operation_id,
    plan_request_sha256,
    freeze_sha256,
    approval_identity_sha256,
    approval_text_sha256,
    derivative_target_set_sha256,
    preflight_proof_sha256,
    admission_request_sha256,
    gate_results,
    gate_results_sha256,
    nonce_sha256,
    attempt_count,
    dispatch_count,
    status,
    admitted_at
  ) values (
    v_request_id,
    v_actor,
    v_preflight.plan_sha256,
    v_preflight.operation_id,
    v_preflight.plan_request_sha256,
    v_preflight.bindings->>'freeze_sha256',
    v_preflight.bindings->>'approval_identity_sha256',
    v_preflight.bindings->>'approval_text_sha256',
    v_preflight.bindings->>'derivative_target_set_sha256',
    v_preflight.preflight_proof_sha256,
    v_admission_request_sha256,
    v_gate_results,
    v_gate_results_sha256,
    v_nonce_sha256,
    1,
    0,
    'dispatching',
    v_now
  );

  update util.dataset_alias_execution_preflights
  set consumed_at = v_now
  where id = v_request_id;

  begin
    v_service_key := util.project_secret_key();
    v_net_request_id := net.http_post(
      url => util.project_url()
        || '/rest/v1/rpc/cmd_dataset_alias_execution_execute',
      headers => jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_key,
        'apikey', v_service_key
      ),
      body => jsonb_build_object(
        'p_request_id', v_request_id,
        'p_nonce', v_nonce
      ),
      timeout_milliseconds => 70000
    );

    if v_net_request_id is null then
      raise exception using
        errcode = 'P0001',
        message = 'pg_net returned no request ID';
    end if;

    update util.dataset_alias_execution_requests
    set
      dispatch_count = 1,
      net_request_id = v_net_request_id,
      status = 'dispatched',
      dispatched_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
    where id = v_request_id;
  exception
    when others then
      v_dispatch_error := jsonb_build_object(
        'phase', 'dispatch',
        'code', 'ALIAS_EXECUTION_DISPATCH_FAILED',
        'sqlstate', sqlstate,
        'message', sqlerrm
      );

      update util.dataset_alias_execution_requests
      set
        status = 'failed',
        terminal_at = pg_catalog.clock_timestamp(),
        last_error = v_dispatch_error,
        updated_at = pg_catalog.clock_timestamp()
      where id = v_request_id;
  end;

  if v_dispatch_error is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_DISPATCH_FAILED',
      'status', 'failed',
      'request_id', v_request_id,
      'attempt_count', 1,
      'dispatch_count', 0,
      'attempt_consumed', true,
      'retry_allowed', false,
      'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
      'admission_request_sha256', v_admission_request_sha256,
      'gate_results_sha256', v_gate_results_sha256
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_admit_guarded',
    'schema_version', v_schema_version,
    'request_id', v_request_id,
    'plan_sha256', v_preflight.plan_sha256,
    'operation_id', v_preflight.operation_id,
    'plan_request_sha256', v_preflight.plan_request_sha256,
    'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
    'admission_request_sha256', v_admission_request_sha256,
    'gate_results_sha256', v_gate_results_sha256,
    'attempt_count', 1,
    'dispatch_count', 1,
    'net_request_id', v_net_request_id::text,
    'status', 'dispatched',
    'attempt_consumed', true,
    'retry_allowed', false
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ADMISSION_LOCK_BUSY',
      'status', 409,
      'message', 'Protected admission could not acquire its bounded lock'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ATTEMPT_ALREADY_CONSUMED',
      'status', 409,
      'message', 'The request or sealed approval identity already consumed its only attempt'
    );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_alias_execution_admit_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_admit_guarded(p_request jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_alias_execution_admit_guarded(p_request jsonb) IS 'Consumes one actor-owned unexpired preflight token, binds three passed gate digests, persists attempt_count=1, and enqueues at most one service executor request. Repeated admission is rejected and status/readback never redispatches.';


--
-- Name: cmd_dataset_alias_execution_gate_guarded(uuid, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '55s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_expected_name text;
  v_expected_sha256 text;
  v_material jsonb;
  v_observed_sha256 text;
  v_receipt_material jsonb;
  v_receipt_sha256 text;
  v_captured_at timestamp with time zone;
  v_alias_result jsonb;
  v_batch_result jsonb;
  v_simulation_passed boolean := false;
  v_execution_count integer := 0;
  v_alias_audit_count integer := 0;
  v_derivative_child_count integer := 0;
  v_snapshot_drift_count integer := 0;
  v_active_rebuild_count integer := 0;
  v_http_count integer := 0;
  v_extraction_count integer := 0;
  v_embedding_count integer := 0;
  v_pending_count integer := 0;
  v_failure_material jsonb;
  v_failure_sha256 text;
  v_target jsonb;
  v_snapshot jsonb;
  v_existing_gate_count integer := 0;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request_id is null
    or p_preflight_token is null
    or p_preflight_token !~ '^[a-f0-9]{64}$'
    or p_gate_name not in (
      'primary_support_plan',
      'execution_unused',
      'derivative_quiescence'
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_INVALID_REQUEST',
      'status', 400,
      'message', 'Exact request ID, preflight token, and known gate name are required'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_actor::text || ':' || p_request_id::text || ':' || p_gate_name,
      0
    )
  );

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = p_request_id
    and preflight.actor_user_id = v_actor
  for update;

  if v_preflight.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_NOT_FOUND',
      'status', 404,
      'message', 'No actor-owned protected preflight exists for this request ID'
    );
  end if;

  if v_preflight.consumed_at is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ATTEMPT_ALREADY_CONSUMED',
      'status', 409,
      'message', 'Admission already consumed this preflight; gates are read-only history now'
    );
  end if;

  if pg_catalog.clock_timestamp() > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_EXPIRED',
      'status', 409,
      'message', 'The 180-second server preflight window expired before all gates completed'
    );
  end if;

  if util.dataset_alias_execution_sha256(p_preflight_token)
      is distinct from v_preflight.token_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TOKEN_MISMATCH',
      'status', 403,
      'message', 'Preflight token does not match the durable server record'
    );
  end if;

  if exists (
    select 1
    from util.dataset_alias_execution_gate_receipts as receipt
    where receipt.preflight_id = p_request_id
      and receipt.gate_name = p_gate_name
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_ALREADY_CAPTURED',
      'status', 409,
      'message', 'Each live gate is captured at most once; freeze again after a lost gate response'
    );
  end if;

  select count(*)::integer
  into v_existing_gate_count
  from util.dataset_alias_execution_gate_receipts as receipt
  where receipt.preflight_id = p_request_id
    and receipt.actor_user_id = v_actor;

  if (
      p_gate_name = 'primary_support_plan'
      and v_existing_gate_count <> 0
    ) or (
      p_gate_name = 'execution_unused'
      and (
        v_existing_gate_count <> 1
        or not exists (
          select 1
          from util.dataset_alias_execution_gate_receipts as receipt
          where receipt.preflight_id = p_request_id
            and receipt.actor_user_id = v_actor
            and receipt.gate_name = 'primary_support_plan'
        )
      )
    ) or (
      p_gate_name = 'derivative_quiescence'
      and (
        v_existing_gate_count <> 2
        or not exists (
          select 1
          from util.dataset_alias_execution_gate_receipts as receipt
          where receipt.preflight_id = p_request_id
            and receipt.actor_user_id = v_actor
            and receipt.gate_name = 'primary_support_plan'
        )
        or not exists (
          select 1
          from util.dataset_alias_execution_gate_receipts as receipt
          where receipt.preflight_id = p_request_id
            and receipt.actor_user_id = v_actor
            and receipt.gate_name = 'execution_unused'
        )
      )
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_ORDER_MISMATCH',
      'status', 409,
      'message', 'Live gates must be captured exactly once in primary/support, execution-unused, derivative-quiescence order'
    );
  end if;

  v_expected_name := case p_gate_name
    when 'primary_support_plan' then 'primary_support_plan_sha256'
    when 'execution_unused' then 'execution_unused_sha256'
    when 'derivative_quiescence' then 'derivative_quiescence_sha256'
  end;
  v_expected_sha256 := v_preflight.gate_expectations->>v_expected_name;

  if p_gate_name = 'primary_support_plan' then
    begin
      v_alias_result := private.cmd_dataset_alias_plan_guarded(v_preflight.plan);
      if coalesce((v_alias_result->>'ok')::boolean, false) is not true
        or coalesce((v_alias_result->>'idempotent_replay')::boolean, true)
        or v_alias_result->>'row_count' is distinct from '52'
        or v_alias_result->>'exchange_count' is distinct from '59' then
        raise exception using
          errcode = 'P0001',
          message = 'Primary/support simulation rejected';
      end if;

      v_batch_result := util.admit_dataset_derivative_rebuild_batch(
        v_actor,
        p_request_id,
        v_preflight.plan_sha256,
        v_preflight.operation_id,
        'PROTECTED_ALIAS_DERIVATIVE_CLOSURE',
        v_preflight.derivative_targets
      );

      if coalesce((v_batch_result->>'ok')::boolean, false) is not true
        or v_batch_result->>'target_count' is distinct from '50'
        or coalesce(v_batch_result->>'flow_count', v_batch_result->>'flows')
          is distinct from '23'
        or coalesce(v_batch_result->>'process_count', v_batch_result->>'processes')
          is distinct from '27' then
        raise exception using
          errcode = 'P0001',
          message = 'Derivative batch simulation rejected';
      end if;

      raise exception using
        errcode = 'P0002',
        message = 'Protected primary/support gate rollback';
    exception
      when sqlstate 'P0002' then
        v_simulation_passed := true;
      when others then
        v_simulation_passed := false;
    end;

    if not v_simulation_passed then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_PRIMARY_SUPPORT_GATE_FAILED',
        'status', 409,
        'message', 'Primary/support plan drifted after preflight'
      );
    end if;

    v_material := jsonb_build_object(
      'schema_version', 'dataset-alias-execution-gate-material.v1',
      'gate', p_gate_name,
      'request_id', p_request_id,
      'actor_user_id', v_actor,
      'plan_request_sha256', v_preflight.plan_request_sha256,
      'derivative_targets_sha256', v_preflight.derivative_targets_sha256,
      'plan_rows', 52,
      'plan_exchanges', 59,
      'alias_audits', 55,
      'derivative_targets', 50,
      'rollback_simulation_passed', true
    );
  elsif p_gate_name = 'execution_unused' then
    select count(*)::integer
    into v_execution_count
    from util.dataset_alias_execution_requests as request
    where request.actor_user_id = v_actor
      and request.approval_identity_sha256 =
        v_preflight.bindings->>'approval_identity_sha256';

    select count(*)::integer
    into v_alias_audit_count
    from private.command_audit_log as audit
    where audit.actor_user_id = v_actor
      and (
        (
          audit.command = 'cmd_dataset_alias_batch_guarded'
          and audit.payload->>'plan_sha256' = v_preflight.plan_sha256
          and audit.payload->>'operation_id' = v_preflight.operation_id
        )
        or (
          audit.command = 'cmd_dataset_alias_plan_guarded'
          and audit.payload->>'plan_request_sha256' =
            v_preflight.plan_request_sha256
        )
      );

    select count(*)::integer
    into v_derivative_child_count
    from util.dataset_derivative_rebuild_requests as request
    where request.actor_user_id = v_actor
      and request.batch_id = p_request_id;

    if v_execution_count <> 0
      or v_alias_audit_count <> 0
      or v_derivative_child_count <> 0 then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_UNUSED_GATE_FAILED',
        'status', 409,
        'message', 'The sealed execution identity already has durable effects'
      );
    end if;

    v_material := jsonb_build_object(
      'schema_version', 'dataset-alias-execution-gate-material.v1',
      'gate', p_gate_name,
      'request_id', p_request_id,
      'actor_user_id', v_actor,
      'plan_request_sha256', v_preflight.plan_request_sha256,
      'sealed_execution_rows', v_execution_count,
      'alias_audit_rows', v_alias_audit_count,
      'derivative_child_rows', v_derivative_child_count
    );
  else
    for v_target in
      select target_item.value
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
    loop
      begin
        v_snapshot := util.dataset_derivative_rebuild_snapshot(
          v_target->>'table',
          (v_target->>'id')::uuid,
          v_target->>'version'
        );
      exception
        when others then
          v_snapshot := null;
      end;

      if v_snapshot is null
        or v_snapshot->>'user_id' is distinct from v_actor::text
        or v_snapshot->>'state_code' is distinct from '0'
        or v_snapshot->>'snapshot_sha256'
          is distinct from v_target->>'baseline_snapshot_sha256' then
        v_snapshot_drift_count := v_snapshot_drift_count + 1;
      end if;
    end loop;

    select count(*)::integer
    into v_active_rebuild_count
    from util.dataset_derivative_rebuild_requests as request
    where request.status not in ('completed', 'stale', 'failed')
      and exists (
        select 1
        from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
        where request.target_table = target_item.value->>'table'
          and request.target_id = (target_item.value->>'id')::uuid
          and request.target_version = target_item.value->>'version'
      );

    select count(*)::integer
    into v_http_count
    from net.http_request_queue as request
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where util.dataset_derivative_rebuild_http_body_matches(
        request.body,
        target_item.value->>'table',
        (target_item.value->>'id')::uuid,
        target_item.value->>'version'
      )
    );

    select count(*)::integer
    into v_extraction_count
    from pgmq.q_dataset_extraction_jobs as job
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where job.message->>'schema' = 'public'
        and job.message->>'table' = target_item.value->>'table'
        and job.message->>'id' = target_item.value->>'id'
        and btrim(job.message->>'version') = target_item.value->>'version'
    );

    select count(*)::integer
    into v_embedding_count
    from pgmq.q_embedding_jobs as job
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where job.message->>'schema' = 'public'
        and job.message->>'table' = target_item.value->>'table'
        and job.message->>'id' = target_item.value->>'id'
        and btrim(job.message->>'version') = target_item.value->>'version'
        and job.message->>'embeddingColumn' = 'embedding_ft'
    );

    select count(*)::integer
    into v_pending_count
    from util.pending_embedding_jobs as pending
    where pending.schema_name = 'public'
      and pending.embedding_column = 'embedding_ft'
      and pending.status = 'pending'
      and exists (
        select 1
        from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
        where pending.table_name = target_item.value->>'table'
          and pending.record_id = target_item.value->>'id'
          and btrim(pending.record_version) = target_item.value->>'version'
      );

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', failure.id,
          'queue_name', failure.queue_name,
          'msg_id', failure.msg_id,
          'read_count', failure.read_count,
          'reason', failure.reason,
          'message', failure.message,
          'failed_at', failure.failed_at
        ) order by failure.id
      ),
      '[]'::jsonb
    )
    into v_failure_material
    from util.embedding_job_failures as failure
    where exists (
      select 1
      from jsonb_array_elements(v_preflight.derivative_targets) as target_item(value)
      where failure.message->>'table' = target_item.value->>'table'
        and failure.message->>'id' = target_item.value->>'id'
        and btrim(failure.message->>'version') = target_item.value->>'version'
    );
    v_failure_sha256 :=
      util.dataset_alias_execution_sha256(v_failure_material::text);

    if v_snapshot_drift_count <> 0
      or v_active_rebuild_count <> 0
      or v_http_count <> 0
      or v_extraction_count <> 0
      or v_embedding_count <> 0
      or v_pending_count <> 0
      or v_failure_sha256 is distinct from v_preflight.failure_baseline_sha256 then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_DERIVATIVE_QUIESCENCE_GATE_FAILED',
        'status', 409,
        'message', 'Derivative baselines, queues, fences, or failure ledger drifted after preflight'
      );
    end if;

    v_material := jsonb_build_object(
      'schema_version', 'dataset-alias-execution-gate-material.v1',
      'gate', p_gate_name,
      'request_id', p_request_id,
      'actor_user_id', v_actor,
      'derivative_targets_sha256', v_preflight.derivative_targets_sha256,
      'snapshot_drift_count', v_snapshot_drift_count,
      'active_rebuild_count', v_active_rebuild_count,
      'http_request_count', v_http_count,
      'extraction_job_count', v_extraction_count,
      'embedding_job_count', v_embedding_count,
      'pending_embedding_count', v_pending_count,
      'failure_baseline_sha256', v_failure_sha256
    );
  end if;

  v_captured_at := pg_catalog.clock_timestamp();
  if v_captured_at > v_preflight.expires_at then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_WINDOW_EXPIRED',
      'status', 409,
      'message', 'The live gate completed after the 180-second server window'
    );
  end if;

  v_observed_sha256 := util.dataset_alias_execution_sha256(v_material::text);
  if v_observed_sha256 is distinct from v_expected_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_EVIDENCE_MISMATCH',
      'status', 409,
      'message', 'The live gate evidence does not match the server-owned preflight expectation'
    );
  end if;

  v_receipt_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-receipt.v1',
    'request_id', p_request_id,
    'actor_user_id', v_actor,
    'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
    'gate', p_gate_name,
    'expected_sha256', v_expected_sha256,
    'observed_sha256', v_observed_sha256,
    'status', 'passed',
    'captured_at', v_captured_at
  );
  v_receipt_sha256 :=
    util.dataset_alias_execution_sha256(v_receipt_material::text);

  insert into util.dataset_alias_execution_gate_receipts (
    preflight_id,
    actor_user_id,
    gate_name,
    expected_sha256,
    observed_sha256,
    material,
    status,
    captured_at,
    receipt_sha256
  ) values (
    p_request_id,
    v_actor,
    p_gate_name,
    v_expected_sha256,
    v_observed_sha256,
    v_material,
    'passed',
    v_captured_at,
    v_receipt_sha256
  );

  return v_receipt_material || jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_gate_guarded',
    'receipt_sha256', v_receipt_sha256
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_LOCK_BUSY',
      'status', 409,
      'message', 'Protected live gate could not acquire its bounded locks'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_GATE_ALREADY_CAPTURED',
      'status', 409,
      'message', 'A concurrent call already captured this live gate'
    );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_alias_execution_gate_guarded(p_request_id uuid, p_preflight_token text, p_gate_name text) IS 'Captures one of exactly three actor-owned post-preflight live gates. Primary/support is rollback-simulated again; unused execution and derivative quiescence are read directly. Each passed receipt is persisted once inside the same 180-second server window.';


--
-- Name: cmd_dataset_alias_execution_preflight_guarded(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_alias_execution_preflight_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '60s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_actor_email text := auth.email();
  v_schema_version constant text := 'dataset-alias-execution-preflight.v1';
  v_request_id uuid;
  v_environment text;
  v_project_ref text;
  v_server_context jsonb;
  v_request_actor jsonb;
  v_plan jsonb;
  v_freeze jsonb;
  v_approval jsonb;
  v_expected_freeze jsonb;
  v_expected_approval jsonb;
  v_bindings jsonb;
  v_expected jsonb;
  v_input_targets jsonb;
  v_targets jsonb;
  v_sorted_targets jsonb;
  v_gate_expectations jsonb;
  v_primary_gate_material jsonb;
  v_unused_gate_material jsonb;
  v_quiescence_gate_material jsonb;
  v_plan_sha256 text;
  v_operation_id text;
  v_plan_request_sha256 text;
  v_alias_plan_request_sha256 text;
  v_derivative_target_set_sha256 text;
  v_derivative_baseline_set_sha256 text;
  v_bindings_sha256 text;
  v_expected_sha256 text;
  v_targets_sha256 text;
  v_gate_expectations_sha256 text;
  v_failure_baseline_material jsonb;
  v_failure_baseline_sha256 text;
  v_request_sha256 text;
  v_token text;
  v_token_sha256 text;
  v_proof_material jsonb;
  v_proof_sha256 text;
  v_completed_at timestamp with time zone;
  v_expires_at timestamp with time zone;
  v_target jsonb;
  v_snapshot jsonb;
  v_alias_result jsonb;
  v_batch_result jsonb;
  v_simulation_passed boolean := false;
  v_simulation_error jsonb;
  v_existing_id uuid;
  v_execution_count integer := 0;
  v_alias_audit_count integer := 0;
  v_derivative_child_count integer := 0;
  v_snapshot_drift_count integer := 0;
  v_active_rebuild_count integer := 0;
  v_http_count integer := 0;
  v_extraction_count integer := 0;
  v_embedding_count integer := 0;
  v_pending_count integer := 0;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if nullif(v_actor_email, '') is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_EMAIL_REQUIRED',
      'status', 401,
      'message', 'Authenticated email claim is required'
    );
  end if;

  if p_request is not null and pg_column_size(p_request) > 67108864 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TOO_LARGE',
      'status', 413,
      'message', 'Protected preflight request exceeds 64 MiB'
    );
  end if;

  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array[
      'schema_version',
      'request_id',
      'environment',
      'project_ref',
      'actor',
      'target_visibility',
      'plan',
      'freeze',
      'approval',
      'bindings',
      'expected',
      'derivative_targets'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_request) as request_key(key)
      where request_key.key <> all (array[
        'schema_version',
        'request_id',
        'environment',
        'project_ref',
        'actor',
        'target_visibility',
        'plan',
        'freeze',
        'approval',
        'bindings',
        'expected',
        'derivative_targets'
      ])
    )
    or p_request->>'schema_version' is distinct from v_schema_version
    or jsonb_typeof(p_request->'request_id') is distinct from 'string'
    or (p_request->>'request_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_request->>'environment' not in ('production', 'preview', 'local')
    or jsonb_typeof(p_request->'project_ref') is distinct from 'string'
    or nullif(btrim(p_request->>'project_ref'), '') is null
    or octet_length(p_request->>'project_ref') > 128
    or p_request->>'target_visibility' is distinct from 'owner_draft'
    or jsonb_typeof(p_request->'actor') is distinct from 'object'
    or jsonb_typeof(p_request->'plan') is distinct from 'object'
    or jsonb_typeof(p_request->'freeze') is distinct from 'object'
    or jsonb_typeof(p_request->'approval') is distinct from 'object'
    or jsonb_typeof(p_request->'bindings') is distinct from 'object'
    or jsonb_typeof(p_request->'expected') is distinct from 'object'
    or jsonb_typeof(p_request->'derivative_targets') is distinct from 'array' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_REQUEST',
      'status', 400,
      'message', 'Preflight request must match dataset-alias-execution-preflight.v1 exactly'
    );
  end if;

  v_request_id := (p_request->>'request_id')::uuid;
  v_environment := p_request->>'environment';
  v_project_ref := btrim(p_request->>'project_ref');
  v_request_actor := p_request->'actor';
  v_plan := p_request->'plan';
  v_freeze := p_request->'freeze';
  v_approval := p_request->'approval';
  v_bindings := p_request->'bindings';
  v_expected := p_request->'expected';
  v_input_targets := p_request->'derivative_targets';

  begin
    v_server_context := util.dataset_alias_execution_server_context();
  exception
    when others then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_SERVER_CONTEXT_UNAVAILABLE',
        'status', 409,
        'message', 'Branch-local project identity could not be derived from trusted server configuration'
      );
  end;

  if v_environment is distinct from v_server_context->>'environment'
    or v_project_ref is distinct from v_server_context->>'project_ref' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_SERVER_CONTEXT_MISMATCH',
      'status', 409,
      'message', 'Requested environment and project_ref do not match the connected database'
    );
  end if;

  if not (v_request_actor ?& array['user_id', 'email'])
    or exists (
      select 1
      from jsonb_object_keys(v_request_actor) as actor_key(key)
      where actor_key.key <> all (array['user_id', 'email'])
    )
    or jsonb_typeof(v_request_actor->'user_id') is distinct from 'string'
    or v_request_actor->>'user_id' is distinct from v_actor::text
    or jsonb_typeof(v_request_actor->'email') is distinct from 'string'
    or lower(btrim(v_request_actor->>'email'))
      is distinct from lower(btrim(v_actor_email))
    or octet_length(v_request_actor->>'email') > 320 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_ACTOR_MISMATCH',
      'status', 403,
      'message', 'Preflight actor must match the authenticated user and email'
    );
  end if;

  if not (v_bindings ?& array[
      'plan_file_sha256',
      'freeze_file_sha256',
      'freeze_sha256',
      'approval_file_sha256',
      'approval_identity_sha256',
      'approval_text_sha256',
      'alias_plan_request_sha256',
      'before_hash_set_sha256',
      'desired_hash_set_sha256',
      'exchange_rewrite_set_sha256',
      'support_snapshot_set_sha256',
      'derivative_baseline_set_sha256',
      'derivative_target_set_sha256',
      'toolchain_evidence_sha256'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_bindings) as binding_key(key)
      where binding_key.key <> all (array[
        'plan_file_sha256',
        'freeze_file_sha256',
        'freeze_sha256',
        'approval_file_sha256',
        'approval_identity_sha256',
        'approval_text_sha256',
        'alias_plan_request_sha256',
        'before_hash_set_sha256',
        'desired_hash_set_sha256',
        'exchange_rewrite_set_sha256',
        'support_snapshot_set_sha256',
        'derivative_baseline_set_sha256',
        'derivative_target_set_sha256',
        'toolchain_evidence_sha256'
      ])
    )
    or exists (
      select 1
      from jsonb_each(v_bindings) as binding_item(key, value)
      where jsonb_typeof(binding_item.value) is distinct from 'string'
        or (binding_item.value #>> '{}') !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_BINDINGS',
      'status', 400,
      'message', 'All protected artifact bindings must be exact SHA-256 values'
    );
  end if;

  if not (v_expected ?& array[
      'action_count',
      'batch_count',
      'exchange_count',
      'amount_field_count',
      'unrelated_exchange_count',
      'audit_count',
      'flowproperty_count',
      'flow_count',
      'process_count',
      'derivative_target_count'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_expected) as expected_key(key)
      where expected_key.key <> all (array[
        'action_count',
        'batch_count',
        'exchange_count',
        'amount_field_count',
        'unrelated_exchange_count',
        'audit_count',
        'flowproperty_count',
        'flow_count',
        'process_count',
        'derivative_target_count'
      ])
    )
    or v_expected is distinct from jsonb_build_object(
      'action_count', 52,
      'batch_count', 2,
      'exchange_count', 59,
      'amount_field_count', 118,
      'unrelated_exchange_count', 309,
      'audit_count', 55,
      'flowproperty_count', 2,
      'flow_count', 23,
      'process_count', 27,
      'derivative_target_count', 50
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_COUNTS',
      'status', 400,
      'message', 'Protected profile requires exact 52/59/118/309/55 and 2/23/27/50 counts'
    );
  end if;

  if jsonb_array_length(v_input_targets) <> 50
    or exists (
      select 1
      from jsonb_array_elements(v_input_targets) as target_item(value)
      where jsonb_typeof(target_item.value) is distinct from 'object'
        or not (target_item.value ?& array[
          'table',
          'id',
          'version',
          'user_id',
          'state_code',
          'baseline_snapshot_sha256'
        ])
        or exists (
          select 1
          from jsonb_object_keys(target_item.value) as target_key(key)
          where target_key.key <> all (array[
            'table',
            'id',
            'version',
            'user_id',
            'state_code',
            'baseline_snapshot_sha256'
          ])
        )
        or target_item.value->>'table' not in ('flows', 'processes')
        or jsonb_typeof(target_item.value->'table') is distinct from 'string'
        or jsonb_typeof(target_item.value->'id') is distinct from 'string'
        or (target_item.value->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(target_item.value->'version') is distinct from 'string'
        or (target_item.value->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        or jsonb_typeof(target_item.value->'user_id') is distinct from 'string'
        or target_item.value->>'user_id' is distinct from v_actor::text
        or jsonb_typeof(target_item.value->'state_code') is distinct from 'number'
        or target_item.value->>'state_code' is distinct from '0'
        or jsonb_typeof(target_item.value->'baseline_snapshot_sha256')
          is distinct from 'string'
        or (target_item.value->>'baseline_snapshot_sha256') !~ '^[a-f0-9]{64}$'
    )
    or (
      select count(*)
      from jsonb_array_elements(v_input_targets) as target_item(value)
      where target_item.value->>'table' = 'flows'
    ) <> 23
    or (
      select count(*)
      from jsonb_array_elements(v_input_targets) as target_item(value)
      where target_item.value->>'table' = 'processes'
    ) <> 27
    or (
      select count(distinct (
        target_item.value->>'table',
        target_item.value->>'id',
        target_item.value->>'version'
      ))
      from jsonb_array_elements(v_input_targets) as target_item(value)
    ) <> 50 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_TARGETS',
      'status', 400,
      'message', 'Derivative targets must be 23 unique flows and 27 unique processes owned by the actor at state_code 0'
    );
  end if;

  select jsonb_agg(target_item.value order by
    target_item.value->>'table',
    target_item.value->>'id',
    target_item.value->>'version'
  )
  into v_sorted_targets
  from jsonb_array_elements(v_input_targets) as target_item(value);

  if v_input_targets is distinct from v_sorted_targets then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TARGET_ORDER',
      'status', 400,
      'message', 'Derivative targets must use stable table/id/version order'
    );
  end if;

  if v_plan->>'schema_version' is distinct from 'dataset-alias-plan.v1'
    or v_plan->>'target_visibility' is distinct from 'owner_draft'
    or (v_plan->>'plan_sha256') !~ '^[a-f0-9]{64}$'
    or nullif(btrim(v_plan->>'operation_id'), '') is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_INVALID_PLAN',
      'status', 400,
      'message', 'Protected preflight requires one owner-draft dataset-alias-plan.v1 request'
    );
  end if;

  v_plan_sha256 := v_plan->>'plan_sha256';
  v_operation_id := btrim(v_plan->>'operation_id');

  select jsonb_agg(
    jsonb_build_object(
      'table', target_item.value->>'table',
      'id', target_item.value->>'id',
      'version', target_item.value->>'version',
      'expected_json_ordered_sha256',
        util.dataset_alias_execution_sha256(
          (action_item.value->'desired_json_ordered')::text
        ),
      'baseline_snapshot_sha256',
        target_item.value->>'baseline_snapshot_sha256'
    ) order by
      target_item.value->>'table',
      target_item.value->>'id',
      target_item.value->>'version'
  )
  into v_targets
  from jsonb_array_elements(v_plan->'batches') as batch_item(value)
  cross join lateral jsonb_array_elements(
    batch_item.value->'actions'
  ) as action_item(value)
  join jsonb_array_elements(v_input_targets) as target_item(value)
    on target_item.value->>'table' = action_item.value->>'table'
   and target_item.value->>'id' = action_item.value->>'id'
   and target_item.value->>'version' = action_item.value->>'version'
  where action_item.value->>'table' in ('flows', 'processes');

  if jsonb_typeof(v_targets) is distinct from 'array'
    or jsonb_array_length(v_targets) <> 50 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_TARGET_PLAN_MISMATCH',
      'status', 409,
      'message', 'Derivative target identities must exactly match the 50 flow/process plan actions'
    );
  end if;

  v_alias_plan_request_sha256 :=
    util.dataset_alias_execution_artifact_sha256(v_plan);

  select util.dataset_alias_execution_artifact_sha256(
    jsonb_agg(
      jsonb_build_object(
        'table', target_item.value->>'table',
        'id', target_item.value->>'id',
        'version', target_item.value->>'version',
        'user_id', target_item.value->>'user_id',
        'state_code', 0
      ) order by
        target_item.value->>'table',
        target_item.value->>'id',
        target_item.value->>'version'
    )
  )
  into v_derivative_target_set_sha256
  from jsonb_array_elements(v_input_targets) as target_item(value);

  select util.dataset_alias_execution_artifact_sha256(
    jsonb_agg(
      jsonb_build_object(
        'table', target_item.value->>'table',
        'id', target_item.value->>'id',
        'version', target_item.value->>'version',
        'baseline_snapshot_sha256',
          target_item.value->>'baseline_snapshot_sha256'
      ) order by
        target_item.value->>'table',
        target_item.value->>'id',
        target_item.value->>'version'
    )
  )
  into v_derivative_baseline_set_sha256
  from jsonb_array_elements(v_input_targets) as target_item(value);

  if v_bindings->>'alias_plan_request_sha256'
      is distinct from v_alias_plan_request_sha256
    or v_bindings->>'derivative_target_set_sha256'
      is distinct from v_derivative_target_set_sha256
    or v_bindings->>'derivative_baseline_set_sha256'
      is distinct from v_derivative_baseline_set_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_ARTIFACT_SET_MISMATCH',
      'status', 409,
      'message', 'The approved alias request or derivative target sets do not match server recomputation'
    );
  end if;

  v_expected_freeze := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-freeze.v1',
    'environment', v_environment,
    'project_ref', v_project_ref,
    'account', v_request_actor,
    'target_visibility', 'owner_draft',
    'plan', jsonb_build_object(
      'plan_file_sha256', v_bindings->>'plan_file_sha256',
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id
    ),
    'sets', jsonb_build_object(
      'alias_plan_request_sha256',
        v_bindings->>'alias_plan_request_sha256',
      'before_hash_set_sha256',
        v_bindings->>'before_hash_set_sha256',
      'desired_hash_set_sha256',
        v_bindings->>'desired_hash_set_sha256',
      'exchange_rewrite_set_sha256',
        v_bindings->>'exchange_rewrite_set_sha256',
      'support_snapshot_set_sha256',
        v_bindings->>'support_snapshot_set_sha256',
      'derivative_baseline_set_sha256',
        v_bindings->>'derivative_baseline_set_sha256',
      'derivative_target_set_sha256',
        v_bindings->>'derivative_target_set_sha256',
      'toolchain_evidence_sha256',
        v_bindings->>'toolchain_evidence_sha256'
    ),
    'expected', v_expected,
    'derivative_targets', v_input_targets,
    'policy', jsonb_build_object(
      'state_code_changes', 0,
      'save_draft', 0,
      'deletes', 0,
      'rebuild_derivatives', 0,
      'unitgroup_actions', 0,
      'person_distance_actions', 0,
      'max_admit_posts', 1,
      'automatic_retry', false
    ),
    'freeze_sha256', v_bindings->>'freeze_sha256'
  );

  if v_freeze is distinct from v_expected_freeze
    or util.dataset_alias_execution_artifact_sha256(
      jsonb_set(v_freeze, '{freeze_sha256}', '""'::jsonb, false)
    ) is distinct from v_bindings->>'freeze_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_FREEZE_MISMATCH',
      'status', 409,
      'message', 'The production freeze envelope or canonical freeze hash is invalid'
    );
  end if;

  begin
    perform (v_approval->>'approved_at_utc')::timestamp with time zone;
  exception
    when others then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_PREFLIGHT_APPROVAL_MISMATCH',
        'status', 409,
        'message', 'The exact approval timestamp is invalid'
      );
  end;

  v_expected_approval := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-approval.v1',
    'approved_at_utc', v_approval->>'approved_at_utc',
    'environment', v_environment,
    'project_ref', v_project_ref,
    'account', v_request_actor,
    'target_visibility', 'owner_draft',
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'plan_file_sha256', v_bindings->>'plan_file_sha256',
    'freeze_file_sha256', v_bindings->>'freeze_file_sha256',
    'freeze_sha256', v_bindings->>'freeze_sha256',
    'approval_text_sha256', v_bindings->>'approval_text_sha256',
    'max_admit_posts', 1,
    'automatic_retry', false,
    'approval_identity_sha256', v_bindings->>'approval_identity_sha256'
  );

  if v_approval is distinct from v_expected_approval
    or util.dataset_alias_execution_artifact_sha256(
      jsonb_set(
        v_approval,
        '{approval_identity_sha256}',
        '""'::jsonb,
        false
      )
    ) is distinct from v_bindings->>'approval_identity_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_APPROVAL_MISMATCH',
      'status', 409,
      'message', 'The approval identity does not bind this exact production freeze and alias request'
    );
  end if;

  select preflight.id
  into v_existing_id
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = v_request_id
     or (
       preflight.actor_user_id = v_actor
       and preflight.approval_identity_sha256 =
         v_bindings->>'approval_identity_sha256'
     )
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_APPROVAL_ALREADY_USED',
      'status', 409,
      'message', 'This request ID or exact approval identity already created a protected preflight; freeze and approve again'
    );
  end if;

  for v_target in
    select target_item.value
    from jsonb_array_elements(v_targets) as target_item(value)
  loop
    begin
      v_snapshot := util.dataset_derivative_rebuild_snapshot(
        v_target->>'table',
        (v_target->>'id')::uuid,
        v_target->>'version'
      );
    exception
      when others then
        v_snapshot := null;
    end;

    if v_snapshot is null
      or v_snapshot->>'user_id' is distinct from v_actor::text
      or v_snapshot->>'state_code' is distinct from '0'
      or v_snapshot->>'json_sha256' is distinct from v_snapshot->>'json_ordered_sha256'
      or v_snapshot->>'snapshot_sha256'
        is distinct from v_target->>'baseline_snapshot_sha256' then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_EXECUTION_PREFLIGHT_BASELINE_DRIFT',
        'status', 409,
        'message', 'A derivative target no longer matches its owner-draft baseline snapshot'
      );
    end if;
  end loop;

  v_plan_request_sha256 := util.dataset_alias_execution_sha256(v_plan::text);
  v_bindings_sha256 := util.dataset_alias_execution_sha256(v_bindings::text);
  v_expected_sha256 := util.dataset_alias_execution_sha256(v_expected::text);
  v_targets_sha256 := util.dataset_alias_execution_sha256(v_targets::text);
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', failure.id,
        'queue_name', failure.queue_name,
        'msg_id', failure.msg_id,
        'read_count', failure.read_count,
        'reason', failure.reason,
        'message', failure.message,
        'failed_at', failure.failed_at
      ) order by failure.id
    ),
    '[]'::jsonb
  )
  into v_failure_baseline_material
  from util.embedding_job_failures as failure
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where failure.message->>'table' = target_item.value->>'table'
      and failure.message->>'id' = target_item.value->>'id'
      and btrim(failure.message->>'version') = target_item.value->>'version'
  );
  v_failure_baseline_sha256 :=
    util.dataset_alias_execution_sha256(v_failure_baseline_material::text);
  v_request_sha256 := util.dataset_alias_execution_sha256(p_request::text);

  -- The simulation creates all normal alias writes, audits, webhook work, and
  -- derivative fences inside this exception block.  The controlled P0002
  -- exception always rolls those effects back before a durable token exists.
  begin
    v_alias_result := private.cmd_dataset_alias_plan_guarded(v_plan);
    if coalesce((v_alias_result->>'ok')::boolean, false) is not true
      or coalesce((v_alias_result->>'idempotent_replay')::boolean, true)
      or v_alias_result->>'row_count' is distinct from '52'
      or v_alias_result->>'exchange_count' is distinct from '59' then
      v_simulation_error := jsonb_build_object(
        'phase', 'alias',
        'result', coalesce(v_alias_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected alias simulation rejected';
    end if;

    v_batch_result := util.admit_dataset_derivative_rebuild_batch(
      v_actor,
      v_request_id,
      v_plan_sha256,
      v_operation_id,
      'PROTECTED_ALIAS_DERIVATIVE_CLOSURE',
      v_targets
    );

    if coalesce((v_batch_result->>'ok')::boolean, false) is not true
      or v_batch_result->>'target_count' is distinct from '50'
      or v_batch_result->>'flow_count' is distinct from '23'
      or v_batch_result->>'process_count' is distinct from '27' then
      v_simulation_error := jsonb_build_object(
        'phase', 'derivative_batch',
        'result', coalesce(v_batch_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected derivative batch simulation rejected';
    end if;

    raise exception using
      errcode = 'P0002',
      message = 'Protected execution preflight simulation rollback';
  exception
    when sqlstate 'P0002' then
      v_simulation_passed := true;
    when others then
      v_simulation_passed := false;
      if v_simulation_error is null then
        v_simulation_error := jsonb_build_object(
          'phase', 'unexpected',
          'sqlstate', sqlstate,
          'message', sqlerrm
        );
      end if;
  end;

  if not v_simulation_passed then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_SIMULATION_FAILED',
      'status', 409,
      'message', 'The exact protected plan failed rollback-only server simulation',
      'evidence', v_simulation_error
    );
  end if;

  select count(*)::integer
  into v_execution_count
  from util.dataset_alias_execution_requests as request
  where request.actor_user_id = v_actor
    and request.approval_identity_sha256 =
      v_bindings->>'approval_identity_sha256';

  select count(*)::integer
  into v_alias_audit_count
  from private.command_audit_log as audit
  where audit.actor_user_id = v_actor
    and (
      (
        audit.command = 'cmd_dataset_alias_batch_guarded'
        and audit.payload->>'plan_sha256' = v_plan_sha256
        and audit.payload->>'operation_id' = v_operation_id
      )
      or (
        audit.command = 'cmd_dataset_alias_plan_guarded'
        and audit.payload->>'plan_request_sha256' = v_plan_request_sha256
      )
    );

  select count(*)::integer
  into v_derivative_child_count
  from util.dataset_derivative_rebuild_requests as request
  where request.actor_user_id = v_actor
    and request.batch_id = v_request_id;

  for v_target in
    select target_item.value
    from jsonb_array_elements(v_targets) as target_item(value)
  loop
    begin
      v_snapshot := util.dataset_derivative_rebuild_snapshot(
        v_target->>'table',
        (v_target->>'id')::uuid,
        v_target->>'version'
      );
    exception
      when others then
        v_snapshot := null;
    end;

    if v_snapshot is null
      or v_snapshot->>'user_id' is distinct from v_actor::text
      or v_snapshot->>'state_code' is distinct from '0'
      or v_snapshot->>'snapshot_sha256'
        is distinct from v_target->>'baseline_snapshot_sha256' then
      v_snapshot_drift_count := v_snapshot_drift_count + 1;
    end if;
  end loop;

  select count(*)::integer
  into v_active_rebuild_count
  from util.dataset_derivative_rebuild_requests as request
  where request.status not in ('completed', 'stale', 'failed')
    and exists (
      select 1
      from jsonb_array_elements(v_targets) as target_item(value)
      where request.target_table = target_item.value->>'table'
        and request.target_id = (target_item.value->>'id')::uuid
        and request.target_version = target_item.value->>'version'
    );

  select count(*)::integer
  into v_http_count
  from net.http_request_queue as request
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where util.dataset_derivative_rebuild_http_body_matches(
      request.body,
      target_item.value->>'table',
      (target_item.value->>'id')::uuid,
      target_item.value->>'version'
    )
  );

  select count(*)::integer
  into v_extraction_count
  from pgmq.q_dataset_extraction_jobs as job
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where job.message->>'schema' = 'public'
      and job.message->>'table' = target_item.value->>'table'
      and job.message->>'id' = target_item.value->>'id'
      and btrim(job.message->>'version') = target_item.value->>'version'
  );

  select count(*)::integer
  into v_embedding_count
  from pgmq.q_embedding_jobs as job
  where exists (
    select 1
    from jsonb_array_elements(v_targets) as target_item(value)
    where job.message->>'schema' = 'public'
      and job.message->>'table' = target_item.value->>'table'
      and job.message->>'id' = target_item.value->>'id'
      and btrim(job.message->>'version') = target_item.value->>'version'
      and job.message->>'embeddingColumn' = 'embedding_ft'
  );

  select count(*)::integer
  into v_pending_count
  from util.pending_embedding_jobs as pending
  where pending.schema_name = 'public'
    and pending.embedding_column = 'embedding_ft'
    and pending.status = 'pending'
    and exists (
      select 1
      from jsonb_array_elements(v_targets) as target_item(value)
      where pending.table_name = target_item.value->>'table'
        and pending.record_id = target_item.value->>'id'
        and btrim(pending.record_version) = target_item.value->>'version'
    );

  if v_execution_count <> 0
    or v_alias_audit_count <> 0
    or v_derivative_child_count <> 0
    or v_snapshot_drift_count <> 0
    or v_active_rebuild_count <> 0
    or v_http_count <> 0
    or v_extraction_count <> 0
    or v_embedding_count <> 0
    or v_pending_count <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_NOT_QUIESCENT',
      'status', 409,
      'message', 'The exact approval identity, targets, or derivative queues are not unused and quiescent'
    );
  end if;

  v_primary_gate_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-material.v1',
    'gate', 'primary_support_plan',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'plan_request_sha256', v_plan_request_sha256,
    'derivative_targets_sha256', v_targets_sha256,
    'plan_rows', 52,
    'plan_exchanges', 59,
    'alias_audits', 55,
    'derivative_targets', 50,
    'rollback_simulation_passed', true
  );
  v_unused_gate_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-material.v1',
    'gate', 'execution_unused',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'plan_request_sha256', v_plan_request_sha256,
    'sealed_execution_rows', v_execution_count,
    'alias_audit_rows', v_alias_audit_count,
    'derivative_child_rows', v_derivative_child_count
  );
  v_quiescence_gate_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-gate-material.v1',
    'gate', 'derivative_quiescence',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'derivative_targets_sha256', v_targets_sha256,
    'snapshot_drift_count', v_snapshot_drift_count,
    'active_rebuild_count', v_active_rebuild_count,
    'http_request_count', v_http_count,
    'extraction_job_count', v_extraction_count,
    'embedding_job_count', v_embedding_count,
    'pending_embedding_count', v_pending_count,
    'failure_baseline_sha256', v_failure_baseline_sha256
  );
  v_gate_expectations := jsonb_build_object(
    'primary_support_plan_sha256',
      util.dataset_alias_execution_sha256(v_primary_gate_material::text),
    'execution_unused_sha256',
      util.dataset_alias_execution_sha256(v_unused_gate_material::text),
    'derivative_quiescence_sha256',
      util.dataset_alias_execution_sha256(v_quiescence_gate_material::text)
  );
  v_gate_expectations_sha256 :=
    util.dataset_alias_execution_sha256(v_gate_expectations::text);

  select preflight.id
  into v_existing_id
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = v_request_id
     or (
       preflight.actor_user_id = v_actor
       and preflight.preflight_request_sha256 = v_request_sha256
     )
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_ALREADY_EXISTS',
      'status', 409,
      'message', 'A preflight request ID or exact request was already used; tokens are never replayed'
    );
  end if;

  v_completed_at := pg_catalog.clock_timestamp();
  v_expires_at := v_completed_at + interval '180 seconds';
  v_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  v_token_sha256 := util.dataset_alias_execution_sha256(v_token);
  v_proof_material := jsonb_build_object(
    'schema_version', 'dataset-alias-execution-preflight-proof.v1',
    'request_id', v_request_id,
    'actor_user_id', v_actor,
    'environment', v_environment,
    'project_ref', v_project_ref,
    'server_context_sha256',
      util.dataset_alias_execution_sha256(v_server_context::text),
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'alias_plan_request_sha256', v_alias_plan_request_sha256,
    'freeze_sha256', v_bindings->>'freeze_sha256',
    'approval_identity_sha256',
      v_bindings->>'approval_identity_sha256',
    'plan_request_sha256', v_plan_request_sha256,
    'bindings_sha256', v_bindings_sha256,
    'expected_sha256', v_expected_sha256,
    'derivative_targets_sha256', v_targets_sha256,
    'gate_expectations', v_gate_expectations,
    'gate_expectations_sha256', v_gate_expectations_sha256,
    'failure_baseline_sha256', v_failure_baseline_sha256,
    'preflight_request_sha256', v_request_sha256,
    'completed_at', v_completed_at,
    'expires_at', v_expires_at
  );
  v_proof_sha256 := util.dataset_alias_execution_sha256(v_proof_material::text);

  insert into util.dataset_alias_execution_preflights (
    id,
    actor_user_id,
    actor_email,
    environment,
    project_ref,
    target_visibility,
    plan,
    freeze_envelope,
    approval_envelope,
    plan_sha256,
    operation_id,
    plan_request_sha256,
    bindings,
    bindings_sha256,
    expected,
    expected_sha256,
    derivative_targets,
    derivative_targets_sha256,
    gate_expectations,
    gate_expectations_sha256,
    failure_baseline_sha256,
    preflight_request_sha256,
    preflight_proof_sha256,
    freeze_sha256,
    approval_identity_sha256,
    token_sha256,
    completed_at,
    expires_at
  ) values (
    v_request_id,
    v_actor,
    lower(btrim(v_actor_email)),
    v_environment,
    v_project_ref,
    'owner_draft',
    v_plan,
    v_freeze,
    v_approval,
    v_plan_sha256,
    v_operation_id,
    v_plan_request_sha256,
    v_bindings,
    v_bindings_sha256,
    v_expected,
    v_expected_sha256,
    v_targets,
    v_targets_sha256,
    v_gate_expectations,
    v_gate_expectations_sha256,
    v_failure_baseline_sha256,
    v_request_sha256,
    v_proof_sha256,
    v_bindings->>'freeze_sha256',
    v_bindings->>'approval_identity_sha256',
    v_token_sha256,
    v_completed_at,
    v_expires_at
  );

  return v_proof_material || jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_preflight_guarded',
    'preflight_token', v_token,
    'preflight_proof_sha256', v_proof_sha256,
    'simulation', jsonb_build_object(
      'plan_rows', 52,
      'plan_exchanges', 59,
      'alias_audits', 55,
      'derivative_targets', 50,
      'rolled_back', true
    )
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_LOCK_BUSY',
      'status', 409,
      'message', 'Protected preflight could not acquire its bounded locks'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_CONCURRENT_CONFLICT',
      'status', 409,
      'message', 'A concurrent preflight consumed the same request identity'
    );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_alias_execution_preflight_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_preflight_guarded(p_request jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_alias_execution_preflight_guarded(p_request jsonb) IS 'Rollback-only server validation for the exact owner-draft 52-row/59-exchange alias plan plus its sorted 23-flow/27-process derivative closure. A successful call persists one non-replayable token that expires 180 seconds after simulation completes.';


--
-- Name: cmd_dataset_alias_execution_read(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_alias_execution_read(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '2s'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_request util.dataset_alias_execution_requests%rowtype;
  v_gate_receipts jsonb := '[]'::jsonb;
  v_gate_count integer := 0;
  v_alias_audit_count integer := 0;
  v_derivative_child_count integer := 0;
  v_derivative_flow_count integer := 0;
  v_derivative_process_count integer := 0;
  v_primary_closure jsonb;
  v_primary_closure_ok boolean := false;
  v_active_dispatch_grace boolean := false;
  v_initial_request_status text;
  v_initial_request_updated_at timestamp with time zone;
  v_proof_request_status text;
  v_proof_request_updated_at timestamp with time zone;
  v_request_changed_during_read boolean := false;
  v_batch_proof_read boolean := false;
  v_terminal_update_count integer := 0;
  v_terminal_update_status text;
  v_batch_proof jsonb;
  v_category text;
  v_now timestamp with time zone := pg_catalog.clock_timestamp();
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_READ_INVALID_REQUEST',
      'status', 400,
      'message', 'Exact protected execution request ID is required'
    );
  end if;

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = p_request_id
    and preflight.actor_user_id = v_actor;

  if v_preflight.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_REQUEST_NOT_FOUND',
      'status', 404,
      'message', 'No actor-owned protected preflight or execution exists'
    );
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'gate', receipt.gate_name,
          'expected_sha256', receipt.expected_sha256,
          'observed_sha256', receipt.observed_sha256,
          'status', receipt.status,
          'captured_at', receipt.captured_at,
          'receipt_sha256', receipt.receipt_sha256
        ) order by receipt.captured_at, receipt.gate_name
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  into v_gate_receipts, v_gate_count
  from util.dataset_alias_execution_gate_receipts as receipt
  where receipt.preflight_id = p_request_id
    and receipt.actor_user_id = v_actor;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  if v_request.id is null then
    return jsonb_build_object(
      'ok', true,
      'command', 'cmd_dataset_alias_execution_read',
      'schema_version', 'dataset-alias-execution-status.v1',
      'request_id', p_request_id,
      'status', 'indeterminate',
      'execution_status', 'not_admitted',
      'code', case
        when v_preflight.consumed_at is null
          then 'ALIAS_EXECUTION_NOT_ADMITTED'
        else 'ALIAS_EXECUTION_ADMISSION_LEDGER_MISSING'
      end,
      'retry_allowed', false,
      'actor_user_id', v_actor,
      'environment', v_preflight.environment,
      'project_ref', v_preflight.project_ref,
      'plan_sha256', v_preflight.plan_sha256,
      'operation_id', v_preflight.operation_id,
      'plan_request_sha256', v_preflight.plan_request_sha256,
      'preflight_proof_sha256', v_preflight.preflight_proof_sha256,
      'preflight_completed_at', v_preflight.completed_at,
      'preflight_expires_at', v_preflight.expires_at,
      'preflight_consumed_at', v_preflight.consumed_at,
      'gate_count', v_gate_count,
      'gates', v_gate_receipts
    );
  end if;

  v_initial_request_status := v_request.status;
  v_initial_request_updated_at := v_request.updated_at;

  v_active_dispatch_grace :=
    v_request.status in ('dispatching', 'dispatched', 'running')
    and v_now <= v_request.admitted_at + interval '120 seconds';

  if v_active_dispatch_grace then
    -- Do not run the heavyweight live closure while the one-shot executor may
    -- be committing.  Apart from wasting work, a status lock/readback race
    -- must never delay or misclassify the only authorized mutation attempt.
    v_primary_closure := jsonb_build_object(
      'ok', false,
      'schema_version', 'dataset-alias-primary-closure.v1',
      'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_PENDING',
      'live_closure_proof', false
    );
  else

  select count(*)::integer
  into v_alias_audit_count
  from private.command_audit_log as audit
  where audit.actor_user_id = v_actor
    and (
      (
        audit.command = 'cmd_dataset_alias_batch_guarded'
        and audit.payload->>'plan_sha256' = v_request.plan_sha256
        and audit.payload->>'operation_id' = v_request.operation_id
        and audit.payload->>'record_type' in ('row', 'batch_summary')
      )
      or (
        audit.command = 'cmd_dataset_alias_plan_guarded'
        and audit.payload->>'plan_request_sha256' =
          v_request.plan_request_sha256
        and audit.payload->>'record_type' = 'plan_summary'
      )
    );

  select
    count(*)::integer,
    count(*) filter (where target_table = 'flows')::integer,
    count(*) filter (where target_table = 'processes')::integer
  into
    v_derivative_child_count,
    v_derivative_flow_count,
    v_derivative_process_count
  from util.dataset_derivative_rebuild_requests as child
  where child.actor_user_id = v_actor
    and child.batch_id = p_request_id;

  v_primary_closure :=
    util.read_dataset_alias_execution_primary_closure(
      v_actor,
      v_preflight.plan
    );
  v_primary_closure_ok := coalesce(
    (v_primary_closure->>'live_closure_proof')::boolean,
    false
  );

  if v_request.status in ('dispatching', 'dispatched', 'running') then
    if v_alias_audit_count = 55
      and v_derivative_child_count = 50
      and v_derivative_flow_count = 23
      and v_derivative_process_count = 27
      and v_primary_closure_ok then
      update util.dataset_alias_execution_requests
      set
        status = 'derivatives_pending',
        primary_committed_at = coalesce(primary_committed_at, updated_at),
        updated_at = v_now
      where id = p_request_id
        and status in ('dispatching', 'dispatched', 'running');
    elsif (
        v_alias_audit_count > 0
        or v_derivative_child_count > 0
      ) and not v_primary_closure_ok then
      update util.dataset_alias_execution_requests
      set
        status = 'indeterminate',
        terminal_at = v_now,
        last_error = jsonb_build_object(
          'phase', 'reconcile',
          'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_MISMATCH',
          'primary_closure', v_primary_closure,
          'retry_allowed', false
        ),
        updated_at = v_now
      where id = p_request_id
        and status in ('dispatching', 'dispatched', 'running');
    elsif v_now > v_request.admitted_at + interval '120 seconds' then
      update util.dataset_alias_execution_requests
      set
        status = 'indeterminate',
        terminal_at = v_now,
        last_error = jsonb_build_object(
          'phase', 'reconcile',
          'code', 'ALIAS_EXECUTION_DISPATCH_OUTCOME_INDETERMINATE',
          'alias_audit_count', v_alias_audit_count,
          'derivative_child_count', v_derivative_child_count,
          'retry_allowed', false
        ),
        updated_at = v_now
      where id = p_request_id
        and status in ('dispatching', 'dispatched', 'running');
    end if;
  end if;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  v_request_changed_during_read :=
    v_request.status is distinct from v_initial_request_status
    or v_request.updated_at is distinct from v_initial_request_updated_at;

  if v_request_changed_during_read then
    -- VOLATILE PL/pgSQL statements can observe different READ COMMITTED
    -- snapshots.  If the executor or this reconciliation pass advanced the
    -- ledger after the first read, none of the evidence cached above is safe
    -- to use for another monotonic classification.  Return an explicit
    -- read-only conflict so the caller can poll again from the new state;
    -- execution admission and dispatch remain permanently non-retryable.
    return jsonb_build_object(
      'ok', false,
      'command', 'cmd_dataset_alias_execution_read',
      'schema_version', 'dataset-alias-execution-status.v1',
      'request_id', p_request_id,
      'code', 'ALIAS_EXECUTION_READ_STATE_CHANGED',
      'status', 409,
      'execution_status', v_request.status,
      'retry_allowed', false,
      'read_retry_allowed', true,
      'message', 'Execution state changed during readback; poll status again without redispatching'
    );
  end if;

  v_proof_request_status := v_request.status;
  v_proof_request_updated_at := v_request.updated_at;

  if v_derivative_child_count > 0
    or v_request.status in ('derivatives_pending', 'completed') then
    v_batch_proof_read := true;
    v_batch_proof := util.read_dataset_derivative_rebuild_batch(
      v_actor,
      p_request_id
    );

    select request.*
    into v_request
    from util.dataset_alias_execution_requests as request
    where request.id = p_request_id
      and request.actor_user_id = v_actor;

    if v_request.status is distinct from v_proof_request_status
      or v_request.updated_at is distinct from v_proof_request_updated_at then
      -- The derivative proof can be substantially more expensive than the
      -- parent-ledger read.  A different reader or the executor may classify
      -- the request while that proof is being assembled, so the cached proof
      -- must not be applied to the newly visible parent state.
      return jsonb_build_object(
        'ok', false,
        'command', 'cmd_dataset_alias_execution_read',
        'schema_version', 'dataset-alias-execution-status.v1',
        'request_id', p_request_id,
        'code', 'ALIAS_EXECUTION_READ_STATE_CHANGED',
        'status', 409,
        'execution_status', v_request.status,
        'retry_allowed', false,
        'read_retry_allowed', true,
        'message', 'Execution state changed during readback; poll status again without redispatching'
      );
    end if;
  end if;

  if v_request.status = 'derivatives_pending' then
    if v_alias_audit_count <> 55
      or v_derivative_child_count <> 50
      or v_derivative_flow_count <> 23
      or v_derivative_process_count <> 27
      or not v_primary_closure_ok then
      update util.dataset_alias_execution_requests
      set
        status = 'indeterminate',
        terminal_at = v_now,
        terminal_proof = jsonb_build_object(
          'primary_closure', v_primary_closure,
          'derivative_closure', v_batch_proof
        ),
        last_error = jsonb_build_object(
          'phase', 'readback',
          'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_MISMATCH',
          'alias_audit_count', v_alias_audit_count,
          'derivative_child_count', v_derivative_child_count,
          'primary_closure', v_primary_closure
        ),
        updated_at = v_now
      where id = p_request_id
        and status = 'derivatives_pending';
      get diagnostics v_terminal_update_count = row_count;
      if v_terminal_update_count = 1 then
        v_terminal_update_status := 'indeterminate';
      end if;
    elsif v_batch_proof->>'status' = 'completed'
      and coalesce((v_batch_proof->>'causal_terminal_proof')::boolean, false) then
      update util.dataset_alias_execution_requests
      set
        status = 'completed',
        terminal_at = v_now,
        terminal_proof = jsonb_build_object(
          'primary_closure', v_primary_closure,
          'derivative_closure', v_batch_proof
        ),
        updated_at = v_now
      where id = p_request_id
        and status = 'derivatives_pending';
      get diagnostics v_terminal_update_count = row_count;
      if v_terminal_update_count = 1 then
        v_terminal_update_status := 'completed';
      end if;
    elsif v_batch_proof->>'status' = 'failed' then
      update util.dataset_alias_execution_requests
      set
        status = 'failed',
        terminal_at = v_now,
        terminal_proof = jsonb_build_object(
          'primary_closure', v_primary_closure,
          'derivative_closure', v_batch_proof
        ),
        last_error = jsonb_build_object(
          'phase', 'derivative_readback',
          'code', coalesce(
            v_batch_proof->>'code',
            'ALIAS_EXECUTION_DERIVATIVE_CLOSURE_FAILED'
          )
        ),
        updated_at = v_now
      where id = p_request_id
        and status = 'derivatives_pending';
      get diagnostics v_terminal_update_count = row_count;
      if v_terminal_update_count = 1 then
        v_terminal_update_status := 'failed';
      end if;
    end if;
  end if;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  if v_batch_proof_read
    and (
      v_request.status is distinct from v_proof_request_status
      or v_request.updated_at is distinct from v_proof_request_updated_at
    )
    and not (
      v_terminal_update_count = 1
      and v_request.status is not distinct from v_terminal_update_status
      and v_request.updated_at is not distinct from v_now
    ) then
    -- A conditional terminal update with ROW_COUNT = 1 is this invocation's
    -- own monotonic classification.  Any other parent transition invalidates
    -- the cached derivative proof and must be retried as read-only polling.
    return jsonb_build_object(
      'ok', false,
      'command', 'cmd_dataset_alias_execution_read',
      'schema_version', 'dataset-alias-execution-status.v1',
      'request_id', p_request_id,
      'code', 'ALIAS_EXECUTION_READ_STATE_CHANGED',
      'status', 409,
      'execution_status', v_request.status,
      'retry_allowed', false,
      'read_retry_allowed', true,
      'message', 'Execution state changed during readback; poll status again without redispatching'
    );
  end if;

  end if;

  v_category := case v_request.status
    when 'completed' then 'passed'
    when 'failed' then 'failed'
    when 'indeterminate' then 'indeterminate'
    else 'pending'
  end;

  -- A stored completion is not allowed to hide later live-state drift during
  -- an independent readback.  The immutable ledger remains completed, but the
  -- fresh response fails closed if its current causal proof no longer passes.
  if v_request.status = 'completed'
    and (
      not v_primary_closure_ok
      or v_batch_proof is null
      or v_batch_proof->>'status' is distinct from 'completed'
      or coalesce((v_batch_proof->>'causal_terminal_proof')::boolean, false)
        is not true
    ) then
    v_category := 'failed';
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_read',
    'schema_version', 'dataset-alias-execution-status.v1',
    'request_id', p_request_id,
    'status', v_category,
    'execution_status', v_request.status,
    'retry_allowed', false,
    'actor_user_id', v_actor,
    'environment', v_preflight.environment,
    'project_ref', v_preflight.project_ref,
    'target_visibility', v_preflight.target_visibility,
    'plan_sha256', v_request.plan_sha256,
    'operation_id', v_request.operation_id,
    'plan_request_sha256', v_request.plan_request_sha256,
    'freeze_sha256', v_request.freeze_sha256,
    'approval_identity_sha256', v_request.approval_identity_sha256,
    'approval_text_sha256', v_request.approval_text_sha256,
    'derivative_target_set_sha256', v_request.derivative_target_set_sha256,
    'server_derivative_targets_sha256',
      v_preflight.derivative_targets_sha256,
    'preflight_proof_sha256', v_request.preflight_proof_sha256,
    'admission_request_sha256', v_request.admission_request_sha256,
    'gate_results_sha256', v_request.gate_results_sha256,
    'attempt_count', v_request.attempt_count,
    'dispatch_count', v_request.dispatch_count,
    'net_request_id', v_request.net_request_id::text,
    'preflight_completed_at', v_preflight.completed_at,
    'preflight_expires_at', v_preflight.expires_at,
    'preflight_consumed_at', v_preflight.consumed_at,
    'admitted_at', v_request.admitted_at,
    'dispatched_at', v_request.dispatched_at,
    'started_at', v_request.started_at,
    'primary_committed_at', v_request.primary_committed_at,
    'terminal_at', v_request.terminal_at,
    'gate_count', v_gate_count,
    'gates', v_gate_receipts,
    'primary_readback', jsonb_build_object(
      'row_count', case
        when v_alias_audit_count = 55 and v_primary_closure_ok then 52
        else null
      end,
      'exchange_count', case
        when v_alias_audit_count = 55 and v_primary_closure_ok then 59
        else null
      end,
      'alias_audit_count', v_alias_audit_count,
      'live_closure_proof', v_primary_closure_ok,
      'closure', v_primary_closure
    ),
    'derivative_readback', coalesce(
      v_batch_proof,
      jsonb_build_object(
        'schema_version', 'dataset-derivative-rebuild-batch-status.v1',
        'batch_id', p_request_id,
        'status', 'not_started',
        'code', 'DERIVATIVE_BATCH_NOT_STARTED',
        'proof_level', 'none',
        'proof_deferred', false,
        'target_count', v_derivative_child_count,
        'flow_count', v_derivative_flow_count,
        'process_count', v_derivative_process_count,
        'completed_count', 0,
        'nonterminal_count', 0,
        'failed_count', 0,
        'invalid_proof_count', null,
        'causal_terminal_proof', false,
        'targets', '[]'::jsonb
      )
    ),
    'error', v_request.last_error
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_READ_LOCK_BUSY',
      'status', 'indeterminate',
      'message', 'Protected execution status row is busy; readback did not retry or redispatch'
    );
end;
$$;


ALTER FUNCTION api.cmd_dataset_alias_execution_read(p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_read(p_request_id uuid); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_alias_execution_read(p_request_id uuid) IS 'Actor-only status and reconciliation for one protected attempt. It may monotonically classify durable evidence as derivatives_pending/completed/failed/indeterminate, but it never dispatches, retries, replays, or changes dataset rows.';


--
-- Name: cmd_dataset_assign_team(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_assign_team(p_table text, p_id uuid, p_version text, p_team_id uuid, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
  v_actor_has_team_role boolean;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can change dataset team ownership'
    );
  end if;

  if v_state_code >= 100 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_ALREADY_PUBLISHED',
      'status', 403,
      'message', 'Published data cannot be reassigned to another team',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  if v_state_code >= 20 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 403,
      'message', 'Data is under review and cannot be reassigned',
      'details', jsonb_build_object(
        'state_code', 20,
        'review_state_code', v_state_code
      )
    );
  end if;

  select exists (
    select 1
    from private.roles r
    where r.user_id = v_actor
      and r.team_id = p_team_id
      and r.role not in ('is_invited', 'rejected')
  )
    into v_actor_has_team_role;

  if not v_actor_has_team_role then
    return jsonb_build_object(
      'ok', false,
      'code', 'TEAM_MEMBERSHIP_REQUIRED',
      'status', 403,
      'message', 'You must belong to the target team before assigning dataset ownership'
    );
  end if;

  execute format(
    'update public.%I as t
        set team_id = $1,
            modified_at = now()
      where t.id = $2
        and t.version = $3
    returning to_jsonb(t)',
    p_table
  )
    into v_updated_row
    using p_team_id, p_id, p_version;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_assign_team',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_assign_team(p_table text, p_id uuid, p_version text, p_team_id uuid, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_create(text, uuid, jsonb, uuid, boolean, jsonb, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_create(p_table text, p_id uuid, p_json_ordered jsonb, p_model_id uuid DEFAULT NULL::uuid, p_rule_verification boolean DEFAULT NULL::boolean, p_audit jsonb DEFAULT '{}'::jsonb, p_model_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_model_version text := nullif(btrim(coalesce(p_model_version, '')), '');
  v_created_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table = 'lifecyclemodels' then
    return jsonb_build_object(
      'ok', false,
      'code', 'LIFECYCLEMODEL_BUNDLE_REQUIRED',
      'status', 400,
      'message', 'Lifecycle models must use bundle create and delete commands'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  if p_json_ordered is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'JSON_ORDERED_REQUIRED',
      'status', 400,
      'message', 'jsonOrdered is required'
    );
  end if;

  if p_table <> 'processes' and p_model_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_NOT_ALLOWED',
      'status', 400,
      'message', 'modelId is only allowed for process dataset creation'
    );
  end if;

  if p_table <> 'processes' and v_model_version is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_VERSION_NOT_ALLOWED',
      'status', 400,
      'message', 'modelVersion is only allowed for process dataset creation'
    );
  end if;

  if v_model_version is not null and p_model_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_REQUIRED_FOR_MODEL_VERSION',
      'status', 400,
      'message', 'modelId is required when modelVersion is provided'
    );
  end if;

  if v_model_version is not null
     and v_model_version !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_MODEL_VERSION',
      'status', 400,
      'message', 'modelVersion must use NN.NN.NNN format'
    );
  end if;

  if p_table = 'flows' then
    perform set_config('lock_timeout', '2s', true);
    perform set_config('statement_timeout', '8s', true);
  end if;

  begin
    if p_table = 'processes' then
      execute format(
        'insert into public.%I as t (id, json_ordered, model_id, model_version, rule_verification)
         values ($1, $2::json, $3, $4, $5)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', t.model_id,
           ''model_version'', t.model_version,
           ''rule_verification'', t.rule_verification
         )',
        p_table
      )
        into v_created_row
        using p_id, p_json_ordered, p_model_id, v_model_version, p_rule_verification;
    else
      execute format(
        'insert into public.%I as t (id, json_ordered, rule_verification)
         values ($1, $2::json, $3)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', null,
           ''model_version'', null,
           ''rule_verification'', t.rule_verification
         )',
        p_table
      )
        into v_created_row
        using p_id, p_json_ordered, p_rule_verification;
    end if;
  exception
    when lock_not_available then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_LOCK_TIMEOUT',
        'status', 503,
        'message', 'Dataset creation is temporarily blocked by concurrent database work'
      );
    when query_canceled then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_TIMEOUT',
        'status', 503,
        'message', 'Dataset creation exceeded the database timeout'
      );
    when unique_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23505',
        'status', 409,
        'message', 'Dataset with the same id and version already exists'
      );
    when not_null_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23502',
        'status', 400,
        'message', 'Dataset creation requires a valid id, version, and jsonOrdered payload'
      );
    when check_violation then
      return jsonb_build_object(
        'ok', false,
        'code', sqlstate,
        'status', 400,
        'message', sqlerrm
      );
  end;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_create',
    v_actor,
    p_table,
    p_id,
    nullif(v_created_row->>'version', ''),
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_created_row
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_create(p_table text, p_id uuid, p_json_ordered jsonb, p_model_id uuid, p_rule_verification boolean, p_audit jsonb, p_model_version text) OWNER TO postgres;

--
-- Name: cmd_dataset_create_version(text, uuid, text, jsonb, uuid, boolean, jsonb, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_create_version(p_table text, p_id uuid, p_source_version text, p_json_ordered jsonb, p_model_id uuid DEFAULT NULL::uuid, p_rule_verification boolean DEFAULT NULL::boolean, p_audit jsonb DEFAULT '{}'::jsonb, p_model_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_model_version text := nullif(btrim(coalesce(p_model_version, '')), '');
  v_root_key text;
  v_uri_slug text;
  v_source_exists boolean := false;
  v_source_version text := nullif(btrim(coalesce(p_source_version, '')), '');
  v_highest_version text;
  v_parts integer[];
  v_next_version text;
  v_next_uri text;
  v_payload jsonb;
  v_dataset jsonb;
  v_admin jsonb;
  v_pub jsonb;
  v_created_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  case p_table
    when 'contacts' then
      v_root_key := 'contactDataSet';
      v_uri_slug := 'contact';
    when 'sources' then
      v_root_key := 'sourceDataSet';
      v_uri_slug := 'source';
    when 'unitgroups' then
      v_root_key := 'unitGroupDataSet';
      v_uri_slug := 'unitgroup';
    when 'flowproperties' then
      v_root_key := 'flowPropertyDataSet';
      v_uri_slug := 'flowproperty';
    when 'flows' then
      v_root_key := 'flowDataSet';
      v_uri_slug := 'productFlow';
    when 'processes' then
      v_root_key := 'processDataSet';
      v_uri_slug := 'process';
    when 'lifecyclemodels' then
      return jsonb_build_object(
        'ok', false,
        'code', 'LIFECYCLEMODEL_BUNDLE_REQUIRED',
        'status', 400,
        'message', 'Lifecycle models must use bundle create-version commands'
      );
    else
      return jsonb_build_object(
        'ok', false,
        'code', 'INVALID_DATASET_TABLE',
        'status', 400,
        'message', 'Unsupported dataset table'
      );
  end case;

  if p_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_ID_REQUIRED',
      'status', 400,
      'message', 'id is required'
    );
  end if;

  if p_json_ordered is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'JSON_ORDERED_REQUIRED',
      'status', 400,
      'message', 'jsonOrdered is required'
    );
  end if;

  if v_source_version is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_SOURCE_VERSION_REQUIRED',
      'status', 400,
      'message', 'sourceVersion is required'
    );
  end if;

  if p_table <> 'processes' and p_model_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_NOT_ALLOWED',
      'status', 400,
      'message', 'modelId is only allowed for process dataset version creation'
    );
  end if;

  if p_table <> 'processes' and v_model_version is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_VERSION_NOT_ALLOWED',
      'status', 400,
      'message', 'modelVersion is only allowed for process dataset version creation'
    );
  end if;

  if v_model_version is not null and p_model_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_REQUIRED_FOR_MODEL_VERSION',
      'status', 400,
      'message', 'modelId is required when modelVersion is provided'
    );
  end if;

  if v_model_version is not null
     and v_model_version !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_MODEL_VERSION',
      'status', 400,
      'message', 'modelVersion must use NN.NN.NNN format'
    );
  end if;

  perform set_config('lock_timeout', '2s', true);
  perform set_config('statement_timeout', '8s', true);

  begin
    perform pg_advisory_xact_lock(
      hashtext('cmd_dataset_create_version:' || p_table),
      hashtext(p_id::text)
    );

    execute format(
      'select exists(
         select 1
           from public.%I d
          where d.id = $1
            and d.version = $2
            and (
              d.state_code >= 100
              or d.user_id = $3
              or exists (
                select 1
                  from private.roles r
                 where r.team_id = d.team_id
                   and r.user_id = $3
                   and r.role::text = any(array[''admin'', ''member'', ''owner''])
              )
            )
       )',
      p_table
    )
      into v_source_exists
      using p_id, v_source_version, v_actor;

    if not v_source_exists then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_SOURCE_NOT_FOUND',
        'status', 404,
        'message', 'Source dataset version not found'
      );
    end if;

    execute format(
      'select version::text
         from public.%I
        where id = $1
          and version::text ~ ''^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$''
        order by split_part(version::text, ''.'', 1)::integer desc,
                 split_part(version::text, ''.'', 2)::integer desc,
                 split_part(version::text, ''.'', 3)::integer desc
        limit 1',
      p_table
    )
      into v_highest_version
      using p_id;

    if v_highest_version is null then
      v_parts := array[0, 0, -1];
    else
      v_parts := array[
        split_part(v_highest_version, '.', 1)::integer,
        split_part(v_highest_version, '.', 2)::integer,
        split_part(v_highest_version, '.', 3)::integer
      ];
    end if;

    v_parts[3] := v_parts[3] + 1;

    if v_parts[3] > 999 then
      v_parts[3] := 0;
      v_parts[2] := v_parts[2] + 1;
    end if;

    if v_parts[2] > 99 then
      v_parts[2] := 0;
      v_parts[1] := v_parts[1] + 1;
    end if;

    v_next_version := lpad(v_parts[1]::text, 2, '0')
      || '.'
      || lpad(v_parts[2]::text, 2, '0')
      || '.'
      || lpad(v_parts[3]::text, 3, '0');
    v_next_uri := 'https://lcdn.tiangong.earth/datasetdetail/'
      || v_uri_slug
      || '.xhtml?uuid='
      || p_id::text
      || '&version='
      || v_next_version;

    v_payload := p_json_ordered;
    v_dataset := coalesce(v_payload->v_root_key, '{}'::jsonb);
    v_admin := coalesce(v_dataset->'administrativeInformation', '{}'::jsonb);
    v_pub := coalesce(v_admin->'publicationAndOwnership', '{}'::jsonb);
    v_pub := jsonb_set(v_pub, '{common:dataSetVersion}', to_jsonb(v_next_version), true);
    v_pub := jsonb_set(v_pub, '{common:permanentDataSetURI}', to_jsonb(v_next_uri), true);
    v_admin := jsonb_set(v_admin, '{publicationAndOwnership}', v_pub, true);
    v_dataset := jsonb_set(v_dataset, '{administrativeInformation}', v_admin, true);
    v_payload := jsonb_set(v_payload, array[v_root_key], v_dataset, true);

    if p_table = 'processes' then
      execute format(
        'insert into public.%I as t (id, json_ordered, model_id, model_version, rule_verification)
         values ($1, $2::json, $3, $4, $5)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', t.model_id,
           ''model_version'', t.model_version,
           ''rule_verification'', t.rule_verification,
           ''json_ordered'', t.json_ordered::jsonb
         )',
        p_table
      )
        into v_created_row
        using p_id, v_payload, p_model_id, v_model_version, p_rule_verification;
    else
      execute format(
        'insert into public.%I as t (id, json_ordered, rule_verification)
         values ($1, $2::json, $3)
         returning jsonb_build_object(
           ''id'', t.id,
           ''version'', t.version,
           ''state_code'', t.state_code,
           ''user_id'', t.user_id,
           ''team_id'', t.team_id,
           ''model_id'', null,
           ''model_version'', null,
           ''rule_verification'', t.rule_verification,
           ''json_ordered'', t.json_ordered::jsonb
         )',
        p_table
      )
        into v_created_row
        using p_id, v_payload, p_rule_verification;
    end if;
  exception
    when lock_not_available then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_VERSION_LOCK_TIMEOUT',
        'status', 503,
        'message', 'Dataset version creation is temporarily blocked by concurrent database work'
      );
    when query_canceled then
      return jsonb_build_object(
        'ok', false,
        'code', 'DATASET_CREATE_VERSION_TIMEOUT',
        'status', 503,
        'message', 'Dataset version creation exceeded the database timeout'
      );
    when unique_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23505',
        'status', 409,
        'message', 'Dataset with the same id and version already exists'
      );
    when not_null_violation then
      return jsonb_build_object(
        'ok', false,
        'code', '23502',
        'status', 400,
        'message', 'Dataset version creation requires a valid id, version, and jsonOrdered payload'
      );
    when check_violation then
      return jsonb_build_object(
        'ok', false,
        'code', sqlstate,
        'status', 400,
        'message', sqlerrm
      );
  end;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_create_version',
    v_actor,
    p_table,
    p_id,
    nullif(v_created_row->>'version', ''),
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_created_row
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_create_version(p_table text, p_id uuid, p_source_version text, p_json_ordered jsonb, p_model_id uuid, p_rule_verification boolean, p_audit jsonb, p_model_version text) OWNER TO postgres;

--
-- Name: cmd_dataset_delete(text, uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_delete(p_table text, p_id uuid, p_version text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_deleted_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table = 'lifecyclemodels' then
    return jsonb_build_object(
      'ok', false,
      'code', 'LIFECYCLEMODEL_BUNDLE_REQUIRED',
      'status', 400,
      'message', 'Lifecycle models must use bundle create and delete commands'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can delete this dataset'
    );
  end if;

  if v_state_code <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_DELETE_REQUIRES_DRAFT',
      'status', 403,
      'message', 'Only draft datasets can be deleted',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  execute format(
    'delete from public.%I as t
      where t.id = $1
        and t.version = $2
      returning to_jsonb(t)',
    p_table
  )
    into v_deleted_row
    using p_id, p_version;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_delete',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_deleted_row
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_delete(p_table text, p_id uuid, p_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_derivative_rebuild_plan_guarded(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_command constant text := 'cmd_dataset_derivative_rebuild_plan_guarded';
  v_schema_version constant text := 'dataset-derivative-rebuild-plan.v1';
  v_plan_sha256 text;
  v_operation_id text;
  v_action jsonb;
  v_action_id text;
  v_target_id uuid;
  v_target_version text;
  v_expected_snapshot_sha256 text;
  v_reason_code text;
  v_plan_request_sha256 text;
  v_action_request_sha256 text;
  v_existing util.dataset_derivative_rebuild_requests%rowtype;
  v_active_request_id uuid;
  v_process public.processes%rowtype;
  v_snapshot jsonb;
  v_quarantine jsonb;
  v_request_id uuid := pg_catalog.gen_random_uuid();
  v_action_audit_id bigint;
  v_summary_audit_id bigint;
  v_now timestamp with time zone := pg_catalog.clock_timestamp();
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_plan is not null and pg_column_size(p_plan) > 65536 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_REQUEST_TOO_LARGE',
      'status', 413,
      'message', 'Derivative rebuild plan exceeds 64 KiB'
    );
  end if;

  if jsonb_typeof(p_plan) is distinct from 'object'
    or not (p_plan ?& array[
      'schema_version',
      'plan_sha256',
      'operation_id',
      'target_visibility',
      'actions'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_plan) as plan_key(key)
      where plan_key.key <> all (array[
        'schema_version',
        'plan_sha256',
        'operation_id',
        'target_visibility',
        'actions'
      ])
    )
    or p_plan->>'schema_version' is distinct from v_schema_version
    or jsonb_typeof(p_plan->'plan_sha256') is distinct from 'string'
    or (p_plan->>'plan_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_plan->'operation_id') is distinct from 'string'
    or nullif(btrim(p_plan->>'operation_id'), '') is null
    or octet_length(p_plan->>'operation_id') > 512
    or p_plan->>'target_visibility' is distinct from 'owner_draft'
    or jsonb_typeof(p_plan->'actions') is distinct from 'array'
    or jsonb_array_length(p_plan->'actions') <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_INVALID_REQUEST',
      'status', 400,
      'message', 'Plan must match dataset-derivative-rebuild-plan.v1 exactly'
    );
  end if;

  v_plan_sha256 := p_plan->>'plan_sha256';
  v_operation_id := btrim(p_plan->>'operation_id');
  v_action := p_plan->'actions'->0;

  if jsonb_typeof(v_action) is distinct from 'object'
    or not (v_action ?& array[
      'action_id',
      'action',
      'table',
      'id',
      'version',
      'expected_state_code',
      'expected_snapshot_sha256',
      'components',
      'reason_code'
    ])
    or exists (
      select 1
      from jsonb_object_keys(v_action) as action_key(key)
      where action_key.key <> all (array[
        'action_id',
        'action',
        'table',
        'id',
        'version',
        'expected_state_code',
        'expected_snapshot_sha256',
        'components',
        'reason_code'
      ])
    )
    or jsonb_typeof(v_action->'action_id') is distinct from 'string'
    or nullif(btrim(v_action->>'action_id'), '') is null
    or octet_length(v_action->>'action_id') > 512
    or v_action->>'action' is distinct from 'rebuild_derivatives'
    or v_action->>'table' is distinct from 'processes'
    or jsonb_typeof(v_action->'id') is distinct from 'string'
    or (v_action->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(v_action->'version') is distinct from 'string'
    or (v_action->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or jsonb_typeof(v_action->'expected_state_code') is distinct from 'number'
    or v_action->>'expected_state_code' <> '0'
    or jsonb_typeof(v_action->'expected_snapshot_sha256') is distinct from 'string'
    or (v_action->>'expected_snapshot_sha256') !~ '^[a-f0-9]{64}$'
    or v_action->'components'
      is distinct from '["extracted_md", "embedding_ft"]'::jsonb
    or jsonb_typeof(v_action->'reason_code') is distinct from 'string'
    or nullif(btrim(v_action->>'reason_code'), '') is null
    or octet_length(v_action->>'reason_code') > 512 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_INVALID_ACTION',
      'status', 400,
      'message', 'Exactly one owner-draft process rebuild action is required'
    );
  end if;

  v_action_id := btrim(v_action->>'action_id');
  v_target_id := (v_action->>'id')::uuid;
  v_target_version := btrim(v_action->>'version');
  v_expected_snapshot_sha256 := v_action->>'expected_snapshot_sha256';
  v_reason_code := btrim(v_action->>'reason_code');
  v_plan_request_sha256 := util.dataset_derivative_rebuild_sha256(p_plan::text);
  v_action_request_sha256 := util.dataset_derivative_rebuild_sha256(v_action::text);

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_actor::text || ':' || v_plan_request_sha256,
      0
    )
  );

  select request.*
  into v_existing
  from util.dataset_derivative_rebuild_requests as request
  where request.actor_user_id = v_actor
    and request.plan_request_sha256 = v_plan_request_sha256;

  if v_existing.id is not null then
    if v_existing.plan_sha256 is distinct from v_plan_sha256
      or v_existing.operation_id is distinct from v_operation_id
      or v_existing.action_id is distinct from v_action_id
      or v_existing.target_id is distinct from v_target_id
      or v_existing.target_version is distinct from v_target_version
      or v_existing.expected_snapshot_sha256
        is distinct from v_expected_snapshot_sha256
      or v_existing.action_request_sha256
        is distinct from v_action_request_sha256 then
      return jsonb_build_object(
        'ok', false,
        'code', 'DERIVATIVE_PLAN_REPLAY_CONFLICT',
        'status', 409,
        'message', 'Existing admission does not match the exact plan'
      );
    end if;

    return jsonb_build_object(
      'ok', true,
      'command', v_command,
      'schema_version', v_schema_version,
      'plan_sha256', v_existing.plan_sha256,
      'operation_id', v_existing.operation_id,
      'target_visibility', v_existing.target_visibility,
      'plan_request_sha256', v_existing.plan_request_sha256,
      'action_count', 1,
      'accepted_count', 1,
      'summary_audit_id', v_existing.summary_audit_id::text,
      'request_id', v_existing.id::text,
      'status', 'queued',
      'action_request_sha256', v_existing.action_request_sha256,
      'database_audit_id', v_existing.action_audit_id::text,
      'idempotent_replay', true
    );
  end if;

  -- SHARE ROW EXCLUSIVE serializes statement snapshots around fence creation.
  -- A process writer either finishes before this frozen snapshot or begins
  -- after the nonterminal request/fence is committed and visible.
  lock table public.processes in share row exclusive mode;

  select process.*
  into v_process
  from public.processes as process
  where process.id = v_target_id
    and btrim(process.version::text) = v_target_version
    and process.user_id = v_actor
    and process.state_code = 0
  for update;

  if v_process.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_SCOPE_MISMATCH',
      'status', 409,
      'message', 'Action does not identify an exact current-owner draft process'
    );
  end if;

  begin
    v_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
  exception
    when others then
      return jsonb_build_object(
        'ok', false,
        'code', 'DERIVATIVE_PLAN_PRIMARY_NOT_READY',
        'status', 409,
        'message', 'Owner-draft process primary snapshot is incomplete'
      );
  end;

  if v_snapshot->>'json_sha256'
      is distinct from v_snapshot->>'json_ordered_sha256'
    or v_snapshot->>'snapshot_sha256'
      is distinct from v_expected_snapshot_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_SNAPSHOT_DRIFT',
      'status', 409,
      'message', 'Action snapshot changed before admission'
    );
  end if;

  select request.id
  into v_active_request_id
  from util.dataset_derivative_rebuild_requests as request
  where request.target_table = 'processes'
    and request.target_id = v_target_id
    and request.target_version = v_target_version
    and request.status not in ('completed', 'stale', 'failed')
  limit 1;

  if v_active_request_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_TARGET_BUSY',
      'status', 409,
      'message', 'Another derivative rebuild already fences this process'
    );
  end if;

  v_quarantine := util.quarantine_dataset_derivative_rebuild_target(
    v_target_id,
    v_target_version
  );

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  ) values (
    v_command,
    v_actor,
    'processes',
    v_target_id,
    v_target_version,
    jsonb_build_object(
      'record_type', 'action',
      'schema_version', v_schema_version,
      'request_id', v_request_id,
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id,
      'action_id', v_action_id,
      'target_visibility', 'owner_draft',
      'expected_snapshot_sha256', v_expected_snapshot_sha256,
      'plan_request_sha256', v_plan_request_sha256,
      'action_request_sha256', v_action_request_sha256,
      'reason_code', v_reason_code,
      'components', jsonb_build_array('extracted_md', 'embedding_ft'),
      'hash_algorithm', 'postgres-jsonb-text-sha256'
    )
  )
  returning id into v_action_audit_id;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  ) values (
    v_command,
    v_actor,
    null,
    null,
    null,
    jsonb_build_object(
      'record_type', 'plan_summary',
      'schema_version', v_schema_version,
      'request_id', v_request_id,
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id,
      'target_visibility', 'owner_draft',
      'plan_request_sha256', v_plan_request_sha256,
      'action_request_sha256', v_action_request_sha256,
      'action_count', 1,
      'accepted_count', 1,
      'action_audit_id', v_action_audit_id::text,
      'hash_algorithm', 'postgres-jsonb-text-sha256'
    )
  )
  returning id into v_summary_audit_id;

  insert into util.dataset_derivative_rebuild_requests (
    id,
    actor_user_id,
    plan_sha256,
    operation_id,
    action_id,
    target_id,
    target_version,
    expected_snapshot_sha256,
    expected_modified_at,
    expected_json_sha256,
    expected_json_ordered_sha256,
    before_extracted_md_sha256,
    before_embedding_ft_sha256,
    before_embedding_ft_at,
    plan_request_sha256,
    action_request_sha256,
    reason_code,
    status,
    phase,
    admitted_at,
    drain_not_before,
    action_audit_id,
    summary_audit_id,
    quarantined_http_requests,
    quarantined_embedding_jobs,
    quarantined_pending_jobs
  ) values (
    v_request_id,
    v_actor,
    v_plan_sha256,
    v_operation_id,
    v_action_id,
    v_target_id,
    v_target_version,
    v_expected_snapshot_sha256,
    (v_snapshot->>'modified_at')::timestamp with time zone,
    v_snapshot->>'json_sha256',
    v_snapshot->>'json_ordered_sha256',
    v_snapshot->>'extracted_md_sha256',
    v_snapshot->>'embedding_ft_sha256',
    (v_snapshot->>'embedding_ft_at')::timestamp with time zone,
    v_plan_request_sha256,
    v_action_request_sha256,
    v_reason_code,
    'queued',
    'admitted',
    v_now,
    v_now + interval '420 seconds',
    v_action_audit_id,
    v_summary_audit_id,
    coalesce((v_quarantine->>'http_requests')::integer, 0),
    coalesce((v_quarantine->>'embedding_jobs')::integer, 0),
    coalesce((v_quarantine->>'pending_jobs')::integer, 0)
  );

  return jsonb_build_object(
    'ok', true,
    'command', v_command,
    'schema_version', v_schema_version,
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'target_visibility', 'owner_draft',
    'plan_request_sha256', v_plan_request_sha256,
    'action_count', 1,
    'accepted_count', 1,
    'summary_audit_id', v_summary_audit_id::text,
    'request_id', v_request_id::text,
    'status', 'queued',
    'action_request_sha256', v_action_request_sha256,
    'database_audit_id', v_action_audit_id::text,
    'idempotent_replay', false
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_LOCK_BUSY',
      'status', 409,
      'message', 'Process write fence could not be acquired'
    );
  when unique_violation then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_PLAN_CONCURRENT_CONFLICT',
      'status', 409,
      'message', 'A concurrent admission won the exact plan or target'
    );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_derivative_rebuild_plan_guarded(p_plan jsonb) IS 'Exactly-once admission for one immutable current-owner state_code=0 process derivative rebuild. It creates the audit/fence atomically, quarantines visible old work, and returns queued admission only; completion is asynchronous.';


--
-- Name: cmd_dataset_derivative_rebuild_read(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_derivative_rebuild_read(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request util.dataset_derivative_rebuild_requests%rowtype;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_request_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_REQUEST_INVALID',
      'status', 400,
      'message', 'request id is required'
    );
  end if;

  select request.*
  into v_request
  from util.dataset_derivative_rebuild_requests as request
  where request.id = p_request_id
    and request.actor_user_id = v_actor;

  if v_request.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_REQUEST_NOT_AVAILABLE',
      'status', 404,
      'message', 'Derivative rebuild request is not available'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_derivative_rebuild_read',
    'schema_version', 'dataset-derivative-rebuild-status.v1',
    'request_id', v_request.id::text,
    'plan_sha256', v_request.plan_sha256,
    'operation_id', v_request.operation_id,
    'action_id', v_request.action_id,
    'table', v_request.target_table,
    'id', v_request.target_id::text,
    'version', v_request.target_version,
    'status', v_request.status,
    'phase', v_request.phase,
    'fence_active',
      v_request.status not in ('completed', 'stale', 'failed'),
    'plan_request_sha256', v_request.plan_request_sha256,
    'action_request_sha256', v_request.action_request_sha256,
    'database_audit_id', v_request.action_audit_id::text,
    'summary_audit_id', v_request.summary_audit_id::text,
    'completed_snapshot_sha256', v_request.completed_snapshot_sha256,
    'completed_at', v_request.completed_at,
    'terminal_at', v_request.terminal_at,
    'drained_at', v_request.drained_at,
    'error', v_request.last_error,
    'expected', jsonb_build_object(
      'snapshot_sha256', v_request.expected_snapshot_sha256,
      'modified_at', v_request.expected_modified_at,
      'json_sha256', v_request.expected_json_sha256,
      'json_ordered_sha256', v_request.expected_json_ordered_sha256,
      'before_extracted_md_sha256',
        v_request.before_extracted_md_sha256,
      'before_embedding_ft_sha256',
        v_request.before_embedding_ft_sha256,
      'before_embedding_ft_at', v_request.before_embedding_ft_at
    ),
    'quarantine', jsonb_build_object(
      'drain_not_before', v_request.drain_not_before,
      'failure_release_not_before',
        v_request.failure_release_not_before,
      'http_requests', v_request.quarantined_http_requests,
      'embedding_jobs', v_request.quarantined_embedding_jobs,
      'pending_jobs', v_request.quarantined_pending_jobs
    ),
    'markdown', jsonb_build_object(
      'request_id', case
        when v_request.markdown_request_id is null then null
        else v_request.markdown_request_id::text
      end,
      'dispatched_at', v_request.markdown_dispatched_at,
      'response_status', v_request.markdown_response_status,
      'response_received_at', v_request.markdown_response_received_at,
      'proposal_id', case
        when v_request.markdown_proposal_id is null then null
        else v_request.markdown_proposal_id::text
      end,
      'accepted_sha256', v_request.accepted_extracted_md_sha256
    ),
    'embedding', jsonb_build_object(
      'pending_job_id', case
        when v_request.embedding_pending_job_id is null then null
        else v_request.embedding_pending_job_id::text
      end,
      'queue_msg_id', case
        when v_request.embedding_queue_msg_id is null then null
        else v_request.embedding_queue_msg_id::text
      end,
      'queued_at', v_request.embedding_queued_at,
      'proposal_id', case
        when v_request.embedding_proposal_id is null then null
        else v_request.embedding_proposal_id::text
      end
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_dataset_derivative_rebuild_read(p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_derivative_rebuild_read(p_request_id uuid); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_derivative_rebuild_read(p_request_id uuid) IS 'Owner-only, mutation-free readback for one durable derivative rebuild request. Pending drain/fence state is explicit and cannot be presented as completion.';


--
-- Name: cmd_dataset_derivative_rebuild_snapshot(text, uuid, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_flow public.flows%rowtype;
  v_process public.processes%rowtype;
  v_snapshot jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table is null
    or p_table not in ('flows', 'processes')
    or p_id is null
    or p_version is null
    or btrim(p_version) !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_INVALID_REQUEST',
      'status', 400,
      'message', 'A flows or processes id and canonical version are required'
    );
  end if;

  if p_table = 'flows' then
    select flow.*
    into v_flow
    from public.flows as flow
    where flow.id = p_id
      and btrim(flow.version::text) = btrim(p_version)
      and flow.user_id = v_actor
      and flow.state_code = 0;
    if v_flow.id is not null then
      begin
        v_snapshot := util.dataset_derivative_rebuild_snapshot(v_flow);
      exception
        when others then
          v_snapshot := null;
      end;
    end if;
  else
    select process.*
    into v_process
    from public.processes as process
    where process.id = p_id
      and btrim(process.version::text) = btrim(p_version)
      and process.user_id = v_actor
      and process.state_code = 0;
    if v_process.id is not null then
      begin
        v_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
      exception
        when others then
          v_snapshot := null;
      end;
    end if;
  end if;

  if (p_table = 'flows' and v_flow.id is null)
    or (p_table = 'processes' and v_process.id is null) then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_NOT_AVAILABLE',
      'status', 404,
      'message', 'Owner-draft dataset snapshot is not available'
    );
  end if;

  if v_snapshot is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_NOT_READY',
      'status', 409,
      'message', 'Owner-draft dataset primary snapshot is incomplete'
    );
  end if;

  if v_snapshot->>'json_sha256'
    is distinct from v_snapshot->>'json_ordered_sha256' then
    return jsonb_build_object(
      'ok', false,
      'code', 'DERIVATIVE_SNAPSHOT_PRIMARY_MISMATCH',
      'status', 409,
      'message', 'json and json_ordered are not synchronized'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_derivative_rebuild_snapshot'
  ) || v_snapshot;
end;
$_$;


ALTER FUNCTION api.cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_derivative_rebuild_snapshot(p_table text, p_id uuid, p_version text) IS 'Returns one current-actor state_code=0 flow or process primary/derivative fingerprint. The original one-process v1 request remains compatible.';


--
-- Name: cmd_dataset_extraction_ack(bigint[]); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_extraction_ack(p_msg_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted jsonb := '[]'::jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  if coalesce(array_length(p_msg_ids, 1), 0) = 0 then
    return jsonb_build_object('ok', true, 'data', jsonb_build_object('deleted_msg_ids', v_deleted));
  end if;

  select coalesce(jsonb_agg(deleted_msg_id order by deleted_msg_id), '[]'::jsonb)
  into v_deleted
  from pgmq.delete('dataset_extraction_jobs', p_msg_ids) as deleted_msg_id;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object('deleted_msg_ids', v_deleted)
  );
end;
$$;


ALTER FUNCTION api.cmd_dataset_extraction_ack(p_msg_ids bigint[]) OWNER TO postgres;

--
-- Name: cmd_dataset_extraction_claim(integer, integer, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_extraction_claim(p_qty integer DEFAULT 10, p_vt_seconds integer DEFAULT 300, p_max_read_count integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qty integer;
  v_vt_seconds integer;
  v_max_read_count integer;
  v_jobs jsonb := '[]'::jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  v_qty := least(greatest(coalesce(p_qty, 10), 1), 50);
  v_vt_seconds := least(greatest(coalesce(p_vt_seconds, 300), 1), 3600);
  v_max_read_count := least(greatest(coalesce(p_max_read_count, 5), 1), 100);

  with expired_jobs as (
    select
      q.msg_id,
      q.message,
      q.read_ct
    from pgmq.q_dataset_extraction_jobs q
    where q.vt <= clock_timestamp()
      and q.read_ct >= v_max_read_count
    order by q.msg_id
    limit greatest(v_qty, 100)
  ),
  recorded_failures as (
    insert into util.dataset_extraction_job_failures (
      queue_name,
      msg_id,
      read_count,
      reason,
      message
    )
    select
      'dataset_extraction_jobs',
      e.msg_id,
      e.read_ct,
      format('read_ct reached retry cap %s', v_max_read_count),
      e.message
    from expired_jobs e
    on conflict (queue_name, msg_id) do update
    set
      read_count = excluded.read_count,
      reason = excluded.reason,
      message = excluded.message,
      created_at = now()
    returning msg_id
  )
  delete from pgmq.q_dataset_extraction_jobs q
  using recorded_failures f
  where q.msg_id = f.msg_id;

  with claimed_jobs as (
    select *
    from pgmq.read('dataset_extraction_jobs', v_vt_seconds, v_qty)
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'msg_id', msg_id,
        'read_ct', read_ct,
        'enqueued_at', enqueued_at,
        'vt', vt,
        'message', message
      )
      order by msg_id
    ),
    '[]'::jsonb
  )
  into v_jobs
  from claimed_jobs;

  return jsonb_build_object(
    'ok', true,
    'data', v_jobs
  );
end;
$$;


ALTER FUNCTION api.cmd_dataset_extraction_claim(p_qty integer, p_vt_seconds integer, p_max_read_count integer) OWNER TO postgres;

--
-- Name: cmd_dataset_extraction_record_failure(bigint, integer, text, jsonb, text, boolean); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_extraction_record_failure(p_msg_id bigint, p_read_count integer, p_reason text, p_message jsonb, p_last_error text DEFAULT NULL::text, p_delete boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  insert into util.dataset_extraction_job_failures (
    queue_name,
    msg_id,
    read_count,
    reason,
    message,
    last_error
  )
  values (
    'dataset_extraction_jobs',
    p_msg_id,
    coalesce(p_read_count, 0),
    coalesce(nullif(p_reason, ''), 'worker failure'),
    coalesce(p_message, '{}'::jsonb),
    p_last_error
  )
  on conflict (queue_name, msg_id) do update
  set
    read_count = excluded.read_count,
    reason = excluded.reason,
    message = excluded.message,
    last_error = excluded.last_error,
    created_at = now();

  if coalesce(p_delete, true) then
    perform pgmq.delete('dataset_extraction_jobs', p_msg_id);
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION api.cmd_dataset_extraction_record_failure(p_msg_id bigint, p_read_count integer, p_reason text, p_message jsonb, p_last_error text, p_delete boolean) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_capture_attest_guarded(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_capture_attest_guarded';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_request_sha256 text;
  v_context jsonb;
  v_existing util.dataset_flow_identity_capture_receipts%rowtype;
  v_receipt_id uuid := gen_random_uuid();
  v_captured_at timestamp with time zone := clock_timestamp();
  v_expires_at timestamp with time zone;
  v_mapping_intent jsonb;
  v_mapping jsonb;
  v_mapping_body jsonb;
  v_mappings jsonb := '[]'::jsonb;
  v_mapping_index jsonb;
  v_source_guard jsonb;
  v_target_guard jsonb;
  v_source_records jsonb := '[]'::jsonb;
  v_target_records jsonb := '[]'::jsonb;
  v_source_ordinal integer := 0;
  v_partition text;
  v_protected_entry jsonb;
  v_protected jsonb;
  v_supports jsonb;
  v_process_records jsonb := '[]'::jsonb;
  v_processes jsonb := '[]'::jsonb;
  v_source_universe jsonb;
  v_source_guard_set_sha256 text;
  v_target_guard_set_sha256 text;
  v_mapping_guard_set_sha256 text;
  v_process_intent_set_sha256 text;
  v_support_set_sha256 text;
  v_protected_sha256 text;
  v_source_universe_sha256 text;
  v_mapping_set_sha256 text;
  v_process_manifest_sha256 text;
  v_receipt_proof_sha256 text;
  v_whole_scope_proof_sha256 text;
  v_rewrite_count integer;
  v_validation jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if v_request is null
    or pg_column_size(v_request) > 134217728
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'environment', 'project_ref', 'actor',
      'target_visibility', 'operation_id', 'compatibility_policy',
      'artifact_evidence', 'mappings', 'process_intents', 'protected_closure'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-capture-attest.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}'))
      is distinct from v_actor_email
    or not private.dataset_flow_identity_exact_keys(
      v_request->'artifact_evidence', array[
        'review_ledger_sha256', 'live_capture_artifact_sha256',
        'toolchain_evidence_sha256'
      ]
    )
    or exists (
      select 1 from unnest(array[
        'review_ledger_sha256', 'live_capture_artifact_sha256',
        'toolchain_evidence_sha256'
      ]) as field(name)
      where v_request->'artifact_evidence'->>field.name
        !~ '^[a-f0-9]{64}$'
    )
    or jsonb_typeof(v_request->'mappings') <> 'array'
    or jsonb_array_length(v_request->'mappings') not between 1 and 305
    or jsonb_typeof(v_request->'process_intents') <> 'array'
    or jsonb_array_length(v_request->'process_intents') not between 1 and 12000
    or not private.dataset_flow_identity_exact_keys(
      v_request->'compatibility_policy', array[
        'schema_version', 'policy_sha256', 'evidence_resolution_sha256',
        'approved_at_utc', 'approval_text_sha256'
      ]
    )
    or v_request #>> '{compatibility_policy,schema_version}'
      <> 'dataset-flow-identity-compatibility-policy.v1'
    or exists (
      select 1 from unnest(array[
        'policy_sha256', 'evidence_resolution_sha256', 'approval_text_sha256'
      ]) as field(name)
      where v_request->'compatibility_policy'->>field.name
        !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CAPTURE_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 capture request schema or safe-JSON domain mismatch'
    );
  end if;
  begin
    perform (v_request #>>
      '{compatibility_policy,approved_at_utc}')::timestamp with time zone;
  exception when others then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CAPTURE_POLICY_TIME_INVALID', 'status', 400,
      'message', 'Compatibility policy approval time is invalid'
    );
  end;
  v_context := util.dataset_alias_execution_server_context();
  if v_request->>'environment' is distinct from v_context->>'environment'
    or v_request->>'project_ref' is distinct from v_context->>'project_ref' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CAPTURE_ENVIRONMENT_MISMATCH', 'status', 409,
      'message', 'Capture does not target this database branch'
    );
  end if;
  -- Capture and every owner-row trigger share this actor fence.  No process
  -- or elementary-flow write can straddle the final receipt attestation.
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  v_request_sha256 := util.dataset_flow_identity_restricted_sha256_v2(v_request);
  select receipt.* into v_existing
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.actor_user_id = v_actor
    and receipt.request_id = (v_request->>'request_id')::uuid;
  if v_existing.id is not null then
    if v_existing.capture_request_sha256 is distinct from v_request_sha256 then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CAPTURE_REQUEST_REUSE_MISMATCH', 'status', 409,
        'message', 'Capture request ID is already bound differently'
      );
    elsif v_existing.expires_at <= clock_timestamp() then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CAPTURE_RECEIPT_EXPIRED', 'status', 409,
        'message', 'Capture receipt expired; create a fresh request ID'
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'command', v_command,
      'schema_version', 'dataset-flow-identity-capture-attest-result.v2',
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'receipt_id', v_existing.id,
      'receipt_proof_sha256', v_existing.receipt_proof_sha256,
      'operation_id', v_existing.operation_id,
      'environment', v_existing.environment,
      'project_ref', v_existing.project_ref,
      'captured_at', v_existing.captured_at,
      'expires_at', v_existing.expires_at,
      'source_guard_set_sha256', v_existing.source_guard_set_sha256,
      'support_guard_set_sha256', v_existing.support_snapshot_set_sha256,
      'target_guard_set_sha256', v_existing.target_guard_set_sha256,
      'mapping_guard_set_sha256', v_existing.mapping_guard_set_sha256,
      'process_intent_set_sha256', v_existing.process_intent_set_sha256,
      'protected_closure_sha256', v_existing.protected_closure_sha256,
      'whole_scope_proof_sha256', v_existing.whole_scope_proof_sha256,
      'policy_sha256', v_existing.compatibility_policy->>'policy_sha256',
      'policy_approval_text_sha256',
        v_existing.policy_approval_text_sha256,
      'source_count', v_existing.source_count,
      'target_count', v_existing.target_count,
      'support_count', v_existing.support_count,
      'mapping_count', v_existing.mapping_count,
      'process_count', v_existing.process_count,
      'rewrite_count', v_existing.rewrite_count,
      'capture_request_sha256', v_existing.capture_request_sha256,
      'replay', true
    );
  end if;

  v_protected := private.dataset_flow_identity_build_protected_v2(
    v_actor, v_request->'protected_closure'
  );
  v_protected_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_protected);

  for v_mapping_intent in
    select item.value
    from jsonb_array_elements(v_request->'mappings')
      with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    if not private.dataset_flow_identity_exact_keys(v_mapping_intent, array[
        'ordinal', 'source', 'target', 'compatibility'
      ])
      or jsonb_typeof(v_mapping_intent->'ordinal') <> 'number'
      or (v_mapping_intent->>'ordinal')::integer
        <> jsonb_array_length(v_mappings) + 1
      or not private.dataset_flow_identity_exact_keys(
        v_mapping_intent->'compatibility', array[
          'policy_sha256', 'mode', 'confidence',
          'flow_property_compatible', 'unit_group_compatible',
          'direction_compatible', 'compartment_compatible',
          'conversion_factor', 'evidence_sha256', 'flow_schema',
          'process_schema_required'
        ]
      )
      or v_mapping_intent #>> '{compatibility,policy_sha256}'
        is distinct from v_request #>> '{compatibility_policy,policy_sha256}'
      or v_mapping_intent #>> '{compatibility,mode}' <> 'identity'
      or v_mapping_intent #>> '{compatibility,confidence}' <> 'approved'
      or v_mapping_intent #>> '{compatibility,conversion_factor}' <> '1'
      or v_mapping_intent #>> '{compatibility,evidence_sha256}'
        !~ '^[a-f0-9]{64}$'
      or v_mapping_intent #>> '{compatibility,process_schema_required}'
        <> 'pass'
      or not private.dataset_flow_identity_exact_keys(
        v_mapping_intent #> '{compatibility,flow_schema}',
        array['status', 'warning_set_sha256']
      )
      or v_mapping_intent #>> '{compatibility,flow_schema,status}'
        not in ('pass', 'legacy_warning')
      or v_mapping_intent #>>
        '{compatibility,flow_schema,warning_set_sha256}'
        !~ '^[a-f0-9]{64}$'
      or exists (
        select 1 from unnest(array[
          'flow_property_compatible', 'unit_group_compatible',
          'direction_compatible', 'compartment_compatible'
        ]) as field(name)
        where v_mapping_intent->'compatibility'->>field.name <> 'true'
      ) then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_MAPPING_INTENT_MISMATCH';
    end if;
    v_source_guard := private.dataset_flow_identity_build_flow_guard_v2(
      v_actor, v_mapping_intent->'source', false
    );
    v_target_guard := private.dataset_flow_identity_build_flow_guard_v2(
      v_actor, v_mapping_intent->'target', true
    );
    if v_source_guard->>'flow_property_id'
        is distinct from v_target_guard->>'flow_property_id'
      or v_source_guard->>'flow_property_version'
        is distinct from v_target_guard->>'flow_property_version'
      or v_source_guard->>'unit_group_id'
        is distinct from v_target_guard->>'unit_group_id'
      or v_source_guard->>'unit_group_version'
        is distinct from v_target_guard->>'unit_group_version' then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_MAPPING_NOT_IDENTITY_ONLY';
    end if;
    v_mapping_body := jsonb_build_object(
      'source', v_source_guard,
      'target', v_target_guard,
      'compatibility', v_mapping_intent->'compatibility'
    );
    v_mapping := jsonb_build_object(
      'ordinal', v_mapping_intent->'ordinal',
      'mapping_id',
        util.dataset_flow_identity_restricted_sha256_v2(v_mapping_body)
    ) || v_mapping_body;
    v_mappings := v_mappings || jsonb_build_array(v_mapping);
    v_source_ordinal := v_source_ordinal + 1;
    v_source_records := v_source_records || jsonb_build_array(
      jsonb_build_object(
        'ordinal', v_source_ordinal, 'disposition', 'mapped',
        'source_id', v_source_guard->>'id',
        'source_version', v_source_guard->>'version',
        'guard', v_source_guard,
        'evidence_sha256', v_source_guard->>'source_trace_sha256'
      )
    );
  end loop;

  foreach v_partition in array array['pending', 'blockers', 'orphans'] loop
    for v_protected_entry in
      select item.value
      from jsonb_array_elements(v_request->'protected_closure'->v_partition)
        with ordinality as item(value, ordinality)
      order by item.ordinality
    loop
      v_source_guard := private.dataset_flow_identity_build_flow_guard_v2(
        v_actor,
        jsonb_build_object(
          'id', v_protected_entry->>'source_id',
          'version', v_protected_entry->>'source_version',
          'source_trace_sha256', v_protected_entry->>'evidence_sha256'
        ),
        false
      );
      v_source_ordinal := v_source_ordinal + 1;
      v_source_records := v_source_records || jsonb_build_array(
        jsonb_build_object(
          'ordinal', v_source_ordinal,
          'disposition', case v_partition
            when 'blockers' then 'blocker'
            when 'orphans' then 'orphan'
            else 'pending' end,
          'source_id', v_source_guard->>'id',
          'source_version', v_source_guard->>'version',
          'guard', v_source_guard,
          'evidence_sha256', v_protected_entry->>'evidence_sha256'
        )
      );
    end loop;
  end loop;
  if jsonb_array_length(v_source_records) <> 305
    or (select count(distinct (item.value->>'source_id') || '@'
          || (item.value->>'source_version'))
        from jsonb_array_elements(v_source_records) as item(value)) <> 305 then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_SOURCE_CLOSURE_MISMATCH';
  end if;

  select coalesce(jsonb_agg(target order by target_id, target_version), '[]'::jsonb)
  into v_target_records
  from (
    select distinct on (
      item.value #>> '{target,id}', item.value #>> '{target,version}'
    )
      item.value #>> '{target,id}' as target_id,
      item.value #>> '{target,version}' as target_version,
      item.value->'target' as target
    from jsonb_array_elements(v_mappings) as item(value)
    order by item.value #>> '{target,id}', item.value #>> '{target,version}'
  ) as distinct_target;
  v_target_records := coalesce((
    select jsonb_agg(jsonb_build_object(
      'ordinal', item.ordinality,
      'target_id', item.value->>'id',
      'target_version', item.value->>'version',
      'guard', item.value
    ) order by item.ordinality)
    from jsonb_array_elements(v_target_records)
      with ordinality as item(value, ordinality)
  ), '[]'::jsonb);

  v_supports := private.dataset_flow_identity_build_support_set_v2(
    v_actor, v_mappings
  );
  for v_mapping in select item.value
    from jsonb_array_elements(v_mappings) as item(value)
  loop
    v_validation := util.dataset_flow_identity_validate_mapping(
      v_actor, v_mapping, v_request->'compatibility_policy', v_supports,
      (v_mapping->>'ordinal')::integer
    );
    if coalesce((v_validation->>'ok')::boolean, false) is false then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_MAPPING_LIVE_MISMATCH';
    end if;
  end loop;
  v_mapping_index :=
    private.dataset_flow_identity_mapping_index_v2(v_mappings);

  if exists (
    select 1
    from jsonb_array_elements(v_request->'process_intents')
      with ordinality as item(value, ordinality)
    where case when jsonb_typeof(item.value->'ordinal') = 'number'
      then (item.value->>'ordinal')::numeric = item.ordinality::numeric
      else false end is not true
  ) then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_ORDINAL_MISMATCH';
  end if;
  with built as materialized (
    select item.ordinality::integer as ordinal,
      private.dataset_flow_identity_build_process_v2(
        v_actor, item.value, v_mapping_index,
        v_request->'compatibility_policy', v_supports, v_protected_sha256
      ) as manifest
    from jsonb_array_elements(v_request->'process_intents')
      with ordinality as item(value, ordinality)
  )
  select
    coalesce(jsonb_agg(built.manifest order by built.ordinal), '[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', built.manifest->'ordinal',
      'process_id', built.manifest->>'id',
      'process_version', built.manifest->>'version',
      'intent_proof_sha256',
        util.dataset_flow_identity_restricted_sha256_v2(built.manifest),
      'manifest', built.manifest
    ) order by built.ordinal), '[]'::jsonb),
    coalesce(sum((built.manifest->>'rewrite_count')::integer), 0)::integer
  into v_processes, v_process_records, v_rewrite_count
  from built;
  if v_rewrite_count <= 0 then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_CLOSURE_EMPTY';
  end if;

  select jsonb_agg(jsonb_build_object(
    'id', (item.value->>'source_id')::uuid,
    'version', item.value->>'source_version',
    'user_id', v_actor,
    'state_code', 0,
    'flow_type', 'Elementary flow'
  ) order by item.value->>'source_id', item.value->>'source_version')
  into v_source_universe
  from jsonb_array_elements(v_source_records) as item(value);
  v_source_universe_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_source_universe);
  v_validation := util.dataset_flow_identity_source_universe(
    v_actor, v_source_universe, v_source_universe_sha256
  );
  if coalesce((v_validation->>'ok')::boolean, false) is false then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_SOURCE_UNIVERSE_LIVE_MISMATCH';
  end if;

  v_source_guard_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_source_records);
  v_target_guard_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_target_records);
  v_mapping_guard_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_mappings);
  v_process_intent_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_process_records);
  v_support_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_supports);
  v_mapping_set_sha256 := v_mapping_guard_set_sha256;
  v_process_manifest_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_processes);
  v_expires_at := v_captured_at + interval '7 days';
  v_whole_scope_proof_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
      'schema_version', 'dataset-flow-identity-capture-whole-scope.v2',
      'receipt_id', v_receipt_id,
      'actor_user_id', v_actor,
      'environment', v_request->>'environment',
      'project_ref', v_request->>'project_ref',
      'operation_id', v_request->>'operation_id',
      'capture_request_sha256', v_request_sha256,
      'source_guard_set_sha256', v_source_guard_set_sha256,
      'support_guard_set_sha256', v_support_set_sha256,
      'target_guard_set_sha256', v_target_guard_set_sha256,
      'mapping_guard_set_sha256', v_mapping_guard_set_sha256,
      'process_intent_set_sha256', v_process_intent_set_sha256,
      'protected_closure_sha256', v_protected_sha256,
      'captured_at', v_captured_at,
      'expires_at', v_expires_at
    ));
  v_receipt_proof_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'receipt_id', v_receipt_id,
      'whole_scope_proof_sha256', v_whole_scope_proof_sha256,
      'policy_sha256',
        v_request #>> '{compatibility_policy,policy_sha256}',
      'policy_approval_text_sha256',
        v_request #>> '{compatibility_policy,approval_text_sha256}'
    ));

  insert into util.dataset_flow_identity_capture_receipts (
    id, actor_user_id, actor_email, request_id, environment, project_ref,
    target_visibility, operation_id, compatibility_policy,
    policy_approval_text_sha256, artifact_evidence, protected_closure,
    protected_closure_sha256, source_universe, source_universe_sha256,
    support_snapshot_set_sha256, source_guard_set_sha256,
    target_guard_set_sha256, mapping_guard_set_sha256,
    process_intent_set_sha256, mapping_set_sha256,
    process_manifest_sha256, capture_request_sha256, receipt_proof_sha256,
    whole_scope_proof_sha256, source_count, target_count, support_count,
    mapping_count, process_count, rewrite_count, captured_at, expires_at
  ) values (
    v_receipt_id, v_actor, v_actor_email, (v_request->>'request_id')::uuid,
    v_request->>'environment', v_request->>'project_ref',
    'owner_draft', v_request->>'operation_id',
    v_request->'compatibility_policy',
    v_request #>> '{compatibility_policy,approval_text_sha256}',
    v_request->'artifact_evidence', v_protected, v_protected_sha256,
    v_source_universe, v_source_universe_sha256, v_support_set_sha256,
    v_source_guard_set_sha256, v_target_guard_set_sha256,
    v_mapping_guard_set_sha256, v_process_intent_set_sha256,
    v_mapping_set_sha256, v_process_manifest_sha256, v_request_sha256,
    v_receipt_proof_sha256, v_whole_scope_proof_sha256, 305,
    jsonb_array_length(v_target_records), jsonb_array_length(v_supports),
    jsonb_array_length(v_mappings), jsonb_array_length(v_processes),
    v_rewrite_count, v_captured_at, v_expires_at
  );
  insert into util.dataset_flow_identity_capture_source_guards (
    receipt_id, ordinal, disposition, source_id, source_version,
    guard, evidence_sha256
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      item.value->>'disposition', (item.value->>'source_id')::uuid,
      item.value->>'source_version', item.value->'guard',
      item.value->>'evidence_sha256'
    from jsonb_array_elements(v_source_records) as item(value);
  insert into util.dataset_flow_identity_capture_target_guards (
    receipt_id, ordinal, target_id, target_version, guard
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      (item.value->>'target_id')::uuid, item.value->>'target_version',
      item.value->'guard'
    from jsonb_array_elements(v_target_records) as item(value);
  insert into util.dataset_flow_identity_capture_support_guards (
    receipt_id, ordinal, support_table, support_id, support_version, guard
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      item.value->>'table', (item.value->>'id')::uuid,
      item.value->>'version', item.value
    from jsonb_array_elements(v_supports) as item(value);
  insert into util.dataset_flow_identity_capture_mapping_guards (
    receipt_id, ordinal, mapping_id, source_id, source_version,
    target_id, target_version, mapping
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      item.value->>'mapping_id', (item.value #>> '{source,id}')::uuid,
      item.value #>> '{source,version}',
      (item.value #>> '{target,id}')::uuid,
      item.value #>> '{target,version}', item.value
    from jsonb_array_elements(v_mappings) as item(value);
  insert into util.dataset_flow_identity_capture_process_intents (
    receipt_id, ordinal, process_id, process_version,
    intent_proof_sha256, manifest
  ) select v_receipt_id, (item.value->>'ordinal')::integer,
      (item.value->>'process_id')::uuid, item.value->>'process_version',
      item.value->>'intent_proof_sha256', item.value->'manifest'
    from jsonb_array_elements(v_process_records) as item(value);

  -- The helper is declared later in this migration, so use runtime resolution
  -- here.  It locks and revalidates all 305 sources, every support/target,
  -- every protected occurrence, and every intended process after the receipt
  -- relation has been fully inserted but before this transaction can return.
  execute
    'select private.dataset_flow_identity_whole_scope_proof_v2($1,$2,null,true)'
    into v_validation using v_actor, v_receipt_id;
  if coalesce((v_validation->>'ok')::boolean, false) is false then
    raise exception using errcode = '40001',
      message = 'FLOW_IDENTITY_CAPTURE_FINAL_WHOLE_SCOPE_DRIFT';
  end if;

  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-capture-attest-result.v2',
    'proof_domain', 'dataset-flow-identity-db-proof.v2',
    'receipt_id', v_receipt_id,
    'receipt_proof_sha256', v_receipt_proof_sha256,
    'operation_id', v_request->>'operation_id',
    'environment', v_request->>'environment',
    'project_ref', v_request->>'project_ref',
    'captured_at', v_captured_at, 'expires_at', v_expires_at,
    'source_guard_set_sha256', v_source_guard_set_sha256,
    'support_guard_set_sha256', v_support_set_sha256,
    'target_guard_set_sha256', v_target_guard_set_sha256,
    'mapping_guard_set_sha256', v_mapping_guard_set_sha256,
    'process_intent_set_sha256', v_process_intent_set_sha256,
    'protected_closure_sha256', v_protected_sha256,
    'whole_scope_proof_sha256', v_whole_scope_proof_sha256,
    'policy_sha256',
      v_request #>> '{compatibility_policy,policy_sha256}',
    'policy_approval_text_sha256',
      v_request #>> '{compatibility_policy,approval_text_sha256}',
    'source_count', 305,
    'target_count', jsonb_array_length(v_target_records),
    'support_count', jsonb_array_length(v_supports),
    'mapping_count', jsonb_array_length(v_mappings),
    'process_count', jsonb_array_length(v_processes),
    'rewrite_count', v_rewrite_count,
    'capture_request_sha256', v_request_sha256,
    'replay', false
  );
exception when others then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', case when sqlstate = '55P03'
      then 'FLOW_IDENTITY_CAPTURE_LOCK_BUSY'
      else 'FLOW_IDENTITY_CAPTURE_FAILED' end,
    'status', case when sqlstate = '55P03' then 409 else 400 end,
    'message', sqlerrm, 'sqlstate', sqlstate
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_flow_identity_capture_attest_guarded(p_request jsonb) IS 'Authenticated Step 3 v2 read-only capture attestation. It accepts typed semantic intent plus opaque artifact evidence, computes every live/before/desired/category/row hash in PostgreSQL, and persists an immutable relation-shaped receipt without mutating LCA datasets.';


--
-- Name: cmd_dataset_flow_identity_process_rewrite_guarded(uuid, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_process_rewrite_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '90s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_process_rewrite_guarded';
  v_actor uuid := auth.uid();
  v_request jsonb;
  v_request_sha256 text;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_ledger util.dataset_flow_identity_process_ledger%rowtype;
  v_internal jsonb;
  v_internal_sha256 text;
  v_core_result jsonb;
  v_live jsonb;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
  v_completed_process_count integer;
  v_next_ordinal integer;
  v_primary_complete boolean;
  v_invocation_id uuid;
  v_invocation util.dataset_flow_identity_wrapper_invocations%rowtype;
  v_execution_permit jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'scope_proof_sha256', 'ordinal',
      'process_intent_proof_sha256', 'process_request_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-process-rewrite.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'scope_proof_sha256' !~ '^[a-f0-9]{64}$'
    or v_request->>'process_intent_proof_sha256' !~ '^[a-f0-9]{64}$'
    or v_request->>'process_request_sha256' !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(v_request->'ordinal') <> 'number'
    or (v_request->>'ordinal')::numeric <= 0
    or (v_request->>'ordinal')::numeric > 2147483647 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 thin process request schema mismatch'
    );
  end if;
  v_request_sha256 := util.dataset_flow_identity_restricted_sha256_v2(
    v_request - 'process_request_sha256'
  );
  if v_request_sha256 is distinct from
    v_request->>'process_request_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_REQUEST_HASH_MISMATCH',
      'status', 409, 'message', 'Thin process request hash mismatch'
    );
  end if;

  -- Active execution is O(1): the owner fence precedes the scope fence.
  -- The full public target/support activation set is acquired only once by
  -- fresh preflight; repeating it for every ordinal would be O(P^2).
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_SCOPE_BUSY', 'status', 409,
      'message', 'Another process transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null
    or v_scope.scope_proof_sha256
      is distinct from v_request->>'scope_proof_sha256'
    or v_scope.status in ('failed', 'cancelled') then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_PROOF_MISMATCH', 'status', 409,
      'message', 'Scope proof is invalid or scope is not executable'
    );
  end if;
  v_invocation_id := private.dataset_flow_identity_validate_wrapper_permit_v1(
    v_actor, p_scope_id, p_authorization, 'process'
  );
  if v_invocation_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_WRAPPER_PERMIT_REQUIRED', 'status', 409,
      'message', 'A fresh one-wrapper execution permit is required'
    );
  end if;
  select invocation.* into strict v_invocation
  from util.dataset_flow_identity_wrapper_invocations as invocation
  where invocation.id = v_invocation_id
    and invocation.scope_id = v_scope.id
    and invocation.actor_user_id = v_actor
  for update;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_scope.receipt_proof_sha256 then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  select ledger.* into v_ledger
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id
    and ledger.ordinal = (v_request->>'ordinal')::integer
  for update;
  if v_ledger.scope_id is null
    or v_ledger.process_intent_proof_sha256
      is distinct from v_request->>'process_intent_proof_sha256' then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_INTENT_PROOF_MISMATCH', 'status', 409,
      'message', 'Thin request does not bind the receipt process intent'
    );
  end if;
  if v_ledger.status = 'completed' then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_ALREADY_COMPLETED_READ_SCOPE',
      'status', 409,
      'message', 'Completed process proof is available only through scope read'
    );
  end if;
  -- Full-scope reproof is reserved for ambiguous replay/recovery.  A normal
  -- pending ordinal is protected by the active row fences and is revalidated
  -- against its exact process/mapping/support guards inside the private core.
  if v_ledger.status = 'completed' then
    v_live := private.dataset_flow_identity_whole_scope_proof_v2(
      v_actor, v_scope.receipt_id, v_scope.id, true
    );
    if coalesce((v_live->>'ok')::boolean, false) is false then
      perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
        v_invocation_id
      );
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
        'message', 'Whole-scope replay proof drifted'
      );
    end if;
  end if;

  v_internal := jsonb_build_object(
    'schema_version', 'dataset-flow-identity-process-rewrite.v1',
    'request_id', v_request->>'request_id',
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'ordinal', v_ledger.ordinal,
    'process', v_ledger.manifest,
    'rewrites', v_ledger.manifest->'rewrites',
    'collision_ledger', v_ledger.manifest->'collision_ledger',
    'collision_ledger_sha256',
      v_ledger.manifest->>'collision_ledger_sha256',
    'process_request_sha256', ''
  );
  v_internal_sha256 := util.dataset_flow_identity_restricted_sha256_v2(
    v_internal - 'process_request_sha256'
  );
  v_internal := jsonb_set(
    v_internal, '{process_request_sha256}', to_jsonb(v_internal_sha256), false
  );
  perform set_config(
    'app.dataset_flow_identity_v2_process_request_sha256',
    v_request_sha256, true
  );
  v_core_result := private.dataset_flow_identity_process_rewrite_core_v1(
    p_scope_id, v_internal
  );
  if coalesce((v_core_result->>'ok')::boolean, false) is false then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return v_core_result;
  end if;
  update util.dataset_flow_identity_process_ledger as ledger
  set wrapper_invocation_id = v_invocation.id,
    permit_generation_before = v_invocation.generation
  where ledger.scope_id = v_scope.id
    and ledger.ordinal = (v_request->>'ordinal')::integer
    and ledger.wrapper_invocation_id is null
    and ledger.permit_generation_before is null
  returning ledger.* into v_ledger;
  if not found then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PROCESS_INVOCATION_BINDING_FAILED';
  end if;
  if v_ledger.status <> 'completed'
    or v_ledger.process_request_sha256 is distinct from v_request_sha256
    or v_ledger.after_payload_sha256
      is distinct from v_ledger.manifest->>'desired_payload_sha256'
    or v_ledger.after_exchange_set_sha256
      is distinct from v_ledger.manifest->>'desired_exchange_set_sha256'
    or v_ledger.audit_id is null or v_ledger.derivative_batch_id is null then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PROCESS_POST_CORE_PROOF_MISMATCH';
  end if;
  select audit.payload into v_audit_payload
  from private.command_audit_log as audit
  where audit.id = v_ledger.audit_id and audit.actor_user_id = v_actor
    and audit.command = v_command and audit.target_table = 'processes'
    and audit.target_id = v_ledger.process_id
    and audit.target_version = v_ledger.process_version;
  if v_audit_payload is null then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PROCESS_V2_AUDIT_MISSING';
  end if;
  v_expected_audit_payload := jsonb_build_object(
      'record_type', 'process_rewrite',
      'schema_version', 'dataset-flow-identity-process-rewrite.v2',
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'scope_id', v_scope.id,
      'receipt_id', v_receipt.id,
      'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
      'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
      'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'operation_id', v_scope.operation_id,
      'plan_sha256', v_scope.plan_sha256,
      'wrapper_invocation_id', v_invocation.id,
      'wrapper_approval_kind', v_invocation.approval_kind,
      'wrapper_approval_identity_sha256',
        v_invocation.approval_identity_sha256,
      'wrapper_admission_request_sha256',
        v_invocation.admission_request_sha256,
      'permit_generation_before', v_invocation.generation,
      'ordinal', v_ledger.ordinal,
      'process_intent_proof_sha256',
        v_ledger.process_intent_proof_sha256,
      'process_request_sha256', v_ledger.process_request_sha256,
      'process_template_sha256', v_ledger.process_template_sha256,
      'rewrite_set_sha256', v_ledger.manifest->>'rewrite_set_sha256',
      'collision_ledger_sha256',
        v_ledger.manifest->>'collision_ledger_sha256',
      'before_payload_sha256', v_ledger.before_payload_sha256,
      'before_exchange_set_sha256',
        v_ledger.manifest->>'before_exchange_set_sha256',
      'desired_payload_sha256',
        v_ledger.manifest->>'desired_payload_sha256',
      'desired_exchange_set_sha256',
        v_ledger.manifest->>'desired_exchange_set_sha256',
      'after_payload_sha256', v_ledger.after_payload_sha256,
      'after_exchange_set_sha256', v_ledger.after_exchange_set_sha256,
      'rewrite_count', v_ledger.rewrite_count,
      'derivative_batch_id', v_ledger.derivative_batch_id,
      'derivative_reason_code', 'FLOW_IDENTITY_SCOPE:'
        || v_scope.id::text || ':' || v_ledger.ordinal::text,
      'hash_algorithm', 'restricted-safe-json-v2-sha256'
    );
  if coalesce((v_core_result->>'replay')::boolean, false) is false then
    update private.command_audit_log
    set payload = v_expected_audit_payload
    where id = v_ledger.audit_id and actor_user_id = v_actor
      and command = v_command and target_table = 'processes'
    returning payload into v_audit_payload;
    if v_audit_payload is distinct from v_expected_audit_payload then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PROCESS_V2_AUDIT_PROMOTION_FAILED';
    end if;
  elsif v_audit_payload is distinct from v_expected_audit_payload then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_V2_AUDIT_DRIFT', 'status', 409,
      'message', 'The authoritative v2 process audit drifted'
    );
  end if;
  if coalesce((v_core_result->>'replay')::boolean, false) then
    select
      count(*) filter (where ledger.status = 'completed')::integer,
      min(ledger.ordinal) filter (where ledger.status = 'pending')::integer
    into v_completed_process_count, v_next_ordinal
    from util.dataset_flow_identity_process_ledger as ledger
    where ledger.scope_id = v_scope.id;
  else
    v_completed_process_count := v_ledger.ordinal;
    v_next_ordinal := case when v_ledger.ordinal < v_scope.process_count
      then v_ledger.ordinal + 1 else null end;
  end if;
  v_primary_complete := v_next_ordinal is null
    and v_completed_process_count = v_scope.process_count;
  v_execution_permit :=
    private.dataset_flow_identity_rotate_wrapper_permit_v1(
      v_invocation_id, 'process', false
    );
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-process-rewrite-result.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_scope.receipt_id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'invocation_id', v_invocation.id,
    'permit_generation_before', v_invocation.generation,
    'ordinal', v_ledger.ordinal,
    'process_id', v_ledger.process_id,
    'process_version', v_ledger.process_version,
    'process_request_sha256', v_ledger.process_request_sha256,
    'process_intent_proof_sha256',
      v_ledger.process_intent_proof_sha256,
    'before_payload_sha256', v_ledger.before_payload_sha256,
    'before_exchange_set_sha256',
      v_ledger.manifest->>'before_exchange_set_sha256',
    'desired_payload_sha256',
      v_ledger.manifest->>'desired_payload_sha256',
    'desired_exchange_set_sha256',
      v_ledger.manifest->>'desired_exchange_set_sha256',
    'after_payload_sha256', v_ledger.after_payload_sha256,
    'after_exchange_set_sha256', v_ledger.after_exchange_set_sha256,
    'rewrite_count', v_ledger.rewrite_count,
    'audit_id', v_ledger.audit_id::text,
    'derivative_batch_id', v_ledger.derivative_batch_id,
    'completed_process_count', v_completed_process_count,
    'next_ordinal', v_next_ordinal,
    'primary_complete', v_primary_complete,
    'status', v_ledger.status,
    'replay', coalesce((v_core_result->>'replay')::boolean, false),
    'execution_permit', v_execution_permit
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_PROCESS_LOCK_BUSY', 'status', 409,
    'message', 'Process transaction could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_flow_identity_process_rewrite_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_cancel_guarded(uuid, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '30s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_cancel_guarded';
  v_actor uuid := auth.uid();
  v_request jsonb;
  v_request_sha256 text;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_ledger_count integer;
  v_completed_count integer;
  v_nonpending_count integer;
  v_inactive_count integer;
  v_primary_proof_count integer;
  v_process_audit_count integer;
  v_permit_count integer;
  v_audit_id bigint;
  v_audit_count integer;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'receipt_id', 'receipt_proof_sha256',
      'operation_id', 'plan_sha256', 'scope_proof_sha256', 'reason',
      'evidence_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-cancel.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'receipt_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or nullif(btrim(v_request->>'reason'), '') is null
    or octet_length(v_request->>'reason') > 512
    or exists (
      select 1 from unnest(array[
        'receipt_proof_sha256', 'plan_sha256', 'scope_proof_sha256',
        'evidence_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 cancel request schema mismatch'
    );
  end if;
  v_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);

  -- Match the v2 execution lock order.  The owner fence excludes direct
  -- owner-row writes while the scope lock excludes a concurrent ordinal.
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_SCOPE_BUSY', 'status', 409,
      'message', 'Another transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_NOT_FOUND', 'status', 404,
      'message', 'No actor-owned Step 3 scope exists'
    );
  end if;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.id::text is distinct from v_request->>'receipt_id'
    or v_receipt.receipt_proof_sha256
      is distinct from v_request->>'receipt_proof_sha256'
    or v_scope.receipt_proof_sha256
      is distinct from v_request->>'receipt_proof_sha256'
    or v_scope.operation_id is distinct from v_request->>'operation_id'
    or v_scope.plan_sha256 is distinct from v_request->>'plan_sha256'
    or v_scope.scope_proof_sha256
      is distinct from v_request->>'scope_proof_sha256'
    or v_scope.target_visibility <> 'owner_draft' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_SCOPE_PROOF_MISMATCH', 'status', 409,
      'message', 'Cancel request does not bind the actor scope and receipt'
    );
  end if;

  v_expected_audit_payload := jsonb_build_object(
    'record_type', 'scope_cancel',
    'schema_version', 'dataset-flow-identity-scope-cancel.v2',
    'proof_domain', 'dataset-flow-identity-db-proof.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'cancel_request_sha256', v_request_sha256,
    'reason', btrim(v_request->>'reason'),
    'evidence_sha256', v_request->>'evidence_sha256',
    'completed_process_count', 0,
    'process_count', v_scope.process_count,
    'rewrite_count', v_scope.rewrite_count,
    'hash_algorithm', 'restricted-safe-json-v2-sha256'
  );
  if v_scope.status = 'cancelled' then
    if v_scope.cancel_request_sha256 is distinct from v_request_sha256 then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CANCEL_REPLAY_MISMATCH', 'status', 409,
        'message', 'Cancelled scope is bound to a different request'
      );
    end if;
    select count(*)::integer,
      jsonb_agg(audit.payload order by audit.id)->0,
      min(audit.id)
    into v_audit_count, v_audit_payload, v_audit_id
    from private.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
      and audit.payload->>'cancel_request_sha256' = v_request_sha256;
    if v_audit_count <> 1
      or v_audit_payload is distinct from v_expected_audit_payload then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_CANCEL_AUDIT_DRIFT', 'status', 409,
        'message', 'The authoritative v2 cancel audit is missing or drifted'
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'command', v_command,
      'schema_version', 'dataset-flow-identity-scope-cancel-result.v2',
      'scope_id', v_scope.id, 'receipt_id', v_receipt.id,
      'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
      'operation_id', v_scope.operation_id, 'plan_sha256', v_scope.plan_sha256,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'cancel_request_sha256', v_request_sha256,
      'status', 'cancelled', 'completed_process_count', 0,
      'audit_id', v_audit_id::text, 'replay', true
    );
  end if;
  if v_scope.status <> 'sealed' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_REQUIRES_ZERO_WRITE_SEAL', 'status', 409,
      'message', 'Only an untouched sealed scope can be cancelled',
      'scope_status', v_scope.status, 'automatic_retry', false
    );
  end if;

  select count(*)::integer,
    count(*) filter (where ledger.status = 'completed')::integer,
    count(*) filter (where ledger.status <> 'pending')::integer,
    count(*) filter (where not ledger.active)::integer,
    count(*) filter (
      where ledger.audit_id is not null
        or ledger.after_payload_sha256 is not null
        or ledger.after_exchange_set_sha256 is not null
        or ledger.derivative_batch_id is not null
        or ledger.process_request_sha256 is not null
        or ledger.completed_at is not null
    )::integer
  into v_ledger_count, v_completed_count, v_nonpending_count,
    v_inactive_count, v_primary_proof_count
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  select count(*)::integer into v_process_audit_count
  from private.command_audit_log as audit
  where audit.command = 'cmd_dataset_flow_identity_process_rewrite_guarded'
    and audit.actor_user_id = v_actor
    and audit.target_table = 'processes'
    and audit.payload->>'scope_id' = v_scope.id::text;
  select count(*)::integer into v_permit_count
  from util.dataset_flow_identity_mutation_permits as permit
  where permit.scope_id = v_scope.id;
  if v_ledger_count <> v_scope.process_count
    or v_completed_count <> 0 or v_nonpending_count <> 0
    or v_inactive_count <> 0 or v_primary_proof_count <> 0
    or v_process_audit_count <> 0 or v_permit_count <> 0 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_CANCEL_PRIMARY_WRITE_PROOF_EXISTS', 'status', 409,
      'message', 'Scope ledger or audit proves a primary write attempt',
      'completed_process_count', v_completed_count,
      'automatic_retry', false
    );
  end if;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    v_command, v_actor, null, null, null, v_expected_audit_payload
  ) returning id into v_audit_id;
  update util.dataset_flow_identity_process_ledger
  set active = false where scope_id = v_scope.id;
  update util.dataset_flow_identity_scopes
  set status = 'cancelled', cancel_request_sha256 = v_request_sha256,
    last_error = jsonb_build_object(
      'code', 'FLOW_IDENTITY_SCOPE_CANCELLED',
      'schema_version', 'dataset-flow-identity-scope-cancel.v2',
      'cancel_request_sha256', v_request_sha256,
      'reason', btrim(v_request->>'reason'),
      'evidence_sha256', v_request->>'evidence_sha256'
    ), updated_at = clock_timestamp()
  where id = v_scope.id;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-cancel-result.v2',
    'scope_id', v_scope.id, 'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'operation_id', v_scope.operation_id, 'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'cancel_request_sha256', v_request_sha256,
    'status', 'cancelled', 'completed_process_count', 0,
    'audit_id', v_audit_id::text, 'replay', false
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_CANCEL_LOCK_BUSY', 'status', 409,
    'message', 'Cancellation could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_flow_identity_scope_cancel_guarded(p_scope_id uuid, p_request jsonb) IS 'Actor-only v2 Step 3 abandon path. Exact replay is read-only; a fresh cancel releases active fences only for an untouched sealed scope whose ledger, audit, derivative, and mutation-permit proof all show zero primary writes.';


--
-- Name: cmd_dataset_flow_identity_scope_finalize_guarded(uuid, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_scope_finalize_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_finalize_guarded';
  v_actor uuid := auth.uid();
  v_request jsonb;
  v_request_sha256 text;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_whole_result jsonb;
  v_whole jsonb;
  v_internal jsonb;
  v_core jsonb;
  v_derivative_targets jsonb;
  v_derivative_target_set_sha256 text;
  v_terminal_proof_sha256 text;
  v_final_audit_id bigint;
  v_final_audit_payload jsonb;
  v_expected_final_audit_payload jsonb;
  v_live_drift boolean;
  v_live_guard_current boolean;
  v_was_completed boolean;
  v_result jsonb;
  v_invocation_id uuid;
  v_invocation util.dataset_flow_identity_wrapper_invocations%rowtype;
  v_execution_permit jsonb;
  v_permit_consumed boolean := false;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'scope_proof_sha256', 'expected'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-finalize.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'scope_proof_sha256' !~ '^[a-f0-9]{64}$'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'expected', array[
        'process_count', 'rewrite_count', 'completed_process_count'
      ]
    )
    or exists (
      select 1 from unnest(array[
        'process_count', 'rewrite_count', 'completed_process_count'
      ]) as field(name)
      where jsonb_typeof(v_request->'expected'->field.name) <> 'number'
        or (v_request->'expected'->>field.name)::numeric <= 0
        or (v_request->'expected'->>field.name)::numeric > 2147483647
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 thin finalize request schema mismatch'
    );
  end if;
  v_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_SCOPE_BUSY', 'status', 409,
      'message', 'Another transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null
    or v_scope.scope_proof_sha256
      is distinct from v_request->>'scope_proof_sha256'
    or v_scope.status in ('failed', 'cancelled')
    or (v_request #>> '{expected,process_count}')::integer
      <> v_scope.process_count
    or (v_request #>> '{expected,rewrite_count}')::integer
      <> v_scope.rewrite_count
    or (v_request #>> '{expected,completed_process_count}')::integer
      <> v_scope.process_count then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_SCOPE_PROOF_MISMATCH', 'status', 409,
      'message', 'Finalize request does not bind the actor scope and counts'
    );
  end if;
  v_invocation_id := private.dataset_flow_identity_validate_wrapper_permit_v1(
    v_actor, p_scope_id, p_authorization, 'finalize'
  );
  if v_invocation_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_WRAPPER_PERMIT_REQUIRED', 'status', 409,
      'message', 'A fresh one-wrapper execution permit is required'
    );
  end if;
  select invocation.* into strict v_invocation
  from util.dataset_flow_identity_wrapper_invocations as invocation
  where invocation.id = v_invocation_id
    and invocation.scope_id = v_scope.id
    and invocation.actor_user_id = v_actor
  for update;
  v_was_completed := v_scope.status = 'completed';
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_scope.receipt_proof_sha256 then
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_FINALIZE_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, true
  );
  v_whole := v_whole_result->'whole_scope_proof';
  v_live_drift := coalesce((v_whole_result->>'ok')::boolean, false) is false;
  v_live_guard_current := coalesce(
      (v_whole->>'audit_current')::boolean, false
    ) and coalesce((v_whole->>'source_guards_current')::boolean, false
    ) and coalesce((v_whole->>'support_guards_current')::boolean, false)
    and coalesce((v_whole->>'target_guards_current')::boolean, false)
    and coalesce((v_whole->>'protected_closure_current')::boolean, false)
    and coalesce((v_whole->>'occurrence_closure_current')::boolean, false);
  select coalesce(jsonb_agg(jsonb_build_object(
    'ordinal', ledger.ordinal,
    'id', ledger.process_id,
    'version', ledger.process_version,
    'desired_json_ordered_sha256',
      ledger.manifest->>'desired_payload_sha256',
    'baseline_snapshot_sha256',
      ledger.manifest->>'derivative_baseline_snapshot_sha256'
  ) order by ledger.ordinal), '[]'::jsonb)
  into v_derivative_targets
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  v_derivative_target_set_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_derivative_targets);
  if not v_live_drift then
    v_internal := jsonb_build_object(
      'schema_version', 'dataset-flow-identity-scope-finalize.v1',
      'request_id', v_request->>'request_id',
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'expected', jsonb_build_object(
        'process_count', v_scope.process_count,
        'rewrite_count', v_scope.rewrite_count,
        'completed_process_count', v_scope.process_count,
        'primary_closure_sha256', v_whole->>'primary_closure_sha256',
        'protected_closure_sha256', v_scope.protected_closure_sha256,
        'derivative_target_set_sha256', v_derivative_target_set_sha256
      )
    );
    perform set_config(
      'app.dataset_flow_identity_v2_finalize_request_sha256',
      v_request_sha256, true
    );
    v_core := private.dataset_flow_identity_scope_finalize_core_v1(
      p_scope_id, v_internal
    );
    if v_core->>'status' not in ('derivatives_pending', 'completed') then
      v_core := jsonb_build_object(
        'ok', false,
        'status', 'failed',
        'code', 'FLOW_IDENTITY_FINALIZE_FAILED',
        'compensation_required', false,
        'compensation_targets', '[]'::jsonb
      );
    end if;
    select scope.* into v_scope
    from util.dataset_flow_identity_scopes as scope
    where scope.id = p_scope_id and scope.actor_user_id = v_actor
    for update;
    -- A fresh completion is promoted using the already current pre-core proof.
    -- Re-entering whole-scope proof before the v2 terminal audit exists would
    -- deterministically mark audit_current false.  Pending and replay paths do
    -- not have that transitional state and are re-read immediately.
    if v_core->>'status' <> 'completed' or v_was_completed then
      v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
        v_actor, v_receipt.id, v_scope.id, true
      );
      v_whole := v_whole_result->'whole_scope_proof';
      v_live_drift :=
        coalesce((v_whole_result->>'ok')::boolean, false) is false;
      v_live_guard_current := coalesce(
          (v_whole->>'audit_current')::boolean, false
        ) and coalesce((v_whole->>'source_guards_current')::boolean, false
        ) and coalesce((v_whole->>'support_guards_current')::boolean, false)
        and coalesce((v_whole->>'target_guards_current')::boolean, false)
        and coalesce((v_whole->>'protected_closure_current')::boolean, false)
        and coalesce((v_whole->>'occurrence_closure_current')::boolean, false);
    end if;
  end if;
  -- Completed replay is dynamic, not a trust in the stored scope status.  A
  -- stale/failed derivative downgrades to pending/compensation and must never
  -- rewrite the terminal proof or terminal audit.
  if not v_live_drift and v_core->>'status' = 'completed'
    and (
      coalesce((v_whole->>'derivatives_current')::boolean, false) is false
      or coalesce((v_whole->>'causal_terminal_proof')::boolean, false) is false
    ) then
    v_core := jsonb_build_object(
      'ok', coalesce((v_whole_result #>>
        '{derivative_set_proof,failed_count}')::integer, 0) = 0,
      'status', 'derivatives_pending',
      'code', case when coalesce((v_whole_result #>>
          '{derivative_set_proof,failed_count}')::integer, 0) > 0
        then 'FLOW_IDENTITY_DERIVATIVE_COMPENSATION_REQUIRED'
        else 'FLOW_IDENTITY_DERIVATIVES_PENDING' end,
      'compensation_required', coalesce((v_whole_result #>>
        '{derivative_set_proof,failed_count}')::integer, 0) > 0,
      'compensation_targets', coalesce(
        v_whole_result #> '{derivative_set_proof,compensation_targets}',
        '[]'::jsonb
      )
    );
  end if;
  if not v_live_drift and v_core->>'status' = 'completed'
      and not v_was_completed then
    v_terminal_proof_sha256 :=
      util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
        'schema_version', 'dataset-flow-identity-terminal-proof.v2',
        'scope_id', v_scope.id,
        'receipt_id', v_receipt.id,
        'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
        'scope_proof_sha256', v_scope.scope_proof_sha256,
        'plan_sha256', v_scope.plan_sha256,
        'final_request_sha256', v_request_sha256,
        'wrapper_invocation_id', v_invocation.id,
        'wrapper_approval_kind', v_invocation.approval_kind,
        'wrapper_approval_identity_sha256',
          v_invocation.approval_identity_sha256,
        'wrapper_admission_request_sha256',
          v_invocation.admission_request_sha256,
        'permit_generation_before', v_invocation.generation,
        'whole_scope_proof_sha256',
          v_whole_result->>'whole_scope_proof_sha256',
        'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
        'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
        'protected_closure_sha256', v_receipt.protected_closure_sha256,
        'derivative_target_set_sha256', v_derivative_target_set_sha256,
        'derivative_proof_set_sha256',
          v_whole->>'derivative_proof_set_sha256'
      ));
    update util.dataset_flow_identity_scopes
    set terminal_proof_sha256 = v_terminal_proof_sha256,
      final_wrapper_invocation_id = v_invocation.id,
      final_permit_generation_before = v_invocation.generation,
      updated_at = clock_timestamp()
    where id = v_scope.id;
    v_scope.terminal_proof_sha256 := v_terminal_proof_sha256;
    select audit.id, audit.payload
    into v_final_audit_id, v_final_audit_payload
    from private.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
    order by audit.id desc limit 1;
    if v_final_audit_id is null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_FINALIZE_V2_AUDIT_MISSING';
    end if;
    v_expected_final_audit_payload := jsonb_build_object(
        'record_type', 'scope_terminal',
        'schema_version', 'dataset-flow-identity-scope-finalize.v2',
        'proof_domain', 'dataset-flow-identity-db-proof.v2',
        'scope_id', v_scope.id,
        'receipt_id', v_receipt.id,
        'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
        'operation_id', v_scope.operation_id,
        'plan_sha256', v_scope.plan_sha256,
        'scope_proof_sha256', v_scope.scope_proof_sha256,
        'final_request_sha256', v_request_sha256,
        'wrapper_invocation_id', v_invocation.id,
        'wrapper_approval_kind', v_invocation.approval_kind,
        'wrapper_approval_identity_sha256',
          v_invocation.approval_identity_sha256,
        'wrapper_admission_request_sha256',
          v_invocation.admission_request_sha256,
        'permit_generation_before', v_invocation.generation,
        'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
        'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
        'protected_closure_sha256', v_receipt.protected_closure_sha256,
        'primary_closure_sha256', v_whole->>'primary_closure_sha256',
        'derivative_target_set_sha256', v_derivative_target_set_sha256,
        'derivative_proof_set_sha256',
          v_whole->>'derivative_proof_set_sha256',
        'whole_scope_proof_sha256',
          v_whole_result->>'whole_scope_proof_sha256',
        'terminal_proof_sha256', v_terminal_proof_sha256,
        'process_count', v_scope.process_count,
        'rewrite_count', v_scope.rewrite_count,
        'hash_algorithm', 'restricted-safe-json-v2-sha256'
      );
    update private.command_audit_log
    set payload = v_expected_final_audit_payload
    where id = v_final_audit_id and actor_user_id = v_actor
      and command = v_command and target_table is null
    returning payload into v_final_audit_payload;
    if v_final_audit_payload
        is distinct from v_expected_final_audit_payload then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_FINALIZE_V2_AUDIT_PROMOTION_FAILED';
    end if;
    -- Terminal consumption is part of the same transaction and precedes the
    -- durable post-promotion proof.  The proof therefore requires the exact
    -- N -> N+1 terminal rotation and one successful finalize post.
    v_execution_permit :=
      private.dataset_flow_identity_rotate_wrapper_permit_v1(
        v_invocation_id, 'finalize', true
      );
    v_permit_consumed := true;
    v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
      v_actor, v_receipt.id, v_scope.id, true
    );
    v_whole := v_whole_result->'whole_scope_proof';
    v_live_drift :=
      coalesce((v_whole_result->>'ok')::boolean, false) is false;
    v_live_guard_current := coalesce(
        (v_whole->>'audit_current')::boolean, false
      ) and coalesce((v_whole->>'source_guards_current')::boolean, false
      ) and coalesce((v_whole->>'support_guards_current')::boolean, false)
      and coalesce((v_whole->>'target_guards_current')::boolean, false)
      and coalesce((v_whole->>'protected_closure_current')::boolean, false)
      and coalesce((v_whole->>'occurrence_closure_current')::boolean, false);
    if v_live_drift then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_FINALIZE_POST_PROMOTION_DRIFT';
    end if;
  else
    select audit.id into v_final_audit_id
    from private.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
    order by audit.id desc limit 1;
  end if;
  v_result := jsonb_build_object(
    'ok', not v_live_drift
      and coalesce(v_core->>'status', '') <> 'failed'
      and coalesce((v_core->>'compensation_required')::boolean, false) is false,
    'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-finalize-result.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'invocation_id', v_invocation.id,
    'permit_generation_before', v_invocation.generation,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', case when v_live_drift then 'live_drift'
      else v_core->>'status' end,
    'process_count', v_scope.process_count,
    'completed_process_count',
      (v_request #>> '{expected,completed_process_count}')::integer,
    'rewrite_count', v_scope.rewrite_count,
    'primary_closure_sha256', v_whole->>'primary_closure_sha256',
    'protected_closure_sha256', v_receipt.protected_closure_sha256,
    'derivative_target_set_sha256', v_derivative_target_set_sha256,
    'derivative_proof_set_sha256',
      v_whole->>'derivative_proof_set_sha256',
    'primary_current', (v_whole->>'primary_current')::boolean,
    'live_guard_current', v_live_guard_current,
    'derivatives_current', case when v_live_drift then false
      else (v_whole->>'derivatives_current')::boolean end,
    'terminal_proof_sha256', case
      when not v_live_drift and v_core->>'status' = 'completed'
      then v_scope.terminal_proof_sha256 else null end,
    'whole_scope_proof', v_whole,
    'whole_scope_proof_sha256',
      v_whole_result->>'whole_scope_proof_sha256',
    'audit_id', case when v_final_audit_id is null
      then null else v_final_audit_id::text end,
    'replay', v_was_completed
  );
  if coalesce((v_result->>'ok')::boolean, false) then
    if not v_permit_consumed then
      v_execution_permit :=
        private.dataset_flow_identity_rotate_wrapper_permit_v1(
          v_invocation_id, 'finalize', false
        );
    end if;
    v_result := v_result || jsonb_build_object(
      'execution_permit', v_execution_permit
    );
  else
    perform private.dataset_flow_identity_invalidate_wrapper_permit_v1(
      v_invocation_id
    );
  end if;
  if v_live_drift then
    return v_result || jsonb_build_object(
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT',
      'compensation_required', false,
      'automatic_retry', false,
      'compensation_targets', '[]'::jsonb
    );
  elsif v_core->>'status' = 'derivatives_pending' then
    return v_result || jsonb_build_object(
      'code', v_core->>'code',
      'compensation_required',
        coalesce((v_core->>'compensation_required')::boolean, false),
      'automatic_retry', false,
      'compensation_targets',
        coalesce(v_core->'compensation_targets', '[]'::jsonb)
    );
  elsif v_core->>'status' = 'failed' then
    return v_result || jsonb_build_object(
      'code', 'FLOW_IDENTITY_FINALIZE_FAILED',
      'compensation_required', false,
      'automatic_retry', false,
      'compensation_targets', '[]'::jsonb
    );
  end if;
  return v_result;
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_FINALIZE_LOCK_BUSY', 'status', 409,
    'message', 'Finalization could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_flow_identity_scope_finalize_guarded(p_scope_id uuid, p_request jsonb, p_authorization jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_lookup(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_scope_lookup(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text := 'cmd_dataset_flow_identity_scope_lookup';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_whole_result jsonb;
  v_audit_id bigint;
  v_next_ordinal integer;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if v_request is null or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'receipt_id', 'receipt_proof_sha256',
      'environment', 'project_ref', 'actor', 'target_visibility',
      'user_state_claim', 'operation_id', 'plan_sha256', 'freeze_sha256',
      'policy_approval_text_sha256', 'execution_approval_request_sha256',
      'execution_approval_text_sha256',
      'execution_approval_identity_sha256', 'toolchain_evidence_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-lookup.v1'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'receipt_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or v_request->>'user_state_claim'
      <> 'authenticated_actor_state_100_plus_own_state_0'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}')) is distinct from v_actor_email
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or exists (
      select 1 from unnest(array[
        'receipt_proof_sha256', 'plan_sha256', 'freeze_sha256',
        'policy_approval_text_sha256', 'execution_approval_request_sha256',
        'execution_approval_text_sha256',
        'execution_approval_identity_sha256', 'toolchain_evidence_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_INVALID_REQUEST', 'status', 400,
      'message', 'Scope lookup request schema mismatch'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.actor_user_id = v_actor
    and scope.request_id = (v_request->>'request_id')::uuid
    and scope.receipt_id = (v_request->>'receipt_id')::uuid
    and scope.receipt_proof_sha256 = v_request->>'receipt_proof_sha256'
    and scope.environment = v_request->>'environment'
    and scope.project_ref = v_request->>'project_ref'
    and scope.target_visibility = v_request->>'target_visibility'
    and scope.user_state_claim = v_request->>'user_state_claim'
    and scope.operation_id = v_request->>'operation_id'
    and scope.plan_sha256 = v_request->>'plan_sha256'
    and scope.freeze_sha256 = v_request->>'freeze_sha256'
    and scope.policy_approval_text_sha256 =
      v_request->>'policy_approval_text_sha256'
    and scope.execution_approval_request_sha256 =
      v_request->>'execution_approval_request_sha256'
    and scope.approval_text_sha256 =
      v_request->>'execution_approval_text_sha256'
    and scope.approval_identity_sha256 =
      v_request->>'execution_approval_identity_sha256'
    and scope.toolchain_evidence_sha256 =
      v_request->>'toolchain_evidence_sha256';
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_NOT_FOUND', 'status', 404,
      'message', 'No exactly bound actor-owned Step 3 scope exists'
    );
  end if;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor
    and receipt.receipt_proof_sha256 = v_scope.receipt_proof_sha256;
  if v_receipt.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, false
  );
  if coalesce((v_whole_result->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
      'message', 'Located scope no longer matches live database state'
    );
  end if;
  select audit.id into v_audit_id
  from private.command_audit_log as audit
  where audit.command = 'cmd_dataset_flow_identity_scope_preflight_guarded'
    and audit.actor_user_id = v_actor and audit.target_table is null
    and audit.payload->>'scope_id' = v_scope.id::text;
  if v_audit_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_LOOKUP_AUDIT_DRIFT', 'status', 409,
      'message', 'Authoritative scope-seal audit is missing'
    );
  end if;
  select coalesce(min(ledger.ordinal) filter (
    where ledger.status = 'pending'
  ), v_scope.process_count + 1)
  into v_next_ordinal
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-lookup-result.v1',
    'read_only', true,
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_scope.status,
    'process_count', v_scope.process_count,
    'mapping_count', v_scope.mapping_count,
    'support_snapshot_count', v_receipt.support_count,
    'source_universe_count', 305,
    'rewrite_count', v_scope.rewrite_count,
    'next_ordinal', v_next_ordinal,
    'audit_id', v_audit_id::text,
    'whole_scope_proof_sha256',
      v_whole_result->>'whole_scope_proof_sha256',
    'execution_permit', null
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_flow_identity_scope_lookup(p_request jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_preflight_guarded(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_scope_preflight_guarded(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_preflight_guarded';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_request_sha256 text;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_internal jsonb;
  v_core_result jsonb;
  v_live jsonb;
  v_mappings jsonb;
  v_supports jsonb;
  v_processes jsonb;
  v_scope_proof_sha256 text;
  v_audit_id bigint;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
  v_invocation_id uuid;
  v_permit_token text;
  v_execution_permit jsonb := null;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'receipt_id', 'receipt_proof_sha256',
      'environment', 'project_ref', 'actor', 'target_visibility',
      'user_state_claim',
      'operation_id', 'plan_sha256', 'freeze_sha256',
      'policy_approval_text_sha256', 'execution_approval_request_sha256',
      'execution_approval_text_sha256',
      'execution_approval_identity_sha256', 'toolchain_evidence_sha256',
      'maximum_wrapper_invocations', 'maximum_process_posts',
      'maximum_finalize_posts', 'maximum_cli_apply_spawns',
      'approval_reusable', 'automatic_retry'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-preflight.v2'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'receipt_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or v_request->>'user_state_claim'
      <> 'authenticated_actor_state_100_plus_own_state_0'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}'))
      is distinct from v_actor_email
    or nullif(btrim(v_request->>'operation_id'), '') is null
    or octet_length(v_request->>'operation_id') > 512
    or jsonb_typeof(v_request->'maximum_wrapper_invocations') <> 'number'
    or (v_request->>'maximum_wrapper_invocations')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_process_posts') <> 'number'
    or (v_request->>'maximum_process_posts')::numeric <= 0
    or (v_request->>'maximum_process_posts')::numeric > 2147483647
    or jsonb_typeof(v_request->'maximum_finalize_posts') <> 'number'
    or (v_request->>'maximum_finalize_posts')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_cli_apply_spawns') <> 'number'
    or (v_request->>'maximum_cli_apply_spawns')::numeric <> 1
    or v_request->'approval_reusable' is distinct from 'false'::jsonb
    or v_request->'automatic_retry' is distinct from 'false'::jsonb
    or exists (
      select 1 from unnest(array[
        'receipt_proof_sha256', 'plan_sha256', 'freeze_sha256',
        'policy_approval_text_sha256', 'execution_approval_request_sha256',
        'execution_approval_text_sha256',
        'execution_approval_identity_sha256', 'toolchain_evidence_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    )
    or (
      select count(distinct value)
      from unnest(array[
        v_request->>'policy_approval_text_sha256',
        v_request->>'execution_approval_request_sha256',
        v_request->>'execution_approval_text_sha256',
        v_request->>'execution_approval_identity_sha256'
      ]) as approval(value)
    ) <> 4 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_INVALID_REQUEST', 'status', 400,
      'message', 'Step 3 v2 preflight request schema mismatch'
    );
  end if;
  v_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);

  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = (v_request->>'receipt_id')::uuid
    and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_request->>'receipt_proof_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_RECEIPT_INVALID', 'status', 409,
      'message', 'Capture receipt is missing, foreign, or forged'
    );
  end if;
  if v_receipt.environment is distinct from v_request->>'environment'
    or v_receipt.project_ref is distinct from v_request->>'project_ref'
    or v_receipt.target_visibility
      is distinct from v_request->>'target_visibility'
    or v_receipt.operation_id is distinct from v_request->>'operation_id'
    or v_receipt.policy_approval_text_sha256
      is distinct from v_request->>'policy_approval_text_sha256'
    or v_receipt.artifact_evidence->>'toolchain_evidence_sha256'
      is distinct from v_request->>'toolchain_evidence_sha256'
    or (v_request->>'maximum_process_posts')::integer
      is distinct from v_receipt.process_count then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_RECEIPT_BINDING_MISMATCH',
      'status', 409,
      'message', 'Preflight identity does not exactly bind the receipt'
    );
  end if;
  -- The owner fence is held through activation.  A concurrent row UPDATE
  -- blocked by the deterministic FOR SHARE proof resumes into this VOLATILE
  -- BEFORE trigger under READ COMMITTED, where the trigger's SQL sees the
  -- newly committed active scope and rejects the write.
  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));

  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.actor_user_id = v_actor
    and scope.operation_id = v_receipt.operation_id;
  if v_scope.id is not null then
    if v_scope.receipt_id is distinct from v_receipt.id
      or v_scope.preflight_request_sha256 is distinct from v_request_sha256 then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_OPERATION_REUSE_MISMATCH',
        'status', 409, 'message', 'Operation is already sealed differently'
      );
    end if;
    if v_scope.status in ('cancelled', 'failed') then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_SCOPE_TERMINAL_CONFLICT',
        'status', 409, 'scope_status', v_scope.status,
        'message', 'A cancelled or failed scope cannot be replayed as v2'
      );
    end if;
  else
    if exists (
      select 1
      from util.dataset_flow_identity_wrapper_invocations as invocation
      where invocation.actor_user_id = v_actor
        and array[
          v_request->>'execution_approval_request_sha256',
          v_request->>'execution_approval_text_sha256',
          v_request->>'execution_approval_identity_sha256'
        ] && array[
          invocation.approval_request_sha256,
          invocation.approval_text_sha256,
          invocation.approval_identity_sha256
        ]
    ) then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_APPROVAL_REUSE_MISMATCH',
        'status', 409,
        'message', 'Execution approval hash was already consumed'
      );
    end if;
    if v_receipt.expires_at <= clock_timestamp() then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_RECEIPT_EXPIRED', 'status', 409,
        'message', 'Capture receipt expired before first consumption'
      );
    end if;
    v_live := private.dataset_flow_identity_whole_scope_proof_v2(
      v_actor, v_receipt.id, null, true
    );
    if coalesce((v_live->>'ok')::boolean, false) is false then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PREFLIGHT_LIVE_DRIFT', 'status', 409,
        'message', 'Receipt baselines drifted before scope sealing'
      );
    end if;

    select coalesce(jsonb_agg(guard.mapping order by guard.ordinal), '[]'::jsonb)
    into v_mappings
    from util.dataset_flow_identity_capture_mapping_guards as guard
    where guard.receipt_id = v_receipt.id;
    select coalesce(jsonb_agg(guard.guard order by guard.ordinal), '[]'::jsonb)
    into v_supports
    from util.dataset_flow_identity_capture_support_guards as guard
    where guard.receipt_id = v_receipt.id;
    select coalesce(jsonb_agg(intent.manifest order by intent.ordinal), '[]'::jsonb)
    into v_processes
    from util.dataset_flow_identity_capture_process_intents as intent
    where intent.receipt_id = v_receipt.id;

    v_internal := jsonb_build_object(
      'schema_version', 'dataset-flow-identity-scope-preflight.v1',
      'request_id', v_request->>'request_id',
      'environment', v_receipt.environment,
      'project_ref', v_receipt.project_ref,
      'actor', jsonb_build_object(
        'user_id', v_actor, 'email', v_actor_email
      ),
      'target_visibility', 'owner_draft',
      'operation_id', v_receipt.operation_id,
      'plan_sha256', v_request->>'plan_sha256',
      'freeze_sha256', v_request->>'freeze_sha256',
      'approval_identity_sha256',
        v_request->>'execution_approval_identity_sha256',
      'approval_text_sha256',
        v_request->>'execution_approval_text_sha256',
      'toolchain_evidence_sha256',
        v_request->>'toolchain_evidence_sha256',
      'compatibility_policy', v_receipt.compatibility_policy,
      'support_snapshot_set_sha256',
        v_receipt.support_snapshot_set_sha256,
      'support_snapshots', v_supports,
      'source_universe_sha256', v_receipt.source_universe_sha256,
      'source_universe_count', 305,
      'mapping_set_sha256', v_receipt.mapping_set_sha256,
      'process_manifest_sha256', v_receipt.process_manifest_sha256,
      'protected_closure_sha256', v_receipt.protected_closure_sha256,
      'mappings', v_mappings,
      'processes', v_processes,
      'protected_closure', v_receipt.protected_closure
    );
    perform set_config(
      'app.dataset_flow_identity_receipt_id', v_receipt.id::text, true
    );
    perform set_config(
      'app.dataset_flow_identity_receipt_proof_sha256',
      v_receipt.receipt_proof_sha256, true
    );
    perform set_config(
      'app.dataset_flow_identity_policy_approval_sha256',
      v_receipt.policy_approval_text_sha256, true
    );
    perform set_config(
      'app.dataset_flow_identity_execution_request_sha256',
      v_request->>'execution_approval_request_sha256', true
    );
    perform set_config(
      'app.dataset_flow_identity_preflight_request_sha256',
      v_request_sha256, true
    );
    v_core_result :=
      private.dataset_flow_identity_scope_preflight_core_v1(v_internal);
    if coalesce((v_core_result->>'ok')::boolean, false) is false then
      return v_core_result;
    end if;
    select scope.* into v_scope
    from util.dataset_flow_identity_scopes as scope
    where scope.id = (v_core_result->>'scope_id')::uuid
      and scope.actor_user_id = v_actor;
    if v_scope.id is null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PREFLIGHT_SCOPE_MISSING_AFTER_CORE';
    end if;
    v_scope_proof_sha256 :=
      util.dataset_flow_identity_restricted_sha256_v2(jsonb_build_object(
        'schema_version', 'dataset-flow-identity-scope-proof.v2',
        'scope_id', v_scope.id,
        'receipt_id', v_receipt.id,
        'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
        'actor_user_id', v_actor,
        'environment', v_scope.environment,
        'project_ref', v_scope.project_ref,
        'operation_id', v_scope.operation_id,
        'plan_sha256', v_scope.plan_sha256,
        'freeze_sha256', v_scope.freeze_sha256,
        'policy_approval_text_sha256',
          v_scope.policy_approval_text_sha256,
        'execution_approval_request_sha256',
          v_scope.execution_approval_request_sha256,
        'execution_approval_text_sha256', v_scope.approval_text_sha256,
        'execution_approval_identity_sha256',
          v_scope.approval_identity_sha256,
        'toolchain_evidence_sha256', v_scope.toolchain_evidence_sha256,
        'preflight_request_sha256', v_scope.preflight_request_sha256,
        'capture_whole_scope_proof_sha256',
          v_receipt.whole_scope_proof_sha256
      ));
    update util.dataset_flow_identity_scopes
    set scope_proof_sha256 = v_scope_proof_sha256,
      updated_at = clock_timestamp()
    where id = v_scope.id;
    v_scope.scope_proof_sha256 := v_scope_proof_sha256;
  end if;

  select audit.id, audit.payload into v_audit_id, v_audit_payload
  from private.command_audit_log as audit
  where audit.command = v_command and audit.actor_user_id = v_actor
    and audit.target_table is null
    and audit.payload->>'scope_id' = v_scope.id::text
  order by audit.id desc limit 1;
  if v_audit_id is null then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_PREFLIGHT_V2_AUDIT_MISSING';
  end if;
  v_expected_audit_payload := jsonb_build_object(
      'record_type', 'scope_seal',
      'schema_version', 'dataset-flow-identity-scope-preflight.v2',
      'proof_domain', 'dataset-flow-identity-db-proof.v2',
      'scope_id', v_scope.id,
      'receipt_id', v_receipt.id,
      'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
      'operation_id', v_scope.operation_id,
      'plan_sha256', v_scope.plan_sha256,
      'freeze_sha256', v_scope.freeze_sha256,
      'capture_request_sha256', v_receipt.capture_request_sha256,
      'capture_whole_scope_proof_sha256',
        v_receipt.whole_scope_proof_sha256,
      'source_guard_set_sha256', v_receipt.source_guard_set_sha256,
      'support_guard_set_sha256', v_receipt.support_snapshot_set_sha256,
      'target_guard_set_sha256', v_receipt.target_guard_set_sha256,
      'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
      'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
      'protected_closure_sha256', v_receipt.protected_closure_sha256,
      'policy_sha256', v_receipt.compatibility_policy->>'policy_sha256',
      'policy_approval_text_sha256',
        v_scope.policy_approval_text_sha256,
      'execution_approval_request_sha256',
        v_scope.execution_approval_request_sha256,
      'execution_approval_text_sha256', v_scope.approval_text_sha256,
      'execution_approval_identity_sha256',
        v_scope.approval_identity_sha256,
      'toolchain_evidence_sha256', v_scope.toolchain_evidence_sha256,
      'user_state_claim', v_scope.user_state_claim,
      'maximum_wrapper_invocations', 1,
      'maximum_process_posts', v_scope.process_count,
      'maximum_finalize_posts', 1,
      'maximum_cli_apply_spawns', 1,
      'approval_reusable', false,
      'automatic_retry', false,
      'preflight_request_sha256', v_scope.preflight_request_sha256,
      'scope_request_sha256', v_scope.scope_request_sha256,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'source_universe_count', 305,
      'mapping_count', v_scope.mapping_count,
      'process_count', v_scope.process_count,
      'rewrite_count', v_scope.rewrite_count,
      'hash_algorithm', 'restricted-safe-json-v2-sha256'
    );
  if v_core_result is not null then
    update private.command_audit_log
    set payload = v_expected_audit_payload
    where id = v_audit_id and actor_user_id = v_actor
      and command = v_command and target_table is null
    returning payload into v_audit_payload;
  end if;
  -- Fresh execution promotes the core's v1 row first; replay never mutates it.
  -- In both cases an exact reread/compare precedes whole-scope proof so that
  -- audit_current cannot deterministically reject a just-created scope.
  if v_audit_payload is distinct from v_expected_audit_payload then
    if v_core_result is not null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PREFLIGHT_V2_AUDIT_PROMOTION_FAILED';
    end if;
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PREFLIGHT_V2_AUDIT_DRIFT', 'status', 409,
      'message', 'The authoritative v2 scope audit is missing or drifted'
    );
  end if;
  v_live := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, true
  );
  if coalesce((v_live->>'ok')::boolean, false) is false then
    if v_core_result is not null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_PREFLIGHT_POST_SEAL_DRIFT';
    end if;
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
      'message', 'Sealed scope no longer matches live database state'
    );
  end if;
  if v_core_result is not null then
    v_permit_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
    insert into util.dataset_flow_identity_wrapper_invocations (
      scope_id, actor_user_id, approval_kind,
      approval_request_sha256, approval_text_sha256,
      approval_identity_sha256, admission_request_sha256,
      baseline_whole_scope_proof_sha256,
      token_sha256, maximum_process_posts, maximum_finalize_posts
    ) values (
      v_scope.id, v_actor, 'initial',
      v_scope.execution_approval_request_sha256,
      v_scope.approval_text_sha256,
      v_scope.approval_identity_sha256,
      v_scope.preflight_request_sha256,
      v_live->>'whole_scope_proof_sha256',
      private.dataset_flow_identity_permit_token_sha256_v1(v_permit_token),
      v_scope.process_count, 1
    ) returning id into v_invocation_id;
    v_execution_permit := jsonb_build_object(
      'schema_version', 'dataset-flow-identity-execution-permit.v1',
      'invocation_id', v_invocation_id,
      'generation', 0,
      'token', v_permit_token
    );
  end if;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-preflight-result.v2',
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'scope_id', v_scope.id,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_scope.status,
    'process_count', v_scope.process_count,
    'mapping_count', v_scope.mapping_count,
    'support_snapshot_count', v_receipt.support_count,
    'source_universe_count', 305,
    'rewrite_count', v_scope.rewrite_count,
    'next_ordinal', coalesce((
      select min(ledger.ordinal)
      from util.dataset_flow_identity_process_ledger as ledger
      where ledger.scope_id = v_scope.id and ledger.status = 'pending'
    ), v_scope.process_count + 1),
    'audit_id', v_audit_id::text,
    'replay', v_core_result is null,
    'execution_permit', v_execution_permit
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_PREFLIGHT_LOCK_BUSY', 'status', 409,
    'message', 'Scope seal could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_flow_identity_scope_preflight_guarded(p_request jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_read(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_scope_read(p_scope_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '90s'
    AS $$
declare
  v_command constant text := 'cmd_dataset_flow_identity_scope_read';
  v_actor uuid := auth.uid();
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_core jsonb;
  v_whole_result jsonb;
  v_whole jsonb;
  v_processes jsonb;
  v_status text;
  v_live_drift boolean;
  v_terminal_conflict boolean;
  v_compensation_required boolean;
  v_result jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  if p_scope_id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_READ_INVALID_REQUEST', 'status', 400,
      'message', 'Scope ID is required'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor;
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_NOT_FOUND', 'status', 404,
      'message', 'No actor-owned Step 3 scope exists'
    );
  end if;
  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null
    or v_receipt.receipt_proof_sha256
      is distinct from v_scope.receipt_proof_sha256 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing or drifted'
    );
  end if;
  v_core := private.dataset_flow_identity_scope_read_core_v1(p_scope_id);
  if v_core->>'code' in ('AUTH_REQUIRED', 'FLOW_IDENTITY_SCOPE_NOT_FOUND') then
    return v_core;
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, false
  );
  v_whole := v_whole_result->'whole_scope_proof';
  if v_whole is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT', 'status', 409,
      'message', 'Whole-scope proof could not be constructed'
    );
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'ordinal', ledger.ordinal,
    'id', ledger.process_id,
    'version', ledger.process_version,
    'status', ledger.status,
    'process_request_sha256', ledger.process_request_sha256,
    'process_intent_proof_sha256', ledger.process_intent_proof_sha256,
    'rewrite_count', ledger.rewrite_count,
    'audit_id', case when ledger.audit_id is null
      then null else ledger.audit_id::text end,
    'before_payload_sha256', ledger.before_payload_sha256,
    'before_exchange_set_sha256',
      ledger.manifest->>'before_exchange_set_sha256',
    'desired_payload_sha256', ledger.manifest->>'desired_payload_sha256',
    'desired_exchange_set_sha256',
      ledger.manifest->>'desired_exchange_set_sha256',
    'after_payload_sha256', ledger.after_payload_sha256,
    'after_exchange_set_sha256', ledger.after_exchange_set_sha256,
    'derivative_batch_id', ledger.derivative_batch_id,
    'derivative_request_id', child.id,
    'derivative_status', case when ledger.derivative_batch_id is null
      then null else coalesce(child.status, 'missing') end,
    'causal_terminal_proof', false,
    'completed_at', ledger.completed_at,
    'last_error', coalesce(ledger.last_error, child.last_error)
  ) order by ledger.ordinal), '[]'::jsonb)
  into v_processes
  from util.dataset_flow_identity_process_ledger as ledger
  left join util.dataset_derivative_rebuild_requests as child
    on child.actor_user_id = v_actor
    and child.batch_id = ledger.derivative_batch_id
    and child.target_table = 'processes'
    and child.target_id = ledger.process_id
    and child.target_version = ledger.process_version
  where ledger.scope_id = p_scope_id;
  v_terminal_conflict := v_scope.status in ('cancelled', 'failed');
  v_live_drift := v_terminal_conflict
    or coalesce((v_whole_result->>'ok')::boolean, false) is false;
  v_status := case when v_live_drift then 'live_drift'
    else v_core->>'status' end;
  v_compensation_required := not v_live_drift
    and coalesce((v_core->>'derivative_failed_count')::integer, 0) > 0;
  v_result := jsonb_build_object(
    'ok', v_status not in ('failed', 'live_drift')
      and not v_compensation_required,
    'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-status.v2',
    'scope_id', v_scope.id,
    'receipt_id', v_receipt.id,
    'receipt_proof_sha256', v_receipt.receipt_proof_sha256,
    'mapping_guard_set_sha256', v_receipt.mapping_guard_set_sha256,
    'process_intent_set_sha256', v_receipt.process_intent_set_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_status,
    'process_count', (v_core->>'process_count')::integer,
    'completed_process_count',
      (v_core->>'completed_process_count')::integer,
    'pending_process_count', (v_core->>'pending_process_count')::integer,
    'failed_process_count', (v_core->>'failed_process_count')::integer,
    'next_ordinal', (v_core->>'next_ordinal')::integer,
    'rewrite_count', (v_core->>'rewrite_count')::integer,
    'completed_rewrite_count',
      (v_core->>'completed_rewrite_count')::integer,
    'primary_complete', (v_core->>'primary_complete')::boolean,
    'cancellable', (v_core->>'cancellable')::boolean,
    'strict_continuation_required',
      (v_core->>'strict_continuation_required')::boolean,
    'primary_current', (v_whole->>'primary_current')::boolean,
    'live_guard_current',
      (v_whole->>'audit_current')::boolean
      and (v_whole->>'source_guards_current')::boolean
      and (v_whole->>'support_guards_current')::boolean
      and (v_whole->>'target_guards_current')::boolean
      and (v_whole->>'protected_closure_current')::boolean
      and (v_whole->>'occurrence_closure_current')::boolean,
    'derivatives_current', case when v_live_drift then false
      else (v_whole->>'derivatives_current')::boolean end,
    'derivative_pending_count',
      (v_core->>'derivative_pending_count')::integer,
    'derivative_failed_count',
      (v_core->>'derivative_failed_count')::integer,
    'derivative_set_proof', v_whole_result->'derivative_set_proof',
    'derivative_proof_set_sha256',
      v_whole_result #>> '{derivative_set_proof,proof_sha256}',
    'compensation_required', v_compensation_required,
    'automatic_retry', false,
    'compensation_targets', case when v_compensation_required
      then v_core->'compensation_targets' else '[]'::jsonb end,
    'protected_closure_current',
      (v_whole->>'protected_closure_current')::boolean,
    'protected_closure_proof', v_core->'protected_closure_proof',
    'processes', v_processes,
    'terminal_proof_sha256', case when v_status = 'completed'
      then v_scope.terminal_proof_sha256 else null end,
    'completed_at', case when v_status = 'completed'
      then v_scope.completed_at else null end,
    'whole_scope_proof', v_whole,
    'whole_scope_proof_sha256',
      v_whole_result->>'whole_scope_proof_sha256'
  );
  if v_live_drift then
    v_result := v_result || jsonb_build_object(
      'code', case when v_terminal_conflict
        then 'FLOW_IDENTITY_SCOPE_TERMINAL_CONFLICT'
        else 'FLOW_IDENTITY_PRIMARY_OR_GUARD_DRIFT' end
    );
  elsif v_compensation_required then
    v_result := v_result || jsonb_build_object(
      'code', 'FLOW_IDENTITY_DERIVATIVE_COMPENSATION_REQUIRED'
    );
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION api.cmd_dataset_flow_identity_scope_read(p_scope_id uuid) OWNER TO postgres;

--
-- Name: cmd_dataset_flow_identity_scope_recover_guarded(uuid, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_flow_identity_scope_recover_guarded(p_scope_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '180s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_scope_recover_guarded';
  v_actor uuid := auth.uid();
  v_actor_email text := lower(btrim(auth.email()));
  v_request jsonb;
  v_wire_request_sha256 text;
  v_approved_at timestamp with time zone;
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_receipt util.dataset_flow_identity_capture_receipts%rowtype;
  v_existing util.dataset_flow_identity_wrapper_invocations%rowtype;
  v_invocation_id uuid;
  v_whole_result jsonb;
  v_completed_count integer;
  v_next_ordinal integer;
  v_remaining_count integer;
  v_mode text;
  v_token text;
  v_audit_id bigint;
  v_audit_payload jsonb;
  v_expected_audit_payload jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;
  v_request := private.dataset_flow_identity_safe_json_v2(p_request);
  if p_scope_id is null or v_request is null
    or pg_column_size(v_request) > 65536
    or not private.dataset_flow_identity_exact_keys(v_request, array[
      'schema_version', 'request_id', 'approved_at_utc',
      'environment', 'project_ref', 'actor', 'target_visibility',
      'user_state_claim', 'operation_id', 'plan_sha256', 'freeze_sha256',
      'original_execution_approval_identity_sha256', 'scope_proof_sha256',
      'observed_scope_status', 'observed_completed_process_count',
      'observed_next_ordinal', 'observed_whole_scope_proof_sha256',
      'recovery_mode', 'recovery_reason', 'toolchain_evidence_sha256',
      'maximum_wrapper_invocations', 'maximum_process_posts',
      'maximum_finalize_posts', 'maximum_cli_apply_spawns',
      'approval_reusable', 'automatic_retry',
      'recovery_approval_request_sha256',
      'recovery_approval_text_sha256',
      'recovery_approval_identity_sha256'
    ])
    or v_request->>'schema_version'
      <> 'dataset-flow-identity-scope-recovery.v1'
    or v_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_request->>'target_visibility' <> 'owner_draft'
    or v_request->>'user_state_claim'
      <> 'authenticated_actor_state_100_plus_own_state_0'
    or not private.dataset_flow_identity_exact_keys(
      v_request->'actor', array['user_id', 'email']
    )
    or v_request #>> '{actor,user_id}' is distinct from v_actor::text
    or lower(btrim(v_request #>> '{actor,email}')) is distinct from v_actor_email
    or v_request->>'observed_scope_status' not in (
      'sealed', 'running', 'primary_complete', 'derivatives_pending'
    )
    or v_request->>'recovery_mode' not in (
      'resume_and_finalize', 'finalize_only'
    )
    or v_request->>'recovery_reason' not in (
      'wrapper_exited_without_permit', 'process_response_ambiguous',
      'process_domain_rejected', 'finalize_response_ambiguous',
      'derivatives_became_ready_after_wrapper_exit'
    )
    or jsonb_typeof(v_request->'observed_completed_process_count') <> 'number'
    or (v_request->>'observed_completed_process_count')::numeric < 0
    or (v_request->>'observed_completed_process_count')::numeric > 2147483647
    or jsonb_typeof(v_request->'observed_next_ordinal') <> 'number'
    or (v_request->>'observed_next_ordinal')::numeric < 1
    or (v_request->>'observed_next_ordinal')::numeric > 2147483647
    or (v_request->>'observed_next_ordinal')::numeric <>
      trunc((v_request->>'observed_next_ordinal')::numeric)
    or jsonb_typeof(v_request->'maximum_wrapper_invocations') <> 'number'
    or (v_request->>'maximum_wrapper_invocations')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_process_posts') <> 'number'
    or (v_request->>'maximum_process_posts')::numeric < 0
    or (v_request->>'maximum_process_posts')::numeric > 2147483647
    or jsonb_typeof(v_request->'maximum_finalize_posts') <> 'number'
    or (v_request->>'maximum_finalize_posts')::numeric <> 1
    or jsonb_typeof(v_request->'maximum_cli_apply_spawns') <> 'number'
    or (v_request->>'maximum_cli_apply_spawns')::numeric <> 1
    or v_request->'approval_reusable' is distinct from 'false'::jsonb
    or v_request->'automatic_retry' is distinct from 'false'::jsonb
    or exists (
      select 1 from unnest(array[
        'plan_sha256', 'freeze_sha256',
        'original_execution_approval_identity_sha256', 'scope_proof_sha256',
        'observed_whole_scope_proof_sha256', 'toolchain_evidence_sha256',
        'recovery_approval_request_sha256',
        'recovery_approval_text_sha256',
        'recovery_approval_identity_sha256'
      ]) as field(name)
      where v_request->>field.name !~ '^[a-f0-9]{64}$'
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_INVALID_REQUEST', 'status', 400,
      'message', 'Recovery approval request schema mismatch'
    );
  end if;
  begin
    v_approved_at := (v_request->>'approved_at_utc')::timestamp with time zone;
  exception when others then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_INVALID_APPROVAL_TIME', 'status', 400,
      'message', 'Recovery approval timestamp is invalid'
    );
  end;
  v_wire_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(v_request);
  if cardinality(array[
      v_request->>'recovery_approval_request_sha256',
      v_request->>'recovery_approval_text_sha256',
      v_request->>'recovery_approval_identity_sha256'
    ]) <> (
      select count(distinct value)
      from unnest(array[
        v_request->>'recovery_approval_request_sha256',
        v_request->>'recovery_approval_text_sha256',
        v_request->>'recovery_approval_identity_sha256'
      ]) as approval(value)
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_APPROVAL_HASH_MISMATCH', 'status', 409,
      'message', 'Recovery approval artifact hashes must be distinct'
    );
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity-actor:' || v_actor::text, 0
  ));
  if not pg_try_advisory_xact_lock(hashtextextended(
    'dataset-flow-identity:' || p_scope_id::text, 0
  )) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_SCOPE_BUSY', 'status', 409,
      'message', 'Another transaction owns this scope'
    );
  end if;
  select scope.* into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id and scope.actor_user_id = v_actor
  for update;
  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_NOT_FOUND', 'status', 404,
      'message', 'No actor-owned Step 3 scope exists'
    );
  end if;
  if v_scope.status in ('completed', 'failed', 'cancelled')
    or v_scope.scope_proof_sha256 is distinct from
      v_request->>'scope_proof_sha256'
    or v_scope.environment is distinct from v_request->>'environment'
    or v_scope.project_ref is distinct from v_request->>'project_ref'
    or v_scope.target_visibility is distinct from
      v_request->>'target_visibility'
    or v_scope.user_state_claim is distinct from
      v_request->>'user_state_claim'
    or v_scope.operation_id is distinct from v_request->>'operation_id'
    or v_scope.plan_sha256 is distinct from v_request->>'plan_sha256'
    or v_scope.freeze_sha256 is distinct from v_request->>'freeze_sha256'
    or v_scope.approval_identity_sha256 is distinct from
      v_request->>'original_execution_approval_identity_sha256'
    or v_approved_at < v_scope.sealed_at
    or exists (
      select 1 from unnest(array[
        v_request->>'recovery_approval_request_sha256',
        v_request->>'recovery_approval_text_sha256',
        v_request->>'recovery_approval_identity_sha256'
      ]) as recovery(value)
      where recovery.value = any(array[
        v_scope.policy_approval_text_sha256,
        v_scope.execution_approval_request_sha256,
        v_scope.approval_text_sha256,
        v_scope.approval_identity_sha256
      ])
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_SCOPE_BINDING_MISMATCH', 'status', 409,
      'message', 'Recovery approval does not bind this active scope'
    );
  end if;

  select invocation.* into v_existing
  from util.dataset_flow_identity_wrapper_invocations as invocation
  where invocation.actor_user_id = v_actor
    and array[
      v_request->>'recovery_approval_request_sha256',
      v_request->>'recovery_approval_text_sha256',
      v_request->>'recovery_approval_identity_sha256'
    ] && array[
      invocation.approval_request_sha256,
      invocation.approval_text_sha256,
      invocation.approval_identity_sha256
    ]
  order by invocation.admitted_at, invocation.id
  limit 1;
  if v_existing.id is not null then
    if v_existing.scope_id is distinct from v_scope.id
      or v_existing.approval_kind <> 'recovery'
      or v_existing.approval_request_sha256 is distinct from
        v_request->>'recovery_approval_request_sha256'
      or v_existing.approval_text_sha256 is distinct from
        v_request->>'recovery_approval_text_sha256'
      or v_existing.approval_identity_sha256 is distinct from
        v_request->>'recovery_approval_identity_sha256'
      or v_existing.admission_request_sha256 is distinct from
        v_wire_request_sha256
      or v_existing.baseline_whole_scope_proof_sha256 is distinct from
        v_request->>'observed_whole_scope_proof_sha256' then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_RECOVERY_APPROVAL_REUSE_MISMATCH',
        'status', 409,
        'message', 'Recovery approval was already consumed differently'
      );
    end if;
    select audit.id, audit.payload into v_audit_id, v_audit_payload
    from private.command_audit_log as audit
    where audit.command = v_command and audit.actor_user_id = v_actor
      and audit.target_table is null
      and audit.payload->>'scope_id' = v_scope.id::text
      and audit.payload->>'recovery_approval_identity_sha256'
        = v_existing.approval_identity_sha256;
    if v_audit_id is null then
      raise exception using errcode = 'P0001',
        message = 'FLOW_IDENTITY_RECOVERY_REPLAY_AUDIT_MISSING';
    end if;
    v_expected_audit_payload := jsonb_build_object(
      'record_type', 'scope_recovery_admission',
      'schema_version', 'dataset-flow-identity-scope-recovery.v1',
      'scope_id', v_scope.id,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'operation_id', v_scope.operation_id,
      'plan_sha256', v_scope.plan_sha256,
      'freeze_sha256', v_scope.freeze_sha256,
      'original_execution_approval_identity_sha256',
        v_scope.approval_identity_sha256,
      'observed_whole_scope_proof_sha256',
        v_request->>'observed_whole_scope_proof_sha256',
      'observed_scope_status', v_request->>'observed_scope_status',
      'observed_completed_process_count',
        (v_request->>'observed_completed_process_count')::integer,
      'observed_next_ordinal',
        (v_request->>'observed_next_ordinal')::integer,
      'recovery_mode', v_request->>'recovery_mode',
      'recovery_reason', v_request->>'recovery_reason',
      'toolchain_evidence_sha256', v_request->>'toolchain_evidence_sha256',
      'recovery_approval_request_sha256',
        v_request->>'recovery_approval_request_sha256',
      'recovery_approval_text_sha256',
        v_request->>'recovery_approval_text_sha256',
      'recovery_approval_identity_sha256',
        v_request->>'recovery_approval_identity_sha256',
      'recovery_wire_request_sha256', v_wire_request_sha256,
      'invocation_id', v_existing.id,
      'maximum_wrapper_invocations', 1,
      'maximum_process_posts',
        (v_request->>'maximum_process_posts')::integer,
      'maximum_finalize_posts', 1,
      'maximum_cli_apply_spawns', 1,
      'approval_reusable', false,
      'automatic_retry', false,
      'hash_algorithm', 'restricted-safe-json-v2-sha256'
    );
    if v_audit_payload is distinct from v_expected_audit_payload then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_RECOVERY_AUDIT_DRIFT', 'status', 409,
        'message', 'Authoritative recovery admission audit drifted'
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'command', v_command,
      'schema_version', 'dataset-flow-identity-scope-recovery-result.v1',
      'scope_id', v_scope.id,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'status', v_audit_payload->>'observed_scope_status',
      'completed_process_count',
        (v_audit_payload->>'observed_completed_process_count')::integer,
      'next_ordinal', (v_audit_payload->>'observed_next_ordinal')::integer,
      'whole_scope_proof_sha256',
        v_existing.baseline_whole_scope_proof_sha256,
      'recovery_wire_request_sha256',
        v_existing.admission_request_sha256,
      'recovery_approval_identity_sha256',
        v_existing.approval_identity_sha256,
      'invocation_id', v_existing.id,
      'audit_id', case when v_audit_id is null then null else v_audit_id::text end,
      'replay', true,
      'execution_permit', null
    );
  end if;

  select receipt.* into v_receipt
  from util.dataset_flow_identity_capture_receipts as receipt
  where receipt.id = v_scope.receipt_id and receipt.actor_user_id = v_actor;
  if v_receipt.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_RECEIPT_DRIFT', 'status', 409,
      'message', 'Scope receipt relation is missing'
    );
  end if;
  v_whole_result := private.dataset_flow_identity_whole_scope_proof_v2(
    v_actor, v_receipt.id, v_scope.id, true
  );
  if coalesce((v_whole_result->>'ok')::boolean, false) is false
    or v_whole_result->>'whole_scope_proof_sha256' is distinct from
      v_request->>'observed_whole_scope_proof_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_LIVE_PROOF_MISMATCH', 'status', 409,
      'message', 'Current whole-scope proof does not match the approval'
    );
  end if;
  select count(*) filter (where ledger.status = 'completed')::integer,
    coalesce(
      min(ledger.ordinal) filter (where ledger.status = 'pending')::integer,
      v_scope.process_count + 1
    )
  into v_completed_count, v_next_ordinal
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = v_scope.id;
  v_remaining_count := v_scope.process_count - v_completed_count;
  v_mode := case when v_remaining_count = 0
    then 'finalize_only' else 'resume_and_finalize' end;
  if v_scope.status is distinct from v_request->>'observed_scope_status'
    or v_completed_count is distinct from
      (v_request->>'observed_completed_process_count')::integer
    or (v_request->>'observed_next_ordinal')::integer <> v_next_ordinal
    or v_mode is distinct from v_request->>'recovery_mode'
    or v_remaining_count is distinct from
      (v_request->>'maximum_process_posts')::integer then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_RECOVERY_PROGRESS_MISMATCH', 'status', 409,
      'message', 'Recovery approval does not match current durable progress'
    );
  end if;

  update util.dataset_flow_identity_wrapper_invocations
  set status = 'superseded', generation = generation + 1,
    token_sha256 = private.dataset_flow_identity_permit_token_sha256_v1(
      pg_catalog.encode(extensions.gen_random_bytes(32), 'hex')
    ),
    updated_at = clock_timestamp(), closed_at = clock_timestamp()
  where scope_id = v_scope.id and status = 'active';
  v_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  insert into util.dataset_flow_identity_wrapper_invocations (
    scope_id, actor_user_id, approval_kind,
    approval_request_sha256, approval_text_sha256,
    approval_identity_sha256, admission_request_sha256,
    baseline_whole_scope_proof_sha256,
    token_sha256, maximum_process_posts, maximum_finalize_posts
  ) values (
    v_scope.id, v_actor, 'recovery',
    v_request->>'recovery_approval_request_sha256',
    v_request->>'recovery_approval_text_sha256',
    v_request->>'recovery_approval_identity_sha256',
    v_wire_request_sha256,
    v_request->>'observed_whole_scope_proof_sha256',
    private.dataset_flow_identity_permit_token_sha256_v1(v_token),
    v_remaining_count, 1
  ) returning id into v_invocation_id;
  v_audit_payload := jsonb_build_object(
    'record_type', 'scope_recovery_admission',
    'schema_version', 'dataset-flow-identity-scope-recovery.v1',
    'scope_id', v_scope.id,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'operation_id', v_scope.operation_id,
    'plan_sha256', v_scope.plan_sha256,
    'freeze_sha256', v_scope.freeze_sha256,
    'original_execution_approval_identity_sha256',
      v_scope.approval_identity_sha256,
    'observed_whole_scope_proof_sha256',
      v_request->>'observed_whole_scope_proof_sha256',
    'observed_scope_status', v_scope.status,
    'observed_completed_process_count', v_completed_count,
    'observed_next_ordinal', v_next_ordinal,
    'recovery_mode', v_mode,
    'recovery_reason', v_request->>'recovery_reason',
    'toolchain_evidence_sha256', v_request->>'toolchain_evidence_sha256',
    'recovery_approval_request_sha256',
      v_request->>'recovery_approval_request_sha256',
    'recovery_approval_text_sha256',
      v_request->>'recovery_approval_text_sha256',
    'recovery_approval_identity_sha256',
      v_request->>'recovery_approval_identity_sha256',
    'recovery_wire_request_sha256', v_wire_request_sha256,
    'invocation_id', v_invocation_id,
    'maximum_wrapper_invocations', 1,
    'maximum_process_posts', v_remaining_count,
    'maximum_finalize_posts', 1,
    'maximum_cli_apply_spawns', 1,
    'approval_reusable', false,
    'automatic_retry', false,
    'hash_algorithm', 'restricted-safe-json-v2-sha256'
  );
  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    v_command, v_actor, null, null, null, v_audit_payload
  ) returning id into v_audit_id;
  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', 'dataset-flow-identity-scope-recovery-result.v1',
    'scope_id', v_scope.id,
    'scope_proof_sha256', v_scope.scope_proof_sha256,
    'status', v_scope.status,
    'completed_process_count', v_completed_count,
    'next_ordinal', v_next_ordinal,
    'whole_scope_proof_sha256',
      v_request->>'observed_whole_scope_proof_sha256',
    'recovery_wire_request_sha256', v_wire_request_sha256,
    'recovery_approval_identity_sha256',
      v_request->>'recovery_approval_identity_sha256',
    'invocation_id', v_invocation_id,
    'audit_id', v_audit_id::text,
    'replay', false,
    'execution_permit', jsonb_build_object(
      'schema_version', 'dataset-flow-identity-execution-permit.v1',
      'invocation_id', v_invocation_id,
      'generation', 0,
      'token', v_token
    )
  );
exception when lock_not_available then
  return jsonb_build_object(
    'ok', false, 'command', v_command,
    'code', 'FLOW_IDENTITY_RECOVERY_LOCK_BUSY', 'status', 409,
    'message', 'Recovery could not acquire its deterministic fence'
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_flow_identity_scope_recover_guarded(p_scope_id uuid, p_request jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_publish(text, uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_publish(p_table text, p_id uuid, p_version text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_root jsonb;
  v_assertion jsonb;
begin
  if v_actor is null
    or p_table not in ('processes', 'lifecyclemodels') then
    return private.cmd_dataset_publish_issue304_legacy(
      p_table,
      p_id,
      p_version,
      p_audit
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('review-publication-lifecycle-closure', 0)
  );

  v_root := api.cmd_review_get_dataset_row(
    p_table,
    p_id,
    p_version,
    true
  );

  if v_root is null
    or nullif(v_root->>'user_id', '')::uuid is distinct from v_actor
    or coalesce((v_root->>'state_code')::integer, 0) >= 100 then
    return private.cmd_dataset_publish_issue304_legacy(
      p_table,
      p_id,
      p_version,
      p_audit
    );
  end if;

  if p_table = 'processes' then
    lock table public.lifecyclemodels in share row exclusive mode;
  end if;

  v_assertion := private.cmd_review_assert_lifecycle_closure(
    jsonb_build_array(jsonb_build_object(
      'table', p_table,
      'id', p_id,
      'version', p_version
    )),
    'publish',
    v_actor
  );

  if v_assertion is not null then
    return v_assertion;
  end if;

  return private.cmd_dataset_publish_issue304_legacy(
    p_table,
    p_id,
    p_version,
    p_audit
  );
end;
$$;


ALTER FUNCTION api.cmd_dataset_publish(p_table text, p_id uuid, p_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_save_draft(text, uuid, text, jsonb, uuid, boolean, jsonb, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_save_draft(p_table text, p_id uuid, p_version text, p_json_ordered jsonb, p_model_id uuid DEFAULT NULL::uuid, p_rule_verification boolean DEFAULT NULL::boolean, p_audit jsonb DEFAULT '{}'::jsonb, p_model_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_model_version text := nullif(btrim(coalesce(p_model_version, '')), '');
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  if p_json_ordered is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'JSON_ORDERED_REQUIRED',
      'status', 400,
      'message', 'jsonOrdered is required'
    );
  end if;

  if p_table <> 'processes' and p_model_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_NOT_ALLOWED',
      'status', 400,
      'message', 'modelId is only allowed for process dataset drafts'
    );
  end if;

  if p_table <> 'processes' and v_model_version is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_VERSION_NOT_ALLOWED',
      'status', 400,
      'message', 'modelVersion is only allowed for process dataset drafts'
    );
  end if;

  if v_model_version is not null and p_model_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MODEL_ID_REQUIRED_FOR_MODEL_VERSION',
      'status', 400,
      'message', 'modelId is required when modelVersion is provided'
    );
  end if;

  if v_model_version is not null
     and v_model_version !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_MODEL_VERSION',
      'status', 400,
      'message', 'modelVersion must use NN.NN.NNN format'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can save draft changes'
    );
  end if;

  if v_state_code >= 100 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_ALREADY_PUBLISHED',
      'status', 403,
      'message', 'Published data cannot be edited through draft save',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  if v_state_code >= 20 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 403,
      'message', 'Data is under review and cannot be modified',
      'details', jsonb_build_object(
        'state_code', 20,
        'review_state_code', v_state_code
      )
    );
  end if;

  if p_table = 'processes' then
    execute format(
      'update public.%I as t
          set json_ordered = $1::json,
              model_id = coalesce($2, t.model_id),
              model_version = case
                when $2 is null then t.model_version
                when $3 is not null then $3
                when $2 is distinct from t.model_id then null
                else t.model_version
              end,
              rule_verification = $4,
              modified_at = now()
        where t.id = $5
          and t.version = $6
      returning to_jsonb(t)',
      p_table
    )
      into v_updated_row
      using p_json_ordered, p_model_id, v_model_version, p_rule_verification, p_id, p_version;
  else
    execute format(
      'update public.%I as t
          set json_ordered = $1::json,
              rule_verification = $2,
              modified_at = now()
        where t.id = $3
          and t.version = $4
      returning to_jsonb(t)',
      p_table
    )
      into v_updated_row
      using p_json_ordered, p_rule_verification, p_id, p_version;
  end if;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_save_draft',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_save_draft(p_table text, p_id uuid, p_version text, p_json_ordered jsonb, p_model_id uuid, p_rule_verification boolean, p_audit jsonb, p_model_version text) OWNER TO postgres;

--
-- Name: cmd_dataset_withdraw(text, uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in ('sources', 'flows', 'processes') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Only sources, flows, and processes can be withdrawn'
    );
  end if;

  if v_reason = '' or length(v_reason) > 4000 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_WITHDRAW_REASON',
      'status', 400,
      'message', 'A non-empty withdrawal reason of at most 4000 characters is required'
    );
  end if;

  if jsonb_typeof(coalesce(p_audit, '{}'::jsonb)) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_AUDIT_PAYLOAD',
      'status', 400,
      'message', 'Audit payload must be a JSON object'
    );
  end if;

  execute format(
    'select to_jsonb(t)
       from public.%I as t
      where t.id = $1
        and t.version = $2
      for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can withdraw this dataset'
    );
  end if;

  if v_state_code = 0 then
    return jsonb_build_object(
      'ok', true,
      'changed', false,
      'code', 'DATASET_ALREADY_DRAFT',
      'data', v_current_row
    );
  end if;

  if v_state_code < 100 or v_state_code >= 200 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_WITHDRAW_REQUIRES_PUBLISHED_STATE',
      'status', 403,
      'message', 'Only public datasets in state 100 through 199 can be withdrawn',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  execute format(
    'update public.%I as t
        set state_code = 0,
            rule_verification = false,
            modified_at = now()
      where t.id = $1
        and t.version = $2
    returning to_jsonb(t)',
    p_table
  )
    into v_updated_row
    using p_id, p_version;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_withdraw',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
      || jsonb_build_object(
        'reason', v_reason,
        'from_state_code', v_state_code,
        'to_state_code', 0
      )
  );

  return jsonb_build_object(
    'ok', true,
    'changed', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION api.cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_dataset_withdraw(p_table text, p_id uuid, p_version text, p_reason text, p_audit jsonb) IS 'Owner-authenticated, audited withdrawal of public source, flow, or process datasets to draft state without changing dataset JSON.';


--
-- Name: cmd_lca_release_approve(uuid, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lca_release_approve(p_release_run_id uuid, p_publish_plan_hash text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_run private.lca_release_runs%rowtype;
  v_approval private.lca_release_approvals%rowtype;
  v_now timestamptz := clock_timestamp();
  v_expires_at timestamptz;
  v_approval_hash text;
begin
  if v_actor is null then
    return private.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not private.lca_release_is_manager() then
    return private.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$' then
    return private.lca_release_error('invalid_publish_plan_hash', 400, 'publishPlanHash must be SHA-256');
  end if;

  select * into v_run
  from private.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return private.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;
  if v_run.publish_plan_hash <> p_publish_plan_hash then
    return private.lca_release_error('publish_plan_hash_mismatch', 409, 'Approval must bind the exact immutable publish plan');
  end if;
  if v_run.status not in ('ready_for_approval', 'approved') then
    return private.lca_release_error('release_not_ready_for_approval', 409, 'Release run is not ready for approval');
  end if;
  if v_run.release_manifest_hash is null
     or (select count(*) from private.lca_release_artifacts where release_run_id = v_run.id) <> 4 then
    return private.lca_release_error('release_artifacts_incomplete', 409, 'Four verified release artifacts are required before approval');
  end if;

  update private.lca_release_approvals
  set status = 'expired'
  where release_run_id = v_run.id
    and status = 'approved'
    and expires_at <= v_now;

  select * into v_approval
  from private.lca_release_approvals
  where release_run_id = v_run.id
    and status = 'approved'
  for update;

  if v_approval.id is not null then
    if v_approval.publish_plan_hash = p_publish_plan_hash then
      return jsonb_build_object(
        'ok', true,
        'reused', true,
        'data', jsonb_build_object(
          'approvalId', v_approval.id,
          'approvalHash', v_approval.approval_hash,
          'publishPlanHash', v_approval.publish_plan_hash,
          'approvedBy', v_approval.approved_by,
          'approvedAt', v_approval.approved_at,
          'expiresAt', v_approval.expires_at
        )
      );
    end if;
    return private.lca_release_error('active_approval_conflict', 409, 'An active approval exists for different content');
  end if;

  v_expires_at := coalesce(p_expires_at, v_now + interval '24 hours');
  if v_expires_at <= v_now then
    return private.lca_release_error('approval_expiry_invalid', 400, 'Approval expiry must be in the future');
  end if;
  v_approval_hash := encode(
    extensions.digest(
      convert_to(
        concat_ws('|', v_run.id::text, p_publish_plan_hash, v_actor::text, v_now::text),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  insert into private.lca_release_approvals (
    release_run_id, publish_plan_hash, approval_hash, status,
    approved_by, approved_at, expires_at, reason, audit_correlation
  ) values (
    v_run.id, p_publish_plan_hash, v_approval_hash, 'approved',
    v_actor, v_now, v_expires_at, nullif(trim(coalesce(p_reason, '')), ''),
    coalesce(p_audit, '{}'::jsonb)
  )
  returning * into v_approval;

  update private.lca_release_runs
  set status = 'approved', approved_at = v_now, updated_at = v_now
  where id = v_run.id;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_approve', v_actor, 'lca_release_approvals', v_approval.id,
    v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'releaseRunId', v_run.id,
      'publishPlanHash', p_publish_plan_hash,
      'approvalHash', v_approval_hash,
      'expiresAt', v_expires_at
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'approvalId', v_approval.id,
      'approvalHash', v_approval.approval_hash,
      'publishPlanHash', v_approval.publish_plan_hash,
      'approvedBy', v_approval.approved_by,
      'approvedAt', v_approval.approved_at,
      'expiresAt', v_approval.expires_at
    )
  );
end;
$_$;


ALTER FUNCTION api.cmd_lca_release_approve(p_release_run_id uuid, p_publish_plan_hash text, p_expires_at timestamp with time zone, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_prepare(uuid, text, text, text, jsonb, text, text, jsonb, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lca_release_prepare(p_release_run_id uuid, p_release_version text, p_selection_manifest_hash text, p_input_manifest_hash text, p_calculation_bundle_ref jsonb, p_calculation_bundle_hash text, p_profile_lock_hash text, p_publish_plan jsonb, p_publish_plan_hash text, p_idempotency_key text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_existing private.lca_release_runs%rowtype;
  v_request_hash text;
  v_artifact_set_hash text;
  v_pair_count integer;
begin
  if v_actor is null then
    return private.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not private.lca_release_is_manager() then
    return private.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if p_release_run_id is null then
    return private.lca_release_error('release_run_id_required', 400, 'releaseRunId is required');
  end if;
  if coalesce(p_release_version, '') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return private.lca_release_error('invalid_release_version', 400, 'releaseVersion must use NN.NN.NNN');
  end if;
  if coalesce(p_selection_manifest_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_input_manifest_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_calculation_bundle_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_profile_lock_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$' then
    return private.lca_release_error('invalid_hash', 400, 'Release hashes must be lowercase SHA-256 values');
  end if;
  if jsonb_typeof(coalesce(p_calculation_bundle_ref, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_publish_plan, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_audit, 'null'::jsonb)) <> 'object' then
    return private.lca_release_error('invalid_payload', 400, 'Bundle ref, publish plan, and audit must be JSON objects');
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    return private.lca_release_error('idempotency_key_required', 400, 'idempotencyKey is required');
  end if;
  if p_publish_plan->>'schemaVersion' is distinct from 'tiangong.release.publish-plan.v1'
     or p_publish_plan->>'releaseRunId' is distinct from p_release_run_id::text
     or p_publish_plan->>'releaseVersion' is distinct from p_release_version
     or p_publish_plan->>'calculationBundleHash' is distinct from p_calculation_bundle_hash
     or p_publish_plan->>'profileLockHash' is distinct from p_profile_lock_hash
     or p_publish_plan->>'planHash' is distinct from p_publish_plan_hash then
    return private.lca_release_error('publish_plan_mismatch', 400, 'Publish plan identity or exact hashes do not match the request');
  end if;
  v_artifact_set_hash := p_publish_plan->>'artifactSetHash';
  if coalesce(v_artifact_set_hash, '') !~ '^[0-9a-f]{64}$' then
    return private.lca_release_error('invalid_artifact_set_hash', 400, 'Publish plan artifactSetHash must be SHA-256');
  end if;
  if jsonb_typeof(p_publish_plan->'datasets') is distinct from 'array'
     or jsonb_array_length(p_publish_plan->'datasets') = 0
     or jsonb_typeof(p_publish_plan->'packages') is distinct from 'array'
     or jsonb_array_length(p_publish_plan->'packages') <> 4 then
    return private.lca_release_error('publish_plan_incomplete', 400, 'Publish plan must contain datasets and exactly four packages');
  end if;

  select count(distinct (package.value->>'profileId') || ':' || (package.value->>'format'))
    into v_pair_count
  from jsonb_array_elements(p_publish_plan->'packages') as package(value)
  where package.value->>'profileId' in (
          'unit-process-full-closure.v1',
          'standalone-lifecyclemodel-result-full-closure.v1'
        )
    and package.value->>'format' in ('tidas', 'ilcd')
    and package.value->>'sha256' ~ '^[0-9a-f]{64}$';

  if v_pair_count <> 4 then
    return private.lca_release_error('publish_plan_profiles_invalid', 400, 'Publish plan must contain both profiles in TIDAS and ILCD formats');
  end if;

  v_request_hash := encode(
    extensions.digest(
      convert_to(
        concat_ws(
          '|', p_release_run_id::text, p_release_version,
          p_selection_manifest_hash, p_input_manifest_hash,
          p_calculation_bundle_hash, p_profile_lock_hash,
          p_publish_plan_hash, v_artifact_set_hash
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  select * into v_existing
  from private.lca_release_runs
  where id = p_release_run_id
     or (created_by = v_actor and idempotency_key = trim(p_idempotency_key))
  order by (id = p_release_run_id) desc
  limit 1
  for update;

  if v_existing.id is not null then
    if v_existing.id = p_release_run_id
       and v_existing.created_by = v_actor
       and v_existing.request_hash = v_request_hash
       and v_existing.calculation_bundle_ref = p_calculation_bundle_ref
       and v_existing.publish_plan = p_publish_plan then
      return jsonb_build_object(
        'ok', true,
        'reused', true,
        'data', jsonb_build_object(
          'releaseRunId', v_existing.id,
          'releaseVersion', v_existing.release_version,
          'status', v_existing.status,
          'publishPlanHash', v_existing.publish_plan_hash
        )
      );
    end if;
    return private.lca_release_error('release_prepare_conflict', 409, 'Release run id or idempotency key is already bound to different content');
  end if;

  insert into private.lca_release_runs (
    id, release_version, scope_mode, selection_manifest_hash,
    input_manifest_hash, calculation_bundle_hash, calculation_bundle_ref,
    profile_lock_hash, publish_plan_hash, publish_plan, artifact_set_hash,
    status, idempotency_key, request_hash, created_by
  ) values (
    p_release_run_id, p_release_version, 'global_eligible', p_selection_manifest_hash,
    p_input_manifest_hash, p_calculation_bundle_hash, p_calculation_bundle_ref,
    p_profile_lock_hash, p_publish_plan_hash, p_publish_plan, v_artifact_set_hash,
    'prepared', trim(p_idempotency_key), v_request_hash, v_actor
  );

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_prepare', v_actor, 'lca_release_runs', p_release_run_id,
    p_release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'publishPlanHash', p_publish_plan_hash,
      'calculationBundleHash', p_calculation_bundle_hash,
      'inputManifestHash', p_input_manifest_hash,
      'artifactSetHash', v_artifact_set_hash
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'releaseRunId', p_release_run_id,
      'releaseVersion', p_release_version,
      'status', 'prepared',
      'publishPlanHash', p_publish_plan_hash
    )
  );
exception
  when unique_violation then
    return private.lca_release_error('release_prepare_conflict', 409, 'Release version, run id, or idempotency key already exists');
end;
$_$;


ALTER FUNCTION api.cmd_lca_release_prepare(p_release_run_id uuid, p_release_version text, p_selection_manifest_hash text, p_input_manifest_hash text, p_calculation_bundle_ref jsonb, p_calculation_bundle_hash text, p_profile_lock_hash text, p_publish_plan jsonb, p_publish_plan_hash text, p_idempotency_key text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_publish(uuid, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lca_release_publish(p_release_run_id uuid, p_approval_id uuid, p_approval_hash text, p_publish_plan_hash text, p_idempotency_key text, p_credential_fingerprint text, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_run private.lca_release_runs%rowtype;
  v_approval private.lca_release_approvals%rowtype;
  v_existing private.lca_release_publications%rowtype;
  v_publication private.lca_release_publications%rowtype;
  v_previous private.lca_release_publications%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then
    return private.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not private.lca_release_is_manager() then
    return private.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if coalesce(p_approval_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_credential_fingerprint, '') !~ '^[0-9a-f]{64}$' then
    return private.lca_release_error('invalid_publish_hash', 400, 'Approval, plan, and credential fingerprint must be lowercase SHA-256 values');
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    return private.lca_release_error('idempotency_key_required', 400, 'idempotencyKey is required');
  end if;

  select * into v_run
  from private.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return private.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;

  select * into v_existing
  from private.lca_release_publications
  where release_run_id = v_run.id
     or (executed_by = v_actor and idempotency_key = trim(p_idempotency_key))
  order by (release_run_id = v_run.id) desc
  limit 1;

  if v_existing.id is not null then
    if v_existing.release_run_id = v_run.id
       and v_existing.executed_by = v_actor
       and v_existing.approval_id = p_approval_id
       and v_existing.approval_hash = p_approval_hash
       and v_existing.publish_plan_hash = p_publish_plan_hash
       and v_existing.idempotency_key = trim(p_idempotency_key)
       and v_existing.credential_fingerprint = p_credential_fingerprint then
      return jsonb_build_object(
        'ok', true,
        'reused', true,
        'data', jsonb_build_object(
          'publicationId', v_existing.id,
          'releaseRunId', v_existing.release_run_id,
          'releaseVersion', v_existing.release_version,
          'status', v_existing.status,
          'publishedAt', v_existing.published_at
        )
      );
    end if;
    return private.lca_release_error('publish_idempotency_conflict', 409, 'Publish idempotency key is bound to different content');
  end if;

  if v_run.status <> 'approved' then
    return private.lca_release_error('release_not_approved', 409, 'Release run must have a durable active approval before publish');
  end if;
  if v_run.publish_plan_hash <> p_publish_plan_hash then
    return private.lca_release_error('publish_plan_hash_mismatch', 409, 'Publish plan hash differs from the prepared release');
  end if;

  select * into v_approval
  from private.lca_release_approvals
  where id = p_approval_id
    and release_run_id = v_run.id
  for update;

  if v_approval.id is null
     or v_approval.status <> 'approved'
     or v_approval.publish_plan_hash <> p_publish_plan_hash
     or v_approval.approval_hash <> p_approval_hash
     or v_approval.expires_at <= v_now then
    return private.lca_release_error('approval_invalid', 409, 'Approval is missing, expired, consumed, or does not bind the exact plan');
  end if;
  if v_run.release_manifest_hash is null
     or v_run.release_manifest->>'publishPlanHash' <> p_publish_plan_hash
     or v_run.release_manifest->>'artifactSetHash' <> v_run.artifact_set_hash
     or (select count(*) from private.lca_release_artifacts where release_run_id = v_run.id and verified_at is not null) <> 4 then
    return private.lca_release_error('release_artifacts_incomplete', 409, 'Verified manifest and all four artifacts are required before publish');
  end if;

  lock table private.lca_release_publications in exclusive mode;

  select * into v_previous
  from private.lca_release_publications
  where publication_series_key = 'global'
    and publication_channel = 'public'
    and visibility_scope = 'public'
    and is_current = true
  for update;

  if v_previous.id is not null then
    update private.lca_release_publications
    set is_current = false,
        status = 'superseded',
        superseded_at = v_now,
        updated_at = v_now
    where id = v_previous.id;
  end if;

  insert into private.lca_release_publications (
    release_run_id, release_version, publication_series_key,
    publication_channel, visibility_scope, status, is_current,
    approval_id, approval_hash, publish_plan_hash, release_manifest_hash,
    artifact_set_hash, approved_by, executed_by, credential_fingerprint,
    idempotency_key, published_at, reason
  ) values (
    v_run.id, v_run.release_version, 'global', 'public', 'public', 'current', true,
    v_approval.id, v_approval.approval_hash, v_run.publish_plan_hash,
    v_run.release_manifest_hash, v_run.artifact_set_hash,
    v_approval.approved_by, v_actor, p_credential_fingerprint,
    trim(p_idempotency_key), v_now, nullif(trim(coalesce(p_reason, '')), '')
  )
  returning * into v_publication;

  if v_previous.id is not null then
    update private.lca_release_publications
    set superseded_by = v_publication.id,
        updated_at = v_now
    where id = v_previous.id;
  end if;

  update private.lca_release_approvals
  set status = 'consumed', consumed_by = v_actor, consumed_at = v_now
  where id = v_approval.id;

  update private.lca_release_artifacts
  set pinned = true, published_at = v_now
  where release_run_id = v_run.id;

  update private.lca_release_runs
  set status = 'published', published_at = v_now, updated_at = v_now
  where id = v_run.id;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_publish', v_actor, 'lca_release_publications', v_publication.id,
    v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'releaseRunId', v_run.id,
      'approvalId', v_approval.id,
      'approvalHash', v_approval.approval_hash,
      'publishPlanHash', v_run.publish_plan_hash,
      'releaseManifestHash', v_run.release_manifest_hash,
      'artifactSetHash', v_run.artifact_set_hash,
      'approvedBy', v_approval.approved_by,
      'executedBy', v_actor,
      'credentialFingerprint', p_credential_fingerprint,
      'previousPublicationId', v_previous.id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'publicationId', v_publication.id,
      'releaseRunId', v_run.id,
      'releaseVersion', v_run.release_version,
      'status', 'current',
      'approvedBy', v_approval.approved_by,
      'executedBy', v_actor,
      'publishedAt', v_now
    )
  );
exception
  when unique_violation then
    return private.lca_release_error('publication_conflict', 409, 'Release version or publish idempotency key already has a publication');
end;
$_$;


ALTER FUNCTION api.cmd_lca_release_publish(p_release_run_id uuid, p_approval_id uuid, p_approval_hash text, p_publish_plan_hash text, p_idempotency_key text, p_credential_fingerprint text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_readback_verify(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lca_release_readback_verify(p_release_run_id uuid, p_release_manifest_hash text, p_artifact_hashes jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_run private.lca_release_runs%rowtype;
  v_mismatch_count integer;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then
    return private.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not private.lca_release_is_manager() then
    return private.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if jsonb_typeof(coalesce(p_artifact_hashes, 'null'::jsonb)) <> 'array' then
    return private.lca_release_error('invalid_readback_payload', 400, 'artifactHashes must be a JSON array');
  end if;

  select * into v_run
  from private.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return private.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;
  if v_run.status not in ('published', 'readback_verified') then
    return private.lca_release_error('release_not_published', 409, 'Release must be published before readback verification');
  end if;
  if v_run.release_manifest_hash <> p_release_manifest_hash then
    return private.lca_release_error('readback_manifest_hash_mismatch', 409, 'Readback release manifest hash differs from the published value');
  end if;
  if jsonb_array_length(p_artifact_hashes) <> 4 then
    return private.lca_release_error('readback_artifacts_incomplete', 409, 'Readback must verify all four release artifacts');
  end if;

  with expected as (
    select id::text as artifact_id, sha256
    from private.lca_release_artifacts
    where release_run_id = v_run.id
  ),
  observed as (
    select value->>'artifactId' as artifact_id, value->>'sha256' as sha256
    from jsonb_array_elements(p_artifact_hashes)
  )
  select count(*) into v_mismatch_count
  from expected
  full join observed using (artifact_id)
  where expected.artifact_id is null
     or observed.artifact_id is null
     or expected.sha256 is distinct from observed.sha256;

  if v_mismatch_count <> 0 then
    return private.lca_release_error('readback_artifact_hash_mismatch', 409, 'Readback artifact hashes differ from published immutable refs');
  end if;

  update private.lca_release_runs
  set status = 'readback_verified',
      readback_verified_at = coalesce(readback_verified_at, v_now),
      readback_receipt = jsonb_build_object(
        'releaseManifestHash', p_release_manifest_hash,
        'artifactHashes', p_artifact_hashes,
        'verifiedBy', v_actor,
        'verifiedAt', v_now
      ),
      updated_at = v_now
  where id = v_run.id;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_readback_verify', v_actor, 'lca_release_runs', v_run.id,
    v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'releaseManifestHash', p_release_manifest_hash,
      'artifactCount', jsonb_array_length(p_artifact_hashes)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'releaseRunId', v_run.id,
      'status', 'readback_verified',
      'releaseManifestHash', p_release_manifest_hash,
      'verifiedAt', v_now
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_lca_release_readback_verify(p_release_run_id uuid, p_release_manifest_hash text, p_artifact_hashes jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lca_release_unpublish(uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lca_release_unpublish(p_publication_id uuid, p_reason text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_publication private.lca_release_publications%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then
    return private.lca_release_error('auth_required', 401, 'Authentication required');
  end if;
  if not private.lca_release_is_manager() then
    return private.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    return private.lca_release_error('reason_required', 400, 'Unpublish requires an audit reason');
  end if;

  select * into v_publication
  from private.lca_release_publications
  where id = p_publication_id
  for update;

  if v_publication.id is null then
    return private.lca_release_error('publication_not_found', 404, 'Publication not found');
  end if;
  if v_publication.status = 'unpublished' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data', jsonb_build_object('publicationId', v_publication.id, 'status', 'unpublished')
    );
  end if;
  if not v_publication.is_current or v_publication.status <> 'current' then
    return private.lca_release_error('publication_not_current', 409, 'Only the current publication can be unpublished');
  end if;

  update private.lca_release_publications
  set status = 'unpublished', is_current = false, unpublished_by = v_actor,
      unpublished_at = v_now, reason = p_reason, updated_at = v_now
  where id = v_publication.id;

  update private.lca_release_runs
  set status = 'unpublished', updated_at = v_now
  where id = v_publication.release_run_id;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_unpublish', v_actor, 'lca_release_publications',
    v_publication.id, v_publication.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object('reason', p_reason)
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object('publicationId', v_publication.id, 'status', 'unpublished')
  );
end;
$$;


ALTER FUNCTION api.cmd_lca_release_unpublish(p_publication_id uuid, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request(text, jsonb, text, text, jsonb, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_result_build_request(p_name text, p_processes jsonb DEFAULT NULL::jsonb, p_coverage_mode text DEFAULT 'global_eligible'::text, p_default_impact_category text DEFAULT NULL::text, p_lcia_method_set jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
begin
  if coalesce((select require_certificate_for_builds from private.lcia_scope_closure_config where singleton), false) then
    return api.lcia_scope_closure_error('closure_check_required', 409, 'A valid scope-closure certificate is required');
  end if;
  return private.cmd_lcia_result_build_request_legacy(p_name, p_processes, p_coverage_mode, p_default_impact_category, p_lcia_method_set, p_idempotency_key, p_audit);
end;
$$;


ALTER FUNCTION api.cmd_lcia_result_build_request(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_v2(text, jsonb, text, text, jsonb, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_result_build_request_v2(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_check private.lcia_scope_closure_checks%rowtype;
begin
  if v_actor is null then
    return api.lcia_scope_closure_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  select * into v_check
  from private.lcia_scope_closure_checks
  where id = p_closure_check_id
    and requested_by = v_actor;
  if v_check.id is null then
    return api.lcia_scope_closure_error(
      'closure_check_not_found', 404, 'Closure check not found'
    );
  end if;
  if v_check.valid_until <= now()
     or exists (
       select 1
       from private.worker_job_artifacts artifact
       where artifact.id in (
         v_check.report_artifact_id,
         v_check.complete_machine_result_artifact_id,
         v_check.closure_bundle_artifact_id
       )
         and (
           artifact.lifecycle_state in ('expired', 'deleted')
           or artifact.expires_at <= now()
         )
     ) then
    return api.lcia_scope_closure_error(
      'closure_certificate_expired', 410, 'Closure certificate evidence has expired'
    );
  end if;
  if not private.lcia_scope_closure_evidence_usable(v_check) then
    return api.lcia_scope_closure_error(
      'closure_check_not_usable', 409, 'Closure certificate evidence is not usable'
    );
  end if;

  return private.cmd_lcia_result_build_request_v2_without_expiry(
    p_name,
    p_processes,
    p_coverage_mode,
    p_default_impact_category,
    p_lcia_method_set,
    p_idempotency_key,
    p_closure_check_id,
    p_requested_scope_hash,
    p_policy_fingerprint,
    p_audit
  );
end;
$$;


ALTER FUNCTION api.cmd_lcia_result_build_request_v2(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_v3(text, jsonb, text, text, jsonb, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_result_build_request_v3(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_idempotency_key text;
  v_request jsonb;
  v_result jsonb;
  v_job private.worker_jobs%rowtype;
  v_job_id uuid;
  v_actual_idempotency_key text;
begin
  if v_actor is null then
    return api.lcia_result_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  if private.portal_lcia_safe_audit_v1(p_audit) is not true
     or nullif(btrim(coalesce(p_idempotency_key, '')), '') is null
     or length(btrim(p_idempotency_key)) > 220 then
    return api.lcia_result_error(
      'invalid_projection_request', 400, 'Invalid Portal LCIA V3 request'
    );
  end if;
  v_idempotency_key := 'portal-lcia-v3:' || btrim(p_idempotency_key);
  v_request := jsonb_build_object(
    'name', p_name,
    'processes', p_processes,
    'coverageMode', p_coverage_mode,
    'defaultImpactCategory', p_default_impact_category,
    'lciaMethodSet', p_lcia_method_set,
    'closureCheckId', p_closure_check_id,
    'requestedScopeHash', p_requested_scope_hash,
    'policyFingerprint', p_policy_fingerprint
  );

  select job.* into v_job
  from private.worker_jobs as job
  where job.job_kind = 'lcia_result.package_build'
    and job.requested_by = v_actor
    and job.payload_schema_version = 'lcia_result.package_build.request.v3'
    and job.payload_json ->> 'portalProjectionIdempotencyKey'
          = v_idempotency_key
  order by job.created_at desc, job.id
  limit 1
  for update;
  if v_job.id is not null then
    if v_job.payload_json -> 'portalProjectionRequest' is distinct from v_request
       or v_job.payload_json ->> 'portalProjectionContractVersion'
            <> 'portal.lcia-projection.v1' then
      return api.lcia_result_error(
        'build_enqueue_conflict', 409,
        'Existing V3 build is bound to different content'
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data', jsonb_build_object(
        'buildId', v_job.subject_id,
        'workerJobId', v_job.id,
        'workerJob', private.worker_job_payload(v_job, false),
        'projectionContractVersion', 'portal.lcia-projection.v1'
      )
    );
  end if;

  v_result := api.cmd_lcia_result_build_request_v2(
    p_name,
    p_processes,
    p_coverage_mode,
    p_default_impact_category,
    p_lcia_method_set,
    v_idempotency_key,
    p_closure_check_id,
    p_requested_scope_hash,
    p_policy_fingerprint,
    p_audit
  );
  if coalesce((v_result ->> 'ok')::boolean, false) is not true then
    return v_result;
  end if;
  begin
    v_job_id := nullif(v_result -> 'data' ->> 'workerJobId', '')::uuid;
    v_actual_idempotency_key := nullif(
      v_result -> 'data' -> 'workerJob' ->> 'idempotencyKey', ''
    );
  exception when invalid_text_representation then
    return api.lcia_result_error(
      'build_enqueue_unavailable', 503,
      'V2 admission did not return a valid Worker job identity'
    );
  end;

  select job.* into v_job
  from private.worker_jobs as job
  where job.id = v_job_id
  for update;
  if v_job.payload_schema_version = 'lcia_result.package_build.request.v3' then
    if v_job.requested_by = v_actor
       and v_job.idempotency_key is not distinct from v_actual_idempotency_key
       and v_job.payload_json ->> 'portalProjectionIdempotencyKey'
            = v_idempotency_key
       and v_job.payload_json -> 'portalProjectionRequest' = v_request
       and v_job.payload_json ->> 'portalProjectionContractVersion'
            = 'portal.lcia-projection.v1' then
      return jsonb_build_object(
        'ok', true,
        'reused', true,
        'data', jsonb_build_object(
          'buildId', v_job.subject_id,
          'workerJobId', v_job.id,
          'workerJob', private.worker_job_payload(v_job, false),
          'projectionContractVersion', 'portal.lcia-projection.v1'
        )
      );
    end if;
    return api.lcia_result_error(
      'build_enqueue_conflict', 409,
      'Existing V3 build is bound to different content'
    );
  end if;
  if v_job.id is null
     or v_job.requested_by <> v_actor
     or v_actual_idempotency_key is null
     or v_job.idempotency_key is distinct from v_actual_idempotency_key
     or v_job.payload_schema_version <> 'lcia_result.package_build.request.v2'
     or v_job.status not in ('queued', 'running', 'waiting', 'stale', 'blocked') then
    return api.lcia_result_error(
      'build_enqueue_conflict', 409,
      'V2 admission did not create the reserved convertible Worker job'
    );
  end if;

  update private.worker_jobs
  set payload_schema_version = 'lcia_result.package_build.request.v3',
      payload_json = payload_json || jsonb_build_object(
        'portalProjectionContractVersion', 'portal.lcia-projection.v1',
        'portalProjectionHashContractVersion',
          'portal.lcia-projection.int32be-frame-sha256.v1',
        'portalProjectionIdempotencyKey', v_idempotency_key,
        'portalProjectionRequest', v_request
      ),
      updated_at = clock_timestamp()
  where id = v_job.id
  returning * into v_job;

  insert into private.worker_job_events (
    job_id, event_type, status, details
  ) values (
    v_job.id,
    'portal_projection_v3_admitted',
    v_job.status,
    jsonb_build_object(
      'projectionContractVersion', 'portal.lcia-projection.v1',
      'hashContractVersion',
        'portal.lcia-projection.int32be-frame-sha256.v1'
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'buildId', v_job.subject_id,
      'workerJobId', v_job.id,
      'workerJob', private.worker_job_payload(v_job, false),
      'projectionContractVersion', 'portal.lcia-projection.v1'
    )
  );
exception
  when unique_violation then
    return api.lcia_result_error(
      'build_enqueue_conflict', 409,
      'A conflicting Portal LCIA V3 build already exists'
    );
end
$$;


ALTER FUNCTION api.cmd_lcia_result_build_request_v3(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_lcia_result_build_request_v3(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_lcia_result_build_request_v3(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) IS 'Additive V3 producer path: reuses unchanged V2 admission and converts only the reserved newly admitted job to the Portal projection contract.';


--
-- Name: cmd_lcia_result_package_publish(uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_result_package_publish(p_package_id uuid, p_display_default_impact_category text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_package private.lcia_result_packages%rowtype;
  v_current_manifest jsonb;
  v_default_impact text;
  v_previous_id uuid;
  v_publication private.lcia_result_publications%rowtype;
begin
  if v_actor is null then
    return api.lcia_result_error('auth_required', 401, 'Authentication required');
  end if;

  if not api.lcia_result_is_manager() then
    return api.lcia_result_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;

  select *
    into v_package
  from private.lcia_result_packages
  where id = p_package_id
  for update;

  if v_package.id is null or v_package.status <> 'preview_ready' then
    return api.lcia_result_error('package_not_ready', 400, 'Package must be preview_ready before publish');
  end if;

  if v_package.coverage_mode <> 'global_eligible'
     or v_package.included_input_count <> v_package.eligible_input_count then
    return api.lcia_result_error('package_not_global_eligible', 400, 'Only full global eligible packages can publish as global latest');
  end if;

  v_current_manifest := api.lcia_result_current_eligible_manifest();

  if v_package.eligible_input_count <> (v_current_manifest->>'eligibleInputCount')::integer
     or v_package.input_manifest_hash <> v_current_manifest->>'inputManifestHash' then
    return api.lcia_result_error('package_stale_eligibility', 409, 'Eligible process set changed after package creation');
  end if;

  v_default_impact := coalesce(
    nullif(trim(p_display_default_impact_category), ''),
    v_package.default_impact_category
  );

  if v_default_impact is null then
    return api.lcia_result_error('default_impact_missing', 400, 'Default impact category is required before publication');
  end if;

  if jsonb_array_length(v_package.available_impact_categories) > 0
     and not exists (
       select 1
       from jsonb_array_elements_text(v_package.available_impact_categories) as impact(value)
       where impact.value = v_default_impact
     ) then
    return api.lcia_result_error('default_impact_missing', 400, 'Default impact category is not present in the package impact category list');
  end if;

  if v_package.result_artifact_ref = '{}'::jsonb then
    return api.lcia_result_error('result_artifact_missing', 400, 'Package result artifact is required before publication');
  end if;

  lock table private.lcia_result_publications in exclusive mode;

  update private.lcia_result_publications
    set is_current = false,
        status = 'superseded',
        updated_at = now()
  where publication_series_key = 'global'
    and publication_channel = 'public'
    and visibility_scope = 'public'
    and is_current = true
  returning id
    into v_previous_id;

  insert into private.lcia_result_publications (
    package_id,
    publication_series_key,
    publication_channel,
    visibility_scope,
    is_current,
    status,
    display_default_impact_category,
    published_by,
    published_at,
    reason
  )
  values (
    v_package.id,
    'global',
    'public',
    'public',
    true,
    'current',
    v_default_impact,
    v_actor,
    now(),
    nullif(trim(coalesce(p_reason, '')), '')
  )
  returning *
    into v_publication;

  update private.lca_results
    set is_pinned = true
  where id = v_package.result_id;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_lcia_result_package_publish',
    v_actor,
    'lcia_result_publications',
    v_publication.id,
    v_package.package_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'packageId', v_package.id,
      'previousPublicationId', v_previous_id,
      'displayDefaultImpactCategory', v_default_impact
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'publicationId', v_publication.id,
      'packageId', v_package.id,
      'previousPublicationId', v_previous_id,
      'isCurrent', v_publication.is_current
    )
  );
exception
  when unique_violation then
    return api.lcia_result_error('latest_conflict', 409, 'Another current publication already exists');
end;
$$;


ALTER FUNCTION api.cmd_lcia_result_package_publish(p_package_id uuid, p_display_default_impact_category text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_publication_unpublish(uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_result_publication_unpublish(p_publication_id uuid, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_publication private.lcia_result_publications%rowtype;
begin
  if v_actor is null then
    return api.lcia_result_error('auth_required', 401, 'Authentication required');
  end if;

  if not api.lcia_result_is_manager() then
    return api.lcia_result_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;

  update private.lcia_result_publications
    set is_current = false,
        status = 'unpublished',
        unpublished_by = v_actor,
        unpublished_at = now(),
        reason = coalesce(nullif(trim(p_reason), ''), reason),
        updated_at = now()
  where id = p_publication_id
  returning *
    into v_publication;

  if v_publication.id is null then
    return api.lcia_result_error('publication_not_found', 404, 'Publication not found');
  end if;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_lcia_result_publication_unpublish',
    v_actor,
    'lcia_result_publications',
    v_publication.id,
    null,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object('reason', p_reason)
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'publicationId', v_publication.id,
      'packageId', v_publication.package_id,
      'status', v_publication.status
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_lcia_result_publication_unpublish(p_publication_id uuid, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_set_create(text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_result_set_create(p_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_result_set private.lcia_result_sets%rowtype;
begin
  if v_actor is null then
    return api.lcia_scope_closure_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  if not api.lcia_scope_closure_is_manager() then
    return api.lcia_scope_closure_error(
      'not_data_product_manager', 403,
      'Data product manager role is required'
    );
  end if;
  if coalesce(length(btrim(p_name)), 0) = 0 then
    return api.lcia_scope_closure_error(
      'invalid_result_set_name', 400, 'Result set name is required'
    );
  end if;

  insert into private.lcia_result_sets (name)
  values (btrim(p_name))
  returning * into v_result_set;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'schemaVersion', 'lcia.result-set.v1',
      'resultSetId', v_result_set.id,
      'name', v_result_set.name,
      'createdAt', v_result_set.created_at
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_lcia_result_set_create(p_name text) OWNER TO postgres;

--
-- Name: cmd_lcia_scope_closure_check_request_v2(jsonb, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_scope jsonb;
  v_policy jsonb;
  v_requested_scope_hash text;
  v_policy_fingerprint text;
  v_expected_validator text;
  v_snapshot_manifest jsonb;
  v_snapshot_token text;
  v_request_fingerprint text;
  v_request_key text;
  v_result jsonb;
  v_check private.lcia_scope_closure_checks%rowtype;
  v_job private.worker_jobs%rowtype;
  v_execution private.lcia_scope_closure_scan_executions%rowtype;
  v_publication private.lca_release_publications%rowtype;
  v_run private.lca_release_runs%rowtype;
  v_dataset_manifest jsonb;
  v_candidate_manifest_hash text;
  v_publication_epoch bigint := 0;
  v_missing_root_count integer;
begin
  if v_actor is null then
    return api.lcia_scope_closure_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  if not api.lcia_scope_closure_is_manager() then
    return api.lcia_scope_closure_error(
      'not_data_product_manager', 403, 'Data product manager role is required'
    );
  end if;
  if coalesce(nullif(trim(p_request_idempotency_token), ''), '') = '' then
    return api.lcia_scope_closure_error(
      'invalid_closure_request', 400, 'Idempotency token is required'
    );
  end if;

  v_scope := private.lcia_scope_closure_normalize_request(p_requested_scope);

  if v_scope->>'eligibilityPredicateVersion' = 'current-public-release-manifest:v2' then
    select *
    into v_publication
    from private.lca_release_publications
    where is_current = true and status = 'current'
    order by published_at desc
    limit 1;

    if v_publication.id is null then
      return api.lcia_scope_closure_error(
        'closure_snapshot_source_changed',
        409,
        'The current release changed while the closure snapshot was being frozen; retry the check'
      );
    end if;
    select *
    into v_run
    from private.lca_release_runs
    where id = v_publication.release_run_id;
    if v_run.id is null or v_run.release_manifest_hash is null then
      return api.lcia_scope_closure_error(
        'closure_evidence_unavailable',
        503,
        'Current public release manifest is unavailable'
      );
    end if;
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'datasetType', d.dataset_type,
        'datasetId', d.dataset_uuid,
        'datasetVersion', d.dataset_version,
        'role', d.dataset_role,
        'sourceProcessId', d.source_process_uuid,
        'sourceProcessVersion', d.source_process_version,
        'versionSignificantHash', d.version_significant_hash,
        'semanticHash', d.semantic_hash,
        'canonicalContentHash', d.canonical_content_hash
      )
      order by d.dataset_type, d.dataset_uuid, d.dataset_version, d.dataset_role
    ), '[]'::jsonb)
    into v_dataset_manifest
    from private.lca_release_dataset_versions d
    where d.release_run_id = v_run.id;

    if jsonb_array_length(v_dataset_manifest) = 0 then
      return api.lcia_scope_closure_error(
        'closure_evidence_unavailable',
        503,
        'Current public release dataset manifest is empty'
      );
    end if;

    v_snapshot_manifest := jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-data-snapshot.v2',
      'requestedScope', v_scope,
      'currentPublicRelease', jsonb_build_object(
        'publicationId', v_publication.id,
        'releaseRunId', v_run.id,
        'releaseVersion', v_run.release_version,
        'publishedAt', v_publication.published_at,
        'releaseManifestHash', v_run.release_manifest_hash
      ),
      'datasets', v_dataset_manifest
    );
    v_publication_epoch := extract(epoch from v_publication.published_at)::bigint;
  else
    if v_scope->>'certificateFreshnessPolicy' = 'current-membership-required-v1' then
      return api.lcia_scope_closure_error(
        'current_release_required',
        409,
        'Current-membership freshness requires a current formal release'
      );
    end if;

    v_dataset_manifest :=
      private.lcia_scope_closure_candidate_dataset_manifest();
    if jsonb_array_length(v_dataset_manifest) = 0 then
      return api.lcia_scope_closure_error(
        'closure_evidence_unavailable',
        503,
        'Candidate public-state dataset manifest is empty'
      );
    end if;

    with roots as (
      select 'processes'::text as dataset_type,
        (item.value->>'id')::uuid as dataset_id,
        item.value->>'version' as dataset_version
      from jsonb_array_elements(v_scope->'processes') item(value)
      union all
      select 'lciamethods',
        (item.value->>'id')::uuid,
        item.value->>'version'
      from jsonb_array_elements(v_scope->'lciaMethods') item(value)
    ),
    frozen as (
      select item.value->>'datasetType' as dataset_type,
        (item.value->>'datasetId')::uuid as dataset_id,
        item.value->>'datasetVersion' as dataset_version
      from jsonb_array_elements(v_dataset_manifest) item(value)
    )
    select count(*)
    into v_missing_root_count
    from roots r
    left join frozen f using (dataset_type, dataset_id, dataset_version)
    where f.dataset_id is null;

    if v_missing_root_count <> 0 then
      return api.lcia_scope_closure_error(
        'closure_snapshot_source_changed',
        409,
        'Candidate data changed while the closure snapshot was being frozen; retry the check'
      );
    end if;

    v_candidate_manifest_hash := private.lcia_scope_closure_sha256(
      jsonb_build_object(
        'eligibilityPredicateVersion',
          v_scope->>'eligibilityPredicateVersion',
        'datasets', v_dataset_manifest
      )
    );
    v_snapshot_manifest := jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-data-snapshot.v2',
      'requestedScope', v_scope,
      -- Required only for deployed Worker v2 compatibility.  candidateData
      -- below is the authoritative source description.
      'currentPublicRelease', jsonb_build_object(
        'publicationId', '00000000-0000-0000-0000-000000000000',
        'releaseRunId', '00000000-0000-0000-0000-000000000000',
        'releaseVersion', 'candidate-public-state-v1',
        'publishedAt', '1970-01-01T00:00:00Z',
        'releaseManifestHash', v_candidate_manifest_hash
      ),
      'candidateData', jsonb_build_object(
        'sourceKind', 'candidate-public-state',
        'eligibilityPredicateVersion',
          v_scope->>'eligibilityPredicateVersion',
        'datasetManifestHash', v_candidate_manifest_hash,
        'workerV2CompatibilityProjection', true
      ),
      'datasets', v_dataset_manifest
    );
  end if;

  v_snapshot_token := private.lcia_scope_closure_sha256(v_snapshot_manifest);
  v_requested_scope_hash := private.lcia_scope_closure_sha256(v_scope);
  v_policy := jsonb_build_object(
    'scopePolicy', v_scope - 'processes' - 'lciaMethods' - 'processManifestHash',
    'visibilityScope', 'data_product_manager.v1'
  );
  v_policy_fingerprint := private.lcia_scope_closure_sha256(v_policy);
  select expected_validator_scanner_fingerprint
  into v_expected_validator
  from private.lcia_scope_closure_config
  where singleton;
  if v_expected_validator is null then
    return api.lcia_scope_closure_error(
      'closure_evidence_unavailable',
      503,
      'Closure validator configuration is unavailable'
    );
  end if;

  v_request_fingerprint := encode(extensions.digest(
    v_requested_scope_hash || '|' || v_policy_fingerprint || '|'
      || v_expected_validator || '|' || v_snapshot_token,
    'sha256'
  ), 'hex');
  v_request_key := encode(extensions.digest(
    v_actor::text || '|' || trim(p_request_idempotency_token) || '|'
      || v_request_fingerprint,
    'sha256'
  ), 'hex');

  select *
  into v_check
  from private.lcia_scope_closure_checks
  where requested_by = v_actor and request_key = v_request_key
  for update;
  if v_check.id is not null then
    select * into v_job from private.worker_jobs where id = v_check.worker_job_id;
    return jsonb_build_object(
      'ok', true,
      'data', jsonb_build_object(
        'closureCheckId', v_check.id,
        'requestedScopeHash', v_check.requested_scope_hash,
        'policyFingerprint', v_check.policy_fingerprint,
        'dataSnapshotToken', v_check.data_snapshot_token,
        'scanExecutionId', v_check.scan_execution_id,
        'workerJob', private.worker_job_payload(v_job, false),
        'reused', true
      )
    );
  end if;

  v_result := private.cmd_lcia_scope_closure_check_request_v2_untracked(
    p_requested_scope,
    p_request_idempotency_token,
    p_audit
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    return v_result;
  end if;
  select *
  into v_check
  from private.lcia_scope_closure_checks
  where id = nullif(v_result->'data'->>'closureCheckId', '')::uuid
  for update;
  if v_check.id is null then
    return api.lcia_scope_closure_error(
      'closure_check_not_found', 404, 'Closure check not found'
    );
  end if;
  if coalesce((v_result->'data'->>'reused')::boolean, false)
     and v_check.request_key <> v_request_key
     and v_check.data_snapshot_token <> v_snapshot_token then
    return api.lcia_scope_closure_error(
      'idempotency_token_bound_to_different_snapshot',
      409,
      'Idempotency token is already bound to a different data snapshot'
    );
  end if;

  insert into private.lcia_scope_closure_data_snapshots(
    data_snapshot_token,
    root_manifest,
    root_manifest_hash,
    publication_epoch
  ) values (
    v_snapshot_token,
    v_snapshot_manifest,
    private.lcia_scope_closure_sha256(v_snapshot_manifest),
    v_publication_epoch
  )
  on conflict (data_snapshot_token) do nothing;

  update private.lcia_scope_closure_checks
  set data_snapshot_token = v_snapshot_token,
      requested_scope_manifest = v_scope,
      requested_scope_hash = v_requested_scope_hash,
      policy_fingerprint = v_policy_fingerprint,
      request_fingerprint = v_request_fingerprint,
      request_key = v_request_key,
      updated_at = now()
  where id = v_check.id
  returning * into v_check;

  select *
  into v_execution
  from private.lcia_scope_closure_scan_executions
  where request_fingerprint = v_request_fingerprint
  for update;
  if v_execution.id is null then
    insert into private.lcia_scope_closure_scan_executions(
      request_fingerprint,
      requested_scope_hash,
      policy_fingerprint,
      data_snapshot_token,
      validator_scanner_fingerprint
    ) values (
      v_request_fingerprint,
      v_requested_scope_hash,
      v_policy_fingerprint,
      v_snapshot_token,
      v_expected_validator
    )
    returning * into v_execution;
  end if;

  update private.lcia_scope_closure_checks
  set scan_execution_id = v_execution.id,
      updated_at = now()
  where id = v_check.id
  returning * into v_check;

  update private.worker_jobs
  set request_hash = v_request_fingerprint,
      concurrency_key = v_request_key,
      payload_json = payload_json || jsonb_build_object(
        'coverage_mode', v_scope->>'coverageMode',
        'input_manifest', jsonb_build_object(
          'predicateVersion', v_scope->>'eligibilityPredicateVersion',
          'selectionMode', 'closure_certificate',
          'processes', v_scope->'processes'
        ),
        'input_manifest_hash',
          private.lcia_scope_closure_sha256(
            jsonb_build_object('processes', v_scope->'processes')
          ),
        'lcia_method_set', v_scope->'lciaMethods',
        'request_fingerprint', v_request_fingerprint,
        'scan_execution_id', v_execution.id,
        'data_snapshot_token', v_snapshot_token
      ),
      updated_at = now()
  where id = v_check.worker_job_id
  returning * into v_job;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'closureCheckId', v_check.id,
      'requestedScopeHash', v_check.requested_scope_hash,
      'policyFingerprint', v_check.policy_fingerprint,
      'dataSnapshotToken', v_snapshot_token,
      'scanExecutionId', v_execution.id,
      'workerJob', private.worker_job_payload(v_job, false),
      'reused', false
    )
  );
exception
  when sqlstate '22023' then
    return api.lcia_scope_closure_error(
      'invalid_closure_scope', 400, sqlerrm
    );
end;
$$;


ALTER FUNCTION api.cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_lcia_scope_closure_check_request_v2(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) IS 'Creates a release-bound closure preflight when a formal release exists, or a deterministic candidate-public-state preflight for initial release bootstrap.';


--
-- Name: cmd_lcia_scope_closure_check_request_v3(uuid, jsonb, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lcia_scope_closure_check_request_v3(p_result_set_id uuid, p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_result jsonb;
  v_closure_check_id uuid;
begin
  if v_actor is null then
    return api.lcia_scope_closure_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  if not api.lcia_scope_closure_is_manager() then
    return api.lcia_scope_closure_error(
      'not_data_product_manager', 403,
      'Data product manager role is required'
    );
  end if;
  if not exists (
    select 1 from private.lcia_result_sets where id = p_result_set_id
  ) then
    return api.lcia_scope_closure_error(
      'result_set_not_found', 404, 'Result set not found'
    );
  end if;

  v_result := api.cmd_lcia_scope_closure_check_request_v2(
    p_requested_scope,
    p_request_idempotency_token,
    coalesce(p_audit, '{}'::jsonb)
      || jsonb_build_object('resultSetId', p_result_set_id)
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    return v_result;
  end if;

  v_closure_check_id := nullif(
    v_result->'data'->>'closureCheckId', ''
  )::uuid;

  update private.lcia_scope_closure_checks
  set result_set_id = p_result_set_id,
      updated_at = now()
  where id = v_closure_check_id
    and requested_by = v_actor
    and (result_set_id is null or result_set_id = p_result_set_id);

  if not found then
    return api.lcia_scope_closure_error(
      'closure_check_result_set_conflict', 409,
      'Closure check is already bound to another result set'
    );
  end if;

  return jsonb_set(
    v_result,
    '{data,resultSetId}',
    to_jsonb(p_result_set_id),
    true
  );
end;
$$;


ALTER FUNCTION api.cmd_lcia_scope_closure_check_request_v3(p_result_set_id uuid, p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_lcia_scope_closure_check_request_v3(p_result_set_id uuid, p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_lcia_scope_closure_check_request_v3(p_result_set_id uuid, p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) IS 'Creates or reuses a Scope Closure check and atomically binds it to one persistent ResultSet.';


--
-- Name: cmd_lifecycle_model_bundle_delete(uuid, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lifecycle_model_bundle_delete(p_model_id uuid, p_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_owner uuid;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTH_REQUIRED';
  end if;

  select model.user_id
  into v_owner
  from public.lifecyclemodels as model
  where model.id = p_model_id
    and model.version = p_version
  for update;

  if v_owner is null then
    raise exception using errcode = 'P0002', message = 'MODEL_NOT_FOUND';
  end if;

  if v_owner <> v_actor and not exists (
    select 1
    from private.roles as membership
    where membership.user_id = v_actor
      and membership.team_id = '00000000-0000-0000-0000-000000000000'::uuid
      and membership.role = 'review-admin'
  ) then
    raise exception using errcode = '42501', message = 'FORBIDDEN';
  end if;

  return private.delete_lifecycle_model_bundle(p_model_id, p_version);
end
$$;


ALTER FUNCTION api.cmd_lifecycle_model_bundle_delete(p_model_id uuid, p_version text) OWNER TO postgres;

--
-- Name: cmd_lifecycle_model_bundle_save(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_lifecycle_model_bundle_save(p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_plan jsonb := coalesce(p_plan, '{}'::jsonb);
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTH_REQUIRED';
  end if;
  v_plan := jsonb_set(v_plan, '{actorUserId}', to_jsonb(v_actor::text), true);
  return private.save_lifecycle_model_bundle(v_plan);
end
$$;


ALTER FUNCTION api.cmd_lifecycle_model_bundle_save(p_plan jsonb) OWNER TO postgres;

