--
-- Name: cmd_membership_resolve_member_order_by(text, boolean); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_membership_resolve_member_order_by(p_sort_by text, p_allow_workload boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
begin
  case lower(coalesce(p_sort_by, ''))
    when 'role' then
      return 'm.role';
    when 'email' then
      return 'm.email';
    when 'display_name' then
      return 'm.display_name';
    when 'modified_at' then
      return 'm.modified_at';
    when 'pendingcount' then
      if p_allow_workload then
        return 'm.pending_count';
      end if;
    when 'pending_count' then
      if p_allow_workload then
        return 'm.pending_count';
      end if;
    when 'reviewedcount' then
      if p_allow_workload then
        return 'm.reviewed_count';
      end if;
    when 'reviewed_count' then
      if p_allow_workload then
        return 'm.reviewed_count';
      end if;
    else
      return 'm.created_at';
  end case;

  return 'm.created_at';
end;
$$;


ALTER FUNCTION api.cmd_membership_resolve_member_order_by(p_sort_by text, p_allow_workload boolean) OWNER TO postgres;

--
-- Name: cmd_membership_resolve_sort_direction(text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_membership_resolve_sort_direction(p_sort_order text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
begin
  case lower(coalesce(p_sort_order, ''))
    when 'asc' then
      return 'asc';
    when 'ascend' then
      return 'asc';
    else
      return 'desc';
  end case;
end;
$$;


ALTER FUNCTION api.cmd_membership_resolve_sort_direction(p_sort_order text) OWNER TO postgres;

--
-- Name: cmd_notification_normalize_text_array(text[]); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_notification_normalize_text_array(p_values text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  with normalized as (
    select
      min(item.ordinality) as first_ordinality,
      nullif(btrim(item.value), '') as normalized_value
    from unnest(coalesce(p_values, array[]::text[])) with ordinality as item(value, ordinality)
    group by nullif(btrim(item.value), '')
  )
  select coalesce(
    array(
      select normalized_value
      from normalized
      where normalized_value is not null
      order by first_ordinality
    ),
    array[]::text[]
  );
$$;


ALTER FUNCTION api.cmd_notification_normalize_text_array(p_values text[]) OWNER TO postgres;

--
-- Name: cmd_notification_send_validation_issue(uuid, text, uuid, text, text, text[], text[], integer, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_notification_send_validation_issue(p_recipient_user_id uuid, p_dataset_type text, p_dataset_id uuid, p_dataset_version text, p_link text DEFAULT NULL::text, p_issue_codes text[] DEFAULT ARRAY[]::text[], p_tab_names text[] DEFAULT ARRAY[]::text[], p_issue_count integer DEFAULT 0, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_dataset_type text := nullif(btrim(coalesce(p_dataset_type, '')), '');
  v_dataset_version text := nullif(btrim(coalesce(p_dataset_version, '')), '');
  v_target_table text;
  v_target_row jsonb;
  v_issue_codes text[];
  v_tab_names text[];
  v_sender_name text;
  v_notification_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_recipient_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'RECIPIENT_REQUIRED',
      'status', 400,
      'message', 'recipientUserId is required'
    );
  end if;

  if v_actor = p_recipient_user_id then
    return jsonb_build_object(
      'ok', false,
      'code', 'NOTIFICATION_SELF_TARGET',
      'status', 409,
      'message', 'The recipient must differ from the actor'
    );
  end if;

  if v_dataset_type is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_TYPE_REQUIRED',
      'status', 400,
      'message', 'datasetType is required'
    );
  end if;

  if p_dataset_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_ID_REQUIRED',
      'status', 400,
      'message', 'datasetId is required'
    );
  end if;

  if v_dataset_version is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_VERSION_REQUIRED',
      'status', 400,
      'message', 'datasetVersion is required'
    );
  end if;

  if not exists (
    select 1
    from private.users
    where id = p_recipient_user_id
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'RECIPIENT_NOT_FOUND',
      'status', 404,
      'message', 'The recipient user does not exist'
    );
  end if;

  v_target_table := api.cmd_review_ref_type_to_table(v_dataset_type);
  if v_target_table is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_TYPE_INVALID',
      'status', 400,
      'message', 'datasetType is not supported'
    );
  end if;

  v_target_row := api.cmd_review_get_dataset_row(
    v_target_table,
    p_dataset_id,
    v_dataset_version,
    false
  );
  if v_target_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'The target dataset does not exist'
    );
  end if;

  if ((v_target_row ->> 'user_id')::uuid is distinct from p_recipient_user_id) then
    return jsonb_build_object(
      'ok', false,
      'code', 'RECIPIENT_NOT_TARGET_OWNER',
      'status', 403,
      'message', 'The recipient must own the target dataset'
    );
  end if;

  v_issue_codes := api.cmd_notification_normalize_text_array(p_issue_codes);
  v_tab_names := api.cmd_notification_normalize_text_array(p_tab_names);

  select coalesce(
    nullif(btrim(u.raw_user_meta_data ->> 'display_name'), ''),
    nullif(btrim(u.raw_user_meta_data ->> 'name'), ''),
    nullif(btrim(u.raw_user_meta_data ->> 'email'), ''),
    '-'
  )
  into v_sender_name
  from private.users as u
  where u.id = v_actor;

  v_sender_name := coalesce(v_sender_name, '-');

  insert into private.notifications (
    recipient_user_id,
    sender_user_id,
    type,
    dataset_type,
    dataset_id,
    dataset_version,
    json,
    modified_at
  )
  values (
    p_recipient_user_id,
    v_actor,
    'validation_issue',
    v_dataset_type,
    p_dataset_id,
    v_dataset_version,
    jsonb_build_object(
      'issueCodes', to_jsonb(v_issue_codes),
      'issueCount', greatest(coalesce(p_issue_count, 0), 0),
      'link', nullif(btrim(coalesce(p_link, '')), ''),
      'senderName', v_sender_name,
      'tabNames', to_jsonb(v_tab_names)
    ),
    now()
  )
  on conflict (
    recipient_user_id,
    sender_user_id,
    type,
    dataset_type,
    dataset_id,
    dataset_version
  ) do update
  set json = excluded.json,
      modified_at = excluded.modified_at
  returning to_jsonb(notifications.*)
    into v_notification_row;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_notification_send_validation_issue',
    v_actor,
    'notifications',
    (v_notification_row ->> 'id')::uuid,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'recipientUserId', p_recipient_user_id,
      'datasetType', v_dataset_type,
      'datasetId', p_dataset_id,
      'datasetVersion', v_dataset_version,
      'issueCount', greatest(coalesce(p_issue_count, 0), 0)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_notification_row
  );
end;
$$;


ALTER FUNCTION api.cmd_notification_send_validation_issue(p_recipient_user_id uuid, p_dataset_type text, p_dataset_id uuid, p_dataset_version text, p_link text, p_issue_codes text[], p_tab_names text[], p_issue_count integer, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_portal_lcia_projection_finalize_publication_v1(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_portal_lcia_projection_finalize_publication_v1(p_projection_id uuid, p_lcia_result_publication_id uuid, p_package_version text, p_package_result_hash text, p_projection_content_hash text, p_idempotency_key text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_projection private.portal_lcia_projection_headers%rowtype;
  v_publication private.lcia_result_publications%rowtype;
  v_package private.lcia_result_packages%rowtype;
begin
  if auth.uid() is null or not api.lcia_result_is_manager() then
    return private.portal_lcia_projection_finalize_unchecked_v1(
      p_projection_id, p_lcia_result_publication_id, p_package_version,
      p_package_result_hash, p_projection_content_hash, p_idempotency_key,
      p_audit
    );
  end if;
  select projection.* into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.id = p_projection_id;
  select publication.* into v_publication
  from private.lcia_result_publications as publication
  where publication.id = p_lcia_result_publication_id;
  select package.* into v_package
  from private.lcia_result_packages as package
  where package.id = v_publication.package_id;
  if v_projection.id is not null
     and v_publication.id is not null
     and v_package.id is not null
     and v_package.build_worker_job_id = v_projection.build_worker_job_id
     and v_package.package_version = p_package_version
     and v_package.package_result_hash = p_package_result_hash
     and v_projection.content_hash = p_projection_content_hash
     and v_package.artifact_manifest ->> 'portalProjectionId'
           = v_projection.id::text then
    perform 1
    from private.worker_jobs as job
    where job.id = v_package.build_worker_job_id
    for share;
    perform 1
    from private.lca_results as result
    where result.id = v_package.result_id
    for share;
    if v_package.latest_all_unit_result_id is not null then
      perform 1
      from private.lca_latest_all_unit_results as latest
      where latest.id = v_package.latest_all_unit_result_id
      for share;
    end if;
    if private.portal_lcia_projection_package_binding_valid_v1(
         v_package.id, v_package.build_worker_job_id, v_projection.id
       ) is not true then
      return api.lcia_result_error(
        'projection_package_binding_invalid', 409,
        'Portal LCIA package binding is no longer authoritative'
      );
    end if;
  end if;
  return private.portal_lcia_projection_finalize_unchecked_v1(
    p_projection_id, p_lcia_result_publication_id, p_package_version,
    p_package_result_hash, p_projection_content_hash, p_idempotency_key,
    p_audit
  );
end
$$;


ALTER FUNCTION api.cmd_portal_lcia_projection_finalize_publication_v1(p_projection_id uuid, p_lcia_result_publication_id uuid, p_package_version text, p_package_result_hash text, p_projection_content_hash text, p_idempotency_key text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_portal_lcia_projection_finalize_publication_v1(p_projection_id uuid, p_lcia_result_publication_id uuid, p_package_version text, p_package_result_hash text, p_projection_content_hash text, p_idempotency_key text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_portal_lcia_projection_finalize_publication_v1(p_projection_id uuid, p_lcia_result_publication_id uuid, p_package_version text, p_package_result_hash text, p_projection_content_hash text, p_idempotency_key text, p_audit jsonb) IS 'Finalizes only an exact authoritative package/result/projection binding for the current LCIA result publication.';


--
-- Name: cmd_portal_lcia_projection_revoke_publication_v1(uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_portal_lcia_projection_revoke_publication_v1(p_lcia_result_publication_id uuid, p_projection_content_hash text, p_reason text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_binding private.portal_lcia_projection_publications%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_now timestamptz := clock_timestamp();
begin
  if v_actor is null then
    return api.lcia_result_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  if not api.lcia_result_is_manager() then
    return api.lcia_result_error(
      'not_data_product_manager', 403,
      'Data product manager role is required'
    );
  end if;
  if p_lcia_result_publication_id is null
     or coalesce(p_projection_content_hash, '') !~ '^[0-9a-f]{64}$'
     or private.portal_lcia_public_text_valid_v1(v_reason, 2000) is not true
     or private.portal_lcia_safe_audit_v1(p_audit) is not true then
    return api.lcia_result_error(
      'invalid_projection_request', 400, 'Invalid projection revoke request'
    );
  end if;

  select binding.* into v_binding
  from private.portal_lcia_projection_publications as binding
  where binding.lcia_result_publication_id = p_lcia_result_publication_id
  for update;
  if v_binding.id is null then
    return api.lcia_result_error(
      'projection_publication_not_found', 404,
      'Projection publication binding was not found'
    );
  end if;
  if v_binding.projection_content_hash <> p_projection_content_hash then
    return api.lcia_result_error(
      'projection_evidence_mismatch', 409,
      'Projection content hash does not match the binding'
    );
  end if;
  if v_binding.status = 'revoked' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data', jsonb_build_object(
        'projectionPublicationId', v_binding.id,
        'lciaResultPublicationId', v_binding.lcia_result_publication_id,
        'status', v_binding.status,
        'revokedAt', private.portal_timestamp_v1(v_binding.revoked_at)
      )
    );
  end if;

  update private.portal_lcia_projection_publications
  set status = 'revoked',
      revoked_by = v_actor,
      revoked_at = v_now,
      revoke_reason = v_reason
  where id = v_binding.id
  returning * into v_binding;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_portal_lcia_projection_revoke_publication_v1',
    v_actor,
    'portal_lcia_projection_publications',
    v_binding.id,
    v_binding.package_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'lciaResultPublicationId', v_binding.lcia_result_publication_id,
      'contentHash', v_binding.projection_content_hash,
      'reason', v_reason
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'projectionPublicationId', v_binding.id,
      'lciaResultPublicationId', v_binding.lcia_result_publication_id,
      'status', v_binding.status,
      'revokedAt', private.portal_timestamp_v1(v_binding.revoked_at)
    )
  );
end
$_$;


ALTER FUNCTION api.cmd_portal_lcia_projection_revoke_publication_v1(p_lcia_result_publication_id uuid, p_projection_content_hash text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_portal_lcia_result_package_publish_v1(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_portal_lcia_result_package_publish_v1(p_package_id uuid, p_display_default_impact_category text, p_expected_publish_plan_hash text, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_package private.lcia_result_packages%rowtype;
  v_projection private.portal_lcia_projection_headers%rowtype;
begin
  if auth.uid() is null or not api.lcia_result_is_manager() then
    return private.portal_lcia_package_publish_unchecked_v1(
      p_package_id, p_display_default_impact_category,
      p_expected_publish_plan_hash, p_reason, p_audit
    );
  end if;
  select package.* into v_package
  from private.lcia_result_packages as package
  where package.id = p_package_id;
  select projection.* into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.id::text =
    v_package.artifact_manifest ->> 'portalProjectionId'
    and projection.build_worker_job_id = v_package.build_worker_job_id;
  if v_package.id is not null and v_projection.id is not null then
    perform 1
    from private.worker_jobs as job
    where job.id = v_package.build_worker_job_id
    for share;
    perform 1
    from private.lca_results as result
    where result.id = v_package.result_id
    for share;
    if v_package.latest_all_unit_result_id is not null then
      perform 1
      from private.lca_latest_all_unit_results as latest
      where latest.id = v_package.latest_all_unit_result_id
      for share;
    end if;
    if private.portal_lcia_projection_package_binding_valid_v1(
         v_package.id, v_package.build_worker_job_id, v_projection.id
       ) is not true then
      return api.lcia_result_error(
        'projection_package_binding_invalid', 409,
        'Portal LCIA package binding is no longer authoritative'
      );
    end if;
  end if;
  return private.portal_lcia_package_publish_unchecked_v1(
    p_package_id, p_display_default_impact_category,
    p_expected_publish_plan_hash, p_reason, p_audit
  );
end
$$;


ALTER FUNCTION api.cmd_portal_lcia_result_package_publish_v1(p_package_id uuid, p_display_default_impact_category text, p_expected_publish_plan_hash text, p_reason text, p_audit jsonb) OWNER TO postgres;

