--
-- Name: cmd_review_get_actor_meta(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_get_actor_meta(p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_meta jsonb;
  v_display_name text;
  v_email text;
begin
  select u.raw_user_meta_data
    into v_meta
  from private.users as u
  where u.id = p_actor;

  v_display_name := coalesce(nullif(v_meta->>'display_name', ''), nullif(v_meta->>'email', ''));
  v_email := nullif(v_meta->>'email', '');

  return jsonb_strip_nulls(
    jsonb_build_object(
      'id', p_actor,
      'display_name', v_display_name,
      'email', v_email
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_review_get_actor_meta(p_actor uuid) OWNER TO postgres;

--
-- Name: cmd_review_get_dataset_name(text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_get_dataset_name(p_table text, p_row jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_table
    when 'contacts' then pg_catalog.jsonb_build_object(
      'baseName', coalesce(
        nullif(nullif(p_row#>'{json,contactDataSet,contactInformation,dataSetInformation,common:shortName}', '{}'::jsonb), '[]'::jsonb),
        nullif(nullif(p_row#>'{json,contactDataSet,contactInformation,dataSetInformation,common:name}', '{}'::jsonb), '[]'::jsonb),
        nullif(nullif(p_row#>'{json_ordered,contactDataSet,contactInformation,dataSetInformation,common:shortName}', '{}'::jsonb), '[]'::jsonb),
        nullif(nullif(p_row#>'{json_ordered,contactDataSet,contactInformation,dataSetInformation,common:name}', '{}'::jsonb), '[]'::jsonb),
        '[]'::jsonb
      )
    )
    when 'sources' then pg_catalog.jsonb_build_object(
      'baseName', coalesce(
        nullif(nullif(p_row#>'{json,sourceDataSet,sourceInformation,dataSetInformation,common:shortName}', '{}'::jsonb), '[]'::jsonb),
        nullif(nullif(p_row#>'{json_ordered,sourceDataSet,sourceInformation,dataSetInformation,common:shortName}', '{}'::jsonb), '[]'::jsonb),
        '[]'::jsonb
      )
    )
    when 'unitgroups' then pg_catalog.jsonb_build_object(
      'baseName', coalesce(
        nullif(nullif(p_row#>'{json,unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}', '{}'::jsonb), '[]'::jsonb),
        nullif(nullif(p_row#>'{json_ordered,unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}', '{}'::jsonb), '[]'::jsonb),
        '[]'::jsonb
      )
    )
    when 'flowproperties' then pg_catalog.jsonb_build_object(
      'baseName', coalesce(
        nullif(nullif(p_row#>'{json,flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}', '{}'::jsonb), '[]'::jsonb),
        nullif(nullif(p_row#>'{json_ordered,flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}', '{}'::jsonb), '[]'::jsonb),
        '[]'::jsonb
      )
    )
    when 'flows' then coalesce(
      p_row#>'{json,flowDataSet,flowInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,flowDataSet,flowInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'processes' then coalesce(
      p_row#>'{json,processDataSet,processInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,processDataSet,processInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    when 'lifecyclemodels' then coalesce(
      p_row#>'{json,lifeCycleModelDataSet,lifeCycleModelInformation,dataSetInformation,name}',
      p_row#>'{json_ordered,lifeCycleModelDataSet,lifeCycleModelInformation,dataSetInformation,name}',
      '{}'::jsonb
    )
    else '{}'::jsonb
  end
$$;


ALTER FUNCTION api.cmd_review_get_dataset_name(p_table text, p_row jsonb) OWNER TO postgres;

--
-- Name: cmd_review_get_dataset_row(text, uuid, text, boolean); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_get_dataset_row(p_table text, p_id uuid, p_version text, p_lock boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_row jsonb;
begin
  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return null;
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 %s',
    p_table,
    case when p_lock then 'for update of t' else '' end
  )
    into v_row
    using p_id, p_version;

  return v_row;
end;
$_$;


ALTER FUNCTION api.cmd_review_get_dataset_row(p_table text, p_id uuid, p_version text, p_lock boolean) OWNER TO postgres;

--
-- Name: cmd_review_get_root_table(jsonb, uuid, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_get_root_table(p_review_json jsonb, p_data_id uuid, p_data_version text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_explicit text := lower(nullif(p_review_json#>>'{data,table}', ''));
  v_process_row jsonb;
  v_model_row jsonb;
  v_expected_name jsonb := coalesce(p_review_json#>'{data,name}', '{}'::jsonb);
begin
  if v_explicit in ('processes', 'lifecyclemodels') then
    return v_explicit;
  end if;

  v_process_row := api.cmd_review_get_dataset_row('processes', p_data_id, p_data_version, false);
  v_model_row := api.cmd_review_get_dataset_row(
    'lifecyclemodels',
    p_data_id,
    p_data_version,
    false
  );

  if v_model_row is not null
     and api.cmd_review_get_dataset_name('lifecyclemodels', v_model_row) = v_expected_name then
    return 'lifecyclemodels';
  end if;

  if v_process_row is not null
     and api.cmd_review_get_dataset_name('processes', v_process_row) = v_expected_name then
    return 'processes';
  end if;

  if v_model_row is not null and v_process_row is null then
    return 'lifecyclemodels';
  end if;

  if v_process_row is not null then
    return 'processes';
  end if;

  return null;
end;
$$;


ALTER FUNCTION api.cmd_review_get_root_table(p_review_json jsonb, p_data_id uuid, p_data_version text) OWNER TO postgres;

