--
-- Name: cmd_review_merge_compliance_declarations(jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_merge_compliance_declarations(p_existing jsonb, p_additions jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  with normalized as (
    select
      case
        when jsonb_typeof(p_existing) = 'object' then p_existing
        else '{}'::jsonb
      end as existing_obj,
      case
        when jsonb_typeof(p_additions) = 'object' then p_additions
        else '{}'::jsonb
      end as additions_obj
  ),
  merged as (
    select
      existing_obj,
      additions_obj,
      existing_obj || (additions_obj - 'compliance') as base_obj
    from normalized
  )
  select case
    when additions_obj ? 'compliance' then
      jsonb_set(
        base_obj,
        '{compliance}',
        api.cmd_review_merge_json_collection(
          existing_obj->'compliance',
          additions_obj->'compliance'
        ),
        true
      )
    else base_obj
  end
  from merged
$$;


ALTER FUNCTION api.cmd_review_merge_compliance_declarations(p_existing jsonb, p_additions jsonb) OWNER TO postgres;

--
-- Name: cmd_review_merge_json_collection(jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_merge_json_collection(p_existing jsonb, p_additions jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select api.cmd_review_json_array(p_existing) || api.cmd_review_json_array(p_additions)
$$;


ALTER FUNCTION api.cmd_review_merge_json_collection(p_existing jsonb, p_additions jsonb) OWNER TO postgres;

--
-- Name: cmd_review_merge_validation(jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_merge_validation(p_existing jsonb, p_additions jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  with normalized as (
    select
      case
        when jsonb_typeof(p_existing) = 'object' then p_existing
        else '{}'::jsonb
      end as existing_obj,
      case
        when jsonb_typeof(p_additions) = 'object' then p_additions
        else '{}'::jsonb
      end as additions_obj
  ),
  merged as (
    select
      existing_obj,
      additions_obj,
      existing_obj || (additions_obj - 'review') as base_obj
    from normalized
  )
  select case
    when additions_obj ? 'review' then
      jsonb_set(
        base_obj,
        '{review}',
        api.cmd_review_merge_json_collection(existing_obj->'review', additions_obj->'review'),
        true
      )
    else base_obj
  end
  from merged
$$;


ALTER FUNCTION api.cmd_review_merge_validation(p_existing jsonb, p_additions jsonb) OWNER TO postgres;

--
-- Name: cmd_review_normalize_reviewer_ids(jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_normalize_reviewer_ids(p_reviewer_ids jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
  with normalized as (
    select
      value,
      min(ordinality) as ordinality
    from jsonb_array_elements_text(
      case
        when jsonb_typeof(p_reviewer_ids) = 'array' then p_reviewer_ids
        else '[]'::jsonb
      end
    ) with ordinality as reviewer_ids(value, ordinality)
    where value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    group by value
  )
  select coalesce(
    jsonb_agg(to_jsonb(value) order by ordinality),
    '[]'::jsonb
  )
  from normalized
$_$;


ALTER FUNCTION api.cmd_review_normalize_reviewer_ids(p_reviewer_ids jsonb) OWNER TO postgres;

--
-- Name: cmd_review_quality_diagnostic_start(); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_quality_diagnostic_start() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_job private.worker_jobs%rowtype;
  v_concurrency_key constant text := 'review.quality_diagnostic.pending_review';
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not api.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Review Admin role is required'
    );
  end if;

  select job.*
  into v_job
  from private.worker_jobs as job
  where job.job_kind = 'review.quality_diagnostic'
    and job.concurrency_key = v_concurrency_key
    and job.status in ('queued', 'running', 'waiting', 'stale')
  order by job.created_at desc, job.id desc
  limit 1;

  if found then
    return jsonb_build_object(
      'ok', true,
      'data', private.review_quality_diagnostic_projection(v_job),
      'reused', true
    );
  end if;

  insert into private.worker_jobs (
    job_kind,
    worker_runtime,
    worker_queue,
    priority,
    queue_key,
    subject_type,
    requester_type,
    requested_by,
    concurrency_key,
    status,
    phase,
    progress,
    visibility,
    max_attempts,
    payload_schema_version,
    payload_json,
    result_schema_version
  ) values (
    'review.quality_diagnostic',
    'calculator',
    'review_quality',
    20,
    'review-admin',
    'pending_review',
    'user',
    v_actor,
    v_concurrency_key,
    'queued',
    'pending_review_snapshot',
    0,
    'operator',
    3,
    'review.quality_diagnostic.request.v1',
    jsonb_build_object(
      'scope', jsonb_build_object(
        'kind', 'pending_review',
        'reviewStates', jsonb_build_array(0, 1)
      ),
      'requestedAt', now()
    ),
    'review.quality_diagnostic.report.v1'
  )
  returning * into v_job;

  insert into private.worker_job_events (
    job_id,
    event_type,
    status,
    phase,
    progress,
    details
  ) values (
    v_job.id,
    'enqueued',
    v_job.status,
    v_job.phase,
    v_job.progress,
    jsonb_build_object(
      'jobKind', v_job.job_kind,
      'scopeKind', 'pending_review',
      'requestedByReviewAdmin', true
    )
  );

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  ) values (
    'cmd_review_quality_diagnostic_start',
    v_actor,
    'reviews',
    null,
    null,
    jsonb_build_object(
      'run_id', v_job.id,
      'scope_kind', 'pending_review'
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', private.review_quality_diagnostic_projection(v_job),
    'reused', false
  );
exception
  when unique_violation then
    select job.*
    into v_job
    from private.worker_jobs as job
    where job.job_kind = 'review.quality_diagnostic'
      and job.concurrency_key = v_concurrency_key
      and job.status in ('queued', 'running', 'waiting', 'stale')
    order by job.created_at desc, job.id desc
    limit 1;

    if found then
      return jsonb_build_object(
        'ok', true,
        'data', private.review_quality_diagnostic_projection(v_job),
        'reused', true
      );
    end if;

    raise;
end;
$$;


ALTER FUNCTION api.cmd_review_quality_diagnostic_start() OWNER TO postgres;

--
-- Name: FUNCTION cmd_review_quality_diagnostic_start(); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_review_quality_diagnostic_start() IS 'Manually starts or reuses the active pending-review quality diagnostic. Review Admin only; the run is informational and cannot block review workflow actions.';


--
-- Name: cmd_review_ref_type_to_table(text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_ref_type_to_table(p_ref_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select case lower(trim(coalesce(p_ref_type, '')))
    when 'contact data set' then 'contacts'
    when 'source data set' then 'sources'
    when 'unit group data set' then 'unitgroups'
    when 'flow property data set' then 'flowproperties'
    when 'flow data set' then 'flows'
    when 'process data set' then 'processes'
    when 'lifecyclemodel data set' then 'lifecyclemodels'
    when 'lifecycle model data set' then 'lifecyclemodels'
    when 'lifecyclemodel dataset' then 'lifecyclemodels'
    else null
  end
$$;


ALTER FUNCTION api.cmd_review_ref_type_to_table(p_ref_type text) OWNER TO postgres;

--
-- Name: cmd_review_reject(text, uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_reject(p_table text, p_review_id uuid, p_reason text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_root_table text;
  v_root_targets jsonb;
  v_comment_ref_roots jsonb := '[]'::jsonb;
  v_target record;
  v_comment_ref record;
  v_review_json jsonb;
  v_affected_datasets jsonb := '[]'::jsonb;
  v_retained_datasets jsonb := '[]'::jsonb;
  v_unverifiable_datasets jsonb := '[]'::jsonb;
  v_other_active_review_ids jsonb := '[]'::jsonb;
  v_unverifiable_review_refs jsonb := '[]'::jsonb;
  v_has_current_review_ref boolean := false;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not api.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Only review admins can reject reviews'
    );
  end if;

  v_root_table := lower(coalesce(p_table, ''));
  if v_root_table not in ('processes', 'lifecyclemodels') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_TABLE',
      'status', 400,
      'message', 'table must be processes or lifecyclemodels'
    );
  end if;

  select *
    into v_review
  from private.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code not in (-1, 0, 1) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Only pending, assigned, or rejected reviews can be rejected',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  v_root_targets := jsonb_build_array(
    jsonb_build_object(
      'table', v_root_table,
      'id', v_review.data_id,
      'version', v_review.data_version,
      'is_root', true
    )
  );

  create temporary table if not exists cmd_review_reject_targets (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    state_code integer not null,
    reviews jsonb,
    dataset_row jsonb not null,
    is_root boolean not null default false,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  truncate table cmd_review_reject_targets;

  insert into cmd_review_reject_targets (
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  )
  select
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  from api.cmd_review_collect_dataset_targets(v_root_targets, true);

  for v_comment_ref in
    select distinct
      ref.ref_type,
      ref.ref_object_id,
      ref.ref_version
    from private.comments as c
    cross join lateral api.cmd_review_extract_refs(coalesce(to_jsonb(c.json), '{}'::jsonb)) as ref
    where c.review_id = p_review_id
      and c.state_code <> -2
  loop
    v_comment_ref_roots := v_comment_ref_roots || jsonb_build_array(
      jsonb_build_object(
        'table', api.cmd_review_ref_type_to_table(v_comment_ref.ref_type),
        'id', v_comment_ref.ref_object_id,
        'version', v_comment_ref.ref_version,
        'is_root', false
      )
    );
  end loop;

  insert into cmd_review_reject_targets (
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  )
  select
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  from api.cmd_review_collect_dataset_targets(v_comment_ref_roots, true)
  on conflict (table_name, dataset_id, dataset_version) do nothing;

  for v_target in
    select *
    from cmd_review_reject_targets
    where state_code >= 20
      and state_code < 100
    order by table_name, dataset_id, dataset_version
  loop
    if not v_target.is_root then
      v_other_active_review_ids := '[]'::jsonb;
      v_unverifiable_review_refs := '[]'::jsonb;
      v_has_current_review_ref := false;

      if jsonb_typeof(v_target.reviews) is distinct from 'array' then
        v_unverifiable_review_refs := jsonb_build_array(
          jsonb_build_object(
            'reason', 'REVIEWS_NOT_ARRAY',
            'reviews', coalesce(v_target.reviews, 'null'::jsonb)
          )
        );
      elsif jsonb_array_length(v_target.reviews) = 0 then
        v_unverifiable_review_refs := jsonb_build_array(
          jsonb_build_object(
            'reason', 'REVIEWS_EMPTY'
          )
        );
      else
        with review_refs as (
          select
            entry.value as review_ref,
            entry.ordinality,
            case
              when jsonb_typeof(entry.value) = 'object'
                and jsonb_typeof(entry.value->'id') = 'string'
                and (entry.value->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (entry.value->>'id')::uuid
              else null
            end as review_id
          from jsonb_array_elements(v_target.reviews)
            with ordinality as entry(value, ordinality)
        ),
        resolved_review_refs as (
          select
            review_refs.review_ref,
            review_refs.ordinality,
            review_refs.review_id,
            linked_review.id is not null as is_resolved
          from review_refs
          left join private.reviews as linked_review
            on linked_review.id = review_refs.review_id
        )
        select
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'ordinal', ordinality,
                'review_ref', review_ref,
                'reason', case
                  when review_id is null then 'INVALID_REVIEW_REF'
                  else 'REVIEW_NOT_FOUND'
                end
              )
              order by ordinality
            ) filter (where review_id is null or not is_resolved),
            '[]'::jsonb
          ),
          coalesce(bool_or(review_id = p_review_id), false)
        into
          v_unverifiable_review_refs,
          v_has_current_review_ref
        from resolved_review_refs;

        if not v_has_current_review_ref then
          v_unverifiable_review_refs := v_unverifiable_review_refs || jsonb_build_array(
            jsonb_build_object(
              'reason', 'CURRENT_REVIEW_REF_MISSING',
              'review_id', p_review_id
            )
          );
        end if;
      end if;

      if jsonb_array_length(v_unverifiable_review_refs) > 0 then
        v_retained_datasets := v_retained_datasets || jsonb_build_array(
          jsonb_build_object(
            'table', v_target.table_name,
            'id', v_target.dataset_id,
            'version', v_target.dataset_version,
            'state_code', v_target.state_code,
            'reason', 'UNVERIFIABLE_REVIEW_LINKS',
            'unverifiable_review_refs', v_unverifiable_review_refs
          )
        );
        v_unverifiable_datasets := v_unverifiable_datasets || jsonb_build_array(
          jsonb_build_object(
            'table', v_target.table_name,
            'id', v_target.dataset_id,
            'version', v_target.dataset_version,
            'state_code', v_target.state_code,
            'unverifiable_review_refs', v_unverifiable_review_refs
          )
        );
        continue;
      end if;

      select coalesce(
        jsonb_agg(to_jsonb(active_review.review_id) order by active_review.review_id),
        '[]'::jsonb
      )
        into v_other_active_review_ids
      from (
        select distinct linked_review.id::text as review_id
        from jsonb_array_elements(v_target.reviews) as review_ref(value)
        join private.reviews as linked_review
          on linked_review.id = (review_ref.value->>'id')::uuid
        where linked_review.id <> p_review_id
          and linked_review.state_code in (0, 1)
      ) as active_review;

      if jsonb_array_length(v_other_active_review_ids) > 0 then
        v_retained_datasets := v_retained_datasets || jsonb_build_array(
          jsonb_build_object(
            'table', v_target.table_name,
            'id', v_target.dataset_id,
            'version', v_target.dataset_version,
            'state_code', v_target.state_code,
            'reason', 'OTHER_ACTIVE_REVIEWS',
            'active_review_ids', v_other_active_review_ids
          )
        );
        continue;
      end if;
    end if;

    execute format(
      'update public.%I
          set state_code = 0,
              modified_at = now()
        where id = $1
          and version = $2',
      v_target.table_name
    )
      using v_target.dataset_id, v_target.dataset_version;

    v_affected_datasets := v_affected_datasets || jsonb_build_array(
      jsonb_build_object(
        'table', v_target.table_name,
        'id', v_target.dataset_id,
        'version', v_target.dataset_version,
        'previous_state_code', v_target.state_code,
        'state_code', 0
      )
    );
  end loop;

  update private.comments
    set state_code = -1,
        modified_at = now()
  where review_id = p_review_id
    and state_code <> -2;

  v_review_json := coalesce(v_review.json, '{}'::jsonb);
  v_review_json := jsonb_set(
    v_review_json,
    '{comment}',
    coalesce(v_review_json->'comment', '{}'::jsonb) || jsonb_build_object(
      'message', coalesce(p_reason, '')
    ),
    true
  );
  v_review_json := api.cmd_review_append_log(
    v_review_json,
    'rejected',
    v_actor,
    jsonb_build_object(
      'reason', coalesce(p_reason, '')
    )
  );

  update private.reviews
    set state_code = -1,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_reject',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'root_table', v_root_table,
      'reason', coalesce(p_reason, ''),
      'active_review_state_codes', jsonb_build_array(0, 1),
      'affected_datasets', v_affected_datasets,
      'retained_datasets', v_retained_datasets,
      'unverifiable_datasets', v_unverifiable_datasets
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review),
      'affected_datasets', v_affected_datasets,
      'retained_datasets', v_retained_datasets,
      'unverifiable_datasets', v_unverifiable_datasets
    )
  );
end;
$_$;


ALTER FUNCTION api.cmd_review_reject(p_table text, p_review_id uuid, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_review_reject(p_table text, p_review_id uuid, p_reason text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_review_reject(p_table text, p_review_id uuid, p_reason text, p_audit jsonb) IS 'Rejects an admin-managed review while retaining non-root under-review datasets still occupied by another active review; unverifiable review links fail closed and are audited.';


--
-- Name: cmd_review_resolve_queue_order_by(text, boolean); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_resolve_queue_order_by(p_sort_by text, p_allow_comment_modified boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
begin
  case lower(coalesce(p_sort_by, ''))
    when 'created_at' then
      return 'q.created_at';
    when 'createat' then
      return 'q.created_at';
    when 'deadline' then
      return 'q.deadline';
    when 'state_code' then
      return 'q.state_code';
    when 'statecode' then
      return 'q.state_code';
    when 'comment_modified_at' then
      if p_allow_comment_modified then
        return 'q.comment_modified_at';
      end if;
    when 'commentmodifiedat' then
      if p_allow_comment_modified then
        return 'q.comment_modified_at';
      end if;
    else
      return 'q.modified_at';
  end case;

  return 'q.modified_at';
end;
$$;


ALTER FUNCTION api.cmd_review_resolve_queue_order_by(p_sort_by text, p_allow_comment_modified boolean) OWNER TO postgres;

--
-- Name: cmd_review_revoke_reviewer(uuid, uuid, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_revoke_reviewer(p_review_id uuid, p_reviewer_id uuid, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_comment private.comments%rowtype;
  v_remaining_reviewer_ids jsonb;
  v_review_json jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not api.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Only review admins can revoke reviewers'
    );
  end if;

  select *
    into v_review
  from private.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Reviewers can only be revoked from assigned reviews',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  if not api.cmd_review_json_array(v_review.reviewer_id) @> jsonb_build_array(to_jsonb(p_reviewer_id::text)) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_NOT_ASSIGNED',
      'status', 409,
      'message', 'Reviewer is not currently assigned to this review'
    );
  end if;

  select *
    into v_comment
  from private.comments
  where review_id = p_review_id
    and reviewer_id = p_reviewer_id
  for update;

  if found and v_comment.state_code <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_ALREADY_RESPONDED',
      'status', 409,
      'message', 'Only pending reviewers can be revoked',
      'details', jsonb_build_object(
        'comment_state_code', v_comment.state_code
      )
    );
  end if;

  select coalesce(
    jsonb_agg(to_jsonb(value) order by ordinality),
    '[]'::jsonb
  )
    into v_remaining_reviewer_ids
  from jsonb_array_elements_text(api.cmd_review_json_array(v_review.reviewer_id))
       with ordinality as reviewer_ids(value, ordinality)
  where reviewer_ids.value <> p_reviewer_id::text;

  v_review_json := api.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    'revoke_reviewer',
    v_actor,
    jsonb_build_object(
      'reviewer_id', p_reviewer_id
    )
  );

  update private.reviews
    set reviewer_id = v_remaining_reviewer_ids,
        state_code = case
          when jsonb_array_length(v_remaining_reviewer_ids) = 0 then 0
          else 1
        end,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  update private.comments
    set state_code = -2,
        modified_at = now()
  where review_id = p_review_id
    and reviewer_id = p_reviewer_id;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_revoke_reviewer',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'reviewer_id', p_reviewer_id,
      'remaining_reviewer_ids', v_remaining_reviewer_ids
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review)
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_review_revoke_reviewer(p_review_id uuid, p_reviewer_id uuid, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_save_assignment_draft(uuid, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_save_assignment_draft(p_review_id uuid, p_reviewer_ids jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_reviewer_ids jsonb;
  v_review_json jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not api.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Only review admins can manage reviewer assignments'
    );
  end if;

  if coalesce(jsonb_typeof(p_reviewer_ids), 'null') not in ('null', 'array') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEWER_IDS',
      'status', 400,
      'message', 'reviewerIds must be an array of UUID strings'
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements_text(coalesce(p_reviewer_ids, '[]'::jsonb)) as reviewer_ids(value)
    where reviewer_ids.value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEWER_IDS',
      'status', 400,
      'message', 'reviewerIds must contain valid UUID strings only'
    );
  end if;

  v_reviewer_ids := api.cmd_review_normalize_reviewer_ids(coalesce(p_reviewer_ids, '[]'::jsonb));

  select *
    into v_review
  from private.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code not in (-1, 0, 1) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Reviewer assignments can only be changed for unassigned or active reviews',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  v_review_json := api.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    'assign_reviewers_temporary',
    v_actor,
    jsonb_build_object(
      'reviewer_ids', v_reviewer_ids
    )
  );

  update private.reviews
    set reviewer_id = v_reviewer_ids,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_save_assignment_draft',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'reviewer_ids', v_reviewer_ids
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review)
    )
  );
end;
$_$;


ALTER FUNCTION api.cmd_review_save_assignment_draft(p_review_id uuid, p_reviewer_ids jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_save_comment_draft(uuid, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_save_comment_draft(p_review_id uuid, p_json jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_comment private.comments%rowtype;
  v_comment_json jsonb := coalesce(p_json, '{}'::jsonb);
  v_review_json jsonb;
begin
  if v_actor is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if coalesce(pg_catalog.jsonb_typeof(v_comment_json), 'null') <> 'object' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'INVALID_COMMENT_JSON',
      'status', 400,
      'message', 'comment json must be an object'
    );
  end if;

  select review_row.*
  into v_review
  from private.reviews as review_row
  where review_row.id = p_review_id
  for update;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code not in (-1, 1) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Review comments can only be edited for assigned or rejected reviews',
      'details', pg_catalog.jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  if not api.cmd_review_json_array(v_review.reviewer_id)
    @> pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(v_actor::text)) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_REQUIRED',
      'status', 403,
      'message', 'Only assigned reviewers can edit review comments'
    );
  end if;

  select comment_row.*
  into v_comment
  from private.comments as comment_row
  where comment_row.review_id = p_review_id
    and comment_row.reviewer_id = v_actor
  for update;

  if found and v_comment.state_code in (-2, 2) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'INVALID_COMMENT_STATE',
      'status', 409,
      'message', 'This reviewer comment can no longer be edited',
      'details', pg_catalog.jsonb_build_object(
        'state_code', v_comment.state_code
      )
    );
  end if;

  if v_comment.review_id is null then
    insert into private.comments (
      review_id,
      reviewer_id,
      json,
      state_code
    )
    values (
      p_review_id,
      v_actor,
      v_comment_json::json,
      case
        when v_review.state_code = -1 then -1
        else 0
      end
    )
    returning * into v_comment;
  else
    update private.comments
    set json = v_comment_json::json,
        modified_at = pg_catalog.now()
    where review_id = p_review_id
      and reviewer_id = v_actor
    returning * into v_comment;
  end if;

  v_review_json := api.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    'submit_comments_temporary',
    v_actor,
    pg_catalog.jsonb_build_object('reviewer_id', v_actor)
  );

  update private.reviews
  set json = v_review_json,
      modified_at = pg_catalog.now()
  where id = p_review_id
  returning * into v_review;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_save_comment_draft',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || pg_catalog.jsonb_build_object(
      'reviewer_id', v_actor,
      'comment_state_code', v_comment.state_code
    )
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'data', pg_catalog.jsonb_build_object(
      'review', pg_catalog.to_jsonb(v_review),
      'comment', pg_catalog.to_jsonb(v_comment)
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_review_save_comment_draft(p_review_id uuid, p_json jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_review_save_comment_draft(p_review_id uuid, p_json jsonb, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_review_save_comment_draft(p_review_id uuid, p_json jsonb, p_audit jsonb) IS 'Temporarily stores editable reviewer Comment JSON and audit metadata without provisioning Reference Reviews or Root candidate hints.';


--
-- Name: cmd_review_submit(text, uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_submit(p_target_table text, p_target_id uuid, p_target_version text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_table text := lower(coalesce(p_target_table, ''));
  v_root_row jsonb;
  v_checksum text;
  v_root_review_id uuid := gen_random_uuid();
  v_root_review private.reviews%rowtype;
  v_reference private.reviews%rowtype;
  v_target record;
  v_target_checksum text;
  v_affected jsonb := '[]'::jsonb;
  v_event_key text;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if v_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table for review submission'
    );
  end if;

  v_root_row := api.cmd_review_get_dataset_row(
    v_table,
    p_target_id,
    p_target_version,
    true
  );

  if v_root_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  if nullif(v_root_row->>'user_id', '')::uuid is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'ROOT_DATASET_NOT_OWNED',
      'status', 403,
      'message', 'Only the dataset owner can submit review'
    );
  end if;

  if coalesce((v_root_row->>'state_code')::integer, 0) <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', case
        when coalesce((v_root_row->>'state_code')::integer, 0) = 100
          then 'APPROVED_DATASET_IMMUTABLE'
        else 'DATA_UNDER_REVIEW'
      end,
      'status', 409,
      'message', 'Only a Draft dataset can be submitted'
    );
  end if;

  v_checksum := private.review_revision_fingerprint_v1(v_table, v_root_row);

  if exists (
    select 1
    from private.review_candidate_root_ids_v1(
      v_table,
      p_target_id,
      p_target_version
    ) as candidate
    where private.review_root_currently_references_target_v1(
      candidate.root_review_id,
      v_table,
      p_target_id,
      p_target_version
    )
  ) then
    v_reference := private.review_get_or_create_reference_v1(
      v_table,
      v_root_row,
      v_checksum,
      v_actor
    );

    perform set_config('app.review_controlled_write', 'on', true);
    execute format(
      'update public.%I
          set state_code = 20,
              modified_at = now()
        where id = $1
          and version = $2
          and state_code = 0',
      v_table
    ) using p_target_id, p_target_version;
    perform set_config('app.review_controlled_write', 'off', true);

    insert into private.command_audit_log (
      command, actor_user_id, target_table, target_id, target_version, payload
    ) values (
      'cmd_review_submit', v_actor, v_table, p_target_id, p_target_version,
      coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
        'review_id', v_reference.id,
        'review_kind', 'reference',
        'submission_mode', 'reference_repair'
      )
    );

    return jsonb_build_object(
      'ok', true,
      'data', jsonb_build_object(
        'reviewId', v_reference.id,
        'reviewKind', 'reference',
        'submissionMode', 'reference_repair'
      )
    );
  end if;

  if exists (
    select 1
    from private.reviews as active_root
    where active_root.review_kind = 'root'
      and active_root.target_table = v_table
      and active_root.data_id = p_target_id
      and btrim(active_root.data_version::text) = p_target_version
      and active_root.state_code in (0, 1)
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 409,
      'message', 'An active Root Review already exists'
    );
  end if;

  create temporary table if not exists review_submit_targets (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    state_code integer not null,
    reviews jsonb,
    dataset_row jsonb not null,
    is_root boolean not null default false,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;
  truncate table review_submit_targets;

  insert into review_submit_targets
  select *
  from api.cmd_review_collect_dataset_targets(
    jsonb_build_array(jsonb_build_object(
      'table', v_table,
      'id', p_target_id,
      'version', p_target_version,
      'is_root', true
    )),
    true
  );

  if not exists (
    select 1
    from review_submit_targets
    where is_root
      and table_name = v_table
      and dataset_id = p_target_id
      and dataset_version = p_target_version
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  for v_target in
    select *
    from review_submit_targets
    order by is_root desc, table_name, dataset_id, dataset_version
  loop
    if nullif(v_target.dataset_row->>'user_id', '') is null
      and (v_target.is_root or v_target.state_code < 100) then
      return jsonb_build_object(
        'ok', false,
        'code', case when v_target.is_root
          then 'ROOT_OWNER_UNRESOLVED'
          else 'REFERENCE_OWNER_UNRESOLVED'
        end,
        'status', 409,
        'message', 'Dataset owner could not be resolved'
      );
    end if;

    if not v_target.is_root
      and nullif(v_target.dataset_row->>'user_id', '')::uuid <> v_actor
      and not private.review_dataset_can_read_v1(
        v_actor,
        v_target.table_name,
        v_target.dataset_row
      ) then
      return jsonb_build_object(
        'ok', false,
        'code', 'REFERENCE_ACCESS_DENIED',
        'status', 403,
        'message', 'A referenced dataset is not accessible'
      );
    end if;

    v_target_checksum := private.review_revision_fingerprint_v1(
      v_target.table_name,
      v_target.dataset_row
    );

    if not v_target.is_root then
      v_reference := private.review_get_or_create_reference_v1(
        v_target.table_name,
        v_target.dataset_row,
        v_target_checksum,
        v_actor
      );
    end if;
  end loop;

  insert into private.reviews (
    id,
    data_id,
    data_version,
    state_code,
    reviewer_id,
    json,
    review_kind,
    target_table,
    submitted_revision_checksum,
    target_owner_id,
    target_team_id
  )
  values (
    v_root_review_id,
    p_target_id,
    p_target_version,
    0,
    '[]'::jsonb,
    private.review_build_json_v1(
      v_table,
      v_root_row,
      v_actor,
      'submit_review',
      v_actor
    ),
    'root',
    v_table,
    v_checksum,
    v_actor,
    nullif(v_root_row->>'team_id', '')::uuid
  )
  returning * into v_root_review;

  perform set_config('app.review_controlled_write', 'on', true);
  for v_target in
    select *
    from review_submit_targets
    order by is_root desc, table_name, dataset_id, dataset_version
  loop
    execute format(
      'update public.%I
          set state_code = case when state_code < 20 then 20 else state_code end,
              reviews = case
                when state_code < 100
                  then api.cmd_review_append_review_ref(reviews, $1)
                else reviews
              end,
              modified_at = now()
        where id = $2
          and version = $3',
      v_target.table_name
    ) using v_root_review_id, v_target.dataset_id, v_target.dataset_version;

    if not v_target.is_root
      and v_target.state_code < 20
      and nullif(v_target.dataset_row->>'user_id', '')::uuid <> v_actor then
      v_event_key := private.review_notify_event_v1(
        'reference_entered_review',
        (
          select reference_review.id
          from private.reviews as reference_review
          where reference_review.review_kind = 'reference'
            and reference_review.target_table = v_target.table_name
            and reference_review.data_id = v_target.dataset_id
            and btrim(reference_review.data_version::text) = v_target.dataset_version
            and reference_review.submitted_revision_checksum =
              private.review_revision_fingerprint_v1(
                v_target.table_name,
                v_target.dataset_row
              )
            and reference_review.state_code in (-1, 0, 1, 2)
          order by case when reference_review.state_code in (0, 1, 2) then 0 else 1 end,
                   reference_review.modified_at desc,
                   reference_review.id
          limit 1
        ),
        nullif(v_target.dataset_row->>'user_id', '')::uuid,
        v_actor,
        v_target.table_name,
        v_target.dataset_id,
        v_target.dataset_version,
        null,
        null,
        null
      );
    end if;

    v_affected := v_affected || jsonb_build_array(jsonb_build_object(
      'table', v_target.table_name,
      'id', v_target.dataset_id,
      'version', v_target.dataset_version,
      'previous_state_code', v_target.state_code,
      'state_code', case
        when v_target.state_code < 20 then 20
        else v_target.state_code
      end
    ));
  end loop;
  perform set_config('app.review_controlled_write', 'off', true);

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_review_submit',
    v_actor,
    v_table,
    p_target_id,
    p_target_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'review_id', v_root_review_id,
      'review_kind', 'root',
      'submission_mode', 'root',
      'affected_datasets', v_affected
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'reviewId', v_root_review_id,
      'reviewKind', 'root',
      'submissionMode', 'root',
      'review', to_jsonb(v_root_review),
      'affectedDatasets', v_affected
    )
  );
exception
  when others then
    perform set_config('app.review_controlled_write', 'off', true);
    if sqlerrm = 'REFERENCE_OWNER_UNRESOLVED' then
      return jsonb_build_object(
        'ok', false,
        'code', sqlerrm,
        'status', 409,
        'message', 'Review submission could not be completed'
      );
    end if;
    raise;
end;
$_$;


ALTER FUNCTION api.cmd_review_submit(p_target_table text, p_target_id uuid, p_target_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_review_submit(p_target_table text, p_target_id uuid, p_target_version text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_review_submit(p_target_table text, p_target_id uuid, p_target_version text, p_audit jsonb) IS 'Stable review-submission command. It enforces authentication, ownership, lifecycle, optimistic target, and transactional review invariants but does not run or require upstream completeness or numerical-quality diagnostics.';


--
-- Name: cmd_review_submit_comment(uuid, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_submit_comment(p_review_id uuid, p_json jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select api.cmd_review_submit_comment(
    p_review_id,
    p_json,
    1,
    p_audit
  )
$$;


ALTER FUNCTION api.cmd_review_submit_comment(p_review_id uuid, p_json jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_submit_comment(uuid, jsonb, integer, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_review_submit_comment(p_review_id uuid, p_json jsonb, p_comment_state integer DEFAULT 1, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_comment private.comments%rowtype;
  v_ref record;
  v_target record;
  v_reference private.reviews%rowtype;
  v_ref_roots jsonb := '[]'::jsonb;
  v_checksum text;
  v_affected jsonb := '[]'::jsonb;
  v_reason text;
begin
  select review_row.*
  into v_review
  from private.reviews as review_row
  where review_row.id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404
    );
  end if;

  if v_review.review_kind is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'LEGACY_REVIEW_READ_ONLY',
      'status', 409
    );
  end if;

  if v_review.review_kind = 'reference'
    or v_review.target_table in (
      'contacts',
      'sources',
      'unitgroups',
      'flowproperties',
      'flows'
    ) then
    v_reason := coalesce(
      p_json->'comment'->>'message',
      p_json->>'reason'
    );
    return api.cmd_simple_review_submit_decision(
      p_review_id,
      case when p_comment_state = 1 then 'approve' else 'reject' end,
      case when p_comment_state = -3 then v_reason else null end,
      p_audit
    );
  end if;

  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401
    );
  end if;

  if v_review.review_kind <> 'root'
    or v_review.target_table not in ('processes', 'lifecyclemodels') then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_METADATA_NOT_APPLICABLE',
      'status', 400
    );
  end if;

  if v_review.state_code <> 1
    or p_comment_state not in (-3, 1)
    or not coalesce(v_review.reviewer_id, '[]'::jsonb)
      @> jsonb_build_array(v_actor::text) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_REQUIRED',
      'status', 403
    );
  end if;

  select comment_row.*
  into v_comment
  from private.comments as comment_row
  where comment_row.review_id = p_review_id
    and comment_row.reviewer_id = v_actor
  for update;

  if found and v_comment.state_code in (-2, 2) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_COMMENT_STATE',
      'status', 409
    );
  end if;

  if p_comment_state = 1 then
    for v_ref in
      select *
      from api.cmd_review_extract_refs(coalesce(p_json, '{}'::jsonb))
    loop
      if api.cmd_review_ref_type_to_table(v_ref.ref_type) is not null then
        v_ref_roots := v_ref_roots || jsonb_build_array(jsonb_build_object(
          'table', api.cmd_review_ref_type_to_table(v_ref.ref_type),
          'id', v_ref.ref_object_id,
          'version', v_ref.ref_version,
          'is_root', false
        ));
      end if;
    end loop;

    create temporary table if not exists review_comment_v2_targets (
      table_name text not null,
      dataset_id uuid not null,
      dataset_version text not null,
      state_code integer not null,
      reviews jsonb,
      dataset_row jsonb not null,
      is_root boolean not null default false,
      primary key (table_name, dataset_id, dataset_version)
    ) on commit drop;
    truncate table review_comment_v2_targets;

    insert into review_comment_v2_targets
    select *
    from api.cmd_review_collect_dataset_targets(v_ref_roots, true);

    for v_target in
      select *
      from review_comment_v2_targets
      order by table_name, dataset_id, dataset_version
    loop
      if nullif(v_target.dataset_row->>'user_id', '') is null
        and v_target.state_code < 100 then
        return jsonb_build_object(
          'ok', false,
          'code', 'REFERENCE_OWNER_UNRESOLVED',
          'status', 409
        );
      end if;

      if nullif(v_target.dataset_row->>'user_id', '')::uuid <> v_actor
        and not private.review_dataset_can_read_v1(
          v_actor,
          v_target.table_name,
          v_target.dataset_row
        ) then
        return jsonb_build_object(
          'ok', false,
          'code', 'REFERENCE_ACCESS_DENIED',
          'status', 403
        );
      end if;

      v_checksum := private.review_revision_fingerprint_v1(
        v_target.table_name,
        v_target.dataset_row
      );
      v_reference := private.review_get_or_create_reference_v1(
        v_target.table_name,
        v_target.dataset_row,
        v_checksum,
        v_actor
      );

      perform set_config('app.review_controlled_write', 'on', true);
      execute format(
        'update public.%I
            set state_code = case when state_code < 20 then 20 else state_code end,
                reviews = case when state_code < 100
                  then api.cmd_review_append_review_ref(reviews, $1)
                  else reviews
                end,
                modified_at = now()
          where id = $2
            and version = $3',
        v_target.table_name
      ) using p_review_id, v_target.dataset_id, v_target.dataset_version;
      perform set_config('app.review_controlled_write', 'off', true);

      if v_target.state_code < 20
        and nullif(v_target.dataset_row->>'user_id', '')::uuid <> v_actor then
        perform private.review_notify_event_v1(
          'reference_entered_review',
          v_reference.id,
          nullif(v_target.dataset_row->>'user_id', '')::uuid,
          v_actor,
          v_target.table_name,
          v_target.dataset_id,
          v_target.dataset_version,
          null,
          null,
          null
        );
      end if;

      v_affected := v_affected || jsonb_build_array(jsonb_build_object(
        'table', v_target.table_name,
        'id', v_target.dataset_id,
        'version', v_target.dataset_version,
        'reference_review_id', v_reference.id
      ));
    end loop;

  end if;

  insert into private.comments (
    review_id,
    reviewer_id,
    json,
    state_code
  )
  values (
    p_review_id,
    v_actor,
    coalesce(p_json, '{}'::jsonb)::json,
    p_comment_state
  )
  on conflict (review_id, reviewer_id) do update
  set json = excluded.json,
      state_code = excluded.state_code,
      modified_at = now()
  returning * into v_comment;

  update private.reviews
  set json = api.cmd_review_append_log(
        coalesce(json, '{}'::jsonb),
        case when p_comment_state = 1
          then 'submit_comments'
          else 'reviewer_rejected'
        end,
        v_actor,
        jsonb_build_object(
          'reviewer_id', v_actor,
          'comment_state_code', p_comment_state
        )
      ),
      modified_at = now()
  where id = p_review_id
  returning * into v_review;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_submit_comment',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'reviewer_id', v_actor,
      'comment_state_code', p_comment_state,
      'affected_datasets', (
        select coalesce(
          jsonb_agg(affected.value - 'reference_review_id'),
          '[]'::jsonb
        )
        from jsonb_array_elements(v_affected) as affected(value)
      )
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review),
      'comment', to_jsonb(v_comment),
      'affected_datasets', v_affected
    )
  );
exception
  when others then
    perform set_config('app.review_controlled_write', 'off', true);
    raise;
end;
$_$;


ALTER FUNCTION api.cmd_review_submit_comment(p_review_id uuid, p_json jsonb, p_comment_state integer, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_reviewer_submit_decision(uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_reviewer_submit_decision(p_review_id uuid, p_decision text, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_comment private.comments%rowtype;
  v_decision text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_decision, '')));
  v_reason text := pg_catalog.btrim(coalesce(p_reason, ''));
  v_comment_json jsonb;
  v_is_simple boolean;
begin
  if v_actor is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if v_decision not in ('approve', 'reject') then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_DECISION_INVALID',
      'status', 400,
      'message', 'decision must be approve or reject'
    );
  end if;

  if v_decision = 'approve' and v_reason <> '' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_DECISION_PAYLOAD_INVALID',
      'status', 400,
      'message', 'approve does not accept a reason'
    );
  end if;

  if v_decision = 'reject' and v_reason = '' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_REJECT_REASON_REQUIRED',
      'status', 400,
      'message', 'reason is required for reject'
    );
  end if;

  if pg_catalog.length(v_reason) > 1000 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_REJECT_REASON_TOO_LONG',
      'status', 400,
      'message', 'reason must not exceed 1000 characters'
    );
  end if;

  select review_row.*
  into v_review
  from private.reviews as review_row
  where review_row.id = p_review_id
  for update;

  if not found or v_review.review_kind not in ('root', 'reference') then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code <> 1
    or not api.cmd_review_json_array(v_review.reviewer_id)
      @> pg_catalog.jsonb_build_array(pg_catalog.to_jsonb(v_actor::text)) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_REQUIRED',
      'status', 403,
      'message', 'Only an assigned reviewer can submit a pending decision'
    );
  end if;

  select comment_row.*
  into v_comment
  from private.comments as comment_row
  where comment_row.review_id = p_review_id
    and comment_row.reviewer_id = v_actor
  for update;

  if not found or v_comment.state_code <> 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_COMMENT_NOT_PENDING',
      'status', 409,
      'message', 'Reviewer decision is no longer pending'
    );
  end if;

  v_is_simple := v_review.review_kind = 'reference'
    or v_review.target_table in (
      'contacts',
      'sources',
      'unitgroups',
      'flowproperties',
      'flows'
    );

  if v_is_simple then
    return api.cmd_simple_review_submit_decision(
      p_review_id,
      v_decision,
      case when v_decision = 'reject' then v_reason else null end,
      coalesce(p_audit, '{}'::jsonb)
        || pg_catalog.jsonb_build_object('reviewer_decision_command', true)
    );
  end if;

  v_comment_json := coalesce(pg_catalog.to_jsonb(v_comment.json), '{}'::jsonb);

  if v_decision = 'approve' and v_comment_json = '{}'::jsonb then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_DRAFT_REQUIRED',
      'status', 409,
      'message', 'Process and LifecycleModel approvals require a saved review draft'
    );
  end if;

  if v_decision = 'reject' then
    v_comment_json := pg_catalog.jsonb_set(
      v_comment_json,
      '{comment}',
      coalesce(v_comment_json->'comment', '{}'::jsonb)
        || pg_catalog.jsonb_build_object('message', v_reason),
      true
    );
  end if;

  return api.cmd_review_submit_comment(
    p_review_id,
    v_comment_json,
    case when v_decision = 'approve' then 1 else -3 end,
    coalesce(p_audit, '{}'::jsonb)
      || pg_catalog.jsonb_build_object('reviewer_decision_command', true)
  );
end;
$$;


ALTER FUNCTION api.cmd_reviewer_submit_decision(p_review_id uuid, p_decision text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_reviewer_submit_decision(p_review_id uuid, p_decision text, p_reason text, p_audit jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.cmd_reviewer_submit_decision(p_review_id uuid, p_decision text, p_reason text, p_audit jsonb) IS 'Submits one assigned reviewer opinion without performing review-admin finalization. Approve records Comment state 1; reject records Comment state -3.';


--
-- Name: cmd_simple_review_submit_decision(uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_simple_review_submit_decision(p_review_id uuid, p_decision text, p_reason text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_comment private.comments%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if v_actor is null then
    return jsonb_build_object('ok', false, 'code', 'AUTH_REQUIRED', 'status', 401);
  end if;

  select review_row.*
  into v_review
  from private.reviews as review_row
  where review_row.id = p_review_id
  for update;

  if not found
    or not (
      v_review.review_kind = 'reference'
      or (
        v_review.review_kind = 'root'
        and v_review.target_table in (
          'contacts',
          'sources',
          'unitgroups',
          'flowproperties',
          'flows'
        )
      )
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SIMPLE_REVIEW_NOT_FOUND',
      'status', 404
    );
  end if;

  if v_review.state_code <> 1
    or not coalesce(v_review.reviewer_id, '[]'::jsonb)
      @> jsonb_build_array(v_actor::text) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_REQUIRED',
      'status', 403
    );
  end if;

  if lower(p_decision) = 'approve' and v_reason <> '' then
    return jsonb_build_object(
      'ok', false,
      'code', 'SIMPLE_REVIEW_DECISION_PAYLOAD_INVALID',
      'status', 400
    );
  elsif lower(p_decision) = 'reject' and v_reason = '' then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_REJECT_REASON_REQUIRED',
      'status', 400
    );
  elsif lower(p_decision) not in ('approve', 'reject') then
    return jsonb_build_object(
      'ok', false,
      'code', 'SIMPLE_REVIEW_DECISION_INVALID',
      'status', 400
    );
  end if;

  insert into private.comments (
    review_id,
    reviewer_id,
    json,
    state_code
  )
  values (
    p_review_id,
    v_actor,
    jsonb_strip_nulls(jsonb_build_object(
      'decision', lower(p_decision),
      'reason', nullif(v_reason, ''),
      'submitted_revision_checksum', v_review.submitted_revision_checksum
    ))::json,
    case when lower(p_decision) = 'approve' then 1 else -3 end
  )
  on conflict (review_id, reviewer_id) do update
  set json = excluded.json,
      state_code = excluded.state_code,
      modified_at = now()
  returning * into v_comment;

  update private.reviews
  set json = api.cmd_review_append_log(
        coalesce(json, '{}'::jsonb),
        case when lower(p_decision) = 'approve'
          then 'simple_reviewer_approved'
          else 'simple_reviewer_rejected'
        end,
        v_actor,
        jsonb_build_object(
          'submitted_revision_checksum',
          v_review.submitted_revision_checksum
        )
      ),
      modified_at = now()
  where id = p_review_id
  returning * into v_review;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_simple_review_submit_decision',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'decision', lower(p_decision),
      'comment_state_code', case
        when lower(p_decision) = 'approve' then 1 else -3
      end
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review),
      'comment', to_jsonb(v_comment)
    )
  );
end;
$$;


ALTER FUNCTION api.cmd_simple_review_submit_decision(p_review_id uuid, p_decision text, p_reason text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_system_change_member_role(uuid, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.cmd_system_change_member_role(p_user_id uuid, p_role text DEFAULT NULL::text, p_action text DEFAULT 'set'::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_action text := lower(coalesce(p_action, 'set'));
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_actor_is_owner boolean;
  v_actor_is_manager boolean;
  v_existing_role text;
  v_role_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object('ok', false, 'code', 'AUTH_REQUIRED', 'status', 401, 'message', 'Authentication required');
  end if;

  if p_user_id is null then
    return jsonb_build_object('ok', false, 'code', 'USER_ID_REQUIRED', 'status', 400, 'message', 'userId is required');
  end if;

  v_actor_is_owner := api.cmd_membership_is_system_owner(v_actor);
  v_actor_is_manager := api.cmd_membership_is_system_manager(v_actor);

  if not v_actor_is_manager then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'status', 403, 'message', 'The actor cannot manage system members');
  end if;

  select role
    into v_existing_role
  from private.roles
  where user_id = p_user_id
    and team_id = v_team_id
  for update;

  if v_action = 'remove' then
    if v_existing_role is null then
      return jsonb_build_object('ok', false, 'code', 'ROLE_NOT_FOUND', 'status', 404, 'message', 'Role not found');
    end if;

    if p_user_id = v_actor or v_existing_role = 'owner' then
      return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'status', 403, 'message', 'The actor cannot remove this system member');
    end if;

    delete from private.roles
    where user_id = p_user_id
      and team_id = v_team_id;

    insert into private.command_audit_log (
      command,
      actor_user_id,
      target_table,
      target_id,
      target_version,
      payload
    )
    values (
      'cmd_system_change_member_role',
      v_actor,
      'roles',
      p_user_id,
      v_team_id::text,
      coalesce(p_audit, '{}'::jsonb) || jsonb_build_object('action', 'remove')
    );

    return jsonb_build_object(
      'ok', true,
      'data', jsonb_build_object('removed', true, 'user_id', p_user_id, 'team_id', v_team_id)
    );
  end if;

  if v_action <> 'set' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ACTION', 'status', 400, 'message', 'Unsupported action');
  end if;

  if p_role not in ('member', 'admin', 'data_product_manager') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ROLE', 'status', 400, 'message', 'Unsupported system role transition');
  end if;

  if p_role = 'admin' and not v_actor_is_owner then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'status', 403, 'message', 'Only the system owner can assign admin roles');
  end if;

  if p_role = 'member' and v_existing_role = 'admin' and not v_actor_is_owner then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'status', 403, 'message', 'Only the system owner can demote an admin');
  end if;

  if v_existing_role is null then
    insert into private.roles (user_id, team_id, role, modified_at)
    values (p_user_id, v_team_id, p_role, now())
    returning to_jsonb(roles.*)
      into v_role_row;
  elsif v_existing_role in ('owner', 'admin', 'member', 'data_product_manager') then
    if v_existing_role = 'owner' then
      return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'status', 403, 'message', 'The owner role cannot be modified');
    end if;

    update private.roles
      set role = p_role,
          modified_at = now()
    where user_id = p_user_id
      and team_id = v_team_id
    returning to_jsonb(roles.*)
      into v_role_row;
  else
    return jsonb_build_object('ok', false, 'code', 'ROLE_CONFLICT', 'status', 409, 'message', 'The existing zero-team role belongs to another scope');
  end if;

  insert into private.command_audit_log (
    command,
    actor_user_id,
