CREATE FUNCTION api.get_latest_process_versions(page_size bigint DEFAULT 10, page_current bigint DEFAULT 1, data_source text DEFAULT 'tg'::text, this_user_id text DEFAULT ''::text, team_id_filter uuid DEFAULT NULL::uuid, state_code_filter integer DEFAULT NULL::integer, type_of_data_set_filter text DEFAULT 'all'::text, sort_by text DEFAULT 'modified_at'::text, sort_direction text DEFAULT 'desc'::text) RETURNS TABLE(id uuid, "json" jsonb, version character, modified_at timestamp with time zone, team_id uuid, model_id uuid, model_version character, total_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    SET statement_timeout TO '60s'
    AS $_$
DECLARE
  normalized_page_size bigint;
  normalized_page_current bigint;
  normalized_sort_by text;
  normalized_sort_direction text;
  normalized_this_user_id uuid;
BEGIN
  normalized_page_size := greatest(coalesce(page_size, 10), 1);
