      FROM public.unitgroups u
      WHERE data_source = 'tg'
        AND u.state_code = 100
        AND (team_id_filter IS NULL OR u.team_id = team_id_filter)
      UNION ALL
      SELECT u.id, u.version, u.created_at, u.modified_at, u.team_id
      FROM public.unitgroups u
      WHERE data_source = 'co'
        AND u.state_code = 200
        AND (team_id_filter IS NULL OR u.team_id = team_id_filter)
      UNION ALL
      SELECT u.id, u.version, u.created_at, u.modified_at, u.team_id
      FROM public.unitgroups u
      WHERE data_source = 'my'
        AND normalized_this_user_id IS NOT NULL
        AND u.user_id = normalized_this_user_id
        AND (state_code_filter IS NULL OR u.state_code = state_code_filter)
      UNION ALL
      SELECT u.id, u.version, u.created_at, u.modified_at, u.team_id
      FROM public.unitgroups u
      WHERE data_source = 'te'
        AND team_id_filter IS NOT NULL
        AND u.team_id = team_id_filter
        AND (state_code_filter IS NULL OR u.state_code = state_code_filter)
    ),
    latest_keys AS (
      SELECT DISTINCT ON (visible_keys.id)
        visible_keys.id,
        visible_keys.version,
        visible_keys.created_at,
        visible_keys.modified_at,
        visible_keys.team_id
      FROM visible_keys
      ORDER BY visible_keys.id, visible_keys.version DESC, visible_keys.modified_at DESC
    ),
    counted_keys AS (
      SELECT latest_keys.*, count(*) OVER()::bigint AS total_count
      FROM latest_keys
    ),
    paged_keys AS (
      SELECT counted_keys.*
      FROM counted_keys
      ORDER BY
        CASE
          WHEN normalized_sort_by = 'version' AND normalized_sort_direction = 'asc' THEN counted_keys.version
        END ASC NULLS LAST,
        CASE
          WHEN normalized_sort_by = 'version' AND normalized_sort_direction <> 'asc' THEN counted_keys.version
        END DESC NULLS LAST,
        CASE
          WHEN normalized_sort_by = 'created_at' AND normalized_sort_direction = 'asc' THEN counted_keys.created_at
        END ASC NULLS LAST,
        CASE
          WHEN normalized_sort_by = 'created_at' AND normalized_sort_direction <> 'asc' THEN counted_keys.created_at
        END DESC NULLS LAST,
        CASE
          WHEN normalized_sort_by = 'modified_at' AND normalized_sort_direction = 'asc' THEN counted_keys.modified_at
        END ASC NULLS LAST,
        CASE
          WHEN normalized_sort_by = 'modified_at' AND normalized_sort_direction <> 'asc' THEN counted_keys.modified_at
        END DESC NULLS LAST,
        counted_keys.id
      LIMIT normalized_page_size
      OFFSET (normalized_page_current - 1) * normalized_page_size
    )
    SELECT
      payload.id,
      payload.json,
      payload.version,
      payload.modified_at,
      payload.team_id,
      paged_keys.total_count
    FROM paged_keys
    JOIN public.unitgroups payload
      ON payload.id = paged_keys.id
     AND payload.version = paged_keys.version
    ORDER BY
      CASE
        WHEN normalized_sort_by = 'version' AND normalized_sort_direction = 'asc' THEN paged_keys.version
      END ASC NULLS LAST,
      CASE
        WHEN normalized_sort_by = 'version' AND normalized_sort_direction <> 'asc' THEN paged_keys.version
      END DESC NULLS LAST,
      CASE
        WHEN normalized_sort_by = 'created_at' AND normalized_sort_direction = 'asc' THEN paged_keys.created_at
      END ASC NULLS LAST,
      CASE
        WHEN normalized_sort_by = 'created_at' AND normalized_sort_direction <> 'asc' THEN paged_keys.created_at
      END DESC NULLS LAST,
      CASE
        WHEN normalized_sort_by = 'modified_at' AND normalized_sort_direction = 'asc' THEN paged_keys.modified_at
      END ASC NULLS LAST,
      CASE
        WHEN normalized_sort_by = 'modified_at' AND normalized_sort_direction <> 'asc' THEN paged_keys.modified_at
      END DESC NULLS LAST,
      paged_keys.id;
END;
$_$;


ALTER FUNCTION api.get_latest_unitgroup_versions(page_size bigint, page_current bigint, data_source text, this_user_id text, team_id_filter uuid, state_code_filter integer, sort_by text, sort_direction text) OWNER TO postgres;

--
-- Name: get_lca_release_artifact_download(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.get_lca_release_artifact_download(p_artifact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_artifact private.lca_release_artifacts%rowtype;
  v_is_public boolean;
begin
  select * into v_artifact
  from private.lca_release_artifacts
  where id = p_artifact_id;

  if v_artifact.id is null then
    return private.lca_release_error('artifact_not_found', 404, 'Release artifact not found');
  end if;
  select exists (
    select 1 from private.lca_release_publications
    where release_run_id = v_artifact.release_run_id
      and status in ('current', 'superseded')
  ) into v_is_public;

  if not v_is_public and not private.lca_release_is_manager() then
    return private.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required for private artifacts');
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'artifactId', v_artifact.id,
      'releaseRunId', v_artifact.release_run_id,
      'profileId', v_artifact.profile_id,
      'format', v_artifact.artifact_format,
      'storageBucket', v_artifact.storage_bucket,
      'objectKey', v_artifact.object_key,
      'sha256', v_artifact.sha256,
      'byteSize', v_artifact.byte_size,
      'mediaType', v_artifact.media_type,
      'public', v_is_public
    )
  );
end;
$$;


ALTER FUNCTION api.get_lca_release_artifact_download(p_artifact_id uuid) OWNER TO postgres;

--
-- Name: get_lca_release_run(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.get_lca_release_run(p_release_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_run private.lca_release_runs%rowtype;
  v_is_public boolean;
begin
  select * into v_run
  from private.lca_release_runs
  where id = p_release_run_id;

  if v_run.id is null then
    return private.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;
  select exists (
    select 1 from private.lca_release_publications
    where release_run_id = v_run.id and status in ('current', 'superseded')
  ) into v_is_public;

  if not v_is_public and not private.lca_release_is_manager() then
    return private.lca_release_error('not_data_product_manager', 403, 'Data product manager role is required for private release runs');
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'releaseRunId', v_run.id,
      'releaseVersion', v_run.release_version,
      'status', v_run.status,
      'scopeMode', v_run.scope_mode,
      'selectionManifestHash', v_run.selection_manifest_hash,
      'inputManifestHash', v_run.input_manifest_hash,
      'calculationBundleHash', v_run.calculation_bundle_hash,
      'publishPlanHash', v_run.publish_plan_hash,
      'releaseManifestHash', v_run.release_manifest_hash,
      'artifactSetHash', v_run.artifact_set_hash,
      'createdBy', case when private.lca_release_is_manager() then v_run.created_by else null end,
      'createdAt', v_run.created_at,
      'approvedAt', v_run.approved_at,
      'publishedAt', v_run.published_at,
      'readbackVerifiedAt', v_run.readback_verified_at,
      'calculationBundle', case when private.lca_release_is_manager() then v_run.calculation_bundle_ref else null end,
      'datasetCounts', (
        select coalesce(jsonb_object_agg(counts.dataset_role, counts.dataset_count), '{}'::jsonb)
        from (
          select dataset.dataset_role, count(*) as dataset_count
          from private.lca_release_dataset_versions as dataset
          where dataset.release_run_id = v_run.id
          group by dataset.dataset_role
        ) as counts
      ),
      'validation', jsonb_build_object(
        'tidas', v_run.release_manifest->'validation'->'tidas'->>'status',
        'ilcd', v_run.release_manifest->'validation'->'ilcd'->>'status',
        'semanticRoundtrip', v_run.release_manifest->'validation'->'semanticRoundtrip'->>'status',
        'referenceClosure', v_run.release_manifest->'validation'->'referenceClosure'->>'status',
        'numericParity', v_run.release_manifest->'validation'->'numericParity'->>'status'
      ),
      'publication', (
        select jsonb_build_object(
          'publicationId', publication.id,
          'status', publication.status,
          'isCurrent', publication.is_current,
          'publishedAt', publication.published_at,
          'unpublishedAt', publication.unpublished_at
        )
        from private.lca_release_publications as publication
        where publication.release_run_id = v_run.id
        order by publication.published_at desc
        limit 1
      ),
      'artifacts', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'artifactId', artifact.id,
          'profileId', artifact.profile_id,
          'format', artifact.artifact_format,
          'sha256', artifact.sha256,
          'byteSize', artifact.byte_size,
          'mediaType', artifact.media_type,
          'pinned', artifact.pinned
        ) order by artifact.profile_id, artifact.artifact_format), '[]'::jsonb)
        from private.lca_release_artifacts as artifact
        where artifact.release_run_id = v_run.id
      ),
      'blockers', case
        when v_run.status = 'prepared' then jsonb_build_array('artifacts_not_finalized')
        when v_run.status = 'ready_for_approval' then jsonb_build_array('approval_required')
        when v_run.status = 'approved' then jsonb_build_array('publish_required')
        when v_run.status = 'published' then jsonb_build_array('readback_verification_required')
        else '[]'::jsonb
      end
    )
  );
end;
$$;


ALTER FUNCTION api.get_lca_release_run(p_release_run_id uuid) OWNER TO postgres;

--
-- Name: get_lcia_result_calculation_bundle(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.get_lcia_result_calculation_bundle(p_package_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_package private.lcia_result_packages%rowtype;
  v_result private.lca_results%rowtype;
  v_bundle jsonb;
  v_downloads jsonb;
  v_download jsonb;
  v_expected jsonb := jsonb_build_object(
    'lcia_results_xlsx', jsonb_build_object(
      'group', 'results',
      'fileName', 'lcia-results.xlsx',
      'mediaType', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    ),
    'lcia_results_csv_zip', jsonb_build_object(
      'group', 'results',
      'fileName', 'lcia-results.csv.zip',
      'mediaType', 'application/zip'
    ),
    'lci_inventory_parquet', jsonb_build_object(
      'group', 'advanced_data',
      'fileName', 'lci-inventory.parquet',
      'mediaType', 'application/vnd.apache.parquet'
    ),
    'lci_inventory_csv_zip', jsonb_build_object(
      'group', 'advanced_data',
      'fileName', 'lci-inventory-csv.zip',
      'mediaType', 'application/zip'
    ),
    'calculation_evidence_bundle', jsonb_build_object(
      'group', 'audit_evidence',
      'fileName', 'calculation-evidence-bundle.zip',
      'mediaType', 'application/zip'
    )
  );
begin
  if not api.lcia_result_is_manager() then
    return api.lcia_result_error(
      'not_data_product_manager', 403, 'Data product manager role is required'
    );
  end if;

  select * into v_package
  from private.lcia_result_packages
  where id = p_package_id;
  if v_package.id is null then
    return api.lcia_result_error('package_not_found', 404, 'Package not found');
  end if;

  select * into v_result
  from private.lca_results
  where id = v_package.result_id;

  v_bundle := coalesce(
    v_package.artifact_manifest->'calculationBundle',
    v_result.diagnostics->'calculation_bundle'
  );
  if v_bundle is null then
    return api.lcia_result_error(
      'calculation_bundle_not_available', 404,
      'Calculation Bundle is not available for this legacy package'
    );
  end if;

  v_downloads := coalesce(v_bundle->'downloads', '[]'::jsonb);
  if jsonb_typeof(v_downloads) <> 'array' then
    return api.lcia_result_error(
      'calculation_downloads_invalid', 409,
      'Calculation product downloads must be a role-bound array'
    );
  end if;
  if jsonb_array_length(v_downloads) not in (0, 5) then
    return api.lcia_result_error(
      'calculation_downloads_incomplete', 409,
      'Calculation product downloads must contain all five semantic artifacts'
    );
  end if;

  for v_download in select value from jsonb_array_elements(v_downloads)
  loop
    if jsonb_typeof(v_download) <> 'object'
       or not v_expected ? coalesce(v_download->>'role', '')
       or v_download->>'group' is distinct from v_expected->(v_download->>'role')->>'group'
       or v_download->>'fileName' is distinct from v_expected->(v_download->>'role')->>'fileName'
       or v_download->>'mediaType' is distinct from v_expected->(v_download->>'role')->>'mediaType'
       or v_download->>'schemaVersion' is distinct from 'tiangong.calculation-download.v1'
       or coalesce(v_download->>'artifactUrl', '') = ''
       or coalesce(v_download->>'sha256', '') !~ '^[0-9a-f]{64}$'
       or coalesce(v_download->>'byteSize', '') !~ '^[1-9][0-9]*$'
       or coalesce(v_download->>'recordCount', '') !~ '^[0-9]+$' then
      return api.lcia_result_error(
        'calculation_download_ref_invalid', 409,
        'Calculation product download metadata is incomplete or invalid'
      );
    end if;
  end loop;

  if jsonb_array_length(v_downloads) = 5 and (
    select count(distinct item->>'role')
    from jsonb_array_elements(v_downloads) as item
  ) <> 5 then
    return api.lcia_result_error(
      'calculation_download_role_conflict', 409,
      'Calculation product download roles must be unique'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'packageId', v_package.id,
      'packageVersion', v_package.package_version,
      'snapshotId', v_package.snapshot_id,
      'resultId', v_package.result_id,
      'calculationBundle', v_bundle - 'downloads',
      'productDownloads', v_downloads,
      'availableImpactCategories', v_package.available_impact_categories
    )
  );
end;
$_$;


ALTER FUNCTION api.get_lcia_result_calculation_bundle(p_package_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_lcia_result_calculation_bundle(p_package_id uuid); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.get_lcia_result_calculation_bundle(p_package_id uuid) IS 'Projects a verified Calculation Bundle plus five role-bound semantic downloads; canonical shards remain internal preview and audit evidence.';


--
-- Name: get_lcia_result_package_preview(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.get_lcia_result_package_preview(p_package_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_package private.lcia_result_packages%rowtype;
begin
  if not api.lcia_result_is_manager() then
    return api.lcia_result_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;

  select *
    into v_package
  from private.lcia_result_packages
  where id = p_package_id;

  if v_package.id is null then
    return api.lcia_result_error('package_not_found', 404, 'Package not found');
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'summary', jsonb_build_object(
        'packageId', v_package.id,
        'packageVersion', v_package.package_version,
        'status', v_package.status,
        'coverageMode', v_package.coverage_mode,
        'snapshotId', v_package.snapshot_id,
        'resultId', v_package.result_id,
        'latestAllUnitResultId', v_package.latest_all_unit_result_id,
        'eligibleInputCount', v_package.eligible_input_count,
        'includedInputCount', v_package.included_input_count,
        'inputManifestHash', v_package.input_manifest_hash,
        'defaultImpactCategory', v_package.default_impact_category,
        'availableImpactCategories', v_package.available_impact_categories
      ),
      'resultArtifact', v_package.result_artifact_ref,
      'queryArtifact', v_package.query_artifact_ref,
      'artifactManifest', v_package.artifact_manifest,
      'inputManifest', v_package.input_manifest
    )
  );
end;
$$;


