--
-- Name: list_lcia_result_sets(integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.list_lcia_result_sets(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 200));
begin
  if v_actor is null then
    return api.lcia_scope_closure_error(
      'auth_required', 401, 'Authentication required'
    );
  end if;
  if not api.lcia_scope_closure_is_manager() then
    return api.lcia_scope_closure_error(
      'not_data_product_manager', 403,
      'Data product manager role is required'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'schemaVersion', 'lcia.result-set.v1',
            'resultSetId', result_set.id,
            'name', result_set.name,
            'createdAt', result_set.created_at
          )
          order by result_set.created_at desc, result_set.id desc
        )
        from (
          select id, name, created_at
          from private.lcia_result_sets
          order by created_at desc, id desc
          limit v_limit
        ) result_set
      ), '[]'::jsonb)
    )
  );
end;
$$;


ALTER FUNCTION api.list_lcia_result_sets(p_limit integer) OWNER TO postgres;

--
-- Name: list_lcia_scope_closure_issues(uuid, uuid, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.list_lcia_scope_closure_issues(p_closure_check_id uuid, p_after_issue_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 200));
begin
  if v_actor is null then
    return api.lcia_scope_closure_error('auth_required', 401, 'Authentication required');
  end if;
  if not api.lcia_scope_closure_is_manager()
     or not exists (
       select 1
       from private.lcia_scope_closure_checks c
       where c.id = p_closure_check_id
         and c.requested_by = v_actor
     ) then
    return api.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;

  return jsonb_build_object('ok', true, 'data', (
    with page as (
      select i.*
      from private.lcia_scope_closure_issues i
      where i.closure_check_id = p_closure_check_id
        and (p_after_issue_id is null or i.id > p_after_issue_id)
      order by i.id
      limit v_limit + 1
    ), shown as (
      select * from page order by id limit v_limit
    )
    select jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-issues-page.v1',
      'closureCheckId', p_closure_check_id,
      'issues', coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'issueId', id,
        'severity', severity,
        'blocking', blocking,
        'code', issue_code,
        'title', issue_code,
        'summary', message,
        'suggestedAction', suggested_action,
        'occurrenceCount', occurrence_count,
        'affectedRootCount', affected_root_count
      )) order by id), '[]'::jsonb),
      'totalCount', (
        select count(*)
        from private.lcia_scope_closure_issues
        where closure_check_id = p_closure_check_id
      ),
      'nextCursor', case when exists (select 1 from page offset v_limit)
        then (select id from shown order by id desc limit 1)
        else null
      end
    )
    from shown
  ));
end;
$$;


ALTER FUNCTION api.list_lcia_scope_closure_issues(p_closure_check_id uuid, p_after_issue_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: oauth_client_pre_request(); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.oauth_client_pre_request() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_claims jsonb := coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );
  v_client_id text := nullif(pg_catalog.btrim(coalesce(v_claims ->> 'client_id', '')), '');
  v_headers jsonb := coalesce(
    nullif(pg_catalog.current_setting('request.headers', true), '')::jsonb,
    '{}'::jsonb
  );
  v_method text := upper(coalesce(
    nullif(pg_catalog.current_setting('request.method', true), ''),
    'GET'
  ));
  v_path text := coalesce(
    nullif(pg_catalog.current_setting('request.path', true), ''),
    '/'
  );
  v_profile text;
  v_route_name text;
  v_command text;
  v_capability_id text;
  v_capability_count integer;
begin
  if v_client_id is null then
    return;
  end if;

  if v_path like '/rpc/%' then
    v_route_name := split_part(v_path, '/', 3);

    select
      min(manifest.capability_id),
      count(distinct manifest.capability_id)::integer
    into v_capability_id, v_capability_count
    from private.api_capability_grants as manifest
    join pg_catalog.pg_proc as routine
      on routine.oid = pg_catalog.to_regprocedure(manifest.routine_identity)
    join pg_catalog.pg_namespace as namespace
      on namespace.oid = routine.pronamespace
    where namespace.nspname = 'api'
      and routine.proname = v_route_name
      and manifest.allow_authenticated;
  else
    v_profile := coalesce(
      case
        when v_method in ('GET', 'HEAD') then v_headers ->> 'accept-profile'
        else v_headers ->> 'content-profile'
      end,
      v_headers ->> 'accept-profile',
      'public'
    );
    v_route_name := ltrim(v_path, '/');
    v_command := case v_method
      when 'GET' then 'select'
      when 'HEAD' then 'select'
      when 'POST' then 'insert'
      when 'PUT' then 'update'
      when 'PATCH' then 'update'
      when 'DELETE' then 'delete'
      else null
    end;

    select relation_grant.capability_id, 1
    into v_capability_id, v_capability_count
    from private.oauth_relation_capability_grants as relation_grant
    where relation_grant.relation_schema = v_profile
      and relation_grant.relation_name = v_route_name
      and relation_grant.command = v_command;
  end if;

  if coalesce(v_capability_count, 0) <> 1
     or not private.oauth_client_has_capability(v_capability_id) then
    raise insufficient_privilege using
      message = 'OAuth client is not authorized for this API route';
  end if;
end;
$$;


ALTER FUNCTION api.oauth_client_pre_request() OWNER TO postgres;

--
-- Name: pgroonga_search_contacts(text, text, bigint, bigint, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.pgroonga_search_contacts(query_text text, filter_condition text DEFAULT ''::text, page_size bigint DEFAULT 10, page_current bigint DEFAULT 1, data_source text DEFAULT 'tg'::text, this_user_id text DEFAULT ''::text) RETURNS TABLE(rank bigint, id uuid, "json" jsonb, version character, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    AS $$
DECLARE
    filter_condition_jsonb JSONB;
BEGIN
	filter_condition_jsonb := filter_condition::JSONB;
  RETURN QUERY
		SELECT 
			RANK () OVER (ORDER BY pgroonga_score(f.tableoid, f.ctid) DESC) AS rank, 
			f.id, 
			f.json,
			f.version,
			f.modified_at,
			COUNT(*) OVER() AS total_count
		FROM contacts f
		WHERE f.json @> filter_condition_jsonb AND f.json &@~ query_text AND ((data_source = 'tg' AND state_code = 100) or (data_source = 'my' AND user_id::text = this_user_id))
		ORDER BY pgroonga_score(tableoid, ctid) DESC
		LIMIT page_size
		OFFSET (page_current -1) * page_size;
END;
$$;


ALTER FUNCTION api.pgroonga_search_contacts(query_text text, filter_condition text, page_size bigint, page_current bigint, data_source text, this_user_id text) OWNER TO postgres;

