CREATE FUNCTION api.pgroonga_search_lifecyclemodels_latest(query_text text, filter_condition jsonb DEFAULT '{}'::jsonb, order_by jsonb DEFAULT '{}'::jsonb, page_size bigint DEFAULT 10, page_current bigint DEFAULT 1, data_source text DEFAULT 'tg'::text, this_user_id text DEFAULT ''::text, team_id_filter uuid DEFAULT NULL::uuid, state_code_filter integer DEFAULT NULL::integer) RETURNS TABLE(rank bigint, id uuid, "json" jsonb, version character, modified_at timestamp with time zone, team_id uuid, total_count bigint)
