--
-- Name: portal_sitemap_entries_v1(text, text, integer); Type: FUNCTION; Schema: api; Owner: portal_public_executor
--

CREATE FUNCTION api.portal_sitemap_entries_v1(p_kind text, p_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '8s'
    AS $_$
declare
  v_filter_kind text;
  v_cursor jsonb;
  v_cursor_kind text;
  v_cursor_id uuid;
  v_items jsonb;
  v_next_cursor text;
begin
  if pg_catalog.octet_length(coalesce(p_kind, '')) > 32 then
    raise exception using errcode = '22023', message = 'invalid portal request';
  end if;
  v_filter_kind := lower(btrim(coalesce(p_kind, '')));
  if v_filter_kind not in ('process', 'flow', 'all')
     or p_limit is null
     or p_limit not between 1 and 1000 then
    raise exception using errcode = '22023', message = 'invalid portal request';
  end if;
  if p_cursor is not null then
    v_cursor := private.portal_cursor_decode_v1(p_cursor);
    if v_cursor is null
       or (select count(*) from jsonb_object_keys(v_cursor)) <> 5
       or v_cursor ->> 'v' <> '1'
       or v_cursor ->> 'filterKind' <> v_filter_kind
       or v_cursor ->> 'kind' not in ('process', 'flow')
       or (v_filter_kind <> 'all' and v_cursor ->> 'kind' <> v_filter_kind)
       or coalesce(v_cursor ->> 'id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_cursor ->> 'version', '') !~ '^\d{2}\.\d{2}\.\d{3}$' then
      raise exception using errcode = '22023', message = 'invalid portal request';
    end if;
    v_cursor_kind := v_cursor ->> 'kind';
    v_cursor_id := (v_cursor ->> 'id')::uuid;
  end if;

  with source_rows as materialized (
    select kinds.kind, source.*
    from (values ('process'::text), ('flow'::text)) as kinds(kind)
    cross join lateral private.portal_catalog_rows_v1(kinds.kind) as source
    where v_filter_kind = 'all' or kinds.kind = v_filter_kind
  ), latest as materialized (
    select candidate.*
    from (
      select source_rows.*,
        row_number() over (
          partition by source_rows.kind, source_rows.id
          order by source_rows.version desc
        ) as version_rank
      from source_rows
    ) as candidate
    where candidate.version_rank = 1
  ), ordered as materialized (
    select latest.*,
      row_number() over (order by latest.kind, latest.id) as page_rank
    from latest
    where v_cursor is null or (latest.kind, latest.id) > (v_cursor_kind, v_cursor_id)
    order by latest.kind, latest.id
    limit p_limit + 1
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'key', jsonb_build_object(
        'kind', ordered.kind,
        'id', ordered.id::text,
        'version', ordered.version
      ),
      'modifiedAt', private.portal_timestamp_v1(ordered.modified_at)
    ) order by ordered.page_rank) filter (where ordered.page_rank <= p_limit), '[]'::jsonb),
    case when max(ordered.page_rank) > p_limit then private.portal_cursor_encode_v1(
      (jsonb_agg(jsonb_build_object(
        'v', 1,
        'filterKind', v_filter_kind,
        'kind', ordered.kind,
        'id', ordered.id::text,
        'version', ordered.version
      ) order by ordered.page_rank) filter (where ordered.page_rank = p_limit)) -> 0
    ) else null end
  into v_items, v_next_cursor
  from ordered;

  return jsonb_build_object(
    'schemaVersion', 'portal.public-sitemap-page.v1',
    'items', v_items,
    'nextCursor', v_next_cursor
  );
exception
  when sqlstate '22023' then
    raise exception using errcode = '22023', message = 'invalid portal request';
  when query_canceled then
    raise exception using errcode = 'P0001', message = 'portal catalog unavailable';
  when others then
    raise exception using errcode = 'P0001', message = 'portal catalog unavailable';
end
$_$;


ALTER FUNCTION api.portal_sitemap_entries_v1(p_kind text, p_cursor text, p_limit integer) OWNER TO portal_public_executor;

--
-- Name: FUNCTION portal_sitemap_entries_v1(p_kind text, p_cursor text, p_limit integer); Type: COMMENT; Schema: api; Owner: portal_public_executor
--

COMMENT ON FUNCTION api.portal_sitemap_entries_v1(p_kind text, p_cursor text, p_limit integer) IS 'Bounded keyset page of the latest visible exact Process/Flow identities for Portal sitemap generation.';


--
-- Name: portal_sitemap_manifest_v1(); Type: FUNCTION; Schema: api; Owner: portal_public_executor
--

CREATE FUNCTION api.portal_sitemap_manifest_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '2s'
    SET max_parallel_workers_per_gather TO '0'
    SET jit TO 'off'
    SET row_security TO 'on'
    AS $$
declare
  v_shards jsonb;
begin
  perform private.assert_portal_catalog_projection_contract_v1();
  perform private.assert_portal_catalog_facet_contract_v1();
  perform private.assert_portal_sitemap_projection_v1();

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'shardCursor',
      private.portal_cursor_encode_v1(pg_catalog.jsonb_build_object(
        'v', 1,
        'scope', 'sitemap-shard',
        'bucket', shard.bucket,
        'shardCount', 64
      )),
      'maxItems', 4096
    )
    order by shard.bucket
  )
  into v_shards
  from pg_catalog.generate_series(0, 63) as shard(bucket);

  return pg_catalog.jsonb_build_object(
    'schemaVersion', 'portal.public-sitemap-manifest.v1',
    'shards', v_shards
  );
exception
  when query_canceled then
    raise exception using
      errcode = 'P0001',
      message = 'portal sitemap unavailable';
  when others then
    raise exception using
      errcode = 'P0001',
      message = 'portal sitemap unavailable';
end
$$;


ALTER FUNCTION api.portal_sitemap_manifest_v1() OWNER TO portal_public_executor;

--
-- Name: FUNCTION portal_sitemap_manifest_v1(); Type: COMMENT; Schema: api; Owner: portal_public_executor
--

COMMENT ON FUNCTION api.portal_sitemap_manifest_v1() IS 'Constant-cost ordered manifest of 64 opaque, globally disjoint Portal sitemap shard cursors.';


--
-- Name: portal_sitemap_shard_v1(text); Type: FUNCTION; Schema: api; Owner: portal_public_executor
--

CREATE FUNCTION api.portal_sitemap_shard_v1(p_shard_cursor text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '4s'
    SET work_mem TO '8MB'
    SET plan_cache_mode TO 'force_custom_plan'
    SET max_parallel_workers_per_gather TO '0'
    SET jit TO 'off'
    SET row_security TO 'on'
    AS $_$
declare
  v_cursor jsonb;
  v_expected_cursor jsonb;
  v_bucket integer;
  v_items jsonb;
  v_result jsonb;
begin
  if p_shard_cursor is null
     or pg_catalog.octet_length(p_shard_cursor) not between 1 and 4096
     or p_shard_cursor ~ '[[:space:]]' then
    raise exception using errcode = '22023', message = 'invalid portal request';
  end if;

  v_cursor := private.portal_cursor_decode_v1(p_shard_cursor);
  if v_cursor is null
     or pg_catalog.jsonb_typeof(v_cursor) <> 'object'
     or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(v_cursor)) <> 4
     or coalesce(v_cursor ->> 'bucket', '') !~ '^([0-9]|[1-5][0-9]|6[0-3])$' then
    raise exception using errcode = '22023', message = 'invalid portal request';
  end if;
  v_bucket := (v_cursor ->> 'bucket')::integer;
  v_expected_cursor := pg_catalog.jsonb_build_object(
    'v', 1,
    'scope', 'sitemap-shard',
    'bucket', v_bucket,
    'shardCount', 64
  );

  if v_cursor is distinct from v_expected_cursor
     or private.portal_cursor_encode_v1(v_expected_cursor) <>
       p_shard_cursor then
    raise exception using errcode = '22023', message = 'invalid portal request';
  end if;

  perform private.assert_portal_catalog_projection_contract_v1();
  perform private.assert_portal_catalog_facet_contract_v1();
  perform private.assert_portal_sitemap_projection_v1();

  with latest as materialized (
    select distinct on (projection.dataset_kind, projection.id)
      projection.dataset_kind,
      projection.id,
      projection.version,
      projection.modified_at
    from private.portal_sitemap_rows_v1 as projection
    where projection.shard_no = v_bucket
      and projection.contract_version = 1
    order by projection.dataset_kind,
      projection.id,
      projection.version desc,
      projection.modified_at desc
    limit 4097
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'key', pg_catalog.jsonb_build_object(
      'kind', latest.dataset_kind,
      'id', latest.id::text,
      'version', latest.version
    ),
    'modifiedAt', private.portal_timestamp_v1(latest.modified_at)
  ) order by latest.dataset_kind, latest.id), '[]'::jsonb)
  into v_items
  from latest;

  if pg_catalog.jsonb_array_length(v_items) > 4096 then
    raise exception using
      errcode = 'P0001',
      message = 'portal sitemap unavailable';
  end if;

  v_result := pg_catalog.jsonb_build_object(
    'schemaVersion', 'portal.public-sitemap-shard.v1',
    'shardCursor', p_shard_cursor,
    'items', v_items
  );
  if pg_catalog.octet_length(v_result::text) > 2 * 1024 * 1024 then
    raise exception using
      errcode = '54000',
      message = 'portal sitemap response exceeded its budget';
  end if;
  return v_result;
exception
  when sqlstate '22023' then
    raise exception using errcode = '22023', message = 'invalid portal request';
  when query_canceled then
    raise exception using
      errcode = 'P0001',
      message = 'portal sitemap unavailable';
  when others then
    raise exception using
      errcode = 'P0001',
      message = 'portal sitemap unavailable';
end
$_$;


ALTER FUNCTION api.portal_sitemap_shard_v1(p_shard_cursor text) OWNER TO portal_public_executor;

--
-- Name: FUNCTION portal_sitemap_shard_v1(p_shard_cursor text); Type: COMMENT; Schema: api; Owner: portal_public_executor
--

COMMENT ON FUNCTION api.portal_sitemap_shard_v1(p_shard_cursor text) IS 'Output-bounded latest-visible Process/Flow sitemap page over exact-version rows for one opaque stable-hash shard cursor.';


--
-- Name: processes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.processes (
    id uuid NOT NULL,
    "json" jsonb,
    created_at timestamp with time zone DEFAULT now(),
    json_ordered json,
    user_id uuid DEFAULT auth.uid(),
    state_code integer DEFAULT 0,
    version character(9) NOT NULL,
    modified_at timestamp with time zone DEFAULT now(),
    team_id uuid,
    review_id uuid,
    rule_verification boolean,
    reviews jsonb,
    model_id uuid,
    embedding_ft_at timestamp with time zone,
    embedding_ft extensions.vector(1024),
    extracted_md text,
    search_text text[],
    model_version character(9),
    CONSTRAINT processes_model_version_format_check CHECK (((model_version IS NULL) OR ((model_version)::text ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'::text))),
    CONSTRAINT processes_model_version_requires_model_id_check CHECK (((model_version IS NULL) OR (model_id IS NOT NULL))),
    CONSTRAINT processes_state_code_check CHECK ((state_code = ANY (ARRAY[0, 20, 100, 200])))
);


ALTER TABLE public.processes OWNER TO postgres;

--
-- Name: COLUMN processes.search_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.processes.search_text IS 'Edge-owned multilingual lexical projection as nullable text[]. The empty scalar precursor was replaced without a heap rewrite; the later backfill writes the complete projection. Not a lexical search source until Database B.';


--
-- Name: COLUMN processes.model_version; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.processes.model_version IS 'Exact LifecycleModel version that owns or generated this Process. NULL preserves the legacy same-version fallback to processes.version.';


--
-- Name: processes_embedding_ft_input(public.processes); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.processes_embedding_ft_input(proc public.processes) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    AS $$
begin
  return proc.extracted_md;
end;
$$;


ALTER FUNCTION api.processes_embedding_ft_input(proc public.processes) OWNER TO postgres;

--
-- Name: qry_identity_get_mine(); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_identity_get_mine() RETURNS TABLE(id uuid, email text, display_name text, contact jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    profile.id,
    coalesce(
      nullif(btrim(auth_user.email), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'email'), '')
    ),
    coalesce(
      nullif(btrim(profile.raw_user_meta_data ->> 'display_name'), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'name'), ''),
      nullif(btrim(auth_user.email), '')
    ),
    profile.contact
  from private.users as profile
  left join auth.users as auth_user on auth_user.id = profile.id
  where auth.uid() is not null
    and profile.id = auth.uid()
$$;


ALTER FUNCTION api.qry_identity_get_mine() OWNER TO postgres;

--
-- Name: qry_identity_get_visible_users(uuid[]); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_identity_get_visible_users(p_user_ids uuid[]) RETURNS TABLE(id uuid, email text, display_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_requested_count integer := coalesce(cardinality(p_user_ids), 0);
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTH_REQUIRED';
  end if;

  if v_requested_count > 100 then
    raise exception using errcode = '22023', message = 'TOO_MANY_USER_IDS';
  end if;

  return query
  with requested as (
    select distinct requested_id
    from unnest(coalesce(p_user_ids, '{}'::uuid[])) as requested_id
    where requested_id is not null
  ), visible as (
    select requested.requested_id
    from requested
    where requested.requested_id = v_actor
      or exists (
        select 1
        from private.roles as actor_membership
        join private.roles as target_membership
          on target_membership.team_id = actor_membership.team_id
        where actor_membership.user_id = v_actor
          and target_membership.user_id = requested.requested_id
          and actor_membership.team_id <> '00000000-0000-0000-0000-000000000000'::uuid
          and actor_membership.role not in ('rejected', 'is_invited')
          and target_membership.role not in ('rejected', 'is_invited')
      )
      or exists (
        select 1
        from private.reviews as review
        where api.policy_review_can_read(review.id, v_actor)
          and (
            review.target_owner_id = requested.requested_id
            or review.reviewer_id ? requested.requested_id::text
            or review.json -> 'user' ->> 'id' = requested.requested_id::text
          )
      )
      or exists (
        select 1
        from private.teams as team
        join private.roles as owner_membership
          on owner_membership.team_id = team.id
         and owner_membership.role = 'owner'
        where coalesce(team.is_public, false)
          and owner_membership.user_id = requested.requested_id
      )
  )
  select
    profile.id,
    coalesce(
      nullif(btrim(auth_user.email), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'email'), '')
    ),
    coalesce(
      nullif(btrim(profile.raw_user_meta_data ->> 'display_name'), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'name'), ''),
      nullif(btrim(auth_user.email), '')
    )
  from visible
  join private.users as profile on profile.id = visible.requested_id
  left join auth.users as auth_user on auth_user.id = profile.id
  order by profile.id;
end
$$;


ALTER FUNCTION api.qry_identity_get_visible_users(p_user_ids uuid[]) OWNER TO postgres;

--
-- Name: qry_membership_get_mine(); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_membership_get_mine() RETURNS TABLE(user_id uuid, team_id uuid, role text, created_at timestamp with time zone, modified_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    membership.user_id,
    membership.team_id,
    membership.role::text,
    membership.created_at,
    membership.modified_at
  from private.roles as membership
  where auth.uid() is not null
    and membership.user_id = auth.uid()
  order by
    membership.modified_at desc nulls last,
    membership.created_at desc nulls last,
    membership.team_id,
    membership.role
$$;


ALTER FUNCTION api.qry_membership_get_mine() OWNER TO postgres;

--
-- Name: qry_national_carbon_organization_contributions(integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_national_carbon_organization_contributions(p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_result jsonb;
begin
  if v_actor is null then
    raise exception using
      errcode = '28000',
      message = 'AUTH_REQUIRED';
  end if;

  if not api.cmd_membership_is_system_manager(v_actor) then
    raise exception using
      errcode = '42501',
      message = 'SYSTEM_MANAGER_REQUIRED';
  end if;

  if p_limit is null or p_limit < 1 or p_limit > 50 then
    raise exception using
      errcode = '22023',
      message = 'INVALID_LIMIT';
  end if;

  with
  daily_date_bounds as materialized (
    select
      (
        pg_catalog.date_trunc(
          'week',
          pg_catalog.timezone('Asia/Shanghai', pg_catalog.statement_timestamp())
        )::date - 364
      ) as start_date,
      pg_catalog.timezone(
        'Asia/Shanghai',
        pg_catalog.statement_timestamp()
      )::date as end_date
  ),
  daily_time_bounds as materialized (
    select
      bounds.start_date,
      bounds.end_date,
      pg_catalog.timezone(
        'Asia/Shanghai',
        bounds.start_date::timestamp without time zone
      ) as start_at,
      pg_catalog.timezone(
        'Asia/Shanghai',
        (bounds.end_date + 1)::timestamp without time zone
      ) as end_at
    from daily_date_bounds as bounds
  ),
  daily_version_facts as materialized (
    select
      'process'::text as dataset_kind,
      pg_catalog.timezone('Asia/Shanghai', process_row.created_at)::date as created_date
    from public.processes as process_row
    cross join daily_time_bounds as bounds
    where process_row.created_at >= bounds.start_at
      and process_row.created_at < bounds.end_at
    union all
    select
      'model'::text as dataset_kind,
      pg_catalog.timezone('Asia/Shanghai', model_row.created_at)::date as created_date
    from public.lifecyclemodels as model_row
    cross join daily_time_bounds as bounds
    where model_row.created_at >= bounds.start_at
      and model_row.created_at < bounds.end_at
  ),
  daily_version_counts as materialized (
    select
      fact.created_date,
      pg_catalog.count(*) filter (where fact.dataset_kind = 'process')::bigint
        as process_count,
      pg_catalog.count(*) filter (where fact.dataset_kind = 'model')::bigint
        as model_count,
      pg_catalog.count(*)::bigint as all_count
    from daily_version_facts as fact
    group by fact.created_date
  ),
  daily_creation_payload as materialized (
    select pg_catalog.jsonb_build_object(
      'metric', 'dataset_version_created_count',
      'deduplicationKey', pg_catalog.jsonb_build_array('datasetType', 'datasetId', 'version'),
      'timezone', 'Asia/Shanghai',
      'startDate', bounds.start_date,
      'endDate', bounds.end_date,
      'days', coalesce(
        pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'date', series.created_date,
            'processCount', coalesce(counts.process_count, 0::bigint),
            'modelCount', coalesce(counts.model_count, 0::bigint),
            'allCount', coalesce(counts.all_count, 0::bigint)
          )
          order by series.created_date
        ),
        '[]'::jsonb
      )
    ) as payload
    from daily_time_bounds as bounds
    cross join lateral pg_catalog.generate_series(
      bounds.start_date::timestamp without time zone,
      bounds.end_date::timestamp without time zone,
      interval '1 day'
    ) as generated(created_at)
    cross join lateral (
      select generated.created_at::date as created_date
    ) as series
    left join daily_version_counts as counts using (created_date)
    group by bounds.start_date, bounds.end_date
  ),
  latest_published_process as materialized (
    select distinct on (process_row.id)
      'process'::text as dataset_kind,
      process_row.id as dataset_id,
      process_row.user_id,
      process_row.modified_at
    from public.processes as process_row
    where process_row.state_code = 100
    order by
      process_row.id,
      process_row.version desc,
      process_row.modified_at desc
  ),
  latest_current_process as materialized (
    select distinct on (process_row.id)
      'process'::text as dataset_kind,
      process_row.id as dataset_id,
      pg_catalog.btrim(process_row.version::text) as dataset_version,
      process_row.user_id,
      process_row.state_code,
      process_row.modified_at
    from public.processes as process_row
    order by
      process_row.id,
      process_row.version desc,
      process_row.modified_at desc
  ),
  latest_published_model as materialized (
    select distinct on (model_row.id)
      'model'::text as dataset_kind,
      model_row.id as dataset_id,
      model_row.user_id,
      model_row.modified_at
    from public.lifecyclemodels as model_row
    where model_row.state_code = 100
    order by
      model_row.id,
      model_row.version desc,
      model_row.modified_at desc
  ),
  latest_current_model as materialized (
    select distinct on (model_row.id)
      'model'::text as dataset_kind,
      model_row.id as dataset_id,
      pg_catalog.btrim(model_row.version::text) as dataset_version,
      model_row.user_id,
      model_row.state_code,
      model_row.modified_at
    from public.lifecyclemodels as model_row
    order by
      model_row.id,
      model_row.version desc,
      model_row.modified_at desc
  ),
  published_facts as materialized (
    select * from latest_published_process
    union all
    select * from latest_published_model
  ),
  pending_review_facts as materialized (
    select
      latest_row.dataset_kind,
      latest_row.dataset_id,
      latest_row.dataset_version,
      latest_row.user_id,
      case when active_review.state_code = 1 then 1 else 0 end::integer
        as assigned_reviewer_count,
      case when active_review.state_code = 1 then 0 else 1 end::integer
        as unassigned_reviewer_count,
      latest_row.modified_at
    from latest_current_process as latest_row
    left join lateral (
      select review_row.state_code
      from private.reviews as review_row
      where review_row.review_kind = 'root'
        and review_row.target_table = 'processes'
        and review_row.data_id = latest_row.dataset_id
        and review_row.data_version = latest_row.dataset_version::character(9)
        and review_row.state_code in (0, 1)
      order by review_row.state_code desc, review_row.modified_at desc, review_row.id
      limit 1
    ) as active_review on true
    where latest_row.state_code = 20
    union all
    select
      latest_row.dataset_kind,
      latest_row.dataset_id,
      latest_row.dataset_version,
      latest_row.user_id,
      case when active_review.state_code = 1 then 1 else 0 end::integer
        as assigned_reviewer_count,
      case when active_review.state_code = 1 then 0 else 1 end::integer
        as unassigned_reviewer_count,
      latest_row.modified_at
    from latest_current_model as latest_row
    left join lateral (
      select review_row.state_code
      from private.reviews as review_row
      where review_row.review_kind = 'root'
        and review_row.target_table = 'lifecyclemodels'
        and review_row.data_id = latest_row.dataset_id
        and review_row.data_version = latest_row.dataset_version::character(9)
        and review_row.state_code in (0, 1)
      order by review_row.state_code desc, review_row.modified_at desc, review_row.id
      limit 1
    ) as active_review on true
    where latest_row.state_code = 20
  ),
  user_organization_names as materialized (
    select
      profile.id as user_id,
      nullif(
        pg_catalog.regexp_replace(
          pg_catalog.btrim(profile.raw_user_meta_data ->> 'organization'),
          '[[:space:]]+',
          ' ',
          'g'
        ),
        ''
      ) as organization_name
    from private.users as profile
    where pg_catalog.jsonb_typeof(profile.raw_user_meta_data -> 'organization') = 'string'
  ),
  user_organizations as materialized (
    select
      named.user_id,
      pg_catalog.lower(named.organization_name) as organization_key,
      named.organization_name
    from user_organization_names as named
  ),
  organization_catalog as materialized (
    select distinct organization.organization_key
    from user_organizations as organization
    where organization.organization_key is not null
  ),
  organization_summary as materialized (
    select pg_catalog.count(*)::bigint as organization_count
    from organization_catalog
  ),
  contribution_facts as (
    select
      published.dataset_kind,
      published.dataset_id,
      published.user_id,
      organization.organization_key,
      organization.organization_name,
      1::integer as published_count,
      0::integer as assigned_reviewer_count,
      0::integer as unassigned_reviewer_count,
      published.modified_at
    from published_facts as published
    left join user_organizations as organization using (user_id)
    union all
    select
      pending.dataset_kind,
      pending.dataset_id,
      pending.user_id,
      organization.organization_key,
      organization.organization_name,
      0::integer as published_count,
      pending.assigned_reviewer_count,
      pending.unassigned_reviewer_count,
      pending.modified_at
    from pending_review_facts as pending
    left join user_organizations as organization using (user_id)
  ),
  scoped_facts as materialized (
    select
      scope.dataset_scope,
      fact.dataset_kind,
      fact.dataset_id,
      fact.user_id,
      fact.organization_key,
      fact.organization_name,
      fact.published_count,
      fact.assigned_reviewer_count,
      fact.unassigned_reviewer_count,
      fact.modified_at
    from contribution_facts as fact
    cross join lateral (
      values (fact.dataset_kind), ('all'::text)
    ) as scope(dataset_scope)
  ),
  scope_catalog(dataset_scope) as (
    values ('process'::text), ('model'::text), ('all'::text)
  ),
  scope_summary_values as materialized (
    select
      scope.dataset_scope,
      organization_summary.organization_count,
      coalesce(
        pg_catalog.sum(fact.published_count)
          filter (where fact.organization_key is not null),
        0::bigint
      )::bigint
        as published_dataset_count,
      coalesce(
        pg_catalog.sum(
          fact.assigned_reviewer_count + fact.unassigned_reviewer_count
        )
          filter (where fact.organization_key is not null),
        0::bigint
      )::bigint
        as pending_review_dataset_count,
      coalesce(
        pg_catalog.sum(fact.published_count)
          filter (
            where fact.organization_key is not null
              and fact.modified_at >= pg_catalog.statement_timestamp() - interval '30 days'
          ),
        0::bigint
      )::bigint as published_last_30_days_count
    from scope_catalog as scope
    cross join organization_summary
    left join scoped_facts as fact on fact.dataset_scope = scope.dataset_scope
    group by scope.dataset_scope, organization_summary.organization_count
  ),
  scope_organization_aggregate as materialized (
    select
      fact.dataset_scope,
      fact.organization_key,
      pg_catalog.min(fact.organization_name collate "C") as organization_name,
      pg_catalog.sum(fact.published_count)::bigint as published_dataset_count,
      pg_catalog.sum(fact.assigned_reviewer_count)::bigint
        as assigned_reviewer_dataset_count,
      pg_catalog.sum(fact.unassigned_reviewer_count)::bigint
        as unassigned_reviewer_dataset_count
    from scoped_facts as fact
    where fact.organization_key is not null
    group by fact.dataset_scope, fact.organization_key
  ),
  scope_ranked as (
    select
      aggregate.dataset_scope,
      pg_catalog.row_number() over (
        partition by aggregate.dataset_scope
        order by
          aggregate.published_dataset_count desc,
          aggregate.organization_name collate "C" asc,
          aggregate.organization_key collate "C" asc
      )::integer as rank,
      aggregate.organization_key,
      aggregate.organization_name,
      aggregate.published_dataset_count,
      aggregate.assigned_reviewer_dataset_count,
      aggregate.unassigned_reviewer_dataset_count
    from scope_organization_aggregate as aggregate
    where aggregate.published_dataset_count > 0
  ),
  scope_ranked_limited as materialized (
    select *
    from scope_ranked
    where rank <= p_limit
  ),
  scope_payloads as materialized (
    select
      summary.dataset_scope,
      pg_catalog.jsonb_build_object(
        'datasetScope', summary.dataset_scope,
        'metric', 'latest_published_dataset_count',
        'summary', pg_catalog.jsonb_build_object(
          'organizationCount', summary.organization_count,
          'publishedDatasetCount', summary.published_dataset_count,
          'pendingReviewDatasetCount', summary.pending_review_dataset_count,
          'publishedLast30DaysCount', summary.published_last_30_days_count
        ),
        'rankings', coalesce(
          (
            select pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object(
                'rank', ranked.rank,
                'organizationKey', ranked.organization_key,
                'organizationName', ranked.organization_name,
                'publishedDatasetCount', ranked.published_dataset_count,
                'assignedReviewerDatasetCount', ranked.assigned_reviewer_dataset_count,
                'unassignedReviewerDatasetCount', ranked.unassigned_reviewer_dataset_count
              )
              order by ranked.rank
            )
            from scope_ranked_limited as ranked
            where ranked.dataset_scope = summary.dataset_scope
          ),
          '[]'::jsonb
        )
      ) as payload
    from scope_summary_values as summary
  ),
  snapshot_metadata as (
    select coalesce(
      pg_catalog.max(fact.modified_at),
      pg_catalog.statement_timestamp()
    ) as data_as_of
    from contribution_facts as fact
  )
  select pg_catalog.jsonb_build_object(
    'schemaVersion', 'national_carbon_organization_contribution_v3',
    'attributionMode', 'current_user_profile',
    'generatedAt', pg_catalog.statement_timestamp(),
    'dataAsOf', metadata.data_as_of,
    'defaultScope', 'all',
    'dailyCreation', (
      select payload from daily_creation_payload
    ),
    'scopes', pg_catalog.jsonb_build_object(
      'process', (
        select payload from scope_payloads where dataset_scope = 'process'
      ),
      'model', (
        select payload from scope_payloads where dataset_scope = 'model'
      ),
      'all', (
        select payload from scope_payloads where dataset_scope = 'all'
      )
    )
  )
  into v_result
  from snapshot_metadata as metadata;

  return v_result;
end;
$$;


ALTER FUNCTION api.qry_national_carbon_organization_contributions(p_limit integer) OWNER TO postgres;

--
-- Name: qry_notification_get_my_data_count(integer, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_notification_get_my_data_count(p_days integer DEFAULT 3, p_last_view_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with visible_reviews as (
    select review_row.id, review_row.modified_at
    from private.reviews as review_row
    where coalesce(review_row.json->'user'->>'id', '') = auth.uid()::text
      and review_row.state_code in (1, -1, 2)
    union
    select review_row.id,
      greatest(review_row.modified_at, notification_row.modified_at)
    from private.notifications as notification_row
    join private.reviews as review_row
      on review_row.id = nullif(notification_row.json->>'review_id', '')::uuid
    where notification_row.recipient_user_id = auth.uid()
      and notification_row.type = 'review_event'
      and review_row.state_code in (-1, 2)
  )
  select count(*)::integer
  from visible_reviews
  where (
    p_last_view_at is not null and modified_at > p_last_view_at
  ) or (
    p_last_view_at is null and (
      coalesce(p_days, 3) <= 0
      or modified_at >= now()
        - make_interval(days => greatest(coalesce(p_days, 3), 0))
    )
  )
$$;


ALTER FUNCTION api.qry_notification_get_my_data_count(p_days integer, p_last_view_at timestamp with time zone) OWNER TO postgres;

--
-- Name: qry_notification_get_my_data_items(integer, integer, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_notification_get_my_data_items(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_days integer DEFAULT 3) RETURNS TABLE(id uuid, state_code integer, "json" jsonb, modified_at timestamp with time zone, total_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with visible_reviews as (
    select review_row.id, review_row.state_code, review_row.json,
      review_row.modified_at
    from private.reviews as review_row
    where coalesce(review_row.json->'user'->>'id', '') = auth.uid()::text
      and review_row.state_code in (1, -1, 2)
    union
    select review_row.id, review_row.state_code, review_row.json,
      greatest(review_row.modified_at, notification_row.modified_at)
    from private.notifications as notification_row
    join private.reviews as review_row
      on review_row.id = nullif(notification_row.json->>'review_id', '')::uuid
    where notification_row.recipient_user_id = auth.uid()
      and notification_row.type = 'review_event'
      and review_row.state_code in (-1, 2)
  )
  select
    visible_review.id,
    visible_review.state_code,
    coalesce(visible_review.json, '{}'::jsonb),
    visible_review.modified_at,
    count(*) over ()::integer
  from visible_reviews as visible_review
  where coalesce(p_days, 3) <= 0
    or visible_review.modified_at >= now()
      - make_interval(days => greatest(coalesce(p_days, 3), 0))
  order by visible_review.modified_at desc
  offset greatest(coalesce(p_page, 1) - 1, 0)
    * greatest(coalesce(p_page_size, 10), 1)
  limit greatest(coalesce(p_page_size, 10), 1)
$$;


ALTER FUNCTION api.qry_notification_get_my_data_items(p_page integer, p_page_size integer, p_days integer) OWNER TO postgres;

--
-- Name: qry_notification_get_my_issue_count(integer, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_notification_get_my_issue_count(p_days integer DEFAULT 3, p_last_view_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select count(*)::integer
  from private.notifications as n
  where n.recipient_user_id = auth.uid()
    and n.type = 'validation_issue'
    and (
      (p_last_view_at is not null and n.modified_at > p_last_view_at) or
      (p_last_view_at is null and (
        coalesce(p_days, 3) <= 0 or
        n.modified_at >= now() - make_interval(days => greatest(coalesce(p_days, 3), 0))
      ))
    );
$$;


ALTER FUNCTION api.qry_notification_get_my_issue_count(p_days integer, p_last_view_at timestamp with time zone) OWNER TO postgres;

--
-- Name: qry_notification_get_my_issue_items(integer, integer, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_notification_get_my_issue_items(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_days integer DEFAULT 3) RETURNS TABLE(id uuid, type text, dataset_type text, dataset_id uuid, dataset_version text, "json" jsonb, modified_at timestamp with time zone, total_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select
    n.id,
    n.type,
    n.dataset_type,
    n.dataset_id,
    n.dataset_version,
    n.json,
    n.modified_at,
    count(*) over ()::integer as total_count
  from private.notifications as n
  where n.recipient_user_id = auth.uid()
    and n.type = 'validation_issue'
    and (
      coalesce(p_days, 3) <= 0 or
      n.modified_at >= now() - make_interval(days => greatest(coalesce(p_days, 3), 0))
    )
  order by n.modified_at desc
  offset greatest(coalesce(p_page, 1) - 1, 0) * greatest(coalesce(p_page_size, 10), 1)
  limit greatest(coalesce(p_page_size, 10), 1);
$$;


