--
-- Name: qry_notification_get_my_team_count(integer, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_notification_get_my_team_count(p_days integer DEFAULT 3, p_last_view_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select count(*)::integer
  from private.roles as r
  where r.user_id = auth.uid()
    and r.role = 'is_invited'
    and r.team_id <> '00000000-0000-0000-0000-000000000000'::uuid
    and (
      (p_last_view_at is not null and r.modified_at > p_last_view_at) or
      (p_last_view_at is null and (
        coalesce(p_days, 3) <= 0 or
        r.modified_at >= now() - make_interval(days => greatest(coalesce(p_days, 3), 0))
      ))
    );
$$;


ALTER FUNCTION api.qry_notification_get_my_team_count(p_days integer, p_last_view_at timestamp with time zone) OWNER TO postgres;

--
-- Name: qry_notification_get_my_team_items(integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_notification_get_my_team_items(p_days integer DEFAULT 3) RETURNS TABLE(team_id uuid, user_id uuid, role text, team_title jsonb, modified_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select
    r.team_id,
    r.user_id,
    r.role,
    coalesce(t.json -> 'title', '[]'::jsonb) as team_title,
    r.modified_at
  from private.roles as r
  join private.teams as t
    on t.id = r.team_id
  where r.user_id = auth.uid()
    and r.team_id <> '00000000-0000-0000-0000-000000000000'::uuid
    and (
      coalesce(p_days, 3) <= 0 or
      r.modified_at >= now() - make_interval(days => greatest(coalesce(p_days, 3), 0))
    )
  order by r.modified_at desc;
$$;


