--
-- Name: qry_reference_review_impacted_roots(uuid, boolean); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_reference_review_impacted_roots(p_reference_review_id uuid, p_include_history boolean DEFAULT false) RETURNS TABLE(root_review_id uuid, target_table text, data_id uuid, data_version text, state_code integer, is_current boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reference private.reviews%rowtype;
  v_candidate_ids uuid[];
begin
  if v_actor is null or not api.cmd_review_is_review_admin(v_actor) then
    raise exception using errcode = '42501', message = 'REVIEW_ADMIN_REQUIRED';
  end if;

  select review_row.*
  into v_reference
  from private.reviews as review_row
  where review_row.id = p_reference_review_id
    and review_row.review_kind = 'reference';

  if not found then
    return;
  end if;

  select coalesce(
    pg_catalog.array_agg(candidate.root_review_id order by candidate.root_review_id),
    array[]::uuid[]
  )
  into v_candidate_ids
  from private.review_candidate_root_ids_v1(
    v_reference.target_table,
    v_reference.data_id,
    pg_catalog.btrim(v_reference.data_version::text)
  ) as candidate;

  return query
  select
    root_review.id,
    root_review.target_table,
    root_review.data_id,
    pg_catalog.btrim(root_review.data_version::text),
    root_review.state_code,
    true
  from private.review_resolve_current_reference_targets_v1(
    v_candidate_ids
  ) as target
  join private.reviews as root_review
    on root_review.id = target.root_review_id
    and root_review.review_kind = 'root'
  where target.target_table = v_reference.target_table
    and target.data_id = v_reference.data_id
    and target.data_version = pg_catalog.btrim(v_reference.data_version::text)
    and target.revision_checksum = v_reference.submitted_revision_checksum
  order by root_review.modified_at desc, root_review.id;
end;
$$;


ALTER FUNCTION api.qry_reference_review_impacted_roots(p_reference_review_id uuid, p_include_history boolean) OWNER TO postgres;

--
-- Name: FUNCTION qry_reference_review_impacted_roots(p_reference_review_id uuid, p_include_history boolean); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.qry_reference_review_impacted_roots(p_reference_review_id uuid, p_include_history boolean) IS 'Returns current dynamically validated impacted roots from append-only target hints without evaluating unrelated roots. p_include_history is retained for signature compatibility and does not restore historical relationships.';


--
-- Name: qry_review_admin_queue_items_v2(text, integer, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_admin_queue_items_v2(p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS TABLE(id uuid, review_kind text, target_table text, data_id uuid, data_version text, state_code integer, target_owner_id uuid, target_team_id uuid, submitted_revision_checksum text, reviewer_id jsonb, deadline timestamp with time zone, reference_count integer, completed_reviewer_count integer, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null or not api.cmd_review_is_review_admin(v_actor) then
    raise exception using errcode = '42501', message = 'REVIEW_ADMIN_REQUIRED';
  end if;

  return query
  with review_rows as materialized (
    select review_row.*
    from private.reviews as review_row
    where review_row.review_kind in ('root', 'reference')
      and (
        p_status is null
        or (p_status = 'unassigned' and review_row.state_code = 0)
        or (p_status = 'assigned' and review_row.state_code = 1)
        or (p_status = 'approved' and review_row.state_code = 2)
        or (p_status = 'rejected' and review_row.state_code = -1)
      )
  )
  select
    review_row.id,
    review_row.review_kind,
    review_row.target_table,
    review_row.data_id,
    pg_catalog.btrim(review_row.data_version::text),
    review_row.state_code,
    review_row.target_owner_id,
    review_row.target_team_id,
    review_row.submitted_revision_checksum,
    coalesce(review_row.reviewer_id, '[]'::jsonb),
    review_row.deadline,
    case when review_row.review_kind = 'root' then (
      select pg_catalog.count(*)::integer
      from private.review_derive_current_references_v1(array[review_row.id])
    ) else 0 end,
    count(comment_row.reviewer_id)
      filter (where comment_row.state_code in (1, -3, 2))::integer,
    review_row.modified_at,
    pg_catalog.count(*) over ()
  from review_rows as review_row
  left join private.comments as comment_row
    on comment_row.review_id = review_row.id
    and comment_row.state_code <> -2
  group by review_row.id, review_row.review_kind, review_row.target_table,
    review_row.data_id, review_row.data_version, review_row.state_code,
    review_row.target_owner_id, review_row.target_team_id,
    review_row.submitted_revision_checksum, review_row.reviewer_id,
    review_row.deadline, review_row.modified_at
  order by review_row.modified_at desc, review_row.id
  offset greatest(coalesce(p_page, 1) - 1, 0)
    * greatest(coalesce(p_page_size, 20), 1)
  limit least(greatest(coalesce(p_page_size, 20), 1), 100);
end;
$$;


ALTER FUNCTION api.qry_review_admin_queue_items_v2(p_status text, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: qry_review_find_member_candidate_by_email(text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_find_member_candidate_by_email(p_email text) RETURNS TABLE(id uuid, email text, display_name text, contact jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_email text := lower(btrim(coalesce(p_email, '')));
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTH_REQUIRED';
  end if;

  if v_email = '' or length(v_email) > 320 then
    raise exception using errcode = '22023', message = 'INVALID_EMAIL';
  end if;

  if not exists (
    select 1
    from private.roles
    where user_id = v_actor
      and team_id = '00000000-0000-0000-0000-000000000000'::uuid
      and role = 'review-admin'
  ) then
    raise exception using errcode = '42501', message = 'REVIEW_ADMIN_REQUIRED';
  end if;

  return query
  select
    auth_user.id,
    coalesce(
      nullif(btrim(auth_user.email), ''),
      nullif(btrim(auth_user.raw_user_meta_data ->> 'email'), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'email'), '')
    ),
    coalesce(
      nullif(btrim(profile.raw_user_meta_data ->> 'display_name'), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'name'), ''),
      nullif(btrim(auth_user.raw_user_meta_data ->> 'display_name'), ''),
      nullif(btrim(auth_user.raw_user_meta_data ->> 'name'), ''),
      nullif(btrim(auth_user.email), ''),
      nullif(btrim(auth_user.raw_user_meta_data ->> 'email'), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'email'), '')
    ),
    profile.contact
  from auth.users as auth_user
  left join private.users as profile on profile.id = auth_user.id
  where lower(coalesce(
    nullif(btrim(auth_user.email), ''),
    nullif(btrim(auth_user.raw_user_meta_data ->> 'email'), ''),
    nullif(btrim(profile.raw_user_meta_data ->> 'email'), ''),
    ''
  )) = v_email
  order by auth_user.created_at desc nulls last, auth_user.id
  limit 1;
end;
$$;


ALTER FUNCTION api.qry_review_find_member_candidate_by_email(p_email text) OWNER TO postgres;

--
-- Name: qry_review_get_admin_queue_items(text, integer, integer, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_admin_queue_items(p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, state_code integer, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_codes jsonb, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := api.cmd_review_resolve_queue_order_by(p_sort_by, false);
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := lower(coalesce(p_status, ''));
  v_state_code integer;
begin
  if v_actor is null or not api.cmd_review_is_review_admin(v_actor) then
    return;
  end if;

  case v_status
    when '', 'all' then v_state_code := null;
    when 'unassigned' then v_state_code := 0;
    when 'assigned' then v_state_code := 1;
    when 'admin-rejected' then v_state_code := -1;
    else return;
  end case;

  return query execute format(
    $sql$
      with q as (
        select
          r.id,
          r.data_id,
          r.data_version::text as data_version,
          r.state_code,
          coalesce(r.reviewer_id, '[]'::jsonb) as reviewer_id,
          coalesce(r.json, '{}'::jsonb) as json,
          r.deadline,
          r.created_at,
          r.modified_at,
          coalesce(
            jsonb_agg(to_jsonb(c.state_code)
              order by c.created_at, c.reviewer_id)
              filter (where c.reviewer_id is not null),
            '[]'::jsonb
          ) as comment_state_codes
        from private.reviews as r
        left join private.comments as c on c.review_id = r.id
        where r.review_kind in ('root', 'reference')
          and ($1::integer is null or r.state_code = $1::integer)
        group by r.id
      )
      select q.*, count(*) over() as total_count
      from q
      order by %s %s nulls last, q.id asc
      limit $2 offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_state_code, v_limit, v_offset;
end;
$_$;


ALTER FUNCTION api.qry_review_get_admin_queue_items(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) OWNER TO postgres;

--
-- Name: qry_review_get_admin_queue_items_v3(text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_admin_queue_items_v3(p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text, p_display_mode text DEFAULT 'all'::text, p_target_table text DEFAULT NULL::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, state_code integer, review_kind text, target_table text, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_codes jsonb, root_matches_status boolean, root_can_read boolean, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 50), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_sort_key text := case pg_catalog.lower(coalesce(p_sort_by, ''))
    when 'created_at' then 'created_at'
    when 'createat' then 'created_at'
    when 'deadline' then 'deadline'
    when 'state_code' then 'state_code'
    when 'statecode' then 'state_code'
    else 'modified_at'
  end;
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := pg_catalog.lower(coalesce(p_status, ''));
  v_display_mode text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_display_mode, 'all')));
  v_target_table text := nullif(
    pg_catalog.lower(pg_catalog.btrim(coalesce(p_target_table, ''))),
    ''
  );
  v_state_code integer;
begin
  if v_actor is null or not api.cmd_review_is_review_admin(v_actor) then
    return;
  end if;

  case v_status
    when '', 'all' then v_state_code := null;
    when 'unassigned' then v_state_code := 0;
    when 'assigned' then v_state_code := 1;
    when 'admin-rejected' then v_state_code := -1;
    else return;
  end case;

  if v_display_mode not in ('all', 'model_process', 'other') then
    raise exception using
      errcode = '22023',
      message = 'INVALID_REVIEW_DISPLAY_MODE';
  end if;
  if v_target_table is not null and not (
    v_target_table = any(array[
      'contacts', 'sources', 'unitgroups', 'flowproperties', 'flows',
      'processes', 'lifecyclemodels'
    ]::text[])
  ) then
    raise exception using
      errcode = '22023',
      message = 'INVALID_REVIEW_TARGET_TABLE';
  end if;

  return query
  with q as (
    select
      review_row.id,
      review_row.data_id,
      pg_catalog.btrim(review_row.data_version::text) as data_version,
      review_row.state_code,
      review_row.review_kind,
      review_row.target_table,
      coalesce(review_row.reviewer_id, '[]'::jsonb) as reviewer_id,
      coalesce(review_row.json, '{}'::jsonb) as json,
      review_row.deadline,
      review_row.created_at,
      review_row.modified_at,
      coalesce(review_comments.comment_state_codes, '[]'::jsonb) as comment_state_codes,
      true as root_matches_status,
      true as root_can_read
    from private.reviews as review_row
    left join lateral (
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(comment_row.state_code)
        order by comment_row.created_at, comment_row.reviewer_id
      ) filter (where comment_row.reviewer_id is not null) as comment_state_codes
      from private.comments as comment_row
      where comment_row.review_id = review_row.id
    ) as review_comments on true
    where review_row.review_kind in ('root', 'reference')
      and (v_state_code is null or review_row.state_code = v_state_code)
      and (
        v_display_mode = 'all'
        or (
          v_display_mode = 'model_process'
          and review_row.target_table in ('processes', 'lifecyclemodels')
        )
        or (
          v_display_mode = 'other'
          and review_row.target_table not in ('processes', 'lifecyclemodels')
        )
      )
      and (v_target_table is null or review_row.target_table = v_target_table)
  )
  select q.*, pg_catalog.count(*) over() as total_count
  from q
  order by
    case when v_sort_key = 'created_at' and v_order_dir = 'asc' then q.created_at end asc nulls last,
    case when v_sort_key = 'created_at' and v_order_dir = 'desc' then q.created_at end desc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'asc' then q.deadline end asc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'desc' then q.deadline end desc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'asc' then q.state_code end asc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'desc' then q.state_code end desc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'asc' then q.modified_at end asc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'desc' then q.modified_at end desc nulls last,
    q.id
  limit v_limit offset v_offset;
end;
$$;


ALTER FUNCTION api.qry_review_get_admin_queue_items_v3(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_display_mode text, p_target_table text) OWNER TO postgres;

--
-- Name: FUNCTION qry_review_get_admin_queue_items_v3(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_display_mode text, p_target_table text); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.qry_review_get_admin_queue_items_v3(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_display_mode text, p_target_table text) IS 'Current Admin queue with server-side display-mode and target-table filtering, then one independently paginated row per Root or Reference Review. Relationships are rendered separately and are not persisted.';


--
-- Name: qry_review_get_admin_root_queue_items_v2(text, integer, integer, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_admin_root_queue_items_v2(p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, state_code integer, review_kind text, target_table text, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_codes jsonb, root_matches_status boolean, root_can_read boolean, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_sort_key text := case pg_catalog.lower(coalesce(p_sort_by, ''))
    when 'created_at' then 'created_at'
    when 'createat' then 'created_at'
    when 'deadline' then 'deadline'
    when 'state_code' then 'state_code'
    when 'statecode' then 'state_code'
    else 'modified_at'
  end;
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := pg_catalog.lower(coalesce(p_status, ''));
  v_state_code integer;
begin
  if v_actor is null or not api.cmd_review_is_review_admin(v_actor) then
    return;
  end if;

  case v_status
    when '', 'all' then v_state_code := null;
    when 'unassigned' then v_state_code := 0;
    when 'assigned' then v_state_code := 1;
    when 'admin-rejected' then v_state_code := -1;
    else return;
  end case;

  return query
  with matching_reference_tasks as materialized (
    select reference_review.*
    from private.reviews as reference_review
    where v_state_code is not null
      and reference_review.review_kind = 'reference'
      and reference_review.state_code = v_state_code
  ),
  direct_roots as materialized (
    select root_review.id
    from private.reviews as root_review
    where root_review.review_kind = 'root'
      and (v_state_code is null or root_review.state_code = v_state_code)
  ),
  hinted_roots as materialized (
    select distinct candidate.root_review_id as id
    from matching_reference_tasks as reference_review
    cross join lateral private.review_candidate_root_ids_v1(
      reference_review.target_table,
      reference_review.data_id,
      pg_catalog.btrim(reference_review.data_version::text)
    ) as candidate
  ),
  candidate_roots as materialized (
    select direct_root.id from direct_roots as direct_root
    union
    select hinted_root.id from hinted_roots as hinted_root
  ),
  derived_references as materialized (
    select derived.*
    from private.review_derive_current_references_v1(
      coalesce(
        (select pg_catalog.array_agg(candidate.id order by candidate.id) from candidate_roots as candidate),
        array[]::uuid[]
      )
    ) as derived
  ),
  root_matches as (
    select
      root_review.id as root_review_id,
      true as root_matches_status,
      root_review.modified_at as matching_task_modified_at
    from private.reviews as root_review
    join direct_roots as direct_root on direct_root.id = root_review.id

    union all

    select
      derived.root_review_id,
      false,
      reference_review.modified_at
    from derived_references as derived
    join matching_reference_tasks as reference_review
      on reference_review.id = derived.reference_review_id
  ),
  grouped_roots as (
    select
      root_match.root_review_id,
      pg_catalog.bool_or(root_match.root_matches_status) as root_matches_status,
      pg_catalog.max(root_match.matching_task_modified_at) as matching_task_modified_at
    from root_matches as root_match
    group by root_match.root_review_id
  ),
  q as (
    select
      root_review.id,
      root_review.data_id,
      pg_catalog.btrim(root_review.data_version::text) as data_version,
      root_review.state_code,
      root_review.review_kind,
      root_review.target_table,
      coalesce(root_review.reviewer_id, '[]'::jsonb) as reviewer_id,
      coalesce(root_review.json, '{}'::jsonb) as json,
      root_review.deadline,
      root_review.created_at,
      grouped.matching_task_modified_at as modified_at,
      coalesce(root_comments.comment_state_codes, '[]'::jsonb) as comment_state_codes,
      grouped.root_matches_status,
      true as root_can_read
    from grouped_roots as grouped
    join private.reviews as root_review
      on root_review.id = grouped.root_review_id
      and root_review.review_kind = 'root'
    left join lateral (
      select pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(root_comment.state_code)
        order by root_comment.created_at, root_comment.reviewer_id
      ) filter (where root_comment.reviewer_id is not null) as comment_state_codes
      from private.comments as root_comment
      where root_comment.review_id = root_review.id
    ) as root_comments on true
  )
  select q.*, pg_catalog.count(*) over() as total_count
  from q
  order by
    case when v_sort_key = 'created_at' and v_order_dir = 'asc' then q.created_at end asc nulls last,
    case when v_sort_key = 'created_at' and v_order_dir = 'desc' then q.created_at end desc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'asc' then q.deadline end asc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'desc' then q.deadline end desc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'asc' then q.state_code end asc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'desc' then q.state_code end desc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'asc' then q.modified_at end asc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'desc' then q.modified_at end desc nulls last,
    q.id
  limit v_limit offset v_offset;
end;
$$;


ALTER FUNCTION api.qry_review_get_admin_root_queue_items_v2(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) OWNER TO postgres;

--
-- Name: FUNCTION qry_review_get_admin_root_queue_items_v2(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.qry_review_get_admin_root_queue_items_v2(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) IS 'Current-state Admin queue grouped by candidate Root Review. Direct or candidate-hinted child matches can include a parent; unrelated roots are not derived.';


--
-- Name: qry_review_get_comment_items(uuid, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_comment_items(p_review_id uuid, p_scope text DEFAULT 'auto'::text) RETURNS TABLE(review_id uuid, reviewer_id uuid, state_code integer, "json" jsonb, created_at timestamp with time zone, modified_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  with actor as (
    select
      auth.uid() as actor_id,
      api.cmd_review_is_review_admin(auth.uid()) as is_review_admin,
      exists (
        select 1
        from private.reviews as r
        where r.id = p_review_id
          and ((r.json -> 'user' ->> 'id')::uuid = auth.uid())
      ) as is_owner
  )
  select
    c.review_id,
    c.reviewer_id,
    c.state_code,
    coalesce(c.json::jsonb, '{}'::jsonb) as json,
    c.created_at,
    c.modified_at
  from private.comments as c
  cross join actor as a
  where c.review_id = p_review_id
    and api.policy_review_can_read(p_review_id, a.actor_id)
    and (
      a.is_review_admin
      or a.is_owner
      or c.reviewer_id = a.actor_id
    )
    and (
      lower(coalesce(p_scope, 'auto')) not in ('mine', 'self')
      or c.reviewer_id = a.actor_id
    )
  order by c.created_at asc, c.reviewer_id asc
$$;


ALTER FUNCTION api.qry_review_get_comment_items(p_review_id uuid, p_scope text) OWNER TO postgres;

--
-- Name: qry_review_get_items(uuid[], uuid, text, integer[]); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_items(p_review_ids uuid[] DEFAULT NULL::uuid[], p_data_id uuid DEFAULT NULL::uuid, p_data_version text DEFAULT NULL::text, p_state_codes integer[] DEFAULT NULL::integer[]) RETURNS TABLE(id uuid, data_id uuid, data_version text, state_code integer, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select
    r.id,
    r.data_id,
    r.data_version::text as data_version,
    r.state_code,
    coalesce(r.reviewer_id, '[]'::jsonb) as reviewer_id,
    coalesce(r.json, '{}'::jsonb) as json,
    r.deadline,
    r.created_at,
    r.modified_at
  from private.reviews as r
  where (p_review_ids is null or r.id = any (p_review_ids))
    and (
      p_data_id is null
      or r.data_id = p_data_id
      or coalesce(r.json -> 'data' ->> 'id', '') = p_data_id::text
    )
    and (
      p_data_version is null
      or r.data_version = p_data_version
      or coalesce(r.json -> 'data' ->> 'version', '') = p_data_version
    )
    and (p_state_codes is null or r.state_code = any (p_state_codes))
    and api.policy_review_can_read(r.id, auth.uid())
  order by r.modified_at desc, r.id desc
$$;


ALTER FUNCTION api.qry_review_get_items(p_review_ids uuid[], p_data_id uuid, p_data_version text, p_state_codes integer[]) OWNER TO postgres;

--
-- Name: qry_review_get_member_list(integer, integer, text, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_member_list(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'created_at'::text, p_sort_order text DEFAULT 'desc'::text, p_role text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, team_id uuid, role text, email text, display_name text, created_at timestamp with time zone, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := api.cmd_membership_resolve_member_order_by(p_sort_by, false);
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
begin
  if v_actor is null then
    return;
  end if;

  if not api.cmd_membership_is_review_admin(v_actor) then
    return;
  end if;

  return query execute format(
    $sql$
      with members as (
        select
          r.user_id,
          r.team_id,
          r.role::text as role,
          coalesce(u.raw_user_meta_data->>'email', '') as email,
          coalesce(
            nullif(u.raw_user_meta_data->>'display_name', ''),
            u.raw_user_meta_data->>'email',
            '-'
          ) as display_name,
          r.created_at,
          r.modified_at
        from private.roles as r
        left join private.users as u
          on u.id = r.user_id
        where r.team_id = $1
          and r.role in ('review-admin', 'review-member')
          and ($4::text is null or r.role = $4::text)
      )
      select
        m.user_id,
        m.team_id,
        m.role,
        m.email,
        m.display_name,
        m.created_at,
        m.modified_at,
        count(*) over() as total_count
      from members as m
      order by %s %s nulls last, m.user_id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_team_id, v_limit, v_offset, p_role;
end;
$_$;


ALTER FUNCTION api.qry_review_get_member_list(p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_role text) OWNER TO postgres;

--
-- Name: qry_review_get_member_queue_items(text, integer, integer, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_member_queue_items(p_status text DEFAULT 'pending'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, review_state_code integer, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_code integer, comment_json jsonb, comment_created_at timestamp with time zone, comment_modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := api.cmd_review_resolve_queue_order_by(p_sort_by, true);
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := lower(coalesce(p_status, 'pending'));
begin
  if v_actor is null or not api.cmd_review_is_review_member(v_actor) then
    return;
  end if;
  if v_status not in ('pending', 'reviewed', 'reviewer-rejected') then
    return;
  end if;

  return query execute format(
    $sql$
      with q as (
        select
          r.id,
          r.data_id,
          r.data_version::text as data_version,
          r.state_code as review_state_code,
          coalesce(r.reviewer_id, '[]'::jsonb) as reviewer_id,
          coalesce(r.json, '{}'::jsonb) as json,
          r.deadline,
          r.created_at,
          r.modified_at,
          c.state_code as comment_state_code,
          coalesce(c.json::jsonb, '{}'::jsonb) as comment_json,
          c.created_at as comment_created_at,
          c.modified_at as comment_modified_at
        from private.comments as c
        join private.reviews as r on r.id = c.review_id
        where r.review_kind in ('root', 'reference')
          and c.reviewer_id = $1
          and api.policy_review_can_read(r.id, $1)
          and (
            ($4 = 'pending' and c.state_code = 0 and r.state_code > 0)
            or ($4 = 'reviewed'
              and c.state_code = any (array[1, 2, -3])
              and r.state_code > 0)
            or ($4 = 'reviewer-rejected'
              and c.state_code = -1
              and r.state_code = -1)
          )
      )
      select q.*, count(*) over() as total_count
      from q
      order by %s %s nulls last, q.id asc
      limit $2 offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_actor, v_limit, v_offset, v_status;
end;
$_$;


ALTER FUNCTION api.qry_review_get_member_queue_items(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) OWNER TO postgres;

--
-- Name: qry_review_get_member_queue_items_v3(text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_member_queue_items_v3(p_status text DEFAULT 'pending'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text, p_display_mode text DEFAULT 'all'::text, p_target_table text DEFAULT NULL::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, review_state_code integer, review_kind text, target_table text, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_code integer, comment_json jsonb, comment_created_at timestamp with time zone, comment_modified_at timestamp with time zone, root_matches_status boolean, root_can_read boolean, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 50), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_sort_key text := case pg_catalog.lower(coalesce(p_sort_by, ''))
    when 'created_at' then 'created_at'
    when 'createat' then 'created_at'
    when 'deadline' then 'deadline'
    when 'state_code' then 'state_code'
    when 'statecode' then 'state_code'
    when 'comment_modified_at' then 'comment_modified_at'
    when 'commentmodifiedat' then 'comment_modified_at'
    else 'modified_at'
  end;
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := pg_catalog.lower(coalesce(p_status, 'pending'));
  v_display_mode text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_display_mode, 'all')));
  v_target_table text := nullif(
    pg_catalog.lower(pg_catalog.btrim(coalesce(p_target_table, ''))),
    ''
  );
begin
  if v_actor is null or not api.cmd_review_is_review_member(v_actor) then
    return;
  end if;
  if v_status not in ('pending', 'reviewed', 'reviewer-rejected') then
    return;
  end if;
  if v_display_mode not in ('all', 'model_process', 'other') then
    raise exception using
      errcode = '22023',
      message = 'INVALID_REVIEW_DISPLAY_MODE';
  end if;
  if v_target_table is not null and not (
    v_target_table = any(array[
      'contacts', 'sources', 'unitgroups', 'flowproperties', 'flows',
      'processes', 'lifecyclemodels'
    ]::text[])
  ) then
    raise exception using
      errcode = '22023',
      message = 'INVALID_REVIEW_TARGET_TABLE';
  end if;

  return query
  with q as (
    select
      review_row.id,
      review_row.data_id,
      pg_catalog.btrim(review_row.data_version::text) as data_version,
      review_row.state_code as review_state_code,
      review_row.review_kind,
      review_row.target_table,
      coalesce(review_row.reviewer_id, '[]'::jsonb) as reviewer_id,
      coalesce(review_row.json, '{}'::jsonb) as json,
      review_row.deadline,
      review_row.created_at,
      greatest(review_row.modified_at, comment_row.modified_at) as modified_at,
      comment_row.state_code as comment_state_code,
      coalesce(comment_row.json::jsonb, '{}'::jsonb) as comment_json,
      comment_row.created_at as comment_created_at,
      comment_row.modified_at as comment_modified_at,
      true as root_matches_status,
      true as root_can_read
    from private.comments as comment_row
    join private.reviews as review_row on review_row.id = comment_row.review_id
    where review_row.review_kind in ('root', 'reference')
      and comment_row.reviewer_id = v_actor
      and api.policy_review_can_read(review_row.id, v_actor)
      and (
        v_display_mode = 'all'
        or (
          v_display_mode = 'model_process'
          and review_row.target_table in ('processes', 'lifecyclemodels')
        )
        or (
          v_display_mode = 'other'
          and review_row.target_table not in ('processes', 'lifecyclemodels')
        )
      )
      and (v_target_table is null or review_row.target_table = v_target_table)
      and (
        (v_status = 'pending' and comment_row.state_code = 0 and review_row.state_code > 0)
        or (v_status = 'reviewed' and comment_row.state_code = any(array[1, 2, -3]) and review_row.state_code > 0)
        or (v_status = 'reviewer-rejected' and comment_row.state_code = -1 and review_row.state_code = -1)
      )
  )
  select q.*, pg_catalog.count(*) over() as total_count
  from q
  order by
    case when v_sort_key = 'created_at' and v_order_dir = 'asc' then q.created_at end asc nulls last,
    case when v_sort_key = 'created_at' and v_order_dir = 'desc' then q.created_at end desc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'asc' then q.deadline end asc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'desc' then q.deadline end desc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'asc' then q.review_state_code end asc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'desc' then q.review_state_code end desc nulls last,
    case when v_sort_key = 'comment_modified_at' and v_order_dir = 'asc' then q.comment_modified_at end asc nulls last,
    case when v_sort_key = 'comment_modified_at' and v_order_dir = 'desc' then q.comment_modified_at end desc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'asc' then q.modified_at end asc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'desc' then q.modified_at end desc nulls last,
    q.id
  limit v_limit offset v_offset;
end;
$$;


ALTER FUNCTION api.qry_review_get_member_queue_items_v3(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_display_mode text, p_target_table text) OWNER TO postgres;

--
-- Name: FUNCTION qry_review_get_member_queue_items_v3(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_display_mode text, p_target_table text); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.qry_review_get_member_queue_items_v3(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_display_mode text, p_target_table text) IS 'Current actor queue with server-side display-mode and target-table filtering, then one independently paginated row per readable assigned Root or Reference Review.';


--
-- Name: qry_review_get_member_root_queue_items_v2(text, integer, integer, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_member_root_queue_items_v2(p_status text DEFAULT 'pending'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'modified_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(id uuid, data_id uuid, data_version text, review_state_code integer, review_kind text, target_table text, reviewer_id jsonb, "json" jsonb, deadline timestamp with time zone, created_at timestamp with time zone, modified_at timestamp with time zone, comment_state_code integer, comment_json jsonb, comment_created_at timestamp with time zone, comment_modified_at timestamp with time zone, root_matches_status boolean, root_can_read boolean, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_sort_key text := case pg_catalog.lower(coalesce(p_sort_by, ''))
    when 'created_at' then 'created_at'
    when 'createat' then 'created_at'
    when 'deadline' then 'deadline'
    when 'state_code' then 'state_code'
    when 'statecode' then 'state_code'
    when 'comment_modified_at' then 'comment_modified_at'
    when 'commentmodifiedat' then 'comment_modified_at'
    else 'modified_at'
  end;
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
  v_status text := pg_catalog.lower(coalesce(p_status, 'pending'));
begin
  if v_actor is null or not api.cmd_review_is_review_member(v_actor) then
    return;
  end if;
  if v_status not in ('pending', 'reviewed', 'reviewer-rejected') then
    return;
  end if;

  return query
  with matching_tasks as materialized (
    select
      review_row.id,
      review_row.review_kind,
      review_row.target_table,
      review_row.data_id,
      pg_catalog.btrim(review_row.data_version::text) as data_version,
      comment_row.state_code as comment_state_code,
      coalesce(comment_row.json::jsonb, '{}'::jsonb) as comment_json,
      comment_row.created_at as comment_created_at,
      comment_row.modified_at as comment_modified_at,
      greatest(review_row.modified_at, comment_row.modified_at) as task_modified_at
    from private.comments as comment_row
    join private.reviews as review_row on review_row.id = comment_row.review_id
    where review_row.review_kind in ('root', 'reference')
      and comment_row.reviewer_id = v_actor
      and api.policy_review_can_read(review_row.id, v_actor)
      and (
        (v_status = 'pending' and comment_row.state_code = 0 and review_row.state_code > 0)
        or (v_status = 'reviewed' and comment_row.state_code = any(array[1, 2, -3]) and review_row.state_code > 0)
        or (v_status = 'reviewer-rejected' and comment_row.state_code = -1 and review_row.state_code = -1)
      )
  ),
  direct_roots as materialized (
    select task.id
    from matching_tasks as task
    where task.review_kind = 'root'
  ),
  hinted_roots as materialized (
    select distinct candidate.root_review_id as id
    from matching_tasks as task
    cross join lateral private.review_candidate_root_ids_v1(
      task.target_table,
      task.data_id,
      task.data_version
    ) as candidate
    where task.review_kind = 'reference'
  ),
  candidate_roots as materialized (
    select direct_root.id from direct_roots as direct_root
    union
    select hinted_root.id from hinted_roots as hinted_root
  ),
  derived_references as materialized (
    select derived.*
    from private.review_derive_current_references_v1(
      coalesce(
        (select pg_catalog.array_agg(candidate.id order by candidate.id) from candidate_roots as candidate),
        array[]::uuid[]
      )
    ) as derived
  ),
  root_matches as (
    select task.id as root_review_id, true as root_matches_status, task.task_modified_at
    from matching_tasks as task
    where task.review_kind = 'root'

    union all

    select derived.root_review_id, false, task.task_modified_at
    from derived_references as derived
    join matching_tasks as task
      on task.id = derived.reference_review_id
      and task.review_kind = 'reference'
  ),
  grouped_roots as (
    select
      root_match.root_review_id,
      pg_catalog.bool_or(root_match.root_matches_status) as root_matches_status,
      pg_catalog.max(root_match.task_modified_at) as matching_task_modified_at
    from root_matches as root_match
    group by root_match.root_review_id
  ),
  q as (
    select
      root_review.id,
      root_review.data_id,
      pg_catalog.btrim(root_review.data_version::text) as data_version,
      root_review.state_code,
      root_review.review_kind,
      root_review.target_table,
      coalesce(root_review.reviewer_id, '[]'::jsonb) as reviewer_id,
      case
        when api.policy_review_can_read(root_review.id, v_actor) then coalesce(root_review.json, '{}'::jsonb)
        else pg_catalog.jsonb_build_object(
          'review_kind', 'root',
          'data', pg_catalog.jsonb_build_object(
            'id', root_review.data_id,
            'version', pg_catalog.btrim(root_review.data_version::text),
            'name', root_review.json #> '{data,name}',
            'table', root_review.target_table
          ),
          'user', pg_catalog.jsonb_build_object(
            'id', root_review.target_owner_id,
            'name', root_review.json #> '{user,name}'
          ),
          'team', pg_catalog.jsonb_build_object(
            'id', root_review.target_team_id,
            'name', root_review.json #> '{team,name}'
          )
        )
      end as json,
      root_review.deadline,
      root_review.created_at,
      grouped.matching_task_modified_at as modified_at,
      direct_task.comment_state_code,
      coalesce(direct_task.comment_json, '{}'::jsonb) as comment_json,
      direct_task.comment_created_at,
      grouped.matching_task_modified_at as comment_modified_at,
      grouped.root_matches_status,
      api.policy_review_can_read(root_review.id, v_actor) as root_can_read
    from grouped_roots as grouped
    join private.reviews as root_review
      on root_review.id = grouped.root_review_id
      and root_review.review_kind = 'root'
    left join matching_tasks as direct_task
      on direct_task.id = root_review.id
      and direct_task.review_kind = 'root'
  )
  select
    q.id,
    q.data_id,
    q.data_version,
    q.state_code,
    q.review_kind,
    q.target_table,
    q.reviewer_id,
    q.json,
    q.deadline,
    q.created_at,
    q.modified_at,
    q.comment_state_code,
    q.comment_json,
    q.comment_created_at,
    q.comment_modified_at,
    q.root_matches_status,
    q.root_can_read,
    pg_catalog.count(*) over()
  from q
  order by
    case when v_sort_key = 'created_at' and v_order_dir = 'asc' then q.created_at end asc nulls last,
    case when v_sort_key = 'created_at' and v_order_dir = 'desc' then q.created_at end desc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'asc' then q.deadline end asc nulls last,
    case when v_sort_key = 'deadline' and v_order_dir = 'desc' then q.deadline end desc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'asc' then q.state_code end asc nulls last,
    case when v_sort_key = 'state_code' and v_order_dir = 'desc' then q.state_code end desc nulls last,
    case when v_sort_key = 'comment_modified_at' and v_order_dir = 'asc' then q.comment_modified_at end asc nulls last,
    case when v_sort_key = 'comment_modified_at' and v_order_dir = 'desc' then q.comment_modified_at end desc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'asc' then q.modified_at end asc nulls last,
    case when v_sort_key = 'modified_at' and v_order_dir = 'desc' then q.modified_at end desc nulls last,
    q.id
  limit v_limit offset v_offset;
end;
$$;


ALTER FUNCTION api.qry_review_get_member_root_queue_items_v2(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) OWNER TO postgres;

--
-- Name: FUNCTION qry_review_get_member_root_queue_items_v2(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.qry_review_get_member_root_queue_items_v2(p_status text, p_page integer, p_page_size integer, p_sort_by text, p_sort_order text) IS 'Current-state Member queue grouped by candidate Root Review. Direct or candidate-hinted child matches can include a parent; unrelated roots are not derived.';


--
-- Name: qry_review_get_member_workload(integer, integer, text, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_get_member_workload(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'created_at'::text, p_sort_order text DEFAULT 'desc'::text, p_role text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, team_id uuid, role text, email text, display_name text, pending_count bigint, reviewed_count bigint, created_at timestamp with time zone, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := api.cmd_membership_resolve_member_order_by(p_sort_by, true);
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
begin
  if v_actor is null then
    return;
  end if;

  if not api.cmd_membership_is_review_admin(v_actor) then
    return;
  end if;

  return query execute format(
    $sql$
      with members as (
        select
          r.user_id,
          r.team_id,
          r.role::text as role,
          coalesce(u.raw_user_meta_data->>'email', '') as email,
          coalesce(
            nullif(u.raw_user_meta_data->>'display_name', ''),
            u.raw_user_meta_data->>'email',
            '-'
          ) as display_name,
          coalesce(w.pending_count, 0) as pending_count,
          coalesce(w.reviewed_count, 0) as reviewed_count,
          r.created_at,
          r.modified_at
        from private.roles as r
        left join private.users as u
          on u.id = r.user_id
        left join lateral (
          select
            count(*) filter (
              where c.state_code = 0
                and rv.state_code > 0
            ) as pending_count,
            count(*) filter (
              where c.state_code in (1, 2)
                and rv.state_code > 0
            ) as reviewed_count
          from private.comments as c
          join private.reviews as rv
            on rv.id = c.review_id
          where c.reviewer_id = r.user_id
            and c.state_code in (0, 1, 2)
        ) as w on true
        where r.team_id = $1
          and r.role in ('review-admin', 'review-member')
          and ($4::text is null or r.role = $4::text)
      )
      select
        m.user_id,
        m.team_id,
        m.role,
        m.email,
        m.display_name,
        m.pending_count,
        m.reviewed_count,
        m.created_at,
        m.modified_at,
        count(*) over() as total_count
      from members as m
      order by %s %s nulls last, m.user_id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_team_id, v_limit, v_offset, p_role;
end;
$_$;


ALTER FUNCTION api.qry_review_get_member_workload(p_page integer, p_page_size integer, p_sort_by text, p_sort_order text, p_role text) OWNER TO postgres;

--
-- Name: qry_review_member_queue_items_v2(text, integer, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_member_queue_items_v2(p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS TABLE(id uuid, review_kind text, target_table text, data_id uuid, data_version text, state_code integer, submitted_revision_checksum text, my_comment_state_code integer, deadline timestamp with time zone, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    review_row.id,
    review_row.review_kind,
    review_row.target_table,
    review_row.data_id,
    btrim(review_row.data_version::text),
    review_row.state_code,
    review_row.submitted_revision_checksum,
    comment_row.state_code,
    review_row.deadline,
    review_row.modified_at,
    count(*) over ()
  from private.reviews as review_row
  join private.comments as comment_row
    on comment_row.review_id = review_row.id
    and comment_row.reviewer_id = auth.uid()
    and comment_row.state_code <> -2
  where review_row.review_kind in ('root', 'reference')
    and coalesce(review_row.reviewer_id, '[]'::jsonb)
      @> jsonb_build_array(auth.uid()::text)
    and (
      p_status is null
      or (p_status = 'pending' and comment_row.state_code = 0)
      or (p_status = 'completed' and comment_row.state_code in (1, -3, 2))
    )
  order by review_row.modified_at desc, review_row.id
  offset greatest(coalesce(p_page, 1) - 1, 0)
    * greatest(coalesce(p_page_size, 20), 1)
  limit least(greatest(coalesce(p_page_size, 20), 1), 100)
$$;


ALTER FUNCTION api.qry_review_member_queue_items_v2(p_status text, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: qry_review_quality_diagnostic(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_review_quality_diagnostic(p_run_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_job private.worker_jobs%rowtype;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not api.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Review Admin role is required'
    );
  end if;

  select job.*
  into v_job
  from private.worker_jobs as job
  where job.job_kind = 'review.quality_diagnostic'
    and (p_run_id is null or job.id = p_run_id)
  order by job.updated_at desc, job.id desc
  limit 1;

  if not found then
    if p_run_id is null then
      return jsonb_build_object('ok', true, 'data', null);
    end if;

    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_QUALITY_DIAGNOSTIC_NOT_FOUND',
      'status', 404,
      'message', 'Review quality diagnostic run not found'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', private.review_quality_diagnostic_projection(v_job)
  );
end;
$$;


ALTER FUNCTION api.qry_review_quality_diagnostic(p_run_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION qry_review_quality_diagnostic(p_run_id uuid); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.qry_review_quality_diagnostic(p_run_id uuid) IS 'Returns one or the latest Review Admin quality diagnostic report. Findings, not-evaluable outcomes, and failures are informational only.';


--
-- Name: qry_root_review_reference_progress(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_root_review_reference_progress(p_root_review_id uuid) RETURNS TABLE(reference_review_id uuid, target_table text, data_id uuid, data_version text, submitted_revision_checksum text, state_code integer, reviewer_count integer, completed_reviewer_count integer, relation_paths jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null or not api.cmd_review_is_review_admin(v_actor) then
    raise exception using errcode = '42501', message = 'REVIEW_ADMIN_REQUIRED';
  end if;

  return query
  select
    progress.reference_review_id,
    progress.target_table,
    progress.data_id,
    progress.data_version,
    progress.submitted_revision_checksum,
    progress.state_code,
    progress.reviewer_count,
    progress.completed_reviewer_count,
    '[]'::jsonb
  from api.qry_root_review_reference_progress_v2(p_root_review_id) as progress;
end;
$$;


ALTER FUNCTION api.qry_root_review_reference_progress(p_root_review_id uuid) OWNER TO postgres;

--
-- Name: qry_root_review_reference_progress_v2(uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_root_review_reference_progress_v2(p_root_review_id uuid) RETURNS TABLE(reference_review_id uuid, target_table text, data_id uuid, data_version text, data_name jsonb, submitted_revision_checksum text, state_code integer, reviewer_count integer, completed_reviewer_count integer, actor_comment_state_code integer, actor_comment_modified_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_is_admin boolean;
  v_is_member boolean;
begin
  v_is_admin := v_actor is not null
    and api.cmd_review_is_review_admin(v_actor);
  v_is_member := v_actor is not null
    and api.cmd_review_is_review_member(v_actor);

  if not v_is_admin and not v_is_member then
    raise exception using errcode = '42501', message = 'REVIEW_ROLE_REQUIRED';
  end if;

  return query
  select
    reference_review.id,
    derived.target_table,
    derived.data_id,
    derived.data_version,
    coalesce(reference_review.json #> '{data,name}', '{}'::jsonb),
    reference_review.submitted_revision_checksum,
    reference_review.state_code,
    pg_catalog.jsonb_array_length(
      coalesce(reference_review.reviewer_id, '[]'::jsonb)
    )::integer,
    (
      select pg_catalog.count(*)::integer
      from private.comments as completed_comment
      where completed_comment.review_id = reference_review.id
        and completed_comment.state_code in (1, -3, 2)
    ),
    actor_comment.state_code,
    actor_comment.modified_at
  from private.review_derive_current_references_v1(
    array[p_root_review_id]::uuid[]
  ) as derived
  join private.reviews as reference_review
    on reference_review.id = derived.reference_review_id
  left join lateral (
    select comment_row.state_code, comment_row.modified_at
    from private.comments as comment_row
    where comment_row.review_id = reference_review.id
      and comment_row.reviewer_id = v_actor
    order by comment_row.modified_at desc, comment_row.created_at desc
    limit 1
  ) as actor_comment on true
  where v_is_admin
    or (
      v_is_member
      and api.policy_review_can_read(reference_review.id, v_actor)
      and actor_comment.state_code is not null
      and actor_comment.state_code <> -2
    )
  order by derived.target_table, derived.data_id, derived.data_version;
end;
$$;


ALTER FUNCTION api.qry_root_review_reference_progress_v2(p_root_review_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION qry_root_review_reference_progress_v2(p_root_review_id uuid); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.qry_root_review_reference_progress_v2(p_root_review_id uuid) IS 'Current Reference Review child rows for Review Management; intentionally excludes relation paths and aggregate overview fields.';


--
-- Name: qry_system_find_member_candidate_by_email(text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_system_find_member_candidate_by_email(p_email text) RETURNS TABLE(id uuid, email text, display_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_email text := lower(btrim(coalesce(p_email, '')));
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTH_REQUIRED';
  end if;
  if v_email = '' or length(v_email) > 320 then
    raise exception using errcode = '22023', message = 'INVALID_EMAIL';
  end if;
  if not exists (
    select 1 from private.roles
    where user_id = v_actor
      and team_id = '00000000-0000-0000-0000-000000000000'::uuid
      and role in ('owner', 'admin', 'member')
  ) then
    raise exception using errcode = '42501', message = 'SYSTEM_MANAGER_REQUIRED';
  end if;

  return query
  select
    profile.id,
    coalesce(nullif(btrim(auth_user.email), ''), nullif(btrim(profile.raw_user_meta_data ->> 'email'), '')),
    coalesce(
      nullif(btrim(profile.raw_user_meta_data ->> 'display_name'), ''),
      nullif(btrim(profile.raw_user_meta_data ->> 'name'), ''),
      nullif(btrim(auth_user.email), '')
    )
  from private.users as profile
  left join auth.users as auth_user on auth_user.id = profile.id
  where lower(btrim(coalesce(auth_user.email, profile.raw_user_meta_data ->> 'email', ''))) = v_email
  order by auth_user.created_at desc nulls last, profile.id
  limit 1;
end
$$;


ALTER FUNCTION api.qry_system_find_member_candidate_by_email(p_email text) OWNER TO postgres;

--
-- Name: qry_system_get_member_list(integer, integer, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.qry_system_get_member_list(p_page integer DEFAULT 1, p_page_size integer DEFAULT 10, p_sort_by text DEFAULT 'created_at'::text, p_sort_order text DEFAULT 'desc'::text) RETURNS TABLE(user_id uuid, team_id uuid, role text, email text, display_name text, created_at timestamp with time zone, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'api', 'private', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_team_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_limit integer := greatest(1, least(coalesce(p_page_size, 10), 100));
  v_offset integer := (greatest(coalesce(p_page, 1), 1) - 1) * v_limit;
  v_order_by text := api.cmd_membership_resolve_member_order_by(p_sort_by, false);
  v_order_dir text := api.cmd_membership_resolve_sort_direction(p_sort_order);
begin
  if v_actor is null then
    return;
  end if;

  if not api.cmd_membership_is_system_manager(v_actor) then
    return;
  end if;

  return query execute format(
    $sql$
      with members as (
        select
          membership.user_id,
          membership.team_id,
          membership.role::text as role,
          coalesce(
            nullif(btrim(auth_user.email), ''),
            nullif(btrim(profile.raw_user_meta_data ->> 'email'), ''),
            ''
          ) as email,
          coalesce(
            nullif(btrim(profile.raw_user_meta_data ->> 'display_name'), ''),
            nullif(btrim(profile.raw_user_meta_data ->> 'name'), ''),
            nullif(btrim(auth_user.email), ''),
            nullif(btrim(profile.raw_user_meta_data ->> 'email'), ''),
            '-'
          ) as display_name,
          membership.created_at,
          membership.modified_at
        from private.roles as membership
        left join private.users as profile
          on profile.id = membership.user_id
        left join auth.users as auth_user
          on auth_user.id = membership.user_id
        where membership.team_id = $1
          and membership.role in ('owner', 'admin', 'member')
      )
      select
        m.user_id,
        m.team_id,
        m.role,
        m.email,
        m.display_name,
        m.created_at,
        m.modified_at,
        count(*) over() as total_count
      from members as m
      order by %s %s nulls last, m.user_id asc
      limit $2
      offset $3
    $sql$,
    v_order_by,
    v_order_dir
  )
  using v_team_id, v_limit, v_offset;
end;
$_$;


