--
-- Name: svc_ai_tidas_suggestion_enqueue(uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_ai_tidas_suggestion_enqueue(p_requested_by uuid, p_data_type text, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_data_type text := lower(trim(coalesce(p_data_type, '')));
  v_payload jsonb;
  v_request_hash text;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to enqueue AI jobs'
    );
  end if;

  if p_requested_by is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AI_REQUESTED_BY_REQUIRED',
      'status', 400,
      'message', 'requestedBy is required'
    );
  end if;

  if v_data_type not in ('process', 'flow') then
    return jsonb_build_object(
      'ok', false,
      'code', 'AI_DATA_TYPE_INVALID',
      'status', 400,
      'message', 'dataType must be process or flow'
    );
  end if;

  if jsonb_typeof(p_data) is distinct from 'object'
    or (
      v_data_type = 'process'
      and jsonb_typeof(p_data->'processDataSet') is distinct from 'object'
    )
    or (
      v_data_type = 'flow'
      and jsonb_typeof(p_data->'flowDataSet') is distinct from 'object'
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'AI_DATA_INVALID',
      'status', 400,
      'message', 'data must contain the matching TIDAS dataset root object'
    );
  end if;

  v_payload := jsonb_build_object(
    'dataType', v_data_type,
    'data', p_data
  );

  if pg_catalog.octet_length(v_payload::text) > 16777216 then
    return jsonb_build_object(
      'ok', false,
      'code', 'AI_DATA_TOO_LARGE',
      'status', 413,
      'message', 'AI request exceeds the 16 MiB absolute contract limit'
    );
  end if;

  v_request_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(v_payload::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  return private.worker_enqueue_job(
    p_job_kind => 'ai.tidas_suggestion',
    p_payload_json => v_payload,
    p_payload_schema_version => 'ai.tidas_suggestion.request.v1',
    p_requested_by => p_requested_by,
    p_requester_type => 'user',
    p_idempotency_key => 'ai.tidas_suggestion:' || v_request_hash,
    p_request_hash => v_request_hash,
    p_visibility => 'user',
    p_max_attempts => 3,
    p_timeout_at => now() + interval '30 minutes'
  );
end;
$$;


ALTER FUNCTION api.svc_ai_tidas_suggestion_enqueue(p_requested_by uuid, p_data_type text, p_data jsonb) OWNER TO postgres;

--
-- Name: FUNCTION svc_ai_tidas_suggestion_enqueue(p_requested_by uuid, p_data_type text, p_data jsonb); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.svc_ai_tidas_suggestion_enqueue(p_requested_by uuid, p_data_type text, p_data jsonb) IS 'Service-only AI TIDAS suggestion enqueue facade with exact v1 payload validation and active-request idempotency.';


--
-- Name: svc_ai_tidas_suggestion_read(uuid, uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_ai_tidas_suggestion_read(p_requested_by uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_job private.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required to read AI jobs'
    );
  end if;

  if p_requested_by is null or p_job_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AI_JOB_NOT_FOUND',
      'status', 404,
      'message', 'AI job was not found'
    );
  end if;

  select * into v_job
  from private.worker_jobs
  where id = p_job_id
    and requested_by = p_requested_by
    and job_kind = 'ai.tidas_suggestion';

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AI_JOB_NOT_FOUND',
      'status', 404,
      'message', 'AI job was not found'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', private.worker_job_payload(v_job, false)
  );
end;
$$;


ALTER FUNCTION api.svc_ai_tidas_suggestion_read(p_requested_by uuid, p_job_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_ai_tidas_suggestion_read(p_requested_by uuid, p_job_id uuid); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.svc_ai_tidas_suggestion_read(p_requested_by uuid, p_job_id uuid) IS 'Service-only requester-scoped AI TIDAS suggestion projection; payload and internal diagnostics remain hidden.';


--
-- Name: svc_data_product_current_public_package(); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_data_product_current_public_package() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_publication private.lcia_result_publications%rowtype;
  v_package private.lcia_result_packages%rowtype;
begin
  select publication.*
  into v_publication
  from private.lcia_result_publications as publication
  where publication.publication_series_key = 'global'
    and publication.publication_channel = 'public'
    and publication.visibility_scope = 'public'
    and publication.is_current = true
    and publication.status = 'current'
  order by publication.published_at desc nulls last, publication.created_at desc,
    publication.id
  limit 1;

  if v_publication.id is null then
    return jsonb_build_object('ok', true, 'data', null);
  end if;

  select package.*
  into v_package
  from private.lcia_result_packages as package
  where package.id = v_publication.package_id
    and package.status = 'preview_ready';

  if v_package.id is null then
    return jsonb_build_object('ok', true, 'data', null);
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'publication', jsonb_strip_nulls(jsonb_build_object(
        'id', v_publication.id,
        'package_id', v_publication.package_id,
        'publication_series_key', v_publication.publication_series_key,
        'publication_channel', v_publication.publication_channel,
        'visibility_scope', v_publication.visibility_scope,
        'is_current', v_publication.is_current,
        'status', v_publication.status,
        'display_default_impact_category', v_publication.display_default_impact_category,
        'published_at', v_publication.published_at,
        'created_at', v_publication.created_at
      )),
      'package', jsonb_strip_nulls(jsonb_build_object(
        'id', v_package.id,
        'package_version', v_package.package_version,
        'eligible_input_count', v_package.eligible_input_count,
        'included_input_count', v_package.included_input_count,
        'input_manifest', v_package.input_manifest,
        'snapshot_id', v_package.snapshot_id,
        'result_id', v_package.result_id,
        'result_artifact_ref', v_package.result_artifact_ref,
        'query_artifact_ref', v_package.query_artifact_ref,
        'artifact_manifest', v_package.artifact_manifest,
        'available_impact_categories', v_package.available_impact_categories,
        'default_impact_category', v_package.default_impact_category,
        'status', v_package.status
      ))
    )
  );
end
$$;


ALTER FUNCTION api.svc_data_product_current_public_package() OWNER TO postgres;

--
-- Name: svc_data_product_publication_list(integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_data_product_publication_list(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_rows jsonb;
begin
  if v_actor is null then
    return jsonb_build_object('ok', false, 'code', 'AUTH_REQUIRED', 'status', 401);
  end if;

  if not exists (
    select 1
    from private.roles as role_row
    where role_row.user_id = v_actor
      and role_row.team_id = '00000000-0000-0000-0000-000000000000'::uuid
      and role_row.role = 'data_product_manager'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_PRODUCT_MANAGER_REQUIRED',
      'status', 403
    );
  end if;

  select coalesce(
    jsonb_agg(
      candidate.payload
      order by candidate.is_current desc, candidate.published_at desc nulls last,
        candidate.created_at desc, candidate.publication_id
    ),
    '[]'::jsonb
  )
  into v_rows
  from (
    select
      publication.id as publication_id,
      publication.is_current,
      publication.published_at,
      publication.created_at,
      jsonb_strip_nulls(jsonb_build_object(
        'publicationId', publication.id,
        'packageId', publication.package_id,
        'packageName', coalesce(
          worker.payload_json ->> 'name',
          worker.payload_json ->> 'packageName',
          worker.payload_json ->> 'package_name'
        ),
        'packageVersion', package.package_version,
        'status', publication.status,
        'isCurrent', publication.is_current,
        'publicationSeriesKey', publication.publication_series_key,
        'publicationChannel', publication.publication_channel,
        'visibilityScope', publication.visibility_scope,
        'displayDefaultImpactCategory', publication.display_default_impact_category,
        'publishedAt', publication.published_at,
        'unpublishedAt', publication.unpublished_at,
        'reason', publication.reason,
        'eligibleInputCount', package.eligible_input_count,
        'includedInputCount', package.included_input_count,
        'packageStatus', package.status
      )) as payload
    from private.lcia_result_publications as publication
    left join private.lcia_result_packages as package on package.id = publication.package_id
    left join private.worker_jobs as worker on worker.id = package.build_worker_job_id
    order by publication.is_current desc, publication.published_at desc nulls last,
      publication.created_at desc, publication.id
    limit v_limit
  ) as candidate;

  return jsonb_build_object('ok', true, 'data', v_rows);
end
$$;


ALTER FUNCTION api.svc_data_product_publication_list(p_limit integer) OWNER TO postgres;

--
-- Name: svc_data_product_worker_metadata(uuid[]); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_data_product_worker_metadata(p_worker_job_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[] := coalesce(p_worker_job_ids, '{}'::uuid[]);
  v_worker_rows jsonb;
  v_package_rows jsonb;
begin
  if cardinality(v_ids) > 200 then
    return jsonb_build_object(
      'ok', false,
      'code', 'WORKER_JOB_LIMIT_EXCEEDED',
      'status', 400
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object('id', worker.id, 'payload_json', worker.payload_json)
      order by array_position(v_ids, worker.id)
    ),
    '[]'::jsonb
  )
  into v_worker_rows
  from private.worker_jobs as worker
  where worker.id = any(v_ids)
    and worker.job_kind = 'lcia_result.package_build';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'build_worker_job_id', package.build_worker_job_id,
        'id', package.id,
        'package_version', package.package_version,
        'status', package.status,
        'eligible_input_count', package.eligible_input_count,
        'included_input_count', package.included_input_count
      )
      order by array_position(v_ids, package.build_worker_job_id)
    ),
    '[]'::jsonb
  )
  into v_package_rows
  from private.lcia_result_packages as package
  where package.build_worker_job_id = any(v_ids);

  return jsonb_build_object(
    'ok', true,
    'worker_rows', v_worker_rows,
    'package_rows', v_package_rows
  );
end
$$;


ALTER FUNCTION api.svc_data_product_worker_metadata(p_worker_job_ids uuid[]) OWNER TO postgres;

--
-- Name: svc_dataset_search_text_backfill_enqueue(text, uuid, text, integer); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_dataset_search_text_backfill_enqueue(p_entity_kind text, p_after_id uuid DEFAULT NULL::uuid, p_after_version text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_entity_kind text := lower(btrim(coalesce(p_entity_kind, '')));
  v_table name;
  v_queue_entity_kind text;
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_cursor_version character(9);
  v_result jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  select mapping.table_name, mapping.queue_entity_kind
  into v_table, v_queue_entity_kind
  from (values
    ('contact', 'contacts'::name, 'contact'),
    ('flowproperty', 'flowproperties'::name, 'flowproperty'),
    ('flow', 'flows'::name, 'flow'),
    ('lifecyclemodel', 'lifecyclemodels'::name, 'lifecyclemodel'),
    ('process', 'processes'::name, 'process'),
    ('source', 'sources'::name, 'source'),
    ('unitgroup', 'unitgroups'::name, 'unitgroup')
  ) as mapping(entity_kind, table_name, queue_entity_kind)
  where mapping.entity_kind = v_entity_kind;

  if v_table is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_ENTITY_KIND',
      'status', 400,
      'message', 'entity_kind must be one of contact, flowproperty, flow, lifecyclemodel, process, source, or unitgroup'
    );
  end if;

  if p_after_id is null and p_after_version is not null then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_CURSOR',
      'status', 400,
      'message', 'after_version requires after_id'
    );
  end if;

  v_cursor_version := nullif(btrim(coalesce(p_after_version, '')), '')::character(9);

  execute format($sql$
    with candidates as materialized (
      select row.id, row.version
      from public.%1$I as row
      where row.search_text is null
        and (
          $1::uuid is null
          or (row.id, row.version) > ($1::uuid, coalesce($2::character(9), ''::character(9)))
        )
      order by row.id, row.version
      limit $3
    ), enqueueable as materialized (
      select candidate.id, candidate.version
      from candidates as candidate
      where not exists (
        select 1
        from pgmq.q_dataset_extraction_jobs as queued
        where queued.message ->> 'schema' = 'public'
          and queued.message ->> 'table' = %1$L
          and queued.message ->> 'id' = candidate.id::text
          and queued.message ->> 'version' = candidate.version::text
          and queued.message ->> 'extraction_kind' = 'search_text'
      )
    ), sent as (
      select pgmq.send(
        'dataset_extraction_jobs',
        jsonb_build_object(
          'schema', 'public',
          'table', %1$L,
          'id', enqueueable.id,
          'version', enqueueable.version,
          'entity_kind', %2$L,
          'extraction_kind', 'search_text',
          'created_at', clock_timestamp()
        )
      ) as msg_id
      from enqueueable
    ), summary as (
      select
        (select count(*) from candidates) as scanned,
        (select count(*) from sent) as enqueued,
        (select count(*) from candidates) - (select count(*) from sent) as already_queued,
        (select id from candidates order by id desc, version desc limit 1) as next_after_id,
        (select version from candidates order by id desc, version desc limit 1) as next_after_version
    )
    select jsonb_build_object(
      'ok', true,
      'data', jsonb_build_object(
        'entity_kind', %2$L,
        'table', %1$L,
        'limit', $3,
        'scanned', summary.scanned,
        'enqueued', summary.enqueued,
        'already_queued', summary.already_queued,
        'next_after_id', summary.next_after_id,
        'next_after_version', summary.next_after_version
      )
    )
    from summary
  $sql$, v_table, v_queue_entity_kind)
  into v_result
  using p_after_id, v_cursor_version, v_limit;

  return v_result;
end
$_$;


ALTER FUNCTION api.svc_dataset_search_text_backfill_enqueue(p_entity_kind text, p_after_id uuid, p_after_version text, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION svc_dataset_search_text_backfill_enqueue(p_entity_kind text, p_after_id uuid, p_after_version text, p_limit integer); Type: COMMENT; Schema: api; Owner: postgres
--

COMMENT ON FUNCTION api.svc_dataset_search_text_backfill_enqueue(p_entity_kind text, p_after_id uuid, p_after_version text, p_limit integer) IS 'Service-role-only, bounded, cursor-based and queue-deduplicated search_text replay enqueue. It never writes projections or embeds data.';


--
-- Name: svc_identity_desired_state_read(text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_identity_desired_state_read(p_keycloak_sub text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_state private.identity_center_users%rowtype;
begin
  if nullif(pg_catalog.btrim(p_keycloak_sub), '') is null then
    raise exception using errcode = '22023', message = 'KEYCLOAK_SUB_REQUIRED';
  end if;
  select identity_state.* into v_state
  from private.identity_center_users as identity_state
  where identity_state.keycloak_sub = p_keycloak_sub;
  if not found then return null; end if;
  return pg_catalog.to_jsonb(v_state);
end
$$;


ALTER FUNCTION api.svc_identity_desired_state_read(p_keycloak_sub text) OWNER TO postgres;

--
-- Name: svc_identity_desired_state_upsert(text, text, text, text, jsonb); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_identity_desired_state_upsert(p_keycloak_sub text, p_status text DEFAULT NULL::text, p_role_code text DEFAULT NULL::text, p_role_operation text DEFAULT 'preserve'::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation text := lower(coalesce(nullif(pg_catalog.btrim(p_role_operation), ''), 'preserve'));
  v_state private.identity_center_users%rowtype;
begin
  if nullif(pg_catalog.btrim(p_keycloak_sub), '') is null then
    raise exception using errcode = '22023', message = 'KEYCLOAK_SUB_REQUIRED';
  end if;
  if p_status is not null and p_status not in ('active', 'disabled', 'revoked', 'deleted') then
    raise exception using errcode = '22023', message = 'INVALID_IDENTITY_STATUS';
  end if;
  if v_operation not in ('preserve', 'set', 'revoke') then
    raise exception using errcode = '22023', message = 'INVALID_ROLE_OPERATION';
  end if;
  if v_operation = 'set' and nullif(pg_catalog.btrim(p_role_code), '') is null then
    raise exception using errcode = '22023', message = 'ROLE_CODE_REQUIRED';
  end if;

  insert into private.identity_center_users as current_state (
    keycloak_sub, status, desired_role, metadata, created_at, modified_at
  ) values (
    p_keycloak_sub,
    coalesce(p_status, 'active'),
    case when v_operation = 'set' then p_role_code else null end,
    coalesce(p_metadata, '{}'::jsonb),
    pg_catalog.now(),
    pg_catalog.now()
  )
  on conflict (keycloak_sub) do update set
    status = coalesce(p_status, current_state.status),
    desired_role = case v_operation
      when 'preserve' then current_state.desired_role
      when 'set' then p_role_code
      when 'revoke' then case
        when p_role_code is null or current_state.desired_role = p_role_code then null
        else current_state.desired_role
      end
    end,
    metadata = coalesce(p_metadata, current_state.metadata),
    modified_at = pg_catalog.now()
  returning * into v_state;

  return pg_catalog.to_jsonb(v_state);
end
$$;


ALTER FUNCTION api.svc_identity_desired_state_upsert(p_keycloak_sub text, p_status text, p_role_code text, p_role_operation text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: svc_identity_event_claim(text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_identity_event_claim(p_event_id text, p_event_type text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_inserted integer;
begin
  if nullif(pg_catalog.btrim(p_event_id), '') is null then
    raise exception using errcode = '22023', message = 'IDENTITY_EVENT_ID_REQUIRED';
  end if;
  insert into private.identity_center_processed_events (event_id, event_type, processed_at)
  values (
    p_event_id,
    coalesce(nullif(pg_catalog.btrim(p_event_type), ''), 'unknown'),
    pg_catalog.now()
  )
  on conflict (event_id) do nothing;
  get diagnostics v_inserted = row_count;
  return v_inserted = 1;
end
$$;


ALTER FUNCTION api.svc_identity_event_claim(p_event_id text, p_event_type text) OWNER TO postgres;

--
-- Name: svc_identity_event_release(text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_identity_event_release(p_event_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted integer;
begin
  if nullif(pg_catalog.btrim(p_event_id), '') is null then
    raise exception using errcode = '22023', message = 'IDENTITY_EVENT_ID_REQUIRED';
  end if;
  delete from private.identity_center_processed_events where event_id = p_event_id;
  get diagnostics v_deleted = row_count;
  return v_deleted = 1;
end
$$;


ALTER FUNCTION api.svc_identity_event_release(p_event_id text) OWNER TO postgres;

--
-- Name: svc_identity_login_bind(text, uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_identity_login_bind(p_keycloak_sub text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_state private.identity_center_users%rowtype;
begin
  if nullif(pg_catalog.btrim(p_keycloak_sub), '') is null or p_user_id is null then
    raise exception using errcode = '22023', message = 'IDENTITY_BINDING_REQUIRED';
  end if;
  begin
    insert into private.identity_center_users as current_state (
      keycloak_sub, user_id, status, metadata, created_at, modified_at
    ) values (
      p_keycloak_sub, p_user_id, 'active', '{}'::jsonb, pg_catalog.now(), pg_catalog.now()
    )
    on conflict (keycloak_sub) do update set
      user_id = excluded.user_id,
      status = 'active',
      modified_at = pg_catalog.now()
    where current_state.user_id is null or current_state.user_id = excluded.user_id
    returning * into v_state;
  exception when unique_violation then
    raise exception using errcode = '23505', message = 'IDENTITY_USER_ALREADY_BOUND';
  end;
  if v_state.keycloak_sub is null then
    raise exception using errcode = '23505', message = 'IDENTITY_SUBJECT_ALREADY_BOUND';
  end if;
  return pg_catalog.to_jsonb(v_state);
end
$$;


ALTER FUNCTION api.svc_identity_login_bind(p_keycloak_sub text, p_user_id uuid) OWNER TO postgres;

--
-- Name: svc_identity_managed_role_materialize(text, uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_identity_managed_role_materialize(p_keycloak_sub text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_system_team_id constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_managed_roles constant text[] := array['admin', 'review-admin', 'review-member'];
  v_desired_role text;
  v_previous_role text;
  v_effective_role text;
  v_changed boolean := false;
  v_reason text;
begin
  if nullif(pg_catalog.btrim(p_keycloak_sub), '') is null or p_user_id is null then
    raise exception using errcode = '22023', message = 'IDENTITY_BINDING_REQUIRED';
  end if;
  select desired_role::text into v_desired_role
  from private.identity_center_users
  where keycloak_sub = p_keycloak_sub and user_id = p_user_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'IDENTITY_BINDING_MISMATCH';
  end if;

  select role::text into v_previous_role
  from private.roles
  where user_id = p_user_id and team_id = v_system_team_id
  for update;
  v_effective_role := v_previous_role;

  if v_desired_role = any(v_managed_roles) then
    if v_previous_role is null then
      insert into private.roles as existing_role (user_id, team_id, role, created_at, modified_at)
      values (p_user_id, v_system_team_id, v_desired_role, pg_catalog.now(), pg_catalog.now())
      on conflict (user_id, team_id) do update set
        role = excluded.role,
        modified_at = pg_catalog.now()
      where existing_role.role::text = any(v_managed_roles)
        and existing_role.role::text is distinct from excluded.role::text
      returning role::text into v_effective_role;
      if found then
        v_changed := true;
        v_reason := 'managed_role_materialized';
      else
        select role::text into v_effective_role from private.roles
        where user_id = p_user_id and team_id = v_system_team_id;
        v_reason := case when v_effective_role = v_desired_role
          then 'already_materialized' else 'non_managed_role_preserved' end;
      end if;
    elsif v_previous_role = any(v_managed_roles) and v_previous_role is distinct from v_desired_role then
      update private.roles set role = v_desired_role, modified_at = pg_catalog.now()
      where user_id = p_user_id and team_id = v_system_team_id
        and role::text = any(v_managed_roles)
      returning role::text into v_effective_role;
      v_changed := found;
      v_reason := case when v_changed then 'managed_role_updated' else 'managed_role_changed_concurrently' end;
    else
      v_reason := case when v_previous_role = v_desired_role
        then 'already_materialized' else 'non_managed_role_preserved' end;
    end if;
  elsif v_desired_role is null and v_previous_role = any(v_managed_roles) then
    update private.roles set role = 'member', modified_at = pg_catalog.now()
    where user_id = p_user_id and team_id = v_system_team_id
      and role::text = any(v_managed_roles)
    returning role::text into v_effective_role;
    v_changed := found;
    v_reason := 'managed_role_revoked';
  elsif v_desired_role is null then
    v_reason := case when v_previous_role is null
      then 'no_desired_or_current_role' else 'non_managed_role_preserved' end;
  else
    v_reason := 'unsupported_desired_role';
  end if;

  return pg_catalog.jsonb_build_object(
    'keycloak_sub', p_keycloak_sub,
    'user_id', p_user_id,
    'team_id', v_system_team_id,
    'desired_role', v_desired_role,
    'previous_role', v_previous_role,
    'effective_role', v_effective_role,
    'changed', v_changed,
    'reason', v_reason
  );
end
$$;


ALTER FUNCTION api.svc_identity_managed_role_materialize(p_keycloak_sub text, p_user_id uuid) OWNER TO postgres;

--
-- Name: svc_lca_cached_job_enqueue(text, uuid, text, jsonb, text, uuid, jsonb, text, uuid, text, text); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_lca_cached_job_enqueue(p_scope text, p_snapshot_id uuid, p_request_key text, p_request_payload jsonb, p_job_kind text, p_job_id uuid, p_payload jsonb, p_payload_schema_version text, p_requested_by uuid, p_idempotency_key text, p_queue_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_scope text := nullif(btrim(p_scope), '');
  v_request_key text := nullif(btrim(p_request_key), '');
  v_cache private.lca_result_cache%rowtype;
  v_worker private.worker_jobs%rowtype;
  v_enqueue jsonb;
  v_worker_id uuid;
  v_resolved_job_id uuid;
  v_resolved_snapshot_id uuid;
  v_worker_status text;
begin
  if p_job_kind not in ('lca.solve_one', 'lca.solve_batch', 'lca.solve_all_unit', 'lca.contribution_path')
     or v_scope is null or p_snapshot_id is null or v_request_key is null
     or p_job_id is null or p_requested_by is null then
    return jsonb_build_object('ok', false, 'code', 'INVALID_LCA_JOB_REQUEST', 'status', 400);
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'lca.cache:' || v_scope || ':' || p_snapshot_id::text || ':' || v_request_key, 0
  ));

  select * into v_cache from private.lca_result_cache
  where scope = v_scope and snapshot_id = p_snapshot_id and request_key = v_request_key
  for update;

  if v_cache.id is not null then
    update private.lca_result_cache set
      hit_count = hit_count + 1, last_accessed_at = now(), updated_at = now()
    where id = v_cache.id returning * into v_cache;
    if v_cache.status = 'ready' and v_cache.result_id is not null then
      return jsonb_build_object(
        'ok', true, 'mode', 'cache_hit', 'cache_id', v_cache.id,
        'job_id', v_cache.job_id, 'worker_job_id', v_cache.worker_job_id,
        'result_id', v_cache.result_id
      );
    end if;
    if v_cache.worker_job_id is not null then
      select * into v_worker from private.worker_jobs where id = v_cache.worker_job_id;
      if v_worker.status in ('queued', 'running', 'waiting', 'stale') then
        return jsonb_build_object(
          'ok', true, 'mode', 'in_progress', 'cache_id', v_cache.id,
          'job_id', v_cache.job_id, 'worker_job_id', v_cache.worker_job_id
        );
      end if;
      if v_worker.status = 'failed' and v_worker.retryable is false then
        return jsonb_build_object(
          'ok', false,
          'code', 'WORKER_REQUEST_NON_RETRYABLE_FAILURE',
          'status', 409,
          'mode', 'failed_cache_hit',
          'message', 'The cached worker request failed and is not retryable',
          'reused', true,
          'reuseReason', 'terminal_non_retryable_failure',
          'cache_id', v_cache.id,
          'job_id', v_cache.job_id,
          'worker_job_id', v_worker.id,
          'error_code', coalesce(v_cache.error_code, v_worker.error_code),
          'error_message', coalesce(v_cache.error_message, v_worker.error_message),
          'retryable', false,
          'details', jsonb_build_object(
            'workerJob', private.worker_job_payload(v_worker, false)
          )
        );
      end if;
    end if;
  end if;

  v_enqueue := private.worker_enqueue_job(
    p_job_kind => p_job_kind,
    p_payload_json => coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('job_id', p_job_id),
    p_payload_schema_version => p_payload_schema_version,
    p_subject_type => 'lca_job',
    p_subject_id => p_job_id,
    p_subject_version => p_snapshot_id::text,
    p_requested_by => p_requested_by,
    p_requester_type => 'user',
    p_idempotency_key => p_idempotency_key,
    p_request_hash => v_request_key,
    p_concurrency_key => v_scope || ':' || p_snapshot_id::text || ':' || v_request_key,
    p_queue_key => p_queue_key,
    p_visibility => 'user'
  );
  if coalesce((v_enqueue ->> 'ok')::boolean, false) is false then return v_enqueue; end if;
  v_worker_id := (v_enqueue #>> '{data,id}')::uuid;
  v_resolved_job_id := coalesce(
    nullif(v_enqueue #>> '{data,payload,job_id}', '')::uuid,
    nullif(v_enqueue #>> '{data,subjectId}', '')::uuid,
    p_job_id
  );
  v_resolved_snapshot_id := coalesce(
    nullif(v_enqueue #>> '{data,subjectVersion}', '')::uuid,
    p_snapshot_id
  );
  v_worker_status := v_enqueue #>> '{data,status}';
  if v_resolved_snapshot_id <> p_snapshot_id then
    return jsonb_build_object('ok', false, 'code', 'LCA_JOB_IDEMPOTENCY_CONFLICT', 'status', 409);
  end if;

  insert into private.lca_result_cache as cache (
    scope, snapshot_id, request_key, request_payload, status,
    job_id, worker_job_id, hit_count, last_accessed_at, created_at, updated_at
  ) values (
    v_scope, p_snapshot_id, v_request_key, coalesce(p_request_payload, '{}'::jsonb),
    case when v_worker_status = 'blocked' then 'failed' else 'pending' end,
    v_resolved_job_id, v_worker_id, 1, now(), now(), now()
  ) on conflict (scope, snapshot_id, request_key) do update set
    request_payload = excluded.request_payload,
    status = excluded.status,
    job_id = excluded.job_id,
    worker_job_id = excluded.worker_job_id,
    result_id = null,
    error_code = null,
    error_message = null,
    hit_count = cache.hit_count + 1,
    last_accessed_at = now(),
    updated_at = now()
  returning * into v_cache;

  return jsonb_build_object(
    'ok', true,
    'mode', case
      when v_worker_status = 'blocked' then 'blocked'
      when coalesce((v_enqueue ->> 'reused')::boolean, false) then 'in_progress'
      else 'queued'
    end,
    'cache_id', v_cache.id,
    'job_id', v_cache.job_id, 'worker_job_id', v_cache.worker_job_id
  );
end;
$$;


ALTER FUNCTION api.svc_lca_cached_job_enqueue(p_scope text, p_snapshot_id uuid, p_request_key text, p_request_payload jsonb, p_job_kind text, p_job_id uuid, p_payload jsonb, p_payload_schema_version text, p_requested_by uuid, p_idempotency_key text, p_queue_key text) OWNER TO postgres;

--
-- Name: svc_lca_latest_all_unit_result(uuid, uuid); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.svc_lca_latest_all_unit_result(p_snapshot_id uuid, p_requested_by uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'ok', true,
    'data', (
      select jsonb_strip_nulls(jsonb_build_object(
        'id', result.id,
        'snapshotId', result.snapshot_id,
        'jobId', result.job_id,
        'workerJobId', result.worker_job_id,
        'resultId', result.result_id,
        'status', result.status,
        'queryArtifactUrl', result.query_artifact_url,
        'queryArtifactSha256', result.query_artifact_sha256,
        'queryArtifactByteSize', result.query_artifact_byte_size,
        'queryArtifactFormat', result.query_artifact_format,
        'computedAt', result.computed_at,
        'updatedAt', result.updated_at
      ))
      from private.lca_latest_all_unit_results as result
      join private.worker_jobs as worker on worker.id = result.worker_job_id
      where result.snapshot_id = p_snapshot_id
        and result.status = 'ready'
        and worker.job_kind = 'lca.solve_all_unit'
        and worker.requested_by = p_requested_by
      order by result.updated_at desc, result.id
      limit 1
    )
  )
$$;


