--
-- Name: unitgroups; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.unitgroups (
    id uuid NOT NULL,
    "json" jsonb,
    created_at timestamp with time zone DEFAULT now(),
    json_ordered json,
    user_id uuid DEFAULT auth.uid(),
    state_code integer DEFAULT 0,
    version character(9) NOT NULL,
    modified_at timestamp with time zone DEFAULT now(),
    team_id uuid,
    review_id uuid,
    rule_verification boolean,
    reviews jsonb,
    extracted_md text,
    embedding_ft_at timestamp with time zone,
    embedding_ft extensions.vector(1024),
    search_text text[],
    CONSTRAINT unitgroups_state_code_check CHECK ((state_code = ANY (ARRAY[0, 20, 100, 200])))
);


ALTER TABLE public.unitgroups OWNER TO postgres;

--
-- Name: COLUMN unitgroups.search_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.unitgroups.search_text IS 'Edge-owned multilingual lexical projection as nullable text[]. The empty scalar precursor was replaced without a heap rewrite; the later backfill writes the complete projection. Not a lexical search source until Database B.';


--
-- Name: unitgroups_embedding_ft_input(public.unitgroups); Type: FUNCTION; Schema: api; Owner: postgres
--

CREATE FUNCTION api.unitgroups_embedding_ft_input(proc public.unitgroups) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select proc.extracted_md;
$$;


ALTER FUNCTION api.unitgroups_embedding_ft_input(proc public.unitgroups) OWNER TO postgres;

