           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = index_catalog.indrelid
               and attribute.attname = 'dataset_kind'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = index_catalog.indrelid
               and attribute.attname = 'id'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = index_catalog.indrelid
               and attribute.attname = 'version'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = index_catalog.indrelid
               and attribute.attname = 'modified_at'
           )
         ]::smallint[]
         and array(
           select operator_class.opcname
           from pg_catalog.unnest(index_catalog.indclass::oid[])
             with ordinality as class_oid(oid, ordinality)
           join pg_catalog.pg_opclass as operator_class
             on operator_class.oid = class_oid.oid
           order by class_oid.ordinality
         ) = array[
           'int2_ops',
           'int2_ops',
           'text_ops',
           'uuid_ops',
           'text_ops',
           'timestamptz_ops'
         ]::name[]
     )
     or not exists (
       select 1
       from pg_catalog.pg_constraint as constraint_catalog
       where constraint_catalog.conrelid =
         'private.portal_sitemap_rows_v1'::regclass
         and constraint_catalog.confrelid =
           'private.portal_catalog_facet_rows_v1'::regclass
         and constraint_catalog.conname =
           'portal_sitemap_rows_source_v1_fk'
         and constraint_catalog.contype = 'f'
         and constraint_catalog.convalidated
         and constraint_catalog.confupdtype = 'r'
         and constraint_catalog.confdeltype = 'c'
         and constraint_catalog.conkey = array[
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = constraint_catalog.conrelid
               and attribute.attname = 'dataset_kind'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = constraint_catalog.conrelid
               and attribute.attname = 'id'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = constraint_catalog.conrelid
               and attribute.attname = 'version'
           )
         ]::smallint[]
         and constraint_catalog.confkey = array[
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = constraint_catalog.confrelid
               and attribute.attname = 'dataset_kind'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = constraint_catalog.confrelid
               and attribute.attname = 'id'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = constraint_catalog.confrelid
               and attribute.attname = 'version'
           )
         ]::smallint[]
     )
     or not exists (
       select 1
       from pg_catalog.pg_trigger as trigger
       where trigger.tgrelid =
         'private.portal_catalog_facet_rows_v1'::regclass
         and trigger.tgname = 'portal_sitemap_rows_sync_v1'
         and not trigger.tgisinternal
         and trigger.tgenabled = 'O'
         and trigger.tgtype = 21
         and pg_catalog.string_to_array(
           trigger.tgattr::text,
           ' '
         )::smallint[] = array[
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = trigger.tgrelid
               and attribute.attname = 'dataset_kind'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = trigger.tgrelid
               and attribute.attname = 'id'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = trigger.tgrelid
               and attribute.attname = 'version'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = trigger.tgrelid
               and attribute.attname = 'state_code'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = trigger.tgrelid
               and attribute.attname = 'modified_at'
           ),
           (
             select attribute.attnum
             from pg_catalog.pg_attribute as attribute
             where attribute.attrelid = trigger.tgrelid
               and attribute.attname = 'facet_contract_version'
           )
         ]::smallint[]
         and trigger.tgfoid =
           'private.sync_portal_sitemap_row_v1()'::regprocedure
     )
     or exists (
       select 1
       from pg_catalog.pg_trigger as trigger
       where trigger.tgrelid =
         'private.portal_catalog_facet_rows_v1'::regclass
         and trigger.tgname = 'portal_sitemap_latest_delete_v1'
         and not trigger.tgisinternal
     )
     or not exists (
       select 1
       from pg_catalog.pg_proc as routine
       where routine.oid =
         'private.sync_portal_sitemap_row_v1()'::regprocedure
         and routine.proowner = 'api_internal_executor'::regrole
         and routine.prosecdef
         and routine.provolatile = 'v'
         and routine.proparallel = 'u'
         and coalesce(routine.proconfig, '{}'::text[]) @> array[
           'search_path=""',
           'row_security=on'
         ]::text[]
         and pg_catalog.md5(routine.prosrc) =
           '9bc7007c0e8fef48c75d997ea8ef96d8'
     ) then
    raise exception using
      errcode = 'P0001',
      message = 'portal sitemap unavailable';
  end if;
end
$$;


ALTER FUNCTION private.assert_portal_sitemap_projection_v1() OWNER TO portal_public_executor;

--
-- Name: catalog_portal_candidate_rows_v1(text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) RETURNS TABLE(id uuid, version text, card jsonb, state_code integer, modified_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET plan_cache_mode TO 'force_custom_plan'
    SET row_security TO 'on'
    AS $_$
begin
  if p_kind = 'process' and p_query = '' then
    return query
    select distinct on (projection.id)
      projection.id,
      projection.version,
      projection.card,
      projection.state_code,
      projection.modified_at
    from private.portal_catalog_search_rows_v1 as projection
    where projection.dataset_kind = 'process'
    order by projection.id,
      projection.version desc,
      projection.modified_at desc,
      projection.state_code desc;
    return;
  end if;

  if p_kind = 'process' and p_exact_id is not null then
    return query
    with matched as materialized (
      select pattern.id,
        pattern.version,
        false as exact_id
      from private.catalog_portal_process_pattern_versions_v1(
        p_like_pattern
      ) as pattern
      union
      select projection.id,
        projection.version,
        true
      from private.portal_catalog_search_rows_v1 as projection
      where projection.dataset_kind = 'process'
        and projection.id = p_exact_id
    ), candidate_ids as materialized (
      select matched.id,
        pg_catalog.bool_or(matched.exact_id) as exact_id
      from matched
      group by matched.id
    ), matched_versions as materialized (
      select distinct matched.id,
        matched.version
      from matched
    ), latest_keys as materialized (
      select latest.id,
        latest.version,
        candidate_ids.exact_id
      from candidate_ids
      cross join lateral (
        select projection.id,
          projection.version
        from private.portal_catalog_search_rows_v1 as projection
        where projection.dataset_kind = 'process'
          and projection.id = candidate_ids.id
        order by projection.version desc,
          projection.modified_at desc,
          projection.state_code desc
        limit 1
      ) as latest
    ), eligible_keys as materialized (
      select latest.id,
        latest.version
      from latest_keys as latest
      left join matched_versions as latest_match
        on latest_match.id = latest.id
       and latest_match.version = latest.version
      where latest.exact_id
         or latest_match.id is not null
    )
    select projection.id,
      projection.version,
      projection.card,
      projection.state_code,
      projection.modified_at
    from eligible_keys
    join private.portal_catalog_search_rows_v1 as projection
      on projection.dataset_kind = 'process'
     and projection.id = eligible_keys.id
     and projection.version = eligible_keys.version;
    return;
  end if;

  if p_kind = 'process' then
    return query
    with matched as materialized (
      select pattern.id,
        pattern.version
      from private.catalog_portal_process_pattern_versions_v1(
        p_like_pattern
      ) as pattern
    ), candidate_ids as materialized (
      select distinct matched.id
      from matched
    ), matched_versions as materialized (
      select distinct matched.id,
        matched.version
      from matched
    ), latest_keys as materialized (
      select latest.id,
        latest.version
      from candidate_ids
      cross join lateral (
        select projection.id,
          projection.version
        from private.portal_catalog_search_rows_v1 as projection
        where projection.dataset_kind = 'process'
          and projection.id = candidate_ids.id
        order by projection.version desc,
          projection.modified_at desc,
          projection.state_code desc
        limit 1
      ) as latest
    ), eligible_keys as materialized (
      select latest.id,
        latest.version
      from latest_keys as latest
      join matched_versions as latest_match
        on latest_match.id = latest.id
       and latest_match.version = latest.version
    )
    select projection.id,
      projection.version,
      projection.card,
      projection.state_code,
      projection.modified_at
    from eligible_keys
    join private.portal_catalog_search_rows_v1 as projection
      on projection.dataset_kind = 'process'
     and projection.id = eligible_keys.id
     and projection.version = eligible_keys.version;
    return;
  end if;

  if p_kind = 'flow' and p_query = '' then
    return query
    select distinct on (projection.id)
      projection.id,
      projection.version,
      projection.card,
      projection.state_code,
      projection.modified_at
    from private.portal_catalog_search_rows_v1 as projection
    where projection.dataset_kind = 'flow'
    order by projection.id,
      projection.version desc,
      projection.modified_at desc,
      projection.state_code desc;
    return;
  end if;

  if p_kind = 'flow'
     and private.portal_catalog_summary_valid_cas_v1(p_query) then
    return query
    with candidate_ids as materialized (
      select distinct projection.id
      from private.portal_catalog_search_rows_v1 as projection
      where projection.dataset_kind = 'flow'
        and pg_catalog.jsonb_typeof(
          projection.card -> 'casNumber'
        ) = 'string'
        and projection.card ->> 'casNumber' ~
          '^[0-9]{2,7}-[0-9]{2}-[0-9]$'
        and pg_catalog.length(
          projection.card ->> 'casNumber'
        ) between 7 and 12
        and projection.card ->> 'casNumber' = p_query
    ), latest_rows as materialized (
      select latest.id,
        latest.version,
        latest.card,
        latest.state_code,
        latest.modified_at
      from candidate_ids
      cross join lateral (
        select projection.id,
          projection.version,
          projection.card,
          projection.state_code,
          projection.modified_at
        from private.portal_catalog_search_rows_v1 as projection
        where projection.dataset_kind = 'flow'
          and projection.id = candidate_ids.id
        order by projection.version desc,
          projection.modified_at desc,
          projection.state_code desc
        limit 1
      ) as latest
      where pg_catalog.jsonb_typeof(
          latest.card -> 'casNumber'
        ) = 'string'
        and latest.card ->> 'casNumber' = p_query
    )
    select latest.id,
      latest.version,
      latest.card,
      latest.state_code,
      latest.modified_at
    from latest_rows as latest;
    return;
  end if;

  if p_kind = 'flow' and p_exact_id is not null then
    return query
    with matched as materialized (
      select pattern.id,
        pattern.version,
        false as exact_id
      from private.catalog_portal_flow_pattern_versions_v1(
        p_like_pattern
      ) as pattern
      union
      select projection.id,
        projection.version,
        true
      from private.portal_catalog_search_rows_v1 as projection
      where projection.dataset_kind = 'flow'
        and projection.id = p_exact_id
    ), candidate_ids as materialized (
      select matched.id,
        pg_catalog.bool_or(matched.exact_id) as exact_id
      from matched
      group by matched.id
    ), matched_versions as materialized (
      select distinct matched.id,
        matched.version
      from matched
    ), latest_keys as materialized (
      select latest.id,
        latest.version,
        candidate_ids.exact_id
      from candidate_ids
      cross join lateral (
        select projection.id,
          projection.version
        from private.portal_catalog_search_rows_v1 as projection
        where projection.dataset_kind = 'flow'
          and projection.id = candidate_ids.id
        order by projection.version desc,
          projection.modified_at desc,
          projection.state_code desc
        limit 1
      ) as latest
    ), eligible_keys as materialized (
      select latest.id,
        latest.version
      from latest_keys as latest
      left join matched_versions as latest_match
        on latest_match.id = latest.id
       and latest_match.version = latest.version
      where latest.exact_id
         or latest_match.id is not null
    )
    select projection.id,
      projection.version,
      projection.card,
      projection.state_code,
      projection.modified_at
    from eligible_keys
    join private.portal_catalog_search_rows_v1 as projection
      on projection.dataset_kind = 'flow'
     and projection.id = eligible_keys.id
     and projection.version = eligible_keys.version;
    return;
  end if;

  if p_kind = 'flow' then
    return query
    with matched as materialized (
      select pattern.id,
        pattern.version
      from private.catalog_portal_flow_pattern_versions_v1(
        p_like_pattern
      ) as pattern
    ), candidate_ids as materialized (
      select distinct matched.id
      from matched
    ), matched_versions as materialized (
      select distinct matched.id,
        matched.version
      from matched
    ), latest_keys as materialized (
      select latest.id,
        latest.version
      from candidate_ids
      cross join lateral (
        select projection.id,
          projection.version
        from private.portal_catalog_search_rows_v1 as projection
        where projection.dataset_kind = 'flow'
          and projection.id = candidate_ids.id
        order by projection.version desc,
          projection.modified_at desc,
          projection.state_code desc
        limit 1
      ) as latest
    ), eligible_keys as materialized (
      select latest.id,
        latest.version
      from latest_keys as latest
      join matched_versions as latest_match
        on latest_match.id = latest.id
       and latest_match.version = latest.version
    )
    select projection.id,
      projection.version,
      projection.card,
      projection.state_code,
      projection.modified_at
    from eligible_keys
    join private.portal_catalog_search_rows_v1 as projection
      on projection.dataset_kind = 'flow'
     and projection.id = eligible_keys.id
     and projection.version = eligible_keys.version;
  end if;
end
$_$;


ALTER FUNCTION private.catalog_portal_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) OWNER TO portal_public_executor;

--
-- Name: FUNCTION catalog_portal_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text); Type: COMMENT; Schema: private; Owner: portal_public_executor
--

COMMENT ON FUNCTION private.catalog_portal_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) IS 'Seven static kind/query branches: valid Flow CAS uses length-isolated exact partial-index keys with latest-version recheck; all empty, UUID, and ordinary lexical paths retain their existing behavior.';


--
-- Name: catalog_portal_candidate_rows_v2(text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_candidate_rows_v2(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) RETURNS TABLE(id uuid, version text, card jsonb, state_code integer, modified_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET plan_cache_mode TO 'force_custom_plan'
    SET row_security TO 'on'
    AS $_$
begin
  if p_kind not in ('process','flow') or p_kind is null then
    raise exception using errcode = '22023', message = 'invalid portal request';
  end if;
  if p_query = '' then
    return query
    select p.id, p.version, p.card, p.state_code, p.modified_at
    from private.portal_catalog_search_rows_v1 as p
    where p.dataset_kind = p_kind and p.state_code in (100,200);
    return;
  end if;
  if p_kind = 'flow' and private.portal_catalog_summary_valid_cas_v1(p_query) then
    return query
    select p.id, p.version, p.card, p.state_code, p.modified_at
    from private.portal_catalog_search_rows_v1 as p
    where p.dataset_kind = 'flow' and p.state_code in (100,200)
      and pg_catalog.jsonb_typeof(p.card -> 'casNumber') = 'string'
      and p.card ->> 'casNumber' ~ '^[0-9]{2,7}-[0-9]{2}-[0-9]$'
      and pg_catalog.length(p.card ->> 'casNumber') between 7 and 12
      and p.card ->> 'casNumber' = p_query;
    return;
  end if;
  return query
  with pattern_matches as materialized (
    select pattern.id,pattern.version
    from private.catalog_portal_process_pattern_versions_v1(p_like_pattern) as pattern
    where p_kind='process'
    union all
    select pattern.id,pattern.version
    from private.catalog_portal_flow_pattern_versions_v1(p_like_pattern) as pattern
    where p_kind='flow'
  ), matched as materialized (
    select pattern.id, pattern.version
    from pattern_matches as pattern
    union
    select p.id, p.version
    from private.portal_catalog_search_rows_v1 as p
    where p.dataset_kind = p_kind and p.id = p_exact_id and p.state_code in (100,200)
  )
  select p.id, p.version, p.card, p.state_code, p.modified_at
  from matched
  join private.portal_catalog_search_rows_v1 as p
    on p.dataset_kind = p_kind and p.id = matched.id and p.version = matched.version
  where p.state_code in (100,200);
end;
$_$;


ALTER FUNCTION private.catalog_portal_candidate_rows_v2(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) OWNER TO portal_public_executor;

--
-- Name: catalog_portal_card_facts_v1(jsonb, jsonb, text); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_card_facts_v1(p_card jsonb, p_filters jsonb, p_query text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'accessLevel', p_card -> 'accessLevel',
    'nameKey', p_card #> '{names,0,value}',
    'nameExact', pg_catalog.to_jsonb(case when p_query = '' then false else
      exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          coalesce(p_card -> 'names', '[]'::jsonb)
        ) as name(item)
        where pg_catalog.lower(pg_catalog.btrim(name.item ->> 'value')) = p_query
      )
    end),
    'nameContains', pg_catalog.to_jsonb(case when p_query = '' then false else
      exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          coalesce(p_card -> 'names', '[]'::jsonb)
        ) as name(item)
        where pg_catalog.strpos(
          pg_catalog.lower(name.item ->> 'value'),
          p_query
        ) > 0
      )
    end),
    'classificationExact', pg_catalog.to_jsonb(
      case when p_query = '' then false else exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          coalesce(p_card -> 'classifications', '[]'::jsonb)
        ) as classification(item)
        where pg_catalog.lower(pg_catalog.btrim(
          classification.item ->> 'code'
        )) = p_query
      ) end
    ),
    'classificationContains', pg_catalog.to_jsonb(
      case when p_query = '' then false else exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          coalesce(p_card -> 'classifications', '[]'::jsonb)
        ) as classification(item)
        where pg_catalog.strpos(
          pg_catalog.lower(classification.item ->> 'code'),
          p_query
        ) > 0
      ) end
    ),
    'classificationFilterMatch', pg_catalog.to_jsonb(
      case when not (p_filters ? 'classification') then false else exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          coalesce(p_card -> 'classifications', '[]'::jsonb)
        ) as classification(item)
        where pg_catalog.lower(pg_catalog.btrim(
          classification.item ->> 'code'
        )) = p_filters ->> 'classification'
      ) end
    ),
    'geographyCode', p_card #> '{geography,code}',
    'referenceYear', p_card -> 'referenceYear',
    'processSubtype', p_card -> 'processSubtype',
    'source', p_card -> 'source',
    'casNumber', p_card -> 'casNumber'
  )
$$;


ALTER FUNCTION private.catalog_portal_card_facts_v1(p_card jsonb, p_filters jsonb, p_query text) OWNER TO portal_public_executor;

--
-- Name: catalog_portal_facet_candidate_rows_v1(text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_facet_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) RETURNS TABLE(dataset_kind text, id uuid, version text, card jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET plan_cache_mode TO 'force_custom_plan'
    SET row_security TO 'on'
    AS $$
begin
  if p_kind = 'process' then
    return query
    select 'process'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v1(
      'process', p_query, p_exact_id, p_like_pattern
    ) as candidate;
  elsif p_kind = 'flow' then
    return query
    select 'flow'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v1(
      'flow', p_query, p_exact_id, p_like_pattern
    ) as candidate;
  elsif p_kind = 'all' then
    return query
    select 'process'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v1(
      'process', p_query, p_exact_id, p_like_pattern
    ) as candidate;
    return query
    select 'flow'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v1(
      'flow', p_query, p_exact_id, p_like_pattern
    ) as candidate;
  end if;
end
$$;


ALTER FUNCTION private.catalog_portal_facet_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) OWNER TO portal_public_executor;

--
-- Name: FUNCTION catalog_portal_facet_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text); Type: COMMENT; Schema: private; Owner: portal_public_executor
--

COMMENT ON FUNCTION private.catalog_portal_facet_candidate_rows_v1(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) IS 'Exact Process/Flow/all latest-visible facet candidates over the synchronized public-safe projection.';


--
-- Name: catalog_portal_facet_candidate_rows_v2(text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_facet_candidate_rows_v2(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) RETURNS TABLE(dataset_kind text, id uuid, version text, card jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET plan_cache_mode TO 'force_custom_plan'
    SET row_security TO 'on'
    AS $$
begin
  if p_kind = 'process' then
    return query
    select 'process'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v2(
      'process', p_query, p_exact_id, p_like_pattern
    ) as candidate;
  elsif p_kind = 'flow' then
    return query
    select 'flow'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v2(
      'flow', p_query, p_exact_id, p_like_pattern
    ) as candidate;
  elsif p_kind = 'all' then
    return query
    select 'process'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v2(
      'process', p_query, p_exact_id, p_like_pattern
    ) as candidate;
    return query
    select 'flow'::text,
      candidate.id,
      candidate.version,
      candidate.card
    from private.catalog_portal_candidate_rows_v2(
      'flow', p_query, p_exact_id, p_like_pattern
    ) as candidate;
  end if;
end
$$;


ALTER FUNCTION private.catalog_portal_facet_candidate_rows_v2(p_kind text, p_query text, p_exact_id uuid, p_like_pattern text) OWNER TO portal_public_executor;

--
-- Name: catalog_portal_facets_empty_v1_impl(text, text); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_facets_empty_v1_impl(p_kind text, p_query_fingerprint text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET work_mem TO '32MB'
    SET plan_cache_mode TO 'force_custom_plan'
    SET row_security TO 'on'
    AS $$
  with latest as materialized (
    select distinct on (facet.dataset_kind, facet.id)
      facet.dataset_kind,
      facet.id,
      facet.version,
      facet.facet_access_level,
      facet.facet_geography,
      facet.facet_reference_year,
      facet.facet_process_subtype,
      facet.facet_source
    from private.portal_catalog_facet_rows_v1 as facet
    where facet.facet_contract_version = 1
      and (p_kind = 'all' or facet.dataset_kind = p_kind)
    order by facet.dataset_kind,
      facet.id,
      facet.version desc,
      facet.modified_at desc,
      facet.state_code desc
  ), facts as materialized (
    select latest.dataset_kind,
      latest.facet_access_level,
      latest.facet_geography,
      latest.facet_reference_year,
      case when latest.dataset_kind = 'process' then
        latest.facet_process_subtype
      else null::text end as facet_process_subtype,
      latest.facet_source
    from latest
  ), counts_raw as materialized (
    select case
        when grouping(facts.dataset_kind) = 0 then 'kind'
        when grouping(facts.facet_access_level) = 0 then 'accessLevel'
        when grouping(facts.facet_geography) = 0 then 'geography'
        when grouping(facts.facet_reference_year) = 0 then 'referenceYear'
        when grouping(facts.facet_process_subtype) = 0 then 'processSubtype'
        else 'source'
      end as group_id,
      case
        when grouping(facts.dataset_kind) = 0 then 1
        when grouping(facts.facet_access_level) = 0 then 2
        when grouping(facts.facet_geography) = 0 then 3
        when grouping(facts.facet_reference_year) = 0 then 4
        when grouping(facts.facet_process_subtype) = 0 then 5
        else 6
      end as group_order,
      case
        when grouping(facts.dataset_kind) = 0 then facts.dataset_kind
        when grouping(facts.facet_access_level) = 0 then
          facts.facet_access_level
        when grouping(facts.facet_geography) = 0 then facts.facet_geography
        when grouping(facts.facet_reference_year) = 0 then
          facts.facet_reference_year
        when grouping(facts.facet_process_subtype) = 0 then
          facts.facet_process_subtype
        else facts.facet_source
      end as value,
      pg_catalog.count(*) as value_count
    from facts
    group by grouping sets (
      (facts.dataset_kind),
      (facts.facet_access_level),
      (facts.facet_geography),
      (facts.facet_reference_year),
      (facts.facet_process_subtype),
      (facts.facet_source)
    )
  ), counts as materialized (
    select counts_raw.group_id,
      counts_raw.group_order,
      counts_raw.value,
      counts_raw.value as label,
      counts_raw.value_count
    from counts_raw
    where nullif(pg_catalog.btrim(counts_raw.value), '') is not null
      and pg_catalog.length(counts_raw.value) <= 128
      and pg_catalog.octet_length(counts_raw.value) <= 512
  ), ranked_counts as materialized (
    select counts.*,
      pg_catalog.row_number() over (
        partition by counts.group_id
        order by counts.value
      ) as value_rank
    from counts
  ), grouped as materialized (
    select ranked_counts.group_id,
      ranked_counts.group_order,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'value', ranked_counts.value,
        'label', pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'language', 'und', 'value', ranked_counts.label
          )
        ),
        'count', ranked_counts.value_count
      ) order by ranked_counts.value)
        filter (where ranked_counts.value_rank <= 100) as values_json,
      pg_catalog.bool_or(ranked_counts.value_rank > 100) as has_more
    from ranked_counts
    group by ranked_counts.group_id, ranked_counts.group_order
  ), groups as (
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', grouped.group_id,
      'label', pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'language', 'en',
          'value', case grouped.group_id
            when 'kind' then 'Object type'
            when 'accessLevel' then 'Access level'
            when 'geography' then 'Geography'
            when 'referenceYear' then 'Reference year'
            when 'processSubtype' then 'Process subtype'
            else 'Source'
          end
        ),
        pg_catalog.jsonb_build_object(
          'language', 'zh-CN',
          'value', case grouped.group_id
            when 'kind' then '对象类型'
            when 'accessLevel' then '访问级别'
            when 'geography' then '地区'
            when 'referenceYear' then '参考年'
            when 'processSubtype' then '过程类型'
            else '数据源'
          end
        )
      ),
      'values', grouped.values_json,
      'hasMore', grouped.has_more
    ) order by grouped.group_order), '[]'::jsonb) as value
    from grouped
  )
  select pg_catalog.jsonb_build_object(
    'schemaVersion', 'portal.public-facets.v1',
    'kind', p_kind,
    'queryFingerprint', p_query_fingerprint,
    'groups', groups.value
  )
  from groups
$$;


