--
-- Name: catalog_portal_projection_payload_v1(text, integer, jsonb); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_projection_payload_v1(p_kind text, p_state_code integer, p_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    AS $$
declare
  v_card jsonb;
begin
  v_card := private.portal_catalog_card_v1(
    p_kind,
    p_state_code,
    p_json
  );
  if pg_catalog.jsonb_typeof(v_card) <> 'object' then
    return null;
  end if;
  return pg_catalog.jsonb_build_object(
    'card', v_card,
    'document', coalesce(v_card ->> 'document', '')
  );
end
$$;


ALTER FUNCTION private.catalog_portal_projection_payload_v1(p_kind text, p_state_code integer, p_json jsonb) OWNER TO portal_public_executor;

--
-- Name: FUNCTION catalog_portal_projection_payload_v1(p_kind text, p_state_code integer, p_json jsonb); Type: COMMENT; Schema: private; Owner: portal_public_executor
--

COMMENT ON FUNCTION private.catalog_portal_projection_payload_v1(p_kind text, p_state_code integer, p_json jsonb) IS 'Pure Portal public-card/document projection used only by the private synchronized search relation.';


--
-- Name: catalog_portal_search_v1_impl(text, text, jsonb, text, text, uuid, text, integer, text); Type: FUNCTION; Schema: private; Owner: api_internal_executor
--

CREATE FUNCTION private.catalog_portal_search_v1_impl(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $_$
declare
  v_items jsonb;
  v_next_cursor_payload jsonb;
  v_exact_id uuid;
  v_like_pattern text;
begin
  if p_query ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_exact_id := p_query::uuid;
  end if;
  if p_query <> '' then
    v_like_pattern := '%' || pg_catalog.replace(
      pg_catalog.replace(
        pg_catalog.replace(
          p_query,
          pg_catalog.chr(92),
          pg_catalog.chr(92) || pg_catalog.chr(92)
        ),
        '%',
        pg_catalog.chr(92) || '%'
      ),
      '_',
      pg_catalog.chr(92) || '_'
    ) || '%';
  end if;
  -- Empty unfiltered browse pages do not require search facts for the whole
  -- catalog.  Order/latest/cursor reduction happens before at most limit+1
  -- cards are hydrated.
  if p_query = ''
     and p_filters = '{}'::jsonb
     and p_sort in ('relevance', 'modified_desc', 'name_asc') then
    with portal_prefilter as materialized (
      select p_kind as dataset_kind,
        candidate.*,
        case when p_sort = 'name_asc' then case
          when nullif(candidate.card #>> '{names,0,value}', '') is not null
            and pg_catalog.length(
              candidate.card #>> '{names,0,value}'
            ) <= 500
            and pg_catalog.octet_length(
              candidate.card #>> '{names,0,value}'
            ) <= 2000
            and candidate.card #>> '{names,0,value}' !~ '[[:cntrl:]]'
            then candidate.card #>> '{names,0,value}'
          else '~unnamed:' || candidate.id::text
        end end as name_key
      from private.catalog_portal_candidate_rows_v1(
        p_kind,
        p_query,
        v_exact_id,
        v_like_pattern
      ) as candidate
    ), portal_after_cursor as materialized (
      select portal_prefilter.*
      from portal_prefilter
      where p_cursor_rank is null
        or case p_sort
          when 'relevance' then
            0::numeric < p_cursor_rank::numeric
            or (
              0::numeric = p_cursor_rank::numeric
              and (
                portal_prefilter.id > p_cursor_id
                or (
                  portal_prefilter.id = p_cursor_id
                  and portal_prefilter.version < p_cursor_version
                )
              )
            )
          when 'modified_desc' then
            portal_prefilter.modified_at < p_cursor_rank::timestamptz
            or (
              portal_prefilter.modified_at = p_cursor_rank::timestamptz
              and (
                portal_prefilter.id > p_cursor_id
                or (
                  portal_prefilter.id = p_cursor_id
                  and portal_prefilter.version < p_cursor_version
                )
              )
            )
          else
            pg_catalog.lower(portal_prefilter.name_key)
              > pg_catalog.lower(p_cursor_rank)
            or (
              pg_catalog.lower(portal_prefilter.name_key)
                = pg_catalog.lower(p_cursor_rank)
              and (
                portal_prefilter.id > p_cursor_id
                or (
                  portal_prefilter.id = p_cursor_id
                  and portal_prefilter.version < p_cursor_version
                )
              )
            )
        end
    ), portal_ordered as materialized (
      select portal_after_cursor.*,
        pg_catalog.row_number() over (
          order by
            case when p_sort = 'modified_desc'
              then portal_after_cursor.modified_at end desc,
            case when p_sort = 'name_asc'
              then pg_catalog.lower(portal_after_cursor.name_key) end asc,
            portal_after_cursor.id asc,
            portal_after_cursor.version desc
        ) as page_rank
      from portal_after_cursor
      order by
        case when p_sort = 'modified_desc'
          then portal_after_cursor.modified_at end desc,
        case when p_sort = 'name_asc'
          then pg_catalog.lower(portal_after_cursor.name_key) end asc,
        portal_after_cursor.id asc,
        portal_after_cursor.version desc
      limit p_limit + 1
    ), portal_decorated as materialized (
      select portal_ordered.*
      from portal_ordered
    )
    select
      coalesce(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'key', pg_catalog.jsonb_build_object(
            'kind', p_kind,
            'id', portal_decorated.id::text,
            'version', portal_decorated.version
          ),
          'accessLevel', portal_decorated.card -> 'accessLevel',
          'capabilities', portal_decorated.card -> 'capabilities',
          'names', portal_decorated.card -> 'names',
          'summary', portal_decorated.card -> 'summary',
          'geography', portal_decorated.card -> 'geography',
          'referenceYear', portal_decorated.card -> 'referenceYear',
          'modifiedAt', pg_catalog.to_char(
            portal_decorated.modified_at at time zone 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
          ),
          'match', pg_catalog.jsonb_build_object(
            'kind', 'lexical',
            'score', 0::numeric,
            'reasonCodes', '[]'::jsonb
          )
        ) order by portal_decorated.page_rank
      ) filter (where portal_decorated.page_rank <= p_limit), '[]'::jsonb),
      case when max(portal_decorated.page_rank) > p_limit then
        (pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'v', 1,
          'fp', p_query_fingerprint,
          'rankKey', case p_sort
            when 'relevance' then '0'
            when 'modified_desc' then pg_catalog.to_char(
              portal_decorated.modified_at at time zone 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
            )
            else pg_catalog.lower(portal_decorated.name_key)
          end,
          'kind', p_kind,
          'id', portal_decorated.id::text,
          'version', portal_decorated.version
        ) order by portal_decorated.page_rank)
          filter (where portal_decorated.page_rank = p_limit)) -> 0
      else null end
    into v_items, v_next_cursor_payload
    from portal_decorated;

    return pg_catalog.jsonb_build_object(
      'items', v_items,
      'nextCursorPayload', v_next_cursor_payload
    );
  end if;

  -- Geography-only Flow browse can use the synchronized narrow facet child
  -- for latest/filter/order/limit, then hydrate only limit+1 stored cards.
  -- This preserves latest-version and cursor semantics without evaluating
  -- the wide card-facts helper over the full Flow card set.
  if p_kind = 'flow'
     and p_query = ''
     and p_sort = 'relevance'
     and p_filters ? 'geography'
     and (select count(*) from pg_catalog.jsonb_object_keys(p_filters)) = 1 then
    perform private.assert_portal_catalog_facet_contract_v1();

    with portal_latest_facts as materialized (
      select distinct on (facet.id)
        facet.id,
        facet.version,
        facet.state_code,
        facet.modified_at,
        facet.facet_geography
      from private.portal_catalog_facet_rows_v1 as facet
      where facet.dataset_kind = 'flow'
      order by facet.id,
        facet.version desc,
        facet.modified_at desc,
        facet.state_code desc
    ), portal_filtered_keys as materialized (
      select portal_latest_facts.*
      from portal_latest_facts
      where portal_latest_facts.facet_geography =
          p_filters ->> 'geography'
        and (
          p_cursor_rank is null
          or 0::numeric < p_cursor_rank::numeric
          or (
            0::numeric = p_cursor_rank::numeric
            and (
              portal_latest_facts.id > p_cursor_id
              or (
                portal_latest_facts.id = p_cursor_id
                and portal_latest_facts.version < p_cursor_version
              )
            )
          )
        )
    ), portal_ordered_keys as materialized (
      select portal_filtered_keys.*,
        pg_catalog.row_number() over (
          order by portal_filtered_keys.id,
            portal_filtered_keys.version desc
        ) as page_rank
      from portal_filtered_keys
      order by portal_filtered_keys.id,
        portal_filtered_keys.version desc
      limit p_limit + 1
    ), portal_hydrated as materialized (
      select portal_ordered_keys.*,
        projection.card
      from portal_ordered_keys
      join private.portal_catalog_search_rows_v1 as projection
        on projection.dataset_kind = 'flow'
       and projection.id = portal_ordered_keys.id
       and projection.version = portal_ordered_keys.version
    )
    select
      coalesce(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'key', pg_catalog.jsonb_build_object(
            'kind', p_kind,
            'id', portal_hydrated.id::text,
            'version', portal_hydrated.version
          ),
          'accessLevel', portal_hydrated.card -> 'accessLevel',
          'capabilities', portal_hydrated.card -> 'capabilities',
          'names', portal_hydrated.card -> 'names',
          'summary', portal_hydrated.card -> 'summary',
          'geography', portal_hydrated.card -> 'geography',
          'referenceYear', portal_hydrated.card -> 'referenceYear',
          'modifiedAt', pg_catalog.to_char(
            portal_hydrated.modified_at at time zone 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
          ),
          'match', pg_catalog.jsonb_build_object(
            'kind', 'lexical',
            'score', 0::numeric,
            'reasonCodes', '[]'::jsonb
          )
        ) order by portal_hydrated.page_rank
      ) filter (where portal_hydrated.page_rank <= p_limit), '[]'::jsonb),
      case when max(portal_hydrated.page_rank) > p_limit then
        (pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'v', 1,
          'fp', p_query_fingerprint,
          'rankKey', '0',
          'kind', p_kind,
          'id', portal_hydrated.id::text,
          'version', portal_hydrated.version
        ) order by portal_hydrated.page_rank)
          filter (where portal_hydrated.page_rank = p_limit)) -> 0
      else null end
    into v_items, v_next_cursor_payload
    from portal_hydrated;

    return pg_catalog.jsonb_build_object(
      'items', v_items,
      'nextCursorPayload', v_next_cursor_payload
    );
  end if;

  with portal_prefilter as materialized (
    select p_kind as dataset_kind,
      candidate.*
    from private.catalog_portal_candidate_rows_v1(
      p_kind,
      p_query,
      v_exact_id,
      v_like_pattern
    ) as candidate
  ), portal_facts as materialized (
    select portal_prefilter.*,
      private.catalog_portal_card_facts_v1(
        portal_prefilter.card,
        p_filters,
        p_query
      ) as facts
    from portal_prefilter
  ), portal_scored as materialized (
    select portal_facts.*,
      case
        when nullif(portal_facts.facts ->> 'nameKey', '') is not null
          and pg_catalog.length(portal_facts.facts ->> 'nameKey') <= 500
          and pg_catalog.octet_length(portal_facts.facts ->> 'nameKey') <= 2000
          and portal_facts.facts ->> 'nameKey' !~ '[[:cntrl:]]'
          then portal_facts.facts ->> 'nameKey'
        else '~unnamed:' || portal_facts.id::text
      end as name_key,
      case
        when p_query = '' then 0::numeric
        when pg_catalog.lower(portal_facts.id::text) = p_query then 1::numeric
        when pg_catalog.lower(coalesce(portal_facts.facts ->> 'casNumber', '')) = p_query
          then 0.98::numeric
        when (portal_facts.facts ->> 'nameExact')::boolean then 0.95::numeric
        when (portal_facts.facts ->> 'classificationExact')::boolean
          then 0.92::numeric
        when p_query <> '' then 0.70::numeric
        else 0::numeric
      end as score,
      case
        when pg_catalog.lower(portal_facts.id::text) = p_query
          then pg_catalog.jsonb_build_array('exact_id')
        when pg_catalog.lower(coalesce(portal_facts.facts ->> 'casNumber', '')) = p_query
          then pg_catalog.jsonb_build_array('cas')
        when (portal_facts.facts ->> 'nameExact')::boolean
          or (portal_facts.facts ->> 'nameContains')::boolean
          then pg_catalog.jsonb_build_array('name')
        when (portal_facts.facts ->> 'classificationExact')::boolean
          or (portal_facts.facts ->> 'classificationContains')::boolean
          then pg_catalog.jsonb_build_array('classification')
        when p_query <> '' then pg_catalog.jsonb_build_array('full_text')
        else '[]'::jsonb
      end as reason_codes
    from portal_facts
  ), portal_filtered as materialized (
    select portal_scored.*,
      case p_sort
        when 'relevance' then portal_scored.score::text
        when 'modified_desc' then pg_catalog.to_char(
          portal_scored.modified_at at time zone 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        )
        else pg_catalog.lower(portal_scored.name_key)
      end as rank_key
    from portal_scored
    where (p_query = '' or portal_scored.score > 0)
      and (
        not (p_filters ? 'accessLevel')
        or portal_scored.facts ->> 'accessLevel' = p_filters ->> 'accessLevel'
      )
      and (
        not (p_filters ? 'geography')
        or pg_catalog.lower(pg_catalog.btrim(coalesce(
          portal_scored.facts ->> 'geographyCode',
          ''
        ))) = p_filters ->> 'geography'
      )
      and (
        not (p_filters ? 'classification')
        or (portal_scored.facts ->> 'classificationFilterMatch')::boolean
      )
      and (
        not (p_filters ? 'referenceYearFrom')
        or (portal_scored.facts ->> 'referenceYear')::integer
          >= (p_filters ->> 'referenceYearFrom')::integer
      )
      and (
        not (p_filters ? 'referenceYearTo')
        or (portal_scored.facts ->> 'referenceYear')::integer
          <= (p_filters ->> 'referenceYearTo')::integer
      )
      and (
        not (p_filters ? 'processSubtype')
        or pg_catalog.lower(pg_catalog.btrim(coalesce(
          portal_scored.facts ->> 'processSubtype',
          ''
        ))) = p_filters ->> 'processSubtype'
      )
      and (
        not (p_filters ? 'source')
        or pg_catalog.lower(pg_catalog.btrim(coalesce(
          portal_scored.facts ->> 'source',
          ''
        ))) = p_filters ->> 'source'
      )
  ), portal_after_cursor as materialized (
    select portal_filtered.*
    from portal_filtered
    where p_cursor_rank is null
      or case p_sort
        when 'relevance' then
          portal_filtered.score < p_cursor_rank::numeric
          or (
            portal_filtered.score = p_cursor_rank::numeric
            and (
              portal_filtered.id > p_cursor_id
              or (
                portal_filtered.id = p_cursor_id
                and portal_filtered.version < p_cursor_version
              )
            )
          )
        when 'modified_desc' then
          portal_filtered.modified_at < p_cursor_rank::timestamptz
          or (
            portal_filtered.modified_at = p_cursor_rank::timestamptz
            and (
              portal_filtered.id > p_cursor_id
              or (
                portal_filtered.id = p_cursor_id
                and portal_filtered.version < p_cursor_version
              )
            )
          )
        else
          pg_catalog.lower(portal_filtered.name_key) > pg_catalog.lower(p_cursor_rank)
          or (
            pg_catalog.lower(portal_filtered.name_key) = pg_catalog.lower(p_cursor_rank)
            and (
              portal_filtered.id > p_cursor_id
              or (
                portal_filtered.id = p_cursor_id
                and portal_filtered.version < p_cursor_version
              )
            )
          )
      end
  ), portal_ordered as materialized (
    select portal_after_cursor.*,
      pg_catalog.row_number() over (
        order by
          case when p_sort = 'relevance' then portal_after_cursor.score end desc,
          case when p_sort = 'modified_desc' then portal_after_cursor.modified_at end desc,
          case when p_sort = 'name_asc'
            then pg_catalog.lower(portal_after_cursor.name_key) end asc,
          portal_after_cursor.id asc,
          portal_after_cursor.version desc
      ) as page_rank
    from portal_after_cursor
    order by
      case when p_sort = 'relevance' then portal_after_cursor.score end desc,
      case when p_sort = 'modified_desc' then portal_after_cursor.modified_at end desc,
      case when p_sort = 'name_asc'
        then pg_catalog.lower(portal_after_cursor.name_key) end asc,
      portal_after_cursor.id asc,
      portal_after_cursor.version desc
    limit p_limit + 1
  ), portal_hydrated as materialized (
    select portal_ordered.*
    from portal_ordered
  )
  select
    coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'key', pg_catalog.jsonb_build_object(
          'kind', p_kind,
          'id', portal_hydrated.id::text,
          'version', portal_hydrated.version
        ),
        'accessLevel', portal_hydrated.card -> 'accessLevel',
        'capabilities', portal_hydrated.card -> 'capabilities',
        'names', portal_hydrated.card -> 'names',
        'summary', portal_hydrated.card -> 'summary',
        'geography', portal_hydrated.card -> 'geography',
        'referenceYear', portal_hydrated.card -> 'referenceYear',
        'modifiedAt', pg_catalog.to_char(
          portal_hydrated.modified_at at time zone 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        ),
        'match', pg_catalog.jsonb_build_object(
          'kind', case when portal_hydrated.reason_codes
            ?| array['exact_id', 'cas', 'classification']
            then 'identifier' else 'lexical' end,
          'score', portal_hydrated.score,
          'reasonCodes', portal_hydrated.reason_codes
        )
      ) order by portal_hydrated.page_rank
    ) filter (where portal_hydrated.page_rank <= p_limit), '[]'::jsonb),
    case when max(portal_hydrated.page_rank) > p_limit then
      (pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'v', 1,
        'fp', p_query_fingerprint,
        'rankKey', portal_hydrated.rank_key,
        'kind', p_kind,
        'id', portal_hydrated.id::text,
        'version', portal_hydrated.version
      ) order by portal_hydrated.page_rank)
        filter (where portal_hydrated.page_rank = p_limit)) -> 0
    else null end
  into v_items, v_next_cursor_payload
  from portal_hydrated;

  return pg_catalog.jsonb_build_object(
    'items', v_items,
    'nextCursorPayload', v_next_cursor_payload
  );
end
$_$;


ALTER FUNCTION private.catalog_portal_search_v1_impl(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) OWNER TO api_internal_executor;

--
-- Name: FUNCTION catalog_portal_search_v1_impl(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text); Type: COMMENT; Schema: private; Owner: api_internal_executor
--

COMMENT ON FUNCTION private.catalog_portal_search_v1_impl(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) IS 'Candidate-first Portal catalog kernel: fixed public-document PGroonga candidates, exact latest-visible recheck, then public-card hydration.';


--
-- Name: catalog_portal_search_v2_impl(text, text, jsonb, text, text, uuid, text, integer, text); Type: FUNCTION; Schema: private; Owner: api_internal_executor
--

CREATE FUNCTION private.catalog_portal_search_v2_impl(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $_$
declare
  v_items jsonb;
  v_next_cursor_payload jsonb;
  v_exact_id uuid;
  v_like_pattern text;
begin
  if p_query ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_exact_id := p_query::uuid;
  end if;
  if p_query <> '' then
    v_like_pattern := '%' || pg_catalog.replace(
      pg_catalog.replace(
        pg_catalog.replace(
          p_query,
          pg_catalog.chr(92),
          pg_catalog.chr(92) || pg_catalog.chr(92)
        ),
        '%',
        pg_catalog.chr(92) || '%'
      ),
      '_',
      pg_catalog.chr(92) || '_'
    ) || '%';
  end if;
  -- Empty unfiltered browse pages do not require search facts for the whole
  -- catalog.  Order/cursor reduction happens before at most limit+1
  -- cards are hydrated.
  if p_query = ''
     and p_filters = '{}'::jsonb
     and p_sort in ('relevance', 'modified_desc', 'name_asc') then
    with portal_prefilter as materialized (
      select p_kind as dataset_kind,
        candidate.*,
        case when p_sort = 'name_asc' then case
          when nullif(candidate.card #>> '{names,0,value}', '') is not null
            and pg_catalog.length(
              candidate.card #>> '{names,0,value}'
            ) <= 500
            and pg_catalog.octet_length(
              candidate.card #>> '{names,0,value}'
            ) <= 2000
            and candidate.card #>> '{names,0,value}' !~ '[[:cntrl:]]'
            then candidate.card #>> '{names,0,value}'
          else '~unnamed:' || candidate.id::text
        end end as name_key
      from private.catalog_portal_candidate_rows_v2(
        p_kind,
        p_query,
        v_exact_id,
        v_like_pattern
      ) as candidate
    ), portal_after_cursor as materialized (
      select portal_prefilter.*
      from portal_prefilter
      where p_cursor_rank is null
        or case p_sort
          when 'relevance' then
            0::numeric < p_cursor_rank::numeric
            or (
              0::numeric = p_cursor_rank::numeric
              and (
                portal_prefilter.id > p_cursor_id
                or (
                  portal_prefilter.id = p_cursor_id
                  and portal_prefilter.version < p_cursor_version
                )
              )
            )
          when 'modified_desc' then
            portal_prefilter.modified_at < p_cursor_rank::timestamptz
            or (
              portal_prefilter.modified_at = p_cursor_rank::timestamptz
              and (
                portal_prefilter.id > p_cursor_id
                or (
                  portal_prefilter.id = p_cursor_id
                  and portal_prefilter.version < p_cursor_version
                )
              )
            )
          else
            pg_catalog.lower(portal_prefilter.name_key)
              > pg_catalog.lower(p_cursor_rank)
            or (
              pg_catalog.lower(portal_prefilter.name_key)
                = pg_catalog.lower(p_cursor_rank)
              and (
                portal_prefilter.id > p_cursor_id
                or (
                  portal_prefilter.id = p_cursor_id
                  and portal_prefilter.version < p_cursor_version
                )
              )
            )
        end
    ), portal_ordered as materialized (
      select portal_after_cursor.*,
        pg_catalog.row_number() over (
          order by
            case when p_sort = 'modified_desc'
              then portal_after_cursor.modified_at end desc,
            case when p_sort = 'name_asc'
              then pg_catalog.lower(portal_after_cursor.name_key) end asc,
            portal_after_cursor.id asc,
            portal_after_cursor.version desc
        ) as page_rank
      from portal_after_cursor
      order by
        case when p_sort = 'modified_desc'
          then portal_after_cursor.modified_at end desc,
        case when p_sort = 'name_asc'
          then pg_catalog.lower(portal_after_cursor.name_key) end asc,
        portal_after_cursor.id asc,
        portal_after_cursor.version desc
      limit p_limit + 1
    ), portal_decorated as materialized (
      select portal_ordered.*
      from portal_ordered
    )
    select
      coalesce(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'key', pg_catalog.jsonb_build_object(
            'kind', p_kind,
            'id', portal_decorated.id::text,
            'version', portal_decorated.version
          ),
          'accessLevel', portal_decorated.card -> 'accessLevel',
          'capabilities', portal_decorated.card -> 'capabilities',
          'names', portal_decorated.card -> 'names',
          'summary', portal_decorated.card -> 'summary',
          'geography', portal_decorated.card -> 'geography',
          'referenceYear', portal_decorated.card -> 'referenceYear',
          'modifiedAt', pg_catalog.to_char(
            portal_decorated.modified_at at time zone 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
          ),
          'match', pg_catalog.jsonb_build_object(
            'kind', 'lexical',
            'score', 0::numeric,
            'reasonCodes', '[]'::jsonb
          )
        ) order by portal_decorated.page_rank
      ) filter (where portal_decorated.page_rank <= p_limit), '[]'::jsonb),
      case when max(portal_decorated.page_rank) > p_limit then
        (pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'v', 1,
          'fp', p_query_fingerprint,
          'rankKey', case p_sort
            when 'relevance' then '0'
            when 'modified_desc' then pg_catalog.to_char(
              portal_decorated.modified_at at time zone 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
            )
            else pg_catalog.lower(portal_decorated.name_key)
          end,
          'kind', p_kind,
          'id', portal_decorated.id::text,
          'version', portal_decorated.version
        ) order by portal_decorated.page_rank)
          filter (where portal_decorated.page_rank = p_limit)) -> 0
      else null end
    into v_items, v_next_cursor_payload
    from portal_decorated;

    return pg_catalog.jsonb_build_object(
      'items', v_items,
      'nextCursorPayload', v_next_cursor_payload
    );
  end if;


  with portal_prefilter as materialized (
    select p_kind as dataset_kind,
      candidate.*
    from private.catalog_portal_candidate_rows_v2(
      p_kind,
      p_query,
      v_exact_id,
      v_like_pattern
    ) as candidate
  ), portal_facts as materialized (
    select portal_prefilter.*,
      private.catalog_portal_card_facts_v1(
        portal_prefilter.card,
        p_filters,
        p_query
      ) as facts
    from portal_prefilter
  ), portal_scored as materialized (
    select portal_facts.*,
      case
        when nullif(portal_facts.facts ->> 'nameKey', '') is not null
          and pg_catalog.length(portal_facts.facts ->> 'nameKey') <= 500
          and pg_catalog.octet_length(portal_facts.facts ->> 'nameKey') <= 2000
          and portal_facts.facts ->> 'nameKey' !~ '[[:cntrl:]]'
          then portal_facts.facts ->> 'nameKey'
        else '~unnamed:' || portal_facts.id::text
      end as name_key,
      case
        when p_query = '' then 0::numeric
        when pg_catalog.lower(portal_facts.id::text) = p_query then 1::numeric
        when pg_catalog.lower(coalesce(portal_facts.facts ->> 'casNumber', '')) = p_query
          then 0.98::numeric
        when (portal_facts.facts ->> 'nameExact')::boolean then 0.95::numeric
        when (portal_facts.facts ->> 'classificationExact')::boolean
          then 0.92::numeric
        when p_query <> '' then 0.70::numeric
        else 0::numeric
      end as score,
      case
        when pg_catalog.lower(portal_facts.id::text) = p_query
          then pg_catalog.jsonb_build_array('exact_id')
        when pg_catalog.lower(coalesce(portal_facts.facts ->> 'casNumber', '')) = p_query
          then pg_catalog.jsonb_build_array('cas')
        when (portal_facts.facts ->> 'nameExact')::boolean
          or (portal_facts.facts ->> 'nameContains')::boolean
          then pg_catalog.jsonb_build_array('name')
        when (portal_facts.facts ->> 'classificationExact')::boolean
          or (portal_facts.facts ->> 'classificationContains')::boolean
          then pg_catalog.jsonb_build_array('classification')
        when p_query <> '' then pg_catalog.jsonb_build_array('full_text')
        else '[]'::jsonb
      end as reason_codes
    from portal_facts
  ), portal_filtered as materialized (
    select portal_scored.*,
      case p_sort
        when 'relevance' then portal_scored.score::text
        when 'modified_desc' then pg_catalog.to_char(
          portal_scored.modified_at at time zone 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        )
        else pg_catalog.lower(portal_scored.name_key)
      end as rank_key
    from portal_scored
    where (p_query = '' or portal_scored.score > 0)
      and (
        not (p_filters ? 'accessLevel')
        or portal_scored.facts ->> 'accessLevel' = p_filters ->> 'accessLevel'
      )
      and (
        not (p_filters ? 'geography')
        or pg_catalog.lower(pg_catalog.btrim(coalesce(
          portal_scored.facts ->> 'geographyCode',
          ''
        ))) = p_filters ->> 'geography'
      )
      and (
        not (p_filters ? 'classification')
        or (portal_scored.facts ->> 'classificationFilterMatch')::boolean
      )
      and (
        not (p_filters ? 'referenceYearFrom')
        or (portal_scored.facts ->> 'referenceYear')::integer
          >= (p_filters ->> 'referenceYearFrom')::integer
      )
      and (
        not (p_filters ? 'referenceYearTo')
        or (portal_scored.facts ->> 'referenceYear')::integer
          <= (p_filters ->> 'referenceYearTo')::integer
      )
      and (
        not (p_filters ? 'processSubtype')
        or pg_catalog.lower(pg_catalog.btrim(coalesce(
          portal_scored.facts ->> 'processSubtype',
          ''
        ))) = p_filters ->> 'processSubtype'
      )
      and (
        not (p_filters ? 'source')
        or pg_catalog.lower(pg_catalog.btrim(coalesce(
          portal_scored.facts ->> 'source',
          ''
        ))) = p_filters ->> 'source'
      )
  ), portal_after_cursor as materialized (
    select portal_filtered.*
    from portal_filtered
    where p_cursor_rank is null
      or case p_sort
        when 'relevance' then
          portal_filtered.score < p_cursor_rank::numeric
          or (
            portal_filtered.score = p_cursor_rank::numeric
            and (
              portal_filtered.id > p_cursor_id
              or (
                portal_filtered.id = p_cursor_id
                and portal_filtered.version < p_cursor_version
              )
            )
          )
        when 'modified_desc' then
          portal_filtered.modified_at < p_cursor_rank::timestamptz
          or (
            portal_filtered.modified_at = p_cursor_rank::timestamptz
            and (
              portal_filtered.id > p_cursor_id
              or (
                portal_filtered.id = p_cursor_id
                and portal_filtered.version < p_cursor_version
              )
            )
          )
        else
          pg_catalog.lower(portal_filtered.name_key) > pg_catalog.lower(p_cursor_rank)
          or (
            pg_catalog.lower(portal_filtered.name_key) = pg_catalog.lower(p_cursor_rank)
            and (
              portal_filtered.id > p_cursor_id
              or (
                portal_filtered.id = p_cursor_id
                and portal_filtered.version < p_cursor_version
              )
            )
          )
      end
  ), portal_ordered as materialized (
    select portal_after_cursor.*,
      pg_catalog.row_number() over (
        order by
          case when p_sort = 'relevance' then portal_after_cursor.score end desc,
          case when p_sort = 'modified_desc' then portal_after_cursor.modified_at end desc,
          case when p_sort = 'name_asc'
            then pg_catalog.lower(portal_after_cursor.name_key) end asc,
          portal_after_cursor.id asc,
          portal_after_cursor.version desc
      ) as page_rank
    from portal_after_cursor
    order by
      case when p_sort = 'relevance' then portal_after_cursor.score end desc,
      case when p_sort = 'modified_desc' then portal_after_cursor.modified_at end desc,
      case when p_sort = 'name_asc'
        then pg_catalog.lower(portal_after_cursor.name_key) end asc,
      portal_after_cursor.id asc,
      portal_after_cursor.version desc
    limit p_limit + 1
  ), portal_hydrated as materialized (
    select portal_ordered.*
    from portal_ordered
  )
  select
    coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'key', pg_catalog.jsonb_build_object(
          'kind', p_kind,
          'id', portal_hydrated.id::text,
          'version', portal_hydrated.version
        ),
        'accessLevel', portal_hydrated.card -> 'accessLevel',
        'capabilities', portal_hydrated.card -> 'capabilities',
        'names', portal_hydrated.card -> 'names',
        'summary', portal_hydrated.card -> 'summary',
        'geography', portal_hydrated.card -> 'geography',
        'referenceYear', portal_hydrated.card -> 'referenceYear',
        'modifiedAt', pg_catalog.to_char(
          portal_hydrated.modified_at at time zone 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        ),
        'match', pg_catalog.jsonb_build_object(
          'kind', case when portal_hydrated.reason_codes
            ?| array['exact_id', 'cas', 'classification']
            then 'identifier' else 'lexical' end,
          'score', portal_hydrated.score,
          'reasonCodes', portal_hydrated.reason_codes
        )
      ) order by portal_hydrated.page_rank
    ) filter (where portal_hydrated.page_rank <= p_limit), '[]'::jsonb),
    case when max(portal_hydrated.page_rank) > p_limit then
      (pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'v', 1,
        'fp', p_query_fingerprint,
        'rankKey', portal_hydrated.rank_key,
        'kind', p_kind,
        'id', portal_hydrated.id::text,
        'version', portal_hydrated.version
      ) order by portal_hydrated.page_rank)
        filter (where portal_hydrated.page_rank = p_limit)) -> 0
    else null end
  into v_items, v_next_cursor_payload
  from portal_hydrated;

  return pg_catalog.jsonb_build_object(
    'items', v_items,
    'nextCursorPayload', v_next_cursor_payload
  );
end
$_$;


ALTER FUNCTION private.catalog_portal_search_v2_impl(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) OWNER TO api_internal_executor;

--
-- Name: catalog_portal_single_character_search_v1_impl(text, text, text, uuid, text, integer, text); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.catalog_portal_single_character_search_v1_impl(p_kind text, p_query text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL RESTRICTED
    SET search_path TO ''
    SET statement_timeout TO '8s'
    SET work_mem TO '32MB'
    SET plan_cache_mode TO 'force_custom_plan'
    SET jit TO 'off'
    SET row_security TO 'on'
    AS $$
declare
  v_items jsonb;
  v_next_cursor_payload jsonb;
begin
  perform private.assert_portal_catalog_character_contract_v1();

  if p_kind not in ('process', 'flow')
     or pg_catalog.char_length(p_query) <> 1
     or p_limit not between 1 and 50 then
    raise exception 'invalid Portal character Search'
      using errcode = '22023';
  end if;

  with latest as materialized (
    select distinct on (character_row.id)
      character_row.id,
      character_row.version,
      character_row.state_code,
      character_row.modified_at,
      character_row.document_characters,
      character_row.name_characters,
      character_row.name_exact_characters,
      character_row.classification_characters,
      character_row.classification_exact_characters
    from private.portal_catalog_character_rows_v1 as character_row
    where character_row.dataset_kind = p_kind
    order by character_row.id,
      character_row.version desc,
      character_row.modified_at desc,
      character_row.state_code desc
  ), scored as materialized (
    select latest.*,
      case
        when pg_catalog.strpos(
          latest.name_exact_characters, p_query
        ) > 0 then 0.95::numeric
        when pg_catalog.strpos(
          latest.classification_exact_characters, p_query
        ) > 0 then 0.92::numeric
        else 0.70::numeric
      end as score,
      case
        when pg_catalog.strpos(latest.name_characters, p_query) > 0
          then pg_catalog.jsonb_build_array('name')
        when pg_catalog.strpos(
          latest.classification_characters, p_query
        ) > 0 then pg_catalog.jsonb_build_array('classification')
        else pg_catalog.jsonb_build_array('full_text')
      end as reason_codes
    from latest
    where pg_catalog.strpos(latest.document_characters, p_query) > 0
  ), after_cursor as materialized (
    select scored.*
    from scored
    where p_cursor_rank is null
      or scored.score < p_cursor_rank::numeric
      or (
        scored.score = p_cursor_rank::numeric
        and (
          scored.id > p_cursor_id
          or (
            scored.id = p_cursor_id
            and scored.version < p_cursor_version
          )
        )
      )
  ), ordered as materialized (
    select after_cursor.*,
      pg_catalog.row_number() over (
        order by after_cursor.score desc,
          after_cursor.id asc,
          after_cursor.version desc
      ) as page_rank
    from after_cursor
    order by after_cursor.score desc,
      after_cursor.id asc,
      after_cursor.version desc
    limit p_limit + 1
  ), hydrated as materialized (
    select ordered.*,
      projection.card
    from ordered
    join private.portal_catalog_search_rows_v1 as projection
      on projection.dataset_kind = p_kind
     and projection.id = ordered.id
     and projection.version = ordered.version
  )
  select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'key', pg_catalog.jsonb_build_object(
            'kind', p_kind,
            'id', hydrated.id::text,
            'version', hydrated.version
          ),
          'accessLevel', hydrated.card -> 'accessLevel',
          'capabilities', hydrated.card -> 'capabilities',
          'names', hydrated.card -> 'names',
          'summary', hydrated.card -> 'summary',
          'geography', hydrated.card -> 'geography',
          'referenceYear', hydrated.card -> 'referenceYear',
          'modifiedAt', pg_catalog.to_char(
            hydrated.modified_at at time zone 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
          ),
          'match', pg_catalog.jsonb_build_object(
            'kind', 'lexical',
            'score', hydrated.score,
            'reasonCodes', hydrated.reason_codes
          )
        )
        order by hydrated.page_rank
      ) filter (where hydrated.page_rank <= p_limit),
      '[]'::jsonb
    ),
    case
      when pg_catalog.max(hydrated.page_rank) > p_limit then
        (
          pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'v', 1,
              'fp', p_query_fingerprint,
              'rankKey', hydrated.score::text,
              'kind', p_kind,
              'id', hydrated.id::text,
              'version', hydrated.version
            )
            order by hydrated.page_rank
          ) filter (where hydrated.page_rank = p_limit)
        ) -> 0
      else null
    end
  into v_items, v_next_cursor_payload
  from hydrated;

  return pg_catalog.jsonb_build_object(
    'items', v_items,
    'nextCursorPayload', v_next_cursor_payload
  );
end
$$;


ALTER FUNCTION private.catalog_portal_single_character_search_v1_impl(p_kind text, p_query text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) OWNER TO portal_public_executor;

--
-- Name: FUNCTION catalog_portal_single_character_search_v1_impl(p_kind text, p_query text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text); Type: COMMENT; Schema: private; Owner: portal_public_executor
--

COMMENT ON FUNCTION private.catalog_portal_single_character_search_v1_impl(p_kind text, p_query text, p_cursor_rank text, p_cursor_id uuid, p_cursor_version text, p_limit integer, p_query_fingerprint text) IS 'Bounded one-code-point unfiltered relevance Search over the synchronized narrow character projection.';


--
-- Name: cmd_dataset_alias_batch_guarded(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_dataset_alias_batch_guarded(p_batch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_schema_version constant text := 'dataset-alias-batch.v1';
  v_command constant text := 'cmd_dataset_alias_batch_guarded';
  v_plan_sha256 text;
  v_operation_id text;
  v_batch_id text;
  v_dimension text;
  v_factor text;
  v_target_visibility text;
  v_target_flowproperty_id uuid;
  v_target_flowproperty_version text;
  v_target_flowproperty_expected_modified_at timestamptz;
  v_target_flowproperty_expected_json_ordered jsonb;
  v_target_unitgroup_id uuid;
  v_target_unitgroup_version text;
  v_target_unitgroup_expected_modified_at timestamptz;
  v_target_unitgroup_expected_json_ordered jsonb;
  v_source_unitgroup_id uuid;
  v_source_unitgroup_version text;
  v_source_unitgroup_expected_modified_at timestamptz;
  v_source_unitgroup_expected_json_ordered jsonb;
  v_target_actual_modified_at timestamptz;
  v_target_actual_json_ordered jsonb;
  v_target_found boolean := false;
  v_source_found boolean := false;
  v_source_flowproperty_id uuid;
  v_source_flowproperty_version text;
  v_source_flowproperty_expected_json_ordered jsonb;
  v_source_flowproperty_name text;
  v_target_flowproperty_name text;
  v_source_unitgroup_name text;
  v_target_unitgroup_name text;
  v_expected_reference jsonb;
  v_units jsonb;
  v_unit jsonb;
  v_unit_count integer;
  v_action_count integer;
  v_flowproperty_count integer;
  v_flow_count integer;
  v_process_count integer;
  v_exchange_count integer;
  v_live_flow_closure_count integer;
  v_live_process_closure_count integer;
  v_live_exchange_closure_count integer;
  v_closure_exact boolean;
  v_forbidden_closure_exists boolean;
  v_request_sha256 text;
  v_action jsonb;
  v_action_id text;
  v_action_table text;
  v_action_uuid uuid;
  v_action_version text;
  v_expected_state_code integer;
  v_expected_modified_at timestamptz;
  v_expected_json_ordered jsonb;
  v_desired_json_ordered jsonb;
  v_expected_root text;
  v_expected_uuid_path text[];
  v_mutation jsonb;
  v_mutation_kind text;
  v_mutation_index integer;
  v_mutation_internal_id text;
  v_mutation_exchange jsonb;
  v_before_reference jsonb;
  v_after_reference jsonb;
  v_before_exchange jsonb;
  v_after_exchange jsonb;
  v_normalized_desired jsonb;
  v_before_mean_text text;
  v_after_mean_text text;
  v_before_resulting_text text;
  v_after_resulting_text text;
  v_exchange_path text[];
  v_actual_state_code integer;
  v_actual_modified_at timestamptz;
  v_actual_json_ordered jsonb;
  v_current_row jsonb;
  v_locked_actions jsonb := '[]'::jsonb;
  v_fresh_count integer := 0;
  v_replay_count integer := 0;
  v_existing_audit_count integer := 0;
  v_prior_audit_id bigint;
  v_summary_audit_id bigint;
  v_audit_id bigint;
  v_audit_rows jsonb := '[]'::jsonb;
  v_before_sha256 text;
  v_after_sha256 text;
  v_target_flowproperty_sha256 text;
  v_target_unitgroup_sha256 text;
  v_source_unitgroup_sha256 text;
  v_committed_modified_at timestamptz;
  v_committed_json_ordered jsonb;
  v_committed_version text;
  v_mismatches text[];
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_batch is not null and pg_column_size(p_batch) > 134217728 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_REQUEST_TOO_LARGE',
      'status', 413,
      'message', 'Alias batch request exceeds the 128 MiB database limit'
    );
  end if;

  if jsonb_typeof(p_batch) is distinct from 'object'
    or not (p_batch ?& array[
      'schema_version',
      'plan_sha256',
      'operation_id',
      'batch_id',
      'dimension',
      'factor',
      'target_visibility',
      'target',
      'actions'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_batch) as request_key(key)
      where request_key.key <> all (array[
        'schema_version',
        'plan_sha256',
        'operation_id',
        'batch_id',
        'dimension',
        'factor',
        'target_visibility',
        'target',
        'actions'
      ])
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_REQUEST',
      'status', 400,
      'message', 'Batch request must match dataset-alias-batch.v1 exactly'
    );
  end if;

  if jsonb_typeof(p_batch->'schema_version') is distinct from 'string'
    or p_batch->>'schema_version' <> v_schema_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_REQUEST',
      'status', 400,
      'message', 'Unsupported alias batch schema version'
    );
  end if;

  v_plan_sha256 := p_batch->>'plan_sha256';
  v_operation_id := nullif(btrim(p_batch->>'operation_id'), '');
  v_batch_id := nullif(btrim(p_batch->>'batch_id'), '');
  v_dimension := p_batch->>'dimension';
  v_factor := p_batch->>'factor';
  v_target_visibility := p_batch->>'target_visibility';

  if jsonb_typeof(p_batch->'plan_sha256') is distinct from 'string'
    or v_plan_sha256 is null
    or v_plan_sha256 !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_batch->'operation_id') is distinct from 'string'
    or v_operation_id is null
    or octet_length(v_operation_id) > 512
    or jsonb_typeof(p_batch->'batch_id') is distinct from 'string'
    or v_batch_id is null
    or octet_length(v_batch_id) > 512 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_AUDIT_CORRELATION_REQUIRED',
      'status', 400,
      'message', 'plan_sha256, operation_id, and batch_id are required'
    );
  end if;

  if jsonb_typeof(p_batch->'dimension') is distinct from 'string'
    or v_dimension not in ('time', 'length_time') then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_DIMENSION',
      'status', 400,
      'message', 'dimension must be time or length_time'
    );
  end if;

  if jsonb_typeof(p_batch->'factor') is distinct from 'string'
    or (v_dimension = 'time' and v_factor <> '0.00011415525114155251')
    or (v_dimension = 'length_time' and v_factor <> '1000') then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_FACTOR',
      'status', 400,
      'message', 'factor does not match the frozen dimension conversion'
    );
  end if;

  if jsonb_typeof(p_batch->'target_visibility') is distinct from 'string'
    or v_target_visibility <> 'owner_draft' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_TARGET_VISIBILITY',
      'status', 400,
      'message', 'target_visibility must be owner_draft'
    );
  end if;

  if jsonb_typeof(p_batch->'target') is distinct from 'object'
    or not ((p_batch->'target') ?& array[
      'flowproperty',
      'unitgroup',
      'source_unitgroup'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_batch->'target') as target_key(key)
      where target_key.key <> all (array[
        'flowproperty',
        'unitgroup',
        'source_unitgroup'
      ])
    )
    or jsonb_typeof(p_batch#>'{target,flowproperty}') is distinct from 'object'
    or not ((p_batch#>'{target,flowproperty}') ?& array[
      'id',
      'version',
      'expected_modified_at',
      'expected_json_ordered'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_batch#>'{target,flowproperty}') as fp_key(key)
      where fp_key.key <> all (array[
        'id',
        'version',
        'expected_modified_at',
        'expected_json_ordered'
      ])
    )
    or jsonb_typeof(p_batch#>'{target,unitgroup}') is distinct from 'object'
    or not ((p_batch#>'{target,unitgroup}') ?& array[
      'id',
      'version',
      'expected_modified_at',
      'expected_json_ordered'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_batch#>'{target,unitgroup}') as ug_key(key)
      where ug_key.key <> all (array[
        'id',
        'version',
        'expected_modified_at',
        'expected_json_ordered'
      ])
    )
    or jsonb_typeof(p_batch#>'{target,flowproperty,id}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,flowproperty,version}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,flowproperty,expected_modified_at}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,flowproperty,expected_json_ordered}') is distinct from 'object'
    or pg_column_size(p_batch#>'{target,flowproperty,expected_json_ordered}') > 16777216
    or jsonb_typeof(p_batch#>'{target,unitgroup,id}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,unitgroup,version}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,unitgroup,expected_modified_at}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,unitgroup,expected_json_ordered}') is distinct from 'object'
    or pg_column_size(p_batch#>'{target,unitgroup,expected_json_ordered}') > 16777216
    or jsonb_typeof(p_batch#>'{target,source_unitgroup}') is distinct from 'object'
    or not ((p_batch#>'{target,source_unitgroup}') ?& array[
      'id',
      'version',
      'expected_modified_at',
      'expected_json_ordered'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_batch#>'{target,source_unitgroup}') as source_ug_key(key)
      where source_ug_key.key <> all (array[
        'id',
        'version',
        'expected_modified_at',
        'expected_json_ordered'
      ])
    )
    or jsonb_typeof(p_batch#>'{target,source_unitgroup,id}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,source_unitgroup,version}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,source_unitgroup,expected_modified_at}') is distinct from 'string'
    or jsonb_typeof(p_batch#>'{target,source_unitgroup,expected_json_ordered}') is distinct from 'object'
    or pg_column_size(p_batch#>'{target,source_unitgroup,expected_json_ordered}') > 16777216
    or (p_batch#>>'{target,flowproperty,id}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or (p_batch#>>'{target,unitgroup,id}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or (p_batch#>>'{target,source_unitgroup,id}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or (p_batch#>>'{target,flowproperty,version}') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or (p_batch#>>'{target,unitgroup,version}') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or (p_batch#>>'{target,source_unitgroup,version}') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_TARGET',
      'status', 400,
      'message', 'Target support rows require exact UUID, version, modified_at, and payload snapshots'
    );
  end if;

  v_target_flowproperty_id := (p_batch#>>'{target,flowproperty,id}')::uuid;
  v_target_flowproperty_version := p_batch#>>'{target,flowproperty,version}';
  v_target_flowproperty_expected_json_ordered :=
    p_batch#>'{target,flowproperty,expected_json_ordered}';
  v_target_unitgroup_id := (p_batch#>>'{target,unitgroup,id}')::uuid;
  v_target_unitgroup_version := p_batch#>>'{target,unitgroup,version}';
  v_target_unitgroup_expected_json_ordered :=
    p_batch#>'{target,unitgroup,expected_json_ordered}';
  v_source_unitgroup_id := (p_batch#>>'{target,source_unitgroup,id}')::uuid;
  v_source_unitgroup_version := p_batch#>>'{target,source_unitgroup,version}';
  v_source_unitgroup_expected_json_ordered :=
    p_batch#>'{target,source_unitgroup,expected_json_ordered}';

  if v_source_unitgroup_id = v_target_unitgroup_id
    and v_source_unitgroup_version = v_target_unitgroup_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_TARGET',
      'status', 400,
      'message', 'Source and target unit group row keys must differ'
    );
  end if;

  if v_target_flowproperty_expected_json_ordered
      #>> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:UUID}'
      is distinct from v_target_flowproperty_id::text
    or v_target_flowproperty_expected_json_ordered
      #>> '{flowPropertyDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from v_target_flowproperty_version
    or v_target_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:UUID}'
      is distinct from v_target_unitgroup_id::text
    or v_target_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from v_target_unitgroup_version
    or v_source_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:UUID}'
      is distinct from v_source_unitgroup_id::text
    or v_source_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from v_source_unitgroup_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_TARGET',
      'status', 400,
      'message', 'Target support payload roots and embedded UUID/version identities must match their row keys'
    );
  end if;

  begin
    v_target_flowproperty_expected_modified_at :=
      (p_batch#>>'{target,flowproperty,expected_modified_at}')::timestamptz;
    v_target_unitgroup_expected_modified_at :=
      (p_batch#>>'{target,unitgroup,expected_modified_at}')::timestamptz;
    v_source_unitgroup_expected_modified_at :=
      (p_batch#>>'{target,source_unitgroup,expected_modified_at}')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_TARGET',
        'status', 400,
        'message', 'Target expected_modified_at values must be valid timestamps'
      );
  end;

  if jsonb_typeof(p_batch->'actions') is distinct from 'array' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_ACTIONS',
      'status', 400,
      'message', 'actions must be an array'
    );
  end if;

  v_action_count := jsonb_array_length(p_batch->'actions');

  for v_action in
    select action_item.value
    from jsonb_array_elements(p_batch->'actions') as action_item(value)
  loop
    if jsonb_typeof(v_action) is distinct from 'object'
      or not (v_action ?& array[
        'action_id',
        'action',
        'table',
        'id',
        'version',
        'expected_state_code',
        'expected_modified_at',
        'expected_json_ordered',
        'desired_json_ordered',
        'mutation'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_action) as action_key(key)
        where action_key.key <> all (array[
          'action_id',
          'action',
          'table',
          'id',
          'version',
          'expected_state_code',
          'expected_modified_at',
          'expected_json_ordered',
          'desired_json_ordered',
          'mutation'
        ])
      )
      or jsonb_typeof(v_action->'action_id') is distinct from 'string'
      or nullif(btrim(v_action->>'action_id'), '') is null
      or octet_length(v_action->>'action_id') > 512
      or jsonb_typeof(v_action->'action') is distinct from 'string'
      or v_action->>'action' <> 'update_json_ordered'
      or jsonb_typeof(v_action->'table') is distinct from 'string'
      or v_action->>'table' not in ('flowproperties', 'flows', 'processes')
      or jsonb_typeof(v_action->'id') is distinct from 'string'
      or (v_action->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or jsonb_typeof(v_action->'version') is distinct from 'string'
      or (v_action->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
      or jsonb_typeof(v_action->'expected_state_code') is distinct from 'number'
      or v_action->>'expected_state_code' <> '0'
      or jsonb_typeof(v_action->'expected_modified_at') is distinct from 'string'
      or jsonb_typeof(v_action->'expected_json_ordered') is distinct from 'object'
      or jsonb_typeof(v_action->'desired_json_ordered') is distinct from 'object'
      or jsonb_typeof(v_action->'mutation') is distinct from 'object'
      or pg_column_size(v_action->'expected_json_ordered') > 16777216
      or pg_column_size(v_action->'desired_json_ordered') > 16777216
      or pg_column_size(v_action->'mutation') > 1048576
      or v_action->'expected_json_ordered' = v_action->'desired_json_ordered' then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_ACTION',
        'status', 400,
        'message', 'Every action must be an exact allowed draft JSON update'
      );
    end if;

    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_expected_root := case v_action_table
      when 'flowproperties' then 'flowPropertyDataSet'
      when 'flows' then 'flowDataSet'
      when 'processes' then 'processDataSet'
    end;
    v_expected_uuid_path := case v_action_table
      when 'flowproperties' then array[
        'flowPropertyDataSet',
        'flowPropertiesInformation',
        'dataSetInformation',
        'common:UUID'
      ]
      when 'flows' then array[
        'flowDataSet',
        'flowInformation',
        'dataSetInformation',
        'common:UUID'
      ]
      when 'processes' then array[
        'processDataSet',
        'processInformation',
        'dataSetInformation',
        'common:UUID'
      ]
    end;

    if not ((v_action->'expected_json_ordered') ? v_expected_root)
      or not ((v_action->'desired_json_ordered') ? v_expected_root)
      or (v_action->'expected_json_ordered') #>> v_expected_uuid_path
        is distinct from v_action_uuid::text
      or (v_action->'desired_json_ordered') #>> v_expected_uuid_path
        is distinct from v_action_uuid::text
      or (v_action->'expected_json_ordered') #>> array[
        v_expected_root,
        'administrativeInformation',
        'publicationAndOwnership',
        'common:dataSetVersion'
      ] is distinct from v_action_version
      or (v_action->'desired_json_ordered') #>> array[
        v_expected_root,
        'administrativeInformation',
        'publicationAndOwnership',
        'common:dataSetVersion'
      ] is distinct from v_action_version then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_ACTION',
        'status', 400,
        'message', 'Action payload root and embedded UUID/version identity must match its table and row key',
        'details', jsonb_build_object('action_id', v_action->>'action_id')
      );
    end if;

    begin
      perform (v_action->>'expected_modified_at')::timestamptz;
    exception
      when invalid_datetime_format or datetime_field_overflow then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_ACTION',
          'status', 400,
          'message', 'expected_modified_at must be a valid timestamp',
          'details', jsonb_build_object('action_id', v_action->>'action_id')
        );
    end;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(p_batch->'actions') as duplicate_action(value)
    group by duplicate_action.value->>'action_id'
    having count(*) <> 1
  ) or exists (
    select 1
    from jsonb_array_elements(p_batch->'actions') as duplicate_row(value)
    group by
      duplicate_row.value->>'table',
      duplicate_row.value->>'id',
      duplicate_row.value->>'version'
    having count(*) <> 1
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DUPLICATE_ACTION',
      'status', 400,
      'message', 'action_id and table/id/version row keys must be unique'
    );
  end if;

  select
    count(*) filter (where action_item.value->>'table' = 'flowproperties'),
    count(*) filter (where action_item.value->>'table' = 'flows'),
    count(*) filter (where action_item.value->>'table' = 'processes')
  into v_flowproperty_count, v_flow_count, v_process_count
  from jsonb_array_elements(p_batch->'actions') as action_item(value);

  if (v_dimension = 'time' and (
      v_action_count <> 25
      or v_flowproperty_count <> 1
      or v_flow_count <> 10
      or v_process_count <> 14
    ))
    or (v_dimension = 'length_time' and (
      v_action_count <> 27
      or v_flowproperty_count <> 1
      or v_flow_count <> 13
      or v_process_count <> 13
    )) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_COUNTS',
      'status', 400,
      'message', 'Action counts do not match the frozen dimension scope',
      'details', jsonb_build_object(
        'action_count', v_action_count,
        'flowproperty_count', v_flowproperty_count,
        'flow_count', v_flow_count,
        'process_count', v_process_count
      )
    );
  end if;

  select
    (source_action.value->>'id')::uuid,
    source_action.value->>'version',
    source_action.value->'expected_json_ordered'
  into
    v_source_flowproperty_id,
    v_source_flowproperty_version,
    v_source_flowproperty_expected_json_ordered
  from jsonb_array_elements(p_batch->'actions') as source_action(value)
  where source_action.value->>'table' = 'flowproperties';

  select name_item.value->>'#text'
  into v_source_flowproperty_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_source_flowproperty_expected_json_ordered
        #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_source_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_source_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  select name_item.value->>'#text'
  into v_target_flowproperty_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_target_flowproperty_expected_json_ordered
        #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_target_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_target_flowproperty_expected_json_ordered
          #> '{flowPropertyDataSet,flowPropertiesInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  select name_item.value->>'#text'
  into v_source_unitgroup_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_source_unitgroup_expected_json_ordered
        #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_source_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_source_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  select name_item.value->>'#text'
  into v_target_unitgroup_name
  from jsonb_array_elements(
    case jsonb_typeof(
      v_target_unitgroup_expected_json_ordered
        #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
    )
      when 'array' then
        v_target_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      else jsonb_build_array(
        v_target_unitgroup_expected_json_ordered
          #> '{unitGroupDataSet,unitGroupInformation,dataSetInformation,common:name}'
      )
    end
  ) as name_item(value)
  where coalesce(name_item.value->>'@xml:lang', 'en') = 'en'
  limit 1;

  if nullif(v_source_flowproperty_name, '') is null
    or nullif(v_target_flowproperty_name, '') is null
    or nullif(v_source_unitgroup_name, '') is null
    or nullif(v_target_unitgroup_name, '') is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Source and target support snapshots require English names'
    );
  end if;

  v_expected_reference := jsonb_build_object(
    '@refObjectId', v_target_unitgroup_id,
    '@type', 'unit group data set',
    '@uri', '../unitgroups/' || v_target_unitgroup_id::text || '.json',
    '@version', v_target_unitgroup_version,
    'common:shortDescription', jsonb_build_object(
      '#text', v_target_unitgroup_name,
      '@xml:lang', 'en'
    )
  );

  if v_target_flowproperty_expected_json_ordered
      #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}'
      is distinct from v_expected_reference then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Target flow property must reference the exact frozen target unit group'
    );
  end if;

  if v_source_unitgroup_expected_json_ordered
      #>> '{unitGroupDataSet,unitGroupInformation,quantitativeReference,referenceToReferenceUnit}'
      is distinct from '1' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Source unit group must retain reference unit internal ID 1'
    );
  end if;

  v_units := v_source_unitgroup_expected_json_ordered
    #> '{unitGroupDataSet,units,unit}';
  v_units := case jsonb_typeof(v_units)
    when 'array' then v_units
    when 'object' then jsonb_build_array(v_units)
    else '[]'::jsonb
  end;

  if jsonb_array_length(v_units) <> 1
    or jsonb_typeof(v_units->0) is distinct from 'object'
    or v_units#>>'{0,@dataSetInternalID}' is distinct from '1'
    or v_units#>>'{0,meanValue}' is distinct from '1.0'
    or v_units#>>'{0,name}' is distinct from
      (case v_dimension when 'time' then 'hr' else 'kmy' end) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Source unit group does not match the frozen conversion unit definition'
    );
  end if;

  v_units := v_target_unitgroup_expected_json_ordered
    #> '{unitGroupDataSet,units,unit}';
  v_units := case jsonb_typeof(v_units)
    when 'array' then v_units
    when 'object' then jsonb_build_array(v_units)
    else '[]'::jsonb
  end;
  v_unit_count := 0;

  for v_unit in
    select unit_item.value
    from jsonb_array_elements(v_units) as unit_item(value)
    where unit_item.value->>'name' =
      (case v_dimension when 'time' then 'hr' else 'kmy' end)
  loop
    v_unit_count := v_unit_count + 1;
    if v_unit->>'@dataSetInternalID' is distinct from '4'
      or jsonb_typeof(v_unit->'meanValue') is distinct from 'string'
      or octet_length(v_unit->>'meanValue') > 128
      or v_unit->>'meanValue' !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
      then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
        'status', 400,
        'message', 'Target unit group conversion unit does not match the frozen factor'
      );
    end if;

    begin
      if (v_unit->>'meanValue')::numeric is distinct from v_factor::numeric then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
          'status', 400,
          'message', 'Target unit group conversion unit does not match the frozen factor'
        );
      end if;
    exception
      when numeric_value_out_of_range or invalid_text_representation then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
          'status', 400,
          'message', 'Target unit group conversion unit must be a finite numeric'
        );
    end;
  end loop;

  if v_unit_count <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_SUPPORT_SNAPSHOT',
      'status', 400,
      'message', 'Target unit group must contain exactly one frozen conversion unit'
    );
  end if;

  v_exchange_count := 0;

  for v_action in
    select action_item.value
    from jsonb_array_elements(p_batch->'actions') as action_item(value)
  loop
    v_action_id := v_action->>'action_id';
    v_action_table := v_action->>'table';
    v_expected_json_ordered := v_action->'expected_json_ordered';
    v_desired_json_ordered := v_action->'desired_json_ordered';
    v_mutation := v_action->'mutation';
    v_mutation_kind := v_mutation->>'kind';

    if v_action_table = 'flowproperties' then
      if not (v_mutation ?& array['kind'])
        or exists (
          select 1
          from jsonb_object_keys(v_mutation) as mutation_key(key)
          where mutation_key.key <> 'kind'
        )
        or jsonb_typeof(v_mutation->'kind') is distinct from 'string'
        or v_mutation_kind <> 'flowproperty_unitgroup_reference' then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Flow property action requires the exact unit-group-reference mutation contract',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      v_before_reference := v_expected_json_ordered #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}';
      v_after_reference := v_desired_json_ordered #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}';
      v_expected_reference := jsonb_build_object(
        '@refObjectId', v_source_unitgroup_id,
        '@type', 'unit group data set',
        '@uri', '../unitgroups/' || v_source_unitgroup_id::text || '.json',
        '@version', v_source_unitgroup_version,
        'common:shortDescription', jsonb_build_object(
          '#text', v_source_unitgroup_name,
          '@xml:lang', 'en'
        )
      );

      if jsonb_typeof(v_before_reference) is distinct from 'object'
        or jsonb_typeof(v_after_reference) is distinct from 'object'
        or v_before_reference is distinct from v_expected_reference
        or v_after_reference->>'@refObjectId' is distinct from v_target_unitgroup_id::text
        or v_after_reference->>'@version' is distinct from v_target_unitgroup_version
        or v_after_reference is distinct from
          v_target_flowproperty_expected_json_ordered
            #> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}'
        or v_expected_json_ordered #- '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}'
          is distinct from
          v_desired_json_ordered #- '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup}' then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
          'status', 400,
          'message', 'Flow property desired payload may replace only its exact source unit group reference with the target reference',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

    elsif v_action_table = 'flows' then
      if not (v_mutation ?& array[
          'kind',
          'flow_property_internal_id',
          'source_flowproperty_id',
          'source_flowproperty_version'
        ])
        or exists (
          select 1
          from jsonb_object_keys(v_mutation) as mutation_key(key)
          where mutation_key.key <> all (array[
            'kind',
            'flow_property_internal_id',
            'source_flowproperty_id',
            'source_flowproperty_version'
          ])
        )
        or jsonb_typeof(v_mutation->'kind') is distinct from 'string'
        or v_mutation_kind <> 'flow_flowproperty_reference'
        or jsonb_typeof(v_mutation->'flow_property_internal_id') is distinct from 'string'
        or v_mutation->>'flow_property_internal_id' <> '1'
        or jsonb_typeof(v_mutation->'source_flowproperty_id') is distinct from 'string'
        or (v_mutation->>'source_flowproperty_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(v_mutation->'source_flowproperty_version') is distinct from 'string'
        or v_mutation->>'source_flowproperty_id' is distinct from v_source_flowproperty_id::text
        or v_mutation->>'source_flowproperty_version' is distinct from v_source_flowproperty_version then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Flow action requires one exact indexed alias flow-property reference mutation',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      v_mutation_internal_id := v_mutation->>'flow_property_internal_id';
      v_exchange_path := array[
        'flowDataSet',
        'flowProperties',
        'flowProperty'
      ];
      v_before_exchange := v_expected_json_ordered #> v_exchange_path;
      v_after_exchange := v_desired_json_ordered #> v_exchange_path;
      v_before_reference := v_before_exchange->'referenceToFlowPropertyDataSet';
      v_after_reference := v_after_exchange->'referenceToFlowPropertyDataSet';
      v_expected_reference := jsonb_build_object(
        '@refObjectId', v_source_flowproperty_id,
        '@type', 'flow property data set',
        '@uri', '../flowproperties/' || v_source_flowproperty_id::text || '.json',
        '@version', v_source_flowproperty_version,
        'common:shortDescription', jsonb_build_object(
          '#text', v_source_flowproperty_name,
          '@xml:lang', 'en'
        )
      );

      if jsonb_typeof(v_before_exchange) is distinct from 'object'
        or jsonb_typeof(v_after_exchange) is distinct from 'object'
        or v_before_exchange->>'@dataSetInternalID' is distinct from v_mutation_internal_id
        or v_after_exchange->>'@dataSetInternalID' is distinct from v_mutation_internal_id
        or v_before_exchange->>'meanValue' is null
        or v_after_exchange->>'meanValue' is null
        or octet_length(v_before_exchange->>'meanValue') > 128
        or octet_length(v_after_exchange->>'meanValue') > 128
        or v_before_exchange->>'meanValue' !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$'
        or v_after_exchange->>'meanValue' !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$'
        or jsonb_typeof(v_before_reference) is distinct from 'object'
        or jsonb_typeof(v_after_reference) is distinct from 'object'
        or v_before_reference is distinct from v_expected_reference
        or v_after_reference is distinct from jsonb_build_object(
          '@refObjectId', v_target_flowproperty_id,
          '@type', 'flow property data set',
          '@uri', '../flowproperties/' || v_target_flowproperty_id::text || '.json',
          '@version', v_target_flowproperty_version,
          'common:shortDescription', jsonb_build_object(
            '#text', v_target_flowproperty_name,
            '@xml:lang', 'en'
          )
        )
        or jsonb_set(
          v_desired_json_ordered,
          array_append(v_exchange_path, 'referenceToFlowPropertyDataSet'),
          v_before_reference,
          false
        ) is distinct from v_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
          'status', 400,
          'message', 'Flow desired payload may replace only the indexed alias flow-property reference',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      begin
        if (v_before_exchange->>'meanValue')::numeric <> 1::numeric
          or (v_after_exchange->>'meanValue')::numeric <> 1::numeric then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
            'status', 400,
            'message', 'Singleton flow property references must retain meanValue=1',
            'details', jsonb_build_object('action_id', v_action_id)
          );
        end if;
      exception
        when numeric_value_out_of_range or invalid_text_representation then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
            'status', 400,
            'message', 'Singleton flow property meanValue must be a finite numeric',
            'details', jsonb_build_object('action_id', v_action_id)
          );
      end;

    elsif v_action_table = 'processes' then
      if not (v_mutation ?& array['kind', 'exchanges'])
        or exists (
          select 1
          from jsonb_object_keys(v_mutation) as mutation_key(key)
          where mutation_key.key <> all (array['kind', 'exchanges'])
        )
        or jsonb_typeof(v_mutation->'kind') is distinct from 'string'
        or v_mutation_kind <> 'process_exchange_amounts'
        or jsonb_typeof(v_mutation->'exchanges') is distinct from 'array'
        or jsonb_array_length(v_mutation->'exchanges') = 0 then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Process action requires a non-empty exact exchange mutation list',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      if exists (
        select 1
        from jsonb_array_elements(v_mutation->'exchanges') as duplicate_exchange(value)
        group by duplicate_exchange.value->>'index'
        having count(*) <> 1
      ) or exists (
        select 1
        from jsonb_array_elements(v_mutation->'exchanges') as duplicate_exchange(value)
        group by duplicate_exchange.value->>'internal_id'
        having count(*) <> 1
      ) then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_INVALID_MUTATION',
          'status', 400,
          'message', 'Process exchange indexes and internal IDs must be unique within an action',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;

      v_normalized_desired := v_desired_json_ordered;

      for v_mutation_exchange in
        select exchange_item.value
        from jsonb_array_elements(v_mutation->'exchanges') as exchange_item(value)
      loop
        if jsonb_typeof(v_mutation_exchange) is distinct from 'object'
          or not (v_mutation_exchange ?& array[
            'index',
            'internal_id',
            'flow_id',
            'flow_version',
            'direction',
            'before_exchange_sha256'
          ])
          or exists (
            select 1
            from jsonb_object_keys(v_mutation_exchange) as exchange_key(key)
            where exchange_key.key <> all (array[
              'index',
              'internal_id',
              'flow_id',
              'flow_version',
              'direction',
              'before_exchange_sha256'
            ])
          )
          or jsonb_typeof(v_mutation_exchange->'index') is distinct from 'number'
          or (v_mutation_exchange->>'index') !~ '^(0|[1-9][0-9]*)$'
          or octet_length(v_mutation_exchange->>'index') > 6
          or jsonb_typeof(v_mutation_exchange->'internal_id') is distinct from 'string'
          or nullif(v_mutation_exchange->>'internal_id', '') is null
          or octet_length(v_mutation_exchange->>'internal_id') > 128
          or jsonb_typeof(v_mutation_exchange->'flow_id') is distinct from 'string'
          or (v_mutation_exchange->>'flow_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or jsonb_typeof(v_mutation_exchange->'flow_version') is distinct from 'string'
          or (v_mutation_exchange->>'flow_version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
          or jsonb_typeof(v_mutation_exchange->'direction') is distinct from 'string'
          or v_mutation_exchange->>'direction' not in ('Input', 'Output')
          or jsonb_typeof(v_mutation_exchange->'before_exchange_sha256') is distinct from 'string'
          or (v_mutation_exchange->>'before_exchange_sha256') !~ '^[a-f0-9]{64}$'
          or not exists (
            select 1
            from jsonb_array_elements(p_batch->'actions') as flow_action(value)
            where flow_action.value->>'table' = 'flows'
              and flow_action.value->>'id' = v_mutation_exchange->>'flow_id'
              and flow_action.value->>'version' = v_mutation_exchange->>'flow_version'
          ) then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_INVALID_MUTATION',
            'status', 400,
            'message', 'Every process exchange locator must be exact and reference a flow action in this batch',
            'details', jsonb_build_object('action_id', v_action_id)
          );
        end if;

        v_mutation_index := (v_mutation_exchange->>'index')::integer;
        v_exchange_path := array[
          'processDataSet',
          'exchanges',
          'exchange',
          v_mutation_index::text
        ];
        v_before_exchange := v_expected_json_ordered #> v_exchange_path;
        v_after_exchange := v_desired_json_ordered #> v_exchange_path;

        if jsonb_typeof(v_before_exchange) is distinct from 'object'
          or jsonb_typeof(v_after_exchange) is distinct from 'object'
          or v_before_exchange->>'@dataSetInternalID' is distinct from v_mutation_exchange->>'internal_id'
          or v_after_exchange->>'@dataSetInternalID' is distinct from v_mutation_exchange->>'internal_id'
          or v_before_exchange#>>'{referenceToFlowDataSet,@refObjectId}' is distinct from v_mutation_exchange->>'flow_id'
          or v_before_exchange#>>'{referenceToFlowDataSet,@version}' is distinct from v_mutation_exchange->>'flow_version'
          or v_after_exchange#>>'{referenceToFlowDataSet,@refObjectId}' is distinct from v_mutation_exchange->>'flow_id'
          or v_after_exchange#>>'{referenceToFlowDataSet,@version}' is distinct from v_mutation_exchange->>'flow_version'
          or v_before_exchange->>'exchangeDirection' is distinct from v_mutation_exchange->>'direction'
          or v_after_exchange->>'exchangeDirection' is distinct from v_mutation_exchange->>'direction'
          or encode(
            extensions.digest(
              convert_to(
                private.dataset_alias_canonical_jsonb_v1(v_before_exchange),
                'UTF8'
              ),
              'sha256'
            ),
            'hex'
          ) is distinct from v_mutation_exchange->>'before_exchange_sha256' then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_MUTATION_EVIDENCE_MISMATCH',
            'status', 400,
            'message', 'Process exchange locator or canonical before hash does not match the expected payload',
            'details', jsonb_build_object(
              'action_id', v_action_id,
              'exchange_index', v_mutation_index
            )
          );
        end if;

        v_before_mean_text := v_before_exchange->>'meanAmount';
        v_after_mean_text := v_after_exchange->>'meanAmount';
        v_before_resulting_text := v_before_exchange->>'resultingAmount';
        v_after_resulting_text := v_after_exchange->>'resultingAmount';

        if jsonb_typeof(v_before_exchange->'meanAmount') is distinct from 'string'
          or jsonb_typeof(v_after_exchange->'meanAmount') is distinct from 'string'
          or jsonb_typeof(v_before_exchange->'resultingAmount') is distinct from 'string'
          or jsonb_typeof(v_after_exchange->'resultingAmount') is distinct from 'string'
          or octet_length(v_before_mean_text) > 128
          or octet_length(v_after_mean_text) > 128
          or octet_length(v_before_resulting_text) > 128
          or octet_length(v_after_resulting_text) > 128
          or v_before_mean_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_after_mean_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_before_resulting_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_after_resulting_text !~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'
          or v_before_mean_text is distinct from v_before_resulting_text
          or v_after_mean_text is distinct from v_after_resulting_text then
          return jsonb_build_object(
            'ok', false,
            'code', 'ALIAS_BATCH_INVALID_AMOUNT',
            'status', 400,
            'message', 'Listed process exchanges require numeric meanAmount and resultingAmount values',
            'details', jsonb_build_object(
              'action_id', v_action_id,
              'exchange_index', v_mutation_index
            )
          );
        end if;

        begin
          if v_after_mean_text::numeric
              is distinct from v_before_mean_text::numeric * v_factor::numeric
            or v_after_resulting_text::numeric
              is distinct from v_before_resulting_text::numeric * v_factor::numeric then
            return jsonb_build_object(
              'ok', false,
              'code', 'ALIAS_BATCH_INVALID_AMOUNT',
              'status', 400,
              'message', 'Listed process exchange amounts must use the exact frozen factor',
              'details', jsonb_build_object(
                'action_id', v_action_id,
                'exchange_index', v_mutation_index
              )
            );
          end if;
        exception
          when numeric_value_out_of_range or invalid_text_representation then
            return jsonb_build_object(
              'ok', false,
              'code', 'ALIAS_BATCH_INVALID_AMOUNT',
              'status', 400,
              'message', 'Listed process exchange amounts must be finite PostgreSQL numerics',
              'details', jsonb_build_object(
                'action_id', v_action_id,
                'exchange_index', v_mutation_index
              )
            );
        end;

        v_normalized_desired := jsonb_set(
          v_normalized_desired,
          array_append(v_exchange_path, 'meanAmount'),
          v_before_exchange->'meanAmount',
          false
        );
        v_normalized_desired := jsonb_set(
          v_normalized_desired,
          array_append(v_exchange_path, 'resultingAmount'),
          v_before_exchange->'resultingAmount',
          false
        );
        v_exchange_count := v_exchange_count + 1;
      end loop;

      if v_normalized_desired is distinct from v_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_MUTATION_SCOPE_VIOLATION',
          'status', 400,
          'message', 'Process desired payload may change only listed meanAmount and resultingAmount fields',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;
    end if;
  end loop;

  if (v_dimension = 'time' and v_exchange_count <> 20)
    or (v_dimension = 'length_time' and v_exchange_count <> 39) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_EXCHANGE_COUNT',
      'status', 400,
      'message', 'Listed exchange count does not match the frozen dimension scope',
      'details', jsonb_build_object('exchange_count', v_exchange_count)
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_batch->'actions') as batch_flow(value)
    where batch_flow.value->>'table' = 'flows'
      and not exists (
        select 1
        from jsonb_array_elements(p_batch->'actions') as batch_process(value)
        cross join lateral jsonb_array_elements(
          batch_process.value#>'{mutation,exchanges}'
        ) as process_exchange(value)
        where batch_process.value->>'table' = 'processes'
          and process_exchange.value->>'flow_id' = batch_flow.value->>'id'
          and process_exchange.value->>'flow_version' = batch_flow.value->>'version'
      )
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_INVALID_MUTATION',
      'status', 400,
      'message', 'Every flow action must be referenced by at least one listed process exchange'
    );
  end if;

  v_request_sha256 := encode(
    extensions.digest(convert_to(p_batch::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_target_flowproperty_sha256 := encode(
    extensions.digest(
      convert_to(v_target_flowproperty_expected_json_ordered::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_target_unitgroup_sha256 := encode(
    extensions.digest(
      convert_to(v_target_unitgroup_expected_json_ordered::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_source_unitgroup_sha256 := encode(
    extensions.digest(
      convert_to(v_source_unitgroup_expected_json_ordered::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  -- Stable table-level write locks close the phantom window between the
  -- support-parent and exact flow/process closure scans and the batch commit.
  -- This internal dimension executor holds these locks only inside the public
  -- full-plan call, whose exception subtransaction covers both dimensions. The
  -- lock wait remains capped at 5 seconds.
  lock table public.flowproperties, public.flows, public.processes
    in share row exclusive mode;

  v_current_row := null;
  v_target_actual_modified_at := null;
  v_target_actual_json_ordered := null;

  select
    target_fp.modified_at,
    target_fp.json_ordered::jsonb,
    to_jsonb(target_fp)
  into
    v_target_actual_modified_at,
    v_target_actual_json_ordered,
    v_current_row
  from public.flowproperties as target_fp
  where target_fp.id = v_target_flowproperty_id
    and target_fp.version = v_target_flowproperty_version
    and target_fp.user_id = v_actor
    and target_fp.state_code = 0
  for share of target_fp;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  if v_target_actual_modified_at is distinct from v_target_flowproperty_expected_modified_at
    or v_target_actual_json_ordered is distinct from v_target_flowproperty_expected_json_ordered then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_TARGET_PRECONDITION_FAILED',
      'status', 409,
      'message', 'Target flow property changed after the alias batch was planned',
      'details', jsonb_build_object('target', 'flowproperty')
    );
  end if;

  v_target_found := false;
  v_source_found := false;

  for v_current_row in
    select to_jsonb(support_ug)
    from public.unitgroups as support_ug
    where support_ug.user_id = v_actor
      and support_ug.state_code = 0
      and (
        (
          support_ug.id = v_target_unitgroup_id
          and support_ug.version = v_target_unitgroup_version
        ) or (
          support_ug.id = v_source_unitgroup_id
          and support_ug.version = v_source_unitgroup_version
        )
      )
    order by support_ug.id, support_ug.version
    for share of support_ug
  loop
    if (v_current_row->>'id')::uuid = v_target_unitgroup_id
      and btrim(v_current_row->>'version') = v_target_unitgroup_version then
      v_target_found := true;
      if (v_current_row->>'modified_at')::timestamptz
          is distinct from v_target_unitgroup_expected_modified_at
        or v_current_row->'json_ordered'
          is distinct from v_target_unitgroup_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_TARGET_PRECONDITION_FAILED',
          'status', 409,
          'message', 'Target unit group changed after the alias batch was planned',
          'details', jsonb_build_object('target', 'unitgroup')
        );
      end if;
    elsif (v_current_row->>'id')::uuid = v_source_unitgroup_id
      and btrim(v_current_row->>'version') = v_source_unitgroup_version then
      v_source_found := true;
      if (v_current_row->>'modified_at')::timestamptz
          is distinct from v_source_unitgroup_expected_modified_at
        or v_current_row->'json_ordered'
          is distinct from v_source_unitgroup_expected_json_ordered then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_SOURCE_SUPPORT_PRECONDITION_FAILED',
          'status', 409,
          'message', 'Source unit group changed after the alias batch was planned'
        );
      end if;
    end if;
  end loop;

  if not v_target_found then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  if not v_source_found then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  for v_action in
    select action_item.value
    from jsonb_array_elements(p_batch->'actions') as action_item(value)
    order by
      case action_item.value->>'table'
        when 'flowproperties' then 1
        when 'flows' then 2
        when 'processes' then 3
      end,
      (action_item.value->>'id')::uuid,
      action_item.value->>'version'
  loop
    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_current_row := null;
    v_actual_state_code := null;
    v_actual_modified_at := null;
    v_actual_json_ordered := null;

    execute format(
      'select t.state_code,
              t.modified_at,
              t.json_ordered::jsonb,
              to_jsonb(t)
         from public.%I as t
        where t.id = $1
          and t.version = $2
          and t.user_id = $3
          and t.state_code = 0
        for update of t',
      v_action_table
    )
      into
        v_actual_state_code,
        v_actual_modified_at,
        v_actual_json_ordered,
        v_current_row
      using v_action_uuid, v_action_version, v_actor;

    if v_current_row is null then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_DATASET_NOT_FOUND',
        'status', 404,
        'message', 'Dataset not found',
        'details', jsonb_build_object('action_id', v_action->>'action_id')
      );
    end if;

    v_locked_actions := v_locked_actions || jsonb_build_array(
      v_action || jsonb_build_object(
        '_actual_state_code', v_actual_state_code,
        '_actual_modified_at', v_actual_modified_at,
        '_actual_json_ordered', v_actual_json_ordered
      )
    );
  end loop;

  -- A private support row must not already participate in a public, foreign,
  -- or otherwise non-draft parent closure. The source flow-property closure
  -- is checked exactly below because those flows are rewritten. Target-FP and
  -- source/target-UG parents may include additional same-owner draft rows that
  -- are outside this mutation, but no mixed-visibility parent is allowed.
  with support_references as (
    select *
    from (values
      (v_source_flowproperty_id::text, v_source_flowproperty_version),
      (v_target_flowproperty_id::text, v_target_flowproperty_version)
    ) as support_reference(id, version)
  ),
  support_parent_flow_keys as materialized (
    select distinct candidate_flow.id, candidate_flow.version
    from support_references as support_reference
    cross join lateral (
      select dataset_flow.id, dataset_flow.version
      from public.flows as dataset_flow
      where private.dataset_alias_jsonb_array_v1(
          dataset_flow.json_ordered::jsonb
            #> '{flowDataSet,flowProperties,flowProperty}'
        ) @> jsonb_build_array(jsonb_build_object(
          'referenceToFlowPropertyDataSet',
          jsonb_build_object(
            '@refObjectId', support_reference.id,
            '@version', support_reference.version
          )
        ))
    ) as candidate_flow
  )
  select
    exists (
      select 1
      from support_parent_flow_keys
      cross join lateral (
        select
          candidate_parent.json_ordered,
          candidate_parent.user_id,
          candidate_parent.state_code
        from public.flows as candidate_parent
        where candidate_parent.id = support_parent_flow_keys.id
          and candidate_parent.version = support_parent_flow_keys.version
        limit 1
      ) as support_parent_flow
      cross join lateral jsonb_array_elements(
        private.dataset_alias_jsonb_array_v1(
          support_parent_flow.json_ordered::jsonb
            #> '{flowDataSet,flowProperties,flowProperty}'
        )
      ) as support_parent_property(value)
      join support_references as support_reference
        on support_reference.id = support_parent_property.value
          #>> '{referenceToFlowPropertyDataSet,@refObjectId}'
        and support_reference.version = support_parent_property.value
          #>> '{referenceToFlowPropertyDataSet,@version}'
      where (
          support_parent_flow.user_id is distinct from v_actor
          or support_parent_flow.state_code is distinct from 0
        )
    ) or exists (
      select 1
      from public.flowproperties as support_parent_fp
      where (
          (
            support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@refObjectId}' =
              v_source_unitgroup_id::text
            and support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@version}' =
              v_source_unitgroup_version
          ) or (
            support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@refObjectId}' =
              v_target_unitgroup_id::text
            and support_parent_fp.json_ordered::jsonb
              #>> '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@version}' =
              v_target_unitgroup_version
          )
        )
        and (
          support_parent_fp.user_id is distinct from v_actor
          or support_parent_fp.state_code is distinct from 0
        )
    )
  into v_forbidden_closure_exists;

  if v_forbidden_closure_exists then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_CLOSURE_MISMATCH',
      'status', 409,
      'message', 'Live owner-draft closure does not match the exact submitted batch'
    );
  end if;

  with submitted_flows as materialized (
    select
      (flow_action.value->>'id')::uuid as id,
      flow_action.value->>'version' as version,
      flow_action.value#>>'{mutation,flow_property_internal_id}' as internal_id
    from jsonb_array_elements(p_batch->'actions') as flow_action(value)
    where flow_action.value->>'table' = 'flows'
  ),
  candidate_flow_keys as materialized (
    select dataset_flow.id, dataset_flow.version
    from public.flows as dataset_flow
    where private.dataset_alias_jsonb_array_v1(
        dataset_flow.json_ordered::jsonb
          #> '{flowDataSet,flowProperties,flowProperty}'
      ) @> jsonb_build_array(jsonb_build_object(
        'referenceToFlowPropertyDataSet',
        jsonb_build_object(
          '@refObjectId', v_source_flowproperty_id::text,
          '@version', v_source_flowproperty_version
        )
      ))
  ),
  live_flows as (
    select
      dataset_flow.id,
      btrim(dataset_flow.version::text) as version,
      dataset_flow.user_id,
      dataset_flow.state_code,
      flow_property.value->>'@dataSetInternalID' as internal_id
    from candidate_flow_keys
    cross join lateral (
      -- LIMIT 1 is lossless because (id, version) is the primary key and
      -- keeps the exact recheck as candidate-driven primary-key lookups.
      select
        candidate_flow.id,
        candidate_flow.version,
        candidate_flow.json_ordered,
        candidate_flow.user_id,
        candidate_flow.state_code
      from public.flows as candidate_flow
      where candidate_flow.id = candidate_flow_keys.id
        and candidate_flow.version = candidate_flow_keys.version
      limit 1
    ) as dataset_flow
    cross join lateral jsonb_array_elements(
      private.dataset_alias_jsonb_array_v1(
        dataset_flow.json_ordered::jsonb
          #> '{flowDataSet,flowProperties,flowProperty}'
      )
    ) as flow_property(value)
    where flow_property.value
        #>> '{referenceToFlowPropertyDataSet,@refObjectId}' =
        v_source_flowproperty_id::text
      and flow_property.value
        #>> '{referenceToFlowPropertyDataSet,@version}' =
        v_source_flowproperty_version
  )
  select
    count(*) filter (
      where live_flows.user_id = v_actor
        and live_flows.state_code = 0
    ),
    coalesce(bool_and(
      case
        when live_flows.user_id = v_actor
          and live_flows.state_code = 0 then exists (
            select 1
            from submitted_flows
            where submitted_flows.id = live_flows.id
              and submitted_flows.version = live_flows.version
              and submitted_flows.internal_id = live_flows.internal_id
          )
        else true
      end
    ), true),
    coalesce(bool_or(
      live_flows.user_id is distinct from v_actor
        or live_flows.state_code is distinct from 0
    ), false)
  into
    v_live_flow_closure_count,
    v_closure_exact,
    v_forbidden_closure_exists
  from live_flows;

  if v_forbidden_closure_exists
    or v_live_flow_closure_count not in (0, v_flow_count)
    or not v_closure_exact then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_CLOSURE_MISMATCH',
      'status', 409,
      'message', 'Live owner-draft closure does not match the exact submitted batch'
    );
  end if;

  with submitted_flows as materialized (
    select
      flow_action.value->>'id' as id,
      flow_action.value->>'version' as version
    from jsonb_array_elements(p_batch->'actions') as flow_action(value)
    where flow_action.value->>'table' = 'flows'
  ),
  candidate_process_keys as materialized (
    select distinct candidate_process.id, candidate_process.version
    from submitted_flows
    cross join lateral (
      select dataset_process.id, dataset_process.version
      from public.processes as dataset_process
      where private.dataset_alias_jsonb_array_v1(
          dataset_process.json_ordered::jsonb
            #> '{processDataSet,exchanges,exchange}'
        ) @> jsonb_build_array(jsonb_build_object(
          'referenceToFlowDataSet',
          jsonb_build_object(
            '@refObjectId', submitted_flows.id,
            '@version', submitted_flows.version
          )
        ))
    ) as candidate_process
  ),
  live_exchanges as (
    select
      dataset_process.id as process_id,
      btrim(dataset_process.version::text) as process_version,
      exchange_item.ordinality - 1 as exchange_index,
      exchange_item.value->>'@dataSetInternalID' as internal_id,
      exchange_item.value#>>'{referenceToFlowDataSet,@refObjectId}' as flow_id,
      exchange_item.value#>>'{referenceToFlowDataSet,@version}' as flow_version,
      exchange_item.value->>'exchangeDirection' as direction,
      dataset_process.user_id,
      dataset_process.state_code
    from candidate_process_keys
    cross join lateral (
      -- LIMIT 1 is lossless because (id, version) is the primary key and
      -- prevents a candidate estimate from choosing a full wide-row hash scan.
      select
        candidate_process.id,
        candidate_process.version,
        candidate_process.json_ordered,
        candidate_process.user_id,
        candidate_process.state_code
      from public.processes as candidate_process
      where candidate_process.id = candidate_process_keys.id
        and candidate_process.version = candidate_process_keys.version
      limit 1
    ) as dataset_process
    cross join lateral jsonb_array_elements(
      private.dataset_alias_jsonb_array_v1(
        dataset_process.json_ordered::jsonb
          #> '{processDataSet,exchanges,exchange}'
      )
    ) with ordinality as exchange_item(value, ordinality)
    join submitted_flows
      on submitted_flows.id =
        exchange_item.value#>>'{referenceToFlowDataSet,@refObjectId}'
      and submitted_flows.version =
        exchange_item.value#>>'{referenceToFlowDataSet,@version}'
  )
  select
    count(distinct (
      live_exchanges.process_id,
      live_exchanges.process_version
    )) filter (
      where live_exchanges.user_id = v_actor
        and live_exchanges.state_code = 0
    ),
    count(*) filter (
      where live_exchanges.user_id = v_actor
        and live_exchanges.state_code = 0
    ),
    coalesce(bool_and(
      case
        when live_exchanges.user_id = v_actor
          and live_exchanges.state_code = 0 then exists (
            select 1
            from jsonb_array_elements(p_batch->'actions') as process_action(value)
            cross join lateral jsonb_array_elements(
              process_action.value#>'{mutation,exchanges}'
            ) as submitted_exchange(value)
            where process_action.value->>'table' = 'processes'
              and process_action.value->>'id' = live_exchanges.process_id::text
              and process_action.value->>'version' = live_exchanges.process_version
              and (submitted_exchange.value->>'index')::integer = live_exchanges.exchange_index
              and submitted_exchange.value->>'internal_id' = live_exchanges.internal_id
              and submitted_exchange.value->>'flow_id' = live_exchanges.flow_id
              and submitted_exchange.value->>'flow_version' = live_exchanges.flow_version
              and submitted_exchange.value->>'direction' = live_exchanges.direction
          )
        else true
      end
    ), true),
    coalesce(bool_or(
      live_exchanges.user_id is distinct from v_actor
        or live_exchanges.state_code is distinct from 0
    ), false)
  into
    v_live_process_closure_count,
    v_live_exchange_closure_count,
    v_closure_exact,
    v_forbidden_closure_exists
  from live_exchanges;

  if v_forbidden_closure_exists
    or v_live_process_closure_count <> v_process_count
    or v_live_exchange_closure_count <> v_exchange_count
    or not v_closure_exact then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_CLOSURE_MISMATCH',
      'status', 409,
      'message', 'Live owner-draft closure does not match the exact submitted batch'
    );
  end if;

  for v_action in
    select locked_item.value
    from jsonb_array_elements(v_locked_actions) as locked_item(value)
  loop
    v_action_id := v_action->>'action_id';
    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_expected_state_code := (v_action->>'expected_state_code')::integer;
    v_expected_modified_at := (v_action->>'expected_modified_at')::timestamptz;
    v_expected_json_ordered := v_action->'expected_json_ordered';
    v_desired_json_ordered := v_action->'desired_json_ordered';
    v_actual_state_code := (v_action->>'_actual_state_code')::integer;
    v_actual_modified_at := (v_action->>'_actual_modified_at')::timestamptz;
    v_actual_json_ordered := v_action->'_actual_json_ordered';
    v_before_sha256 := encode(
      extensions.digest(convert_to(v_expected_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_after_sha256 := encode(
      extensions.digest(convert_to(v_desired_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_prior_audit_id := null;

    select audit_log.id
    into v_prior_audit_id
    from private.command_audit_log as audit_log
    where audit_log.command = v_command
      and audit_log.actor_user_id = v_actor
      and audit_log.target_table = v_action_table
      and audit_log.target_id = v_action_uuid
      and audit_log.target_version = v_action_version
      and audit_log.payload->>'record_type' = 'row'
      and audit_log.payload->>'schema_version' = v_schema_version
      and audit_log.payload->>'plan_sha256' = v_plan_sha256
      and audit_log.payload->>'operation_id' = v_operation_id
      and audit_log.payload->>'batch_id' = v_batch_id
      and audit_log.payload->>'dimension' = v_dimension
      and audit_log.payload->>'factor' = v_factor
      and audit_log.payload->>'target_visibility' = v_target_visibility
      and audit_log.payload->>'batch_request_sha256' = v_request_sha256
      and audit_log.payload->>'hash_algorithm' = 'postgres-jsonb-text-sha256'
      and audit_log.payload->>'exchange_evidence_hash_algorithm' = 'sorted-key-compact-json-v1-sha256'
      and audit_log.payload->>'action_id' = v_action_id
      and audit_log.payload->>'expected_state_code' = v_expected_state_code::text
      and audit_log.payload->'expected_modified_at' = to_jsonb(v_expected_modified_at)
      and audit_log.payload->>'expected_json_ordered_sha256' = v_before_sha256
      and audit_log.payload->>'desired_json_ordered_sha256' = v_after_sha256
      and audit_log.payload->>'mutation_sha256' = encode(
        extensions.digest(convert_to((v_action->'mutation')::text, 'UTF8'), 'sha256'),
        'hex'
      )
      and audit_log.payload->'committed_modified_at' = to_jsonb(v_actual_modified_at)
    order by audit_log.id desc
    limit 1;

    if v_actual_state_code = v_expected_state_code
      and v_actual_modified_at is not distinct from v_expected_modified_at
      and v_actual_json_ordered = v_expected_json_ordered then
      if v_prior_audit_id is not null then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_AUDIT_STATE_CONFLICT',
          'status', 409,
          'message', 'A matching committed audit exists while a row is still at its before state',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;
      v_fresh_count := v_fresh_count + 1;
    elsif v_actual_state_code = v_expected_state_code
      and v_actual_json_ordered = v_desired_json_ordered then
      if v_prior_audit_id is null then
        return jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_BATCH_REPLAY_UNPROVEN',
          'status', 409,
          'message', 'A desired-state row has no exact committed batch audit proof',
          'details', jsonb_build_object('action_id', v_action_id)
        );
      end if;
      v_replay_count := v_replay_count + 1;
      v_audit_rows := v_audit_rows || jsonb_build_array(jsonb_build_object(
        'action_id', v_action_id,
        'table', v_action_table,
        'id', v_action_uuid,
        'version', v_action_version,
        'audit_id', v_prior_audit_id::text
      ));
    else
      v_mismatches := array[]::text[];
      if v_actual_state_code is distinct from v_expected_state_code then
        v_mismatches := array_append(v_mismatches, 'state_code');
      end if;
      if v_actual_modified_at is distinct from v_expected_modified_at then
        v_mismatches := array_append(v_mismatches, 'modified_at');
      end if;
      if v_actual_json_ordered is distinct from v_expected_json_ordered then
        v_mismatches := array_append(v_mismatches, 'json_ordered');
      end if;

      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_PRECONDITION_FAILED',
        'status', 409,
        'message', 'A dataset changed after the alias batch was planned',
        'details', jsonb_build_object(
          'action_id', v_action_id,
          'mismatches', to_jsonb(v_mismatches)
        )
      );
    end if;
  end loop;

  v_summary_audit_id := null;

  select audit_log.id
  into v_summary_audit_id
  from private.command_audit_log as audit_log
  where audit_log.command = v_command
    and audit_log.actor_user_id = v_actor
    and audit_log.target_table is null
    and audit_log.target_id is null
    and audit_log.target_version is null
    and audit_log.payload->>'record_type' = 'batch_summary'
    and audit_log.payload->>'schema_version' = v_schema_version
    and audit_log.payload->>'plan_sha256' = v_plan_sha256
    and audit_log.payload->>'operation_id' = v_operation_id
    and audit_log.payload->>'batch_id' = v_batch_id
    and audit_log.payload->>'dimension' = v_dimension
    and audit_log.payload->>'factor' = v_factor
    and audit_log.payload->>'target_visibility' = v_target_visibility
    and audit_log.payload->>'batch_request_sha256' = v_request_sha256
    and audit_log.payload->>'hash_algorithm' = 'postgres-jsonb-text-sha256'
    and audit_log.payload->>'exchange_evidence_hash_algorithm' = 'sorted-key-compact-json-v1-sha256'
    and audit_log.payload->>'batch_action_count' = v_action_count::text
    and audit_log.payload->>'exchange_count' = v_exchange_count::text
    and audit_log.payload->>'target_flowproperty_sha256' = v_target_flowproperty_sha256
    and audit_log.payload->>'target_unitgroup_sha256' = v_target_unitgroup_sha256
    and audit_log.payload->>'source_unitgroup_sha256' = v_source_unitgroup_sha256
    and audit_log.payload->>'target_flowproperty_expected_state_code' = '0'
    and audit_log.payload->>'target_unitgroup_expected_state_code' = '0'
    and audit_log.payload->>'source_unitgroup_expected_state_code' = '0'
    and audit_log.payload->>'support_owner_user_id' = v_actor::text
  order by audit_log.id desc
  limit 1;

  select count(*)
  into v_existing_audit_count
  from private.command_audit_log as audit_log
  where audit_log.command = v_command
    and audit_log.actor_user_id = v_actor
    and audit_log.payload->>'batch_request_sha256' = v_request_sha256;

  if v_replay_count = v_action_count then
    if v_summary_audit_id is null
      or v_existing_audit_count <> v_action_count + 1 then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_BATCH_REPLAY_UNPROVEN',
        'status', 409,
        'message', 'Committed audit cardinality does not match the exact batch'
      );
    end if;

    return jsonb_build_object(
      'ok', true,
      'command', v_command,
      'dimension', v_dimension,
      'target_visibility', v_target_visibility,
      'batch_id', v_batch_id,
      'batch_request_sha256', v_request_sha256,
      'row_count', v_action_count,
      'exchange_count', v_exchange_count,
      'summary_audit_id', v_summary_audit_id::text,
      'audit', v_audit_rows,
      'idempotent_replay', true
    );
  end if;

  if v_fresh_count <> v_action_count then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_PARTIAL_STATE',
      'status', 409,
      'message', 'Batch rows are split between before and committed states'
    );
  end if;

  if v_existing_audit_count <> 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_BATCH_AUDIT_STATE_CONFLICT',
      'status', 409,
      'message', 'Audit rows already exist for a batch whose datasets remain at the before state'
    );
  end if;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    v_command,
    v_actor,
    null,
    null,
    null,
    jsonb_build_object(
      'record_type', 'batch_summary',
      'schema_version', v_schema_version,
      'plan_sha256', v_plan_sha256,
      'operation_id', v_operation_id,
      'batch_id', v_batch_id,
      'dimension', v_dimension,
      'factor', v_factor,
      'target_visibility', v_target_visibility,
      'batch_request_sha256', v_request_sha256,
      'hash_algorithm', 'postgres-jsonb-text-sha256',
      'exchange_evidence_hash_algorithm', 'sorted-key-compact-json-v1-sha256',
      'batch_action_count', v_action_count,
      'flowproperty_count', v_flowproperty_count,
      'flow_count', v_flow_count,
      'process_count', v_process_count,
      'exchange_count', v_exchange_count,
      'target_flowproperty_id', v_target_flowproperty_id,
      'target_flowproperty_version', v_target_flowproperty_version,
      'target_flowproperty_expected_modified_at', v_target_flowproperty_expected_modified_at,
      'target_flowproperty_expected_state_code', 0,
      'target_flowproperty_sha256', v_target_flowproperty_sha256,
      'target_unitgroup_id', v_target_unitgroup_id,
      'target_unitgroup_version', v_target_unitgroup_version,
      'target_unitgroup_expected_modified_at', v_target_unitgroup_expected_modified_at,
      'target_unitgroup_expected_state_code', 0,
      'target_unitgroup_sha256', v_target_unitgroup_sha256,
      'source_unitgroup_id', v_source_unitgroup_id,
      'source_unitgroup_version', v_source_unitgroup_version,
      'source_unitgroup_expected_modified_at', v_source_unitgroup_expected_modified_at,
      'source_unitgroup_expected_state_code', 0,
      'source_unitgroup_sha256', v_source_unitgroup_sha256,
      'support_owner_user_id', v_actor
    )
  )
  returning id into v_summary_audit_id;

  for v_action in
    select locked_item.value
    from jsonb_array_elements(v_locked_actions) as locked_item(value)
  loop
    v_action_id := v_action->>'action_id';
    v_action_table := v_action->>'table';
    v_action_uuid := (v_action->>'id')::uuid;
    v_action_version := v_action->>'version';
    v_expected_state_code := (v_action->>'expected_state_code')::integer;
    v_expected_modified_at := (v_action->>'expected_modified_at')::timestamptz;
    v_expected_json_ordered := v_action->'expected_json_ordered';
    v_desired_json_ordered := v_action->'desired_json_ordered';
    v_before_sha256 := encode(
      extensions.digest(convert_to(v_expected_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_after_sha256 := encode(
      extensions.digest(convert_to(v_desired_json_ordered::text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_committed_modified_at := null;
    v_committed_json_ordered := null;
    v_committed_version := null;

    execute format(
      'update public.%I as t
          set json_ordered = $1::json,
              modified_at = now()
        where t.id = $2
          and t.version = $3
          and t.user_id = $4
          and t.state_code = $5
          and t.modified_at is not distinct from $6
          and t.json_ordered::jsonb is not distinct from $7
      returning t.modified_at, t.json_ordered::jsonb, t.version::text',
      v_action_table
    )
      into
        v_committed_modified_at,
        v_committed_json_ordered,
        v_committed_version
      using
        v_desired_json_ordered,
        v_action_uuid,
        v_action_version,
        v_actor,
        v_expected_state_code,
        v_expected_modified_at,
        v_expected_json_ordered;

    if v_committed_modified_at is null
      or v_committed_json_ordered is distinct from v_desired_json_ordered
      or v_committed_version is distinct from v_action_version then
      raise exception using
        errcode = 'P0001',
        message = format(
          'Guarded alias batch lost its locked update precondition for action %s',
          v_action_id
        );
    end if;

    insert into private.command_audit_log (
      command,
      actor_user_id,
      target_table,
      target_id,
      target_version,
      payload
    )
    values (
      v_command,
      v_actor,
      v_action_table,
      v_action_uuid,
      v_action_version,
      jsonb_build_object(
        'record_type', 'row',
        'schema_version', v_schema_version,
        'plan_sha256', v_plan_sha256,
        'operation_id', v_operation_id,
        'batch_id', v_batch_id,
        'dimension', v_dimension,
        'factor', v_factor,
        'target_visibility', v_target_visibility,
        'batch_request_sha256', v_request_sha256,
        'hash_algorithm', 'postgres-jsonb-text-sha256',
        'exchange_evidence_hash_algorithm', 'sorted-key-compact-json-v1-sha256',
        'batch_action_count', v_action_count,
        'target_flowproperty_id', v_target_flowproperty_id,
        'target_flowproperty_version', v_target_flowproperty_version,
        'target_unitgroup_id', v_target_unitgroup_id,
        'target_unitgroup_version', v_target_unitgroup_version,
        'source_unitgroup_id', v_source_unitgroup_id,
        'source_unitgroup_version', v_source_unitgroup_version,
        'action_id', v_action_id,
        'action', 'update_json_ordered',
        'mutation_sha256', encode(
          extensions.digest(convert_to((v_action->'mutation')::text, 'UTF8'), 'sha256'),
          'hex'
        ),
        'expected_state_code', v_expected_state_code,
        'expected_modified_at', v_expected_modified_at,
        'expected_json_ordered_sha256', v_before_sha256,
        'desired_json_ordered_sha256', v_after_sha256,
        'committed_modified_at', v_committed_modified_at
      )
    )
    returning id into v_audit_id;

    v_audit_rows := v_audit_rows || jsonb_build_array(jsonb_build_object(
      'action_id', v_action_id,
      'table', v_action_table,
      'id', v_action_uuid,
      'version', v_action_version,
      'audit_id', v_audit_id::text
    ));
  end loop;

  select count(*)
  into v_existing_audit_count
  from private.command_audit_log as audit_log
  where audit_log.command = v_command
    and audit_log.actor_user_id = v_actor
    and audit_log.payload->>'batch_request_sha256' = v_request_sha256;

  if v_existing_audit_count <> v_action_count + 1 then
    raise exception using
      errcode = 'P0001',
      message = 'Guarded alias batch committed an incomplete audit set';
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', v_command,
    'dimension', v_dimension,
    'target_visibility', v_target_visibility,
    'batch_id', v_batch_id,
    'batch_request_sha256', v_request_sha256,
    'row_count', v_action_count,
    'exchange_count', v_exchange_count,
    'summary_audit_id', v_summary_audit_id::text,
    'audit', v_audit_rows,
    'idempotent_replay', false
  );
end;
$_$;


ALTER FUNCTION private.cmd_dataset_alias_batch_guarded(p_batch jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_batch_guarded(p_batch jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.cmd_dataset_alias_batch_guarded(p_batch jsonb) IS 'Internal owner-draft dimension executor used only by the guarded full-plan RPC. Direct API execution is revoked so time and length_time cannot commit independently; the executor retains exact actor, state, closure, hash, audit, and replay checks for its dimension.';


--
-- Name: cmd_dataset_alias_execution_execute(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '60s'
    AS $_$
declare
  v_request util.dataset_alias_execution_requests%rowtype;
  v_preflight util.dataset_alias_execution_preflights%rowtype;
  v_alias_result jsonb;
  v_primary_closure jsonb;
  v_batch_result jsonb;
  v_alias_audit_count integer;
  v_failure jsonb;
  v_committed_at timestamp with time zone;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  if p_request_id is null
    or p_nonce is null
    or p_nonce !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_INVALID_SERVICE_REQUEST',
      'status', 400,
      'message', 'Exact request ID and executor nonce are required'
    );
  end if;

  select request.*
  into v_request
  from util.dataset_alias_execution_requests as request
  where request.id = p_request_id
  for update;

  if v_request.id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_REQUEST_NOT_FOUND',
      'status', 404,
      'message', 'Protected execution request not found'
    );
  end if;

  if util.dataset_alias_execution_sha256(p_nonce)
      is distinct from v_request.nonce_sha256 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_NONCE_MISMATCH',
      'status', 403,
      'message', 'Executor nonce does not match the admitted request'
    );
  end if;

  if v_request.status is distinct from 'dispatched'
    or v_request.dispatch_count <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_ALREADY_STARTED',
      'status', 409,
      'message', 'The one-shot executor may start only once',
      'request_status', v_request.status,
      'retry_allowed', false
    );
  end if;

  select preflight.*
  into v_preflight
  from util.dataset_alias_execution_preflights as preflight
  where preflight.id = p_request_id
    and preflight.actor_user_id = v_request.actor_user_id;

  if v_preflight.id is null
    or v_preflight.consumed_at is null
    or v_preflight.preflight_proof_sha256
      is distinct from v_request.preflight_proof_sha256 then
    update util.dataset_alias_execution_requests
    set
      status = 'indeterminate',
      terminal_at = pg_catalog.clock_timestamp(),
      last_error = jsonb_build_object(
        'phase', 'executor_precondition',
        'code', 'ALIAS_EXECUTION_PREFLIGHT_LEDGER_MISMATCH'
      ),
      updated_at = pg_catalog.clock_timestamp()
    where id = p_request_id;

    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_EXECUTION_PREFLIGHT_LEDGER_MISMATCH',
      'status', 'indeterminate',
      'retry_allowed', false
    );
  end if;

  update util.dataset_alias_execution_requests
  set
    status = 'running',
    started_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where id = p_request_id;

  -- The service request remains authenticated by its secret headers.  Only
  -- auth.uid()/auth.email() are rebound so the existing owner-draft alias
  -- validators execute against the originally admitted actor.
  perform pg_catalog.set_config(
    'request.jwt.claim.sub',
    v_request.actor_user_id::text,
    true
  );
  perform pg_catalog.set_config(
    'request.jwt.claim.email',
    v_preflight.actor_email,
    true
  );

  begin
    v_alias_result := private.cmd_dataset_alias_plan_guarded(v_preflight.plan);

    if coalesce((v_alias_result->>'ok')::boolean, false) is not true
      or coalesce((v_alias_result->>'idempotent_replay')::boolean, true)
      or v_alias_result->>'plan_sha256' is distinct from v_request.plan_sha256
      or v_alias_result->>'operation_id' is distinct from v_request.operation_id
      or v_alias_result->>'plan_request_sha256'
        is distinct from v_request.plan_request_sha256
      or v_alias_result->>'row_count' is distinct from '52'
      or v_alias_result->>'exchange_count' is distinct from '59' then
      v_failure := jsonb_build_object(
        'phase', 'alias',
        'code', 'ALIAS_EXECUTION_PRIMARY_REJECTED',
        'result', coalesce(v_alias_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected primary alias execution rejected';
    end if;

    select count(*)
    into v_alias_audit_count
    from private.command_audit_log as audit
    where audit.actor_user_id = v_request.actor_user_id
      and (
        (
          audit.command = 'cmd_dataset_alias_batch_guarded'
          and audit.payload->>'plan_sha256' = v_request.plan_sha256
          and audit.payload->>'operation_id' = v_request.operation_id
          and audit.payload->>'record_type' in ('row', 'batch_summary')
        )
        or (
          audit.command = 'cmd_dataset_alias_plan_guarded'
          and audit.payload->>'plan_request_sha256' = v_request.plan_request_sha256
          and audit.payload->>'record_type' = 'plan_summary'
        )
      );

    if v_alias_audit_count <> 55 then
      v_failure := jsonb_build_object(
        'phase', 'alias_audit',
        'code', 'ALIAS_EXECUTION_AUDIT_COUNT_MISMATCH',
        'expected', 55,
        'observed', v_alias_audit_count
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected alias audit set is incomplete';
    end if;

    v_primary_closure :=
      util.read_dataset_alias_execution_primary_closure(
        v_request.actor_user_id,
        v_preflight.plan
      );

    if coalesce(
        (v_primary_closure->>'live_closure_proof')::boolean,
        false
      ) is not true
      or v_primary_closure->>'row_count' is distinct from '52'
      or v_primary_closure->>'exchange_count' is distinct from '59'
      or v_primary_closure->>'support_reference_count' is distinct from '6'
      or v_primary_closure->>'invalid_action_count' is distinct from '0'
      or v_primary_closure->>'invalid_support_count' is distinct from '0' then
      v_failure := jsonb_build_object(
        'phase', 'primary_closure',
        'code', 'ALIAS_EXECUTION_PRIMARY_CLOSURE_MISMATCH',
        'proof', coalesce(v_primary_closure, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected primary/support live closure is incomplete';
    end if;

    v_batch_result := util.admit_dataset_derivative_rebuild_batch(
      v_request.actor_user_id,
      v_request.id,
      v_request.plan_sha256,
      v_request.operation_id,
      'PROTECTED_ALIAS_DERIVATIVE_CLOSURE',
      v_preflight.derivative_targets
    );

    if coalesce((v_batch_result->>'ok')::boolean, false) is not true
      or v_batch_result->>'target_count' is distinct from '50'
      or coalesce(v_batch_result->>'flow_count', v_batch_result->>'flows')
        is distinct from '23'
      or coalesce(v_batch_result->>'process_count', v_batch_result->>'processes')
        is distinct from '27' then
      v_failure := jsonb_build_object(
        'phase', 'derivative_batch',
        'code', 'ALIAS_EXECUTION_DERIVATIVE_ADMISSION_MISMATCH',
        'result', coalesce(v_batch_result, '{}'::jsonb)
      );
      raise exception using
        errcode = 'P0001',
        message = 'Protected derivative batch admission rejected';
    end if;

    v_committed_at := pg_catalog.clock_timestamp();

    update util.dataset_alias_execution_requests
    set
      status = 'derivatives_pending',
      primary_committed_at = v_committed_at,
      alias_result = v_alias_result || jsonb_build_object(
        'primary_closure', v_primary_closure
      ),
      derivative_admission = v_batch_result,
      updated_at = v_committed_at
    where id = p_request_id;
  exception
    when others then
      if v_failure is null then
        v_failure := jsonb_build_object(
          'phase', 'executor',
          'code', 'ALIAS_EXECUTION_TRANSACTION_FAILED',
          'sqlstate', sqlstate,
          'message', sqlerrm
        );
      end if;
  end;

  if v_failure is not null then
    update util.dataset_alias_execution_requests
    set
      status = 'failed',
      terminal_at = pg_catalog.clock_timestamp(),
      last_error = v_failure,
      updated_at = pg_catalog.clock_timestamp()
    where id = p_request_id;

    return jsonb_build_object(
      'ok', false,
      'command', 'cmd_dataset_alias_execution_execute',
      'request_id', p_request_id,
      'status', 'failed',
      'primary_rolled_back', true,
      'retry_allowed', false,
      'error', v_failure
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', 'cmd_dataset_alias_execution_execute',
    'request_id', p_request_id,
    'status', 'derivatives_pending',
    'plan_sha256', v_request.plan_sha256,
    'operation_id', v_request.operation_id,
    'plan_request_sha256', v_request.plan_request_sha256,
    'primary_committed_at', v_committed_at,
    'row_count', 52,
    'exchange_count', 59,
    'alias_audit_count', 55,
    'primary_closure', v_primary_closure,
    'derivative_target_count', 50,
    'retry_allowed', false
  );
end;
$_$;


ALTER FUNCTION private.cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.cmd_dataset_alias_execution_execute(p_request_id uuid, p_nonce text) IS 'Service-only, nonce-bound, non-replayable executor. It commits either the exact 52 alias rows/59 exchanges/55 alias audits plus all 50 derivative child requests in one transaction, or none of those business effects.';


--
-- Name: cmd_dataset_alias_plan_guarded(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_dataset_alias_plan_guarded(p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '45s'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_schema_version constant text := 'dataset-alias-plan.v1';
  v_batch_schema_version constant text := 'dataset-alias-batch.v1';
  v_command constant text := 'cmd_dataset_alias_plan_guarded';
  v_plan_sha256 text;
  v_operation_id text;
  v_target_visibility text;
  v_batches jsonb;
  v_time_batch jsonb;
  v_length_time_batch jsonb;
  v_batch jsonb;
  v_dimension text;
  v_expected_dimension text;
  v_expected_factor text;
  v_expected_action_count integer;
  v_action_count integer;
  v_owned_action_count integer;
  v_action_distinct_count integer;
  v_batch_request_sha256 text;
  v_time_batch_request_sha256 text;
  v_length_time_batch_request_sha256 text;
  v_plan_request_sha256 text;
  v_time_result jsonb;
  v_length_time_result jsonb;
  v_batch_result jsonb;
  v_failure_result jsonb;
  v_failed_dimension text;
  v_time_replay boolean;
  v_length_time_replay boolean;
  v_time_summary_audit_id bigint;
  v_length_time_summary_audit_id bigint;
  v_plan_summary_audit_id bigint;
  v_existing_plan_audit_count integer;
  v_batch_proof_count integer;
  v_support_owned boolean;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_plan is not null and pg_column_size(p_plan) > 268435456 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_REQUEST_TOO_LARGE',
      'status', 413,
      'message', 'Alias plan request exceeds the 256 MiB database limit'
    );
  end if;

  if jsonb_typeof(p_plan) is distinct from 'object'
    or not (p_plan ?& array[
      'schema_version',
      'plan_sha256',
      'operation_id',
      'target_visibility',
      'batches'
    ])
    or exists (
      select 1
      from jsonb_object_keys(p_plan) as plan_key(key)
      where plan_key.key <> all (array[
        'schema_version',
        'plan_sha256',
        'operation_id',
        'target_visibility',
        'batches'
      ])
    ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_REQUEST',
      'status', 400,
      'message', 'Plan request must match dataset-alias-plan.v1 exactly'
    );
  end if;

  if jsonb_typeof(p_plan->'schema_version') is distinct from 'string'
    or p_plan->>'schema_version' <> v_schema_version
    or jsonb_typeof(p_plan->'plan_sha256') is distinct from 'string'
    or (p_plan->>'plan_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_plan->'operation_id') is distinct from 'string'
    or nullif(btrim(p_plan->>'operation_id'), '') is null
    or octet_length(p_plan->>'operation_id') > 512
    or jsonb_typeof(p_plan->'target_visibility') is distinct from 'string'
    or p_plan->>'target_visibility' <> 'owner_draft'
    or jsonb_typeof(p_plan->'batches') is distinct from 'array'
    or jsonb_array_length(p_plan->'batches') <> 2 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_REQUEST',
      'status', 400,
      'message', 'Plan identity, owner_draft visibility, and exactly two batches are required'
    );
  end if;

  v_plan_sha256 := p_plan->>'plan_sha256';
  v_operation_id := btrim(p_plan->>'operation_id');
  v_target_visibility := p_plan->>'target_visibility';
  v_batches := p_plan->'batches';
  v_time_batch := v_batches->0;
  v_length_time_batch := v_batches->1;

  -- Requiring a stable order makes the whole-plan request hash deterministic
  -- and prevents callers from substituting two copies of one dimension.
  if jsonb_typeof(v_time_batch) is distinct from 'object'
    or jsonb_typeof(v_length_time_batch) is distinct from 'object'
    or v_time_batch->>'dimension' is distinct from 'time'
    or v_length_time_batch->>'dimension' is distinct from 'length_time' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_BATCH_SET',
      'status', 400,
      'message', 'batches must contain time followed by length_time exactly once'
    );
  end if;

  -- Validate enough of both batch envelopes to perform a safe, non-locking
  -- ownership preflight.  The internal executor repeats the complete semantic,
  -- payload, closure, hash, and locked-row validation after the broad locks.
  for v_batch, v_expected_dimension, v_expected_factor, v_expected_action_count in
    select *
    from (values
      (v_time_batch, 'time'::text, '0.00011415525114155251'::text, 25),
      (v_length_time_batch, 'length_time'::text, '1000'::text, 27)
    ) as expected(batch, dimension, factor, action_count)
  loop
    if not (v_batch ?& array[
        'schema_version',
        'plan_sha256',
        'operation_id',
        'batch_id',
        'dimension',
        'factor',
        'target_visibility',
        'target',
        'actions'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_batch) as batch_key(key)
        where batch_key.key <> all (array[
          'schema_version',
          'plan_sha256',
          'operation_id',
          'batch_id',
          'dimension',
          'factor',
          'target_visibility',
          'target',
          'actions'
        ])
      )
      or jsonb_typeof(v_batch->'schema_version') is distinct from 'string'
      or v_batch->>'schema_version' <> v_batch_schema_version
      or jsonb_typeof(v_batch->'plan_sha256') is distinct from 'string'
      or v_batch->>'plan_sha256' is distinct from v_plan_sha256
      or jsonb_typeof(v_batch->'operation_id') is distinct from 'string'
      or btrim(v_batch->>'operation_id') is distinct from v_operation_id
      or jsonb_typeof(v_batch->'batch_id') is distinct from 'string'
      or nullif(btrim(v_batch->>'batch_id'), '') is null
      or octet_length(v_batch->>'batch_id') > 512
      or jsonb_typeof(v_batch->'dimension') is distinct from 'string'
      or v_batch->>'dimension' is distinct from v_expected_dimension
      or jsonb_typeof(v_batch->'factor') is distinct from 'string'
      or v_batch->>'factor' is distinct from v_expected_factor
      or jsonb_typeof(v_batch->'target_visibility') is distinct from 'string'
      or v_batch->>'target_visibility' is distinct from v_target_visibility
      or jsonb_typeof(v_batch->'target') is distinct from 'object'
      or not ((v_batch->'target') ?& array[
        'flowproperty',
        'unitgroup',
        'source_unitgroup'
      ])
      or exists (
        select 1
        from jsonb_object_keys(v_batch->'target') as target_key(key)
        where target_key.key <> all (array[
          'flowproperty',
          'unitgroup',
          'source_unitgroup'
        ])
      )
      or jsonb_typeof(v_batch->'actions') is distinct from 'array'
      or jsonb_array_length(v_batch->'actions') <> v_expected_action_count
      or exists (
        select 1
        from jsonb_array_elements(v_batch->'actions') as action_item(value)
        where jsonb_typeof(action_item.value) is distinct from 'object'
          or jsonb_typeof(action_item.value->'table') is distinct from 'string'
          or action_item.value->>'table' not in (
            'flowproperties', 'flows', 'processes'
          )
          or jsonb_typeof(action_item.value->'id') is distinct from 'string'
          or (action_item.value->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or jsonb_typeof(action_item.value->'version') is distinct from 'string'
          or (action_item.value->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
          or jsonb_typeof(action_item.value->'expected_state_code') is distinct from 'number'
          or action_item.value->>'expected_state_code' <> '0'
      ) then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_INVALID_BATCH',
        'status', 400,
        'message', 'Both batch envelopes must match the frozen full-plan contract'
      );
    end if;

    if exists (
      select 1
      from (values
        (v_batch#>'{target,flowproperty}'),
        (v_batch#>'{target,unitgroup}'),
        (v_batch#>'{target,source_unitgroup}')
      ) as support_item(value)
      where jsonb_typeof(support_item.value) is distinct from 'object'
        or jsonb_typeof(support_item.value->'id') is distinct from 'string'
        or (support_item.value->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(support_item.value->'version') is distinct from 'string'
        or (support_item.value->>'version') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    ) then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_INVALID_BATCH',
        'status', 400,
        'message', 'Both batch envelopes must carry valid support row keys'
      );
    end if;

    -- This preflight intentionally happens before either dimension can reach
    -- the internal executor's SHARE ROW EXCLUSIVE locks.  It is non-locking,
    -- uniform, and non-disclosing; the executor rechecks after taking locks.
    select
      exists (
        select 1
        from public.flowproperties as target_fp
        where target_fp.id = (v_batch#>>'{target,flowproperty,id}')::uuid
          and target_fp.version::text = v_batch#>>'{target,flowproperty,version}'
          and target_fp.user_id = v_actor
          and target_fp.state_code = 0
      )
      and exists (
        select 1
        from public.unitgroups as target_ug
        where target_ug.id = (v_batch#>>'{target,unitgroup,id}')::uuid
          and target_ug.version::text = v_batch#>>'{target,unitgroup,version}'
          and target_ug.user_id = v_actor
          and target_ug.state_code = 0
      )
      and exists (
        select 1
        from public.unitgroups as source_ug
        where source_ug.id = (v_batch#>>'{target,source_unitgroup,id}')::uuid
          and source_ug.version::text = v_batch#>>'{target,source_unitgroup,version}'
          and source_ug.user_id = v_actor
          and source_ug.state_code = 0
      )
    into v_support_owned;

    select count(*)
    into v_owned_action_count
    from jsonb_array_elements(v_batch->'actions') as action_item(value)
    where (
      action_item.value->>'table' = 'flowproperties'
      and exists (
        select 1
        from public.flowproperties as dataset_row
        where dataset_row.id = (action_item.value->>'id')::uuid
          and dataset_row.version::text = action_item.value->>'version'
          and dataset_row.user_id = v_actor
          and dataset_row.state_code = 0
      )
    ) or (
      action_item.value->>'table' = 'flows'
      and exists (
        select 1
        from public.flows as dataset_row
        where dataset_row.id = (action_item.value->>'id')::uuid
          and dataset_row.version::text = action_item.value->>'version'
          and dataset_row.user_id = v_actor
          and dataset_row.state_code = 0
      )
    ) or (
      action_item.value->>'table' = 'processes'
      and exists (
        select 1
        from public.processes as dataset_row
        where dataset_row.id = (action_item.value->>'id')::uuid
          and dataset_row.version::text = action_item.value->>'version'
          and dataset_row.user_id = v_actor
          and dataset_row.state_code = 0
      )
    );

    if not v_support_owned
      or v_owned_action_count <> v_expected_action_count then
      return jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_SCOPE_MISMATCH',
        'status', 409,
        'message', 'Full-plan owner-draft scope does not match the authenticated actor'
      );
    end if;
  end loop;

  if v_time_batch->>'batch_id' = v_length_time_batch->>'batch_id' then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_INVALID_BATCH_SET',
      'status', 400,
      'message', 'Batch IDs must be distinct'
    );
  end if;

  select count(distinct (
    action_item.value->>'table',
    action_item.value->>'id',
    action_item.value->>'version'
  ))
  into v_action_distinct_count
  from jsonb_array_elements(v_batches) as batch_item(value)
  cross join lateral jsonb_array_elements(
    batch_item.value->'actions'
  ) as action_item(value);

  if v_action_distinct_count <> 52
    or (v_time_batch#>>'{target,flowproperty,id}') =
      (v_length_time_batch#>>'{target,flowproperty,id}')
    or (v_time_batch#>>'{target,flowproperty,id}') in (
      select action_item.value->>'id'
      from jsonb_array_elements(v_batches) as batch_item(value)
      cross join lateral jsonb_array_elements(
        batch_item.value->'actions'
      ) as action_item(value)
      where action_item.value->>'table' = 'flowproperties'
    )
    or (v_length_time_batch#>>'{target,flowproperty,id}') in (
      select action_item.value->>'id'
      from jsonb_array_elements(v_batches) as batch_item(value)
      cross join lateral jsonb_array_elements(
        batch_item.value->'actions'
      ) as action_item(value)
      where action_item.value->>'table' = 'flowproperties'
    )
    or (
      select count(distinct support_ug.id)
      from (values
        (v_time_batch#>>'{target,unitgroup,id}'),
        (v_time_batch#>>'{target,source_unitgroup,id}'),
        (v_length_time_batch#>>'{target,unitgroup,id}'),
        (v_length_time_batch#>>'{target,source_unitgroup,id}')
      ) as support_ug(id)
    ) <> 4 then
    return jsonb_build_object(
      'ok', false,
      'code', 'ALIAS_PLAN_OVERLAPPING_BATCHES',
      'status', 400,
      'message', 'The two frozen dimensions must use 52 distinct action rows and disjoint support rows'
    );
  end if;

  v_time_batch_request_sha256 := encode(
    extensions.digest(convert_to(v_time_batch::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_length_time_batch_request_sha256 := encode(
    extensions.digest(convert_to(v_length_time_batch::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_plan_request_sha256 := encode(
    extensions.digest(convert_to(p_plan::text, 'UTF8'), 'sha256'),
    'hex'
  );

  -- PL/pgSQL exception blocks are subtransactions.  Any returned batch error
  -- or unexpected second-dimension exception is raised inside this block,
  -- caught outside it, and therefore rolls back the first dimension's rows and
  -- audits before a structured plan failure is returned.
  begin
    v_failed_dimension := 'time';
    v_time_result := private.cmd_dataset_alias_batch_guarded(v_time_batch);
    if coalesce((v_time_result->>'ok')::boolean, false) is not true then
      v_failure_result := v_time_result;
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias time batch rejected';
    end if;

    v_failed_dimension := 'length_time';
    v_length_time_result :=
      private.cmd_dataset_alias_batch_guarded(v_length_time_batch);
    if coalesce((v_length_time_result->>'ok')::boolean, false) is not true then
      v_failure_result := v_length_time_result;
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias length_time batch rejected';
    end if;

    if v_time_result->>'dimension' is distinct from 'time'
      or v_time_result->>'target_visibility' is distinct from 'owner_draft'
      or v_time_result->>'batch_request_sha256'
        is distinct from v_time_batch_request_sha256
      or v_time_result->>'row_count' is distinct from '25'
      or v_time_result->>'exchange_count' is distinct from '20'
      or (v_time_result->>'summary_audit_id') !~ '^[0-9]+$'
      or jsonb_typeof(v_time_result->'audit') is distinct from 'array'
      or jsonb_array_length(v_time_result->'audit') <> 25
      or v_length_time_result->>'dimension' is distinct from 'length_time'
      or v_length_time_result->>'target_visibility' is distinct from 'owner_draft'
      or v_length_time_result->>'batch_request_sha256'
        is distinct from v_length_time_batch_request_sha256
      or v_length_time_result->>'row_count' is distinct from '27'
      or v_length_time_result->>'exchange_count' is distinct from '39'
      or (v_length_time_result->>'summary_audit_id') !~ '^[0-9]+$'
      or jsonb_typeof(v_length_time_result->'audit') is distinct from 'array'
      or jsonb_array_length(v_length_time_result->'audit') <> 27 then
      v_failure_result := jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_BATCH_PROOF_MISMATCH',
        'status', 409,
        'message', 'A dimension result did not prove the exact frozen batch'
      );
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias dimension proof mismatch';
    end if;

    v_time_replay := (v_time_result->>'idempotent_replay')::boolean;
    v_length_time_replay :=
      (v_length_time_result->>'idempotent_replay')::boolean;
    v_time_summary_audit_id :=
      (v_time_result->>'summary_audit_id')::bigint;
    v_length_time_summary_audit_id :=
      (v_length_time_result->>'summary_audit_id')::bigint;

    if v_time_replay is distinct from v_length_time_replay then
      v_failure_result := jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_PARTIAL_STATE',
        'status', 409,
        'message', 'The two dimensions are split between fresh and replay states'
      );
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias plan partial state';
    end if;

    select count(*)
    into v_batch_proof_count
    from private.command_audit_log as batch_audit
    where batch_audit.id in (
        v_time_summary_audit_id,
        v_length_time_summary_audit_id
      )
      and batch_audit.command = 'cmd_dataset_alias_batch_guarded'
      and batch_audit.actor_user_id = v_actor
      and batch_audit.target_table is null
      and batch_audit.payload->>'record_type' = 'batch_summary'
      and (
        (
          batch_audit.id = v_time_summary_audit_id
          and batch_audit.payload->>'dimension' = 'time'
          and batch_audit.payload->>'batch_request_sha256' =
            v_time_batch_request_sha256
        ) or (
          batch_audit.id = v_length_time_summary_audit_id
          and batch_audit.payload->>'dimension' = 'length_time'
          and batch_audit.payload->>'batch_request_sha256' =
            v_length_time_batch_request_sha256
        )
      );

    if v_batch_proof_count <> 2 then
      v_failure_result := jsonb_build_object(
        'ok', false,
        'code', 'ALIAS_PLAN_BATCH_PROOF_MISMATCH',
        'status', 409,
        'message', 'Dimension audit proofs do not match the exact full plan'
      );
      raise exception using
        errcode = 'P0001',
        message = 'Guarded alias dimension audits mismatch';
    end if;

    select count(*)
    into v_existing_plan_audit_count
    from private.command_audit_log as plan_audit
    where plan_audit.command = v_command
      and plan_audit.actor_user_id = v_actor
      and plan_audit.payload->>'plan_request_sha256' = v_plan_request_sha256;

    v_plan_summary_audit_id := null;
    select plan_audit.id
    into v_plan_summary_audit_id
    from private.command_audit_log as plan_audit
    where plan_audit.command = v_command
      and plan_audit.actor_user_id = v_actor
      and plan_audit.target_table is null
      and plan_audit.target_id is null
      and plan_audit.target_version is null
      and plan_audit.payload->>'record_type' = 'plan_summary'
      and plan_audit.payload->>'schema_version' = v_schema_version
      and plan_audit.payload->>'plan_sha256' = v_plan_sha256
      and plan_audit.payload->>'operation_id' = v_operation_id
      and plan_audit.payload->>'target_visibility' = v_target_visibility
      and plan_audit.payload->>'plan_request_sha256' = v_plan_request_sha256
      and plan_audit.payload->>'hash_algorithm' = 'postgres-jsonb-text-sha256'
      and plan_audit.payload->>'time_batch_request_sha256' =
        v_time_batch_request_sha256
      and plan_audit.payload->>'length_time_batch_request_sha256' =
        v_length_time_batch_request_sha256
      and plan_audit.payload->>'time_batch_summary_audit_id' =
        v_time_summary_audit_id::text
      and plan_audit.payload->>'length_time_batch_summary_audit_id' =
        v_length_time_summary_audit_id::text
      and plan_audit.payload->>'batch_count' = '2'
      and plan_audit.payload->>'row_count' = '52'
      and plan_audit.payload->>'exchange_count' = '59'
      and plan_audit.payload->>'support_owner_user_id' = v_actor::text
    order by plan_audit.id desc
    limit 1;

    if v_time_replay then
      if v_existing_plan_audit_count <> 1
        or v_plan_summary_audit_id is null then
        v_failure_result := jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_PLAN_REPLAY_UNPROVEN',
          'status', 409,
          'message', 'Committed dimensions have no exact full-plan audit proof'
        );
        raise exception using
          errcode = 'P0001',
          message = 'Guarded alias plan replay unproven';
      end if;
    else
      if v_existing_plan_audit_count <> 0
        or v_plan_summary_audit_id is not null then
        v_failure_result := jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_PLAN_AUDIT_STATE_CONFLICT',
          'status', 409,
          'message', 'A plan audit exists while both dimensions are fresh'
        );
        raise exception using
          errcode = 'P0001',
          message = 'Guarded alias plan audit state conflict';
      end if;

      insert into private.command_audit_log (
        command,
        actor_user_id,
        target_table,
        target_id,
        target_version,
        payload
      )
      values (
        v_command,
        v_actor,
        null,
        null,
        null,
        jsonb_build_object(
          'record_type', 'plan_summary',
          'schema_version', v_schema_version,
          'plan_sha256', v_plan_sha256,
          'operation_id', v_operation_id,
          'target_visibility', v_target_visibility,
          'plan_request_sha256', v_plan_request_sha256,
          'hash_algorithm', 'postgres-jsonb-text-sha256',
          'time_batch_request_sha256', v_time_batch_request_sha256,
          'length_time_batch_request_sha256',
            v_length_time_batch_request_sha256,
          'time_batch_summary_audit_id', v_time_summary_audit_id::text,
          'length_time_batch_summary_audit_id',
            v_length_time_summary_audit_id::text,
          'batch_count', 2,
          'row_count', 52,
          'exchange_count', 59,
          'support_owner_user_id', v_actor
        )
      )
      returning id into v_plan_summary_audit_id;
    end if;
  exception
    when others then
      if v_failure_result is null then
        v_failure_result := jsonb_build_object(
          'ok', false,
          'code', 'ALIAS_PLAN_EXECUTION_FAILED',
          'status', 409,
          'message', 'The full owner-draft plan failed and was rolled back'
        );
      end if;
  end;

  if v_failure_result is not null then
    return v_failure_result || jsonb_build_object(
      'failed_dimension', v_failed_dimension,
      'plan_rolled_back', true
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'command', v_command,
    'schema_version', v_schema_version,
    'plan_sha256', v_plan_sha256,
    'operation_id', v_operation_id,
    'target_visibility', v_target_visibility,
    'plan_request_sha256', v_plan_request_sha256,
    'batch_count', 2,
    'row_count', 52,
    'exchange_count', 59,
    'summary_audit_id', v_plan_summary_audit_id::text,
    'batches', jsonb_build_array(v_time_result, v_length_time_result),
    'idempotent_replay', v_time_replay
  );
end;
$_$;


ALTER FUNCTION private.cmd_dataset_alias_plan_guarded(p_plan jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_alias_plan_guarded(p_plan jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.cmd_dataset_alias_plan_guarded(p_plan jsonb) IS 'Internal owner-draft alias transaction used by the protected one-shot executor and rollback-only preflight. Direct authenticated/service-role API execution is revoked because this legacy function supports idempotent replay.';


--
-- Name: cmd_dataset_publish_issue304_legacy(text, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_dataset_publish_issue304_legacy(p_table text, p_id uuid, p_version text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_current_row jsonb;
  v_owner_id uuid;
  v_state_code integer;
  v_updated_row jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_DATASET_TABLE',
      'status', 400,
      'message', 'Unsupported dataset table'
    );
  end if;

  execute format(
    'select to_jsonb(t) from public.%I as t where t.id = $1 and t.version = $2 for update of t',
    p_table
  )
    into v_current_row
    using p_id, p_version;

  if v_current_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_NOT_FOUND',
      'status', 404,
      'message', 'Dataset not found'
    );
  end if;

  v_owner_id := nullif(v_current_row->>'user_id', '')::uuid;
  v_state_code := coalesce((v_current_row->>'state_code')::integer, 0);

  if v_owner_id is distinct from v_actor then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATASET_OWNER_REQUIRED',
      'status', 403,
      'message', 'Only the dataset owner can publish the dataset'
    );
  end if;

  if v_state_code >= 100 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_ALREADY_PUBLISHED',
      'status', 403,
      'message', 'Dataset is already published',
      'details', jsonb_build_object(
        'state_code', v_state_code
      )
    );
  end if;

  if v_state_code >= 20 then
    return jsonb_build_object(
      'ok', false,
      'code', 'DATA_UNDER_REVIEW',
      'status', 403,
      'message', 'Data is under review and cannot be published directly',
      'details', jsonb_build_object(
        'state_code', 20,
        'review_state_code', v_state_code
      )
    );
  end if;

  execute format(
    'update public.%I as t
        set state_code = 100,
            modified_at = now()
      where t.id = $1
        and t.version = $2
    returning to_jsonb(t)',
    p_table
  )
    into v_updated_row
    using p_id, p_version;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_dataset_publish',
    v_actor,
    p_table,
    p_id,
    p_version,
    coalesce(p_audit, '{}'::jsonb)
  );

  return jsonb_build_object(
    'ok', true,
    'data', v_updated_row
  );
end;
$_$;


ALTER FUNCTION private.cmd_dataset_publish_issue304_legacy(p_table text, p_id uuid, p_version text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_dataset_semantic_backfill(text, integer, uuid, text, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_dataset_semantic_backfill(p_table text, p_batch_size integer DEFAULT 100, p_after_id uuid DEFAULT NULL::uuid, p_after_version text DEFAULT NULL::text, p_force_extraction boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_table text := lower(btrim(coalesce(p_table, '')));
  v_entity_kind text;
  v_content_function text;
  v_batch_size integer := least(greatest(coalesce(p_batch_size, 100), 1), 500);
  v_row_id uuid;
  v_row_version text;
  v_needs_extraction boolean;
  v_needs_embedding boolean;
  v_scanned_count integer := 0;
  v_extraction_enqueued integer := 0;
  v_embedding_enqueued integer := 0;
  v_already_queued integer := 0;
  v_last_id uuid;
  v_last_version text;
  v_job_exists boolean;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false,
      'code', 'SERVICE_ROLE_REQUIRED',
      'status', 403,
      'message', 'Service role is required'
    );
  end if;

  v_entity_kind := case v_table
    when 'contacts' then 'contact'
    when 'flowproperties' then 'flowproperty'
    when 'sources' then 'source'
    when 'unitgroups' then 'unitgroup'
    else null
  end;

  if v_entity_kind is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'UNSUPPORTED_DATASET_TABLE',
      'status', 400,
      'message', format('Unsupported semantic backfill table: %s', coalesce(p_table, '<null>'))
    );
  end if;

  v_content_function := v_table || '_embedding_ft_input';

  for v_row_id, v_row_version, v_needs_extraction, v_needs_embedding in execute format(
    $sql$
      select
        dataset.id,
        btrim(dataset.version::text) as version,
        dataset.extracted_md is null or $4 as needs_extraction,
        dataset.embedding_ft is null as needs_embedding
      from public.%I dataset
      where dataset.json is not null
        and nullif(btrim(dataset.version::text), '') is not null
        and ($4 or dataset.extracted_md is null or dataset.embedding_ft is null)
        and (
          $1 is null
          or (dataset.id, btrim(dataset.version::text)) > ($1, coalesce($2, ''))
        )
      order by dataset.id, btrim(dataset.version::text)
      limit $3
    $sql$,
    v_table
  ) using p_after_id, p_after_version, v_batch_size, coalesce(p_force_extraction, false)
  loop
    v_scanned_count := v_scanned_count + 1;
    v_last_id := v_row_id;
    v_last_version := v_row_version;

    if v_needs_extraction then
      select exists (
        select 1
        from pgmq.q_dataset_extraction_jobs queued
        where queued.message->>'schema' = 'public'
          and queued.message->>'table' = v_table
          and queued.message->>'id' = v_row_id::text
          and queued.message->>'version' = v_row_version
          and queued.message->>'extraction_kind' = 'extracted_md'
      ) into v_job_exists;

      if v_job_exists then
        v_already_queued := v_already_queued + 1;
      else
        perform pgmq.send(
          queue_name => 'dataset_extraction_jobs',
          msg => jsonb_build_object(
            'schema', 'public',
            'table', v_table,
            'id', v_row_id,
            'version', v_row_version,
            'entity_kind', v_entity_kind,
            'extraction_kind', 'extracted_md',
            'created_at', clock_timestamp(),
            'backfill', true
          )
        );
        v_extraction_enqueued := v_extraction_enqueued + 1;
      end if;
    elsif v_needs_embedding then
      select exists (
        select 1
        from pgmq.q_embedding_jobs queued
        where queued.message->>'schema' = 'public'
          and queued.message->>'table' = v_table
          and queued.message->>'id' = v_row_id::text
          and queued.message->>'version' = v_row_version
          and queued.message->>'embeddingColumn' = 'embedding_ft'
          and queued.message->>'edgeFunction' = 'embedding_ft'
      ) or exists (
        select 1
        from util.pending_embedding_jobs pending
        where pending.schema_name = 'public'
          and pending.table_name = v_table
          and pending.record_id = v_row_id::text
          and pending.record_version = v_row_version
          and pending.embedding_column = 'embedding_ft'
          and pending.edge_function = 'embedding_ft'
          and pending.status in ('pending', 'enqueued')
      ) into v_job_exists;

      if v_job_exists then
        v_already_queued := v_already_queued + 1;
      else
        perform pgmq.send(
          queue_name => 'embedding_jobs',
          msg => jsonb_build_object(
            'id', v_row_id,
            'version', v_row_version,
            'schema', 'public',
            'table', v_table,
            'contentFunction', v_content_function,
            'embeddingColumn', 'embedding_ft',
            'edgeFunction', 'embedding_ft',
            'backfill', true
          )
        );
        v_embedding_enqueued := v_embedding_enqueued + 1;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'table', v_table,
    'scanned_count', v_scanned_count,
    'extraction_enqueued_count', v_extraction_enqueued,
    'embedding_enqueued_count', v_embedding_enqueued,
    'already_queued_count', v_already_queued,
    'last_id', v_last_id,
    'last_version', v_last_version,
    'has_more', v_scanned_count = v_batch_size
  );
end;
$_$;


ALTER FUNCTION private.cmd_dataset_semantic_backfill(p_table text, p_batch_size integer, p_after_id uuid, p_after_version text, p_force_extraction boolean) OWNER TO postgres;

--
-- Name: FUNCTION cmd_dataset_semantic_backfill(p_table text, p_batch_size integer, p_after_id uuid, p_after_version text, p_force_extraction boolean); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.cmd_dataset_semantic_backfill(p_table text, p_batch_size integer, p_after_id uuid, p_after_version text, p_force_extraction boolean) IS 'Service-only bounded cursor RPC that enqueues missing foundation-dataset derivatives and skips rows without a stable nonblank id/version worker identity.';


--
-- Name: cmd_lca_release_artifacts_finalize_service(uuid, text, jsonb, text, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lca_release_artifacts_finalize_service(p_release_run_id uuid, p_publish_plan_hash text, p_release_manifest jsonb, p_release_manifest_hash text, p_artifacts jsonb, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_run private.lca_release_runs%rowtype;
  v_invalid_count integer;
  v_dataset_count integer;
  v_artifact_count integer;
begin
  if not private.lca_release_is_service_request() then
    return private.lca_release_error('service_role_required', 403, 'Internal service identity is required to finalize artifacts');
  end if;
  if jsonb_typeof(coalesce(p_release_manifest, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_artifacts, 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_audit, 'null'::jsonb)) <> 'object' then
    return private.lca_release_error('invalid_payload', 400, 'Release manifest, artifacts, and audit have invalid JSON shapes');
  end if;
  if coalesce(p_publish_plan_hash, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_release_manifest_hash, '') !~ '^[0-9a-f]{64}$' then
    return private.lca_release_error('invalid_hash', 400, 'Plan and release manifest hashes must be lowercase SHA-256 values');
  end if;

  select * into v_run
  from private.lca_release_runs
  where id = p_release_run_id
  for update;

  if v_run.id is null then
    return private.lca_release_error('release_run_not_found', 404, 'Release run not found');
  end if;
  if v_run.publish_plan_hash <> p_publish_plan_hash then
    return private.lca_release_error('publish_plan_hash_mismatch', 409, 'Artifact finalize plan hash does not match the prepared run');
  end if;
  if v_run.status <> 'prepared' then
    if v_run.status in ('ready_for_approval', 'approved', 'published', 'readback_verified')
       and v_run.release_manifest_hash = p_release_manifest_hash then
      with existing as (
        select profile_id, artifact_format, storage_bucket, object_key, sha256, byte_size, media_type
        from private.lca_release_artifacts
        where release_run_id = v_run.id
      ),
      supplied as (
        select
          artifact.value->>'profileId' as profile_id,
          artifact.value->>'format' as artifact_format,
          artifact.value->>'storageBucket' as storage_bucket,
          artifact.value->>'objectKey' as object_key,
          artifact.value->>'sha256' as sha256,
          (artifact.value->>'byteSize')::bigint as byte_size,
          artifact.value->>'mediaType' as media_type
        from jsonb_array_elements(p_artifacts) as artifact(value)
      )
      select count(*) into v_invalid_count
      from existing
      full join supplied using (profile_id, artifact_format)
      where existing.profile_id is null
         or supplied.profile_id is null
         or existing.storage_bucket is distinct from supplied.storage_bucket
         or existing.object_key is distinct from supplied.object_key
         or existing.sha256 is distinct from supplied.sha256
         or existing.byte_size is distinct from supplied.byte_size
         or existing.media_type is distinct from supplied.media_type;

      if v_invalid_count = 0 and jsonb_array_length(p_artifacts) = 4 then
        return jsonb_build_object(
          'ok', true,
          'reused', true,
          'data', jsonb_build_object(
            'releaseRunId', v_run.id,
            'status', v_run.status,
            'releaseManifestHash', v_run.release_manifest_hash
          )
        );
      end if;
      return private.lca_release_error('release_finalize_conflict', 409, 'Finalize retry artifact refs differ from durable content');
    end if;
    return private.lca_release_error('release_state_conflict', 409, 'Release run is not in prepared state');
  end if;

  if p_release_manifest->>'schemaVersion' is distinct from 'tiangong.release-manifest.v1'
     or p_release_manifest->>'releaseRunId' is distinct from v_run.id::text
     or p_release_manifest->>'releaseVersion' is distinct from v_run.release_version
     or p_release_manifest->>'profileLockHash' is distinct from v_run.profile_lock_hash
     or p_release_manifest->>'publishPlanHash' is distinct from v_run.publish_plan_hash
     or p_release_manifest->>'artifactSetHash' is distinct from v_run.artifact_set_hash
     or p_release_manifest->'scope'->>'coverageMode' is distinct from 'global_eligible'
     or p_release_manifest->'scope'->>'selectionManifestHash' is distinct from v_run.selection_manifest_hash
     or p_release_manifest->'calculationBundle'->>'bundleContentHash' is distinct from v_run.calculation_bundle_hash then
    return private.lca_release_error('release_manifest_mismatch', 409, 'Release manifest does not match the prepared run and exact hashes');
  end if;
  if jsonb_typeof(p_release_manifest->'datasets') is distinct from 'array'
     or jsonb_array_length(p_release_manifest->'datasets') = 0
     or jsonb_typeof(p_release_manifest->'packages') is distinct from 'array'
     or jsonb_array_length(p_release_manifest->'packages') <> 4
     or jsonb_array_length(p_artifacts) <> 4 then
    return private.lca_release_error('release_manifest_incomplete', 400, 'Release manifest requires datasets and four uploaded package artifacts');
  end if;
  if coalesce(
    p_release_manifest->'validation'->'tidas'->>'status' = 'passed'
    and p_release_manifest->'validation'->'ilcd'->>'status' = 'passed'
    and p_release_manifest->'validation'->'semanticRoundtrip'->>'status' = 'passed'
    and p_release_manifest->'validation'->'referenceClosure'->>'status' = 'passed'
    and p_release_manifest->'validation'->'numericParity'->>'status' = 'passed',
    false
  ) is not true then
    return private.lca_release_error('validation_not_passed', 400, 'All release validation gates must pass before artifact finalization');
  end if;

  with expected as (
    select
      package.value->>'profileId' as profile_id,
      package.value->>'format' as artifact_format,
      package.value->>'closureHash' as closure_hash,
      package.value->'artifact'->>'sha256' as sha256,
      (package.value->'artifact'->>'byteSize')::bigint as byte_size,
      package.value->'artifact'->>'mediaType' as media_type
    from jsonb_array_elements(p_release_manifest->'packages') as package(value)
  ),
  uploaded as (
    select
      artifact.value->>'profileId' as profile_id,
      artifact.value->>'format' as artifact_format,
      artifact.value->>'storageBucket' as storage_bucket,
      artifact.value->>'objectKey' as object_key,
      artifact.value->>'sha256' as sha256,
      (artifact.value->>'byteSize')::bigint as byte_size,
      artifact.value->>'mediaType' as media_type
    from jsonb_array_elements(p_artifacts) as artifact(value)
  )
  select count(*) into v_invalid_count
  from expected
  full join uploaded using (profile_id, artifact_format)
  where expected.profile_id is null
     or uploaded.profile_id is null
     or expected.profile_id not in (
          'unit-process-full-closure.v1',
          'standalone-lifecyclemodel-result-full-closure.v1'
        )
     or expected.artifact_format not in ('tidas', 'ilcd')
     or expected.sha256 !~ '^[0-9a-f]{64}$'
     or expected.closure_hash !~ '^[0-9a-f]{64}$'
     or expected.sha256 is distinct from uploaded.sha256
     or expected.byte_size is distinct from uploaded.byte_size
     or expected.media_type is distinct from uploaded.media_type
     or coalesce(length(trim(uploaded.storage_bucket)), 0) = 0
     or coalesce(length(trim(uploaded.object_key)), 0) = 0;

  if v_invalid_count <> 0 then
    return private.lca_release_error('artifact_set_mismatch', 409, 'Uploaded artifact refs do not exactly match the release manifest');
  end if;

  with dataset_rows as (
    select dataset.value
    from jsonb_array_elements(p_release_manifest->'datasets') as dataset(value)
  )
  select count(*) into v_invalid_count
  from dataset_rows
  where value->>'datasetType' not in (
          'process', 'lifecyclemodel', 'flow', 'flowproperty', 'unitgroup',
          'lciamethod', 'source', 'contact'
        )
     or value->>'role' not in ('unit_process', 'result_process', 'lifecycle_model', 'support')
     or (value->>'role' in ('unit_process', 'result_process') and value->>'datasetType' <> 'process')
     or (value->>'role' = 'lifecycle_model' and value->>'datasetType' <> 'lifecyclemodel')
     or value->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
     or (
       value->>'role' in ('unit_process', 'result_process', 'lifecycle_model')
       and (
         jsonb_typeof(value->'sourceProcess') is distinct from 'object'
         or coalesce(value->'sourceProcess'->>'id', '') = ''
         or value->'sourceProcess'->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
       )
     )
     or (
       value->>'role' = 'unit_process'
       and (
         value->'sourceProcess'->>'id' is distinct from value->>'uuid'
         or value->'sourceProcess'->>'version' is distinct from value->>'version'
       )
     )
     or (
       value->>'role' = 'support'
       and value ? 'sourceProcess'
     )
     or value->>'versionSignificantHash' !~ '^[0-9a-f]{64}$'
     or value->>'semanticHash' !~ '^[0-9a-f]{64}$'
     or value->>'canonicalContentHash' !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(value->'artifact') is distinct from 'object';

  if v_invalid_count <> 0 then
    return private.lca_release_error('dataset_index_invalid', 400, 'Release dataset index contains invalid identities, versions, or hashes');
  end if;

  with process_datasets as (
    select
      dataset.value->>'role' as dataset_role,
      dataset.value->'sourceProcess'->>'id' as source_process_uuid,
      dataset.value->'sourceProcess'->>'version' as source_process_version
    from jsonb_array_elements(p_release_manifest->'datasets') as dataset(value)
    where dataset.value->>'role' in ('unit_process', 'lifecycle_model', 'result_process')
  ),
  invalid_source_sets as (
    select source_process_uuid, source_process_version
    from process_datasets
    group by source_process_uuid, source_process_version
    having count(*) filter (where dataset_role = 'unit_process') <> 1
       or count(*) filter (where dataset_role = 'lifecycle_model') <> 1
       or count(*) filter (where dataset_role = 'result_process') <> 1
  )
  select count(*) into v_invalid_count
  from invalid_source_sets;

  if v_invalid_count <> 0 then
    return private.lca_release_error(
      'dataset_source_process_set_invalid', 400,
      'Each source Process requires exactly one Unit Process, LifecycleModel, and Result Process identity'
    );
  end if;

  insert into private.lca_release_dataset_versions (
    release_run_id, dataset_type, dataset_role, dataset_uuid, dataset_version,
    source_process_uuid, source_process_version,
    version_significant_hash, semantic_hash, canonical_content_hash, artifact_ref
  )
  select
    v_run.id,
    dataset.value->>'datasetType',
    dataset.value->>'role',
    (dataset.value->>'uuid')::uuid,
    dataset.value->>'version',
    (dataset.value->'sourceProcess'->>'id')::uuid,
    dataset.value->'sourceProcess'->>'version',
    dataset.value->>'versionSignificantHash',
    dataset.value->>'semanticHash',
    dataset.value->>'canonicalContentHash',
    dataset.value->'artifact'
  from jsonb_array_elements(p_release_manifest->'datasets') as dataset(value);
  get diagnostics v_dataset_count = row_count;

  insert into private.lca_release_artifacts (
    release_run_id, profile_id, artifact_format, storage_bucket, object_key,
    sha256, byte_size, media_type, closure_hash, verified_at
  )
  select
    v_run.id,
    package.value->>'profileId',
    package.value->>'format',
    artifact.value->>'storageBucket',
    artifact.value->>'objectKey',
    artifact.value->>'sha256',
    (artifact.value->>'byteSize')::bigint,
    artifact.value->>'mediaType',
    package.value->>'closureHash',
    now()
  from jsonb_array_elements(p_release_manifest->'packages') as package(value)
  join jsonb_array_elements(p_artifacts) as artifact(value)
    on artifact.value->>'profileId' = package.value->>'profileId'
   and artifact.value->>'format' = package.value->>'format';
  get diagnostics v_artifact_count = row_count;

  update private.lca_release_runs
  set release_manifest = p_release_manifest,
      release_manifest_hash = p_release_manifest_hash,
      status = 'ready_for_approval',
      artifacts_finalized_at = now(),
      updated_at = now()
  where id = v_run.id;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'cmd_lca_release_artifacts_finalize_service', v_run.created_by,
    'lca_release_runs', v_run.id, v_run.release_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'serviceCallback', true,
      'publishPlanHash', p_publish_plan_hash,
      'releaseManifestHash', p_release_manifest_hash,
      'artifactSetHash', v_run.artifact_set_hash,
      'artifactCount', v_artifact_count,
      'datasetCount', v_dataset_count
    )
  );

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', jsonb_build_object(
      'releaseRunId', v_run.id,
      'status', 'ready_for_approval',
      'releaseManifestHash', p_release_manifest_hash,
      'artifactCount', v_artifact_count,
      'datasetCount', v_dataset_count
    )
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return private.lca_release_error('release_manifest_invalid', 400, 'Release manifest contains invalid UUID or byte-size values');
  when unique_violation then
    return private.lca_release_error('release_artifact_conflict', 409, 'Release dataset or artifact identity already exists with conflicting content');
end;
$_$;


ALTER FUNCTION private.cmd_lca_release_artifacts_finalize_service(p_release_run_id uuid, p_publish_plan_hash text, p_release_manifest jsonb, p_release_manifest_hash text, p_artifacts jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_legacy(text, jsonb, text, text, jsonb, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lcia_result_build_request_legacy(p_name text, p_processes jsonb DEFAULT NULL::jsonb, p_coverage_mode text DEFAULT 'global_eligible'::text, p_default_impact_category text DEFAULT NULL::text, p_lcia_method_set jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_coverage_mode text := lower(trim(coalesce(p_coverage_mode, 'global_eligible')));
  v_build_id uuid;
  v_idempotency_key text;
  v_current_manifest jsonb;
  v_input_manifest jsonb;
  v_input_manifest_hash text;
  v_eligible_input_count integer;
  v_included_input_count integer;
  v_invalid_count integer := 0;
  v_duplicate_count integer := 0;
  v_request_hash text;
  v_worker_payload jsonb;
  v_worker_job jsonb;
begin
  if v_actor is null then
    return api.lcia_result_error('auth_required', 401, 'Authentication required');
  end if;

  if not api.lcia_result_is_manager() then
    return api.lcia_result_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;

  if v_coverage_mode not in ('subset', 'global_eligible') then
    return api.lcia_result_error('invalid_coverage_mode', 400, 'coverage_mode must be subset or global_eligible');
  end if;

  if v_coverage_mode = 'global_eligible'
     and p_processes is not null
     and jsonb_array_length(p_processes) > 0 then
    return api.lcia_result_error('invalid_coverage_mode', 400, 'global_eligible builds are resolved from the current published input predicate');
  end if;

  if jsonb_typeof(coalesce(p_lcia_method_set, '[]'::jsonb)) <> 'array' then
    return api.lcia_result_error('invalid_lcia_method_set', 400, 'lcia_method_set must be a JSON array');
  end if;

  if p_processes is not null and jsonb_typeof(p_processes) <> 'array' then
    return api.lcia_result_error('invalid_process_selection', 400, 'process selection must be a JSON array');
  end if;

  v_current_manifest := api.lcia_result_current_eligible_manifest();
  v_eligible_input_count := (v_current_manifest->>'eligibleInputCount')::integer;

  if v_coverage_mode = 'global_eligible' then
    v_input_manifest := v_current_manifest->'inputManifest';
    v_input_manifest_hash := v_current_manifest->>'inputManifestHash';
    v_included_input_count := v_eligible_input_count;
  else
    with requested as (
      select
        (item.value->>'id')::uuid as process_id,
        coalesce(item.value->>'version', item.value->>'process_version')::character(9) as process_version,
        item.ordinality::integer as ordinal
      from jsonb_array_elements(coalesce(p_processes, '[]'::jsonb)) with ordinality as item(value, ordinality)
    ),
    duplicate_rows as (
      select process_id, process_version, count(*)::integer as duplicate_count
      from requested
      group by process_id, process_version
      having count(*) > 1
    ),
    resolved as (
      select
        r.process_id,
        r.process_version,
        r.ordinal,
        p.state_code
      from requested as r
      left join public.processes as p
        on p.id = r.process_id
       and p.version = r.process_version
    ),
    aggregated as (
      select
        count(*) filter (where state_code between 100 and 199)::integer as included_count,
        count(*) filter (where state_code is null or state_code not between 100 and 199)::integer as invalid_count,
        coalesce((select sum(duplicate_count - 1)::integer from duplicate_rows), 0) as duplicate_count,
        md5(
          coalesce(
            string_agg(
              process_id::text || ':' || process_version,
              ','
              order by process_id, process_version
            ) filter (where state_code between 100 and 199),
            ''
          ) || '|published:100-199:v1'
        ) as manifest_hash,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'id', process_id,
              'version', process_version,
              'stateCode', state_code
            )
            order by ordinal
          ) filter (where state_code between 100 and 199),
          '[]'::jsonb
        ) as selected_processes
      from resolved
    )
    select
      included_count,
      invalid_count,
      duplicate_count,
      manifest_hash,
      jsonb_build_object(
        'predicateVersion', 'published-state-code-100-199:v1',
        'selectionMode', 'manual',
        'processes', selected_processes
      )
    into
      v_included_input_count,
      v_invalid_count,
      v_duplicate_count,
      v_input_manifest_hash,
      v_input_manifest
    from aggregated;

    if v_duplicate_count > 0 then
      return api.lcia_result_error('invalid_process_selection', 400, 'process selection contains duplicate inputs');
    end if;

    if v_invalid_count > 0 then
      return api.lcia_result_error('input_not_eligible', 400, 'All LCIA result package inputs must be published process rows');
    end if;
  end if;

  if coalesce(v_included_input_count, 0) = 0 then
    return api.lcia_result_error('input_empty', 400, 'LCIA result package build requires at least one eligible process');
  end if;

  v_idempotency_key := 'lcia_result.package_build:' || coalesce(
    nullif(trim(coalesce(p_idempotency_key, '')), ''),
    gen_random_uuid()::text
  );

  if nullif(trim(coalesce(p_idempotency_key, '')), '') is not null then
    v_build_id := (
      substr(md5(v_actor::text || ':' || p_idempotency_key), 1, 8) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 9, 4) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 13, 4) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 17, 4) || '-' ||
      substr(md5(v_actor::text || ':' || p_idempotency_key), 21, 12)
    )::uuid;
  else
    v_build_id := gen_random_uuid();
  end if;

  v_request_hash := md5(
    v_input_manifest_hash || '|' ||
    coalesce(p_default_impact_category, '') || '|' ||
    coalesce(p_lcia_method_set::text, '[]')
  );

  v_worker_payload := jsonb_build_object(
    'type', 'lcia_result_package_build',
    'build_id', v_build_id,
    'requested_by', v_actor,
    'name', nullif(trim(coalesce(p_name, '')), ''),
    'coverage_mode', v_coverage_mode,
    'input_status_filter', v_current_manifest->'inputStatusFilter',
    'eligibility_definition', v_current_manifest - 'eligibleInputCount' - 'includedInputCount' - 'inputManifestHash' - 'inputManifest',
    'eligibility_resolved_at', now(),
    'eligible_input_count', v_eligible_input_count,
    'included_input_count', v_included_input_count,
    'input_manifest_hash', v_input_manifest_hash,
    'input_manifest', v_input_manifest,
    'lcia_method_set', coalesce(p_lcia_method_set, '[]'::jsonb),
    'default_impact_category', nullif(trim(coalesce(p_default_impact_category, '')), ''),
    'postprocess_manifest', jsonb_build_object(
      'postprocess_mode', 'skipped',
      'postprocess_reason', 'MVP does not aggregate process results'
    )
  );

  v_worker_job := jsonb_build_object(
    'jobKind', 'lcia_result.package_build',
    'payload', v_worker_payload,
    'payloadSchemaVersion', 'lcia_result.package_build.request.v1',
    'subjectType', 'lcia_result_build',
    'subjectId', v_build_id,
    'subjectVersion', null,
    'requestedBy', v_actor,
    'requesterType', 'operator',
    'idempotencyKey', v_idempotency_key,
    'requestHash', v_request_hash,
    'queueKey', v_build_id,
    'visibility', 'operator'
  );

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    target_version,
    payload
  )
  values (
    'cmd_lcia_result_build_request',
    v_actor,
    'worker_jobs',
    v_build_id,
    null,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'coverageMode', v_coverage_mode,
      'eligibleInputCount', v_eligible_input_count,
      'includedInputCount', v_included_input_count,
      'inputManifestHash', v_input_manifest_hash
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'buildId', v_build_id,
      'coverageMode', v_coverage_mode,
      'eligibleInputCount', v_eligible_input_count,
      'includedInputCount', v_included_input_count,
      'inputManifestHash', v_input_manifest_hash,
      'workerJob', v_worker_job
    ),
    'reused', false
  );
exception
  when invalid_text_representation then
    return api.lcia_result_error('invalid_process_selection', 400, 'process ids and versions must be valid');
end;
$$;


ALTER FUNCTION private.cmd_lcia_result_build_request_legacy(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_v2_envelope(text, jsonb, text, text, jsonb, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lcia_result_build_request_v2_envelope(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); v_check private.lcia_scope_closure_checks%rowtype; v_result jsonb; v_effective jsonb; v_payload jsonb;
begin
  if v_actor is null then return api.lcia_scope_closure_error('auth_required',401,'Authentication required'); end if;
  select * into v_check from private.lcia_scope_closure_checks where id=p_closure_check_id and requested_by=v_actor;
  if v_check.id is null then return api.lcia_scope_closure_error('closure_check_not_found',404,'Closure check not found'); end if;
  if v_check.certificate_status='stale' then return api.lcia_scope_closure_error('closure_check_stale',409,'Closure certificate is stale'); end if;
  if v_check.certificate_status='revoked' then return api.lcia_scope_closure_error('closure_check_revoked',409,'Closure certificate is revoked'); end if;
  if v_check.status<>'passed' or v_check.scan_completeness<>'complete' or v_check.certificate_status<>'valid' or v_check.certificate_hash is null then return api.lcia_scope_closure_error('closure_check_not_usable',409,'A valid complete closure certificate is required'); end if;
  if v_check.requested_scope_hash<>trim(coalesce(p_requested_scope_hash,'')) then return api.lcia_scope_closure_error('closure_check_scope_mismatch',409,'Requested scope does not match the closure certificate'); end if;
  if v_check.policy_fingerprint<>trim(coalesce(p_policy_fingerprint,'')) then return api.lcia_scope_closure_error('closure_check_policy_mismatch',409,'Policy does not match the closure certificate'); end if;
  v_effective:=coalesce(v_check.effective_scope_manifest,v_check.requested_scope_manifest);
  v_result:=private.cmd_lcia_result_build_request_legacy(p_name,v_effective->'processes','subset',p_default_impact_category,v_effective->'lciaMethods',p_idempotency_key,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('closureCheckId',v_check.id,'requestedScopeHash',v_check.requested_scope_hash,'policyFingerprint',v_check.policy_fingerprint,'certificateHash',v_check.certificate_hash));
  v_payload:=(v_result->'data'->'workerJob'->'payload') || jsonb_build_object('coverage_mode',v_effective->>'coverageMode','input_manifest',jsonb_build_object('predicateVersion',v_effective->>'eligibilityPredicateVersion','selectionMode','closure_certificate','processes',v_effective->'processes'),'input_manifest_hash',private.lcia_scope_closure_sha256(jsonb_build_object('processes',v_effective->'processes')),'lcia_method_set',v_effective->'lciaMethods','closure_check_id',v_check.id,'closure_certificate_hash',v_check.certificate_hash,'effective_scope_hash',v_check.effective_scope_hash,'data_snapshot_token',v_check.data_snapshot_token,'snapshot_id',v_check.snapshot_id,'snapshot_hash',v_check.snapshot_hash,'closure_bundle_hash',v_check.closure_bundle_hash,'report_artifact_manifest_hash',v_check.report_artifact_manifest_hash);
  return jsonb_set(v_result,'{data,workerJob,payload}',v_payload,true) || jsonb_build_object('closureCheckId',v_check.id,'effectiveScopeHash',v_check.effective_scope_hash,'certificateHash',v_check.certificate_hash);
end;
$$;


ALTER FUNCTION private.cmd_lcia_result_build_request_v2_envelope(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_build_request_v2_without_expiry(text, jsonb, text, text, jsonb, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lcia_result_build_request_v2_without_expiry(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_check private.lcia_scope_closure_checks%rowtype;
  v_snapshot private.lca_network_snapshots%rowtype;
  v_artifact private.lca_snapshot_artifacts%rowtype;
  v_bundle private.worker_job_artifacts%rowtype;
  v_report private.worker_job_artifacts%rowtype;
  v_result jsonb;
  v_kind private.worker_job_kinds%rowtype;
  v_job private.worker_jobs%rowtype;
  v_build_id uuid;
  v_payload jsonb;
  v_input_manifest jsonb;
  v_report_manifest_hash text;
  v_idempotency_key text;
begin
  if v_actor is null then
    return api.lcia_scope_closure_error('auth_required', 401, 'Authentication required');
  end if;
  select * into v_check
  from private.lcia_scope_closure_checks
  where id = p_closure_check_id and requested_by = v_actor
  for share;
  if v_check.id is null then
    return api.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if v_check.certificate_status = 'stale' then
    return api.lcia_scope_closure_error('closure_check_stale', 409, 'Closure certificate is stale');
  end if;
  if v_check.certificate_status = 'revoked' then
    return api.lcia_scope_closure_error('closure_check_revoked', 409, 'Closure certificate is revoked');
  end if;
  if v_check.status <> 'passed'
     or v_check.scan_completeness <> 'complete'
     or v_check.certificate_status <> 'valid'
     or v_check.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
     or v_check.certificate_hash is null then
    return api.lcia_scope_closure_error('closure_check_not_usable', 409, 'A valid complete numerical snapshot certificate is required');
  end if;
  if v_check.requested_scope_hash <> trim(coalesce(p_requested_scope_hash, '')) then
    return api.lcia_scope_closure_error('closure_check_scope_mismatch', 409, 'Requested scope does not match the closure certificate');
  end if;
  if v_check.policy_fingerprint <> trim(coalesce(p_policy_fingerprint, '')) then
    return api.lcia_scope_closure_error('closure_check_policy_mismatch', 409, 'Policy does not match the closure certificate');
  end if;
  if v_check.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
     and not private.lcia_scope_closure_current_release_matches(v_check.data_snapshot_token) then
    return api.lcia_scope_closure_error('closure_check_stale', 409, 'Closure certificate was created against an earlier public release');
  end if;

  select * into v_snapshot
  from private.lca_network_snapshots
  where id = v_check.snapshot_id;
  select * into v_artifact
  from private.lca_snapshot_artifacts
  where id = v_check.snapshot_artifact_id;
  select * into v_bundle
  from private.worker_job_artifacts
  where id = v_check.closure_bundle_artifact_id;
  select * into v_report
  from private.worker_job_artifacts
  where id = v_check.report_artifact_id;
  v_report_manifest_hash := private.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_artifact.id is null
     or v_artifact.snapshot_id <> v_snapshot.id
     or v_artifact.status <> 'ready'
     or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_artifact.artifact_sha256 <> v_check.snapshot_hash
     or v_artifact.snapshot_index_sha256 <> v_check.snapshot_index_sha256
     or v_artifact.snapshot_build_contract_hash <> v_check.snapshot_build_contract_hash
     or v_artifact.effective_scope_hash <> v_check.effective_scope_hash
     or v_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_artifact.closure_bundle_hash <> v_check.closure_bundle_hash
     or not private.lcia_scope_closure_bundle_binding_matches(v_check, v_bundle)
     or v_report.id is null
     or v_report.job_id <> v_check.worker_job_id
     or v_report.artifact_type <> 'closure_report_xlsx'
     or v_report_manifest_hash <> v_check.report_artifact_manifest_hash then
    return api.lcia_scope_closure_error('closure_snapshot_binding_invalid', 409, 'Numerical snapshot certificate binding is not ready');
  end if;

  v_result := private.cmd_lcia_result_build_request_v2_envelope(
    p_name, p_processes, p_coverage_mode, p_default_impact_category,
    p_lcia_method_set, p_idempotency_key, p_closure_check_id,
    p_requested_scope_hash, p_policy_fingerprint, p_audit
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then return v_result; end if;
  v_build_id := nullif(v_result->'data'->>'buildId', '')::uuid;
  select * into v_kind
  from private.worker_job_kinds
  where job_kind = 'lcia_result.package_build';
  if v_build_id is null or v_kind.job_kind is null then
    return api.lcia_scope_closure_error('build_enqueue_unavailable', 503, 'Build queue configuration is unavailable');
  end if;

  v_input_manifest := jsonb_build_object(
    'predicateVersion', v_check.effective_scope_manifest->>'eligibilityPredicateVersion',
    'selectionMode', 'closure_certificate',
    'processes', v_check.effective_scope_manifest->'processes'
  );
  v_payload := coalesce(v_result->'data'->'workerJob'->'payload', '{}'::jsonb)
    || jsonb_build_object(
      'coverage_mode', v_check.effective_scope_manifest->>'coverageMode',
      'input_manifest', v_input_manifest,
      'input_manifest_hash', private.lcia_scope_closure_sha256(v_input_manifest),
      'lcia_method_set', v_check.effective_scope_manifest->'lciaMethods',
      'closure_check_id', v_check.id,
      'closure_certificate_hash', v_check.certificate_hash,
      'requested_scope_hash', v_check.requested_scope_hash,
      'policy_fingerprint', v_check.policy_fingerprint,
      'effective_scope_hash', v_check.effective_scope_hash,
      'data_snapshot_token', v_check.data_snapshot_token,
      'snapshot_id', v_check.snapshot_id,
      'snapshot_hash', v_check.snapshot_hash,
      'closure_bundle_artifact_id', v_check.closure_bundle_artifact_id,
      'closure_bundle_hash', v_check.closure_bundle_hash,
      'report_artifact_manifest_hash', v_check.report_artifact_manifest_hash,
      'snapshot_artifact_id', v_check.snapshot_artifact_id,
      'snapshot_index_sha256', v_check.snapshot_index_sha256,
      'snapshot_build_contract_hash', v_check.snapshot_build_contract_hash,
      'effective_scope', v_check.effective_scope_manifest
    );
  v_idempotency_key := nullif(v_result->'data'->'workerJob'->>'idempotencyKey', '');
  select * into v_job
  from private.worker_jobs
  where worker_runtime = v_kind.worker_runtime
    and job_kind = v_kind.job_kind
    and requested_by = v_actor
    and idempotency_key is not distinct from v_idempotency_key
    and status in ('queued', 'running', 'waiting', 'stale', 'blocked')
  order by created_at desc limit 1
  for update;
  if v_job.id is null then
    insert into private.worker_jobs(
      job_kind, worker_runtime, worker_queue, priority, queue_key,
      subject_type, subject_id, requester_type, requested_by,
      idempotency_key, request_hash, concurrency_key, visibility,
      max_attempts, payload_schema_version, payload_json, payload_ref,
      result_schema_version
    ) values (
      v_kind.job_kind, v_kind.worker_runtime, v_kind.worker_queue,
      v_kind.default_priority, nullif(v_result->'data'->'workerJob'->>'queueKey', ''),
      'lcia_result_build', v_build_id, 'operator', v_actor,
      v_idempotency_key, nullif(v_result->'data'->'workerJob'->>'requestHash', ''),
      nullif(v_result->'data'->'workerJob'->>'queueKey', ''), 'operator',
      v_kind.default_max_attempts, 'lcia_result.package_build.request.v2',
      v_payload,
      jsonb_build_object('closureCertificate', jsonb_build_object(
        'closureCheckId', v_check.id,
        'certificateHash', v_check.certificate_hash,
        'requestedScopeHash', v_check.requested_scope_hash,
        'policyFingerprint', v_check.policy_fingerprint,
        'effectiveScopeHash', v_check.effective_scope_hash,
        'dataSnapshotToken', v_check.data_snapshot_token,
        'snapshotId', v_check.snapshot_id,
        'snapshotHash', v_check.snapshot_hash,
        'closureBundleArtifactId', v_check.closure_bundle_artifact_id,
        'closureBundleHash', v_check.closure_bundle_hash,
        'reportArtifactManifestHash', v_check.report_artifact_manifest_hash,
        'snapshotArtifactId', v_check.snapshot_artifact_id,
        'snapshotIndexSha256', v_check.snapshot_index_sha256,
        'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
        'effectiveScope', v_check.effective_scope_manifest
      )),
      v_kind.result_schema_version
    ) returning * into v_job;
    insert into private.worker_job_events(job_id, event_type, status, details)
    values(v_job.id, 'enqueued', v_job.status, jsonb_build_object(
      'jobKind', v_job.job_kind,
      'closureCheckId', v_check.id,
      'certificateHash', v_check.certificate_hash,
      'snapshotId', v_check.snapshot_id
    ));
  elsif v_job.payload_schema_version <> 'lcia_result.package_build.request.v2'
        or v_job.payload_json <> v_payload then
    return api.lcia_scope_closure_error('build_enqueue_conflict', 409, 'Existing active build does not match the certificate-bound V2 payload');
  end if;
  return jsonb_set(
    jsonb_set(v_result, '{data,workerJob}', private.worker_job_payload(v_job, false), true),
    '{data,workerJobId}', to_jsonb(v_job.id), true
  );
exception
  when unique_violation then
    return api.lcia_scope_closure_error('build_enqueue_conflict', 409, 'A conflicting certificate-bound build is already active');
end;
$$;


ALTER FUNCTION private.cmd_lcia_result_build_request_v2_without_expiry(p_name text, p_processes jsonb, p_coverage_mode text, p_default_impact_category text, p_lcia_method_set jsonb, p_idempotency_key text, p_closure_check_id uuid, p_requested_scope_hash text, p_policy_fingerprint text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_package_mark_ready(uuid, text, uuid, uuid, uuid, jsonb, jsonb, jsonb, jsonb, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lcia_result_package_mark_ready(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid DEFAULT NULL::uuid, p_result_artifact_ref jsonb DEFAULT '{}'::jsonb, p_query_artifact_ref jsonb DEFAULT '{}'::jsonb, p_artifact_manifest jsonb DEFAULT '{}'::jsonb, p_available_impact_categories jsonb DEFAULT '[]'::jsonb, p_default_impact_category text DEFAULT NULL::text, p_package_result_hash text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_job private.worker_jobs%rowtype;
  v_check private.lcia_scope_closure_checks%rowtype;
  v_snapshot private.lca_network_snapshots%rowtype;
  v_artifact private.lca_snapshot_artifacts%rowtype;
  v_closure_check_id uuid;
  v_binding jsonb;
begin
  if not api.lcia_result_is_service_request() then
    return api.lcia_result_error('service_role_required', 403, 'Service role is required to mark LCIA result packages ready');
  end if;
  select * into v_job
  from private.worker_jobs
  where id = p_build_worker_job_id
  for update;
  if v_job.id is null or v_job.job_kind <> 'lcia_result.package_build' then
    return api.lcia_result_error('build_worker_job_not_found', 404, 'LCIA result package build worker job not found');
  end if;
  if v_job.payload_schema_version <> 'lcia_result.package_build.request.v2' then
    return private.cmd_lcia_result_package_mark_ready_without_closure_recheck(
      p_build_worker_job_id, p_package_version, p_snapshot_id, p_result_id,
      p_latest_all_unit_result_id, p_result_artifact_ref, p_query_artifact_ref,
      p_artifact_manifest, p_available_impact_categories,
      p_default_impact_category, p_package_result_hash, p_audit
    );
  end if;
  if v_job.status <> 'running'
     or v_job.lease_token is null
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now() then
    return api.lcia_result_error('build_worker_job_lease_invalid', 409, 'Build job does not hold a current running lease');
  end if;
  begin
    v_closure_check_id := nullif(v_job.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    return api.lcia_result_error('closure_certificate_binding_mismatch', 409, 'Build payload contains an invalid closure check identity');
  end;
  select * into v_check
  from private.lcia_scope_closure_checks
  where id = v_closure_check_id
  for share;
  if v_check.id is null then
    return api.lcia_result_error('closure_check_not_usable', 409, 'Closure certificate is not available');
  end if;
  if v_check.certificate_status = 'revoked' then
    return api.lcia_result_error('closure_check_revoked', 409, 'Closure certificate was revoked before package readiness');
  end if;
  if v_check.certificate_status = 'stale' then
    return api.lcia_result_error('closure_check_stale', 409, 'Closure certificate became stale before package readiness');
  end if;
  if v_check.status <> 'passed'
     or v_check.scan_completeness <> 'complete'
     or v_check.certificate_status <> 'valid'
     or v_check.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
     or v_check.requested_by <> v_job.requested_by then
    return api.lcia_result_error('closure_check_not_usable', 409, 'Closure certificate is no longer usable');
  end if;
  if v_check.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
     and not private.lcia_scope_closure_current_release_matches(v_check.data_snapshot_token) then
    return api.lcia_result_error('closure_check_stale', 409, 'Closure certificate was created against an earlier public release');
  end if;
  v_binding := private.svc_lcia_scope_closure_build_binding(p_build_worker_job_id);
  if coalesce((v_binding->>'ok')::boolean, false) is not true then
    return api.lcia_result_error('closure_certificate_binding_mismatch', 409, 'Build payload or persisted evidence no longer matches the numerical snapshot certificate');
  end if;
  select * into v_snapshot
  from private.lca_network_snapshots
  where id = v_check.snapshot_id;
  select * into v_artifact
  from private.lca_snapshot_artifacts
  where id = v_check.snapshot_artifact_id;
  if p_snapshot_id <> v_check.snapshot_id
     or v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_artifact.id is null
     or v_artifact.snapshot_id <> v_snapshot.id
     or v_artifact.status <> 'ready'
     or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_artifact.artifact_sha256 <> v_check.snapshot_hash
     or v_artifact.snapshot_index_sha256 <> v_check.snapshot_index_sha256
     or v_artifact.snapshot_build_contract_hash <> v_check.snapshot_build_contract_hash
     or v_artifact.effective_scope_hash <> v_check.effective_scope_hash
     or v_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_artifact.closure_bundle_hash <> v_check.closure_bundle_hash
     or coalesce(v_job.payload_json->>'closure_certificate_hash', '') <> v_check.certificate_hash
     or coalesce(v_job.payload_json->>'snapshot_id', '') <> v_check.snapshot_id::text
     or coalesce(v_job.payload_json->>'snapshot_hash', '') <> v_check.snapshot_hash
     or coalesce(v_job.payload_json->>'snapshot_artifact_id', '') <> v_check.snapshot_artifact_id::text
     or coalesce(v_job.payload_json->>'snapshot_index_sha256', '') <> v_check.snapshot_index_sha256
     or coalesce(v_job.payload_json->>'snapshot_build_contract_hash', '') <> v_check.snapshot_build_contract_hash
     or coalesce(v_job.payload_json->'effective_scope', 'null'::jsonb) <> v_check.effective_scope_manifest
     or coalesce(v_job.payload_json->'input_manifest'->'processes', 'null'::jsonb)
          <> coalesce(v_check.effective_scope_manifest->'processes', 'null'::jsonb) then
    return api.lcia_result_error('closure_certificate_binding_mismatch', 409, 'Build result does not match the current numerical snapshot certificate');
  end if;
  return private.cmd_lcia_result_package_mark_ready_without_closure_recheck(
    p_build_worker_job_id, p_package_version, p_snapshot_id, p_result_id,
    p_latest_all_unit_result_id, p_result_artifact_ref, p_query_artifact_ref,
    p_artifact_manifest, p_available_impact_categories,
    p_default_impact_category, p_package_result_hash, p_audit
  );
end;
$$;


ALTER FUNCTION private.cmd_lcia_result_package_mark_ready(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid, p_result_artifact_ref jsonb, p_query_artifact_ref jsonb, p_artifact_manifest jsonb, p_available_impact_categories jsonb, p_default_impact_category text, p_package_result_hash text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_result_package_mark_ready_without_closure_recheck(uuid, text, uuid, uuid, uuid, jsonb, jsonb, jsonb, jsonb, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lcia_result_package_mark_ready_without_closure_recheck(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid DEFAULT NULL::uuid, p_result_artifact_ref jsonb DEFAULT '{}'::jsonb, p_query_artifact_ref jsonb DEFAULT '{}'::jsonb, p_artifact_manifest jsonb DEFAULT '{}'::jsonb, p_available_impact_categories jsonb DEFAULT '[]'::jsonb, p_default_impact_category text DEFAULT NULL::text, p_package_result_hash text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_job private.worker_jobs%rowtype;
  v_result private.lca_results%rowtype;
  v_latest private.lca_latest_all_unit_results%rowtype;
  v_package private.lcia_result_packages%rowtype;
  v_result_artifact_ref jsonb;
  v_query_artifact_ref jsonb;
  v_default_impact text;
begin
  if not api.lcia_result_is_service_request() then
    return api.lcia_result_error('service_role_required', 403, 'Service role is required to mark LCIA result packages ready');
  end if;

  if jsonb_typeof(coalesce(p_result_artifact_ref, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_query_artifact_ref, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_artifact_manifest, '{}'::jsonb)) <> 'object' then
    return api.lcia_result_error('invalid_artifact_payload', 400, 'artifact payloads must be JSON objects');
  end if;

  if jsonb_typeof(coalesce(p_available_impact_categories, '[]'::jsonb)) <> 'array' then
    return api.lcia_result_error('invalid_available_impact_categories', 400, 'available impact categories must be a JSON array');
  end if;

  select *
    into v_job
  from private.worker_jobs
  where id = p_build_worker_job_id
  for update;

  if v_job.id is null or v_job.job_kind <> 'lcia_result.package_build' then
    return api.lcia_result_error('build_worker_job_not_found', 404, 'LCIA result package build worker job not found');
  end if;

  select *
    into v_result
  from private.lca_results
  where id = p_result_id;

  if v_result.id is null then
    return api.lcia_result_error('result_not_found', 404, 'LCIA result artifact row not found');
  end if;

  if p_latest_all_unit_result_id is not null then
    select *
      into v_latest
    from private.lca_latest_all_unit_results
    where id = p_latest_all_unit_result_id;

    if v_latest.id is null then
      return api.lcia_result_error('latest_all_unit_result_not_found', 404, 'Latest all-unit LCIA result row not found');
    end if;
  end if;

  v_result_artifact_ref := case
    when coalesce(p_result_artifact_ref, '{}'::jsonb) <> '{}'::jsonb then p_result_artifact_ref
    else jsonb_strip_nulls(
      jsonb_build_object(
        'artifactUrl', v_result.artifact_url,
        'artifactSha256', v_result.artifact_sha256,
        'artifactByteSize', v_result.artifact_byte_size,
        'artifactFormat', v_result.artifact_format
      )
    )
  end;

  v_query_artifact_ref := case
    when coalesce(p_query_artifact_ref, '{}'::jsonb) <> '{}'::jsonb then p_query_artifact_ref
    when v_latest.id is not null then jsonb_strip_nulls(
      jsonb_build_object(
        'artifactUrl', v_latest.query_artifact_url,
        'artifactSha256', v_latest.query_artifact_sha256,
        'artifactByteSize', v_latest.query_artifact_byte_size,
        'artifactFormat', v_latest.query_artifact_format
      )
    )
    else '{}'::jsonb
  end;

  if v_result_artifact_ref = '{}'::jsonb then
    return api.lcia_result_error('result_artifact_missing', 400, 'LCIA result package requires a persisted result artifact reference');
  end if;

  v_default_impact := coalesce(
    nullif(trim(coalesce(p_default_impact_category, '')), ''),
    nullif(trim(coalesce(v_job.payload_json->>'default_impact_category', '')), '')
  );

  insert into private.lcia_result_packages (
    build_id,
    build_worker_job_id,
    package_version,
    coverage_mode,
    input_status_filter,
    eligibility_definition,
    eligibility_resolved_at,
    eligible_input_count,
    included_input_count,
    input_manifest_hash,
    input_manifest,
    snapshot_id,
    result_id,
    latest_all_unit_result_id,
    result_artifact_ref,
    query_artifact_ref,
    artifact_manifest,
    package_result_hash,
    lcia_method_set,
    available_impact_categories,
    postprocess_manifest,
    default_impact_category,
    status,
    created_by
  )
  values (
    (v_job.payload_json->>'build_id')::uuid,
    v_job.id,
    nullif(trim(coalesce(p_package_version, '')), ''),
    v_job.payload_json->>'coverage_mode',
    coalesce(v_job.payload_json->'input_status_filter', '{"state_code":{"between":[100,199]}}'::jsonb),
    coalesce(v_job.payload_json->'eligibility_definition', '{}'::jsonb),
    coalesce((v_job.payload_json->>'eligibility_resolved_at')::timestamptz, now()),
    coalesce((v_job.payload_json->>'eligible_input_count')::integer, 0),
    coalesce((v_job.payload_json->>'included_input_count')::integer, 0),
    nullif(v_job.payload_json->>'input_manifest_hash', ''),
    coalesce(v_job.payload_json->'input_manifest', '{}'::jsonb),
    p_snapshot_id,
    v_result.id,
    v_latest.id,
    v_result_artifact_ref,
    v_query_artifact_ref,
    coalesce(p_artifact_manifest, '{}'::jsonb),
    nullif(trim(coalesce(p_package_result_hash, '')), ''),
    coalesce(v_job.payload_json->'lcia_method_set', '[]'::jsonb),
    coalesce(p_available_impact_categories, '[]'::jsonb),
    coalesce(v_job.payload_json->'postprocess_manifest', '{"postprocess_mode":"skipped"}'::jsonb),
    v_default_impact,
    'preview_ready',
    v_job.requested_by
  )
  returning *
    into v_package;

  if v_job.status in ('queued', 'running', 'waiting', 'stale') then
    update private.worker_jobs
      set result_ref = coalesce(result_ref, '{}'::jsonb) || jsonb_build_object(
            'packageId', v_package.id,
            'packageVersion', v_package.package_version
          ),
          updated_at = now()
    where id = v_job.id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'packageId', v_package.id,
      'packageVersion', v_package.package_version,
      'status', v_package.status,
      'buildWorkerJobId', v_package.build_worker_job_id,
      'includedInputCount', v_package.included_input_count
    )
  );
exception
  when unique_violation then
    return api.lcia_result_error('package_conflict', 409, 'LCIA result package already exists for this build or package version');
  when foreign_key_violation then
    return api.lcia_result_error('package_reference_invalid', 400, 'LCIA result package references invalid worker, snapshot, or result rows');
  when invalid_text_representation then
    return api.lcia_result_error('invalid_package_payload', 400, 'LCIA result package payload contains invalid ids or numeric values');
  when not_null_violation then
    return api.lcia_result_error('invalid_package_payload', 400, 'LCIA result package payload is missing required fields');
  when check_violation then
    return api.lcia_result_error('invalid_package_payload', 400, 'LCIA result package payload violates schema constraints');
end;
$$;


ALTER FUNCTION private.cmd_lcia_result_package_mark_ready_without_closure_recheck(p_build_worker_job_id uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid, p_result_artifact_ref jsonb, p_query_artifact_ref jsonb, p_artifact_manifest jsonb, p_available_impact_categories jsonb, p_default_impact_category text, p_package_result_hash text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_scope_closure_check_request(text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lcia_scope_closure_check_request(p_requested_scope_hash text, p_policy_fingerprint text, p_request_idempotency_token text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request_key text; v_current_manifest jsonb; v_data_snapshot_token text; v_expected_validator_scanner_fingerprint text;
  v_request_fingerprint text;
  v_check private.lcia_scope_closure_checks%rowtype;
  v_job private.worker_jobs%rowtype;
begin
  if v_actor is null then
    return api.lcia_scope_closure_error('auth_required', 401, 'Authentication required');
  end if;
  if not api.lcia_scope_closure_is_manager() then
    return api.lcia_scope_closure_error('not_data_product_manager', 403, 'Data product manager role is required');
  end if;
  if coalesce(nullif(trim(p_requested_scope_hash), ''), '') = ''
    or coalesce(nullif(trim(p_policy_fingerprint), ''), '') = ''
    or coalesce(nullif(trim(p_request_idempotency_token), ''), '') = '' then
    return api.lcia_scope_closure_error('invalid_closure_request', 400, 'Closure scope, policy, and idempotency token are required');
  end if;
  select expected_validator_scanner_fingerprint into v_expected_validator_scanner_fingerprint
  from private.lcia_scope_closure_config where singleton;
  if v_expected_validator_scanner_fingerprint is null then
    return api.lcia_scope_closure_error('closure_evidence_unavailable', 503, 'Closure validator configuration is unavailable');
  end if;
  v_current_manifest := api.lcia_result_current_eligible_manifest();
  v_data_snapshot_token := v_current_manifest->>'inputManifestHash';

  v_request_fingerprint := encode(digest(
    trim(p_requested_scope_hash) || '|' || trim(p_policy_fingerprint) || '|' ||
    v_expected_validator_scanner_fingerprint || '|' || v_data_snapshot_token, 'sha256'), 'hex');
  v_request_key := encode(digest(v_actor::text || '|' || trim(p_request_idempotency_token) || '|' || v_request_fingerprint, 'sha256'), 'hex');

  select * into v_check
  from private.lcia_scope_closure_checks
  where requested_by = v_actor and request_key = v_request_key
  for update;
  if v_check.id is not null then
    select * into v_job from private.worker_jobs where id = v_check.worker_job_id;
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'closureCheckId', v_check.id, 'workerJob', private.worker_job_payload(v_job, false),
      'requestFingerprint', v_request_fingerprint, 'reused', true));
  end if;

  insert into private.worker_jobs (
    job_kind, worker_runtime, worker_queue, priority, subject_type, requester_type,
    requested_by, idempotency_key, request_hash, concurrency_key, visibility,
    max_attempts, payload_schema_version, payload_json, result_schema_version
  ) values (
    'lcia.scope_closure_check', 'calculator', 'solver', 10, 'lcia_scope_closure_check', 'user',
    v_actor, trim(p_request_idempotency_token), v_request_fingerprint, v_request_key, 'operator',
    3, 'lcia.scope_closure_check.request.v1', jsonb_build_object(
      'closure_check_id', null, 'requested_by', v_actor, 'requested_scope_hash', trim(p_requested_scope_hash),
      'policy_fingerprint', trim(p_policy_fingerprint), 'data_snapshot_token', v_data_snapshot_token,
      'expected_validator_scanner_fingerprint', v_expected_validator_scanner_fingerprint,
      'request_fingerprint', v_request_fingerprint, 'request_key', v_request_key),
    'lcia.scope_closure_check.result.v1'
  ) returning * into v_job;

  insert into private.lcia_scope_closure_checks (
    worker_job_id, requested_by, request_idempotency_token, request_key, request_fingerprint,
    requested_scope_hash, policy_fingerprint, data_snapshot_token, expected_validator_scanner_fingerprint
  ) values (
    v_job.id, v_actor, trim(p_request_idempotency_token), v_request_key, v_request_fingerprint,
    trim(p_requested_scope_hash), trim(p_policy_fingerprint), v_data_snapshot_token, v_expected_validator_scanner_fingerprint
  ) returning * into v_check;

  update private.worker_jobs
  set subject_id = v_check.id,
      payload_json = payload_json || jsonb_build_object('closure_check_id', v_check.id),
      updated_at = now()
  where id = v_job.id
  returning * into v_job;

  insert into private.worker_job_events (job_id, event_type, status, details)
  values (v_job.id, 'enqueued', 'queued', jsonb_build_object('closureCheckId', v_check.id, 'requestFingerprint', v_request_fingerprint));

  insert into private.command_audit_log (command, actor_user_id, target_table, target_id, payload)
  values ('cmd_lcia_scope_closure_check_request', v_actor, 'lcia_scope_closure_checks', v_check.id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object('requestFingerprint', v_request_fingerprint));

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id, 'workerJob', private.worker_job_payload(v_job, false),
    'requestFingerprint', v_request_fingerprint, 'reused', false));
end;
$$;


ALTER FUNCTION private.cmd_lcia_scope_closure_check_request(p_requested_scope_hash text, p_policy_fingerprint text, p_request_idempotency_token text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_lcia_scope_closure_check_request_v2_untracked(jsonb, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_lcia_scope_closure_check_request_v2_untracked(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_scope jsonb; v_policy jsonb; v_requested_scope_hash text;
  v_policy_fingerprint text; v_data_snapshot_token text; v_expected_validator_scanner_fingerprint text;
  v_request_fingerprint text; v_request_key text; v_check private.lcia_scope_closure_checks%rowtype; v_job private.worker_jobs%rowtype;
begin
  if v_actor is null then return api.lcia_scope_closure_error('auth_required', 401, 'Authentication required'); end if;
  if not api.lcia_scope_closure_is_manager() then return api.lcia_scope_closure_error('not_data_product_manager', 403, 'Data product manager role is required'); end if;
  if coalesce(nullif(trim(p_request_idempotency_token), ''), '') = '' then return api.lcia_scope_closure_error('invalid_closure_request', 400, 'Idempotency token is required'); end if;
  v_scope := private.lcia_scope_closure_normalize_request(p_requested_scope);
  v_requested_scope_hash := private.lcia_scope_closure_sha256(v_scope);
  v_policy := jsonb_build_object('scopePolicy', v_scope - 'processes' - 'lciaMethods' - 'processManifestHash', 'visibilityScope', 'data_product_manager.v1');
  v_policy_fingerprint := private.lcia_scope_closure_sha256(v_policy);
  v_data_snapshot_token := private.lcia_scope_closure_sha256(jsonb_build_object('processes', v_scope->'processes', 'lciaMethods', v_scope->'lciaMethods'));
  select expected_validator_scanner_fingerprint into v_expected_validator_scanner_fingerprint from private.lcia_scope_closure_config where singleton;
  if v_expected_validator_scanner_fingerprint is null then return api.lcia_scope_closure_error('closure_evidence_unavailable', 503, 'Closure validator configuration is unavailable'); end if;
  v_request_fingerprint := encode(extensions.digest(v_requested_scope_hash || '|' || v_policy_fingerprint || '|' || v_expected_validator_scanner_fingerprint || '|' || v_data_snapshot_token, 'sha256'), 'hex');
  v_request_key := encode(extensions.digest(v_actor::text || '|' || trim(p_request_idempotency_token) || '|' || v_request_fingerprint, 'sha256'), 'hex');
  select * into v_check from private.lcia_scope_closure_checks where requested_by = v_actor and request_key = v_request_key for update;
  if v_check.id is not null then
    select * into v_job from private.worker_jobs where id = v_check.worker_job_id;
    return jsonb_build_object('ok', true, 'data', jsonb_build_object('closureCheckId', v_check.id, 'requestedScopeHash', v_check.requested_scope_hash, 'policyFingerprint', v_check.policy_fingerprint, 'workerJob', private.worker_job_payload(v_job, false), 'reused', true));
  end if;
  insert into private.worker_jobs (job_kind, worker_runtime, worker_queue, priority, subject_type, requester_type, requested_by, idempotency_key, request_hash, concurrency_key, visibility, max_attempts, payload_schema_version, payload_json, result_schema_version)
  values ('lcia.scope_closure_check','calculator','solver',10,'lcia_scope_closure_check','user',v_actor,trim(p_request_idempotency_token),v_request_fingerprint,v_request_key,'operator',3,'lcia.scope_closure_check.request.v1',jsonb_build_object('closure_check_id', null, 'request_fingerprint', v_request_fingerprint),'lcia.scope_closure_check.result.v1') returning * into v_job;
  insert into private.lcia_scope_closure_checks (worker_job_id,requested_by,request_idempotency_token,request_key,request_fingerprint,requested_scope_hash,requested_scope_manifest,policy_fingerprint,data_snapshot_token,expected_validator_scanner_fingerprint)
  values (v_job.id,v_actor,trim(p_request_idempotency_token),v_request_key,v_request_fingerprint,v_requested_scope_hash,v_scope,v_policy_fingerprint,v_data_snapshot_token,v_expected_validator_scanner_fingerprint) returning * into v_check;
  update private.worker_jobs set subject_id = v_check.id, payload_json = payload_json || jsonb_build_object('closure_check_id', v_check.id), updated_at = now() where id = v_job.id returning * into v_job;
  insert into private.worker_job_events(job_id,event_type,status,details) values(v_job.id,'enqueued','queued',jsonb_build_object('closureCheckId',v_check.id,'requestFingerprint',v_request_fingerprint));
  insert into private.command_audit_log(command,actor_user_id,target_table,target_id,payload) values ('cmd_lcia_scope_closure_check_request_v2',v_actor,'lcia_scope_closure_checks',v_check.id,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('requestFingerprint',v_request_fingerprint,'requestedScopeHash',v_requested_scope_hash,'policyFingerprint',v_policy_fingerprint));
  return jsonb_build_object('ok',true,'data',jsonb_build_object('closureCheckId',v_check.id,'requestedScopeHash',v_requested_scope_hash,'policyFingerprint',v_policy_fingerprint,'workerJob',private.worker_job_payload(v_job,false),'reused',false));
exception when sqlstate '22023' then
  return api.lcia_scope_closure_error('invalid_closure_scope',400,sqlerrm);
end;
$$;


ALTER FUNCTION private.cmd_lcia_scope_closure_check_request_v2_untracked(p_requested_scope jsonb, p_request_idempotency_token text, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_approve_issue304_legacy(text, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_review_approve_issue304_legacy(p_table text, p_review_id uuid, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_root_table text;
  v_root_targets jsonb;
  v_comment_ref_roots jsonb := '[]'::jsonb;
  v_target record;
  v_comment_ref record;
  v_review_items jsonb := '[]'::jsonb;
  v_compliance_items jsonb := '[]'::jsonb;
  v_root_row jsonb;
  v_updated_root_row jsonb;
  v_submodel_ids uuid[] := array[]::uuid[];
  v_submodel_id uuid;
  v_submodel_doc jsonb;
  v_affected_datasets jsonb := '[]'::jsonb;
  v_review_json jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not api.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Only review admins can approve reviews'
    );
  end if;

  v_root_table := lower(coalesce(p_table, ''));
  if v_root_table not in ('processes', 'lifecyclemodels') then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_TABLE',
      'status', 400,
      'message', 'table must be processes or lifecyclemodels'
    );
  end if;

  select *
    into v_review
  from private.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code <> 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Only assigned reviews can be approved',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  v_root_targets := jsonb_build_array(
    jsonb_build_object(
      'table', v_root_table,
      'id', v_review.data_id,
      'version', v_review.data_version,
      'is_root', true
    )
  );

  create temporary table if not exists cmd_review_approve_targets (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    state_code integer not null,
    reviews jsonb,
    dataset_row jsonb not null,
    is_root boolean not null default false,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  truncate table cmd_review_approve_targets;

  insert into cmd_review_approve_targets (
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  )
  select
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  from api.cmd_review_collect_dataset_targets(v_root_targets, true);

  select coalesce(
    jsonb_agg(review_items.value),
    '[]'::jsonb
  )
    into v_review_items
  from private.comments as c
  cross join lateral jsonb_array_elements(
    api.cmd_review_json_array(to_jsonb(c.json)#>'{modellingAndValidation,validation,review}')
  ) as review_items(value)
  where c.review_id = p_review_id
    and c.state_code = 1;

  select coalesce(
    jsonb_agg(compliance_items.value),
    '[]'::jsonb
  )
    into v_compliance_items
  from private.comments as c
  cross join lateral jsonb_array_elements(
    api.cmd_review_json_array(
      to_jsonb(c.json)#>'{modellingAndValidation,complianceDeclarations,compliance}'
    )
  ) as compliance_items(value)
  where c.review_id = p_review_id
    and c.state_code = 1;

  for v_comment_ref in
    select distinct
      ref.ref_type,
      ref.ref_object_id,
      ref.ref_version
    from private.comments as c
    cross join lateral api.cmd_review_extract_refs(coalesce(to_jsonb(c.json), '{}'::jsonb)) as ref
    where c.review_id = p_review_id
      and c.state_code = 1
  loop
    v_comment_ref_roots := v_comment_ref_roots || jsonb_build_array(
      jsonb_build_object(
        'table', api.cmd_review_ref_type_to_table(v_comment_ref.ref_type),
        'id', v_comment_ref.ref_object_id,
        'version', v_comment_ref.ref_version,
        'is_root', false
      )
    );
  end loop;

  insert into cmd_review_approve_targets (
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  )
  select
    table_name,
    dataset_id,
    dataset_version,
    state_code,
    reviews,
    dataset_row,
    is_root
  from api.cmd_review_collect_dataset_targets(v_comment_ref_roots, true)
  on conflict (table_name, dataset_id, dataset_version) do nothing;

  select dataset_row
    into v_root_row
  from cmd_review_approve_targets
  where is_root
    and table_name = v_root_table
    and dataset_id = v_review.data_id
    and dataset_version = v_review.data_version
  limit 1;

  if v_root_row is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_TARGET_NOT_FOUND',
      'status', 404,
      'message', 'Review target dataset not found'
    );
  end if;

  if v_root_table = 'processes' then
    v_updated_root_row := api.cmd_review_apply_mv_payload(
      'processes',
      v_review.data_id,
      v_review.data_version,
      v_review_items,
      v_compliance_items
    );
  elsif v_root_table = 'lifecyclemodels' then
    select coalesce(
      array_agg(model_process.id order by model_process.id),
      array[]::uuid[]
    )
      into v_submodel_ids
    from public.processes as model_process
    where model_process.model_id = v_review.data_id
      and coalesce(model_process.model_version, model_process.version) = v_review.data_version
      and model_process.id <> v_review.data_id;

    foreach v_submodel_id in array v_submodel_ids
    loop
      if not exists (
        select 1
        from cmd_review_approve_targets as t
        where t.table_name = 'processes'
          and t.dataset_id = v_submodel_id
          and t.dataset_version = v_review.data_version
      ) then
        return jsonb_build_object(
          'ok', false,
          'code', 'INVALID_PAYLOAD',
          'status', 400,
          'message', format(
            'Missing current process snapshot for submodel %s',
            v_submodel_id
          )
        );
      end if;
    end loop;

    v_updated_root_row := api.cmd_review_apply_mv_payload(
      'lifecyclemodels',
      v_review.data_id,
      v_review.data_version,
      v_review_items,
      v_compliance_items
    );

    foreach v_submodel_id in array v_submodel_ids
    loop
      select api.cmd_review_apply_model_validation_to_process_json(
        coalesce(t.dataset_row->'json_ordered', t.dataset_row->'json', '{}'::jsonb),
        coalesce(v_updated_root_row->'json_ordered', v_updated_root_row->'json', '{}'::jsonb),
        v_review_items,
        v_compliance_items
      )
        into v_submodel_doc
      from cmd_review_approve_targets as t
      where t.table_name = 'processes'
        and t.dataset_id = v_submodel_id
        and t.dataset_version = v_review.data_version
      limit 1;

      update public.processes
        set json_ordered = v_submodel_doc::json,
            json = v_submodel_doc,
            modified_at = now()
      where id = v_submodel_id
        and version = v_review.data_version;
    end loop;

    for v_target in
      select *
      from cmd_review_approve_targets
      where table_name = 'processes'
        and not (dataset_id = any(v_submodel_ids))
      order by dataset_id, dataset_version
    loop
      perform api.cmd_review_apply_mv_payload(
        'processes',
        v_target.dataset_id,
        v_target.dataset_version,
        v_review_items,
        v_compliance_items
      );
    end loop;
  end if;

  for v_target in
    select *
    from cmd_review_approve_targets
    where state_code < 100
      and state_code <> 200
    order by table_name, dataset_id, dataset_version
  loop
    execute format(
      'update public.%I
          set state_code = 100,
              modified_at = now()
        where id = $1
          and version = $2',
      v_target.table_name
    )
      using v_target.dataset_id, v_target.dataset_version;
  end loop;

  update private.comments
    set state_code = 2,
        modified_at = now()
  where review_id = p_review_id
    and state_code <> -2;

  v_review_json := api.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    'approved',
    v_actor
  );

  update private.reviews
    set state_code = 2,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'table', table_name,
        'id', dataset_id,
        'version', dataset_version,
        'state_code', 100
      )
      order by table_name, dataset_id, dataset_version
    ),
    '[]'::jsonb
  )
    into v_affected_datasets
  from cmd_review_approve_targets
  where state_code < 100
    and state_code <> 200;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_approve',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'root_table', v_root_table,
      'affected_datasets', v_affected_datasets
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review),
      'affected_datasets', v_affected_datasets
    )
  );
end;
$_$;


ALTER FUNCTION private.cmd_review_approve_issue304_legacy(p_table text, p_review_id uuid, p_audit jsonb) OWNER TO postgres;

--
-- Name: FUNCTION cmd_review_approve_issue304_legacy(p_table text, p_review_id uuid, p_audit jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.cmd_review_approve_issue304_legacy(p_table text, p_review_id uuid, p_audit jsonb) IS 'Legacy approval compatibility path; Process model membership uses exact owner-version semantics.';


--
-- Name: cmd_review_assert_lifecycle_closure(jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_review_assert_lifecycle_closure(p_roots jsonb, p_action text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_root jsonb;
  v_current record;
  v_row jsonb;
  v_doc jsonb;
  v_root_owner uuid;
  v_ref record;
  v_paired jsonb;
  v_publish_root_table text;
  v_publish_root_id uuid;
  v_publish_root_version text;
begin
  create temporary table if not exists pg_temp.cmd_review_policy_queue (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    is_root boolean not null default false,
    dependency_role text not null,
    reference_path text not null,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  create temporary table if not exists pg_temp.cmd_review_policy_seen (
    table_name text not null,
    dataset_id uuid not null,
    dataset_version text not null,
    primary key (table_name, dataset_id, dataset_version)
  ) on commit drop;

  truncate table pg_temp.cmd_review_policy_queue;
  truncate table pg_temp.cmd_review_policy_seen;

  if p_actor is null
    or pg_catalog.jsonb_typeof(p_roots) <> 'array'
    or p_action not in ('submit', 'approve', 'publish') then
    return private.cmd_review_lifecycle_error(
      'REFERENCE_ROLE_POLICY_GAP',
      'request'
    );
  end if;

  for v_root in
    select root_item.value
    from pg_catalog.jsonb_array_elements(p_roots) as root_item(value)
  loop
    if lower(coalesce(v_root->>'table', ''))
      not in ('processes', 'lifecyclemodels')
      or coalesce(v_root->>'id', '')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or nullif(v_root->>'version', '') is null then
      return private.cmd_review_lifecycle_error(
        'REFERENCE_ROLE_POLICY_GAP',
        'request.root'
      );
    end if;

    insert into pg_temp.cmd_review_policy_queue (
      table_name,
      dataset_id,
      dataset_version,
      is_root,
      dependency_role,
      reference_path
    )
    values (
      lower(v_root->>'table'),
      (v_root->>'id')::uuid,
      v_root->>'version',
      true,
      'Root',
      'request.root'
    )
    on conflict do nothing;

    if v_publish_root_table is null then
      v_publish_root_table := lower(v_root->>'table');
      v_publish_root_id := (v_root->>'id')::uuid;
      v_publish_root_version := v_root->>'version';
    end if;
  end loop;

  while exists (select 1 from pg_temp.cmd_review_policy_queue) loop
    select
      queue.table_name,
      queue.dataset_id,
      queue.dataset_version,
      queue.is_root,
      queue.dependency_role,
      queue.reference_path
    into v_current
    from pg_temp.cmd_review_policy_queue as queue
    order by
      queue.is_root desc,
      queue.table_name,
      queue.dataset_id,
      queue.dataset_version
    limit 1;

    delete from pg_temp.cmd_review_policy_queue as queue
    where queue.table_name = v_current.table_name
      and queue.dataset_id = v_current.dataset_id
      and queue.dataset_version = v_current.dataset_version;

    if exists (
      select 1
      from pg_temp.cmd_review_policy_seen as seen
      where seen.table_name = v_current.table_name
        and seen.dataset_id = v_current.dataset_id
        and seen.dataset_version = v_current.dataset_version
    ) then
      continue;
    end if;

    v_row := api.cmd_review_get_dataset_row(
      v_current.table_name,
      v_current.dataset_id,
      v_current.dataset_version,
      true
    );

    if v_row is null then
      if v_current.dependency_role in ('ModelComposition', 'Paired') then
        return private.cmd_review_lifecycle_error(
          'MODEL_DEPENDENCY_NOT_PUBLIC',
          v_current.reference_path,
          v_current.table_name,
          v_current.dataset_id,
          v_current.dataset_version
        );
      end if;
      continue;
    end if;

    if v_current.is_root then
      v_root_owner := nullif(v_row->>'user_id', '')::uuid;
    elsif v_current.dependency_role in ('ModelComposition', 'Paired') then
      if p_action = 'publish' then
        if coalesce((v_row->>'state_code')::integer, 0) < 100
          and not (
            v_current.table_name = v_publish_root_table
            and v_current.dataset_id = v_publish_root_id
            and v_current.dataset_version = v_publish_root_version
          ) then
          return private.cmd_review_lifecycle_error(
            'MODEL_DEPENDENCY_NOT_PUBLIC',
            v_current.reference_path,
            v_current.table_name,
            v_current.dataset_id,
            v_current.dataset_version
          );
        end if;
      elsif coalesce((v_row->>'state_code')::integer, 0) < 100
        and nullif(v_row->>'user_id', '')::uuid is distinct from v_root_owner then
        return private.cmd_review_lifecycle_error(
          'MODEL_DEPENDENCY_NOT_PUBLIC',
          v_current.reference_path,
          v_current.table_name,
          v_current.dataset_id,
          v_current.dataset_version
        );
      end if;
    end if;

    insert into pg_temp.cmd_review_policy_seen (
      table_name,
      dataset_id,
      dataset_version
    )
    values (
      v_current.table_name,
      v_current.dataset_id,
      v_current.dataset_version
    );

    v_doc := case
      when coalesce(v_row->'json_ordered', 'null'::jsonb)
        not in ('null'::jsonb, '{}'::jsonb)
        then v_row->'json_ordered'
      else coalesce(v_row->'json', '{}'::jsonb)
    end;

    for v_ref in
      select *
      from private.cmd_review_reference_roles(
        v_current.table_name,
        'json',
        v_doc
      )
      order by reference_path, ref_table, ref_object_id, ref_version
    loop
      if v_ref.lifecycle_role = 'PolicyGap' then
        return private.cmd_review_lifecycle_error(
          'REFERENCE_ROLE_POLICY_GAP',
          v_ref.reference_path,
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version
        );
      elsif v_ref.lifecycle_role = 'RequiredSupport'
        and p_action in ('submit', 'approve') then
        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version,
          false,
          'RequiredSupport',
          v_ref.reference_path
        )
        on conflict do nothing;
      elsif v_ref.lifecycle_role = 'ModelComposition' then
        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          v_ref.ref_table,
          v_ref.ref_object_id,
          v_ref.ref_version,
          false,
          'ModelComposition',
          v_ref.reference_path
        )
        on conflict do nothing;
      end if;
    end loop;

    if v_current.table_name = 'lifecyclemodels' then
      insert into pg_temp.cmd_review_policy_queue (
        table_name,
        dataset_id,
        dataset_version,
        is_root,
        dependency_role,
        reference_path
      )
      select
        'processes',
        model_process.id,
        model_process.version,
        false,
        'ModelComposition',
        pg_catalog.format(
          'modelResults[%s@%s]',
          model_process.id,
          model_process.version
        )
      from public.processes as model_process
      where model_process.model_id = v_current.dataset_id
        and coalesce(model_process.model_version, model_process.version) = v_current.dataset_version
      on conflict do nothing;
    end if;

    if v_current.table_name = 'processes' then
      v_paired := api.cmd_review_get_dataset_row(
        'lifecyclemodels',
        v_current.dataset_id,
        v_current.dataset_version,
        true
      );

      if v_paired is not null then
        if (
          p_action = 'publish'
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
        ) or (
          p_action in ('submit', 'approve')
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
          and (
            v_current.is_root
            or nullif(v_paired->>'user_id', '')::uuid
              is distinct from v_root_owner
          )
        ) then
          return private.cmd_review_lifecycle_error(
            'MODEL_DEPENDENCY_NOT_PUBLIC',
            'pairedLifecycleModel',
            'lifecyclemodels',
            v_current.dataset_id,
            v_current.dataset_version
          );
        end if;

        insert into pg_temp.cmd_review_policy_queue (
          table_name,
          dataset_id,
          dataset_version,
          is_root,
          dependency_role,
          reference_path
        )
        values (
          'lifecyclemodels',
          v_current.dataset_id,
          v_current.dataset_version,
          false,
          'Paired',
          'pairedLifecycleModel'
        )
        on conflict do nothing;
      end if;
    elsif v_current.table_name = 'lifecyclemodels'
      and v_current.is_root then
      v_paired := api.cmd_review_get_dataset_row(
        'processes',
        v_current.dataset_id,
        v_current.dataset_version,
        true
      );

      if v_paired is not null then
        if (
          p_action = 'publish'
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
        ) or (
          p_action in ('submit', 'approve')
          and coalesce((v_paired->>'state_code')::integer, 0) < 100
          and nullif(v_paired->>'user_id', '')::uuid is distinct from v_root_owner
        ) then
          return private.cmd_review_lifecycle_error(
            'MODEL_DEPENDENCY_NOT_PUBLIC',
            'pairedProcess',
            'processes',
            v_current.dataset_id,
            v_current.dataset_version
          );
        end if;

        if p_action in ('submit', 'approve') then
          insert into pg_temp.cmd_review_policy_queue (
            table_name,
            dataset_id,
            dataset_version,
            is_root,
            dependency_role,
            reference_path
          )
          values (
            'processes',
            v_current.dataset_id,
            v_current.dataset_version,
            false,
            'Paired',
            'pairedProcess'
          )
          on conflict do nothing;
        end if;
      end if;
    end if;
  end loop;

  truncate table pg_temp.cmd_review_policy_queue;
  truncate table pg_temp.cmd_review_policy_seen;
  return null;
end;
$_$;


ALTER FUNCTION private.cmd_review_assert_lifecycle_closure(p_roots jsonb, p_action text, p_actor uuid) OWNER TO postgres;

--
-- Name: FUNCTION cmd_review_assert_lifecycle_closure(p_roots jsonb, p_action text, p_actor uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.cmd_review_assert_lifecycle_closure(p_roots jsonb, p_action text, p_actor uuid) IS 'Asserts lifecycle closure using exact Process owner versions with legacy same-version fallback.';


--
-- Name: cmd_review_assign_reviewers_v1_legacy(uuid, jsonb, timestamp with time zone, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_review_assign_reviewers_v1_legacy(p_review_id uuid, p_reviewer_ids jsonb, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_reviewer_ids jsonb;
  v_review_json jsonb;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if not api.cmd_review_is_review_admin(v_actor) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_ADMIN_REQUIRED',
      'status', 403,
      'message', 'Only review admins can assign reviewers'
    );
  end if;

  if coalesce(jsonb_typeof(p_reviewer_ids), 'null') <> 'array' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEWER_IDS',
      'status', 400,
      'message', 'reviewerIds must be an array of UUID strings'
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements_text(p_reviewer_ids) as reviewer_ids(value)
    where reviewer_ids.value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEWER_IDS',
      'status', 400,
      'message', 'reviewerIds must contain valid UUID strings only'
    );
  end if;

  v_reviewer_ids := api.cmd_review_normalize_reviewer_ids(p_reviewer_ids);

  if jsonb_array_length(v_reviewer_ids) = 0 then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_REQUIRED',
      'status', 400,
      'message', 'At least one reviewer is required'
    );
  end if;

  select *
    into v_review
  from private.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code not in (-1, 0, 1) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Reviewers can only be assigned for pending or rejected reviews',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  create temporary table if not exists cmd_review_assignment_active_reviewers (
    reviewer_id uuid primary key
  ) on commit drop;

  truncate table cmd_review_assignment_active_reviewers;

  insert into cmd_review_assignment_active_reviewers (reviewer_id)
  select value::uuid
  from jsonb_array_elements_text(v_reviewer_ids) as reviewer_ids(value);

  update private.comments
    set state_code = -2,
        modified_at = now()
  where review_id = p_review_id
    and reviewer_id not in (
      select reviewer_id
      from cmd_review_assignment_active_reviewers
    )
    and state_code = 0;

  insert into private.comments (
    review_id,
    reviewer_id,
    state_code
  )
  select
    p_review_id,
    reviewer_id,
    0
  from cmd_review_assignment_active_reviewers
  on conflict (review_id, reviewer_id) do update
    set state_code = case
      when private.comments.state_code in (-2, -1) then 0
      else private.comments.state_code
    end,
        modified_at = now();

  v_review_json := api.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    'assign_reviewers',
    v_actor,
    jsonb_strip_nulls(
      jsonb_build_object(
        'reviewer_ids', v_reviewer_ids,
        'deadline', case
          when p_deadline is null then null
          else to_jsonb(p_deadline)
        end
      )
    )
  );

  update private.reviews
    set reviewer_id = v_reviewer_ids,
        state_code = 1,
        deadline = p_deadline,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_assign_reviewers',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_strip_nulls(
      jsonb_build_object(
        'reviewer_ids', v_reviewer_ids,
        'deadline', case
          when p_deadline is null then null
          else to_jsonb(p_deadline)
        end
      )
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review)
    )
  );
end;
$_$;


ALTER FUNCTION private.cmd_review_assign_reviewers_v1_legacy(p_review_id uuid, p_reviewer_ids jsonb, p_deadline timestamp with time zone, p_audit jsonb) OWNER TO postgres;

--
-- Name: cmd_review_lifecycle_error(text, text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_review_lifecycle_error(p_code text, p_path text, p_ref_table text DEFAULT NULL::text, p_ref_id uuid DEFAULT NULL::uuid, p_ref_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'ok', false,
    'code', p_code,
    'status', 409,
    'message', case p_code
      when 'MODEL_DEPENDENCY_NOT_PUBLIC'
        then 'Model dependency is not public'
      when 'MODEL_COMPOSITION_POLICY_GAP'
        then 'Model composition sources do not agree'
      else 'Reference role is not configured'
    end,
    'details', jsonb_build_object(
      'path', p_path,
      'reference', jsonb_strip_nulls(jsonb_build_object(
        'table', p_ref_table,
        'id', p_ref_id,
        'version', p_ref_version
      ))
    )
  )
$$;


ALTER FUNCTION private.cmd_review_lifecycle_error(p_code text, p_path text, p_ref_table text, p_ref_id uuid, p_ref_version text) OWNER TO postgres;

--
-- Name: cmd_review_reference_roles(text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_review_reference_roles(p_table text, p_source text, p_json jsonb) RETURNS TABLE(reference_path text, lifecycle_role text, ref_type text, ref_table text, ref_object_id uuid, ref_version text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  with recursive walk(value, path) as (
    select coalesce(p_json, '{}'::jsonb), array[]::text[]
    union all
    select child.value, walk.path || child.path_item
    from walk
    cross join lateral (
      select object_item.value, object_item.key as path_item
      from pg_catalog.jsonb_each(
        case
          when pg_catalog.jsonb_typeof(walk.value) = 'object' then walk.value
          else '{}'::jsonb
        end
      ) as object_item(key, value)
      union all
      select array_item.value, (array_item.ordinality - 1)::text as path_item
      from pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(walk.value) = 'array' then walk.value
          else '[]'::jsonb
        end
      ) with ordinality as array_item(value, ordinality)
    ) as child
  ),
  candidates as (
    select
      value,
      path,
      coalesce((
        select pg_catalog.array_agg(path_item.item order by path_item.ordinality)
        from pg_catalog.unnest(path)
          with ordinality as path_item(item, ordinality)
        where not (
          path_item.item ~ '^[0-9]+$'
          and path_item.ordinality > 1
          and path[path_item.ordinality - 1] = any(array[
            'exchange',
            'referenceToFlowDataSet',
            'referencesToDataSource',
            'referenceToDataSource',
            'processInstance',
            'referenceToProcess',
            'referenceToResultingProcess',
            'review',
            'common:referenceToReviewDetails',
            'common:referenceToPrecedingDataSetVersion',
            'referenceToIncludedProcesses'
          ])
        )
      ), array[]::text[]) as semantic_path
    from walk
    where pg_catalog.jsonb_typeof(value) = 'object'
  ),
  refs as (
    select
      candidates.value,
      candidates.path,
      candidates.semantic_path,
      case
        when candidates.semantic_path in (
          array[
            'processDataSet',
            'processInformation',
            'technology',
            'referenceToIncludedProcesses'
          ],
          array[
            'lifeCycleModelDataSet',
            'lifeCycleModelInformation',
            'technology',
            'processes',
            'processInstance',
            'referenceToProcess'
          ]
        ) then 'processes'
        else api.cmd_review_ref_type_to_table(candidates.value->>'@type')
      end as mapped_table,
      (
        candidates.value->>'@refObjectId'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and candidates.value->>'@version'
          ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        and (
          not candidates.value ? '@type'
          or api.cmd_review_ref_type_to_table(
            candidates.value->>'@type'
          ) = 'processes'
        )
      ) as valid_process_composition
    from candidates
    where (
      candidates.value ? '@refObjectId'
      and candidates.value ? '@version'
      and candidates.value ? '@type'
      and candidates.value->>'@refObjectId'
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and nullif(candidates.value->>'@version', '') is not null
      and api.cmd_review_ref_type_to_table(
        candidates.value->>'@type'
      ) is not null
    ) or candidates.semantic_path in (
      array[
        'processDataSet',
        'processInformation',
        'technology',
        'referenceToIncludedProcesses'
      ],
      array[
        'lifeCycleModelDataSet',
        'lifeCycleModelInformation',
        'technology',
        'processes',
        'processInstance',
        'referenceToProcess'
      ]
    )
  )
  select
    coalesce(p_source, 'json') || coalesce((
      select pg_catalog.string_agg(
        case
          when path_item.item ~ '^[0-9]+$' then '[' || path_item.item || ']'
          else '.' || path_item.item
        end,
        ''
        order by path_item.ordinality
      )
      from pg_catalog.unnest(refs.path)
        with ordinality as path_item(item, ordinality)
    ), '') as reference_path,
    case
      when refs.semantic_path = array[
        case lower(coalesce(p_table, ''))
          when 'contacts' then 'contactDataSet'
          when 'sources' then 'sourceDataSet'
          when 'unitgroups' then 'unitGroupDataSet'
          when 'flowproperties' then 'flowPropertyDataSet'
          when 'flows' then 'flowDataSet'
          when 'processes' then 'processDataSet'
          when 'lifecyclemodels' then 'lifeCycleModelDataSet'
          else null
        end,
        'administrativeInformation',
        'publicationAndOwnership',
        'common:referenceToPrecedingDataSetVersion'
      ]
        then 'Lineage'
      when lower(coalesce(p_table, '')) = 'processes'
        and refs.semantic_path = array[
          'processDataSet',
          'exchanges',
          'exchange',
          'referenceToFlowDataSet'
        ]
        then 'RequiredSupport'
      when lower(coalesce(p_table, '')) = 'processes'
        and refs.semantic_path = array[
          'processDataSet',
          'exchanges',
          'exchange',
          'referencesToDataSource',
          'referenceToDataSource'
        ]
        then 'RequiredSupport'
      when lower(coalesce(p_table, '')) = 'processes'
        and refs.semantic_path = array[
          'processDataSet',
          'processInformation',
          'quantitativeReference',
          'referenceToReferenceFlow'
        ]
        then 'RequiredSupport'
      when lower(coalesce(p_table, '')) = 'processes'
        and refs.semantic_path = array[
          'processDataSet',
          'processInformation',
          'technology',
          'referenceToIncludedProcesses'
        ]
        then case
          when refs.valid_process_composition then 'ModelComposition'
          else 'PolicyGap'
        end
      when lower(coalesce(p_table, '')) = 'lifecyclemodels'
        and refs.semantic_path = array[
          'lifeCycleModelDataSet',
          'lifeCycleModelInformation',
          'technology',
          'processes',
          'processInstance',
          'referenceToProcess'
        ]
        then case
          when refs.valid_process_composition then 'ModelComposition'
          else 'PolicyGap'
        end
      when lower(coalesce(p_table, '')) = 'lifecyclemodels'
        and refs.semantic_path = array[
          'lifeCycleModelDataSet',
          'lifeCycleModelInformation',
          'dataSetInformation',
          'referenceToResultingProcess'
        ]
        then 'Descriptive'
      when lower(coalesce(p_table, '')) = 'comments'
        and refs.semantic_path = array[
          'modellingAndValidation',
          'validation',
          'review',
          'common:referenceToReviewDetails'
        ]
        then 'RequiredSupport'
      when refs.mapped_table in ('processes', 'flows')
        then 'PolicyGap'
      else 'RequiredSupport'
    end as lifecycle_role,
    case
      when not refs.value ? '@type'
        and refs.mapped_table = 'processes'
        then 'process data set'
      else lower(trim(refs.value->>'@type'))
    end as ref_type,
    refs.mapped_table as ref_table,
    case
      when refs.value->>'@refObjectId'
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (refs.value->>'@refObjectId')::uuid
      else null
    end as ref_object_id,
    refs.value->>'@version' as ref_version
  from refs
$_$;


ALTER FUNCTION private.cmd_review_reference_roles(p_table text, p_source text, p_json jsonb) OWNER TO postgres;

--
-- Name: cmd_review_submit_comment_pre_v2(uuid, jsonb, integer, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.cmd_review_submit_comment_pre_v2(p_review_id uuid, p_json jsonb, p_comment_state integer DEFAULT 1, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_review private.reviews%rowtype;
  v_comment private.comments%rowtype;
  v_comment_json jsonb := coalesce(p_json, '{}'::jsonb);
  v_review_json jsonb;
  v_ref record;
  v_ref_table text;
  v_ref_roots jsonb := '[]'::jsonb;
  v_target record;
  v_affected_datasets jsonb := '[]'::jsonb;
  v_action text;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'AUTH_REQUIRED',
      'status', 401,
      'message', 'Authentication required'
    );
  end if;

  if p_comment_state not in (-3, 1) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_COMMENT_STATE',
      'status', 400,
      'message', 'commentState must be 1 or -3'
    );
  end if;

  if coalesce(jsonb_typeof(v_comment_json), 'null') <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_COMMENT_JSON',
      'status', 400,
      'message', 'comment json must be an object'
    );
  end if;

  select *
    into v_review
  from private.reviews
  where id = p_review_id
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEW_NOT_FOUND',
      'status', 404,
      'message', 'Review not found'
    );
  end if;

  if v_review.state_code not in (-1, 1) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REVIEW_STATE',
      'status', 409,
      'message', 'Review comments can only be submitted for assigned or rejected reviews',
      'details', jsonb_build_object(
        'state_code', v_review.state_code
      )
    );
  end if;

  if not api.cmd_review_json_array(v_review.reviewer_id) @> jsonb_build_array(to_jsonb(v_actor::text)) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REVIEWER_REQUIRED',
      'status', 403,
      'message', 'Only assigned reviewers can submit review comments'
    );
  end if;

  select *
    into v_comment
  from private.comments
  where review_id = p_review_id
    and reviewer_id = v_actor
  for update;

  if found and v_comment.state_code in (-2, 2) then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_COMMENT_STATE',
      'status', 409,
      'message', 'This reviewer comment can no longer be submitted',
      'details', jsonb_build_object(
        'state_code', v_comment.state_code
      )
    );
  end if;

  if not found then
    insert into private.comments (
      review_id,
      reviewer_id,
      state_code
    )
    values (
      p_review_id,
      v_actor,
      case
        when v_review.state_code = -1 then -1
        else 0
      end
    )
    returning *
      into v_comment;
  end if;

  if p_comment_state = 1 then
    for v_ref in
      select *
      from api.cmd_review_extract_refs(v_comment_json)
    loop
      v_ref_table := api.cmd_review_ref_type_to_table(v_ref.ref_type);

      if v_ref_table is null then
        continue;
      end if;

      v_ref_roots := v_ref_roots || jsonb_build_array(
        jsonb_build_object(
          'table', v_ref_table,
          'id', v_ref.ref_object_id,
          'version', v_ref.ref_version,
          'is_root', false
        )
      );
    end loop;

    create temporary table if not exists cmd_review_submit_comment_targets (
      table_name text not null,
      dataset_id uuid not null,
      dataset_version text not null,
      state_code integer not null,
      reviews jsonb,
      dataset_row jsonb not null,
      is_root boolean not null default false,
      primary key (table_name, dataset_id, dataset_version)
    ) on commit drop;

    truncate table cmd_review_submit_comment_targets;

    insert into cmd_review_submit_comment_targets (
      table_name,
      dataset_id,
      dataset_version,
      state_code,
      reviews,
      dataset_row,
      is_root
    )
    select
      table_name,
      dataset_id,
      dataset_version,
      state_code,
      reviews,
      dataset_row,
      is_root
    from api.cmd_review_collect_dataset_targets(v_ref_roots, true);

    for v_target in
      select *
      from cmd_review_submit_comment_targets
      where state_code >= 20
        and state_code < 100
      order by table_name, dataset_id, dataset_version
    loop
      return jsonb_build_object(
        'ok', false,
        'code', 'REFERENCED_DATA_UNDER_REVIEW',
        'status', 409,
        'message', 'Referenced data is already under review',
        'details', jsonb_build_object(
          'table', v_target.table_name,
          'id', v_target.dataset_id,
          'version', v_target.dataset_version,
          'state_code', 20,
          'review_state_code', v_target.state_code
        )
      );
    end loop;

    for v_target in
      select *
      from cmd_review_submit_comment_targets
      where state_code < 20
      order by table_name, dataset_id, dataset_version
    loop
      execute format(
        'update public.%I
            set state_code = 20,
                reviews = $1,
                modified_at = now()
          where id = $2
            and version = $3',
        v_target.table_name
      )
        using api.cmd_review_append_review_ref(v_target.reviews, p_review_id),
              v_target.dataset_id,
              v_target.dataset_version;
    end loop;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'table', table_name,
          'id', dataset_id,
          'version', dataset_version,
          'state_code', 20
        )
        order by table_name, dataset_id, dataset_version
      ),
      '[]'::jsonb
    )
      into v_affected_datasets
    from cmd_review_submit_comment_targets
    where state_code < 20;
  end if;

  update private.comments
    set json = v_comment_json::json,
        state_code = p_comment_state,
        modified_at = now()
  where review_id = p_review_id
    and reviewer_id = v_actor
  returning *
    into v_comment;

  v_action := case
    when p_comment_state = -3 then 'reviewer_rejected'
    else 'submit_comments'
  end;

  v_review_json := api.cmd_review_append_log(
    coalesce(v_review.json, '{}'::jsonb),
    v_action,
    v_actor,
    jsonb_build_object(
      'reviewer_id', v_actor,
      'comment_state_code', p_comment_state
    )
  );

  update private.reviews
    set state_code = case
          when p_comment_state = 1 and state_code = -1 then 1
          else state_code
        end,
        json = v_review_json,
        modified_at = now()
  where id = p_review_id
  returning *
    into v_review;

  insert into private.command_audit_log (
    command,
    actor_user_id,
    target_table,
    target_id,
    payload
  )
  values (
    'cmd_review_submit_comment',
    v_actor,
    'reviews',
    p_review_id,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'reviewer_id', v_actor,
      'comment_state_code', p_comment_state,
      'affected_datasets', v_affected_datasets
    )
  );

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'review', to_jsonb(v_review),
      'comment', to_jsonb(v_comment),
      'affected_datasets', v_affected_datasets
    )
  );
end;
$_$;


ALTER FUNCTION private.cmd_review_submit_comment_pre_v2(p_review_id uuid, p_json jsonb, p_comment_state integer, p_audit jsonb) OWNER TO postgres;

--
-- Name: contacts_sync_jsonb_version(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.contacts_sync_jsonb_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NEW.json_ordered::jsonb IS DISTINCT FROM OLD.json_ordered::jsonb THEN
        NEW.json := NEW.json_ordered;
        NEW.version := COALESCE(
            NEW.json->'contactDataSet'->'administrativeInformation'->'publicationAndOwnership'->>'common:dataSetVersion', 
            ''
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION private.contacts_sync_jsonb_version() OWNER TO postgres;

--
-- Name: dataset_alias_canonical_jsonb_v1(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_alias_canonical_jsonb_v1(p_value jsonb) RETURNS text
    LANGUAGE plpgsql STABLE STRICT
    SET search_path TO ''
    AS $$
declare
  v_result text;
begin
  case jsonb_typeof(p_value)
    when 'object' then
      select '{' || coalesce(string_agg(
        to_jsonb(object_item.key)::text
          || ':'
          || private.dataset_alias_canonical_jsonb_v1(object_item.value),
        ',' order by private.dataset_alias_js_object_key_sort_key_v1(object_item.key)
      ), '') || '}'
      into v_result
      from jsonb_each(p_value) as object_item(key, value);
    when 'array' then
      select '[' || coalesce(string_agg(
        private.dataset_alias_canonical_jsonb_v1(array_item.value),
        ',' order by array_item.ordinality
      ), '') || ']'
      into v_result
      from jsonb_array_elements(p_value)
        with ordinality as array_item(value, ordinality);
    else
      v_result := p_value::text;
  end case;

  return v_result;
end;
$$;


ALTER FUNCTION private.dataset_alias_canonical_jsonb_v1(p_value jsonb) OWNER TO postgres;

--
-- Name: FUNCTION dataset_alias_canonical_jsonb_v1(p_value jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.dataset_alias_canonical_jsonb_v1(p_value jsonb) IS 'Serializes JSON with recursively stableJsonText-compatible object key order and compact separators for guarded alias exchange evidence hashing.';


--
-- Name: dataset_alias_js_object_key_sort_key_v1(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_alias_js_object_key_sort_key_v1(p_value text) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $_$
declare
  v_result bytea := '\x01'::bytea;
  v_array_index bigint;
  v_code_point integer;
  v_supplementary integer;
begin
  -- stableJsonText sorts keys by JavaScript UTF-16 order before rebuilding an
  -- object. JSON.stringify then enumerates canonical array-index keys first in
  -- ascending numeric order. Reproduce both rules with a binary prefix plus a
  -- big-endian numeric or UTF-16 payload. PostgreSQL text cannot contain lone
  -- surrogates.
  if p_value ~ '^(0|[1-9][0-9]{0,9})$' then
    v_array_index := p_value::bigint;
    if v_array_index <= 4294967294 then
      return '\x00'::bytea || int8send(v_array_index);
    end if;
  end if;

  for v_character_index in 1..character_length(p_value) loop
    v_code_point := ascii(substring(p_value from v_character_index for 1));

    if v_code_point <= 65535 then
      v_result := v_result || decode(
        lpad(to_hex(v_code_point), 4, '0'),
        'hex'
      );
    else
      v_supplementary := v_code_point - 65536;
      v_result := v_result || decode(
        lpad(to_hex(55296 + (v_supplementary / 1024)), 4, '0')
          || lpad(to_hex(56320 + (v_supplementary % 1024)), 4, '0'),
        'hex'
      );
    end if;
  end loop;

  return v_result;
end;
$_$;


ALTER FUNCTION private.dataset_alias_js_object_key_sort_key_v1(p_value text) OWNER TO postgres;

--
-- Name: FUNCTION dataset_alias_js_object_key_sort_key_v1(p_value text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.dataset_alias_js_object_key_sort_key_v1(p_value text) IS 'Builds a binary sort key matching stableJsonText object enumeration: canonical array indexes first, then JavaScript UTF-16 string order.';


--
-- Name: dataset_alias_jsonb_array_v1(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_alias_jsonb_array_v1(p_value jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case pg_catalog.jsonb_typeof(p_value)
    when 'array' then p_value
    when 'object' then pg_catalog.jsonb_build_array(p_value)
    else '[]'::jsonb
  end;
$$;


ALTER FUNCTION private.dataset_alias_jsonb_array_v1(p_value jsonb) OWNER TO postgres;

--
-- Name: FUNCTION dataset_alias_jsonb_array_v1(p_value jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.dataset_alias_jsonb_array_v1(p_value jsonb) IS 'Normalizes singleton-object or array dataset reference collections into an immutable JSONB array for guarded alias candidate indexes and exact rechecks. EXECUTE is limited to postgres-owned definer code and the trusted service_role table writer.';


--
-- Name: dataset_flow_identity_active_fence(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_active_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_id uuid;
  v_new_id uuid;
  v_old_version text;
  v_new_version text;
  v_old_user_id uuid;
  v_new_user_id uuid;
  v_old_state_code integer;
  v_new_state_code integer;
  v_actor uuid;
  v_permit_scope uuid;
  v_old_payload jsonb;
  v_new_payload jsonb;
  v_is_exact_process boolean := false;
  v_is_guarded boolean := false;
begin
  if tg_op <> 'INSERT' then
    v_old_id := old.id;
    v_old_version := btrim(old.version::text);
    v_old_user_id := old.user_id;
    v_old_state_code := old.state_code;
    if tg_table_name in ('processes', 'flows') then
      v_old_payload := old.json_ordered::jsonb;
    end if;
  end if;
  if tg_op <> 'DELETE' then
    v_new_id := new.id;
    v_new_version := btrim(new.version::text);
    v_new_user_id := new.user_id;
    v_new_state_code := new.state_code;
    if tg_table_name in ('processes', 'flows') then
      v_new_payload := new.json_ordered::jsonb;
    end if;
  end if;

  if tg_table_name = 'processes' then
    -- Derivative workers may continue while a scope is active, but only when
    -- every primary identity/payload/policy column is byte-for-byte stable.
    if tg_op = 'UPDATE'
      and new.id is not distinct from old.id
      and new.version is not distinct from old.version
      and new.user_id is not distinct from old.user_id
      and new.state_code is not distinct from old.state_code
      and new.json::jsonb is not distinct from old.json::jsonb
      and new.json_ordered::jsonb
        is not distinct from old.json_ordered::jsonb
      and new.model_id is not distinct from old.model_id
      and new.rule_verification is not distinct from old.rule_verification then
      return new;
    end if;

    -- Serialize both ownership domains.  This closes UPDATEs that move a row
    -- from a foreign owner into the actor (or away from the actor).
    for v_actor in
      select distinct actor_id
      from (values (v_old_user_id), (v_new_user_id)) as actors(actor_id)
      where actor_id is not null
      order by actor_id
    loop
      if not pg_try_advisory_xact_lock(hashtextextended(
        'dataset-flow-identity-actor:' || v_actor::text, 0
      )) then
        raise exception using errcode = '55P03',
          message = 'FLOW_IDENTITY_ACTIVE_SCOPE_ACTOR_FENCE_BUSY';
      end if;
    end loop;
    -- The only primary mutation permit is a private, transaction-scoped row
    -- minted by the rewrite core and consumed exactly once here.  Caller-set
    -- custom GUCs have no authority.
    if tg_op = 'UPDATE'
      and new.id is not distinct from old.id
      and new.version is not distinct from old.version
      and new.user_id is not distinct from old.user_id
      and new.state_code is not distinct from old.state_code
      and new.model_id is not distinct from old.model_id
      and new.rule_verification is not distinct from old.rule_verification
      and new.json::jsonb is not distinct from old.json::jsonb then
      with consumed as (
        delete from util.dataset_flow_identity_mutation_permits as permit
        using util.dataset_flow_identity_process_ledger as ledger,
          util.dataset_flow_identity_scopes as scope
        where permit.transaction_id = txid_current()
          and permit.process_id = old.id
          and permit.process_version = btrim(old.version::text)
          and permit.before_payload_sha256
            = util.dataset_flow_identity_sha256(old.json_ordered::jsonb)
          and permit.after_payload_sha256
            = util.dataset_flow_identity_sha256(new.json_ordered::jsonb)
          and ledger.scope_id = permit.scope_id
          and ledger.ordinal = permit.ordinal
          and ledger.process_id = permit.process_id
          and ledger.process_version = permit.process_version
          and ledger.mutation_nonce = permit.mutation_nonce
          and ledger.status = 'pending' and ledger.active
          and scope.id = ledger.scope_id
          and scope.actor_user_id = old.user_id
          and scope.status in (
            'sealed', 'running', 'primary_complete', 'derivatives_pending'
          )
        returning permit.scope_id
      )
      select consumed.scope_id into v_permit_scope from consumed;
      if v_permit_scope is not null then
        return new;
      end if;
    end if;

    -- An exact captured process stays fenced after its source references have
    -- been removed.  Source-reference inspection alone is not sufficient.
    select exists (
      select 1
      from util.dataset_flow_identity_scopes as scope
      join util.dataset_flow_identity_process_ledger as ledger
        on ledger.scope_id = scope.id and ledger.active
      where scope.status in (
          'sealed', 'running', 'primary_complete', 'derivatives_pending'
        )
        and (
          (scope.actor_user_id = v_old_user_id
            and ledger.process_id = v_old_id
            and ledger.process_version = v_old_version)
          or (scope.actor_user_id = v_new_user_id
            and ledger.process_id = v_new_id
            and ledger.process_version = v_new_version)
        )
    ) into v_is_exact_process;
    if v_is_exact_process then
      raise exception using errcode = '55000',
        message = 'FLOW_IDENTITY_ACTIVE_SCOPE_PROCESS_FENCE';
    end if;

    select exists (
      select 1
      from util.dataset_flow_identity_scopes as scope
      join util.dataset_flow_identity_capture_source_guards as guard
        on guard.receipt_id = scope.receipt_id
      cross join lateral jsonb_array_elements(
        case when scope.actor_user_id = v_old_user_id
          then coalesce(private.dataset_flow_identity_exchanges(v_old_payload), '[]'::jsonb)
          else '[]'::jsonb end
        || case when scope.actor_user_id = v_new_user_id
          then coalesce(private.dataset_flow_identity_exchanges(v_new_payload), '[]'::jsonb)
          else '[]'::jsonb end
      ) as exchange(value)
      where scope.status in (
          'sealed', 'running', 'primary_complete', 'derivatives_pending'
        )
        and exchange.value #>> '{referenceToFlowDataSet,@refObjectId}'
          = guard.source_id::text
        and exchange.value #>> '{referenceToFlowDataSet,@version}'
          = guard.source_version
    ) into v_is_guarded;
    if v_is_guarded then
      raise exception using errcode = '55000',
        message = 'FLOW_IDENTITY_ACTIVE_SCOPE_PROCESS_FENCE';
    end if;
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_table_name = 'flows' then
    -- Acquire every OLD/NEW and guarded-scope actor in one globally sorted
    -- pass.  Splitting those sets into two loops permits A->Z and Z->A lock
    -- inversion for cross-owner public-target updates.
    for v_actor in
      select distinct actor_id
      from (
        values (v_old_user_id), (v_new_user_id)
        union all
        select scope.actor_user_id
        from util.dataset_flow_identity_scopes as scope
        where scope.status in (
            'sealed', 'running', 'primary_complete', 'derivatives_pending'
          )
          and (
            scope.actor_user_id in (v_old_user_id, v_new_user_id)
            or exists (
              select 1
              from util.dataset_flow_identity_capture_source_guards as guard
              where guard.receipt_id = scope.receipt_id
                and ((guard.source_id = v_old_id
                    and guard.source_version = v_old_version)
                  or (guard.source_id = v_new_id
                    and guard.source_version = v_new_version))
            )
            or exists (
              select 1
              from util.dataset_flow_identity_capture_target_guards as guard
              where guard.receipt_id = scope.receipt_id
                and ((guard.target_id = v_old_id
                    and guard.target_version = v_old_version)
                  or (guard.target_id = v_new_id
                    and guard.target_version = v_new_version))
            )
          )
      ) as actors(actor_id)
      where actor_id is not null
      order by actor_id
    loop
      if not pg_try_advisory_xact_lock(hashtextextended(
        'dataset-flow-identity-actor:' || v_actor::text, 0
      )) then
        raise exception using errcode = '55P03',
          message = 'FLOW_IDENTITY_ACTIVE_SCOPE_ACTOR_FENCE_BUSY';
      end if;
    end loop;
    select exists (
      select 1
      from util.dataset_flow_identity_scopes as scope
      where scope.status in (
          'sealed', 'running', 'primary_complete', 'derivatives_pending'
        )
        and (
          (scope.actor_user_id = v_old_user_id
            and v_old_state_code = 0
            and v_old_payload #>>
              '{flowDataSet,modellingAndValidation,LCIMethod,typeOfDataSet}'
              = 'Elementary flow')
          or (scope.actor_user_id = v_new_user_id
            and v_new_state_code = 0
            and v_new_payload #>>
              '{flowDataSet,modellingAndValidation,LCIMethod,typeOfDataSet}'
              = 'Elementary flow')
          or exists (
            select 1
            from util.dataset_flow_identity_capture_source_guards as guard
            where guard.receipt_id = scope.receipt_id
              and ((guard.source_id = v_old_id
                  and guard.source_version = v_old_version)
                or (guard.source_id = v_new_id
                  and guard.source_version = v_new_version))
          )
          or exists (
            select 1
            from util.dataset_flow_identity_capture_target_guards as guard
            where guard.receipt_id = scope.receipt_id
              and ((guard.target_id = v_old_id
                  and guard.target_version = v_old_version)
                or (guard.target_id = v_new_id
                  and guard.target_version = v_new_version))
          )
        )
    ) into v_is_guarded;
    if v_is_guarded then
      raise exception using errcode = '55000',
        message = 'FLOW_IDENTITY_ACTIVE_SCOPE_FLOW_FENCE';
    end if;
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_table_name in ('flowproperties', 'unitgroups') then
    for v_actor in
      select distinct scope.actor_user_id
      from util.dataset_flow_identity_scopes as scope
      join util.dataset_flow_identity_capture_support_guards as guard
        on guard.receipt_id = scope.receipt_id
        and guard.support_table = tg_table_name
        and ((guard.support_id = v_old_id
            and guard.support_version = v_old_version)
          or (guard.support_id = v_new_id
            and guard.support_version = v_new_version))
      where scope.status in (
        'sealed', 'running', 'primary_complete', 'derivatives_pending'
      )
      order by scope.actor_user_id
    loop
      if not pg_try_advisory_xact_lock(hashtextextended(
        'dataset-flow-identity-actor:' || v_actor::text, 0
      )) then
        raise exception using errcode = '55P03',
          message = 'FLOW_IDENTITY_ACTIVE_SCOPE_ACTOR_FENCE_BUSY';
      end if;
    end loop;
    select exists (
      select 1
      from util.dataset_flow_identity_scopes as scope
      join util.dataset_flow_identity_capture_support_guards as guard
        on guard.receipt_id = scope.receipt_id
        and guard.support_table = tg_table_name
        and ((guard.support_id = v_old_id
            and guard.support_version = v_old_version)
          or (guard.support_id = v_new_id
            and guard.support_version = v_new_version))
      where scope.status in (
        'sealed', 'running', 'primary_complete', 'derivatives_pending'
      )
    ) into v_is_guarded;
    if v_is_guarded then
      raise exception using errcode = '55000',
        message = 'FLOW_IDENTITY_ACTIVE_SCOPE_SUPPORT_FENCE';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION private.dataset_flow_identity_active_fence() OWNER TO postgres;

--
-- Name: dataset_flow_identity_build_flow_guard_v2(uuid, jsonb, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_build_flow_guard_v2(p_actor uuid, p_endpoint jsonb, p_target boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_flow public.flows%rowtype;
  v_flowproperty public.flowproperties%rowtype;
  v_unitgroup public.unitgroups%rowtype;
  v_flow_properties jsonb;
  v_reference_internal_id text;
  v_fp_id uuid;
  v_fp_version text;
  v_ug_id uuid;
  v_ug_version text;
  v_reference_unit_internal_id text;
  v_payload_sha256 text;
  v_category_sha256 text;
  v_row_sha256 text;
  v_guard jsonb;
  v_reference jsonb;
  v_expected_uri text;
begin
  if p_actor is null
    or not private.dataset_flow_identity_exact_keys(
      p_endpoint,
      case when p_target
        then array['id', 'version', 'reference']
        else array['id', 'version', 'source_trace_sha256']
      end
    )
    or p_endpoint->>'id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_endpoint->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or (not p_target
      and p_endpoint->>'source_trace_sha256' !~ '^[a-f0-9]{64}$') then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_ENDPOINT_SCHEMA_MISMATCH';
  end if;

  if p_target then
    v_reference := p_endpoint->'reference';
    v_expected_uri := '../flows/' || (p_endpoint->>'id') || '_'
      || (p_endpoint->>'version') || '.xml';
    if not private.dataset_flow_identity_exact_keys(
        v_reference,
        array[
          '@refObjectId', '@type', '@uri', '@version',
          'common:shortDescription'
        ]
      )
      or exists (
        select 1
        from unnest(array[
          '@refObjectId', '@type', '@uri', '@version'
        ]) as field(name)
        where jsonb_typeof(v_reference->field.name) <> 'string'
      )
      or v_reference->>'@refObjectId' <> p_endpoint->>'id'
      or v_reference->>'@version' <> p_endpoint->>'version'
      or v_reference->>'@type' <> 'flow data set'
      or v_reference->>'@uri' <> v_expected_uri
      or not private.dataset_flow_identity_short_description_v2(
        v_reference->'common:shortDescription'
      ) then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_TARGET_REFERENCE_MISMATCH';
    end if;
  end if;

  select flow.* into v_flow
  from public.flows as flow
  where flow.id = (p_endpoint->>'id')::uuid
    and btrim(flow.version::text) = p_endpoint->>'version';

  if v_flow.id is null
    or v_flow.json is null or v_flow.json_ordered is null
    or v_flow.json::jsonb is distinct from v_flow.json_ordered::jsonb
    or (p_target and v_flow.state_code <> 100)
    or (not p_target and v_flow.state_code <> 0)
    or (p_target and (v_flow.user_id is null or v_flow.user_id = p_actor))
    or (not p_target and v_flow.user_id is distinct from p_actor)
    or v_flow.json #>>
      '{flowDataSet,flowInformation,dataSetInformation,common:UUID}'
      is distinct from p_endpoint->>'id'
    or v_flow.json #>>
      '{flowDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}'
      is distinct from p_endpoint->>'version'
    or v_flow.json #>>
      '{flowDataSet,modellingAndValidation,LCIMethod,typeOfDataSet}'
      is distinct from 'Elementary flow' then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_FLOW_LIVE_MISMATCH';
  end if;

  v_flow_properties := v_flow.json #> '{flowDataSet,flowProperties,flowProperty}';
  if jsonb_typeof(v_flow_properties) = 'object' then
    v_flow_properties := jsonb_build_array(v_flow_properties);
  end if;
  v_reference_internal_id := v_flow.json #>>
    '{flowDataSet,flowInformation,quantitativeReference,referenceToReferenceFlowProperty}';
  if jsonb_typeof(v_flow_properties) <> 'array'
    or nullif(v_reference_internal_id, '') is null then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_FLOW_PROPERTY_MISSING';
  end if;

  select
    (item.value #>> '{referenceToFlowPropertyDataSet,@refObjectId}')::uuid,
    item.value #>> '{referenceToFlowPropertyDataSet,@version}'
  into v_fp_id, v_fp_version
  from jsonb_array_elements(v_flow_properties) as item(value)
  where item.value->>'@dataSetInternalID' = v_reference_internal_id;

  select support.* into v_flowproperty
  from public.flowproperties as support
  where support.id = v_fp_id
    and btrim(support.version::text) = v_fp_version
    and (
      (
        p_target
        and support.state_code = 100
        and support.user_id is not null
        and support.user_id <> p_actor
      )
      or (
        not p_target
        and (
          support.state_code = 100
          or (support.user_id = p_actor and support.state_code = 0)
        )
      )
    );
  if v_flowproperty.id is null
    or v_flowproperty.json is null or v_flowproperty.json_ordered is null
    or v_flowproperty.json::jsonb
      is distinct from v_flowproperty.json_ordered::jsonb then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_FLOW_PROPERTY_INVALID';
  end if;

  begin
    v_ug_id := (v_flowproperty.json #>>
      '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@refObjectId}')::uuid;
    v_ug_version := v_flowproperty.json #>>
      '{flowPropertyDataSet,flowPropertiesInformation,quantitativeReference,referenceToReferenceUnitGroup,@version}';
  exception when others then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_UNIT_GROUP_REFERENCE_INVALID';
  end;

  select support.* into v_unitgroup
  from public.unitgroups as support
  where support.id = v_ug_id
    and btrim(support.version::text) = v_ug_version
    and (
      (
        p_target
        and support.state_code = 100
        and support.user_id is not null
        and support.user_id <> p_actor
      )
      or (
        not p_target
        and (
          support.state_code = 100
          or (support.user_id = p_actor and support.state_code = 0)
        )
      )
    );
  v_reference_unit_internal_id := v_unitgroup.json #>>
    '{unitGroupDataSet,unitGroupInformation,quantitativeReference,referenceToReferenceUnit}';
  if v_unitgroup.id is null
    or v_unitgroup.json is null or v_unitgroup.json_ordered is null
    or v_unitgroup.json::jsonb is distinct from v_unitgroup.json_ordered::jsonb
    or nullif(v_reference_unit_internal_id, '') is null
    or not exists (
      select 1
      from jsonb_array_elements(
        case jsonb_typeof(v_unitgroup.json #> '{unitGroupDataSet,units,unit}')
          when 'array' then v_unitgroup.json #> '{unitGroupDataSet,units,unit}'
          when 'object' then jsonb_build_array(
            v_unitgroup.json #> '{unitGroupDataSet,units,unit}'
          )
          else '[]'::jsonb
        end
      ) as unit_item(value)
      where unit_item.value->>'@dataSetInternalID'
          = v_reference_unit_internal_id
        and (unit_item.value->>'meanValue')::numeric = 1
    ) then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_REFERENCE_UNIT_INVALID';
  end if;

  v_payload_sha256 := util.dataset_flow_identity_sha256(
    v_flow.json_ordered::jsonb
  );
  v_category_sha256 := util.dataset_flow_identity_sha256(coalesce(
    v_flow.json #>
      '{flowDataSet,flowInformation,dataSetInformation,classificationInformation}',
    'null'::jsonb
  ));
  v_row_sha256 := private.dataset_flow_identity_row_sha256(
    v_flow.id, btrim(v_flow.version::text), v_flow.user_id,
    v_flow.state_code, v_flow.modified_at, v_payload_sha256
  );
  v_guard := jsonb_build_object(
    'id', v_flow.id,
    'version', btrim(v_flow.version::text),
    'user_id', v_flow.user_id,
    'state_code', v_flow.state_code,
    'modified_at', v_flow.modified_at,
    'payload_sha256', v_payload_sha256,
    'row_sha256', v_row_sha256,
    'flow_type', 'Elementary flow',
    'flow_property_id', v_fp_id,
    'flow_property_version', v_fp_version,
    'unit_group_id', v_ug_id,
    'unit_group_version', v_ug_version,
    'category_path_sha256', v_category_sha256
  );
  if p_target then
    if not (
      private.dataset_flow_identity_text_values(
        v_reference->'common:shortDescription'
      ) && private.dataset_flow_identity_text_values(
        v_flow.json #>
          '{flowDataSet,flowInformation,dataSetInformation,name,baseName}'
      )
    ) then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_TARGET_NAME_MISMATCH';
    end if;
    return v_guard || jsonb_build_object('reference', v_reference);
  end if;
  return v_guard || jsonb_build_object(
    'source_trace_sha256', p_endpoint->>'source_trace_sha256'
  );
end;
$_$;


ALTER FUNCTION private.dataset_flow_identity_build_flow_guard_v2(p_actor uuid, p_endpoint jsonb, p_target boolean) OWNER TO postgres;

--
-- Name: dataset_flow_identity_build_process_v2(uuid, jsonb, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_build_process_v2(p_actor uuid, p_intent jsonb, p_mappings jsonb, p_policy jsonb, p_supports jsonb, p_protected_closure_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_process public.processes%rowtype;
  v_before_payload jsonb;
  v_before_exchanges jsonb;
  v_after_exchanges jsonb;
  v_desired_payload jsonb;
  v_thin jsonb;
  v_mapping jsonb;
  v_before_exchange jsonb;
  v_after_exchange jsonb;
  v_source_reference jsonb;
  v_target_reference jsonb;
  v_rewrite jsonb;
  v_rewrites jsonb := '[]'::jsonb;
  v_collision jsonb;
  v_snapshot jsonb;
  v_before_payload_sha256 text;
  v_before_exchange_sha256 text;
  v_desired_payload_sha256 text;
  v_desired_exchange_sha256 text;
  v_manifest jsonb;
  v_validation jsonb;
begin
  if jsonb_typeof(p_mappings) <> 'object'
    or not private.dataset_flow_identity_exact_keys(p_mappings, array[
      'schema_version', 'mapping_count', 'mapping_guard_set_sha256',
      'mappings', 'by_ordinal', 'by_id', 'by_source'
    ])
    or p_mappings->>'schema_version'
      <> 'dataset-flow-identity-mapping-index.v2'
    or jsonb_typeof(p_mappings->'by_ordinal') <> 'object'
    or jsonb_typeof(p_mappings->'by_id') <> 'object'
    or jsonb_typeof(p_mappings->'by_source') <> 'object'
    or not private.dataset_flow_identity_exact_keys(p_intent, array[
      'ordinal', 'id', 'version', 'rewrites', 'process_schema'
    ])
    or jsonb_typeof(p_intent->'ordinal') <> 'number'
    or (p_intent->>'ordinal')::integer <= 0
    or p_intent->>'id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_intent->>'version' !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    or jsonb_typeof(p_intent->'rewrites') <> 'array'
    or jsonb_array_length(p_intent->'rewrites') <= 0
    or not private.dataset_flow_identity_exact_keys(
      p_intent->'process_schema', array['status', 'evidence_sha256']
    )
    or p_intent #>> '{process_schema,status}' <> 'pass'
    or p_intent #>> '{process_schema,evidence_sha256}'
      !~ '^[a-f0-9]{64}$' then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_INTENT_SCHEMA_MISMATCH';
  end if;

  select process.* into v_process
  from public.processes as process
  where process.id = (p_intent->>'id')::uuid
    and btrim(process.version::text) = p_intent->>'version'
    and process.user_id = p_actor and process.state_code = 0;
  if v_process.id is null
    or v_process.json is null or v_process.json_ordered is null
    or v_process.json::jsonb is distinct from v_process.json_ordered::jsonb then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_LIVE_MISMATCH';
  end if;
  v_before_payload := v_process.json_ordered::jsonb;
  v_before_exchanges := private.dataset_flow_identity_exchanges(v_before_payload);
  v_after_exchanges := v_before_exchanges;
  if v_before_exchanges is null then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_EXCHANGES_INVALID';
  end if;

  for v_thin in
    select item.value
    from jsonb_array_elements(p_intent->'rewrites')
      with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    if not private.dataset_flow_identity_exact_keys(v_thin, array[
        'ordinal', 'exchange_index', 'internal_id', 'direction',
        'mapping_ordinal'
      ])
      or jsonb_typeof(v_thin->'ordinal') <> 'number'
      or (v_thin->>'ordinal')::integer <= 0
      or jsonb_typeof(v_thin->'exchange_index') <> 'number'
      or (v_thin->>'exchange_index')::integer < 0
      or (v_thin->>'exchange_index')::integer
        >= jsonb_array_length(v_before_exchanges)
      or jsonb_typeof(v_thin->'mapping_ordinal') <> 'number'
      or (v_thin->>'mapping_ordinal')::integer <= 0
      or nullif(v_thin->>'internal_id', '') is null
      or v_thin->>'direction' not in ('Input', 'Output') then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_REWRITE_INTENT_MISMATCH';
    end if;
    v_mapping := p_mappings #> array[
      'by_ordinal', (v_thin->>'mapping_ordinal')::integer::text
    ];
    if v_mapping is null then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_REWRITE_MAPPING_MISSING';
    end if;
    v_before_exchange := v_after_exchanges->(v_thin->>'exchange_index')::integer;
    v_source_reference := private.dataset_flow_identity_reference(v_before_exchange);
    v_target_reference := v_mapping #> '{target,reference}';
    if v_before_exchange->>'@dataSetInternalID'
        is distinct from v_thin->>'internal_id'
      or v_before_exchange->>'exchangeDirection'
        is distinct from v_thin->>'direction'
      or v_source_reference->>'@refObjectId'
        is distinct from v_mapping #>> '{source,id}'
      or v_source_reference->>'@version'
        is distinct from v_mapping #>> '{source,version}'
      or not private.dataset_flow_identity_short_description_v2(
        v_source_reference->'common:shortDescription'
      )
      or not private.dataset_flow_identity_short_description_v2(
        v_target_reference->'common:shortDescription'
      ) then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_REWRITE_LOCATOR_DRIFT';
    end if;
    v_rewrite := jsonb_build_object(
      'ordinal', v_thin->'ordinal',
      'exchange_index', v_thin->'exchange_index',
      'internal_id', v_thin->>'internal_id',
      'direction', v_thin->>'direction',
      'mapping_id', v_mapping->>'mapping_id',
      'source_reference', v_source_reference,
      'target_reference', v_target_reference,
      'before_reference_sha256',
        util.dataset_flow_identity_sha256(v_source_reference),
      'after_reference_sha256',
        util.dataset_flow_identity_sha256(v_target_reference)
    );
    v_rewrites := v_rewrites || jsonb_build_array(v_rewrite);
    v_after_exchange := jsonb_set(
      v_before_exchange,
      '{referenceToFlowDataSet}',
      (v_before_exchange->'referenceToFlowDataSet') || v_target_reference,
      false
    );
    if v_after_exchange - 'referenceToFlowDataSet'
        is distinct from v_before_exchange - 'referenceToFlowDataSet'
      or (v_after_exchange->'referenceToFlowDataSet')
          - '@refObjectId' - '@type' - '@uri' - '@version'
          - 'common:shortDescription'
        is distinct from
        (v_before_exchange->'referenceToFlowDataSet')
          - '@refObjectId' - '@type' - '@uri' - '@version'
          - 'common:shortDescription' then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_FIVE_FIELD_BOUNDARY_FAILED';
    end if;
    v_after_exchanges := jsonb_set(
      v_after_exchanges,
      array[(v_thin->>'exchange_index')::integer::text],
      v_after_exchange,
      false
    );
  end loop;
  if jsonb_array_length(v_rewrites)
      <> jsonb_array_length(p_intent->'rewrites') then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_REWRITE_COUNT_MISMATCH';
  end if;

  v_collision := private.dataset_flow_identity_collision_ledger(
    v_after_exchanges, v_rewrites
  );
  v_desired_payload := private.dataset_flow_identity_replace_exchanges(
    v_before_payload, v_after_exchanges
  );
  v_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
  if v_desired_payload is null or v_snapshot is null then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_DESIRED_OR_DERIVATIVE_INVALID';
  end if;
  v_before_payload_sha256 := util.dataset_flow_identity_sha256(v_before_payload);
  v_before_exchange_sha256 := util.dataset_flow_identity_sha256(v_before_exchanges);
  v_desired_payload_sha256 := util.dataset_flow_identity_sha256(v_desired_payload);
  v_desired_exchange_sha256 := util.dataset_flow_identity_sha256(v_after_exchanges);
  v_manifest := jsonb_build_object(
    'ordinal', p_intent->'ordinal',
    'id', v_process.id,
    'version', btrim(v_process.version::text),
    'user_id', v_process.user_id,
    'state_code', v_process.state_code,
    'modified_at', v_process.modified_at,
    'model_id', v_process.model_id,
    'rule_verification', v_process.rule_verification,
    'before_row_sha256', util.dataset_flow_identity_sha256(jsonb_build_object(
      'id', v_process.id,
      'version', btrim(v_process.version::text),
      'user_id', v_process.user_id,
      'state_code', v_process.state_code,
      'modified_at', v_process.modified_at,
      'model_id', v_process.model_id,
      'rule_verification', v_process.rule_verification,
      'payload_sha256', v_before_payload_sha256
    )),
    'before_payload_sha256', v_before_payload_sha256,
    'before_exchange_set_sha256', v_before_exchange_sha256,
    'before_exchange_count', jsonb_array_length(v_before_exchanges),
    'desired_payload_sha256', v_desired_payload_sha256,
    'desired_exchange_set_sha256', v_desired_exchange_sha256,
    'rewrite_count', jsonb_array_length(v_rewrites),
    'rewrite_set_sha256',
      util.dataset_flow_identity_restricted_sha256_v2(v_rewrites),
    'rewrites', v_rewrites,
    'collision_ledger', v_collision,
    'collision_ledger_sha256',
      util.dataset_flow_identity_restricted_sha256_v2(v_collision),
    'derivative_baseline_snapshot_sha256', v_snapshot->>'snapshot_sha256',
    'process_schema', p_intent->'process_schema',
    'pending_blocker_closure_sha256', p_protected_closure_sha256
  );
  v_manifest := v_manifest || jsonb_build_object(
    'process_template_sha256',
      util.dataset_flow_identity_restricted_sha256_v2(v_manifest)
  );
  v_validation := util.dataset_flow_identity_dry_validate_process(
    p_actor, v_manifest, p_mappings, p_policy, p_supports
  );
  if coalesce((v_validation->>'ok')::boolean, false) is false then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROCESS_DRY_VALIDATION_FAILED';
  end if;
  return v_manifest;
end;
$_$;


ALTER FUNCTION private.dataset_flow_identity_build_process_v2(p_actor uuid, p_intent jsonb, p_mappings jsonb, p_policy jsonb, p_supports jsonb, p_protected_closure_sha256 text) OWNER TO postgres;

--
-- Name: dataset_flow_identity_build_protected_v2(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_build_protected_v2(p_actor uuid, p_intent jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_partition text;
  v_entry jsonb;
  v_occurrence jsonb;
  v_process public.processes%rowtype;
  v_exchanges jsonb;
  v_exchange jsonb;
  v_reference jsonb;
  v_occurrences jsonb;
  v_entries jsonb;
  v_pending jsonb := '[]'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_orphans jsonb := '[]'::jsonb;
  v_result jsonb;
  v_validation jsonb;
begin
  if not private.dataset_flow_identity_exact_keys(
      p_intent, array['schema_version', 'pending', 'blockers', 'orphans']
    )
    or p_intent->>'schema_version'
      <> 'dataset-flow-identity-protected-intent.v2'
    or jsonb_typeof(p_intent->'pending') <> 'array'
    or jsonb_typeof(p_intent->'blockers') <> 'array'
    or jsonb_typeof(p_intent->'orphans') <> 'array' then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROTECTED_SCHEMA_MISMATCH';
  end if;

  foreach v_partition in array array['pending', 'blockers'] loop
    v_entries := '[]'::jsonb;
    for v_entry in
      select item.value
      from jsonb_array_elements(p_intent->v_partition)
        with ordinality as item(value, ordinality)
      order by item.ordinality
    loop
      if not private.dataset_flow_identity_exact_keys(v_entry, array[
          'source_id', 'source_version', 'expected_reference_count',
          'occurrences', 'evidence_sha256'
        ])
        or v_entry->>'source_id'
          !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or v_entry->>'source_version'
          !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
        or v_entry->>'evidence_sha256' !~ '^[a-f0-9]{64}$'
        or jsonb_typeof(v_entry->'expected_reference_count') <> 'number'
        or (v_entry->>'expected_reference_count')::integer < 0
        or jsonb_typeof(v_entry->'occurrences') <> 'array'
        or jsonb_array_length(v_entry->'occurrences')
          <> (v_entry->>'expected_reference_count')::integer then
        raise exception using errcode = '22023',
          message = 'FLOW_IDENTITY_CAPTURE_PROTECTED_ENTRY_MISMATCH';
      end if;
      v_occurrences := '[]'::jsonb;
      for v_occurrence in
        select item.value
        from jsonb_array_elements(v_entry->'occurrences') as item(value)
        order by item.value->>'process_id', item.value->>'process_version',
          (item.value->>'exchange_index')::integer
      loop
        if not private.dataset_flow_identity_exact_keys(v_occurrence, array[
            'process_id', 'process_version', 'exchange_index', 'internal_id',
            'direction'
          ])
          or v_occurrence->>'process_id'
            !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or v_occurrence->>'process_version'
            !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
          or jsonb_typeof(v_occurrence->'exchange_index') <> 'number'
          or (v_occurrence->>'exchange_index')::integer < 0
          or nullif(v_occurrence->>'internal_id', '') is null
          or v_occurrence->>'direction' not in ('Input', 'Output') then
          raise exception using errcode = '22023',
            message = 'FLOW_IDENTITY_CAPTURE_PROTECTED_OCCURRENCE_MISMATCH';
        end if;
        select process.* into v_process
        from public.processes as process
        where process.id = (v_occurrence->>'process_id')::uuid
          and btrim(process.version::text) = v_occurrence->>'process_version'
          and process.user_id = p_actor and process.state_code = 0;
        v_exchanges := private.dataset_flow_identity_exchanges(
          v_process.json_ordered::jsonb
        );
        if v_process.id is null
          or v_process.json is null or v_process.json_ordered is null
          or v_process.json::jsonb is distinct from v_process.json_ordered::jsonb
          or (v_occurrence->>'exchange_index')::integer
            >= coalesce(jsonb_array_length(v_exchanges), 0) then
          raise exception using errcode = '22023',
            message = 'FLOW_IDENTITY_CAPTURE_PROTECTED_PROCESS_MISMATCH';
        end if;
        v_exchange := v_exchanges->(v_occurrence->>'exchange_index')::integer;
        v_reference := private.dataset_flow_identity_reference(v_exchange);
        if v_exchange->>'@dataSetInternalID'
            is distinct from v_occurrence->>'internal_id'
          or v_exchange->>'exchangeDirection'
            is distinct from v_occurrence->>'direction'
          or v_reference->>'@refObjectId'
            is distinct from v_entry->>'source_id'
          or v_reference->>'@version'
            is distinct from v_entry->>'source_version'
          or not private.dataset_flow_identity_short_description_v2(
            v_reference->'common:shortDescription'
          ) then
          raise exception using errcode = '22023',
            message = 'FLOW_IDENTITY_CAPTURE_PROTECTED_LOCATOR_DRIFT';
        end if;
        v_occurrences := v_occurrences || jsonb_build_array(
          v_occurrence || jsonb_build_object(
            'reference_sha256', util.dataset_flow_identity_sha256(v_reference)
          )
        );
      end loop;
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'source_id', v_entry->>'source_id',
        'source_version', v_entry->>'source_version',
        'expected_reference_count', jsonb_array_length(v_occurrences),
        'occurrences', v_occurrences,
        'occurrence_set_sha256',
          util.dataset_flow_identity_restricted_sha256_v2(v_occurrences),
        'evidence_sha256', v_entry->>'evidence_sha256'
      ));
    end loop;
    if v_partition = 'pending' then
      v_pending := v_entries;
    else
      v_blockers := v_entries;
    end if;
  end loop;

  select coalesce(jsonb_agg(jsonb_build_object(
    'source_id', item.value->>'source_id',
    'source_version', item.value->>'source_version',
    'evidence_sha256', item.value->>'evidence_sha256'
  ) order by item.ordinality), '[]'::jsonb)
  into v_orphans
  from jsonb_array_elements(p_intent->'orphans')
    with ordinality as item(value, ordinality)
  where private.dataset_flow_identity_exact_keys(
      item.value, array['source_id', 'source_version', 'evidence_sha256']
    )
    and item.value->>'source_id'
      ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and item.value->>'source_version'
      ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
    and item.value->>'evidence_sha256' ~ '^[a-f0-9]{64}$';
  if jsonb_array_length(v_orphans)
      <> jsonb_array_length(p_intent->'orphans') then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_ORPHAN_SCHEMA_MISMATCH';
  end if;
  v_result := jsonb_build_object(
    'schema_version', 'dataset-flow-identity-protected-closure.v1',
    'pending', v_pending,
    'blockers', v_blockers,
    'orphans', v_orphans,
    'pending_set_sha256',
      util.dataset_flow_identity_restricted_sha256_v2(v_pending),
    'blocker_set_sha256',
      util.dataset_flow_identity_restricted_sha256_v2(v_blockers),
    'orphan_set_sha256',
      util.dataset_flow_identity_restricted_sha256_v2(v_orphans),
    'total_expected_reference_count',
      coalesce((select sum((item.value->>'expected_reference_count')::integer)
        from jsonb_array_elements(v_pending || v_blockers) as item(value)), 0)
  );
  v_validation := util.dataset_flow_identity_protected_closure(p_actor, v_result);
  if coalesce((v_validation->>'ok')::boolean, false) is false then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_PROTECTED_LIVE_MISMATCH';
  end if;
  return v_result;
end;
$_$;


ALTER FUNCTION private.dataset_flow_identity_build_protected_v2(p_actor uuid, p_intent jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_build_support_set_v2(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_build_support_set_v2(p_actor uuid, p_mappings jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb := '[]'::jsonb;
  v_claim record;
  v_flowproperty public.flowproperties%rowtype;
  v_unitgroup public.unitgroups%rowtype;
  v_payload jsonb;
  v_user_id uuid;
  v_state_code integer;
  v_modified_at timestamp with time zone;
  v_payload_sha256 text;
  v_row_sha256 text;
  v_ordinal integer := 0;
  v_validation jsonb;
begin
  for v_claim in
    with endpoint as (
      select guard.value
      from jsonb_array_elements(p_mappings) as mapping(value)
      cross join lateral jsonb_array_elements(jsonb_build_array(
        mapping.value->'source', mapping.value->'target'
      )) as guard(value)
    ), claimed as (
      select 'flowproperties'::text as support_table,
        (value->>'flow_property_id')::uuid as id,
        value->>'flow_property_version' as version
      from endpoint
      union
      select 'unitgroups', (value->>'unit_group_id')::uuid,
        value->>'unit_group_version'
      from endpoint
    )
    select * from claimed order by support_table, id, version
  loop
    v_ordinal := v_ordinal + 1;
    if v_claim.support_table = 'flowproperties' then
      select support.* into v_flowproperty
      from public.flowproperties as support
      where support.id = v_claim.id
        and btrim(support.version::text) = v_claim.version;
      if v_flowproperty.id is null
        or v_flowproperty.json is null or v_flowproperty.json_ordered is null
        or v_flowproperty.json::jsonb
          is distinct from v_flowproperty.json_ordered::jsonb then
        raise exception using errcode = '22023',
          message = 'FLOW_IDENTITY_CAPTURE_SUPPORT_INVALID';
      end if;
      v_payload := v_flowproperty.json_ordered::jsonb;
      v_user_id := v_flowproperty.user_id;
      v_state_code := v_flowproperty.state_code;
      v_modified_at := v_flowproperty.modified_at;
    else
      select support.* into v_unitgroup
      from public.unitgroups as support
      where support.id = v_claim.id
        and btrim(support.version::text) = v_claim.version;
      if v_unitgroup.id is null
        or v_unitgroup.json is null or v_unitgroup.json_ordered is null
        or v_unitgroup.json::jsonb
          is distinct from v_unitgroup.json_ordered::jsonb then
        raise exception using errcode = '22023',
          message = 'FLOW_IDENTITY_CAPTURE_SUPPORT_INVALID';
      end if;
      v_payload := v_unitgroup.json_ordered::jsonb;
      v_user_id := v_unitgroup.user_id;
      v_state_code := v_unitgroup.state_code;
      v_modified_at := v_unitgroup.modified_at;
    end if;
    if v_state_code not in (0, 100)
      or (v_state_code = 0 and v_user_id is distinct from p_actor) then
      raise exception using errcode = '22023',
        message = 'FLOW_IDENTITY_CAPTURE_SUPPORT_VISIBILITY_MISMATCH';
    end if;
    v_payload_sha256 := util.dataset_flow_identity_sha256(v_payload);
    v_row_sha256 := private.dataset_flow_identity_row_sha256(
      v_claim.id, v_claim.version, v_user_id, v_state_code,
      v_modified_at, v_payload_sha256
    );
    v_result := v_result || jsonb_build_array(jsonb_build_object(
      'ordinal', v_ordinal,
      'table', v_claim.support_table,
      'id', v_claim.id,
      'version', v_claim.version,
      'user_id', v_user_id,
      'state_code', v_state_code,
      'modified_at', v_modified_at,
      'payload_sha256', v_payload_sha256,
      'row_sha256', v_row_sha256
    ));
  end loop;
  v_validation := util.dataset_flow_identity_validate_support_set(
    p_actor, v_result, util.dataset_flow_identity_sha256(v_result)
  );
  if coalesce((v_validation->>'ok')::boolean, false) is false then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_CAPTURE_SUPPORT_SET_INVALID';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION private.dataset_flow_identity_build_support_set_v2(p_actor uuid, p_mappings jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_collision_ledger(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_collision_ledger(p_exchanges jsonb, p_rewrites jsonb) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO ''
    AS $$
  with touched as (
    select distinct
      rewrite.value #>> '{target_reference,@refObjectId}' as target_id,
      rewrite.value #>> '{target_reference,@version}' as target_version
    from jsonb_array_elements(p_rewrites) as rewrite(value)
  ), matching as (
    select
      touched.target_id,
      touched.target_version,
      (exchange.ordinality - 1)::integer as exchange_index,
      exchange.value->>'@dataSetInternalID' as internal_id,
      rewrite.value->>'mapping_id' as mapping_id
    from touched
    join lateral jsonb_array_elements(p_exchanges)
      with ordinality as exchange(value, ordinality)
      on exchange.value #>> '{referenceToFlowDataSet,@refObjectId}'
          = touched.target_id
        and exchange.value #>> '{referenceToFlowDataSet,@version}'
          = touched.target_version
    left join lateral (
      select candidate.value
      from jsonb_array_elements(p_rewrites) as candidate(value)
      where (candidate.value->>'exchange_index')::integer
        = exchange.ordinality - 1
      limit 1
    ) as rewrite on true
  ), grouped as (
    select
      matching.target_id,
      matching.target_version,
      count(*)::integer as multiplicity,
      jsonb_agg(matching.exchange_index order by matching.exchange_index)
        as exchange_indexes,
      jsonb_agg(matching.internal_id order by matching.exchange_index)
        as internal_ids,
      jsonb_agg(to_jsonb(matching.mapping_id)
        order by matching.exchange_index) as mapping_ids
    from matching
    group by matching.target_id, matching.target_version
    having count(*) > 1
  )
  select jsonb_build_object(
    'schema_version', 'dataset-flow-identity-collision-ledger.v1',
    'entries', coalesce(jsonb_agg(jsonb_build_object(
      'target_id', grouped.target_id,
      'target_version', grouped.target_version,
      'exchange_indexes', grouped.exchange_indexes,
      'internal_ids', grouped.internal_ids,
      'mapping_ids', grouped.mapping_ids,
      'preserve_rows', true
    ) order by grouped.target_id, grouped.target_version), '[]'::jsonb)
  )
  from grouped
$$;


ALTER FUNCTION private.dataset_flow_identity_collision_ledger(p_exchanges jsonb, p_rewrites jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_exact_keys(jsonb, text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_exact_keys(p_value jsonb, p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select jsonb_typeof(p_value) = 'object'
    and p_value ?& p_keys
    and not exists (
      select 1
      from jsonb_object_keys(p_value) as actual(key)
      where actual.key <> all (p_keys)
    )
$$;


ALTER FUNCTION private.dataset_flow_identity_exact_keys(p_value jsonb, p_keys text[]) OWNER TO postgres;

--
-- Name: dataset_flow_identity_exchanges(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_exchanges(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE STRICT
    SET search_path TO ''
    AS $$
declare
  v_exchange jsonb := p_payload #> '{processDataSet,exchanges,exchange}';
begin
  if jsonb_typeof(v_exchange) = 'array' then
    return v_exchange;
  elsif jsonb_typeof(v_exchange) = 'object' then
    return jsonb_build_array(v_exchange);
  end if;
  return null;
end;
$$;


ALTER FUNCTION private.dataset_flow_identity_exchanges(p_payload jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_invalidate_wrapper_permit_v1(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_invalidate_wrapper_permit_v1(p_invocation_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_token text := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
begin
  update util.dataset_flow_identity_wrapper_invocations
  set generation = generation + 1,
    token_sha256 =
      private.dataset_flow_identity_permit_token_sha256_v1(v_token),
    status = 'superseded',
    updated_at = clock_timestamp(),
    closed_at = clock_timestamp()
  where id = p_invocation_id and status = 'active';
  if not found then
    raise exception using errcode = 'P0001',
      message = 'FLOW_IDENTITY_WRAPPER_PERMIT_INVALIDATE_FAILED';
  end if;
end;
$$;


ALTER FUNCTION private.dataset_flow_identity_invalidate_wrapper_permit_v1(p_invocation_id uuid) OWNER TO postgres;

--
-- Name: dataset_flow_identity_mapping_index_v2(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_mapping_index_v2(p_mappings jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE STRICT
    SET search_path TO ''
    AS $_$
declare
  v_count integer;
  v_distinct_ordinals integer;
  v_distinct_ids integer;
  v_distinct_sources integer;
  v_by_ordinal jsonb;
  v_by_id jsonb;
  v_by_source jsonb;
begin
  if jsonb_typeof(p_mappings) <> 'array'
    or jsonb_array_length(p_mappings) not between 1 and 305 then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_MAPPING_INDEX_ARRAY_INVALID';
  end if;
  select
    count(*)::integer,
    count(distinct item.value->>'ordinal')::integer,
    count(distinct item.value->>'mapping_id')::integer,
    count(distinct (item.value #>> '{source,id}') || '@'
      || (item.value #>> '{source,version}'))::integer,
    jsonb_object_agg(item.value->>'ordinal', item.value),
    jsonb_object_agg(item.value->>'mapping_id', item.value),
    jsonb_object_agg(
      (item.value #>> '{source,id}') || '@'
        || (item.value #>> '{source,version}'), item.value
    )
  into v_count, v_distinct_ordinals, v_distinct_ids, v_distinct_sources,
    v_by_ordinal, v_by_id, v_by_source
  from jsonb_array_elements(p_mappings) as item(value)
  where jsonb_typeof(item.value->'ordinal') = 'number'
    and (item.value->>'ordinal')::numeric between 1 and 305
    and item.value->>'mapping_id' ~ '^[a-f0-9]{64}$';
  if v_count <> jsonb_array_length(p_mappings)
    or v_distinct_ordinals <> v_count
    or v_distinct_ids <> v_count
    or v_distinct_sources <> v_count then
    raise exception using errcode = '22023',
      message = 'FLOW_IDENTITY_MAPPING_INDEX_IDENTITY_INVALID';
  end if;
  return jsonb_build_object(
    'schema_version', 'dataset-flow-identity-mapping-index.v2',
    'mapping_count', v_count,
    'mapping_guard_set_sha256',
      util.dataset_flow_identity_restricted_sha256_v2(p_mappings),
    'mappings', p_mappings,
    'by_ordinal', v_by_ordinal,
    'by_id', v_by_id,
    'by_source', v_by_source
  );
end;
$_$;


ALTER FUNCTION private.dataset_flow_identity_mapping_index_v2(p_mappings jsonb) OWNER TO postgres;

--
-- Name: dataset_flow_identity_permit_token_sha256_v1(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_permit_token_sha256_v1(p_token text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(p_token, 'UTF8'), 'sha256'),
    'hex'
  )
$$;


ALTER FUNCTION private.dataset_flow_identity_permit_token_sha256_v1(p_token text) OWNER TO postgres;

--
-- Name: dataset_flow_identity_process_rewrite_core_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.dataset_flow_identity_process_rewrite_core_v1(p_scope_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET statement_timeout TO '60s'
    AS $_$
declare
  v_command constant text :=
    'cmd_dataset_flow_identity_process_rewrite_guarded';
  v_schema_version constant text :=
    'dataset-flow-identity-process-rewrite.v1';
  v_result_schema_version constant text :=
    'dataset-flow-identity-process-rewrite-result.v1';
  v_top_keys constant text[] := array[
    'schema_version', 'request_id', 'scope_proof_sha256', 'ordinal',
    'process', 'rewrites', 'collision_ledger', 'collision_ledger_sha256',
    'process_request_sha256'
  ];
  v_rewrite_keys constant text[] := array[
    'ordinal', 'exchange_index', 'internal_id', 'direction', 'mapping_id',
    'source_reference', 'target_reference', 'before_reference_sha256',
    'after_reference_sha256'
  ];
  v_reference_keys constant text[] := array[
    '@refObjectId', '@type', '@uri', '@version',
    'common:shortDescription'
  ];
  v_actor uuid := auth.uid();
  v_scope util.dataset_flow_identity_scopes%rowtype;
  v_ledger util.dataset_flow_identity_process_ledger%rowtype;
  v_process public.processes%rowtype;
  v_committed public.processes%rowtype;
  v_mapping util.dataset_flow_identity_mappings%rowtype;
  v_rewrite jsonb;
  v_mapping_validation jsonb;
  v_process_validation jsonb;
  v_before_payload jsonb;
  v_desired_payload jsonb;
  v_before_exchanges jsonb;
  v_after_exchanges jsonb;
  v_before_exchange jsonb;
  v_after_exchange jsonb;
  v_before_reference jsonb;
  v_after_reference jsonb;
  v_collision_ledger jsonb;
  v_internal_request_sha256 text;
  v_request_sha256 text;
  v_before_payload_sha256 text;
  v_after_payload_sha256 text;
  v_after_exchange_sha256 text;
  v_baseline_snapshot jsonb;
  v_after_snapshot jsonb;
  v_derivative_targets jsonb;
  v_derivative_result jsonb;
  v_derivative_batch_id uuid;
  v_derivative_reason_code text;
  v_audit_id bigint;
  v_next_ordinal integer;
  v_remaining integer;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command, 'code', 'AUTH_REQUIRED',
      'status', 401, 'message', 'Authentication required'
    );
  end if;

  if p_scope_id is null
    or p_request is null
    or pg_column_size(p_request) > 8388608
    or not private.dataset_flow_identity_exact_keys(p_request, v_top_keys)
    or p_request->>'schema_version' <> v_schema_version
    or p_request->>'request_id'
      !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or p_request->>'scope_proof_sha256' !~ '^[a-f0-9]{64}$'
    or p_request->>'process_request_sha256' !~ '^[a-f0-9]{64}$'
    or p_request->>'collision_ledger_sha256' !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_request->'ordinal') <> 'number'
    or (p_request->>'ordinal')::integer <= 0
    or jsonb_typeof(p_request->'rewrites') <> 'array'
    or jsonb_array_length(p_request->'rewrites') <= 0
    or jsonb_array_length(p_request->'rewrites') > 10000 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_INVALID_REQUEST',
      'status', 400, 'message', 'Step 3 process request schema mismatch'
    );
  end if;

  v_internal_request_sha256 :=
    util.dataset_flow_identity_restricted_sha256_v2(
    p_request - 'process_request_sha256'
  );
  if v_internal_request_sha256 is distinct from
    p_request->>'process_request_sha256'
    or util.dataset_flow_identity_restricted_sha256_v2(
      p_request->'collision_ledger'
    )
      is distinct from p_request->>'collision_ledger_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_REQUEST_HASH_MISMATCH',
      'status', 409, 'message', 'Process or collision request hash mismatch'
    );
  end if;
  v_request_sha256 := coalesce(nullif(current_setting(
    'app.dataset_flow_identity_v2_process_request_sha256', true
  ), ''), v_internal_request_sha256);
  if v_request_sha256 !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_REQUEST_HASH_MISMATCH',
      'status', 409, 'message', 'External v2 request hash is invalid'
    );
  end if;

  if not pg_try_advisory_xact_lock(
    hashtextextended('dataset-flow-identity:' || p_scope_id::text, 0)
  ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_SCOPE_BUSY', 'status', 409,
      'message', 'Another process transaction currently owns this scope'
    );
  end if;

  select scope.*
  into v_scope
  from util.dataset_flow_identity_scopes as scope
  where scope.id = p_scope_id
    and scope.actor_user_id = v_actor
  for update;

  if v_scope.id is null then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_NOT_FOUND', 'status', 404,
      'message', 'No actor-owned Step 3 scope exists'
    );
  end if;
  if v_scope.scope_proof_sha256 is distinct from
      p_request->>'scope_proof_sha256'
    or v_scope.status in ('failed', 'cancelled') then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_SCOPE_PROOF_MISMATCH', 'status', 409,
      'message', 'Scope proof is invalid or scope is failed'
    );
  end if;

  select ledger.*
  into v_ledger
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = p_scope_id
    and ledger.ordinal = (p_request->>'ordinal')::integer
  for update;

  if v_ledger.scope_id is null
    or p_request->'process' is distinct from v_ledger.manifest
    or p_request->'rewrites' is distinct from v_ledger.manifest->'rewrites'
    or p_request->'collision_ledger'
      is distinct from v_ledger.manifest->'collision_ledger'
    or p_request #>> '{process,process_template_sha256}'
      is distinct from v_ledger.process_template_sha256 then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_MANIFEST_MISMATCH', 'status', 409,
      'message', 'Request does not match the sealed process manifest'
    );
  end if;

  if v_ledger.status = 'completed' then
    select process.*
    into v_committed
    from public.processes as process
    where process.id = v_ledger.process_id
      and btrim(process.version::text) = v_ledger.process_version
      and process.user_id = v_actor
      and process.state_code = 0;
    if v_ledger.process_request_sha256 is distinct from v_request_sha256
      or v_committed.id is null
      or util.dataset_flow_identity_sha256(v_committed.json_ordered::jsonb)
        is distinct from v_ledger.after_payload_sha256
      or util.dataset_flow_identity_sha256(
        private.dataset_flow_identity_exchanges(v_committed.json_ordered::jsonb)
      ) is distinct from v_ledger.after_exchange_set_sha256
      or not exists (
        select 1 from private.command_audit_log as audit
        where audit.id = v_ledger.audit_id
          and audit.actor_user_id = v_actor
          and audit.command = v_command
          and audit.payload->>'process_request_sha256' = v_request_sha256
          and audit.payload->>'derivative_batch_id'
            = v_ledger.derivative_batch_id::text
          and audit.payload->>'derivative_reason_code'
            = 'FLOW_IDENTITY_SCOPE:' || p_scope_id::text || ':'
              || v_ledger.ordinal::text
      )
      or not exists (
        select 1
        from util.dataset_derivative_rebuild_requests as child
        where child.actor_user_id = v_actor
          and child.batch_id = v_ledger.derivative_batch_id
          and child.target_table = 'processes'
          and child.target_id = v_ledger.process_id
          and child.target_version = v_ledger.process_version
          and child.reason_code = 'FLOW_IDENTITY_SCOPE:'
            || p_scope_id::text || ':' || v_ledger.ordinal::text
          and child.expected_json_ordered_sha256
            = util.dataset_derivative_rebuild_sha256(
              v_committed.json_ordered::jsonb::text
            )
      ) then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PROCESS_REPLAY_PROOF_MISMATCH', 'status', 409,
        'message', 'Completed process no longer has exact audit/live proof'
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'command', v_command,
      'schema_version', v_result_schema_version,
      'scope_id', p_scope_id, 'ordinal', v_ledger.ordinal,
      'process_id', v_ledger.process_id,
      'process_version', v_ledger.process_version,
      'process_request_sha256', v_request_sha256,
      'before_payload_sha256', v_ledger.before_payload_sha256,
      'after_payload_sha256', v_ledger.after_payload_sha256,
      'rewrite_count', v_ledger.rewrite_count,
      'audit_id', v_ledger.audit_id::text,
      'derivative_batch_id', v_ledger.derivative_batch_id,
      'status', 'completed', 'replay', true
    );
  elsif v_ledger.status <> 'pending' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_NOT_EXECUTABLE', 'status', 409,
      'message', 'Process ledger is not pending or exactly replayable'
    );
  end if;

  select min(ledger.ordinal)
  into v_next_ordinal
  from util.dataset_flow_identity_process_ledger as ledger
  where ledger.scope_id = p_scope_id and ledger.status = 'pending';
  if v_next_ordinal is distinct from v_ledger.ordinal then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_ORDINAL_MISMATCH', 'status', 409,
      'message', 'Processes must execute in sealed ordinal order',
      'next_ordinal', v_next_ordinal
    );
  end if;

  if jsonb_array_length(p_request->'rewrites') <> v_ledger.rewrite_count
    or util.dataset_flow_identity_restricted_sha256_v2(
      p_request->'rewrites'
    )
      is distinct from v_ledger.manifest->>'rewrite_set_sha256'
    or p_request->>'collision_ledger_sha256'
      is distinct from v_ledger.manifest->>'collision_ledger_sha256'
    or (
      select min((rewrite.value->>'ordinal')::integer) = 1
        and max((rewrite.value->>'ordinal')::integer) = v_ledger.rewrite_count
        and count(distinct (rewrite.value->>'ordinal')::integer)
          = v_ledger.rewrite_count
        and count(distinct (rewrite.value->>'exchange_index')::integer)
          = v_ledger.rewrite_count
      from jsonb_array_elements(p_request->'rewrites') as rewrite(value)
    ) is not true then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_REWRITE_SET_MISMATCH', 'status', 409,
      'message', 'Rewrite set does not match the sealed manifest'
    );
  end if;

  v_process_validation := util.dataset_flow_identity_validate_process_guard(
    v_actor, v_ledger.manifest
  );
  if coalesce((v_process_validation->>'ok')::boolean, false) is false then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_BASELINE_DRIFT', 'status', 409,
      'message', 'Owner-draft process drifted after scope seal',
      'details', v_process_validation
    );
  end if;

  select process.*
  into v_process
  from public.processes as process
  where process.id = v_ledger.process_id
    and btrim(process.version::text) = v_ledger.process_version
    and process.user_id = v_actor
    and process.state_code = 0
  for update;

  v_before_payload := v_process.json_ordered::jsonb;
  v_before_exchanges := private.dataset_flow_identity_exchanges(v_before_payload);
  v_after_exchanges := v_before_exchanges;
  v_before_payload_sha256 := util.dataset_flow_identity_sha256(v_before_payload);
  begin
    v_baseline_snapshot := util.dataset_derivative_rebuild_snapshot(v_process);
  exception when others then
    v_baseline_snapshot := null;
  end;
  if v_before_payload_sha256 is distinct from
      v_ledger.manifest->>'before_payload_sha256'
    or v_baseline_snapshot is null
    or v_baseline_snapshot->>'snapshot_sha256' is distinct from
      v_ledger.manifest->>'derivative_baseline_snapshot_sha256' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_LOCKED_BASELINE_DRIFT', 'status', 409,
      'message', 'Locked process no longer matches its baseline'
    );
  end if;

  for v_rewrite in
    select rewrite.value
    from jsonb_array_elements(p_request->'rewrites')
      with ordinality as rewrite(value, ordinality)
    order by rewrite.ordinality
  loop
    if not private.dataset_flow_identity_exact_keys(
        v_rewrite, v_rewrite_keys
      )
      or jsonb_typeof(v_rewrite->'ordinal') <> 'number'
      or jsonb_typeof(v_rewrite->'exchange_index') <> 'number'
      or (v_rewrite->>'exchange_index')::integer < 0
      or (v_rewrite->>'exchange_index')::integer
        >= jsonb_array_length(v_before_exchanges)
      or nullif(v_rewrite->>'internal_id', '') is null
      or v_rewrite->>'direction' not in ('Input', 'Output')
      or v_rewrite->>'mapping_id' !~ '^[a-f0-9]{64}$'
      or v_rewrite->>'before_reference_sha256' !~ '^[a-f0-9]{64}$'
      or v_rewrite->>'after_reference_sha256' !~ '^[a-f0-9]{64}$'
      or not private.dataset_flow_identity_exact_keys(
        v_rewrite->'source_reference', v_reference_keys
      )
      or not private.dataset_flow_identity_exact_keys(
        v_rewrite->'target_reference', v_reference_keys
      ) then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PROCESS_REWRITE_SCHEMA_MISMATCH', 'status', 400,
        'message', 'A rewrite locator or reference is invalid'
      );
    end if;

    select mapping.*
    into v_mapping
    from util.dataset_flow_identity_mappings as mapping
    where mapping.scope_id = p_scope_id
      and mapping.mapping_id = v_rewrite->>'mapping_id';
    if v_mapping.scope_id is null then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PROCESS_MAPPING_NOT_SEALED', 'status', 409,
        'message', 'Rewrite mapping is outside the sealed scope'
      );
    end if;

    v_mapping_validation := util.dataset_flow_identity_validate_mapping(
      v_actor, v_mapping.mapping, v_scope.compatibility_policy,
      v_scope.support_snapshots,
      v_mapping.ordinal
    );
    if coalesce((v_mapping_validation->>'ok')::boolean, false) is false then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PROCESS_MAPPING_DRIFT', 'status', 409,
        'message', 'A source/public/support mapping guard drifted',
        'details', v_mapping_validation
      );
    end if;

    v_before_exchange := v_after_exchanges ->
      (v_rewrite->>'exchange_index')::integer;
    v_before_reference := private.dataset_flow_identity_reference(
      v_before_exchange
    );
    if v_before_exchange->>'@dataSetInternalID'
        is distinct from v_rewrite->>'internal_id'
      or v_before_exchange->>'exchangeDirection'
        is distinct from v_rewrite->>'direction'
      or v_before_reference is distinct from v_rewrite->'source_reference'
      or util.dataset_flow_identity_sha256(v_before_reference)
        is distinct from v_rewrite->>'before_reference_sha256'
      or v_before_reference->>'@refObjectId'
        is distinct from v_mapping.source_id::text
      or v_before_reference->>'@version'
        is distinct from v_mapping.source_version
      or v_rewrite->'target_reference'
        is distinct from v_mapping.mapping #> '{target,reference}'
      or util.dataset_flow_identity_sha256(v_rewrite->'target_reference')
        is distinct from v_rewrite->>'after_reference_sha256' then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PROCESS_EXCHANGE_LOCATOR_DRIFT', 'status', 409,
        'message', 'An exchange locator or exact reference drifted'
      );
    end if;

    v_after_exchange := jsonb_set(
      v_before_exchange,
      '{referenceToFlowDataSet}',
      (v_before_exchange->'referenceToFlowDataSet')
        || v_rewrite->'target_reference',
      false
    );
    v_after_reference := private.dataset_flow_identity_reference(
      v_after_exchange
    );
    if v_after_reference is distinct from v_rewrite->'target_reference'
      or v_after_exchange - 'referenceToFlowDataSet'
        is distinct from v_before_exchange - 'referenceToFlowDataSet'
      or (v_after_exchange->'referenceToFlowDataSet')
          - '@refObjectId' - '@type' - '@uri' - '@version'
          - 'common:shortDescription'
        is distinct from
        (v_before_exchange->'referenceToFlowDataSet')
          - '@refObjectId' - '@type' - '@uri' - '@version'
          - 'common:shortDescription' then
      return jsonb_build_object(
        'ok', false, 'command', v_command,
        'code', 'FLOW_IDENTITY_PROCESS_FIVE_FIELD_BOUNDARY_FAILED',
        'status', 409,
        'message', 'Rewrite would change a non-approved exchange field'
      );
    end if;

    v_after_exchanges := jsonb_set(
      v_after_exchanges,
      array[(v_rewrite->>'exchange_index')::integer::text],
      v_after_exchange,
      false
    );
  end loop;

  v_collision_ledger := private.dataset_flow_identity_collision_ledger(
    v_after_exchanges, p_request->'rewrites'
  );
  if v_collision_ledger is distinct from p_request->'collision_ledger' then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_COLLISION_LEDGER_MISMATCH', 'status', 409,
      'message', 'Post-rewrite collision ledger is not exact'
    );
  end if;

  v_desired_payload := private.dataset_flow_identity_replace_exchanges(
    v_before_payload, v_after_exchanges
  );
  v_after_payload_sha256 := util.dataset_flow_identity_sha256(v_desired_payload);
  v_after_exchange_sha256 := util.dataset_flow_identity_sha256(v_after_exchanges);
  if v_desired_payload is null
    or jsonb_array_length(v_before_exchanges)
      <> jsonb_array_length(v_after_exchanges)
    or v_after_payload_sha256 is distinct from
      v_ledger.manifest->>'desired_payload_sha256'
    or v_after_exchange_sha256 is distinct from
      v_ledger.manifest->>'desired_exchange_set_sha256'
    or exists (
      select 1
      from util.dataset_flow_identity_mappings as mapping
      join lateral jsonb_array_elements(v_after_exchanges) as exchange(value)
        on exchange.value #>> '{referenceToFlowDataSet,@refObjectId}'
          = mapping.source_id::text
        and exchange.value #>> '{referenceToFlowDataSet,@version}'
          = mapping.source_version
      where mapping.scope_id = p_scope_id
    ) then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_DESIRED_CLOSURE_MISMATCH', 'status', 409,
      'message', 'Server-reconstructed desired process does not match the seal'
    );
  end if;

  insert into util.dataset_flow_identity_mutation_permits (
    transaction_id, scope_id, ordinal, process_id, process_version,
    mutation_nonce, before_payload_sha256, after_payload_sha256
  ) values (
    txid_current(), p_scope_id, v_ledger.ordinal, v_process.id,
    btrim(v_process.version::text), v_ledger.mutation_nonce,
    v_before_payload_sha256, v_after_payload_sha256
  );

  update public.processes
  set json_ordered = v_desired_payload::json
  where id = v_process.id
    and btrim(version::text) = btrim(v_process.version::text)
    and user_id = v_actor
    and state_code = 0
    and modified_at = v_process.modified_at
  returning * into v_committed;

  if v_committed.id is null then
    raise exception using
      errcode = '40001',
      message = 'Step 3 locked process update precondition was lost';
  end if;
  begin
    v_after_snapshot := util.dataset_derivative_rebuild_snapshot(v_committed);
  exception when others then
    v_after_snapshot := null;
  end;
  if v_after_snapshot is null
    or v_after_snapshot->>'json_sha256'
      is distinct from v_after_snapshot->>'json_ordered_sha256'
    or util.dataset_flow_identity_sha256(v_committed.json_ordered::jsonb)
      is distinct from v_after_payload_sha256 then
    raise exception using
      errcode = 'P0001',
      message = 'Step 3 committed process primary hash mismatch';
  end if;

  -- Generate and bind the protected derivative batch before the primary audit.
  -- The audit, request ledger, and admission therefore share one exact causal
  -- identifier even though the admission itself happens after the audit row.
  v_derivative_batch_id := gen_random_uuid();
  v_derivative_reason_code := 'FLOW_IDENTITY_SCOPE:'
    || p_scope_id::text || ':' || v_ledger.ordinal::text;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    v_command, v_actor, 'processes', v_process.id,
    btrim(v_process.version::text),
    jsonb_build_object(
      'record_type', 'process_rewrite',
      'schema_version', v_schema_version,
      'scope_id', p_scope_id,
      'scope_proof_sha256', v_scope.scope_proof_sha256,
      'operation_id', v_scope.operation_id,
      'plan_sha256', v_scope.plan_sha256,
      'ordinal', v_ledger.ordinal,
      'process_request_sha256', v_request_sha256,
      'process_template_sha256', v_ledger.process_template_sha256,
      'rewrite_set_sha256', v_ledger.manifest->>'rewrite_set_sha256',
      'collision_ledger_sha256',
        v_ledger.manifest->>'collision_ledger_sha256',
      'before_payload_sha256', v_before_payload_sha256,
      'after_payload_sha256', v_after_payload_sha256,
      'after_exchange_set_sha256', v_after_exchange_sha256,
      'rewrite_count', v_ledger.rewrite_count,
      'derivative_batch_id', v_derivative_batch_id,
      'derivative_reason_code', v_derivative_reason_code,
      'committed_modified_at', v_committed.modified_at,
      'hash_algorithm', 'sorted-key-compact-json-v1-sha256'
    )
  ) returning id into v_audit_id;

  v_derivative_targets := jsonb_build_array(jsonb_build_object(
    'table', 'processes',
    'id', v_committed.id,
    'version', btrim(v_committed.version::text),
    'expected_json_ordered_sha256',
      v_after_snapshot->>'json_ordered_sha256',
    'baseline_snapshot_sha256',
      v_ledger.manifest->>'derivative_baseline_snapshot_sha256'
  ));
  v_derivative_result := util.admit_dataset_derivative_rebuild_batch(
    v_actor,
    v_derivative_batch_id,
    v_scope.plan_sha256,
    v_scope.operation_id,
    v_derivative_reason_code,
    v_derivative_targets
  );
  if coalesce((v_derivative_result->>'ok')::boolean, false) is false
    or v_derivative_result->>'target_count' is distinct from '1'
    or v_derivative_result->>'process_count' is distinct from '1' then
    raise exception using
      errcode = 'P0001',
      message = 'Step 3 derivative admission mismatch';
  end if;

  update util.dataset_flow_identity_process_ledger
  set
    status = 'completed',
    process_request_sha256 = v_request_sha256,
    audit_id = v_audit_id,
    after_payload_sha256 = v_after_payload_sha256,
    after_exchange_set_sha256 = v_after_exchange_sha256,
    derivative_batch_id = v_derivative_batch_id,
    derivative_admission = v_derivative_result,
    completed_at = clock_timestamp()
  where scope_id = p_scope_id and ordinal = v_ledger.ordinal;

  -- Ordinals execute strictly in order, so after committing ordinal N the
  -- remaining primary count is exact without rescanning the whole ledger.
  v_remaining := v_scope.process_count - v_ledger.ordinal;
  update util.dataset_flow_identity_scopes
  set
    status = case when v_remaining = 0
      then 'derivatives_pending' else 'running' end,
    primary_completed_at = case when v_remaining = 0
      then clock_timestamp() else primary_completed_at end,
    updated_at = clock_timestamp()
  where id = p_scope_id;

  return jsonb_build_object(
    'ok', true, 'command', v_command,
    'schema_version', v_result_schema_version,
    'scope_id', p_scope_id, 'ordinal', v_ledger.ordinal,
    'process_id', v_process.id,
    'process_version', btrim(v_process.version::text),
    'process_request_sha256', v_request_sha256,
    'before_payload_sha256', v_before_payload_sha256,
    'after_payload_sha256', v_after_payload_sha256,
    'rewrite_count', v_ledger.rewrite_count,
    'audit_id', v_audit_id::text,
    'derivative_batch_id', v_derivative_batch_id,
    'status', 'completed', 'replay', false
  );
exception
  when lock_not_available then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_LOCK_BUSY', 'status', 409,
      'message', 'Process transaction could not acquire its bounded lock'
    );
  when others then
    return jsonb_build_object(
      'ok', false, 'command', v_command,
      'code', 'FLOW_IDENTITY_PROCESS_TRANSACTION_FAILED', 'status', 409,
      'message', sqlerrm, 'sqlstate', sqlstate,
      'primary_rolled_back', true, 'automatic_retry', false
    );
end;
$_$;


ALTER FUNCTION private.dataset_flow_identity_process_rewrite_core_v1(p_scope_id uuid, p_request jsonb) OWNER TO postgres;

--
-- Name: FUNCTION dataset_flow_identity_process_rewrite_core_v1(p_scope_id uuid, p_request jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.dataset_flow_identity_process_rewrite_core_v1(p_scope_id uuid, p_request jsonb) IS 'Actor-only, scope-serialized Step 3 transaction. It reconstructs one desired process by changing exactly five flow-reference fields at exact exchange indexes, preserves collision rows, records one unique audit, and admits one protected derivative rebuild atomically. Exact replay is proof-only; failed/lost mutations are never blindly retried.';


