CREATE FUNCTION private.hybrid_search_processes_v2_impl(query_text text, query_embedding text, filter_condition text DEFAULT ''::text, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 20, lexical_weight double precision DEFAULT 0.5, semantic_weight double precision DEFAULT 0.5, rrf_k integer DEFAULT 10, data_source text DEFAULT 'tg'::text, page_size integer DEFAULT 10, page_current integer DEFAULT 1, query_terms text[] DEFAULT NULL::text[]) RETURNS TABLE(id uuid, "json" jsonb, version character, modified_at timestamp with time zone, model_id uuid, team_id uuid, total_count bigint)
    LANGUAGE plpgsql
    SET statement_timeout TO '60s'
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    AS $$
declare
  candidate_limit integer;
  semantic_match_count integer;
  filter_condition_jsonb jsonb;
