-- Name: FUNCTION lca_enqueue_job(p_queue_name text, p_message jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.lca_enqueue_job(p_queue_name text, p_message jsonb) IS 'Disabled legacy LCA pgmq delivery entrypoint. Use public.worker_enqueue_job for new worker jobs.';


--
-- Name: lca_legacy_job_type(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lca_legacy_job_type(p_job_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select case lower(trim(coalesce(p_job_kind, '')))
    when 'lca.solve_one' then 'solve_one'
    when 'lca.solve_batch' then 'solve_batch'
    when 'lca.solve_all_unit' then 'solve_all_unit'
    when 'lca.build_snapshot' then 'build_snapshot'
    when 'lca.contribution_path' then 'analyze_contribution_path'
    when 'lca.factorization_prepare' then 'prepare_factorization'
    when 'lca.snapshot_gc' then 'snapshot_gc'
    when 'lca.result_gc' then 'result_gc'
    else null
  end
$$;


ALTER FUNCTION private.lca_legacy_job_type(p_job_kind text) OWNER TO postgres;

