--
-- Name: lcia_scope_closure_artifact_lifecycle_guard(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_artifact_lifecycle_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_old_expected_role text := case
    when tg_op = 'UPDATE'
    then private.lcia_scope_closure_artifact_role(old.artifact_type)
  end;
  v_new_expected_role text :=
    private.lcia_scope_closure_artifact_role(new.artifact_type);
begin
  if tg_op = 'INSERT'
     and v_new_expected_role is null
     and new.artifact_role is null then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and v_old_expected_role is null
     and v_new_expected_role is null
     and old.artifact_role is null
     and new.artifact_role is null then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.artifact_role := coalesce(new.artifact_role, v_new_expected_role);
    new.expires_at := coalesce(
      new.expires_at,
      coalesce(new.created_at, now()) + interval '7 days'
    );
    new.lifecycle_state := coalesce(
      new.lifecycle_state,
      case when new.expires_at <= now() then 'expired' else 'ready' end
    );
  else
    if new.artifact_type is distinct from old.artifact_type
       or new.artifact_role is distinct from old.artifact_role
       or new.created_at is distinct from old.created_at
       or new.expires_at is distinct from old.expires_at then
      raise exception 'scope_closure_artifact_identity_or_expiry_is_immutable'
        using errcode = '23514';
    end if;
    if old.lifecycle_state = 'deleted'
       and new.lifecycle_state is distinct from 'deleted' then
      raise exception 'scope_closure_artifact_deleted_is_terminal'
        using errcode = '23514';
    end if;
    if old.lifecycle_state = 'expired'
       and new.lifecycle_state not in ('expired', 'deleted') then
      raise exception 'scope_closure_artifact_cannot_return_to_ready'
        using errcode = '23514';
    end if;
    if old.lifecycle_state = 'ready'
       and new.lifecycle_state not in ('ready', 'expired') then
      raise exception 'scope_closure_artifact_invalid_transition'
        using errcode = '23514';
    end if;
  end if;
  if v_new_expected_role is null
     or new.artifact_role is distinct from v_new_expected_role
     or new.expires_at is null
     or new.expires_at > coalesce(new.created_at, now()) + interval '7 days'
     or new.lifecycle_state is null then
    raise exception 'invalid_scope_closure_artifact_lifecycle'
      using errcode = '23514';
  end if;
  if new.lifecycle_state = 'ready'
     and (
       nullif(trim(new.storage_bucket), '') is null
       or nullif(trim(new.storage_path), '') is null
       or new.content_type is null
       or new.byte_size is null
       or new.checksum_sha256 is null
     ) then
    raise exception 'scope_closure_artifact_ready_metadata_incomplete'
      using errcode = '23514';
  end if;
  if new.lifecycle_state = 'deleted' then
    new.deleted_at := coalesce(new.deleted_at, now());
    new.storage_bucket := null;
    new.storage_path := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.lcia_scope_closure_artifact_lifecycle_guard() OWNER TO postgres;

--
-- Name: lcia_scope_closure_artifact_role(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_artifact_role(p_artifact_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select case p_artifact_type
    when 'closure_report_xlsx' then 'closure_report'
    when 'closure_complete_machine_result' then 'complete_machine_result'
    when 'closure_bundle' then 'closure_bundle'
    else null
  end
$$;


ALTER FUNCTION private.lcia_scope_closure_artifact_role(p_artifact_type text) OWNER TO postgres;

--
-- Name: lcia_scope_closure_checks; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.lcia_scope_closure_checks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    worker_job_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    request_idempotency_token text NOT NULL,
    request_key text NOT NULL,
    request_fingerprint text NOT NULL,
    requested_scope_hash text NOT NULL,
    effective_scope_hash text,
    policy_fingerprint text NOT NULL,
    data_snapshot_token text NOT NULL,
    expected_validator_scanner_fingerprint text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    scan_completeness text,
    certificate_status text DEFAULT 'pending'::text NOT NULL,
    certificate_hash text,
    report_artifact_id uuid,
    result_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    blocker_codes text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    requested_scope_manifest jsonb,
    effective_scope_manifest jsonb,
    certificate_schema_version text,
    source_fingerprint text,
    resolution_map_hash text,
    closure_bundle_hash text,
    snapshot_id uuid,
    snapshot_hash text,
    report_artifact_manifest_hash text,
    evidence_hash text,
    scan_execution_id uuid,
    reused_from_check_id uuid,
    closure_bundle_artifact_id uuid,
    snapshot_artifact_id uuid,
    snapshot_index_sha256 text,
    snapshot_build_contract_hash text,
    complete_machine_result_artifact_id uuid,
    valid_until timestamp with time zone,
    result_set_id uuid,
    CONSTRAINT lcia_scope_closure_checks_certificate_check CHECK ((certificate_status = ANY (ARRAY['pending'::text, 'valid'::text, 'stale'::text, 'revoked'::text, 'unavailable'::text]))),
    CONSTRAINT lcia_scope_closure_checks_completeness_check CHECK (((scan_completeness IS NULL) OR (scan_completeness = ANY (ARRAY['complete'::text, 'incomplete'::text, 'unknown'::text])))),
    CONSTRAINT lcia_scope_closure_checks_effective_scope_manifest_check CHECK (((effective_scope_manifest IS NULL) OR (jsonb_typeof(effective_scope_manifest) = 'object'::text))),
    CONSTRAINT lcia_scope_closure_checks_hash_check CHECK (((length(TRIM(BOTH FROM requested_scope_hash)) > 0) AND (length(TRIM(BOTH FROM policy_fingerprint)) > 0))),
    CONSTRAINT lcia_scope_closure_checks_request_token_check CHECK (((length(TRIM(BOTH FROM request_idempotency_token)) >= 1) AND (length(TRIM(BOTH FROM request_idempotency_token)) <= 200))),
    CONSTRAINT lcia_scope_closure_checks_requested_scope_manifest_check CHECK (((requested_scope_manifest IS NULL) OR (jsonb_typeof(requested_scope_manifest) = 'object'::text))),
    CONSTRAINT lcia_scope_closure_checks_result_summary_check CHECK ((jsonb_typeof(result_summary) = 'object'::text)),
    CONSTRAINT lcia_scope_closure_checks_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'passed'::text, 'blocked'::text, 'failed'::text, 'cancelled'::text])))
);


ALTER TABLE private.lcia_scope_closure_checks OWNER TO postgres;

--
-- Name: COLUMN lcia_scope_closure_checks.snapshot_id; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.lcia_scope_closure_checks.snapshot_id IS 'Immutable certificate snapshot UUID. It is a soft audit reference after the certificate is stale or revoked and retention deletes the snapshot.';


--
-- Name: COLUMN lcia_scope_closure_checks.snapshot_artifact_id; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.lcia_scope_closure_checks.snapshot_artifact_id IS 'Ready numerical snapshot artifact UUID verified by record_result_v3 before signing and retained as a soft audit reference after stale or revoked evidence is garbage-collected.';


--
-- Name: COLUMN lcia_scope_closure_checks.complete_machine_result_artifact_id; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.lcia_scope_closure_checks.complete_machine_result_artifact_id IS 'Soft immutable link to the complete machine-readable closure result whose expiry bounds certificate admission.';


--
-- Name: COLUMN lcia_scope_closure_checks.valid_until; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.lcia_scope_closure_checks.valid_until IS 'Certificate admission deadline, bounded by every required closure evidence artifact.';


--
-- Name: COLUMN lcia_scope_closure_checks.result_set_id; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.lcia_scope_closure_checks.result_set_id IS 'Optional ResultSet container binding. NULL preserves legacy closure checks.';


--
-- Name: worker_job_artifacts; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.worker_job_artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    artifact_type text NOT NULL,
    storage_bucket text,
    storage_path text,
    content_type text,
    byte_size bigint,
    checksum_sha256 text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    visibility text DEFAULT 'operator'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    artifact_role text,
    lifecycle_state text,
    gc_claim_token uuid,
    gc_claimed_at timestamp with time zone,
    gc_claim_expires_at timestamp with time zone,
    gc_failure_count integer DEFAULT 0 NOT NULL,
    gc_last_error text,
    deleted_at timestamp with time zone,
    gc_cleanup_state text DEFAULT 'none'::text NOT NULL,
    CONSTRAINT worker_job_artifacts_artifact_role_check CHECK ((NOT (artifact_role IS DISTINCT FROM private.lcia_scope_closure_artifact_role(artifact_type)))),
    CONSTRAINT worker_job_artifacts_byte_size_check CHECK (((byte_size IS NULL) OR (byte_size >= 0))),
    CONSTRAINT worker_job_artifacts_checksum_check CHECK (((checksum_sha256 IS NULL) OR (checksum_sha256 ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT worker_job_artifacts_gc_cleanup_lifecycle_check CHECK ((((lifecycle_state = 'deleted'::text) AND (gc_cleanup_state = ANY (ARRAY['pending'::text, 'complete'::text]))) OR ((lifecycle_state IS DISTINCT FROM 'deleted'::text) AND (gc_cleanup_state = 'none'::text)) OR (artifact_role IS NULL))),
    CONSTRAINT worker_job_artifacts_gc_cleanup_state_check CHECK ((gc_cleanup_state = ANY (ARRAY['none'::text, 'pending'::text, 'complete'::text]))),
    CONSTRAINT worker_job_artifacts_gc_failure_count_check CHECK ((gc_failure_count >= 0)),
    CONSTRAINT worker_job_artifacts_lifecycle_state_check CHECK (((lifecycle_state IS NULL) OR (lifecycle_state = ANY (ARRAY['ready'::text, 'expired'::text, 'deleted'::text])))),
    CONSTRAINT worker_job_artifacts_metadata_object_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT worker_job_artifacts_visibility_check CHECK ((visibility = ANY (ARRAY['user'::text, 'operator'::text, 'system'::text])))
);


ALTER TABLE private.worker_job_artifacts OWNER TO postgres;

--
-- Name: COLUMN worker_job_artifacts.expires_at; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_job_artifacts.expires_at IS 'Trusted retention deadline. Scope-closure evidence expires no later than seven days after creation.';


--
-- Name: COLUMN worker_job_artifacts.artifact_role; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_job_artifacts.artifact_role IS 'Authoritative role for seven-day scope-closure evidence artifacts.';


--
-- Name: COLUMN worker_job_artifacts.gc_cleanup_state; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_job_artifacts.gc_cleanup_state IS 'DB-owned bounded detail-cleanup state: pending rows remain service-claimable after Storage object deletion.';


--
-- Name: lcia_scope_closure_artifact_lineage_eligible(private.lcia_scope_closure_checks, private.worker_job_artifacts, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_artifact_lineage_eligible(p_check private.lcia_scope_closure_checks, p_artifact private.worker_job_artifacts, p_public_artifact_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  select case p_public_artifact_role
    when 'closure_report_xlsx' then
      (p_artifact).id = (p_check).report_artifact_id
      and (p_artifact).job_id = (p_check).worker_job_id
      and (p_artifact).artifact_role = 'closure_report'
      and (p_artifact).artifact_type = 'closure_report_xlsx'
    when 'closure_issue_manifest' then
      (p_artifact).id = (p_check).complete_machine_result_artifact_id
      and (p_artifact).artifact_role = 'complete_machine_result'
      and (p_artifact).artifact_type = 'closure_complete_machine_result'
      and (
        (p_artifact).job_id = (p_check).worker_job_id
        or exists (
          select 1
          from private.lcia_scope_closure_checks source_check
          where source_check.id = (p_check).reused_from_check_id
            and source_check.worker_job_id = (p_artifact).job_id
        )
      )
    else false
  end
$$;


ALTER FUNCTION private.lcia_scope_closure_artifact_lineage_eligible(p_check private.lcia_scope_closure_checks, p_artifact private.worker_job_artifacts, p_public_artifact_role text) OWNER TO postgres;

--
-- Name: lcia_scope_closure_artifact_v2_descriptor_set(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_artifact_v2_descriptor_set(p_write_set_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'contractVersion', write_set.contract_version,
    'descriptors', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'ordinal', item.ordinal,
          'clientKey', item.client_key,
          'artifactType', item.artifact_type,
          'artifactRole', item.artifact_role,
          'bucket', item.storage_bucket,
          'objectPath', item.storage_path,
          'mediaType', item.content_type,
          'size', item.byte_size,
          'checksumSha256', item.checksum_sha256,
          'metadata', item.metadata
        )
        order by item.ordinal
      )
      from private.lcia_scope_closure_artifact_write_set_items item
      where item.write_set_id = write_set.id
    ), '[]'::jsonb)
  )
  from private.lcia_scope_closure_artifact_write_sets write_set
  where write_set.id = p_write_set_id
$$;


ALTER FUNCTION private.lcia_scope_closure_artifact_v2_descriptor_set(p_write_set_id uuid) OWNER TO postgres;

--
-- Name: lcia_scope_closure_artifact_v2_item_guard(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_artifact_v2_item_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_contract_version text;
  v_status text;
  v_write_set_id uuid := case
    when tg_op = 'DELETE' then old.write_set_id
    else new.write_set_id
  end;
begin
  select write_set.contract_version, write_set.status
  into v_contract_version, v_status
  from private.lcia_scope_closure_artifact_write_sets write_set
  where write_set.id = v_write_set_id;

  if v_contract_version is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op = 'INSERT' and v_status = 'registration_open' then
    return new;
  end if;
  raise exception 'artifact_write_set_v2_items_are_immutable'
    using errcode = '23514';
end;
$$;


ALTER FUNCTION private.lcia_scope_closure_artifact_v2_item_guard() OWNER TO postgres;

--
-- Name: lcia_scope_closure_artifact_v2_lease_sha256(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_artifact_v2_lease_sha256(p_lease_token uuid) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select encode(
    extensions.digest(convert_to(p_lease_token::text, 'UTF8'), 'sha256'),
    'hex'
  )
$$;


ALTER FUNCTION private.lcia_scope_closure_artifact_v2_lease_sha256(p_lease_token uuid) OWNER TO postgres;

