--
-- Name: lcia_scope_closure_build_admission_guard(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_build_admission_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_check private.lcia_scope_closure_checks%rowtype;
  v_check_id uuid;
begin
  if new.job_kind <> 'lcia_result.package_build'
     or new.payload_schema_version <> 'lcia_result.package_build.request.v2' then
    return new;
  end if;

  begin
    v_check_id := nullif(new.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'closure_certificate_expired_or_unavailable'
      using errcode = '23514';
  end;

  select * into v_check
  from private.lcia_scope_closure_checks
  where id = v_check_id
    and requested_by = new.requested_by;
  if v_check.id is null
     or not private.lcia_scope_closure_evidence_usable(v_check) then
    raise exception 'closure_certificate_expired_or_unavailable'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.lcia_scope_closure_build_admission_guard() OWNER TO postgres;

--
-- Name: lcia_scope_closure_bundle_binding_matches(private.lcia_scope_closure_checks, private.worker_job_artifacts); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_bundle_binding_matches(p_check private.lcia_scope_closure_checks, p_bundle private.worker_job_artifacts) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
  SELECT coalesce((
    (p_bundle).id = (p_check).closure_bundle_artifact_id
    AND (p_bundle).artifact_role = 'closure_bundle'
    AND (p_bundle).artifact_type = 'closure_bundle'
    AND (p_bundle).checksum_sha256 = (p_check).closure_bundle_hash
    AND (
      (
        (p_check).reused_from_check_id IS NULL
        AND (p_bundle).job_id = (p_check).worker_job_id
        AND coalesce((p_bundle).metadata->>'closureCheckId', '') = (p_check).id::text
      )
      OR EXISTS (
        SELECT 1
        FROM private.lcia_scope_closure_checks source
        WHERE source.id = (p_check).reused_from_check_id
          AND source.reused_from_check_id IS NULL
          AND source.status = 'passed'
          AND source.scan_completeness = 'complete'
          AND source.worker_job_id = (p_bundle).job_id
          AND source.closure_bundle_artifact_id = (p_bundle).id
          AND source.closure_bundle_hash = (p_check).closure_bundle_hash
          AND source.snapshot_id = (p_check).snapshot_id
          AND source.snapshot_hash = (p_check).snapshot_hash
          AND source.snapshot_artifact_id = (p_check).snapshot_artifact_id
          AND source.snapshot_index_sha256 = (p_check).snapshot_index_sha256
          AND source.snapshot_build_contract_hash = (p_check).snapshot_build_contract_hash
          AND source.effective_scope_hash = (p_check).effective_scope_hash
          AND source.requested_scope_hash = (p_check).requested_scope_hash
          AND source.policy_fingerprint = (p_check).policy_fingerprint
          AND source.data_snapshot_token = (p_check).data_snapshot_token
          AND coalesce((p_bundle).metadata->>'closureCheckId', '') = source.id::text
      )
    )
  ), false)
$$;


ALTER FUNCTION private.lcia_scope_closure_bundle_binding_matches(p_check private.lcia_scope_closure_checks, p_bundle private.worker_job_artifacts) OWNER TO postgres;

--
-- Name: lcia_scope_closure_candidate_dataset_manifest(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_candidate_dataset_manifest() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'datasetType', dataset_type,
      'datasetId', dataset_id,
      'datasetVersion', dataset_version,
      'role', role,
      -- Worker v2 requires all three hashes.  Candidate snapshots define each
      -- compatibility field over the exact frozen full document.
      'versionSignificantHash', canonical_content_hash,
      'semanticHash', canonical_content_hash,
      'canonicalContentHash', canonical_content_hash
    )
    order by dataset_type, dataset_id, dataset_version, role
  ), '[]'::jsonb)
  from private.lcia_scope_closure_candidate_document_hashes
$$;


