-- Name: FUNCTION lcia_scope_closure_worker_canonical_json_text(p_value jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.lcia_scope_closure_worker_canonical_json_text(p_value jsonb) IS 'Serializes JSON exactly as the scope-closure Worker canonical JSON writer: recursively sorted object keys, preserved array order, and compact separators.';


--
-- Name: lcia_scope_closure_worker_canonical_sha256(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lcia_scope_closure_worker_canonical_sha256(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select encode(
    extensions.digest(
      convert_to(
        private.lcia_scope_closure_worker_canonical_json_text(p_value),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
$$;


ALTER FUNCTION private.lcia_scope_closure_worker_canonical_sha256(p_value jsonb) OWNER TO postgres;

