--
-- Name: portal_search_v1(text, text, jsonb, text, text, integer); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.portal_search_v1(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE PARALLEL RESTRICTED
    SET search_path TO ''
    AS $_$
declare
  v_query text;
  v_filters jsonb;
  v_sort text;
  v_limit integer := coalesce(p_limit, 20);
  v_fingerprint text;
  v_cursor jsonb;
  v_cursor_rank text;
  v_cursor_id uuid;
  v_cursor_version text;
  v_kernel jsonb;
  v_next_cursor_payload jsonb;
begin
  perform private.assert_portal_catalog_projection_contract_v1();

  perform private.portal_validate_search_v1(
    p_kind,
    coalesce(p_query, ''),
    coalesce(p_filters, '{}'::jsonb),
    coalesce(p_sort, 'relevance'),
    v_limit
  );
  v_query := pg_catalog.lower(pg_catalog.btrim(coalesce(p_query, '')));
  v_filters := private.portal_normalize_filters_v1(p_filters);
  v_sort := pg_catalog.lower(pg_catalog.btrim(coalesce(p_sort, 'relevance')));
  v_fingerprint := private.portal_query_fingerprint_v1(
    p_kind,
    v_query,
    v_filters,
    v_sort
  );
  if p_cursor is not null then
    v_cursor := private.portal_cursor_decode_v1(p_cursor);
    if v_cursor is null
       or (select count(*) from pg_catalog.jsonb_object_keys(v_cursor)) <> 6
       or v_cursor ->> 'v' <> '1'
       or v_cursor ->> 'fp' <> v_fingerprint
       or v_cursor ->> 'kind' <> p_kind
       or coalesce(v_cursor ->> 'rankKey', '') = ''
       or coalesce(v_cursor ->> 'id', '')
         !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_cursor ->> 'version', '') !~ '^\d{2}\.\d{2}\.\d{3}$' then
      raise exception using errcode = '22023', message = 'invalid portal request';
    end if;
    v_cursor_rank := v_cursor ->> 'rankKey';
    v_cursor_id := (v_cursor ->> 'id')::uuid;
    v_cursor_version := v_cursor ->> 'version';
    if v_sort = 'relevance'
       and v_cursor_rank !~ '^(0(\.\d+)?|1(\.0+)?)$' then
      raise exception using errcode = '22023', message = 'invalid portal request';
    elsif v_sort = 'modified_desc'
       and private.portal_datetime_v1(v_cursor_rank) is null then
      raise exception using errcode = '22023', message = 'invalid portal request';
    end if;
  end if;

  if pg_catalog.char_length(v_query) = 1
     and v_filters = '{}'::jsonb
     and v_sort = 'relevance' then
    v_kernel := private.catalog_portal_single_character_search_v1_impl(
      p_kind,
      v_query,
      v_cursor_rank,
      v_cursor_id,
      v_cursor_version,
      v_limit,
      v_fingerprint
    );
  elsif p_kind = 'process'
     and pg_catalog.char_length(v_query) > 1
     and v_query !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and v_filters = '{}'::jsonb
     and v_sort = 'relevance' then
    perform private.assert_portal_process_keyword_rank_contract_v1();
    v_kernel := private.catalog_portal_process_keyword_relevance_v1_impl(
      v_query,
      v_cursor_rank,
      v_cursor_id,
      v_cursor_version,
      v_limit,
      v_fingerprint
    );
  else
    v_kernel := private.catalog_portal_search_v1_impl(
      p_kind,
      v_query,
      v_filters,
      v_sort,
      v_cursor_rank,
      v_cursor_id,
      v_cursor_version,
      v_limit,
      v_fingerprint
    );
  end if;

  v_next_cursor_payload := nullif(
    v_kernel -> 'nextCursorPayload',
    'null'::jsonb
  );

  return pg_catalog.jsonb_build_object(
    'schemaVersion', 'portal.public-search-page.v1',
    'kind', p_kind,
    'queryFingerprint', v_fingerprint,
    'items', coalesce(v_kernel -> 'items', '[]'::jsonb),
    'nextCursor', case when v_next_cursor_payload is null then null
      else private.portal_cursor_encode_v1(v_next_cursor_payload)
    end
  );
end
$_$;


ALTER FUNCTION private.portal_search_v1(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor text, p_limit integer) OWNER TO portal_public_executor;

--
-- Name: FUNCTION portal_search_v1(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor text, p_limit integer); Type: COMMENT; Schema: private; Owner: portal_public_executor
--

COMMENT ON FUNCTION private.portal_search_v1(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor text, p_limit integer) IS 'Validates public Search; routes one-code-point searches to the character child and unfiltered Process keyword relevance to bounded key selection before card hydration.';


--
-- Name: portal_search_v2(text, text, jsonb, text, text, integer); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.portal_search_v2(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE PARALLEL RESTRICTED
    SET search_path TO ''
    AS $_$
declare
  v_query text;
  v_filters jsonb;
  v_sort text;
  v_limit integer := coalesce(p_limit, 20);
  v_fingerprint text;
  v_cursor jsonb;
  v_cursor_rank text;
  v_cursor_id uuid;
  v_cursor_version text;
  v_kernel jsonb;
  v_next_cursor_payload jsonb;
begin
  perform private.assert_portal_catalog_projection_contract_v1();

  perform private.portal_validate_search_v1(
    p_kind,
    coalesce(p_query, ''),
    coalesce(p_filters, '{}'::jsonb),
    coalesce(p_sort, 'relevance'),
    v_limit
  );
  v_query := pg_catalog.lower(pg_catalog.btrim(coalesce(p_query, '')));
  v_filters := private.portal_normalize_filters_v1(p_filters);
  v_sort := pg_catalog.lower(pg_catalog.btrim(coalesce(p_sort, 'relevance')));
  v_fingerprint := private.portal_query_fingerprint_v1(
    p_kind,
    v_query,
    v_filters,
    v_sort
  );
  v_fingerprint := pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to('portal-search-versions-v2:' || v_fingerprint,'UTF8'),'sha256'),'hex');
  if p_cursor is not null then
    v_cursor := private.portal_cursor_decode_v1(p_cursor);
    if v_cursor is null
       or (select count(*) from pg_catalog.jsonb_object_keys(v_cursor)) <> 6
       or v_cursor ->> 'v' <> '1'
       or v_cursor ->> 'fp' <> v_fingerprint
       or v_cursor ->> 'kind' <> p_kind
       or coalesce(v_cursor ->> 'rankKey', '') = ''
       or coalesce(v_cursor ->> 'id', '')
         !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_cursor ->> 'version', '') !~ '^\d{2}\.\d{2}\.\d{3}$' then
      raise exception using errcode = '22023', message = 'invalid portal request';
    end if;
    v_cursor_rank := v_cursor ->> 'rankKey';
    v_cursor_id := (v_cursor ->> 'id')::uuid;
    v_cursor_version := v_cursor ->> 'version';
    if v_sort = 'relevance'
       and v_cursor_rank !~ '^(0(\.\d+)?|1(\.0+)?)$' then
      raise exception using errcode = '22023', message = 'invalid portal request';
    elsif v_sort = 'modified_desc'
       and private.portal_datetime_v1(v_cursor_rank) is null then
      raise exception using errcode = '22023', message = 'invalid portal request';
    end if;
  end if;

  v_kernel := private.catalog_portal_search_v2_impl(
    p_kind,v_query,v_filters,v_sort,v_cursor_rank,v_cursor_id,v_cursor_version,v_limit,v_fingerprint
  );

  v_next_cursor_payload := nullif(
    v_kernel -> 'nextCursorPayload',
    'null'::jsonb
  );

  return pg_catalog.jsonb_build_object(
    'schemaVersion', 'portal.public-search-page.v1',
    'kind', p_kind,
    'queryFingerprint', v_fingerprint,
    'items', coalesce(v_kernel -> 'items', '[]'::jsonb),
    'nextCursor', case when v_next_cursor_payload is null then null
      else private.portal_cursor_encode_v1(v_next_cursor_payload)
    end
  );
end
$_$;


ALTER FUNCTION private.portal_search_v2(p_kind text, p_query text, p_filters jsonb, p_sort text, p_cursor text, p_limit integer) OWNER TO portal_public_executor;

--
-- Name: portal_source_v1(text, jsonb); Type: FUNCTION; Schema: private; Owner: portal_public_executor
--

CREATE FUNCTION private.portal_source_v1(p_kind text, p_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE PARALLEL SAFE
    SET search_path TO ''
    AS $_$
declare
  v_publication jsonb := private.portal_publication_root_v1(p_kind, p_json);
  v_database jsonb := v_publication -> 'common:referenceToUnchangedRepublication';
  v_source jsonb;
begin
  v_source := case p_kind
    when 'process' then p_json #> '{processDataSet,modellingAndValidation,dataSourcesTreatmentAndRepresentativeness,referenceToDataSource}'
    when 'flow' then p_json #> '{flowDataSet,modellingAndValidation,dataSourcesTreatmentAndRepresentativeness,referenceToDataSource}'
    else null
  end;
  if jsonb_typeof(v_source) = 'array' and jsonb_array_length(v_source) = 1 then
    v_source := v_source -> 0;
  elsif jsonb_typeof(v_source) <> 'object' then
    v_source := null;
  end if;
  return jsonb_build_object(
    'databaseId', case
      when lower(coalesce(v_database ->> '@refObjectId', '')) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then lower(v_database ->> '@refObjectId')
      else null
    end,
    'databaseVersion', case
      when coalesce(v_database ->> '@version', '') ~ '^\d{2}\.\d{2}\.\d{3}$'
        then v_database ->> '@version'
      else null
    end,
    'sourceRecordId', case
      when lower(coalesce(v_source ->> '@refObjectId', '')) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then lower(v_source ->> '@refObjectId')
      else null
    end,
    'providerName', private.portal_localized_text_v1(
      v_publication #> '{common:referenceToOwnershipOfDataSet,common:shortDescription}'
    ),
    'licenseId', nullif(private.portal_scalar_text_v1(v_publication -> 'common:licenseType'), ''),
    'licenseUrl', null
  );
end
$_$;


ALTER FUNCTION private.portal_source_v1(p_kind text, p_json jsonb) OWNER TO portal_public_executor;

