--
-- Name: review_assert_all_reviewers_completed_v1(private.reviews); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_assert_all_reviewers_completed_v1(p_review private.reviews) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if pg_catalog.jsonb_array_length(
    coalesce(p_review.reviewer_id, '[]'::jsonb)
  ) = 0 then
    raise exception using
      errcode = '55000',
      message = 'REVIEWER_REQUIRED';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements_text(
      coalesce(p_review.reviewer_id, '[]'::jsonb)
    ) as reviewer(value)
    left join private.comments as comment_row
      on comment_row.review_id = p_review.id
      and comment_row.reviewer_id = reviewer.value::uuid
      and comment_row.state_code <> -2
    where comment_row.reviewer_id is null
      or comment_row.state_code not in (1, -3)
  ) then
    raise exception using
      errcode = '55000',
      message = 'REVIEWERS_NOT_COMPLETED';
  end if;
end;
$$;


ALTER FUNCTION private.review_assert_all_reviewers_completed_v1(p_review private.reviews) OWNER TO postgres;

--
-- Name: review_build_json_v1(text, jsonb, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_build_json_v1(p_target_table text, p_target_row jsonb, p_owner_id uuid, p_action text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_team_name jsonb;
  v_owner_meta jsonb;
  v_actor_meta jsonb;
begin
  select coalesce(team_row.json->'title', team_row.json->'name')
  into v_team_name
  from private.teams as team_row
  where team_row.id = nullif(p_target_row->>'team_id', '')::uuid;

  select user_row.raw_user_meta_data
  into v_owner_meta
  from private.users as user_row
  where user_row.id = p_owner_id;

  select user_row.raw_user_meta_data
  into v_actor_meta
  from private.users as user_row
  where user_row.id = p_actor;

  return jsonb_build_object(
    'review_kind', case
      when p_action = 'submit_reference_review' then 'reference'
      else 'root'
    end,
    'data', jsonb_build_object(
      'id', p_target_row->>'id',
      'version', p_target_row->>'version',
      'table', p_target_table,
      'name', api.cmd_review_get_dataset_name(
        p_target_table,
        p_target_row
      )
    ),
    'team', jsonb_build_object(
      'id', p_target_row->>'team_id',
      'name', v_team_name
    ),
    'user', jsonb_build_object(
      'id', p_owner_id,
      'name', coalesce(
        nullif(v_owner_meta->>'display_name', ''),
        nullif(v_owner_meta->>'email', '')
      ),
      'email', nullif(v_owner_meta->>'email', '')
    ),
    'comment', jsonb_build_object('message', ''),
    'logs', jsonb_build_array(jsonb_build_object(
      'action', p_action,
      'time', to_jsonb(now()),
      'user', jsonb_build_object(
        'id', p_actor,
        'display_name', coalesce(
          nullif(v_actor_meta->>'display_name', ''),
          nullif(v_actor_meta->>'email', '')
        )
      )
    ))
  );
end;
$$;


ALTER FUNCTION private.review_build_json_v1(p_target_table text, p_target_row jsonb, p_owner_id uuid, p_action text, p_actor uuid) OWNER TO postgres;

--
-- Name: review_candidate_root_ids_v1(text, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_candidate_root_ids_v1(p_target_table text, p_target_id uuid, p_target_version text) RETURNS TABLE(root_review_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if p_target_table not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    return;
  end if;

  return query execute pg_catalog.format(
    $query$
      select distinct (entry.value->>'id')::uuid
      from public.%I as dataset_row
      cross join lateral pg_catalog.jsonb_array_elements(
        case
          when pg_catalog.jsonb_typeof(dataset_row.reviews) = 'array'
            then dataset_row.reviews
          else '[]'::jsonb
        end
      ) as entry(value)
      where dataset_row.id = $1
        and pg_catalog.btrim(dataset_row.version::text) = $2
        and coalesce(entry.value->>'id', '')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    $query$,
    p_target_table
  ) using p_target_id, p_target_version;
end;
$_$;


ALTER FUNCTION private.review_candidate_root_ids_v1(p_target_table text, p_target_id uuid, p_target_version text) OWNER TO postgres;

--
-- Name: FUNCTION review_candidate_root_ids_v1(p_target_table text, p_target_id uuid, p_target_version text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.review_candidate_root_ids_v1(p_target_table text, p_target_id uuid, p_target_version text) IS 'Reads append-only business reviews[].id Root candidates. Callers must validate every candidate against current JSON/comments.';


--
-- Name: review_canonical_json_text_v1(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_canonical_json_text_v1(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
declare
  v_result text;
begin
  case pg_catalog.jsonb_typeof(p_value)
    when 'object' then
      select '{' || coalesce(pg_catalog.string_agg(
        pg_catalog.to_jsonb(item.key)::text
          || ':'
          || private.review_canonical_json_text_v1(item.value),
        ',' order by item.key collate "C"
      ), '') || '}'
      into v_result
      from pg_catalog.jsonb_each(p_value) as item(key, value);
    when 'array' then
      select '[' || coalesce(pg_catalog.string_agg(
        private.review_canonical_json_text_v1(item.value),
        ',' order by item.ordinality
      ), '') || ']'
      into v_result
      from pg_catalog.jsonb_array_elements(p_value)
        with ordinality as item(value, ordinality);
    else
      v_result := p_value::text;
  end case;

  return v_result;
end;
$$;


ALTER FUNCTION private.review_canonical_json_text_v1(p_value jsonb) OWNER TO postgres;

--
-- Name: FUNCTION review_canonical_json_text_v1(p_value jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.review_canonical_json_text_v1(p_value jsonb) IS 'Canonical JSON writer for review revision fingerprints. Object keys use UTF-8/C byte order, arrays retain order, and separators are compact, matching app_dataset_submit_review Gate hashing.';


--
-- Name: review_dataset_can_read_v1(uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_dataset_can_read_v1(p_actor uuid, p_target_table text, p_target_row jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_actor is not null and (
    coalesce((p_target_row->>'state_code')::integer, 0) >= 100
    or nullif(p_target_row->>'user_id', '')::uuid = p_actor
    or exists (
      select 1
      from private.roles as membership
      where membership.user_id = p_actor
        and membership.team_id = nullif(p_target_row->>'team_id', '')::uuid
        and membership.role in ('owner', 'admin', 'member')
    )
  )
$$;


ALTER FUNCTION private.review_dataset_can_read_v1(p_actor uuid, p_target_table text, p_target_row jsonb) OWNER TO postgres;

--
-- Name: review_dataset_content_guard_v1(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_dataset_content_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.state_code in (20, 100)
    and pg_catalog.current_setting('app.review_controlled_write', true)
      is distinct from 'on'
    and (
      to_jsonb(old)
        - array['extracted_md', 'search_text', 'embedding_ft', 'embedding_ft_at']
      is distinct from
      to_jsonb(new)
        - array['extracted_md', 'search_text', 'embedding_ft', 'embedding_ft_at']
    ) then
    raise exception using
      errcode = '55000',
      message = case
        when old.state_code = 100 then 'APPROVED_DATASET_IMMUTABLE'
        else 'DATASET_UNDER_REVIEW_IMMUTABLE'
      end;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.review_dataset_content_guard_v1() OWNER TO postgres;

--
-- Name: FUNCTION review_dataset_content_guard_v1(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.review_dataset_content_guard_v1() IS 'State 20/100 authored content is immutable; uncontrolled writes may change only extracted_md, search_text, embedding_ft, and embedding_ft_at. Review-controlled commands retain their existing bypass context.';


--
-- Name: review_derive_current_references_v1(uuid[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_derive_current_references_v1(p_root_review_ids uuid[]) RETURNS TABLE(root_review_id uuid, reference_review_id uuid, target_table text, data_id uuid, data_version text, submitted_revision_checksum text, state_code integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from private.review_resolve_current_reference_targets_v1(
      p_root_review_ids
    ) as target
    join private.reviews as root_review
      on root_review.id = target.root_review_id
      and root_review.state_code in (0, 1)
    where not exists (
      select 1
      from private.reviews as candidate
      where candidate.review_kind = 'reference'
        and candidate.target_table = target.target_table
        and candidate.data_id = target.data_id
        and pg_catalog.btrim(candidate.data_version::text) = target.data_version
        and candidate.submitted_revision_checksum = target.revision_checksum
        and candidate.state_code in (-1, 0, 1, 2)
    )
  ) then
    raise exception using
      errcode = '55000',
      message = 'MISSING_CURRENT_REFERENCE_REVIEW';
  end if;

  return query
  select
    target.root_review_id,
    reference_review.id,
    target.target_table,
    target.data_id,
    target.data_version,
    reference_review.submitted_revision_checksum,
    reference_review.state_code
  from private.review_resolve_current_reference_targets_v1(
    p_root_review_ids
  ) as target
  join lateral (
    select candidate.*
    from private.reviews as candidate
    where candidate.review_kind = 'reference'
      and candidate.target_table = target.target_table
      and candidate.data_id = target.data_id
      and pg_catalog.btrim(candidate.data_version::text) = target.data_version
      and candidate.submitted_revision_checksum = target.revision_checksum
      and candidate.state_code in (-1, 0, 1, 2)
    order by
      case when candidate.state_code in (0, 1, 2) then 0 else 1 end,
      candidate.modified_at desc,
      candidate.id
    limit 1
  ) as reference_review on true
  order by target.root_review_id, target.target_table,
    target.data_id, target.data_version;
end;
$$;


ALTER FUNCTION private.review_derive_current_references_v1(p_root_review_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION review_derive_current_references_v1(p_root_review_ids uuid[]); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.review_derive_current_references_v1(p_root_review_ids uuid[]) IS 'Derives current Root/Reference Review pairs from dataset JSON, non-revoked Reviewer comments, target identity, and revision checksum; persists no pair.';


--
-- Name: review_get_or_create_reference_v1(text, jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_get_or_create_reference_v1(p_target_table text, p_target_row jsonb, p_checksum text, p_actor uuid) RETURNS private.reviews
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_reference private.reviews%rowtype;
  v_owner_id uuid := nullif(p_target_row->>'user_id', '')::uuid;
  v_team_id uuid := nullif(p_target_row->>'team_id', '')::uuid;
  v_state integer := coalesce((p_target_row->>'state_code')::integer, 0);
begin
  if v_owner_id is null and v_state < 100 then
    raise exception using
      errcode = '23502',
      message = 'REFERENCE_OWNER_UNRESOLVED';
  end if;


  select reference_row.*
  into v_reference
  from private.reviews as reference_row
  where reference_row.review_kind = 'reference'
    and reference_row.target_table = p_target_table
    and reference_row.data_id = (p_target_row->>'id')::uuid
    and btrim(reference_row.data_version::text) = p_target_row->>'version'
    and reference_row.submitted_revision_checksum = p_checksum
    and reference_row.state_code in (0, 1, 2)
  order by reference_row.state_code desc, reference_row.created_at
  limit 1
  for update;

  if found then
    return v_reference;
  end if;

  begin
    insert into private.reviews (
      id,
      data_id,
      data_version,
      state_code,
      reviewer_id,
      json,
      review_kind,
      target_table,
      submitted_revision_checksum,
      approved_revision_checksum,
      target_owner_id,
      target_team_id
    )
    values (
      gen_random_uuid(),
      (p_target_row->>'id')::uuid,
      p_target_row->>'version',
      case when v_state >= 100 then 2 else 0 end,
      '[]'::jsonb,
      private.review_build_json_v1(
        p_target_table,
        p_target_row,
        v_owner_id,
        'submit_reference_review',
        p_actor
      ),
      'reference',
      p_target_table,
      p_checksum,
      case when v_state >= 100 then p_checksum else null end,
      v_owner_id,
      v_team_id
    )
    returning * into v_reference;
  exception
    when unique_violation then
      select reference_row.*
      into strict v_reference
      from private.reviews as reference_row
      where reference_row.review_kind = 'reference'
        and reference_row.target_table = p_target_table
        and reference_row.data_id = (p_target_row->>'id')::uuid
        and btrim(reference_row.data_version::text) = p_target_row->>'version'
        and reference_row.submitted_revision_checksum = p_checksum
        and reference_row.state_code in (0, 1, 2)
      order by reference_row.state_code desc, reference_row.created_at
      limit 1
      for update;
  end;

  return v_reference;
end;
$$;


ALTER FUNCTION private.review_get_or_create_reference_v1(p_target_table text, p_target_row jsonb, p_checksum text, p_actor uuid) OWNER TO postgres;

--
-- Name: review_notify_event_v1(text, uuid, uuid, uuid, text, uuid, text, uuid, integer, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_notify_event_v1(p_event_type text, p_review_id uuid, p_recipient_user_id uuid, p_sender_user_id uuid, p_target_table text, p_target_id uuid, p_target_version text, p_root_review_id uuid DEFAULT NULL::uuid, p_scope_version integer DEFAULT NULL::integer, p_reason_code text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  with payload as (
    select
      p_event_type || '|' ||
      p_review_id::text || '|' ||
      p_recipient_user_id::text || '|' ||
      coalesce(p_root_review_id::text, '') || '|' ||
      coalesce(p_scope_version::text, '') as event_key
  )
  insert into private.notifications (
    recipient_user_id,
    sender_user_id,
    type,
    dataset_type,
    dataset_id,
    dataset_version,
    json
  )
  select
    p_recipient_user_id,
    coalesce(p_sender_user_id, p_recipient_user_id),
    'review_event',
    p_target_table,
    p_target_id,
    p_target_version,
    jsonb_strip_nulls(jsonb_build_object(
      'event_key', payload.event_key,
      'event_type', p_event_type,
      'review_id', p_review_id,
      'root_review_id', p_root_review_id,
      'scope_version', p_scope_version,
      'reason_code', p_reason_code,
      'target_table', p_target_table,
      'target_id', p_target_id,
      'target_version', p_target_version
    ))
  from payload
  on conflict (
    recipient_user_id,
    sender_user_id,
    type,
    dataset_type,
    dataset_id,
    dataset_version
  )
  do update
  set json = excluded.json,
      modified_at = now()
  returning notifications.json->>'event_key';
$$;


ALTER FUNCTION private.review_notify_event_v1(p_event_type text, p_review_id uuid, p_recipient_user_id uuid, p_sender_user_id uuid, p_target_table text, p_target_id uuid, p_target_version text, p_root_review_id uuid, p_scope_version integer, p_reason_code text) OWNER TO postgres;

--
-- Name: review_notify_impacted_roots_v1(private.reviews, text, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_notify_impacted_roots_v1(p_reference_review private.reviews, p_event_type text, p_actor uuid, p_reason_code text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_root record;
begin
  for v_root in
    select impacted.root_review_id, root_review.target_owner_id
    from api.qry_reference_review_impacted_roots(
      p_reference_review.id,
      false
    ) as impacted
    join private.reviews as root_review
      on root_review.id = impacted.root_review_id
    order by impacted.root_review_id
  loop
    perform private.review_notify_event_v1(
      p_event_type,
      p_reference_review.id,
      v_root.target_owner_id,
      p_actor,
      p_reference_review.target_table,
      p_reference_review.data_id,
      pg_catalog.btrim(p_reference_review.data_version::text),
      null,
      null,
      p_reason_code
    );
  end loop;
end;
$$;


ALTER FUNCTION private.review_notify_impacted_roots_v1(p_reference_review private.reviews, p_event_type text, p_actor uuid, p_reason_code text) OWNER TO postgres;

--
-- Name: worker_jobs; Type: TABLE; Schema: private; Owner: postgres
--

CREATE TABLE private.worker_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_kind text NOT NULL,
    worker_runtime text DEFAULT 'calculator'::text NOT NULL,
    worker_queue text NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    queue_key text,
    root_job_id uuid,
    parent_job_id uuid,
    subject_type text,
    subject_id uuid,
    subject_version text,
    requester_type text DEFAULT 'user'::text NOT NULL,
    requested_by uuid,
    team_id uuid,
    idempotency_key text,
    request_hash text,
    concurrency_key text,
    status text DEFAULT 'queued'::text NOT NULL,
    phase text,
    progress numeric,
    visibility text DEFAULT 'user'::text NOT NULL,
    run_after timestamp with time zone DEFAULT now() NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    leased_by text,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    timeout_at timestamp with time zone,
    payload_schema_version text NOT NULL,
    payload_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload_ref jsonb,
    result_schema_version text,
    result_json jsonb,
    result_ref jsonb,
    diagnostics jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_code text,
    error_message text,
    error_details jsonb,
    blocker_codes text[] DEFAULT '{}'::text[] NOT NULL,
    resolution_scope text,
    retryable boolean,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    expires_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    CONSTRAINT worker_jobs_ai_tidas_suggestion_semantics_check CHECK (((job_kind <> 'ai.tidas_suggestion'::text) OR ((worker_queue = 'ai'::text) AND (visibility = 'user'::text) AND (payload_schema_version = 'ai.tidas_suggestion.request.v1'::text) AND (COALESCE(jsonb_typeof(payload_json), ''::text) = 'object'::text) AND (COALESCE((payload_json ->> 'dataType'::text), ''::text) = ANY (ARRAY['process'::text, 'flow'::text])) AND (COALESCE(jsonb_typeof((payload_json -> 'data'::text)), ''::text) = 'object'::text) AND ((((payload_json ->> 'dataType'::text) = 'process'::text) AND (COALESCE(jsonb_typeof(((payload_json -> 'data'::text) -> 'processDataSet'::text)), ''::text) = 'object'::text)) OR (((payload_json ->> 'dataType'::text) = 'flow'::text) AND (COALESCE(jsonb_typeof(((payload_json -> 'data'::text) -> 'flowDataSet'::text)), ''::text) = 'object'::text))) AND (status <> 'blocked'::text) AND (cardinality(blocker_codes) = 0) AND (resolution_scope IS NULL) AND ((status <> 'completed'::text) OR ((result_schema_version = 'ai.tidas_suggestion.result.v1'::text) AND (COALESCE(jsonb_typeof(result_json), ''::text) = 'object'::text) AND (COALESCE((result_json ->> 'status'::text), ''::text) = ANY (ARRAY['complete'::text, 'partial'::text])))) AND ((status <> 'failed'::text) OR (result_json IS NULL) OR ((result_schema_version = 'ai.tidas_suggestion.result.v1'::text) AND (COALESCE(jsonb_typeof(result_json), ''::text) = 'object'::text) AND (COALESCE((result_json ->> 'status'::text), ''::text) = 'failed'::text)))))),
    CONSTRAINT worker_jobs_attempt_check CHECK (((attempt_count >= 0) AND (max_attempts >= 0) AND (attempt_count <= max_attempts))),
    CONSTRAINT worker_jobs_blocked_explanation_check CHECK (((status <> 'blocked'::text) OR ((cardinality(blocker_codes) > 0) AND (resolution_scope IS NOT NULL)))),
    CONSTRAINT worker_jobs_diagnostics_object_check CHECK ((jsonb_typeof(diagnostics) = 'object'::text)),
    CONSTRAINT worker_jobs_error_details_object_check CHECK (((error_details IS NULL) OR (jsonb_typeof(error_details) = 'object'::text))),
    CONSTRAINT worker_jobs_payload_object_check CHECK ((jsonb_typeof(payload_json) = 'object'::text)),
    CONSTRAINT worker_jobs_payload_ref_object_check CHECK (((payload_ref IS NULL) OR (jsonb_typeof(payload_ref) = 'object'::text))),
    CONSTRAINT worker_jobs_progress_check CHECK (((progress IS NULL) OR ((progress >= (0)::numeric) AND (progress <= (1)::numeric)))),
    CONSTRAINT worker_jobs_queue_check CHECK ((worker_queue = ANY (ARRAY['solver'::text, 'review_submit'::text, 'review_submit_gate'::text, 'review_quality'::text, 'package'::text, 'maintenance'::text, 'ai'::text]))),
    CONSTRAINT worker_jobs_requester_check CHECK ((((requester_type = 'user'::text) AND (requested_by IS NOT NULL)) OR (requester_type = ANY (ARRAY['system'::text, 'service'::text, 'operator'::text])))),
    CONSTRAINT worker_jobs_resolution_scope_check CHECK (((resolution_scope IS NULL) OR (resolution_scope = ANY (ARRAY['user'::text, 'operator'::text, 'system'::text])))),
    CONSTRAINT worker_jobs_result_object_check CHECK (((result_json IS NULL) OR (jsonb_typeof(result_json) = 'object'::text))),
    CONSTRAINT worker_jobs_result_ref_object_check CHECK (((result_ref IS NULL) OR (jsonb_typeof(result_ref) = 'object'::text))),
    CONSTRAINT worker_jobs_review_quality_diagnostic_semantics_check CHECK (((job_kind <> 'review.quality_diagnostic'::text) OR ((worker_queue = 'review_quality'::text) AND (visibility = 'operator'::text) AND (status <> 'blocked'::text) AND (cardinality(blocker_codes) = 0) AND (resolution_scope IS NULL) AND ((status <> 'completed'::text) OR ((result_schema_version = 'review.quality_diagnostic.report.v1'::text) AND (jsonb_typeof(result_json) = 'object'::text) AND ((result_json ->> 'outcome'::text) = ANY (ARRAY['clear'::text, 'findings'::text, 'not_evaluable'::text]))))))),
    CONSTRAINT worker_jobs_runtime_check CHECK ((worker_runtime = 'calculator'::text)),
    CONSTRAINT worker_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting'::text, 'completed'::text, 'blocked'::text, 'stale'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT worker_jobs_visibility_check CHECK ((visibility = ANY (ARRAY['user'::text, 'operator'::text, 'system'::text])))
);


