-- Name: COLUMN worker_jobs.root_job_id; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_jobs.root_job_id IS 'Optional root worker job for multi-step flows such as review_submit.submit -> review_submit.gate.';


--
-- Name: COLUMN worker_jobs.parent_job_id; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_jobs.parent_job_id IS 'Immediate parent worker job for child execution records.';


--
-- Name: COLUMN worker_jobs.subject_type; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_jobs.subject_type IS 'Domain subject table or logical entity name used for latest/read/list projections.';


--
-- Name: COLUMN worker_jobs.subject_id; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_jobs.subject_id IS 'Domain subject UUID used with subject_type and subject_version.';


--
-- Name: COLUMN worker_jobs.subject_version; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_jobs.subject_version IS 'Domain subject version used with subject_type and subject_id.';


--
-- Name: COLUMN worker_jobs.payload_ref; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_jobs.payload_ref IS 'Internal reference to request payload artifacts or legacy compatibility rows. Exposed only through internal worker projections.';


--
-- Name: COLUMN worker_jobs.result_ref; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON COLUMN private.worker_jobs.result_ref IS 'Internal reference to result/artifact/cache rows. Exposed only through internal worker projections.';


--
-- Name: review_quality_diagnostic_projection(private.worker_jobs); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_quality_diagnostic_projection(p_job private.worker_jobs) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'runId', (p_job).id,
    'status', (p_job).status,
    'outcome', (p_job).result_json->>'outcome',
    'requestedBy', (p_job).requested_by,
    'requestedAt', (p_job).created_at,
    'startedAt', (p_job).started_at,
    'finishedAt', (p_job).finished_at,
    'updatedAt', (p_job).updated_at,
    'reportSchemaVersion', (p_job).result_schema_version,
    'report', (p_job).result_json,
    'error', case
      when (p_job).error_code is null and (p_job).error_message is null
        then null
      else jsonb_strip_nulls(jsonb_build_object(
        'code', (p_job).error_code,
        'message', (p_job).error_message
      ))
    end
  ))
$$;


ALTER FUNCTION private.review_quality_diagnostic_projection(p_job private.worker_jobs) OWNER TO postgres;

--
-- Name: review_resolve_current_reference_targets_v1(uuid[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_resolve_current_reference_targets_v1(p_root_review_ids uuid[]) RETURNS TABLE(root_review_id uuid, target_table text, data_id uuid, data_version text, revision_checksum text, provenance jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive requested_roots as materialized (
    select review_row.*
    from private.reviews as review_row
    where review_row.review_kind = 'root'
      and review_row.id = any(coalesce(p_root_review_ids, array[]::uuid[]))
  ),
  seed_targets as (
    select
      root_review.id as root_review_id,
      root_review.target_table,
      root_review.data_id,
      pg_catalog.btrim(root_review.data_version::text) as data_version,
      true as is_root,
      api.cmd_review_get_dataset_row(
        root_review.target_table,
        root_review.data_id,
        pg_catalog.btrim(root_review.data_version::text),
        false
      ) as dataset_row
    from requested_roots as root_review

    union

    select
      root_review.id,
      api.cmd_review_ref_type_to_table(ref.ref_type),
      ref.ref_object_id,
      ref.ref_version,
      false,
      api.cmd_review_get_dataset_row(
        api.cmd_review_ref_type_to_table(ref.ref_type),
        ref.ref_object_id,
        ref.ref_version,
        false
      )
    from requested_roots as root_review
    join private.comments as comment_row
      on comment_row.review_id = root_review.id
      and comment_row.state_code in (1, -3, 2)
    cross join lateral api.cmd_review_extract_refs(
      coalesce(comment_row.json::jsonb, '{}'::jsonb)
    ) as ref
    where api.cmd_review_ref_type_to_table(ref.ref_type) is not null
  ),
  closure (
    root_review_id,
    target_table,
    data_id,
    data_version,
    is_root,
    dataset_row
  ) as (
    select
      seed.root_review_id,
      seed.target_table,
      seed.data_id,
      seed.data_version,
      seed.is_root,
      seed.dataset_row
    from seed_targets as seed
    where seed.dataset_row is not null

    union

    select
      current_target.root_review_id,
      neighbour.target_table,
      neighbour.data_id,
      neighbour.data_version,
      false,
      dataset.dataset_row
    from closure as current_target
    cross join lateral (
      select
        api.cmd_review_ref_type_to_table(ref.ref_type) as target_table,
        ref.ref_object_id as data_id,
        ref.ref_version as data_version
      from (
        select * from api.cmd_review_extract_refs(
          coalesce(current_target.dataset_row->'json_ordered', '{}'::jsonb)
        )
        union
        select * from api.cmd_review_extract_refs(
          coalesce(current_target.dataset_row->'json', '{}'::jsonb)
        )
      ) as ref
      where (
          current_target.is_root
          or coalesce((current_target.dataset_row->>'state_code')::integer, 0) < 100
        )
        and api.cmd_review_ref_type_to_table(ref.ref_type) is not null

      union

      select
        'lifecyclemodels',
        current_target.data_id,
        current_target.data_version
      where current_target.target_table = 'processes'
        and not current_target.is_root

      union

      select
        'processes',
        current_target.data_id,
        current_target.data_version
      where current_target.target_table = 'lifecyclemodels'
        and current_target.is_root

      union

      select
        'processes',
        model_process.id,
        model_process.version
      from public.processes as model_process
      where current_target.target_table = 'lifecyclemodels'
        and (
          current_target.is_root
          or coalesce((current_target.dataset_row->>'state_code')::integer, 0) < 100
        )
        and model_process.model_id = current_target.data_id
        and coalesce(model_process.model_version, model_process.version) = current_target.data_version
    ) as neighbour
    cross join lateral (
      select api.cmd_review_get_dataset_row(
        neighbour.target_table,
        neighbour.data_id,
        neighbour.data_version,
        false
      ) as dataset_row
    ) as dataset
    where dataset.dataset_row is not null
      and not (
        neighbour.target_table = current_target.target_table
        and neighbour.data_id = current_target.data_id
        and neighbour.data_version = current_target.data_version
      )
  )
  select
    current_target.root_review_id,
    current_target.target_table,
    current_target.data_id,
    current_target.data_version,
    private.review_revision_fingerprint_v1(
      current_target.target_table,
      current_target.dataset_row
    ),
    pg_catalog.jsonb_build_array('current_json_or_comment')
  from closure as current_target
  join requested_roots as root_review
    on root_review.id = current_target.root_review_id
  where not current_target.is_root
    and not (
      current_target.target_table = root_review.target_table
      and current_target.data_id = root_review.data_id
      and current_target.data_version = pg_catalog.btrim(root_review.data_version::text)
    )
  group by
    current_target.root_review_id,
    current_target.target_table,
    current_target.data_id,
    current_target.data_version,
    current_target.dataset_row
$$;


ALTER FUNCTION private.review_resolve_current_reference_targets_v1(p_root_review_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION review_resolve_current_reference_targets_v1(p_root_review_ids uuid[]); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.review_resolve_current_reference_targets_v1(p_root_review_ids uuid[]) IS 'Resolves current review references using exact Process owner versions with legacy same-version fallback.';


--
-- Name: review_revision_fingerprint_v1(text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_revision_fingerprint_v1(p_target_table text, p_target_row jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
declare
  v_document jsonb;
begin
  if lower(p_target_table) not in (
    'contacts',
    'sources',
    'unitgroups',
    'flowproperties',
    'flows',
    'processes',
    'lifecyclemodels'
  ) then
    raise exception using
      errcode = '22023',
      message = 'REVIEW_TARGET_TABLE_INVALID';
  end if;

  v_document := coalesce(
    p_target_row->'json_ordered',
    p_target_row->'json',
    '{}'::jsonb
  );

  return pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        private.review_canonical_json_text_v1(v_document),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
end;
$$;


ALTER FUNCTION private.review_revision_fingerprint_v1(p_target_table text, p_target_row jsonb) OWNER TO postgres;

--
-- Name: FUNCTION review_revision_fingerprint_v1(p_target_table text, p_target_row jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.review_revision_fingerprint_v1(p_target_table text, p_target_row jsonb) IS 'Returns the unprefixed 64-character lowercase SHA-256 revision checksum shared with the Process review-submit Gate.';


--
-- Name: review_root_currently_references_target_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_root_currently_references_target_v1(p_root_review_id uuid, p_target_table text, p_target_id uuid, p_target_version text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_temp'
    AS $$
declare
  v_root private.reviews%rowtype;
  v_comment_roots jsonb;
begin
  select review_row.*
  into v_root
  from private.reviews as review_row
  where review_row.id = p_root_review_id
    and review_row.review_kind = 'root';

  if not found then
    return false;
  end if;

  if exists (
    select 1
    from api.cmd_review_collect_dataset_targets(
      pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'table', v_root.target_table,
        'id', v_root.data_id,
        'version', pg_catalog.btrim(v_root.data_version::text),
        'is_root', true
      )),
      false
    ) as target
    where not target.is_root
      and target.table_name = p_target_table
      and target.dataset_id = p_target_id
      and target.dataset_version = pg_catalog.btrim(p_target_version)
  ) then
    return true;
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(distinct pg_catalog.jsonb_build_object(
      'table', api.cmd_review_ref_type_to_table(ref.ref_type),
      'id', ref.ref_object_id,
      'version', ref.ref_version,
      'is_root', false
    )),
    '[]'::jsonb
  )
  into v_comment_roots
  from private.comments as comment_row
  cross join lateral api.cmd_review_extract_refs(
    coalesce(comment_row.json::jsonb, '{}'::jsonb)
  ) as ref
  where comment_row.review_id = p_root_review_id
    and comment_row.state_code <> -2
    and api.cmd_review_ref_type_to_table(ref.ref_type) is not null;

  return exists (
    select 1
    from api.cmd_review_collect_dataset_targets(v_comment_roots, false) as target
    where target.table_name = p_target_table
      and target.dataset_id = p_target_id
      and target.dataset_version = pg_catalog.btrim(p_target_version)
  );
end;
$$;


ALTER FUNCTION private.review_root_currently_references_target_v1(p_root_review_id uuid, p_target_table text, p_target_id uuid, p_target_version text) OWNER TO postgres;

--
-- Name: review_v2_comment_guard(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_v2_comment_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if current_setting('app.review_legacy_migration', true) = 'on' then
    return new;
  end if;

  if exists (
    select 1
    from private.reviews as review_row
    where review_row.id = new.review_id
      and review_row.review_kind is null
  ) then
    raise exception using
      errcode = '55000',
      message = 'LEGACY_REVIEW_READ_ONLY';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.review_v2_comment_guard() OWNER TO postgres;

--
-- Name: review_v2_kind_guard(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.review_v2_kind_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if current_setting('app.review_legacy_migration', true) = 'on' then
    return new;
  end if;

  if tg_op = 'INSERT' and new.review_kind is null then
    raise exception using
      errcode = '55000',
      message = 'LEGACY_REVIEW_INSERT_DISABLED';
  end if;

  if tg_op = 'UPDATE' and old.review_kind is null then
    raise exception using
      errcode = '55000',
      message = 'LEGACY_REVIEW_READ_ONLY';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.review_v2_kind_guard() OWNER TO postgres;

--
-- Name: save_lifecycle_model_bundle(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.save_lifecycle_model_bundle(p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
    v_mode text := coalesce(p_plan->>'mode', '');
    v_model_id uuid := nullif(p_plan->>'modelId', '')::uuid;
    v_expected_version text := nullif(btrim(coalesce(p_plan->>'version', '')), '');
    v_actor_user_id uuid := nullif(p_plan->>'actorUserId', '')::uuid;
    v_allocate_version boolean := coalesce((p_plan->>'allocateVersion')::boolean, false);
    v_source_version text := nullif(btrim(coalesce(p_plan->>'sourceVersion', '')), '');
    v_parent jsonb := coalesce(p_plan->'parent', '{}'::jsonb);
    v_parent_json_ordered jsonb := v_parent->'jsonOrdered';
    v_parent_json_tg jsonb := coalesce(v_parent->'jsonTg', '{}'::jsonb);
    v_parent_rule_verification boolean := coalesce((v_parent->>'ruleVerification')::boolean, true);
    v_process_mutations jsonb := coalesce(p_plan->'processMutations', '[]'::jsonb);
    v_mutation jsonb;
    v_child_id uuid;
    v_child_version text;
    v_child_json_ordered jsonb;
    v_child_rule_verification boolean;
    v_result_row lifecyclemodels%rowtype;
    v_rows_affected integer;
    v_highest_version text;
    v_parts integer[];
    v_allocated_version text;
    v_model_version text;
    v_allocated_uri text;
    v_dataset jsonb;
    v_admin jsonb;
    v_pub jsonb;
    v_resulting_refs jsonb;
    v_submodels jsonb;
begin
    if v_mode not in ('create', 'update') then
        raise exception 'INVALID_PLAN';
    end if;

    if v_model_id is null or v_parent_json_ordered is null then
        raise exception 'INVALID_PLAN';
    end if;

    if v_actor_user_id is null then
        raise exception 'INVALID_PLAN';
    end if;

    if jsonb_typeof(v_process_mutations) <> 'array' then
        raise exception 'INVALID_PLAN';
    end if;

    if v_allocate_version then
        if v_mode <> 'create' or v_source_version is null then
            raise exception 'INVALID_PLAN';
        end if;

        perform set_config('lock_timeout', '2s', true);
        perform set_config('statement_timeout', '8s', true);
        perform pg_advisory_xact_lock(
            hashtext('save_lifecycle_model_bundle:create_version'),
            hashtext(v_model_id::text)
        );

        perform 1
          from lifecyclemodels d
         where d.id = v_model_id
           and d.version = v_source_version
           and (
             d.state_code >= 100
             or d.user_id = v_actor_user_id
             or exists (
               select 1
                 from private.roles r
                where r.team_id = d.team_id
                  and r.user_id = v_actor_user_id
                  and r.role::text = any(array['admin', 'member', 'owner'])
             )
           );

        if not found then
            raise exception 'MODEL_NOT_FOUND';
        end if;

        select version::text
          into v_highest_version
          from public.lifecyclemodels
         where id = v_model_id
           and version::text ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$'
         order by split_part(version::text, '.', 1)::integer desc,
                  split_part(version::text, '.', 2)::integer desc,
                  split_part(version::text, '.', 3)::integer desc
         limit 1;

        if v_highest_version is null then
            v_parts := array[0, 0, -1];
        else
            v_parts := array[
                split_part(v_highest_version, '.', 1)::integer,
                split_part(v_highest_version, '.', 2)::integer,
                split_part(v_highest_version, '.', 3)::integer
            ];
        end if;

        v_parts[3] := v_parts[3] + 1;

        if v_parts[3] > 999 then
            v_parts[3] := 0;
            v_parts[2] := v_parts[2] + 1;
        end if;

        if v_parts[2] > 99 then
            v_parts[2] := 0;
            v_parts[1] := v_parts[1] + 1;
        end if;

        v_allocated_version := lpad(v_parts[1]::text, 2, '0')
            || '.'
            || lpad(v_parts[2]::text, 2, '0')
            || '.'
            || lpad(v_parts[3]::text, 3, '0');
        v_allocated_uri := 'https://lcdn.tiangong.earth/datasetdetail/lifecyclemodel.xhtml?uuid='
            || v_model_id::text
            || '&version='
            || v_allocated_version;

        v_dataset := coalesce(v_parent_json_ordered->'lifeCycleModelDataSet', '{}'::jsonb);
        v_admin := coalesce(v_dataset->'administrativeInformation', '{}'::jsonb);
        v_pub := coalesce(v_admin->'publicationAndOwnership', '{}'::jsonb);
        v_pub := jsonb_set(v_pub, '{common:dataSetVersion}', to_jsonb(v_allocated_version), true);
        v_pub := jsonb_set(v_pub, '{common:permanentDataSetURI}', to_jsonb(v_allocated_uri), true);
        v_admin := jsonb_set(v_admin, '{publicationAndOwnership}', v_pub, true);
        v_dataset := jsonb_set(v_dataset, '{administrativeInformation}', v_admin, true);
        v_parent_json_ordered := jsonb_set(
            v_parent_json_ordered,
            '{lifeCycleModelDataSet}',
            v_dataset,
            true
        );

        v_resulting_refs := v_parent_json_ordered #> '{lifeCycleModelDataSet,lifeCycleModelInformation,dataSetInformation,referenceToResultingProcess}';
        if jsonb_typeof(v_resulting_refs) = 'array' then
            select coalesce(
                jsonb_agg(
                    case
                        when jsonb_typeof(value) = 'object'
                            then jsonb_set(value, '{@version}', to_jsonb(v_allocated_version), true)
                        else value
                    end
                ),
                '[]'::jsonb
            )
              into v_resulting_refs
              from jsonb_array_elements(v_resulting_refs);
            v_parent_json_ordered := jsonb_set(
                v_parent_json_ordered,
                '{lifeCycleModelDataSet,lifeCycleModelInformation,dataSetInformation,referenceToResultingProcess}',
                v_resulting_refs,
                true
            );
        elsif jsonb_typeof(v_resulting_refs) = 'object' then
            v_parent_json_ordered := jsonb_set(
                v_parent_json_ordered,
                '{lifeCycleModelDataSet,lifeCycleModelInformation,dataSetInformation,referenceToResultingProcess}',
                jsonb_set(v_resulting_refs, '{@version}', to_jsonb(v_allocated_version), true),
                true
            );
        end if;

        if jsonb_typeof(v_parent_json_tg->'submodels') = 'array' then
            select coalesce(
                jsonb_agg(
                    case
                        when jsonb_typeof(value) = 'object'
                            then jsonb_set(value, '{version}', to_jsonb(v_allocated_version), true)
                        else value
                    end
                ),
                '[]'::jsonb
            )
              into v_submodels
              from jsonb_array_elements(v_parent_json_tg->'submodels');
            v_parent_json_tg := jsonb_set(v_parent_json_tg, '{submodels}', v_submodels, true);
        end if;
    end if;

    if v_mode = 'update' then
        if v_expected_version is null then
            raise exception 'INVALID_PLAN';
        end if;

        perform 1
          from lifecyclemodels
         where id = v_model_id
           and version = v_expected_version
         for update;

        if not found then
            raise exception 'MODEL_NOT_FOUND';
        end if;
    end if;

    v_model_version := case
        when v_allocate_version then v_allocated_version
        when v_mode = 'update' then v_expected_version
        else nullif(
            btrim(
                coalesce(
                    v_parent_json_ordered #>> '{lifeCycleModelDataSet,administrativeInformation,publicationAndOwnership,common:dataSetVersion}',
                    ''
                )
            ),
            ''
        )
    end;

    if v_model_version is null
       or v_model_version !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{3}$' then
        raise exception 'INVALID_PLAN';
    end if;

    for v_mutation in
        select value
          from jsonb_array_elements(v_process_mutations)
    loop
        case coalesce(v_mutation->>'op', '')
            when 'delete' then
                v_child_id := nullif(v_mutation->>'id', '')::uuid;
                v_child_version := nullif(btrim(coalesce(v_mutation->>'version', '')), '');

                if v_child_id is null or v_child_version is null then
                    raise exception 'INVALID_PLAN';
                end if;

                execute 'del' || 'ete from processes where id = $1 and version = $2 and model_id = $3 and coalesce(model_version, version) = $4'
                   using v_child_id, v_child_version, v_model_id, v_model_version;

                get diagnostics v_rows_affected = row_count;
                if v_rows_affected = 0 then
                    raise exception 'PROCESS_NOT_FOUND';
                end if;
            when 'create' then
                v_child_id := nullif(v_mutation->>'id', '')::uuid;
                v_child_json_ordered := v_mutation->'jsonOrdered';
                v_child_rule_verification := coalesce(
                    (v_mutation->>'ruleVerification')::boolean,
                    true
                );

                if v_child_id is null or v_child_json_ordered is null then
                    raise exception 'INVALID_PLAN';
                end if;

                if v_allocate_version then
                    v_dataset := coalesce(v_child_json_ordered->'processDataSet', '{}'::jsonb);
                    v_admin := coalesce(v_dataset->'administrativeInformation', '{}'::jsonb);
                    v_pub := coalesce(v_admin->'publicationAndOwnership', '{}'::jsonb);
                    v_pub := jsonb_set(
                        v_pub,
                        '{common:dataSetVersion}',
                        to_jsonb(v_allocated_version),
                        true
                    );
                    v_pub := jsonb_set(
                        v_pub,
                        '{common:permanentDataSetURI}',
                        to_jsonb(
                            'https://lcdn.tiangong.earth/datasetdetail/process.xhtml?uuid='
                            || v_child_id::text
                            || '&version='
                            || v_allocated_version
                        ),
                        true
                    );
                    v_admin := jsonb_set(v_admin, '{publicationAndOwnership}', v_pub, true);
                    v_dataset := jsonb_set(v_dataset, '{administrativeInformation}', v_admin, true);
                    v_child_json_ordered := jsonb_set(
                        v_child_json_ordered,
                        '{processDataSet}',
                        v_dataset,
                        true
                    );
                end if;

                begin
                    insert into processes (
                        id,
                        json_ordered,
                        model_id,
                        model_version,
                        user_id,
                        rule_verification
                    )
                    values (
                        v_child_id,
                        v_child_json_ordered::json,
                        v_model_id,
                        v_model_version,
                        v_actor_user_id,
                        v_child_rule_verification
                    );
                exception
                    when unique_violation then
                        raise exception 'VERSION_CONFLICT';
                end;
            when 'update' then
                v_child_id := nullif(v_mutation->>'id', '')::uuid;
                v_child_version := nullif(btrim(coalesce(v_mutation->>'version', '')), '');
                v_child_json_ordered := v_mutation->'jsonOrdered';
                v_child_rule_verification := coalesce(
                    (v_mutation->>'ruleVerification')::boolean,
                    true
                );

                if v_child_id is null or v_child_version is null or v_child_json_ordered is null then
                    raise exception 'INVALID_PLAN';
                end if;

                update processes
                   set json_ordered = v_child_json_ordered::json,
                       model_id = v_model_id,
                       model_version = v_model_version,
                       rule_verification = v_child_rule_verification
                 where id = v_child_id
                   and version = v_child_version
                   and model_id = v_model_id
                   and coalesce(model_version, version) = v_model_version;

                if not found then
                    raise exception 'PROCESS_NOT_FOUND';
                end if;
            else
                raise exception 'INVALID_PLAN';
        end case;
    end loop;

    if v_mode = 'create' then
        begin
            insert into lifecyclemodels (
                id,
                json_ordered,
                json_tg,
                user_id,
                rule_verification
            )
            values (
                v_model_id,
                v_parent_json_ordered::json,
                v_parent_json_tg,
                v_actor_user_id,
                v_parent_rule_verification
            )
            returning *
                 into v_result_row;
        exception
            when unique_violation then
                raise exception 'VERSION_CONFLICT';
        end;
    else
        update lifecyclemodels
           set json_ordered = v_parent_json_ordered::json,
               json_tg = v_parent_json_tg,
               rule_verification = v_parent_rule_verification
         where id = v_model_id
           and version = v_expected_version
        returning *
             into v_result_row;

        if not found then
            raise exception 'MODEL_NOT_FOUND';
        end if;
    end if;

    return jsonb_build_object(
        'model_id', v_result_row.id,
        'version', v_result_row.version,
        'lifecycle_model', to_jsonb(v_result_row)
    );
end;
$_$;


ALTER FUNCTION private.save_lifecycle_model_bundle(p_plan jsonb) OWNER TO postgres;

--
-- Name: search_dataset_json_uuid_mentions_impl(uuid, text[], text, text, uuid, integer, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.search_dataset_json_uuid_mentions_impl(p_uuid uuid, p_source_entity_kinds text[] DEFAULT NULL::text[], p_data_source text DEFAULT 'tg'::text, p_this_user_id text DEFAULT ''::text, p_team_id_filter uuid DEFAULT NULL::uuid, p_state_code_filter integer DEFAULT NULL::integer, p_limit integer DEFAULT 20) RETURNS TABLE(rank bigint, source_entity_kind text, source_id uuid, source_version character, source_name text, source_modified_at timestamp with time zone, source_team_id uuid, source_json jsonb, matched_by text, matched_entity_table text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    SET statement_timeout TO '20s'
    AS $_$
declare
  normalized_data_source text;
  effective_user_id uuid;
  can_read_team_filter boolean;
  normalized_limit integer;
  per_entity_limit integer;
  uuid_pattern text;
  normalized_source_entity_kinds text[];
  branches text[] := array[]::text[];
  v_sql text;
begin
  normalized_data_source := coalesce(nullif(lower(btrim(p_data_source)), ''), 'tg');
  effective_user_id := private.dataset_search_effective_user_id(p_this_user_id);
  can_read_team_filter := private.dataset_search_can_read_team_filter(p_team_id_filter, effective_user_id);
  normalized_limit := least(greatest(coalesce(p_limit, 20), 1), 50);
  per_entity_limit := normalized_limit;
  uuid_pattern := '%' || p_uuid::text || '%';

  if p_source_entity_kinds is not null then
    select array_agg(distinct normalized_kind order by normalized_kind)
    into normalized_source_entity_kinds
    from (
      select case lower(btrim(kind))
        when 'flow' then 'flow'
        when 'flows' then 'flow'
        when 'process' then 'process'
        when 'processes' then 'process'
        when 'lifecyclemodel' then 'lifecyclemodel'
        when 'lifecyclemodels' then 'lifecyclemodel'
        when 'model' then 'lifecyclemodel'
        when 'models' then 'lifecyclemodel'
        when 'source' then 'source'
        when 'sources' then 'source'
        when 'contact' then 'contact'
        when 'contacts' then 'contact'
        when 'unitgroup' then 'unitgroup'
        when 'unitgroups' then 'unitgroup'
        when 'flowproperty' then 'flowproperty'
        when 'flowproperties' then 'flowproperty'
        else null
      end as normalized_kind
      from unnest(p_source_entity_kinds) as requested(kind)
    ) normalized
    where normalized_kind is not null;

    if coalesce(array_length(normalized_source_entity_kinds, 1), 0) = 0 then
      return;
    end if;
  end if;

  if normalized_source_entity_kinds is null or 'process' = any(normalized_source_entity_kinds) then
    branches := branches || array[$branch$
      (select *
      from (
        select distinct on (d.id)
          10::integer as entity_rank,
          'process'::text as source_entity_kind,
          d.id as source_id,
          d.version as source_version,
          private.dataset_json_display_name('process', d.json) as source_name,
          d.modified_at as source_modified_at,
          d.team_id as source_team_id,
          d.json as source_json,
          'json_uuid_scan'::text as matched_by,
          'public.processes'::text as matched_entity_table
        from public.processes d
        where (
            ($1 = 'tg' and d.state_code = 100 and ($3 is null or d.team_id = $3))
            or ($1 = 'co' and d.state_code = 200 and ($3 is null or d.team_id = $3))
            or ($1 = 'my' and $2 is not null and d.user_id = $2 and ($4 is null or d.state_code = $4))
            or ($1 = 'te' and $3 is not null and $5 and d.team_id = $3 and ($4 is null or d.state_code = $4))
          )
        order by d.id, d.version desc, d.modified_at desc
      ) latest
      where latest.source_json::text like $6
      order by latest.source_modified_at desc nulls last, latest.source_id
      limit $8
      )
    $branch$];
  end if;

  if normalized_source_entity_kinds is null or 'flow' = any(normalized_source_entity_kinds) then
    branches := branches || array[$branch$
      (select *
      from (
        select distinct on (d.id)
          20::integer as entity_rank,
          'flow'::text as source_entity_kind,
          d.id as source_id,
          d.version as source_version,
          private.dataset_json_display_name('flow', d.json) as source_name,
          d.modified_at as source_modified_at,
