--
-- Name: search_text_cutover_gate_v1(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.search_text_cutover_gate_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_total bigint := 0;
  v_missing bigint := 0;
  v_tables jsonb := '[]'::jsonb;
begin
  with coverage(table_name, total_rows, missing_rows) as (
    select 'contacts', count(*)::bigint, count(*) filter (where search_text is null)::bigint
    from public.contacts
    union all
    select 'flowproperties', count(*)::bigint, count(*) filter (where search_text is null)::bigint
    from public.flowproperties
    union all
    select 'flows', count(*)::bigint, count(*) filter (where search_text is null)::bigint
    from public.flows
    union all
    select 'lifecyclemodels', count(*)::bigint, count(*) filter (where search_text is null)::bigint
    from public.lifecyclemodels
    union all
    select 'processes', count(*)::bigint, count(*) filter (where search_text is null)::bigint
    from public.processes
    union all
    select 'sources', count(*)::bigint, count(*) filter (where search_text is null)::bigint
    from public.sources
    union all
    select 'unitgroups', count(*)::bigint, count(*) filter (where search_text is null)::bigint
    from public.unitgroups
  )
  select
    coalesce(sum(coverage.total_rows), 0)::bigint,
    coalesce(sum(coverage.missing_rows), 0)::bigint,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'table', coverage.table_name,
          'total', coverage.total_rows,
          'missing_search_text', coverage.missing_rows
        )
        order by coverage.table_name
      ),
      '[]'::jsonb
    )
  into v_total, v_missing, v_tables
  from coverage;

  return jsonb_build_object(
    'fresh_database', v_total = 0,
    'ready', v_total = 0 or v_missing = 0,
    'total_rows', v_total,
    'missing_rows', v_missing,
    'tables', v_tables
  );
end
$$;


ALTER FUNCTION private.search_text_cutover_gate_v1() OWNER TO postgres;

--
-- Name: FUNCTION search_text_cutover_gate_v1(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.search_text_cutover_gate_v1() IS 'Database B gate: an empty new/test database is allowed; an existing environment must have non-NULL search_text for every row in all seven dataset tables before lexical source switch.';


--
-- Name: semantic_flow_candidates(text, text, double precision, integer, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.semantic_flow_candidates(query_embedding text, filter_condition text DEFAULT ''::text, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 20, data_source text DEFAULT 'tg'::text) RETURNS TABLE(rank bigint, id uuid, distance double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    SET statement_timeout TO '60s'
    SET plan_cache_mode TO 'force_custom_plan'
    SET "hnsw.iterative_scan" TO 'strict_order'
    AS $$
declare
  query_embedding_vector vector(1024);
  filter_condition_jsonb jsonb;
  normalized_data_source text;
  normalized_match_count integer;
  candidate_size integer;
  threshold_distance double precision;
  effective_user_id uuid;
  flow_type text;
  flow_type_array text[];
  as_input boolean;
begin
  query_embedding_vector := query_embedding::vector(1024);
  filter_condition_jsonb := coalesce(nullif(btrim(filter_condition), ''), '{}')::jsonb;
  normalized_data_source := coalesce(nullif(lower(btrim(data_source)), ''), 'tg');
  normalized_match_count := greatest(coalesce(match_count, 20), 1);
  candidate_size := greatest(normalized_match_count * 10, 200);
  threshold_distance := 1 - coalesce(match_threshold, 0.5);
  effective_user_id := private.dataset_search_effective_user_id('');

  flow_type := nullif(btrim(filter_condition_jsonb->>'flowType'), '');
  if flow_type is not null then
    flow_type_array := string_to_array(flow_type, ',');
  else
    flow_type_array := null;
  end if;
  filter_condition_jsonb := filter_condition_jsonb - 'flowType';

  if filter_condition_jsonb ? 'asInput' then
    as_input := nullif(btrim(filter_condition_jsonb->>'asInput'), '')::boolean;
  else
    as_input := null;
  end if;
  filter_condition_jsonb := filter_condition_jsonb - 'asInput';

  if normalized_data_source = 'tg' then
    return query
      with candidates as materialized (
        select
          f.id as candidate_id,
          (f.embedding_ft <=> query_embedding_vector) as candidate_distance
        from public.flows f
        where f.embedding_ft is not null
          and f.state_code = 100
          and (filter_condition_jsonb = '{}'::jsonb or f.json @> filter_condition_jsonb)
          and (
            flow_type is null
            or flow_type = ''
            or (f.json->'flowDataSet'->'modellingAndValidation'->'LCIMethod'->>'typeOfDataSet') = any(flow_type_array)
          )
          and (
            as_input is null
            or as_input = false
            or not (
              f.json @> '{"flowDataSet":{"flowInformation":{"dataSetInformation":{"classificationInformation":{"common:elementaryFlowCategorization":{"common:category":[{"#text":"Emissions","@level":"0"}]}}}}}}'
            )
          )
        order by f.embedding_ft <=> query_embedding_vector
        limit candidate_size
      ),
      filtered as (
        select candidates.*
        from candidates
        where candidates.candidate_distance < threshold_distance
      )
      select
        rank() over (order by filtered.candidate_distance)::bigint,
        filtered.candidate_id,
        filtered.candidate_distance
      from filtered
      order by filtered.candidate_distance
      limit normalized_match_count;
    return;
  end if;

  if normalized_data_source = 'co' then
    return query
      with candidates as materialized (
        select
          f.id as candidate_id,
          (f.embedding_ft <=> query_embedding_vector) as candidate_distance
        from public.flows f
        where f.embedding_ft is not null
          and f.state_code = 200
          and (filter_condition_jsonb = '{}'::jsonb or f.json @> filter_condition_jsonb)
          and (
            flow_type is null
            or flow_type = ''
            or (f.json->'flowDataSet'->'modellingAndValidation'->'LCIMethod'->>'typeOfDataSet') = any(flow_type_array)
          )
          and (
            as_input is null
            or as_input = false
            or not (
              f.json @> '{"flowDataSet":{"flowInformation":{"dataSetInformation":{"classificationInformation":{"common:elementaryFlowCategorization":{"common:category":[{"#text":"Emissions","@level":"0"}]}}}}}}'
            )
          )
        order by f.embedding_ft <=> query_embedding_vector
        limit candidate_size
      ),
      filtered as (
        select candidates.*
        from candidates
        where candidates.candidate_distance < threshold_distance
      )
      select
        rank() over (order by filtered.candidate_distance)::bigint,
        filtered.candidate_id,
        filtered.candidate_distance
      from filtered
      order by filtered.candidate_distance
      limit normalized_match_count;
    return;
  end if;

  if normalized_data_source = 'my' then
    if effective_user_id is null then
      return;
    end if;

    return query
      with candidates as materialized (
        select
          f.id as candidate_id,
          (f.embedding_ft <=> query_embedding_vector) as candidate_distance
        from public.flows f
        where f.embedding_ft is not null
          and f.user_id = effective_user_id
          and (filter_condition_jsonb = '{}'::jsonb or f.json @> filter_condition_jsonb)
          and (
            flow_type is null
            or flow_type = ''
            or (f.json->'flowDataSet'->'modellingAndValidation'->'LCIMethod'->>'typeOfDataSet') = any(flow_type_array)
          )
          and (
            as_input is null
            or as_input = false
            or not (
              f.json @> '{"flowDataSet":{"flowInformation":{"dataSetInformation":{"classificationInformation":{"common:elementaryFlowCategorization":{"common:category":[{"#text":"Emissions","@level":"0"}]}}}}}}'
            )
          )
        order by f.embedding_ft <=> query_embedding_vector
        limit candidate_size
      ),
      filtered as (
        select candidates.*
        from candidates
        where candidates.candidate_distance < threshold_distance
      )
      select
        rank() over (order by filtered.candidate_distance)::bigint,
        filtered.candidate_id,
        filtered.candidate_distance
      from filtered
      order by filtered.candidate_distance
      limit normalized_match_count;
    return;
  end if;

  if normalized_data_source = 'te' then
    if effective_user_id is null then
      return;
    end if;

    return query
      with candidates as materialized (
        select
          f.id as candidate_id,
          (f.embedding_ft <=> query_embedding_vector) as candidate_distance
        from public.flows f
        where f.embedding_ft is not null
          and exists (
            select 1
            from private.roles r
            where r.user_id = effective_user_id
              and r.team_id = f.team_id
              and r.role::text in ('admin', 'member', 'owner')
          )
          and (filter_condition_jsonb = '{}'::jsonb or f.json @> filter_condition_jsonb)
          and (
            flow_type is null
            or flow_type = ''
            or (f.json->'flowDataSet'->'modellingAndValidation'->'LCIMethod'->>'typeOfDataSet') = any(flow_type_array)
          )
          and (
            as_input is null
            or as_input = false
            or not (
              f.json @> '{"flowDataSet":{"flowInformation":{"dataSetInformation":{"classificationInformation":{"common:elementaryFlowCategorization":{"common:category":[{"#text":"Emissions","@level":"0"}]}}}}}}'
            )
          )
        order by f.embedding_ft <=> query_embedding_vector
        limit candidate_size
      ),
      filtered as (
        select candidates.*
        from candidates
        where candidates.candidate_distance < threshold_distance
      )
      select
        rank() over (order by filtered.candidate_distance)::bigint,
        filtered.candidate_id,
        filtered.candidate_distance
      from filtered
      order by filtered.candidate_distance
      limit normalized_match_count;
    return;
  end if;
end;
$$;


