--
-- Name: semantic_simple_dataset_candidates(regclass, text, text, double precision, integer, text, integer, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.semantic_simple_dataset_candidates(p_table regclass, query_embedding text, filter_condition text DEFAULT ''::text, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 20, data_source text DEFAULT 'tg'::text, state_code_filter integer DEFAULT NULL::integer, team_id_filter uuid DEFAULT NULL::uuid) RETURNS TABLE(rank bigint, id uuid, distance double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    SET statement_timeout TO '60s'
    SET plan_cache_mode TO 'force_custom_plan'
    SET "hnsw.iterative_scan" TO 'strict_order'
    AS $_$
declare
  query_embedding_vector extensions.vector(1024);
  filter_condition_jsonb jsonb;
  normalized_data_source text;
  normalized_match_count integer;
  candidate_size integer;
  threshold_distance double precision;
  effective_user_id uuid;
  can_read_team_filter boolean;
  visibility_clause text;
  json_filter_clause text;
  candidate_sql text;
begin
  if p_table not in (
    'public.contacts'::regclass,
    'public.flowproperties'::regclass,
    'public.sources'::regclass,
    'public.unitgroups'::regclass
  ) then
    raise exception 'unsupported semantic dataset table: %', p_table;
  end if;

  query_embedding_vector := query_embedding::extensions.vector(1024);
  filter_condition_jsonb := coalesce(nullif(btrim(filter_condition), ''), '{}')::jsonb;
  normalized_data_source := coalesce(nullif(lower(btrim(data_source)), ''), 'tg');
  normalized_match_count := least(greatest(coalesce(match_count, 20), 1), 200);
  candidate_size := greatest(normalized_match_count * 10, 200);
  threshold_distance := 1 - least(greatest(coalesce(match_threshold, 0.5), -1), 1);
  effective_user_id := private.dataset_search_effective_user_id('');
  can_read_team_filter := private.dataset_search_can_read_team_filter(
    team_id_filter,
    effective_user_id
  );

  if normalized_data_source = 'tg' then
    visibility_clause := 'd.state_code = 100 and ($7::uuid is null or d.team_id = $7)';
  elsif normalized_data_source = 'co' then
    visibility_clause := 'd.state_code = 200 and ($7::uuid is null or d.team_id = $7)';
  elsif normalized_data_source = 'my' then
    if effective_user_id is null then
      return;
    end if;
    visibility_clause := 'd.user_id = $5 and ($8::integer is null or d.state_code = $8)';
  elsif normalized_data_source = 'te' then
    if team_id_filter is null or not can_read_team_filter then
      return;
    end if;
    visibility_clause := 'd.team_id = $7 and ($8::integer is null or d.state_code = $8)';
  else
    return;
  end if;

  json_filter_clause := case
    when filter_condition_jsonb = '{}'::jsonb then ''
    else 'and d.json @> $2'
  end;

  candidate_sql := format(
    $sql$
      with candidates as materialized (
        select
          d.id as candidate_id,
          d.embedding_ft <=> $1 as candidate_distance
        from %1$s d
        where d.embedding_ft is not null
          and %2$s
          %3$s
        order by d.embedding_ft <=> $1
        limit $3
      ),
      deduplicated as (
        select
          candidates.candidate_id,
          min(candidates.candidate_distance) as candidate_distance
        from candidates
        where candidates.candidate_distance < $4
        group by candidates.candidate_id
      )
      select
        rank() over (
          order by deduplicated.candidate_distance, deduplicated.candidate_id
        )::bigint,
        deduplicated.candidate_id,
        deduplicated.candidate_distance
      from deduplicated
      order by deduplicated.candidate_distance, deduplicated.candidate_id
      limit $6
    $sql$,
    p_table,
    visibility_clause,
    json_filter_clause
  );

  return query execute candidate_sql
    using query_embedding_vector, filter_condition_jsonb, candidate_size,
          threshold_distance, effective_user_id, normalized_match_count,
          team_id_filter, state_code_filter;
end;
$_$;


ALTER FUNCTION private.semantic_simple_dataset_candidates(p_table regclass, query_embedding text, filter_condition text, match_threshold double precision, match_count integer, data_source text, state_code_filter integer, team_id_filter uuid) OWNER TO postgres;

--
-- Name: FUNCTION semantic_simple_dataset_candidates(p_table regclass, query_embedding text, filter_condition text, match_threshold double precision, match_count integer, data_source text, state_code_filter integer, team_id_filter uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.semantic_simple_dataset_candidates(p_table regclass, query_embedding text, filter_condition text, match_threshold double precision, match_count integer, data_source text, state_code_filter integer, team_id_filter uuid) IS 'Allow-listed, state/team-aware, visibility-first HNSW candidate generator shared by contacts, flow properties, sources, and unit groups.';


--
-- Name: semantic_simple_dataset_search(regclass, text, text, double precision, integer, text, integer, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.semantic_simple_dataset_search(p_table regclass, query_embedding text, filter_condition text DEFAULT ''::text, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 20, data_source text DEFAULT 'tg'::text, state_code_filter integer DEFAULT NULL::integer, team_id_filter uuid DEFAULT NULL::uuid) RETURNS TABLE(rank bigint, id uuid, "json" jsonb, version character, modified_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'extensions', 'pg_temp'
    SET statement_timeout TO '60s'
    AS $_$
declare
  normalized_data_source text;
  effective_user_id uuid;
  can_read_team_filter boolean;
  visibility_clause text;
  search_sql text;
begin
  if p_table not in (
    'public.contacts'::regclass,
    'public.flowproperties'::regclass,
    'public.sources'::regclass,
    'public.unitgroups'::regclass
  ) then
    raise exception 'unsupported semantic dataset table: %', p_table;
  end if;

  normalized_data_source := coalesce(nullif(lower(btrim(data_source)), ''), 'tg');
  effective_user_id := private.dataset_search_effective_user_id('');
  can_read_team_filter := private.dataset_search_can_read_team_filter(
    team_id_filter,
    effective_user_id
  );

  if normalized_data_source = 'tg' then
    visibility_clause := 'd.state_code = 100 and ($9::uuid is null or d.team_id = $9)';
  elsif normalized_data_source = 'co' then
    visibility_clause := 'd.state_code = 200 and ($9::uuid is null or d.team_id = $9)';
  elsif normalized_data_source = 'my' then
    if effective_user_id is null then
      return;
    end if;
    visibility_clause := 'd.user_id = $7 and ($8::integer is null or d.state_code = $8)';
  elsif normalized_data_source = 'te' then
    if team_id_filter is null or not can_read_team_filter then
      return;
    end if;
    visibility_clause := 'd.team_id = $9 and ($8::integer is null or d.state_code = $8)';
  else
    return;
  end if;

  search_sql := format(
    $sql$
      with semantic as materialized (
        select candidate.rank, candidate.id, candidate.distance
        from private.semantic_simple_dataset_candidates(
          $1, $2, $3, $4, $5, $6, $8, $9
        ) candidate
      ),
      visible_rows as (
        select
          d.id,
          d.json,
          d.version,
          d.modified_at,
          semantic.rank as semantic_rank,
          semantic.distance
        from %1$s d
        join semantic on semantic.id = d.id
        where %2$s
      ),
      latest_rows as (
        select distinct on (visible_rows.id)
          visible_rows.id,
          visible_rows.json,
          visible_rows.version,
          visible_rows.modified_at,
          visible_rows.semantic_rank,
          visible_rows.distance
        from visible_rows
        order by visible_rows.id, visible_rows.version desc, visible_rows.modified_at desc
      ),
      counted_rows as (
        select latest_rows.*, count(*) over()::bigint as total_count
        from latest_rows
      )
      select
        counted_rows.semantic_rank,
        counted_rows.id,
        counted_rows.json,
        counted_rows.version,
        counted_rows.modified_at,
        counted_rows.total_count
      from counted_rows
      order by counted_rows.semantic_rank, counted_rows.distance, counted_rows.id
    $sql$,
    p_table,
    visibility_clause
  );

  return query execute search_sql
    using p_table, query_embedding, filter_condition, match_threshold,
          match_count, normalized_data_source, effective_user_id,
          state_code_filter, team_id_filter;
end;
$_$;


ALTER FUNCTION private.semantic_simple_dataset_search(p_table regclass, query_embedding text, filter_condition text, match_threshold double precision, match_count integer, data_source text, state_code_filter integer, team_id_filter uuid) OWNER TO postgres;

--
-- Name: sources_sync_jsonb_version(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.sources_sync_jsonb_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NEW.json_ordered::jsonb IS DISTINCT FROM OLD.json_ordered::jsonb THEN
        NEW.json := NEW.json_ordered;
        NEW.version := COALESCE(NEW.json->'sourceDataSet'->'administrativeInformation'->'publicationAndOwnership'->>'common:dataSetVersion',
					''
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION private.sources_sync_jsonb_version() OWNER TO postgres;

--
-- Name: svc_lcia_document_validation_evidence_lookup(jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_document_validation_evidence_lookup(p_cache_keys jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
begin
  if not coalesce(util.is_service_request(), false) then return api.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  if jsonb_typeof(coalesce(p_cache_keys,'null'::jsonb)) <> 'array' then return api.lcia_scope_closure_error('invalid_document_evidence_keys',400,'Cache keys must be an array'); end if;
  return jsonb_build_object('ok',true,'data',coalesce((
    with requested as (
      select (value->>'datasetType') dataset_type, nullif(value->>'datasetId','')::uuid dataset_id,
        value->>'datasetVersion' dataset_version, value->>'canonicalContentHash' canonical_content_hash,
        value->>'documentValidatorVersion' document_validator_version,
        value->>'documentValidationProfile' document_validation_profile,
        value->>'validationReportSchemaVersion' validation_report_schema_version,
        value->>'validatorEngineFingerprint' validator_engine_fingerprint,
        value->>'tidasSchemaLockSha256' tidas_schema_lock_sha256
      from jsonb_array_elements(p_cache_keys)
    )
    select jsonb_agg(jsonb_build_object('datasetType',e.dataset_type,'datasetId',e.dataset_id,'datasetVersion',e.dataset_version,'canonicalContentHash',e.canonical_content_hash,'documentValidatorVersion',e.document_validator_version,'documentValidationProfile',e.document_validation_profile,'validationReportSchemaVersion',e.validation_report_schema_version,'validatorEngineFingerprint',e.validator_engine_fingerprint,'tidasSchemaLockSha256',e.tidas_schema_lock_sha256,'status',e.status,'summary',e.summary,'issueArtifactRef',e.issue_artifact_ref,'issueArtifactHash',e.issue_artifact_hash) order by e.dataset_type,e.dataset_id,e.dataset_version)
    from requested r join private.lcia_document_validation_evidence e on (e.dataset_type,e.dataset_id,e.dataset_version,e.canonical_content_hash,e.document_validator_version,e.document_validation_profile,e.validation_report_schema_version,e.validator_engine_fingerprint,e.tidas_schema_lock_sha256)=(r.dataset_type,r.dataset_id,r.dataset_version,r.canonical_content_hash,r.document_validator_version,r.document_validation_profile,r.validation_report_schema_version,r.validator_engine_fingerprint,r.tidas_schema_lock_sha256)
  ),'[]'::jsonb));
exception when invalid_text_representation then return api.lcia_scope_closure_error('invalid_document_evidence_keys',400,'Cache key contains invalid identity values');
end;
$$;


ALTER FUNCTION private.svc_lcia_document_validation_evidence_lookup(p_cache_keys jsonb) OWNER TO postgres;

--
-- Name: svc_lcia_document_validation_evidence_record(jsonb, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_document_validation_evidence_record(p_records jsonb, p_source_worker_job_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare v_record jsonb; v_inserted integer:=0;
begin
  if not coalesce(util.is_service_request(), false) then return api.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  if jsonb_typeof(coalesce(p_records,'null'::jsonb)) <> 'array' then return api.lcia_scope_closure_error('invalid_document_evidence_records',400,'Evidence records must be an array'); end if;
  for v_record in select value from jsonb_array_elements(p_records) loop
    insert into private.lcia_document_validation_evidence(dataset_type,dataset_id,dataset_version,canonical_content_hash,document_validator_version,document_validation_profile,validation_report_schema_version,validator_engine_fingerprint,tidas_schema_lock_sha256,status,summary,issue_artifact_ref,issue_artifact_hash,source_worker_job_id)
    values(nullif(v_record->>'datasetType',''),nullif(v_record->>'datasetId','')::uuid,nullif(v_record->>'datasetVersion',''),nullif(v_record->>'canonicalContentHash',''),nullif(v_record->>'documentValidatorVersion',''),nullif(v_record->>'documentValidationProfile',''),nullif(v_record->>'validationReportSchemaVersion',''),nullif(v_record->>'validatorEngineFingerprint',''),nullif(v_record->>'tidasSchemaLockSha256',''),nullif(v_record->>'status',''),coalesce(v_record->'summary','{}'::jsonb),coalesce(v_record->'issueArtifactRef','{}'::jsonb),nullif(v_record->>'issueArtifactHash',''),p_source_worker_job_id)
    on conflict (dataset_type,dataset_id,dataset_version,canonical_content_hash,document_validator_version,document_validation_profile,validation_report_schema_version,validator_engine_fingerprint,tidas_schema_lock_sha256) do nothing;
    if found then v_inserted:=v_inserted+1; end if;
  end loop;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('insertedCount',v_inserted));
exception when not_null_violation or invalid_text_representation or check_violation then return api.lcia_scope_closure_error('invalid_document_evidence_records',400,'Evidence record violates the cache contract');
end;
$$;


ALTER FUNCTION private.svc_lcia_document_validation_evidence_record(p_records jsonb, p_source_worker_job_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_result_build_bind_closure(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_result_build_bind_closure(p_worker_job_id uuid, p_closure_check_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare v_job private.worker_jobs%rowtype; v_check private.lcia_scope_closure_checks%rowtype; v_binding jsonb;
begin
  if not coalesce(util.is_service_request(), false) then return api.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  select * into v_job from private.worker_jobs where id=p_worker_job_id for update;
  select * into v_check from private.lcia_scope_closure_checks where id=p_closure_check_id;
  if v_job.id is null or v_job.job_kind<>'lcia_result.package_build' or v_check.id is null then return api.lcia_scope_closure_error('build_binding_not_found',404,'Build job or closure certificate not found'); end if;
  if v_check.status<>'passed' or v_check.scan_completeness<>'complete' or v_check.certificate_status<>'valid' then return api.lcia_scope_closure_error('closure_check_not_usable',409,'Closure certificate is not usable'); end if;
  v_binding:=jsonb_strip_nulls(jsonb_build_object('closure_check_id',v_check.id,'closure_certificate_hash',v_check.certificate_hash,'effective_scope_hash',v_check.effective_scope_hash,'data_snapshot_token',v_check.data_snapshot_token,'snapshot_id',v_check.snapshot_id,'snapshot_hash',v_check.snapshot_hash,'closure_bundle_hash',v_check.closure_bundle_hash,'report_artifact_manifest_hash',v_check.report_artifact_manifest_hash));
  update private.worker_jobs set payload_json=payload_json||v_binding,payload_ref=coalesce(payload_ref,'{}'::jsonb)||jsonb_build_object('closureCertificate',v_binding),updated_at=now() where id=v_job.id returning * into v_job;
  insert into private.worker_job_events(job_id,event_type,status,details) values(v_job.id,'closure_certificate_bound',v_job.status,jsonb_build_object('closureCheckId',v_check.id,'certificateHash',v_check.certificate_hash));
  return jsonb_build_object('ok',true,'data',jsonb_build_object('workerJobId',v_job.id,'closureCheckId',v_check.id));
end;
$$;


ALTER FUNCTION private.svc_lcia_result_build_bind_closure(p_worker_job_id uuid, p_closure_check_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_claim(integer, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_gc_claim(p_limit integer DEFAULT 100, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_claim_token uuid := gen_random_uuid();
  v_lease_expires_at timestamptz :=
    now() + make_interval(secs => p_lease_seconds);
  v_items jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_limit is null
     or p_limit not between 1 and 500
     or p_lease_seconds is null
     or p_lease_seconds not between 1 and 3600 then
    return api.lcia_scope_closure_error(
      'invalid_gc_claim', 400, 'Invalid GC claim bounds'
    );
  end if;
  with candidates as (
    select id
    from private.worker_job_artifacts
    where artifact_role is not null
      and (
        (
          lifecycle_state in ('ready', 'expired')
          and expires_at <= now()
        )
        or (
          lifecycle_state = 'deleted'
          and gc_cleanup_state = 'pending'
        )
      )
      and (
        gc_claim_token is null
        or gc_claim_expires_at is null
        or gc_claim_expires_at <= now()
      )
    order by
      case
        when lifecycle_state = 'deleted'
             and gc_cleanup_state = 'pending' then 0
        else 1
      end,
      expires_at,
      created_at,
      id
    for update skip locked
    limit p_limit
  ), claimed as (
    update private.worker_job_artifacts artifact
    set lifecycle_state = case
          when artifact.lifecycle_state = 'deleted' then 'deleted'
          else 'expired'
        end,
        gc_claim_token = v_claim_token,
        gc_claimed_at = now(),
        gc_claim_expires_at = v_lease_expires_at,
        gc_last_error = null
    from candidates
    where artifact.id = candidates.id
    returning artifact.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'artifactId', id,
    'artifactRole', artifact_role,
    'lifecycleState', lifecycle_state,
    'gcPhase', case
      when lifecycle_state = 'deleted' then 'detail_cleanup'
      else 'object_delete'
    end,
    'objectDeleteRequired', lifecycle_state <> 'deleted',
    'bucket', storage_bucket,
    'objectPath', storage_path,
    'checksumSha256', checksum_sha256,
    'artifactExpiresAt', expires_at
  ) order by
    case when lifecycle_state = 'deleted' then 0 else 1 end,
    expires_at,
    created_at,
    id
  ), '[]'::jsonb)
  into v_items
  from claimed;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'claimToken', v_claim_token,
    'leaseExpiresAt', v_lease_expires_at,
    'items', v_items
  ));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_gc_claim(p_limit integer, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_complete(uuid, uuid, boolean, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_gc_complete(p_artifact_id uuid, p_claim_token uuid, p_object_missing boolean DEFAULT false, p_detail_limit integer DEFAULT 10000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_artifact private.worker_job_artifacts%rowtype;
  v_check private.lcia_scope_closure_checks%rowtype;
  v_deleted_occurrences integer := 0;
  v_deleted_roots integer := 0;
  v_deleted_issues integer := 0;
  v_remaining bigint := 0;
  v_gc_phase text;
  v_object_delete_required boolean;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_detail_limit is null
     or p_detail_limit not between 1 and 50000 then
    return api.lcia_scope_closure_error(
      'invalid_gc_completion', 400, 'Invalid detail cleanup bound'
    );
  end if;

  select * into v_artifact
  from private.worker_job_artifacts
  where id = p_artifact_id
  for update;
  if v_artifact.id is null then
    return api.lcia_scope_closure_error(
      'artifact_not_found', 404, 'Artifact not found'
    );
  end if;

  if v_artifact.lifecycle_state = 'deleted'
     and v_artifact.gc_cleanup_state = 'complete'
     and v_artifact.gc_claim_token = p_claim_token then
    return jsonb_build_object('ok', true, 'reused', true, 'data',
      jsonb_build_object(
        'artifactId', v_artifact.id,
        'state', 'deleted',
        'lifecycleState', 'deleted',
        'gcPhase', 'detail_cleanup',
        'objectDeleteRequired', false,
        'objectMissing', p_object_missing,
        'detailsRemaining', 0,
        'cleanupPending', false,
        'cleanupComplete', true
      )
    );
  end if;

  if v_artifact.gc_claim_token is distinct from p_claim_token
     or v_artifact.gc_claim_expires_at is null
     or v_artifact.gc_claim_expires_at < now()
     or not (
       v_artifact.lifecycle_state = 'expired'
       or (
         v_artifact.lifecycle_state = 'deleted'
         and v_artifact.gc_cleanup_state = 'pending'
       )
     ) then
    return api.lcia_scope_closure_error(
      'gc_claim_invalid', 409, 'GC claim is not current'
    );
  end if;

  v_object_delete_required := v_artifact.lifecycle_state = 'expired';
  v_gc_phase := case
    when v_object_delete_required then 'object_delete'
    else 'detail_cleanup'
  end;

  select * into v_check
  from private.lcia_scope_closure_checks
  where report_artifact_id = v_artifact.id
     or complete_machine_result_artifact_id = v_artifact.id
     or closure_bundle_artifact_id = v_artifact.id
  order by finished_at nulls last, id
  limit 1
  for update;

  if v_check.id is not null then
    insert into private.lcia_scope_closure_retention_summaries (
      closure_check_id,
      issue_count,
      occurrence_count,
      affected_root_count,
      issue_content_hash,
      compact_result_summary
    )
    select
      v_check.id,
      (
        select count(*)
        from private.lcia_scope_closure_issues issue
        where issue.closure_check_id = v_check.id
      ),
      (
        select count(*)
        from private.lcia_scope_closure_issue_occurrences occurrence
        join private.lcia_scope_closure_issues issue
          on issue.id = occurrence.closure_issue_id
        where issue.closure_check_id = v_check.id
      ),
      (
        select count(*)
        from private.lcia_scope_closure_issue_roots root
        join private.lcia_scope_closure_issues issue
          on issue.id = root.closure_issue_id
        where issue.closure_check_id = v_check.id
      ),
      private.lcia_scope_closure_sha256(coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'issueKey', issue.issue_key,
            'issueCode', issue.issue_code,
            'severity', issue.severity,
            'blocking', issue.blocking,
            'occurrenceCount', issue.occurrence_count,
            'affectedRootCount', issue.affected_root_count
          )
          order by issue.issue_key, issue.id
        )
        from private.lcia_scope_closure_issues issue
        where issue.closure_check_id = v_check.id
      ), '[]'::jsonb)),
      v_check.result_summary
    on conflict (closure_check_id) do nothing;

    with doomed as (
      select occurrence.ctid
      from private.lcia_scope_closure_issue_occurrences occurrence
      join private.lcia_scope_closure_issues issue
        on issue.id = occurrence.closure_issue_id
      where issue.closure_check_id = v_check.id
      limit p_detail_limit
    )
    delete from private.lcia_scope_closure_issue_occurrences occurrence
    using doomed
    where occurrence.ctid = doomed.ctid;
    get diagnostics v_deleted_occurrences = row_count;

    with doomed as (
      select root.ctid
      from private.lcia_scope_closure_issue_roots root
      join private.lcia_scope_closure_issues issue
        on issue.id = root.closure_issue_id
      where issue.closure_check_id = v_check.id
      limit p_detail_limit
    )
    delete from private.lcia_scope_closure_issue_roots root
    using doomed
    where root.ctid = doomed.ctid;
    get diagnostics v_deleted_roots = row_count;

    if not exists (
      select 1
      from private.lcia_scope_closure_issue_occurrences occurrence
      join private.lcia_scope_closure_issues issue
        on issue.id = occurrence.closure_issue_id
      where issue.closure_check_id = v_check.id
    ) and not exists (
      select 1
      from private.lcia_scope_closure_issue_roots root
      join private.lcia_scope_closure_issues issue
        on issue.id = root.closure_issue_id
      where issue.closure_check_id = v_check.id
    ) then
      with doomed as (
        select ctid
        from private.lcia_scope_closure_issues
        where closure_check_id = v_check.id
        limit p_detail_limit
      )
      delete from private.lcia_scope_closure_issues issue
      using doomed
      where issue.ctid = doomed.ctid;
      get diagnostics v_deleted_issues = row_count;
    end if;

    select
      (select count(*)
       from private.lcia_scope_closure_issues
       where closure_check_id = v_check.id)
      + (
        select count(*)
        from private.lcia_scope_closure_issue_occurrences occurrence
        join private.lcia_scope_closure_issues issue
          on issue.id = occurrence.closure_issue_id
        where issue.closure_check_id = v_check.id
      )
      + (
        select count(*)
        from private.lcia_scope_closure_issue_roots root
        join private.lcia_scope_closure_issues issue
          on issue.id = root.closure_issue_id
        where issue.closure_check_id = v_check.id
      )
    into v_remaining;
  end if;

  update private.worker_job_artifacts
  set lifecycle_state = 'deleted',
      deleted_at = coalesce(deleted_at, now()),
      gc_cleanup_state = case
        when v_remaining > 0 then 'pending'
        else 'complete'
      end,
      gc_claim_expires_at = case
        when v_remaining > 0 then gc_claim_expires_at
        else null
      end,
      gc_last_error = null
  where id = v_artifact.id
  returning * into v_artifact;

  return jsonb_build_object('ok', true, 'reused', false, 'data',
    jsonb_build_object(
      'artifactId', v_artifact.id,
      'state', v_artifact.lifecycle_state,
      'lifecycleState', v_artifact.lifecycle_state,
      'gcPhase', v_gc_phase,
      'objectDeleteRequired', v_object_delete_required,
      'objectMissing', p_object_missing,
      'deletedOccurrences', v_deleted_occurrences,
      'deletedAffectedRoots', v_deleted_roots,
      'deletedIssues', v_deleted_issues,
      'detailsRemaining', v_remaining,
      'cleanupPending', v_remaining > 0,
      'cleanupComplete', v_remaining = 0
    )
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_gc_complete(p_artifact_id uuid, p_claim_token uuid, p_object_missing boolean, p_detail_limit integer) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_fail(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_gc_fail(p_artifact_id uuid, p_claim_token uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_artifact private.worker_job_artifacts%rowtype;
  v_gc_phase text;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if nullif(trim(coalesce(p_error, '')), '') is null then
    return api.lcia_scope_closure_error(
      'invalid_gc_failure', 400, 'GC failure reason is required'
    );
  end if;

  select * into v_artifact
  from private.worker_job_artifacts
  where id = p_artifact_id
  for update;
  if v_artifact.id is null then
    return api.lcia_scope_closure_error(
      'artifact_not_found', 404, 'Artifact not found'
    );
  end if;
  if v_artifact.lifecycle_state = 'deleted'
     and v_artifact.gc_cleanup_state = 'complete'
     and v_artifact.gc_claim_token = p_claim_token then
    return jsonb_build_object('ok', true, 'reused', true);
  end if;
  if v_artifact.gc_claim_token is distinct from p_claim_token
     or v_artifact.gc_claim_expires_at is null
     or v_artifact.gc_claim_expires_at < now()
     or not (
       v_artifact.lifecycle_state = 'expired'
       or (
         v_artifact.lifecycle_state = 'deleted'
         and v_artifact.gc_cleanup_state = 'pending'
       )
     ) then
    return api.lcia_scope_closure_error(
      'gc_claim_invalid', 409, 'GC claim is not current'
    );
  end if;

  v_gc_phase := case
    when v_artifact.lifecycle_state = 'deleted' then 'detail_cleanup'
    else 'object_delete'
  end;

  update private.worker_job_artifacts
  set gc_claim_token = null,
      gc_claimed_at = null,
      gc_claim_expires_at = null,
      gc_failure_count = gc_failure_count + 1,
      gc_last_error = left(trim(p_error), 1000)
  where id = v_artifact.id
  returning * into v_artifact;

  return jsonb_build_object('ok', true, 'reused', false, 'data',
    jsonb_build_object(
      'artifactId', v_artifact.id,
      'state', v_artifact.lifecycle_state,
      'lifecycleState', v_artifact.lifecycle_state,
      'gcPhase', v_gc_phase,
      'objectDeleteRequired', v_gc_phase = 'object_delete',
      'failureCount', v_artifact.gc_failure_count
    )
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_gc_fail(p_artifact_id uuid, p_claim_token uuid, p_error text) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_gc_preview(integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_gc_preview(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_items jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_limit is null or p_limit not between 1 and 500 then
    return api.lcia_scope_closure_error(
      'invalid_gc_preview', 400, 'Invalid GC preview bound'
    );
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'artifactId', artifact.id,
    'artifactRole', artifact.artifact_role,
    'lifecycleState', artifact.lifecycle_state,
    'gcPhase', case
      when artifact.lifecycle_state = 'deleted' then 'detail_cleanup'
      else 'object_delete'
    end,
    'objectDeleteRequired', artifact.lifecycle_state <> 'deleted',
    'bucket', artifact.storage_bucket,
    'objectPath', artifact.storage_path,
    'checksumSha256', artifact.checksum_sha256,
    'artifactExpiresAt', artifact.expires_at
  ) order by
    case when artifact.lifecycle_state = 'deleted' then 0 else 1 end,
    artifact.expires_at,
    artifact.created_at,
    artifact.id
  ), '[]'::jsonb)
  into v_items
  from (
    select *
    from private.worker_job_artifacts
    where artifact_role is not null
      and (
        (
          lifecycle_state in ('ready', 'expired')
          and expires_at <= now()
        )
        or (
          lifecycle_state = 'deleted'
          and gc_cleanup_state = 'pending'
        )
      )
      and (
        gc_claim_token is null
        or gc_claim_expires_at is null
        or gc_claim_expires_at <= now()
      )
    order by
      case
        when lifecycle_state = 'deleted'
             and gc_cleanup_state = 'pending' then 0
        else 1
      end,
      expires_at,
      created_at,
      id
    limit p_limit
  ) artifact;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'items', v_items
  ));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_gc_preview(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_gc_preview(p_limit integer); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_gc_preview(p_limit integer) IS 'Service-only, strictly non-mutating ordered preview of immediately claimable scope-closure GC candidates.';


--
-- Name: svc_lcia_scope_closure_artifact_gc_renew(uuid, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_gc_renew(p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_lease_expires_at timestamptz :=
    now() + make_interval(secs => p_lease_seconds);
  v_artifact_ids jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_claim_token is null
     or p_lease_seconds is null
     or p_lease_seconds not between 1 and 3600 then
    return api.lcia_scope_closure_error(
      'invalid_gc_renewal', 400, 'Invalid GC renewal request'
    );
  end if;
  with renewed as (
    update private.worker_job_artifacts artifact
    set gc_claim_expires_at = v_lease_expires_at
    where artifact.gc_claim_token = p_claim_token
      and artifact.gc_claim_expires_at >= now()
      and (
        artifact.lifecycle_state = 'expired'
        or (
          artifact.lifecycle_state = 'deleted'
          and artifact.gc_cleanup_state = 'pending'
        )
      )
    returning artifact.id
  )
  select jsonb_agg(id order by id)
  into v_artifact_ids
  from renewed;
  if v_artifact_ids is null then
    return api.lcia_scope_closure_error(
      'gc_claim_invalid', 409, 'GC claim is not current'
    );
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'claimToken', p_claim_token,
    'leaseExpiresAt', v_lease_expires_at,
    'artifactIds', v_artifact_ids
  ));
end;
$$;


