-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_fail_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_error text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_write_set_fail_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_error text) IS 'Service-only current-lease failure transition from registration_open or sealed staging into the existing fenced reconciliation/GC lifecycle.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_finalize(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_write_set private.lcia_scope_closure_artifact_write_sets%rowtype;
  v_report_id uuid;
  v_manifest_id uuid;
  v_bundle_id uuid;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select * into v_write_set
  from private.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return api.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.contract_version is not null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_fence_required',
      409,
      'Use the worker-lease-fenced v2 finalize RPC'
    );
  end if;
  if v_write_set.status = 'ready' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data', private.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
    );
  end if;
  if v_write_set.status <> 'staging'
     or v_write_set.staging_expires_at <= now() then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_finalizable',
      409,
      'Artifact write-set is not finalizable'
    );
  end if;

  select id into v_report_id
  from private.lcia_scope_closure_artifact_write_set_items
  where write_set_id = v_write_set.id
    and artifact_role = 'closure_report';
  if v_write_set.publication_mode = 'fresh' then
    select id into v_manifest_id
    from private.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'complete_machine_result'
      and content_type =
        'application/vnd.tiangong.scope-closure-manifest+json';
    select id into v_bundle_id
    from private.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'closure_bundle';
  end if;

  insert into private.worker_job_artifacts (
    id,
    job_id,
    artifact_type,
    artifact_role,
    lifecycle_state,
    storage_bucket,
    storage_path,
    content_type,
    byte_size,
    checksum_sha256,
    metadata,
    visibility,
    created_at,
    expires_at
  )
  select
    item.id,
    v_write_set.worker_job_id,
    item.artifact_type,
    item.artifact_role,
    'ready',
    item.storage_bucket,
    item.storage_path,
    item.content_type,
    item.byte_size,
    item.checksum_sha256,
    case
      when item.artifact_role = 'closure_bundle' then
        (item.metadata - 'completeMachineResultClientKey')
        || jsonb_build_object(
          'completeMachineResultArtifactId', v_manifest_id
        )
      else item.metadata
    end || jsonb_build_object(
      'writeSetId', v_write_set.id,
      'closureCheckId', v_write_set.closure_check_id,
      'clientKey', item.client_key
    ),
    'operator',
    now(),
    now() + interval '7 days'
  from private.lcia_scope_closure_artifact_write_set_items item
  where item.write_set_id = v_write_set.id
  order by item.ordinal;

  if v_write_set.publication_mode = 'fresh' then
    update private.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        complete_machine_result_artifact_id = v_manifest_id,
        closure_bundle_artifact_id = v_bundle_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id is null;
  else
    update private.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id = v_write_set.reused_from_check_id
      and complete_machine_result_artifact_id is not null
      and closure_bundle_artifact_id is not null;
  end if;
  if not found then
    raise exception 'artifact_write_set_closure_binding_changed'
      using errcode = '23514';
  end if;

  update private.lcia_scope_closure_artifact_write_sets
  set status = 'ready',
      finalized_at = now(),
      updated_at = now(),
      failure_reason = null
  where id = v_write_set.id
  returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_write_set_finalize(p_write_set_id uuid, p_write_token uuid) IS 'Service-only fenced atomic finalize. Fresh mode resolves completeMachineResultClientKey to completeMachineResultArtifactId and publishes all items; reused mode publishes only the new report and preserves source evidence bindings.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_finalize_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_job private.worker_jobs%rowtype;
  v_write_set private.lcia_scope_closure_artifact_write_sets%rowtype;
  v_report_id uuid;
  v_manifest_id uuid;
  v_bundle_id uuid;
  v_actual_sha256 text;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_write_set_id is null
     or p_write_token is null
     or p_worker_job_id is null
     or p_worker_lease_token is null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact write-set finalize request'
    );
  end if;

  select * into v_write_set
  from private.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null
     or v_write_set.contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2' then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return api.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.worker_job_id is distinct from p_worker_job_id then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job is not bound to the artifact write-set'
    );
  end if;

  select * into v_job
  from private.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now()
     or v_write_set.worker_lease_token_sha256 is distinct from
       private.lcia_scope_closure_artifact_v2_lease_sha256(
         p_worker_lease_token
       ) then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  if v_write_set.status = 'ready' then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;
  if v_write_set.status <> 'staging'
     or v_write_set.sealed_at is null
     or v_write_set.staging_expires_at <= now() then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_finalizable',
      409,
      'Artifact write-set is not finalizable'
    );
  end if;

  v_actual_sha256 :=
    private.lcia_scope_closure_worker_canonical_sha256(
      private.lcia_scope_closure_artifact_v2_descriptor_set(v_write_set.id)
    );
  if v_actual_sha256 is distinct from v_write_set.descriptor_set_sha256 then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_digest_mismatch',
      409,
      'Sealed artifact descriptor-set digest changed'
    );
  end if;

  select id into v_report_id
  from private.lcia_scope_closure_artifact_write_set_items
  where write_set_id = v_write_set.id
    and artifact_role = 'closure_report';
  if v_write_set.publication_mode = 'fresh' then
    select id into v_manifest_id
    from private.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'complete_machine_result'
      and content_type =
        'application/vnd.tiangong.scope-closure-manifest+json';
    select id into v_bundle_id
    from private.lcia_scope_closure_artifact_write_set_items
    where write_set_id = v_write_set.id
      and artifact_role = 'closure_bundle';
  end if;

  insert into private.worker_job_artifacts (
    id,
    job_id,
    artifact_type,
    artifact_role,
    lifecycle_state,
    storage_bucket,
    storage_path,
    content_type,
    byte_size,
    checksum_sha256,
    metadata,
    visibility,
    created_at,
    expires_at
  )
  select
    item.id,
    v_write_set.worker_job_id,
    item.artifact_type,
    item.artifact_role,
    'ready',
    item.storage_bucket,
    item.storage_path,
    item.content_type,
    item.byte_size,
    item.checksum_sha256,
    case
      when item.artifact_role = 'closure_bundle' then
        (item.metadata - 'completeMachineResultClientKey')
        || jsonb_build_object(
          'completeMachineResultArtifactId', v_manifest_id
        )
      else item.metadata
    end || jsonb_build_object(
      'writeSetId', v_write_set.id,
      'closureCheckId', v_write_set.closure_check_id,
      'clientKey', item.client_key
    ),
    'operator',
    now(),
    now() + interval '7 days'
  from private.lcia_scope_closure_artifact_write_set_items item
  where item.write_set_id = v_write_set.id
  order by item.ordinal;

  if v_write_set.publication_mode = 'fresh' then
    update private.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        complete_machine_result_artifact_id = v_manifest_id,
        closure_bundle_artifact_id = v_bundle_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id is null;
  else
    update private.lcia_scope_closure_checks
    set report_artifact_id = v_report_id,
        updated_at = now()
    where id = v_write_set.closure_check_id
      and worker_job_id = v_write_set.worker_job_id
      and reused_from_check_id = v_write_set.reused_from_check_id
      and complete_machine_result_artifact_id is not null
      and closure_bundle_artifact_id is not null;
  end if;
  if not found then
    raise exception 'artifact_write_set_closure_binding_changed'
      using errcode = '23514';
  end if;

  update private.lcia_scope_closure_artifact_write_sets
  set status = 'ready',
      finalized_at = now(),
      updated_at = now(),
      failure_reason = null
  where id = v_write_set.id
  returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_write_set_finalize_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) IS 'Service-only current-lease atomic finalize after object upload. Inserts every registered artifact as ready and updates the closure projection in the same transaction.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_inspect(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_inspect(p_write_set_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_data jsonb;
  v_contract_version text;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select contract_version into v_contract_version
  from private.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id;
  if not found then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_contract_version is not null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_status_required',
      409,
      'Use the lease-fenced v2 status RPC'
    );
  end if;
  v_data := private.lcia_scope_closure_artifact_write_set_json(p_write_set_id);
  return jsonb_build_object('ok', true, 'data', v_data);
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_inspect(p_write_set_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_write_set_reconcile(integer, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer DEFAULT 100, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_token uuid := gen_random_uuid();
  v_lease_expires_at timestamptz :=
    now() + make_interval(secs => p_lease_seconds);
  v_claimed_ids uuid[] := array[]::uuid[];
  v_items jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_limit is null
     or p_limit not between 1 and 500
     or p_lease_seconds is null
     or p_lease_seconds not between 1 and 3600 then
    return api.lcia_scope_closure_error(
      'artifact_write_set_reconcile_invalid', 400, 'Invalid reconcile bounds'
    );
  end if;
  with candidates as (
    select id
    from private.lcia_scope_closure_artifact_write_sets
    where (
      status = 'cleanup_pending'
      or (
        status in ('registration_open', 'staging')
        and staging_expires_at <= now()
      )
    )
      and (
        reconcile_token is null
        or reconcile_expires_at is null
        or reconcile_expires_at <= now()
      )
    order by staging_expires_at, created_at, id
    for update skip locked
    limit p_limit
  ), claimed as (
    update private.lcia_scope_closure_artifact_write_sets write_set
    set status = 'cleanup_pending',
        reconcile_token = v_token,
        reconcile_claimed_at = now(),
        reconcile_expires_at = v_lease_expires_at,
        updated_at = now()
    from candidates
    where write_set.id = candidates.id
    returning write_set.id
  )
  select coalesce(array_agg(claimed.id order by claimed.id), array[]::uuid[])
  into v_claimed_ids
  from claimed;

  select coalesce(jsonb_agg(
    private.lcia_scope_closure_artifact_write_set_json(claimed_id)
    order by claimed_id
  ), '[]'::jsonb)
  into v_items
  from unnest(v_claimed_ids) claimed_id;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'reconcileToken', v_token,
    'leaseExpiresAt', v_lease_expires_at,
    'writeSets', v_items
  ));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer, p_lease_seconds integer); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_write_set_reconcile(p_limit integer, p_lease_seconds integer) IS 'Service-only fenced stale-publication claim. Returns cleanup_pending write-set projections from a post-update statement so status, reconcileToken, and reconcileLeaseExpiresAt exactly match persisted claim state.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_reconcile_complete(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_reconcile_complete(p_write_set_id uuid, p_reconcile_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_write_set private.lcia_scope_closure_artifact_write_sets%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select * into v_write_set
  from private.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.status = 'cleaned'
     and v_write_set.reconcile_token = p_reconcile_token then
    return jsonb_build_object('ok', true, 'reused', true);
  end if;
  if v_write_set.status <> 'cleanup_pending'
     or v_write_set.reconcile_token is distinct from p_reconcile_token
     or v_write_set.reconcile_expires_at is null
     or v_write_set.reconcile_expires_at < now() then
    return api.lcia_scope_closure_error(
      'artifact_write_set_reconcile_invalid',
      409,
      'Artifact write-set reconcile claim is not current'
    );
  end if;
  update private.lcia_scope_closure_artifact_write_sets
  set status = 'cleaned',
      cleaned_at = now(),
      updated_at = now(),
      reconcile_expires_at = null
  where id = v_write_set.id;
  return jsonb_build_object('ok', true, 'reused', false, 'data',
    private.lcia_scope_closure_artifact_write_set_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_reconcile_complete(p_write_set_id uuid, p_reconcile_token uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_artifact_write_set_register_batch_v2(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_job private.worker_jobs%rowtype;
  v_write_set private.lcia_scope_closure_artifact_write_sets%rowtype;
  v_batch private.lcia_scope_closure_artifact_write_set_batches%rowtype;
  v_items jsonb;
  v_request_sha256 text;
  v_first_ordinal integer;
  v_last_ordinal integer;
  v_item_count integer;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_write_set_id is null
     or p_write_token is null
     or p_worker_job_id is null
     or p_worker_lease_token is null
     or p_batch_id is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) not between 1 and 500 then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact descriptor batch'
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    where jsonb_typeof(item) <> 'object'
       or (
         select count(*)
         from jsonb_object_keys(item) key
       ) <> 10
       or exists (
         select 1
         from jsonb_object_keys(item) key
         where key not in (
           'ordinal',
           'clientKey',
           'artifactType',
           'artifactRole',
           'bucket',
           'objectPath',
           'mediaType',
           'size',
           'checksumSha256',
           'metadata'
         )
       )
       or jsonb_typeof(item->'ordinal') <> 'number'
       or coalesce(item->>'ordinal', '') !~ '^[1-9][0-9]*$'
       or length(item->>'ordinal') > 6
       or nullif(item->>'clientKey', '') is null
       or item->>'clientKey' <> trim(item->>'clientKey')
       or length(item->>'clientKey') > 500
       or nullif(item->>'artifactType', '') is null
       or item->>'artifactType' <> trim(item->>'artifactType')
       or length(item->>'artifactType') > 200
       or nullif(item->>'artifactRole', '') is null
       or item->>'artifactRole' <> trim(item->>'artifactRole')
       or length(item->>'artifactRole') > 200
       or nullif(item->>'bucket', '') is null
       or item->>'bucket' <> trim(item->>'bucket')
       or length(item->>'bucket') > 255
       or nullif(item->>'objectPath', '') is null
       or item->>'objectPath' <> trim(item->>'objectPath')
       or length(item->>'objectPath') > 2048
       or nullif(item->>'mediaType', '') is null
       or item->>'mediaType' <> trim(item->>'mediaType')
       or length(item->>'mediaType') > 255
       or jsonb_typeof(item->'size') <> 'number'
       or coalesce(item->>'size', '') !~ '^(0|[1-9][0-9]*)$'
       or length(item->>'size') > 19
       or (
         length(item->>'size') = 19
         and item->>'size' > '9223372036854775807'
       )
       or coalesce(item->>'checksumSha256', '') !~ '^[a-f0-9]{64}$'
       or jsonb_typeof(item->'metadata') <> 'object'
       or octet_length((item->'metadata')::text) > 65536
       or private.lcia_scope_closure_artifact_role(
            item->>'artifactType'
          ) is distinct from item->>'artifactRole'
       or item->>'clientKey' like '/%'
       or item->>'clientKey' like '%//%'
       or item->>'clientKey' ~ '(^|/)\.\.?(/|$)'
       or item->>'clientKey' ~ '[[:cntrl:]\\]'
       or item->>'objectPath' like '/%'
       or item->>'objectPath' like '%//%'
       or item->>'objectPath' ~ '(^|/)\.\.?(/|$)'
       or item->>'objectPath' ~ '[[:cntrl:]\\]'
       or item->>'bucket' ~ '[[:cntrl:]/\\]'
  ) then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Staged artifact descriptor is invalid'
    );
  end if;

  if exists (
    select 1
    from (
      select
        (item.value->>'ordinal')::integer as ordinal,
        item.ordinality,
        lag((item.value->>'ordinal')::integer)
          over (order by item.ordinality) as previous_ordinal
      from jsonb_array_elements(p_items)
        with ordinality item(value, ordinality)
    ) ordered
    where (
      ordered.ordinality > 1
      and ordered.ordinal <> ordered.previous_ordinal + 1
    )
  ) then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Batch ordinals must be strictly ascending and contiguous'
    );
  end if;

  select jsonb_agg(jsonb_build_object(
    'ordinal', (item.value->>'ordinal')::integer,
    'clientKey', item.value->>'clientKey',
    'artifactType', item.value->>'artifactType',
    'artifactRole', item.value->>'artifactRole',
    'bucket', item.value->>'bucket',
    'objectPath', item.value->>'objectPath',
    'mediaType', item.value->>'mediaType',
    'size', (item.value->>'size')::bigint,
    'checksumSha256', item.value->>'checksumSha256',
    'metadata', item.value->'metadata'
  ) order by item.ordinality)
  into v_items
  from jsonb_array_elements(p_items)
    with ordinality item(value, ordinality);

  v_item_count := jsonb_array_length(v_items);
  v_first_ordinal := (v_items #>> '{0,ordinal}')::integer;
  v_last_ordinal :=
    (v_items #>> array[(v_item_count - 1)::text, 'ordinal'])::integer;
  v_request_sha256 :=
    private.lcia_scope_closure_worker_canonical_sha256(jsonb_build_object(
      'contractVersion',
        'lcia.scope-closure-artifact-write-set.v2',
      'batchId', p_batch_id,
      'items', v_items
    ));

  select * into v_write_set
  from private.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null
     or v_write_set.contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2' then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return api.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.worker_job_id is distinct from p_worker_job_id then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job is not bound to the artifact write-set'
    );
  end if;

  select * into v_job
  from private.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now()
     or v_write_set.worker_lease_token_sha256 is distinct from
       private.lcia_scope_closure_artifact_v2_lease_sha256(
         p_worker_lease_token
       ) then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  select * into v_batch
  from private.lcia_scope_closure_artifact_write_set_batches
  where write_set_id = v_write_set.id
    and batch_id = p_batch_id;
  if v_batch.write_set_id is not null then
    if v_batch.request_sha256 is distinct from v_request_sha256 then
      return api.lcia_scope_closure_error(
        'artifact_write_set_v2_batch_conflict',
        409,
        'Artifact descriptor batch identity conflicts'
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;

  if v_write_set.status <> 'registration_open'
     or v_write_set.staging_expires_at <= now() then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_registration_closed',
      409,
      'Artifact descriptor registration is closed'
    );
  end if;
  if v_first_ordinal < 1
     or v_last_ordinal > v_write_set.expected_descriptor_count then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Artifact descriptor ordinal is outside the expected range'
    );
  end if;

  begin
    insert into private.lcia_scope_closure_artifact_write_set_items (
      write_set_id,
      ordinal,
      client_key,
      artifact_type,
      artifact_role,
      storage_bucket,
      storage_path,
      content_type,
      byte_size,
      checksum_sha256,
      metadata
    )
    select
      v_write_set.id,
      (item->>'ordinal')::integer,
      item->>'clientKey',
      item->>'artifactType',
      item->>'artifactRole',
      item->>'bucket',
      item->>'objectPath',
      item->>'mediaType',
      (item->>'size')::bigint,
      item->>'checksumSha256',
      item->'metadata'
    from jsonb_array_elements(v_items) item
    order by (item->>'ordinal')::integer;

    insert into private.lcia_scope_closure_artifact_write_set_batches (
      write_set_id,
      batch_id,
      request_sha256,
      item_count,
      first_ordinal,
      last_ordinal
    ) values (
      v_write_set.id,
      p_batch_id,
      v_request_sha256,
      v_item_count,
      v_first_ordinal,
      v_last_ordinal
    );
  exception
    when unique_violation then
      return api.lcia_scope_closure_error(
        'artifact_write_set_v2_descriptor_conflict',
        409,
        'Artifact descriptor ordinal, client key, or locator conflicts'
      );
  end;

  update private.lcia_scope_closure_artifact_write_sets
  set updated_at = now()
  where id = v_write_set.id;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$_$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_write_set_register_batch_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_batch_id uuid, p_items jsonb) IS 'Service-only bounded registration of 1..500 exact descriptors. Batch UUID plus canonical bytes is idempotent; conflicting ordinal, client key, locator, or retry fails without partial insertion.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_seal_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $_$
declare
  v_job private.worker_jobs%rowtype;
  v_write_set private.lcia_scope_closure_artifact_write_sets%rowtype;
  v_item_count integer;
  v_min_ordinal integer;
  v_max_ordinal integer;
  v_actual_sha256 text;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_write_set_id is null
     or p_write_token is null
     or p_worker_job_id is null
     or p_worker_lease_token is null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact write-set seal request'
    );
  end if;

  select * into v_write_set
  from private.lcia_scope_closure_artifact_write_sets
  where id = p_write_set_id
  for update;
  if v_write_set.id is null
     or v_write_set.contract_version is distinct from
       'lcia.scope-closure-artifact-write-set.v2' then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;
  if v_write_set.write_token is distinct from p_write_token then
    return api.lcia_scope_closure_error(
      'artifact_write_set_token_invalid',
      409,
      'Artifact write-set token is not current'
    );
  end if;
  if v_write_set.worker_job_id is distinct from p_worker_job_id then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job is not bound to the artifact write-set'
    );
  end if;

  select * into v_job
  from private.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now()
     or v_write_set.worker_lease_token_sha256 is distinct from
       private.lcia_scope_closure_artifact_v2_lease_sha256(
         p_worker_lease_token
       ) then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  if v_write_set.status in ('staging', 'ready')
     and v_write_set.sealed_at is not null then
    return jsonb_build_object(
      'ok', true,
      'reused', true,
      'data',
        private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
    );
  end if;
  if v_write_set.status <> 'registration_open'
     or v_write_set.staging_expires_at <= now() then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_registration_closed',
      409,
      'Artifact descriptor registration is closed'
    );
  end if;

  select count(*), min(ordinal), max(ordinal)
  into v_item_count, v_min_ordinal, v_max_ordinal
  from private.lcia_scope_closure_artifact_write_set_items
  where write_set_id = v_write_set.id;
  if v_item_count <> v_write_set.expected_descriptor_count
     or v_min_ordinal is distinct from 1
     or v_max_ordinal is distinct from
       v_write_set.expected_descriptor_count then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_incomplete',
      409,
      'Artifact descriptor set is incomplete'
    );
  end if;

  v_actual_sha256 :=
    private.lcia_scope_closure_worker_canonical_sha256(
      private.lcia_scope_closure_artifact_v2_descriptor_set(v_write_set.id)
    );
  if v_actual_sha256 is distinct from v_write_set.descriptor_set_sha256 then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_digest_mismatch',
      409,
      'Artifact descriptor-set digest does not match'
    );
  end if;

  if v_write_set.required_primary_roles is distinct from
       private.lcia_scope_closure_artifact_v2_required_roles(
         v_write_set.publication_mode
       )
     or exists (
       select 1
       from private.lcia_scope_closure_artifact_write_set_items item
       where item.write_set_id = v_write_set.id
         and (
           item.metadata->>'schemaVersion' is distinct from
             'lcia.scope-closure-artifact.v2'
           or item.metadata->>'closureCheckId' is distinct from
             v_write_set.closure_check_id::text
           or item.metadata->>'fileName' is distinct from item.client_key
           or item.metadata->>'artifactRole' is distinct from
             item.artifact_role
           or item.metadata->>'retentionSeconds' is distinct from '604800'
           or coalesce(
             item.metadata->>'contentArtifactManifestHash',
             ''
           ) !~ '^[a-f0-9]{64}$'
           or position(
             'scope-closure/' || v_write_set.closure_check_id::text || '/'
             in item.storage_path
           ) = 0
           or right(
             item.storage_path,
             length(item.client_key) + 1
           ) <> '/' || item.client_key
         )
     ) then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_primary_roles_invalid',
      409,
      'Artifact descriptor invariants are invalid'
    );
  end if;

  if v_write_set.publication_mode = 'fresh' then
    if (
      select count(*)
      from private.lcia_scope_closure_artifact_write_set_items item
      where item.write_set_id = v_write_set.id
        and item.artifact_role = 'closure_report'
        and item.artifact_type = 'closure_report_xlsx'
        and item.content_type =
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    ) <> 1
       or (
         select count(*)
         from private.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'closure_report'
       ) <> 1
       or (
         select count(*)
         from private.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'closure_bundle'
           and item.artifact_type = 'closure_bundle'
           and item.content_type = 'application/json'
       ) <> 1
       or (
         select count(*)
         from private.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'closure_bundle'
       ) <> 1
       or (
         select count(*)
         from private.lcia_scope_closure_artifact_write_set_items item
         where item.write_set_id = v_write_set.id
           and item.artifact_role = 'complete_machine_result'
           and item.artifact_type = 'closure_complete_machine_result'
           and item.content_type =
             'application/vnd.tiangong.scope-closure-manifest+json'
       ) <> 1
       or not exists (
         select 1
         from private.lcia_scope_closure_artifact_write_set_items bundle
         join private.lcia_scope_closure_artifact_write_set_items manifest
           on manifest.write_set_id = bundle.write_set_id
          and manifest.client_key =
            bundle.metadata->>'completeMachineResultClientKey'
         where bundle.write_set_id = v_write_set.id
           and bundle.artifact_role = 'closure_bundle'
           and manifest.artifact_role = 'complete_machine_result'
           and manifest.artifact_type =
             'closure_complete_machine_result'
           and manifest.content_type =
             'application/vnd.tiangong.scope-closure-manifest+json'
       ) then
      return api.lcia_scope_closure_error(
        'artifact_write_set_v2_primary_roles_invalid',
        409,
        'Fresh publication primary artifact roles are invalid'
      );
    end if;
  elsif v_item_count <> 1
     or not exists (
       select 1
       from private.lcia_scope_closure_artifact_write_set_items item
       where item.write_set_id = v_write_set.id
         and item.artifact_role = 'closure_report'
         and item.artifact_type = 'closure_report_xlsx'
         and item.content_type =
           'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
     ) then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_primary_roles_invalid',
      409,
      'Reused publication primary artifact role is invalid'
    );
  end if;

  update private.lcia_scope_closure_artifact_write_sets
  set status = 'staging',
      sealed_at = now(),
      updated_at = now()
  where id = v_write_set.id
  returning * into v_write_set;

  return jsonb_build_object(
    'ok', true,
    'reused', false,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$_$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_write_set_seal_v2(p_write_set_id uuid, p_write_token uuid, p_worker_job_id uuid, p_worker_lease_token uuid) IS 'Service-only atomic seal. Under one write-set lock it verifies exact contiguous cardinality, canonical digest, primary roles, metadata and locator invariants, and current fences before the single registration_open-to-staging upload authorization.';


--
-- Name: svc_lcia_scope_closure_artifact_write_set_status_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_job private.worker_jobs%rowtype;
  v_write_set private.lcia_scope_closure_artifact_write_sets%rowtype;
  v_lease_sha256 text;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  if p_closure_check_id is null
     or p_worker_job_id is null
     or p_worker_lease_token is null
     or p_request_id is null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_v2_invalid',
      400,
      'Invalid staged artifact write-set status request'
    );
  end if;

  select * into v_job
  from private.worker_jobs
  where id = p_worker_job_id;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_worker_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now() then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is no longer valid'
    );
  end if;

  select * into v_write_set
  from private.lcia_scope_closure_artifact_write_sets
  where closure_check_id = p_closure_check_id
    and worker_job_id = p_worker_job_id
    and request_id = p_request_id
    and contract_version =
      'lcia.scope-closure-artifact-write-set.v2';
  if v_write_set.id is null then
    return api.lcia_scope_closure_error(
      'artifact_write_set_not_found', 404, 'Artifact write-set not found'
    );
  end if;

  v_lease_sha256 :=
    private.lcia_scope_closure_artifact_v2_lease_sha256(
      p_worker_lease_token
    );
  if v_write_set.worker_lease_token_sha256 is distinct from v_lease_sha256 then
    return api.lcia_scope_closure_error(
      'worker_job_lease_invalid',
      409,
      'Worker job lease is not bound to the artifact write-set'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', private.lcia_scope_closure_artifact_v2_status_json(v_write_set.id)
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_lcia_scope_closure_artifact_write_set_status_v2(p_closure_check_id uuid, p_worker_job_id uuid, p_worker_lease_token uuid, p_request_id uuid) IS 'Service-only current-lease status/readback for ambiguous responses. Returns fences, counts, batch ranges, and post-seal artifact IDs without owner identity, object locators, raw lease authority, or service credentials.';


--
-- Name: svc_lcia_scope_closure_build_binding(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_build_binding(build_worker_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_job private.worker_jobs%rowtype;
  v_check private.lcia_scope_closure_checks%rowtype;
  v_check_id uuid;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error(
      'service_role_required', 403, 'Service role is required'
    );
  end if;
  select * into v_job
  from private.worker_jobs
  where id = build_worker_job_id;
  if v_job.id is null
     or v_job.job_kind <> 'lcia_result.package_build' then
    return api.lcia_scope_closure_error(
      'build_binding_not_found', 404, 'Build job not found'
    );
  end if;
  begin
    v_check_id := nullif(v_job.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    return api.lcia_scope_closure_error(
      'build_binding_invalid', 409, 'Build payload contains an invalid closure check identity'
    );
  end;
  select * into v_check
  from private.lcia_scope_closure_checks
  where id = v_check_id
    and requested_by = v_job.requested_by;
  if v_check.id is null then
    return api.lcia_scope_closure_error(
      'closure_check_not_usable', 409, 'Closure certificate is not valid for this build owner'
    );
  end if;
  if v_check.valid_until <= now()
     or not private.lcia_scope_closure_evidence_usable(v_check) then
    return api.lcia_scope_closure_error(
      'closure_certificate_expired', 410, 'Closure certificate evidence has expired'
    );
  end if;
  return private.svc_lcia_scope_closure_build_binding_without_expiry(
    build_worker_job_id
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_build_binding(build_worker_job_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_build_binding_without_expiry(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_build_binding_without_expiry(build_worker_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_job private.worker_jobs%rowtype;
  v_check private.lcia_scope_closure_checks%rowtype;
  v_snapshot private.lca_network_snapshots%rowtype;
  v_artifact private.lca_snapshot_artifacts%rowtype;
  v_bundle private.worker_job_artifacts%rowtype;
  v_report private.worker_job_artifacts%rowtype;
  v_closure_check_id uuid;
  v_input_manifest jsonb;
  v_input_manifest_hash text;
  v_report_manifest_hash text;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  select * into v_job
  from private.worker_jobs
  where id = build_worker_job_id
  for update;
  if v_job.id is null or v_job.job_kind <> 'lcia_result.package_build' then
    return api.lcia_scope_closure_error('build_binding_not_found', 404, 'Build job not found');
  end if;
  if v_job.payload_schema_version <> 'lcia_result.package_build.request.v2'
     or v_job.status <> 'running'
     or v_job.lease_token is null
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at < now() then
    return api.lcia_scope_closure_error('build_worker_job_lease_invalid', 409, 'Build job does not hold a current running lease');
  end if;
  begin
    v_closure_check_id := nullif(v_job.payload_json->>'closure_check_id', '')::uuid;
  exception when invalid_text_representation then
    return api.lcia_scope_closure_error('build_binding_invalid', 409, 'Build payload contains an invalid closure check identity');
  end;
  select * into v_check
  from private.lcia_scope_closure_checks
  where id = v_closure_check_id
  for share;
  if v_check.id is null
     or v_check.requested_by <> v_job.requested_by
     or v_check.status <> 'passed'
     or v_check.scan_completeness <> 'complete'
     or v_check.certificate_status <> 'valid'
     or v_check.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
     or v_check.certificate_hash is null then
    return api.lcia_scope_closure_error('closure_check_not_usable', 409, 'Closure certificate is not valid for this build owner');
  end if;
  if v_check.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
     and not private.lcia_scope_closure_current_release_matches(v_check.data_snapshot_token) then
    return api.lcia_scope_closure_error('closure_check_stale', 409, 'Closure certificate was created against an earlier public release');
  end if;

  select * into v_snapshot
  from private.lca_network_snapshots
  where id = v_check.snapshot_id;
  select * into v_artifact
  from private.lca_snapshot_artifacts
  where id = v_check.snapshot_artifact_id;
  select * into v_bundle
  from private.worker_job_artifacts
  where id = v_check.closure_bundle_artifact_id;
  select * into v_report
  from private.worker_job_artifacts
  where id = v_check.report_artifact_id;
  v_input_manifest := jsonb_build_object(
    'predicateVersion', v_check.effective_scope_manifest->>'eligibilityPredicateVersion',
    'selectionMode', 'closure_certificate',
    'processes', v_check.effective_scope_manifest->'processes'
  );
  v_input_manifest_hash := private.lcia_scope_closure_sha256(v_input_manifest);
  v_report_manifest_hash := private.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_artifact.id is null
     or v_artifact.snapshot_id <> v_snapshot.id
     or v_artifact.status <> 'ready'
     or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_artifact.artifact_sha256 <> v_check.snapshot_hash
     or v_artifact.snapshot_index_sha256 <> v_check.snapshot_index_sha256
     or v_artifact.snapshot_build_contract_hash <> v_check.snapshot_build_contract_hash
     or v_artifact.effective_scope_hash <> v_check.effective_scope_hash
     or v_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_artifact.closure_bundle_hash <> v_check.closure_bundle_hash
     or not private.lcia_scope_closure_bundle_binding_matches(v_check, v_bundle)
     or v_report.id is null
     or v_report.job_id <> v_check.worker_job_id
     or v_report.artifact_type <> 'closure_report_xlsx'
     or v_report_manifest_hash <> v_check.report_artifact_manifest_hash then
    return api.lcia_scope_closure_error('closure_snapshot_binding_invalid', 409, 'Persisted closure snapshot evidence is no longer usable');
  end if;

  if coalesce(v_job.payload_json->>'closure_check_id', '') <> v_check.id::text
     or coalesce(v_job.payload_json->>'closure_certificate_hash', '') <> v_check.certificate_hash
     or coalesce(v_job.payload_json->>'requested_scope_hash', '') <> v_check.requested_scope_hash
     or coalesce(v_job.payload_json->>'policy_fingerprint', '') <> v_check.policy_fingerprint
     or coalesce(v_job.payload_json->>'effective_scope_hash', '') <> v_check.effective_scope_hash
     or coalesce(v_job.payload_json->>'data_snapshot_token', '') <> v_check.data_snapshot_token
     or coalesce(v_job.payload_json->>'snapshot_id', '') <> v_check.snapshot_id::text
     or coalesce(v_job.payload_json->>'snapshot_hash', '') <> v_check.snapshot_hash
     or coalesce(v_job.payload_json->>'closure_bundle_artifact_id', '') <> v_check.closure_bundle_artifact_id::text
     or coalesce(v_job.payload_json->>'closure_bundle_hash', '') <> v_check.closure_bundle_hash
     or coalesce(v_job.payload_json->>'report_artifact_manifest_hash', '') <> v_check.report_artifact_manifest_hash
     or coalesce(v_job.payload_json->>'snapshot_artifact_id', '') <> v_check.snapshot_artifact_id::text
     or coalesce(v_job.payload_json->>'snapshot_index_sha256', '') <> v_check.snapshot_index_sha256
     or coalesce(v_job.payload_json->>'snapshot_build_contract_hash', '') <> v_check.snapshot_build_contract_hash
     or coalesce(v_job.payload_json->'effective_scope', 'null'::jsonb) <> v_check.effective_scope_manifest
     or coalesce(v_job.payload_json->>'coverage_mode', '') <> v_check.effective_scope_manifest->>'coverageMode'
     or coalesce(v_job.payload_json->'lcia_method_set', 'null'::jsonb)
          <> coalesce(v_check.effective_scope_manifest->'lciaMethods', 'null'::jsonb)
     or coalesce(v_job.payload_json->'input_manifest', 'null'::jsonb) <> v_input_manifest
     or coalesce(v_job.payload_json->>'input_manifest_hash', '') <> v_input_manifest_hash then
    return api.lcia_scope_closure_error('build_binding_mismatch', 409, 'Build payload does not exactly match the database-owned certificate');
  end if;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id,
    'certificateHash', v_check.certificate_hash,
    'requestedScopeHash', v_check.requested_scope_hash,
    'policyFingerprint', v_check.policy_fingerprint,
    'effectiveScopeHash', v_check.effective_scope_hash,
    'dataSnapshotToken', v_check.data_snapshot_token,
    'snapshotId', v_check.snapshot_id,
    'snapshotHash', v_check.snapshot_hash,
    'closureBundleArtifactId', v_check.closure_bundle_artifact_id,
    'closureBundleHash', v_check.closure_bundle_hash,
    'snapshotArtifactId', v_check.snapshot_artifact_id,
    'snapshotIndexSha256', v_check.snapshot_index_sha256,
    'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
    'coverageMode', v_check.effective_scope_manifest->>'coverageMode',
    'lciaMethodSet', v_check.effective_scope_manifest->'lciaMethods',
    'inputManifest', v_input_manifest,
    'inputManifestHash', v_input_manifest_hash,
    'effectiveScope', v_check.effective_scope_manifest
  ));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_build_binding_without_expiry(build_worker_job_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_certificate_event(uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_certificate_event(p_closure_check_id uuid, p_certificate_status text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_check private.lcia_scope_closure_checks%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if p_certificate_status not in ('stale', 'revoked')
     or coalesce(nullif(trim(p_reason), ''), '') = '' then
    return api.lcia_scope_closure_error('invalid_certificate_event', 400, 'Certificate event status and reason are required');
  end if;

  select *
    into v_check
  from private.lcia_scope_closure_checks
  where id = p_closure_check_id
  for update;

  if v_check.id is null then
    return api.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if not (
    (v_check.certificate_status = 'valid' and p_certificate_status in ('stale', 'revoked'))
    or (v_check.certificate_status = 'stale' and p_certificate_status = 'revoked')
  ) then
    return api.lcia_scope_closure_error('invalid_certificate_transition', 409, 'Certificate validity transition is not allowed');
  end if;

  insert into private.lcia_scope_closure_certificate_events (
    closure_check_id,
    certificate_status,
    reason
  ) values (
    v_check.id,
    p_certificate_status,
    trim(p_reason)
  );

  update private.lcia_scope_closure_checks
  set certificate_status = p_certificate_status,
      updated_at = clock_timestamp()
  where id = v_check.id;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'closureCheckId', v_check.id,
      'certificateStatus', p_certificate_status
    )
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_certificate_event(p_closure_check_id uuid, p_certificate_status text, p_reason text) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_get_worker_input(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_check_get_worker_input(p_closure_check_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_check private.lcia_scope_closure_checks%rowtype;
  v_data_snapshot private.lcia_scope_closure_data_snapshots%rowtype;
  v_execution private.lcia_scope_closure_scan_executions%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  select * into v_check
  from private.lcia_scope_closure_checks
  where id = p_closure_check_id;
  select * into v_data_snapshot
  from private.lcia_scope_closure_data_snapshots
  where data_snapshot_token = v_check.data_snapshot_token;
  select * into v_execution
  from private.lcia_scope_closure_scan_executions
  where id = v_check.scan_execution_id;
  if v_check.id is null
     or v_check.requested_scope_manifest is null
     or v_data_snapshot.data_snapshot_token is null
     or v_execution.id is null
     or v_execution.numerical_snapshot_id is null then
    return api.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check or preallocated numerical snapshot not found');
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id,
    'scanExecutionId', v_check.scan_execution_id,
    'numericalSnapshotId', v_execution.numerical_snapshot_id,
    'requestedScope', v_check.requested_scope_manifest,
    'requestedScopeHash', v_check.requested_scope_hash,
    'policyFingerprint', v_check.policy_fingerprint,
    'dataSnapshotToken', v_check.data_snapshot_token,
    'dataSnapshotManifest', v_data_snapshot.root_manifest,
    'dataSnapshotManifestHash', v_data_snapshot.root_manifest_hash,
    'publicationEpoch', v_data_snapshot.publication_epoch,
    'expectedValidatorScannerFingerprint', v_check.expected_validator_scanner_fingerprint,
    'requestFingerprint', v_check.request_fingerprint
  ));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_check_get_worker_input(p_closure_check_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result(uuid, text, text, text, text, jsonb, text[], uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_check_record_result(p_closure_check_id uuid, p_status text, p_scan_completeness text, p_effective_scope_hash text, p_certificate_hash text DEFAULT NULL::text, p_result_summary jsonb DEFAULT '{}'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare v_check private.lcia_scope_closure_checks%rowtype; v_job private.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if p_status not in ('passed', 'blocked', 'failed', 'cancelled')
    or p_scan_completeness not in ('complete', 'incomplete')
    or jsonb_typeof(coalesce(p_result_summary, '{}'::jsonb)) <> 'object' then
    return api.lcia_scope_closure_error('invalid_closure_result', 400, 'Invalid closure result payload');
  end if;
  select * into v_check from private.lcia_scope_closure_checks where id = p_closure_check_id for update;
  if v_check.id is null then return api.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found'); end if;
  if p_report_artifact_id is not null and not exists (
    select 1 from private.worker_job_artifacts a where a.id = p_report_artifact_id and a.job_id = v_check.worker_job_id
  ) then return api.lcia_scope_closure_error('closure_report_unavailable', 409, 'Report artifact does not belong to the closure job'); end if;
  if p_status = 'blocked' and p_report_artifact_id is null then
    return api.lcia_scope_closure_error('closure_report_unavailable', 409, 'Blocked closure checks require a report artifact');
  end if;
  if p_status = 'passed' and p_scan_completeness <> 'complete' then
    return api.lcia_scope_closure_error('closure_check_incomplete', 409, 'A passed closure check must be complete');
  end if;
  if p_status = 'passed' and (coalesce(nullif(trim(p_effective_scope_hash), ''), '') = '' or coalesce(nullif(trim(p_certificate_hash), ''), '') = '') then
    return api.lcia_scope_closure_error('closure_evidence_unavailable', 409, 'Passed closure checks require effective scope and certificate evidence');
  end if;
  if p_status = 'passed' and coalesce(p_result_summary->>'evidenceHash', '') <> coalesce(nullif(trim(p_certificate_hash), ''), '') then
    return api.lcia_scope_closure_error('closure_evidence_hash_mismatch', 409, 'Certificate hash must match the worker evidence hash');
  end if;
  update private.lcia_scope_closure_checks
  set status = p_status, scan_completeness = p_scan_completeness,
      effective_scope_hash = nullif(trim(p_effective_scope_hash), ''), certificate_status = case when p_status = 'passed' then 'valid' else 'unavailable' end,
      certificate_hash = nullif(trim(p_certificate_hash), ''), result_summary = coalesce(p_result_summary, '{}'::jsonb),
      blocker_codes = coalesce(p_blocker_codes, '{}'::text[]), report_artifact_id = p_report_artifact_id,
      updated_at = now(), finished_at = now()
  where id = v_check.id returning * into v_check;
  update private.worker_jobs set status = case when p_status = 'passed' then 'completed' else p_status end,
      result_json = jsonb_build_object('closureCheckId', v_check.id, 'status', p_status,
        'scanCompleteness', p_scan_completeness, 'certificateStatus', case when p_status = 'passed' then 'valid' else 'unavailable' end,
        'effectiveScopeHash', v_check.effective_scope_hash, 'certificateHash', v_check.certificate_hash),
      blocker_codes = case when p_status = 'blocked' then coalesce(p_blocker_codes, '{}'::text[]) else blocker_codes end,
      resolution_scope = case when p_status = 'blocked' then 'operator' else resolution_scope end,
      finished_at = now(), updated_at = now()
  where id = v_check.worker_job_id returning * into v_job;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object('closureCheckId', v_check.id, 'workerJob', private.worker_job_payload(v_job, true)));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_check_record_result(p_closure_check_id uuid, p_status text, p_scan_completeness text, p_effective_scope_hash text, p_certificate_hash text, p_result_summary jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v2(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_check_record_result_v2(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb DEFAULT '{}'::jsonb, p_issues jsonb DEFAULT '[]'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
begin
  if lower(trim(coalesce(p_status, ''))) = 'passed' then
    return api.lcia_scope_closure_error(
      'closure_snapshot_evidence_v3_required', 409,
      'Passed closure checks require database-verified numerical snapshot evidence through record_result_v3'
    );
  end if;
  return private.svc_lcia_scope_closure_check_record_result_v2_legacy(
    p_closure_check_id,
    p_job_id,
    p_lease_token,
    p_status,
    p_scan_completeness,
    p_effective_scope_manifest,
    coalesce(p_evidence, '{}'::jsonb)
      - array['snapshotId', 'snapshotHash', 'snapshotArtifactId',
              'snapshotIndexSha256', 'snapshotBuildContractHash'],
    p_result_summary,
    p_issues,
    p_blocker_codes,
    p_report_artifact_id
  );
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_check_record_result_v2(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb, p_issues jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v2_legacy(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_check_record_result_v2_legacy(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb DEFAULT '{}'::jsonb, p_issues jsonb DEFAULT '[]'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb; v_check private.lcia_scope_closure_checks%rowtype; v_execution private.lcia_scope_closure_scan_executions%rowtype; v_scan_key text; v_existing_execution uuid;
begin
  select * into v_check from private.lcia_scope_closure_checks where id=p_closure_check_id;
  if v_check.id is null then return api.lcia_scope_closure_error('closure_check_not_found',404,'Closure check not found'); end if;
  if v_check.scan_execution_id is not null then
    select * into v_execution from private.lcia_scope_closure_scan_executions where id=v_check.scan_execution_id for update;
    if v_execution.status<>'running' or v_execution.leased_by_job_id<>p_job_id or v_execution.lease_token is distinct from p_lease_token then return api.lcia_scope_closure_error('scan_execution_lease_invalid',409,'Scan execution is not held by this worker job'); end if;
  end if;
  v_result:=private.svc_lcia_scope_closure_check_record_result_v2_untracked(p_closure_check_id,p_job_id,p_lease_token,p_status,p_scan_completeness,p_effective_scope_manifest,p_evidence,p_result_summary,p_issues,p_blocker_codes,p_report_artifact_id);
  if coalesce((v_result->>'ok')::boolean,false) is not true then return v_result; end if;
  if v_execution.id is not null then
    select * into v_check from private.lcia_scope_closure_checks where id=p_closure_check_id;
    v_scan_key:=private.lcia_scope_closure_sha256(jsonb_build_object('effectiveScopeHash',v_check.effective_scope_hash,'policyFingerprint',v_check.policy_fingerprint,'validatorScannerFingerprint',v_check.expected_validator_scanner_fingerprint,'dataSnapshotToken',v_check.data_snapshot_token));
    select id into v_existing_execution from private.lcia_scope_closure_scan_executions where scan_key=v_scan_key and id<>v_execution.id limit 1;
    if v_existing_execution is not null then v_scan_key:=null; end if;
    update private.lcia_scope_closure_scan_executions set scan_key=v_scan_key,status=case when lower(trim(p_status))='passed' or (lower(trim(p_status))='blocked' and p_scan_completeness='complete') then 'completed' else 'failed' end,lease_token=null,leased_by_job_id=null,lease_expires_at=null,completed_check_id=case when lower(trim(p_status))='passed' or (lower(trim(p_status))='blocked' and p_scan_completeness='complete') then p_closure_check_id else null end,source_fingerprint=nullif(p_evidence->>'sourceFingerprint',''),evidence_hash=nullif(p_evidence->>'evidenceHash',''),updated_at=now(),completed_at=now() where id=v_execution.id;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_check_record_result_v2_legacy(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb, p_issues jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v2_untracked(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_check_record_result_v2_untracked(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb DEFAULT '{}'::jsonb, p_issues jsonb DEFAULT '[]'::jsonb, p_blocker_codes text[] DEFAULT '{}'::text[], p_report_artifact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_check private.lcia_scope_closure_checks%rowtype; v_job private.worker_jobs%rowtype; v_status text := lower(trim(p_status));
  v_effective_hash text; v_certificate_bindings jsonb; v_certificate_hash text; v_worker_status text; v_issue jsonb; v_worker_result jsonb;
  v_closure_issue private.lcia_scope_closure_issues%rowtype; v_occurrence jsonb; v_root jsonb;
  v_artifact private.worker_job_artifacts%rowtype; v_report_artifact_manifest_hash text; v_worker_record jsonb;
begin
  if not coalesce(util.is_service_request(), false) then return api.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  if v_status not in ('passed','blocked','failed') or p_scan_completeness not in ('complete','incomplete','unknown')
     or jsonb_typeof(coalesce(p_effective_scope_manifest,'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_evidence,'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_result_summary,'{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_issues,'[]'::jsonb)) <> 'array' then return api.lcia_scope_closure_error('invalid_closure_result',400,'Invalid closure result payload'); end if;
  select * into v_check from private.lcia_scope_closure_checks where id = p_closure_check_id for update;
  if v_check.id is null or v_check.worker_job_id <> p_job_id then return api.lcia_scope_closure_error('closure_check_not_found',404,'Closure check not found'); end if;
  if v_check.status not in ('queued','running') then return api.lcia_scope_closure_error('closure_check_already_terminal',409,'Closure check is already terminal'); end if;
  select * into v_job from private.worker_jobs where id = p_job_id for update;
  if v_job.status <> 'running' or v_job.lease_token is distinct from p_lease_token or v_job.lease_expires_at < now() then return api.lcia_scope_closure_error('worker_job_lease_invalid',409,'Worker job lease is no longer valid'); end if;
  select * into v_artifact from private.worker_job_artifacts where id = p_report_artifact_id and job_id = v_job.id;
  if p_report_artifact_id is not null and v_artifact.id is null then return api.lcia_scope_closure_error('closure_report_unavailable',409,'Report artifact does not belong to the closure job'); end if;
  if v_status in ('passed','blocked') and p_report_artifact_id is null then return api.lcia_scope_closure_error('closure_report_unavailable',409,'Completed closure checks require a report artifact'); end if;
  if v_status = 'passed' and (p_scan_completeness <> 'complete' or exists (
    select 1 from jsonb_array_elements(p_issues) issue(value)
    where coalesce((issue.value->>'blocking')::boolean, false)
  )) then return api.lcia_scope_closure_error('closure_check_incomplete',409,'Passed closure checks must be complete and free of blocking issues'); end if;
  if v_status = 'blocked' and (cardinality(coalesce(p_blocker_codes,'{}'::text[])) = 0 or jsonb_array_length(p_issues) = 0) then return api.lcia_scope_closure_error('closure_blocker_details_required',409,'Blocked closure checks require issues and blocker codes'); end if;
  if v_status = 'passed' and not (p_evidence ?& array['schemaVersion','sourceFingerprint','resolutionMapHash','closureBundleHash','snapshotId','snapshotHash','reportArtifactManifestHash','evidenceHash']) then return api.lcia_scope_closure_error('closure_evidence_unavailable',409,'Passed closure checks require complete evidence'); end if;
  if p_report_artifact_id is not null then
    v_report_artifact_manifest_hash := private.lcia_scope_closure_sha256(jsonb_build_object('artifactId',v_artifact.id,'bucket',v_artifact.storage_bucket,'objectPath',v_artifact.storage_path,'mediaType',v_artifact.content_type,'byteSize',v_artifact.byte_size,'checksumSha256',v_artifact.checksum_sha256));
  end if;
  if v_status = 'passed' and coalesce(p_evidence->>'reportArtifactManifestHash','') <> coalesce(v_report_artifact_manifest_hash,'') then return api.lcia_scope_closure_error('closure_report_hash_mismatch',409,'Report artifact manifest hash does not match persisted artifact metadata'); end if;
  v_effective_hash := private.lcia_scope_closure_sha256(p_effective_scope_manifest);
  if v_status = 'passed' then
    v_certificate_bindings := jsonb_build_object('certificateSchemaVersion','lcia.scope-closure-certificate.v1','requestedScopeHash',v_check.requested_scope_hash,'scopeHash',v_effective_hash,'policyFingerprint',v_check.policy_fingerprint,'dataSnapshotToken',v_check.data_snapshot_token,'validatorScannerFingerprint',v_check.expected_validator_scanner_fingerprint,'sourceFingerprint',p_evidence->>'sourceFingerprint','resolutionMapHash',p_evidence->>'resolutionMapHash','closureBundleHash',p_evidence->>'closureBundleHash','snapshotId',p_evidence->>'snapshotId','snapshotHash',p_evidence->>'snapshotHash','reportArtifactManifestHash',p_evidence->>'reportArtifactManifestHash','evidenceHash',p_evidence->>'evidenceHash');
    v_certificate_hash := private.lcia_scope_closure_sha256(v_certificate_bindings);
  end if;
  delete from private.lcia_scope_closure_issues where closure_check_id = v_check.id;
  for v_issue in select value from jsonb_array_elements(p_issues) loop
    insert into private.lcia_scope_closure_issues(closure_check_id,issue_key,severity,blocking,issue_code,source_dataset_type,source_dataset_id,source_dataset_version,json_path,reference_role,requested_target_type,requested_target_id,requested_target_version,message,suggested_action,occurrence_count,affected_root_count,details)
    values(v_check.id,coalesce(nullif(trim(v_issue->>'issueKey'),''),private.lcia_scope_closure_sha256(v_issue)),coalesce(v_issue->>'severity','blocker'),coalesce((v_issue->>'blocking')::boolean,false),coalesce(nullif(trim(v_issue->>'issueCode'),''),'closure_issue'),nullif(v_issue->>'sourceDatasetType',''),nullif(v_issue->>'sourceDatasetId','')::uuid,nullif(v_issue->>'sourceDatasetVersion',''),nullif(v_issue->>'jsonPath',''),nullif(v_issue->>'referenceRole',''),nullif(v_issue->>'requestedTargetType',''),nullif(v_issue->>'requestedTargetId','')::uuid,nullif(v_issue->>'requestedTargetVersion',''),coalesce(nullif(v_issue->>'message',''),'Closure validation issue'),nullif(v_issue->>'suggestedAction',''),greatest(1,coalesce((v_issue->>'occurrenceCount')::integer,1)),greatest(0,coalesce((v_issue->>'affectedRootCount')::integer,0)),coalesce(v_issue->'details','{}'::jsonb)) returning * into v_closure_issue;
    for v_occurrence in select value from jsonb_array_elements(coalesce(v_issue->'occurrences','[]'::jsonb)) loop
      insert into private.lcia_scope_closure_issue_occurrences(closure_issue_id,occurrence_key,source_dataset_type,source_dataset_id,source_dataset_version,json_path,reference_role,details)
      values(v_closure_issue.id,coalesce(nullif(v_occurrence->>'occurrenceKey',''),private.lcia_scope_closure_sha256(v_occurrence)),nullif(v_occurrence->>'sourceDatasetType',''),nullif(v_occurrence->>'sourceDatasetId','')::uuid,nullif(v_occurrence->>'sourceDatasetVersion',''),nullif(v_occurrence->>'jsonPath',''),nullif(v_occurrence->>'referenceRole',''),coalesce(v_occurrence->'details','{}'::jsonb));
    end loop;
    for v_root in select value from jsonb_array_elements(coalesce(v_issue->'affectedRoots','[]'::jsonb)) loop
      insert into private.lcia_scope_closure_issue_roots(closure_issue_id,root_dataset_type,root_dataset_id,root_dataset_version,impact_role,witness_path)
      values(v_closure_issue.id,coalesce(nullif(v_root->>'datasetType',''),'process'),(v_root->>'id')::uuid,coalesce(nullif(v_root->>'version',''),'00.00.000'),coalesce(nullif(v_root->>'impactRole',''),'root'),coalesce(v_root->'witnessPath','[]'::jsonb));
    end loop;
  end loop;
  update private.lcia_scope_closure_checks set status=v_status,scan_completeness=p_scan_completeness,effective_scope_manifest=p_effective_scope_manifest,effective_scope_hash=v_effective_hash,certificate_schema_version=case when v_status='passed' then 'lcia.scope-closure-certificate.v1' else null end,certificate_status=case when v_status='passed' then 'valid' else 'unavailable' end,certificate_hash=v_certificate_hash,source_fingerprint=nullif(p_evidence->>'sourceFingerprint',''),resolution_map_hash=nullif(p_evidence->>'resolutionMapHash',''),closure_bundle_hash=nullif(p_evidence->>'closureBundleHash',''),snapshot_id=nullif(p_evidence->>'snapshotId','')::uuid,snapshot_hash=nullif(p_evidence->>'snapshotHash',''),report_artifact_manifest_hash=nullif(p_evidence->>'reportArtifactManifestHash',''),evidence_hash=nullif(p_evidence->>'evidenceHash',''),result_summary=p_result_summary,blocker_codes=coalesce(p_blocker_codes,'{}'::text[]),report_artifact_id=p_report_artifact_id,updated_at=now(),finished_at=now() where id=v_check.id returning * into v_check;
  v_worker_status := case v_status when 'passed' then 'completed' else v_status end;
  v_worker_result := jsonb_strip_nulls(jsonb_build_object('closureCheckId',v_check.id,'status',v_status,'scanCompleteness',p_scan_completeness,'certificateStatus',v_check.certificate_status,'effectiveScopeHash',v_check.effective_scope_hash,'certificateHash',v_check.certificate_hash));
  select private.worker_record_job_result(v_job.id,p_lease_token,v_worker_status,v_worker_result,'lcia.scope_closure_check.result.v1',null,jsonb_build_object('progressCounters',coalesce(p_result_summary->'progressCounters','{}'::jsonb)),case when v_status='failed' then coalesce(p_result_summary->>'errorCode','closure_check_failed') else null end,case when v_status='failed' then 'Scope closure check failed' else null end,null,case when v_status='blocked' then coalesce(p_blocker_codes,'{}'::text[]) else null end,case when v_status='blocked' then 'operator' else null end,case when v_status='failed' then true else false end) into v_worker_record;
  if coalesce((v_worker_record->>'ok')::boolean,false) is not true then raise exception using errcode='P0001',message='worker_job_result_rejected'; end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('closureCheckId',v_check.id,'certificateHash',v_certificate_hash,'workerJobId',v_job.id));
exception when invalid_text_representation then return api.lcia_scope_closure_error('invalid_closure_result',400,'Closure result contains invalid identity values');
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_check_record_result_v2_untracked(p_closure_check_id uuid, p_job_id uuid, p_lease_token uuid, p_status text, p_scan_completeness text, p_effective_scope_manifest jsonb, p_evidence jsonb, p_result_summary jsonb, p_issues jsonb, p_blocker_codes text[], p_report_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_check_record_result_v3(uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb, jsonb, text[], uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_check_record_result_v3(check_id uuid, worker_job_id uuid, lease_token uuid, status text, scan_completeness text, effective_scope jsonb, evidence jsonb, result_summary jsonb, issues jsonb, blocker_codes text[], report_artifact_id uuid, closure_bundle_artifact_id uuid, snapshot_artifact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_status text := lower(trim(coalesce(status, '')));
  v_check private.lcia_scope_closure_checks%rowtype;
  v_job private.worker_jobs%rowtype;
  v_execution private.lcia_scope_closure_scan_executions%rowtype;
  v_snapshot private.lca_network_snapshots%rowtype;
  v_snapshot_artifact private.lca_snapshot_artifacts%rowtype;
  v_report private.worker_job_artifacts%rowtype;
  v_bundle private.worker_job_artifacts%rowtype;
  v_effective_scope_hash text;
  v_report_manifest_hash text;
  v_evidence_hash text;
  v_build_contract_hash text;
  v_certificate_hash text;
  v_certificate_bindings jsonb;
  v_issue jsonb;
  v_occurrence jsonb;
  v_root jsonb;
  v_closure_issue private.lcia_scope_closure_issues%rowtype;
  v_worker_result jsonb;
  v_scan_key text;
  v_existing_execution uuid;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if v_status not in ('passed', 'blocked', 'failed')
     or scan_completeness not in ('complete', 'incomplete', 'unknown')
     or jsonb_typeof(coalesce(effective_scope, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(evidence, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(result_summary, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(issues, 'null'::jsonb)) <> 'array' then
    return api.lcia_scope_closure_error('invalid_closure_result', 400, 'Invalid closure result payload');
  end if;

  -- Blocked and failed checks intentionally do not acquire or persist a
  -- numerical snapshot binding.  V2 remains the compatibility path for those
  -- non-certificate terminal states.
  if v_status <> 'passed' then
    return private.svc_lcia_scope_closure_check_record_result_v2_legacy(
      check_id, worker_job_id, lease_token, v_status, scan_completeness,
      effective_scope,
      coalesce(evidence, '{}'::jsonb)
        - array['snapshotId', 'snapshotHash', 'snapshotArtifactId',
                'snapshotIndexSha256', 'snapshotBuildContractHash'],
      result_summary, issues, blocker_codes, report_artifact_id
    );
  end if;

  if scan_completeness <> 'complete'
     or exists (
       select 1 from jsonb_array_elements(issues) issue(value)
       where coalesce((issue.value->>'blocking')::boolean, false)
     ) then
    return api.lcia_scope_closure_error('closure_check_incomplete', 409, 'Passed closure checks must be complete and free of blocking issues');
  end if;
  if evidence->>'schemaVersion' is distinct from 'lcia.scope-closure-evidence.v2'
     or result_summary->>'schemaVersion' is distinct from 'lcia.scope-closure-summary.v1'
     or not (evidence ?& array[
    'sourceFingerprint', 'resolutionMapHash', 'closureBundleHash',
    'closureBundleArtifactId', 'snapshotId', 'snapshotHash', 'snapshotArtifactId',
    'snapshotIndexSha256', 'snapshotBuildContractHash', 'evidenceHash'
  ]) or not (result_summary ? 'evidenceHash') then
    return api.lcia_scope_closure_error('closure_evidence_unavailable', 409, 'Passed closure checks require complete numerical snapshot evidence');
  end if;

  select * into v_check
  from private.lcia_scope_closure_checks
  where id = check_id
  for update;
  if v_check.id is null or v_check.worker_job_id <> worker_job_id then
    return api.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if v_check.status not in ('queued', 'running') then
    return api.lcia_scope_closure_error('closure_check_already_terminal', 409, 'Closure check is already terminal');
  end if;

  select * into v_job
  from private.worker_jobs
  where id = worker_job_id
  for update;
  if v_job.id is null
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from lease_token
     or v_job.lease_expires_at < now() then
    return api.lcia_scope_closure_error('worker_job_lease_invalid', 409, 'Worker job lease is no longer valid');
  end if;

  select * into v_execution
  from private.lcia_scope_closure_scan_executions
  where id = v_check.scan_execution_id
  for update;
  if v_execution.id is null
     or v_execution.status <> 'running'
     or v_execution.leased_by_job_id <> worker_job_id
     or v_execution.lease_token is distinct from lease_token then
    return api.lcia_scope_closure_error('scan_execution_lease_invalid', 409, 'Scan execution is not held by this worker job');
  end if;

  select * into v_report
  from private.worker_job_artifacts
  where id = report_artifact_id
    and job_id = v_job.id
    and artifact_type = 'closure_report_xlsx';
  if v_report.id is null then
    return api.lcia_scope_closure_error('closure_report_unavailable', 409, 'Report artifact does not belong to the closure job or has the wrong type');
  end if;

  select * into v_bundle
  from private.worker_job_artifacts
  where id = closure_bundle_artifact_id
    and job_id = v_job.id
    and artifact_type = 'closure_bundle';
  if v_bundle.id is null
     or v_bundle.checksum_sha256 is null
     or v_bundle.id::text <> evidence->>'closureBundleArtifactId'
     or v_bundle.checksum_sha256 <> evidence->>'closureBundleHash'
     or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_check.id::text then
    return api.lcia_scope_closure_error('closure_bundle_binding_invalid', 409, 'Closure bundle does not belong to this check or its hash does not match');
  end if;

  select * into v_snapshot
  from private.lca_network_snapshots
  where id = v_execution.numerical_snapshot_id
  for update;
  select * into v_snapshot_artifact
  from private.lca_snapshot_artifacts
  where id = snapshot_artifact_id;

  v_effective_scope_hash := private.lcia_scope_closure_sha256(effective_scope);
  v_build_contract_hash := private.lcia_scope_closure_sha256_text(
    'lcia.numerical-snapshot-build-contract.v1' || chr(10)
    || v_effective_scope_hash || chr(10)
    || v_check.data_snapshot_token || chr(10)
    || v_bundle.checksum_sha256 || chr(10)
    || v_execution.numerical_snapshot_id::text || chr(10)
    || coalesce(v_snapshot_artifact.artifact_format, '')
  );

  if v_snapshot.id is null
     or v_snapshot.status <> 'ready'
     or v_snapshot.scope <> 'data_product'
     or v_snapshot.provider_matching_rule <> 'split_by_process_volume'
     or v_snapshot.id::text <> evidence->>'snapshotId'
     or v_snapshot_artifact.id is null
     or v_snapshot_artifact.id::text <> evidence->>'snapshotArtifactId'
     or v_snapshot_artifact.snapshot_id <> v_snapshot.id
     or v_snapshot_artifact.status <> 'ready'
     or v_snapshot_artifact.artifact_format <> 'snapshot-hdf5:v1'
     or v_snapshot_artifact.artifact_sha256 <> evidence->>'snapshotHash'
     or v_snapshot_artifact.snapshot_index_sha256 <> evidence->>'snapshotIndexSha256'
     or v_snapshot_artifact.snapshot_build_contract_hash <> evidence->>'snapshotBuildContractHash'
     or v_snapshot_artifact.snapshot_build_contract_hash <> v_build_contract_hash
     or v_snapshot_artifact.effective_scope_hash <> v_effective_scope_hash
     or v_snapshot_artifact.data_snapshot_token <> v_check.data_snapshot_token
     or v_snapshot_artifact.closure_bundle_hash <> v_bundle.checksum_sha256 then
    return api.lcia_scope_closure_error('numerical_snapshot_binding_invalid', 409, 'Numerical snapshot or artifact does not satisfy the closure certificate contract');
  end if;

  v_report_manifest_hash := private.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if coalesce(evidence->>'reportArtifactManifestHash', '') <> v_report_manifest_hash then
    return api.lcia_scope_closure_error('closure_report_hash_mismatch', 409, 'Report artifact manifest hash does not match persisted artifact metadata');
  end if;

  v_evidence_hash := private.lcia_scope_closure_sha256_text(
    'lcia.scope-closure-evidence.v2' || chr(10)
    || (evidence->>'sourceFingerprint') || chr(10)
    || (evidence->>'resolutionMapHash') || chr(10)
    || v_bundle.checksum_sha256 || chr(10)
    || v_bundle.id::text || chr(10)
    || v_snapshot.id::text || chr(10)
    || v_snapshot_artifact.artifact_sha256 || chr(10)
    || v_snapshot_artifact.id::text || chr(10)
    || v_snapshot_artifact.snapshot_index_sha256 || chr(10)
    || v_snapshot_artifact.snapshot_build_contract_hash
  );
  if evidence->>'evidenceHash' <> v_evidence_hash
     or result_summary->>'evidenceHash' <> v_evidence_hash then
    return api.lcia_scope_closure_error('closure_evidence_hash_mismatch', 409, 'Closure evidence hash does not match database-owned snapshot evidence');
  end if;

  v_certificate_bindings := jsonb_build_object(
    'certificateSchemaVersion', 'lcia.scope-closure-certificate.v2',
    'closureCheckId', v_check.id,
    'requestedScopeHash', v_check.requested_scope_hash,
    'effectiveScopeHash', v_effective_scope_hash,
    'effectiveScope', effective_scope,
    'policyFingerprint', v_check.policy_fingerprint,
    'dataSnapshotToken', v_check.data_snapshot_token,
    'validatorScannerFingerprint', v_check.expected_validator_scanner_fingerprint,
    'sourceFingerprint', evidence->>'sourceFingerprint',
    'resolutionMapHash', evidence->>'resolutionMapHash',
    'closureBundleArtifactId', v_bundle.id,
    'closureBundleHash', v_bundle.checksum_sha256,
    'snapshotId', v_snapshot.id,
    'snapshotHash', v_snapshot_artifact.artifact_sha256,
    'snapshotArtifactId', v_snapshot_artifact.id,
    'snapshotIndexSha256', v_snapshot_artifact.snapshot_index_sha256,
    'snapshotBuildContractHash', v_snapshot_artifact.snapshot_build_contract_hash,
    'reportArtifactManifestHash', v_report_manifest_hash,
    'evidenceHash', v_evidence_hash
  );
  v_certificate_hash := private.lcia_scope_closure_sha256(v_certificate_bindings);

  delete from private.lcia_scope_closure_issues where closure_check_id = v_check.id;
  for v_issue in select value from jsonb_array_elements(issues) loop
    insert into private.lcia_scope_closure_issues(
      closure_check_id, issue_key, severity, blocking, issue_code,
      source_dataset_type, source_dataset_id, source_dataset_version,
      json_path, reference_role, requested_target_type, requested_target_id,
      requested_target_version, message, suggested_action,
      occurrence_count, affected_root_count, details
    ) values (
      v_check.id,
      coalesce(nullif(trim(v_issue->>'issueKey'), ''), private.lcia_scope_closure_sha256(v_issue)),
      coalesce(v_issue->>'severity', 'blocker'),
      coalesce((v_issue->>'blocking')::boolean, false),
      coalesce(nullif(trim(v_issue->>'issueCode'), ''), 'closure_issue'),
      nullif(v_issue->>'sourceDatasetType', ''),
      nullif(v_issue->>'sourceDatasetId', '')::uuid,
      nullif(v_issue->>'sourceDatasetVersion', ''),
      nullif(v_issue->>'jsonPath', ''),
      nullif(v_issue->>'referenceRole', ''),
      nullif(v_issue->>'requestedTargetType', ''),
      nullif(v_issue->>'requestedTargetId', '')::uuid,
      nullif(v_issue->>'requestedTargetVersion', ''),
      coalesce(nullif(v_issue->>'message', ''), 'Closure validation issue'),
      nullif(v_issue->>'suggestedAction', ''),
      greatest(1, coalesce((v_issue->>'occurrenceCount')::integer, 1)),
      greatest(0, coalesce((v_issue->>'affectedRootCount')::integer, 0)),
      coalesce(v_issue->'details', '{}'::jsonb)
    ) returning * into v_closure_issue;
    for v_occurrence in
      select value from jsonb_array_elements(coalesce(v_issue->'occurrences', '[]'::jsonb))
    loop
      insert into private.lcia_scope_closure_issue_occurrences(
        closure_issue_id, occurrence_key, source_dataset_type,
        source_dataset_id, source_dataset_version, json_path, reference_role, details
      ) values (
        v_closure_issue.id,
        coalesce(nullif(v_occurrence->>'occurrenceKey', ''), private.lcia_scope_closure_sha256(v_occurrence)),
        nullif(v_occurrence->>'sourceDatasetType', ''),
        nullif(v_occurrence->>'sourceDatasetId', '')::uuid,
        nullif(v_occurrence->>'sourceDatasetVersion', ''),
        nullif(v_occurrence->>'jsonPath', ''),
        nullif(v_occurrence->>'referenceRole', ''),
        coalesce(v_occurrence->'details', '{}'::jsonb)
      );
    end loop;
    for v_root in
      select value from jsonb_array_elements(coalesce(v_issue->'affectedRoots', '[]'::jsonb))
    loop
      insert into private.lcia_scope_closure_issue_roots(
        closure_issue_id, root_dataset_type, root_dataset_id,
        root_dataset_version, impact_role, witness_path
      ) values (
        v_closure_issue.id,
        coalesce(nullif(v_root->>'datasetType', ''), 'process'),
        (v_root->>'id')::uuid,
        coalesce(nullif(v_root->>'version', ''), '00.00.000'),
        coalesce(nullif(v_root->>'impactRole', ''), 'root'),
        coalesce(v_root->'witnessPath', '[]'::jsonb)
      );
    end loop;
  end loop;

  update private.lcia_scope_closure_checks set
    status = 'passed',
    scan_completeness = 'complete',
    effective_scope_manifest = effective_scope,
    effective_scope_hash = v_effective_scope_hash,
    certificate_schema_version = 'lcia.scope-closure-certificate.v2',
    certificate_status = 'valid',
    certificate_hash = v_certificate_hash,
    source_fingerprint = nullif(evidence->>'sourceFingerprint', ''),
    resolution_map_hash = nullif(evidence->>'resolutionMapHash', ''),
    closure_bundle_hash = v_bundle.checksum_sha256,
    closure_bundle_artifact_id = v_bundle.id,
    snapshot_id = v_snapshot.id,
    snapshot_hash = v_snapshot_artifact.artifact_sha256,
    snapshot_artifact_id = v_snapshot_artifact.id,
    snapshot_index_sha256 = v_snapshot_artifact.snapshot_index_sha256,
    snapshot_build_contract_hash = v_snapshot_artifact.snapshot_build_contract_hash,
    report_artifact_manifest_hash = v_report_manifest_hash,
    evidence_hash = v_evidence_hash,
    result_summary = svc_lcia_scope_closure_check_record_result_v3.result_summary,
    blocker_codes = coalesce(svc_lcia_scope_closure_check_record_result_v3.blocker_codes, '{}'::text[]),
    report_artifact_id = v_report.id,
    updated_at = now(),
    finished_at = now()
  where id = v_check.id
  returning * into v_check;

  v_scan_key := private.lcia_scope_closure_sha256(jsonb_build_object(
    'effectiveScopeHash', v_check.effective_scope_hash,
    'policyFingerprint', v_check.policy_fingerprint,
    'validatorScannerFingerprint', v_check.expected_validator_scanner_fingerprint,
    'dataSnapshotToken', v_check.data_snapshot_token
  ));
  select id into v_existing_execution
  from private.lcia_scope_closure_scan_executions
  where scan_key = v_scan_key and id <> v_execution.id
  limit 1;
  if v_existing_execution is not null then v_scan_key := null; end if;
  update private.lcia_scope_closure_scan_executions set
    scan_key = v_scan_key,
    status = 'completed',
    lease_token = null,
    leased_by_job_id = null,
    lease_expires_at = null,
    completed_check_id = v_check.id,
    source_fingerprint = v_check.source_fingerprint,
    evidence_hash = v_check.evidence_hash,
    updated_at = now(),
    completed_at = now()
  where id = v_execution.id;

  select private.worker_record_job_result(
    v_job.id,
    lease_token,
    'completed',
    jsonb_build_object(
      'closureCheckId', v_check.id,
      'status', v_check.status,
      'scanCompleteness', v_check.scan_completeness,
      'certificateStatus', v_check.certificate_status,
      'certificateHash', v_check.certificate_hash,
      'effectiveScopeHash', v_check.effective_scope_hash,
      'snapshotId', v_check.snapshot_id,
      'snapshotHash', v_check.snapshot_hash,
      'snapshotArtifactId', v_check.snapshot_artifact_id,
      'snapshotIndexSha256', v_check.snapshot_index_sha256,
      'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
      'evidenceHash', v_check.evidence_hash
    ),
    'lcia.scope_closure_check.result.v2',
    jsonb_build_object(
      'reportArtifactId', v_report.id,
      'closureBundleArtifactId', v_bundle.id,
      'snapshotArtifactId', v_snapshot_artifact.id
    ),
    jsonb_build_object('progressCounters', coalesce(result_summary->'progressCounters', '{}'::jsonb)),
    null, null, null, null, null, false
  ) into v_worker_result;
  if coalesce((v_worker_result->>'ok')::boolean, false) is not true then
    raise exception using errcode = 'P0001', message = 'worker_job_result_rejected';
  end if;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_check.id,
    'status', v_check.status,
    'scanCompleteness', v_check.scan_completeness,
    'certificateStatus', v_check.certificate_status,
    'certificateHash', v_check.certificate_hash,
    'effectiveScopeHash', v_check.effective_scope_hash,
    'snapshotId', v_check.snapshot_id,
    'snapshotHash', v_check.snapshot_hash,
    'snapshotArtifactId', v_check.snapshot_artifact_id,
    'snapshotIndexSha256', v_check.snapshot_index_sha256,
    'snapshotBuildContractHash', v_check.snapshot_build_contract_hash,
    'evidenceHash', v_check.evidence_hash
  ));
exception
  when invalid_text_representation then
    return api.lcia_scope_closure_error('invalid_closure_result', 400, 'Closure result contains invalid identity values');
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_check_record_result_v3(check_id uuid, worker_job_id uuid, lease_token uuid, status text, scan_completeness text, effective_scope jsonb, evidence jsonb, result_summary jsonb, issues jsonb, blocker_codes text[], report_artifact_id uuid, closure_bundle_artifact_id uuid, snapshot_artifact_id uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_claim_scan_execution(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_claim_scan_execution(p_scan_execution_id uuid, p_worker_job_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare v_execution private.lcia_scope_closure_scan_executions%rowtype; v_job private.worker_jobs%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then return api.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  select * into v_job from private.worker_jobs where id=p_worker_job_id;
  if v_job.id is null or v_job.status<>'running' or v_job.lease_token is distinct from p_lease_token or v_job.lease_expires_at<now() then return api.lcia_scope_closure_error('worker_job_lease_invalid',409,'Worker job lease is no longer valid'); end if;
  select * into v_execution from private.lcia_scope_closure_scan_executions where id=p_scan_execution_id for update;
  if v_execution.id is null or not exists (select 1 from private.lcia_scope_closure_checks c where c.scan_execution_id=v_execution.id and c.worker_job_id=v_job.id and c.request_fingerprint=v_execution.request_fingerprint) then return api.lcia_scope_closure_error('scan_execution_not_found',404,'Scan execution not found'); end if;
  if v_execution.status='completed' then return jsonb_build_object('ok',true,'data',jsonb_build_object('acquired',false,'completed',true,'completedCheckId',v_execution.completed_check_id)); end if;
  if v_execution.status='running' and v_execution.lease_expires_at>=now() and v_execution.leased_by_job_id<>v_job.id then return jsonb_build_object('ok',true,'data',jsonb_build_object('acquired',false,'completed',false)); end if;
  update private.lcia_scope_closure_scan_executions set status='running',lease_token=p_lease_token,leased_by_job_id=v_job.id,lease_expires_at=v_job.lease_expires_at,updated_at=now() where id=v_execution.id;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('acquired',true,'completed',false));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_claim_scan_execution(p_scan_execution_id uuid, p_worker_job_id uuid, p_lease_token uuid) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_fail_before_scan(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_fail_before_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare c private.lcia_scope_closure_checks%rowtype; j private.worker_jobs%rowtype; e private.lcia_scope_closure_scan_executions%rowtype; wr jsonb;
begin
  if not coalesce(util.is_service_request(),false) then return api.lcia_scope_closure_error('service_role_required',403,'Service role is required'); end if;
  select * into c from private.lcia_scope_closure_checks where id=p_closure_check_id for update; select * into j from private.worker_jobs where id=p_worker_job_id for update;
  if c.id is null or c.worker_job_id<>j.id or c.status not in ('queued','running') or j.status<>'running' or j.lease_token is distinct from p_lease_token or j.lease_expires_at<now() then return api.lcia_scope_closure_error('worker_job_lease_invalid',409,'Worker job lease is no longer valid'); end if;
  select * into e from private.lcia_scope_closure_scan_executions where id=c.scan_execution_id for update;
  update private.lcia_scope_closure_checks set status='failed',scan_completeness='unknown',certificate_status='unavailable',result_summary=jsonb_build_object('errorCode',coalesce(nullif(trim(p_error_code),''),'closure_check_failed')),updated_at=now(),finished_at=now() where id=c.id;
  if e.id is not null and e.status='running' and e.leased_by_job_id=j.id and e.lease_token is not distinct from p_lease_token then update private.lcia_scope_closure_scan_executions set status='failed',lease_token=null,leased_by_job_id=null,lease_expires_at=null,updated_at=now(),completed_at=now() where id=e.id; end if;
  select private.worker_record_job_result(j.id,p_lease_token,'failed',jsonb_build_object('closureCheckId',c.id,'status','failed'),'lcia.scope_closure_check.result.v1',null,null,coalesce(nullif(trim(p_error_code),''),'closure_check_failed'),'Scope closure check failed',null,null,null,true) into wr;
  if coalesce((wr->>'ok')::boolean,false) is not true then raise exception using errcode='P0001',message='worker_job_result_rejected'; end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('closureCheckId',c.id,'workerJobId',j.id,'status','failed'));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_fail_before_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_error_code text) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_finalize_reused_scan(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_finalize_reused_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid, p_report_artifact_id uuid, p_result_summary jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_target private.lcia_scope_closure_checks%rowtype;
  v_source private.lcia_scope_closure_checks%rowtype;
  v_execution private.lcia_scope_closure_scan_executions%rowtype;
  v_job private.worker_jobs%rowtype;
  v_report private.worker_job_artifacts%rowtype;
  v_snapshot private.lca_network_snapshots%rowtype;
  v_artifact private.lca_snapshot_artifacts%rowtype;
  v_bundle private.worker_job_artifacts%rowtype;
  v_old_issue private.lcia_scope_closure_issues%rowtype;
  v_new_issue private.lcia_scope_closure_issues%rowtype;
  v_report_hash text;
  v_certificate_hash text;
  v_worker_status text;
  v_worker_record jsonb;
  v_summary jsonb;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  if jsonb_typeof(coalesce(p_result_summary, 'null'::jsonb)) <> 'object'
     or p_result_summary->>'schemaVersion' is distinct from 'lcia.scope-closure-summary.v1' then
    return api.lcia_scope_closure_error('invalid_closure_result', 400, 'Reused closure result summary must be an object');
  end if;
  select * into v_target from private.lcia_scope_closure_checks where id = p_closure_check_id for update;
  select * into v_source
  from private.lcia_scope_closure_checks
  where id = p_completed_check_id
  for share;
  select * into v_job from private.worker_jobs where id = p_worker_job_id for update;
  select * into v_execution from private.lcia_scope_closure_scan_executions where id = v_target.scan_execution_id for update;
  select * into v_report from private.worker_job_artifacts
  where id = p_report_artifact_id
    and job_id = p_worker_job_id
    and artifact_type = 'closure_report_xlsx';
  if v_target.id is null or v_source.id is null
     or v_target.worker_job_id <> v_job.id
     or v_target.status not in ('queued', 'running')
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at < now()
     or v_execution.id is null
     or v_execution.status <> 'completed'
     or v_execution.completed_check_id <> v_source.id
     or v_report.id is null
     or v_source.status not in ('passed', 'blocked')
     or v_source.scan_completeness <> 'complete'
     or v_source.requested_scope_hash <> v_target.requested_scope_hash
     or v_source.policy_fingerprint <> v_target.policy_fingerprint
     or v_source.data_snapshot_token <> v_target.data_snapshot_token then
    return api.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Reusable scan evidence or new report artifact is invalid');
  end if;
  if coalesce(v_report.metadata->>'closureCheckId', v_target.id::text) <> v_target.id::text then
    return api.lcia_scope_closure_error('closure_report_unavailable', 409, 'New report does not belong to this closure run');
  end if;
  if v_source.status = 'passed' then
    select * into v_snapshot from private.lca_network_snapshots where id = v_source.snapshot_id;
    select * into v_artifact from private.lca_snapshot_artifacts where id = v_source.snapshot_artifact_id;
    select * into v_bundle from private.worker_job_artifacts where id = v_source.closure_bundle_artifact_id;
    if v_source.certificate_status <> 'valid'
       or v_source.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
       or (
         v_source.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
         and not private.lcia_scope_closure_current_release_matches(v_source.data_snapshot_token)
       )
       or v_execution.numerical_snapshot_id is distinct from v_source.snapshot_id
       or v_snapshot.id is null or v_snapshot.status <> 'ready'
       or v_artifact.id is null or v_artifact.snapshot_id <> v_snapshot.id
       or v_artifact.status <> 'ready'
       or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
       or v_artifact.artifact_sha256 <> v_source.snapshot_hash
       or v_artifact.snapshot_index_sha256 <> v_source.snapshot_index_sha256
       or v_artifact.snapshot_build_contract_hash <> v_source.snapshot_build_contract_hash
       or v_artifact.effective_scope_hash <> v_source.effective_scope_hash
       or v_artifact.data_snapshot_token <> v_source.data_snapshot_token
       or v_artifact.closure_bundle_hash <> v_source.closure_bundle_hash
       or v_bundle.id is null
       or v_bundle.job_id <> v_source.worker_job_id
       or v_bundle.artifact_type <> 'closure_bundle'
       or v_bundle.checksum_sha256 <> v_source.closure_bundle_hash
       or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_source.id::text then
      return api.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Source numerical snapshot certificate is not reusable');
    end if;
  end if;

  v_report_hash := private.lcia_scope_closure_sha256(jsonb_build_object(
    'artifactId', v_report.id,
    'bucket', v_report.storage_bucket,
    'objectPath', v_report.storage_path,
    'mediaType', v_report.content_type,
    'byteSize', v_report.byte_size,
    'checksumSha256', v_report.checksum_sha256
  ));
  if v_source.status = 'passed' then
    v_certificate_hash := private.lcia_scope_closure_sha256(jsonb_build_object(
      'certificateSchemaVersion', 'lcia.scope-closure-certificate.v2',
      'closureCheckId', v_target.id,
      'requestedScopeHash', v_target.requested_scope_hash,
      'effectiveScopeHash', v_source.effective_scope_hash,
      'effectiveScope', v_source.effective_scope_manifest,
      'policyFingerprint', v_target.policy_fingerprint,
      'dataSnapshotToken', v_target.data_snapshot_token,
      'validatorScannerFingerprint', v_target.expected_validator_scanner_fingerprint,
      'sourceFingerprint', v_source.source_fingerprint,
      'resolutionMapHash', v_source.resolution_map_hash,
      'closureBundleArtifactId', v_source.closure_bundle_artifact_id,
      'closureBundleHash', v_source.closure_bundle_hash,
      'snapshotId', v_source.snapshot_id,
      'snapshotHash', v_source.snapshot_hash,
      'snapshotArtifactId', v_source.snapshot_artifact_id,
      'snapshotIndexSha256', v_source.snapshot_index_sha256,
      'snapshotBuildContractHash', v_source.snapshot_build_contract_hash,
      'reportArtifactManifestHash', v_report_hash,
      'evidenceHash', v_source.evidence_hash
    ));
  end if;

  for v_old_issue in
    select * from private.lcia_scope_closure_issues
    where closure_check_id = v_source.id order by id
  loop
    insert into private.lcia_scope_closure_issues(
      closure_check_id, issue_key, severity, blocking, issue_code,
      source_dataset_type, source_dataset_id, source_dataset_version,
      json_path, reference_role, requested_target_type, requested_target_id,
      requested_target_version, message, suggested_action,
      occurrence_count, affected_root_count, details
    ) values (
      v_target.id, v_old_issue.issue_key, v_old_issue.severity,
      v_old_issue.blocking, v_old_issue.issue_code,
      v_old_issue.source_dataset_type, v_old_issue.source_dataset_id,
      v_old_issue.source_dataset_version, v_old_issue.json_path,
      v_old_issue.reference_role, v_old_issue.requested_target_type,
      v_old_issue.requested_target_id, v_old_issue.requested_target_version,
      v_old_issue.message, v_old_issue.suggested_action,
      v_old_issue.occurrence_count, v_old_issue.affected_root_count,
      v_old_issue.details
    ) returning * into v_new_issue;
    insert into private.lcia_scope_closure_issue_occurrences(
      closure_issue_id, occurrence_key, source_dataset_type,
      source_dataset_id, source_dataset_version, json_path, reference_role, details
    ) select
      v_new_issue.id, occurrence_key, source_dataset_type,
      source_dataset_id, source_dataset_version, json_path, reference_role, details
    from private.lcia_scope_closure_issue_occurrences
    where closure_issue_id = v_old_issue.id;
    insert into private.lcia_scope_closure_issue_roots(
      closure_issue_id, root_dataset_type, root_dataset_id,
      root_dataset_version, impact_role, witness_path
    ) select
      v_new_issue.id, root_dataset_type, root_dataset_id,
      root_dataset_version, impact_role, witness_path
    from private.lcia_scope_closure_issue_roots
    where closure_issue_id = v_old_issue.id;
  end loop;

  v_summary := jsonb_strip_nulls(p_result_summary || jsonb_build_object(
    'reusedFromCheckId', v_source.id,
    'reportArtifactId', v_report.id,
    'reportArtifactManifestHash', v_report_hash,
    'evidenceHash', v_source.evidence_hash
  ));
  update private.lcia_scope_closure_checks set
    status = v_source.status,
    scan_completeness = v_source.scan_completeness,
    effective_scope_manifest = v_source.effective_scope_manifest,
    effective_scope_hash = v_source.effective_scope_hash,
    certificate_schema_version = case when v_source.status = 'passed' then 'lcia.scope-closure-certificate.v2' else null end,
    certificate_status = case when v_source.status = 'passed' then 'valid' else 'unavailable' end,
    certificate_hash = v_certificate_hash,
    source_fingerprint = v_source.source_fingerprint,
    resolution_map_hash = v_source.resolution_map_hash,
    closure_bundle_hash = case when v_source.status = 'passed' then v_source.closure_bundle_hash else null end,
    closure_bundle_artifact_id = case when v_source.status = 'passed' then v_source.closure_bundle_artifact_id else null end,
    snapshot_id = case when v_source.status = 'passed' then v_source.snapshot_id else null end,
    snapshot_hash = case when v_source.status = 'passed' then v_source.snapshot_hash else null end,
    snapshot_artifact_id = case when v_source.status = 'passed' then v_source.snapshot_artifact_id else null end,
    snapshot_index_sha256 = case when v_source.status = 'passed' then v_source.snapshot_index_sha256 else null end,
    snapshot_build_contract_hash = case when v_source.status = 'passed' then v_source.snapshot_build_contract_hash else null end,
    report_artifact_manifest_hash = v_report_hash,
    evidence_hash = case when v_source.status = 'passed' then v_source.evidence_hash else null end,
    result_summary = v_summary,
    blocker_codes = v_source.blocker_codes,
    report_artifact_id = v_report.id,
    reused_from_check_id = v_source.id,
    updated_at = now(),
    finished_at = now()
  where id = v_target.id
  returning * into v_target;

  v_worker_status := case when v_target.status = 'passed' then 'completed' else 'blocked' end;
  select private.worker_record_job_result(
    v_job.id, p_lease_token, v_worker_status,
    jsonb_build_object(
      'closureCheckId', v_target.id,
      'status', v_target.status,
      'scanCompleteness', v_target.scan_completeness,
      'certificateStatus', v_target.certificate_status,
      'certificateHash', v_target.certificate_hash,
      'snapshotId', v_target.snapshot_id,
      'snapshotHash', v_target.snapshot_hash,
      'snapshotArtifactId', v_target.snapshot_artifact_id,
      'snapshotIndexSha256', v_target.snapshot_index_sha256,
      'snapshotBuildContractHash', v_target.snapshot_build_contract_hash,
      'evidenceHash', v_target.evidence_hash,
      'reusedFromCheckId', v_source.id
    ),
    'lcia.scope_closure_check.result.v2',
    jsonb_build_object('reportArtifactId', v_report.id, 'reportArtifactManifestHash', v_report_hash),
    jsonb_build_object('progressCounters', coalesce(v_target.result_summary->'progressCounters', '{}'::jsonb)),
    null, null, null,
    case when v_worker_status = 'blocked' then v_target.blocker_codes else null end,
    case when v_worker_status = 'blocked' then 'operator' else null end,
    false
  ) into v_worker_record;
  if coalesce((v_worker_record->>'ok')::boolean, false) is not true then
    raise exception using errcode = 'P0001', message = 'worker_job_result_rejected';
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'closureCheckId', v_target.id,
    'workerJobId', v_job.id,
    'status', v_target.status,
    'scanCompleteness', v_target.scan_completeness,
    'certificateStatus', v_target.certificate_status,
    'certificateHash', v_target.certificate_hash,
    'effectiveScopeHash', v_target.effective_scope_hash,
    'snapshotId', v_target.snapshot_id,
    'snapshotHash', v_target.snapshot_hash,
    'snapshotArtifactId', v_target.snapshot_artifact_id,
    'snapshotIndexSha256', v_target.snapshot_index_sha256,
    'snapshotBuildContractHash', v_target.snapshot_build_contract_hash,
    'evidenceHash', v_target.evidence_hash,
    'reportArtifactId', v_report.id,
    'reusedFromCheckId', v_source.id
  ));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_finalize_reused_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid, p_report_artifact_id uuid, p_result_summary jsonb) OWNER TO postgres;

--
-- Name: svc_lcia_scope_closure_reuse_completed_scan(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_lcia_scope_closure_reuse_completed_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'api', 'public', 'util', 'extensions', 'pg_temp'
    AS $$
declare
  v_target private.lcia_scope_closure_checks%rowtype;
  v_source private.lcia_scope_closure_checks%rowtype;
  v_execution private.lcia_scope_closure_scan_executions%rowtype;
  v_job private.worker_jobs%rowtype;
  v_snapshot private.lca_network_snapshots%rowtype;
  v_artifact private.lca_snapshot_artifacts%rowtype;
  v_bundle private.worker_job_artifacts%rowtype;
begin
  if not coalesce(util.is_service_request(), false) then
    return api.lcia_scope_closure_error('service_role_required', 403, 'Service role is required');
  end if;
  select * into v_target from private.lcia_scope_closure_checks where id = p_closure_check_id for update;
  select * into v_source
  from private.lcia_scope_closure_checks
  where id = p_completed_check_id
  for share;
  select * into v_job from private.worker_jobs where id = p_worker_job_id for update;
  if v_target.id is null or v_source.id is null
     or v_target.worker_job_id <> p_worker_job_id
     or v_target.status not in ('queued', 'running') then
    return api.lcia_scope_closure_error('closure_check_not_found', 404, 'Closure check not found');
  end if;
  if v_job.status <> 'running'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at < now() then
    return api.lcia_scope_closure_error('worker_job_lease_invalid', 409, 'Worker job lease is no longer valid');
  end if;
  select * into v_execution
  from private.lcia_scope_closure_scan_executions
  where id = v_target.scan_execution_id
  for update;
  if v_execution.id is null
     or v_execution.status <> 'completed'
     or v_execution.completed_check_id <> v_source.id
     or (
       v_source.status = 'passed'
       and v_execution.numerical_snapshot_id is distinct from v_source.snapshot_id
     )
     or v_source.status not in ('passed', 'blocked')
     or v_source.scan_completeness <> 'complete'
     or v_source.requested_scope_hash <> v_target.requested_scope_hash
     or v_source.policy_fingerprint <> v_target.policy_fingerprint
     or v_source.data_snapshot_token <> v_target.data_snapshot_token then
    return api.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Completed scan evidence does not match this closure run');
  end if;
  if v_source.status = 'passed' then
    select * into v_snapshot from private.lca_network_snapshots where id = v_source.snapshot_id;
    select * into v_artifact from private.lca_snapshot_artifacts where id = v_source.snapshot_artifact_id;
    select * into v_bundle from private.worker_job_artifacts where id = v_source.closure_bundle_artifact_id;
    if v_source.certificate_status <> 'valid'
       or v_source.certificate_schema_version <> 'lcia.scope-closure-certificate.v2'
       or (
         v_source.requested_scope_manifest->>'certificateFreshnessPolicy' = 'current-membership-required-v1'
         and not private.lcia_scope_closure_current_release_matches(v_source.data_snapshot_token)
       )
       or v_snapshot.id is null
       or v_snapshot.status <> 'ready'
       or v_artifact.id is null
       or v_artifact.snapshot_id <> v_snapshot.id
       or v_artifact.status <> 'ready'
       or v_artifact.artifact_format <> 'snapshot-hdf5:v1'
       or v_artifact.artifact_sha256 <> v_source.snapshot_hash
       or v_artifact.snapshot_index_sha256 <> v_source.snapshot_index_sha256
       or v_artifact.snapshot_build_contract_hash <> v_source.snapshot_build_contract_hash
       or v_artifact.effective_scope_hash <> v_source.effective_scope_hash
       or v_artifact.data_snapshot_token <> v_source.data_snapshot_token
       or v_artifact.closure_bundle_hash <> v_source.closure_bundle_hash
       or v_bundle.id is null
       or v_bundle.job_id <> v_source.worker_job_id
       or v_bundle.artifact_type <> 'closure_bundle'
       or v_bundle.checksum_sha256 <> v_source.closure_bundle_hash
       or coalesce(v_bundle.metadata->>'closureCheckId', '') <> v_source.id::text then
      return api.lcia_scope_closure_error('scan_execution_not_reusable', 409, 'Source numerical snapshot certificate is not reusable');
    end if;
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'reuseAvailable', true,
    'closureCheckId', v_target.id,
    'workerJobId', v_job.id,
    'completedCheckId', v_source.id,
    'status', v_source.status,
    'scanCompleteness', v_source.scan_completeness,
    'evidence', jsonb_strip_nulls(jsonb_build_object(
      'schemaVersion', 'lcia.scope-closure-evidence.v2',
      'sourceFingerprint', v_source.source_fingerprint,
      'resolutionMapHash', v_source.resolution_map_hash,
      'closureBundleHash', v_source.closure_bundle_hash,
      'closureBundleArtifactId', v_source.closure_bundle_artifact_id,
      'snapshotId', v_source.snapshot_id,
      'snapshotHash', v_source.snapshot_hash,
      'snapshotArtifactId', v_source.snapshot_artifact_id,
      'snapshotIndexSha256', v_source.snapshot_index_sha256,
      'snapshotBuildContractHash', v_source.snapshot_build_contract_hash,
      'artifactFormat', v_artifact.artifact_format,
      'evidenceHash', v_source.evidence_hash
    )),
    'blockerCodes', to_jsonb(v_source.blocker_codes)
  ));
end;
$$;


ALTER FUNCTION private.svc_lcia_scope_closure_reuse_completed_scan(p_closure_check_id uuid, p_worker_job_id uuid, p_lease_token uuid, p_completed_check_id uuid) OWNER TO postgres;

--
-- Name: svc_portal_lcia_projection_package_mark_ready_v1(uuid, uuid, uuid, text, uuid, uuid, uuid, jsonb, jsonb, jsonb, jsonb, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_portal_lcia_projection_package_mark_ready_v1(p_projection_id uuid, p_build_worker_job_id uuid, p_lease_token uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid DEFAULT NULL::uuid, p_result_artifact_ref jsonb DEFAULT '{}'::jsonb, p_query_artifact_ref jsonb DEFAULT '{}'::jsonb, p_artifact_manifest jsonb DEFAULT '{}'::jsonb, p_available_impact_categories jsonb DEFAULT '[]'::jsonb, p_default_impact_category text DEFAULT NULL::text, p_package_result_hash text DEFAULT NULL::text, p_audit jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_projection private.portal_lcia_projection_headers%rowtype;
  v_job private.worker_jobs%rowtype;
  v_result jsonb;
  v_package private.lcia_result_packages%rowtype;
  v_package_id uuid;
  v_projection_impacts jsonb;
  v_reused boolean := false;
  v_expected_build_id uuid;
  v_expected_closure_check_id uuid;
  v_expected_eligibility_resolved_at timestamptz;
  v_expected_eligible_input_count integer;
  v_expected_included_input_count integer;
  v_expected_default_impact text;
  v_restart_default_impact text;
  v_authoritative_result private.lca_results%rowtype;
  v_authoritative_latest private.lca_latest_all_unit_results%rowtype;
  v_expected_result_artifact_ref jsonb;
  v_expected_query_artifact_ref jsonb;
  v_preexisting_package boolean := false;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false, 'code', 'service_role_required', 'status', 403
    );
  end if;
  if private.portal_lcia_safe_audit_v1(p_audit) is not true
     or private.portal_lcia_public_text_valid_v1(p_package_version, 256)
          is not true
     or jsonb_typeof(p_result_artifact_ref) <> 'object'
     or jsonb_typeof(p_query_artifact_ref) <> 'object'
     or jsonb_typeof(p_artifact_manifest) <> 'object'
     or p_result_artifact_ref ->> 'artifactSha256'
          !~ '^[0-9a-f]{64}$'
     or p_query_artifact_ref ->> 'artifactSha256'
          !~ '^[0-9a-f]{64}$'
     or p_artifact_manifest ->> 'bundleContentHash'
          !~ '^[0-9a-f]{64}$'
     or p_artifact_manifest ->> 'bundleManifestSha256'
          !~ '^[0-9a-f]{64}$'
     or p_artifact_manifest ->> 'lciaChunkSetSha256'
          !~ '^[0-9a-f]{64}$'
     or p_artifact_manifest ->> 'portalProjectionId'
          !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or p_artifact_manifest ->> 'portalProjectionContentHash'
          !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(p_available_impact_categories) <> 'array'
     or (
       p_default_impact_category is not null
       and private.portal_lcia_public_text_valid_v1(
         p_default_impact_category, 512
       ) is not true
     )
     or coalesce(p_package_result_hash, '') !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_projection_request', 'status', 400
    );
  end if;

  select projection.* into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.id = p_projection_id
    and projection.build_worker_job_id = p_build_worker_job_id
  for share;
  if v_projection.id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_found', 'status', 404
    );
  end if;
  if v_projection.status <> 'prepared' then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_prepared', 'status', 409
    );
  end if;
  if v_projection.stage_lease_token is distinct from p_lease_token
     or private.portal_lcia_projection_v3_job_binding_valid_v1(
       p_build_worker_job_id, p_lease_token
     ) is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_lease_invalid', 'status', 409
    );
  end if;
  if v_projection.result_artifact_sha256
       <> p_result_artifact_ref ->> 'artifactSha256'
     or v_projection.query_artifact_sha256
       <> p_query_artifact_ref ->> 'artifactSha256'
     or v_projection.bundle_content_hash
       <> p_artifact_manifest ->> 'bundleContentHash'
     or v_projection.bundle_manifest_sha256
       <> p_artifact_manifest ->> 'bundleManifestSha256'
     or v_projection.lcia_chunk_set_sha256
       <> p_artifact_manifest ->> 'lciaChunkSetSha256'
     or v_projection.id::text
       <> p_artifact_manifest ->> 'portalProjectionId'
     or v_projection.content_hash
       <> p_artifact_manifest ->> 'portalProjectionContentHash' then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;
  select coalesce(
    jsonb_agg(to_jsonb(impact.method_id::text) order by impact.impact_index),
    '[]'::jsonb
  ) into v_projection_impacts
  from private.portal_lcia_projection_impact_axis as impact
  where impact.projection_id = v_projection.id;
  if jsonb_typeof(p_available_impact_categories) <> 'array'
     or p_available_impact_categories is distinct from v_projection_impacts then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  select job.* into v_job
  from private.worker_jobs as job
  where job.id = p_build_worker_job_id
  for update;
  select exists (
    select 1
    from private.lcia_result_packages as package
    where package.build_worker_job_id = p_build_worker_job_id
      and package.package_version = p_package_version
  ) into v_preexisting_package;
  if v_job.payload_json ->> 'snapshot_id' is distinct from p_snapshot_id::text then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  begin
    v_expected_build_id := nullif(
      v_job.payload_json ->> 'build_id', ''
    )::uuid;
    v_expected_closure_check_id := nullif(
      v_job.payload_json ->> 'closure_check_id', ''
    )::uuid;
    v_expected_eligibility_resolved_at := nullif(
      v_job.payload_json ->> 'eligibility_resolved_at', ''
    )::timestamptz;
    v_expected_eligible_input_count := coalesce(
      (v_job.payload_json ->> 'eligible_input_count')::integer, 0
    );
    v_expected_included_input_count := coalesce(
      (v_job.payload_json ->> 'included_input_count')::integer, 0
    );
  exception
    when invalid_text_representation
      or invalid_datetime_format
      or datetime_field_overflow
      or numeric_value_out_of_range then
      if v_preexisting_package then
        return api.lcia_result_error(
          'package_conflict', 409,
          'LCIA result package already exists for this build or package version'
        );
      end if;
      return jsonb_build_object(
        'ok', false, 'code', 'projection_package_binding_invalid',
        'status', 409
      );
  end;
  v_expected_default_impact := coalesce(
    nullif(btrim(coalesce(p_default_impact_category, '')), ''),
    nullif(btrim(coalesce(
      v_job.payload_json ->> 'default_impact_category', ''
    )), '')
  );
  v_restart_default_impact := coalesce(
    nullif(btrim(coalesce(
      v_job.payload_json ->> 'default_impact_category', ''
    )), ''),
    v_projection_impacts ->> 0
  );

  select result.* into v_authoritative_result
  from private.lca_results as result
  where result.id = p_result_id;
  v_expected_result_artifact_ref := jsonb_build_object(
    'artifactUrl', v_authoritative_result.artifact_url,
    'artifactSha256', v_authoritative_result.artifact_sha256,
    'artifactByteSize', v_authoritative_result.artifact_byte_size,
    'artifactFormat', v_authoritative_result.artifact_format
  );
  if v_authoritative_result.id is null
     or v_expected_build_id is distinct from v_job.subject_id
     or v_job.subject_type <> 'lcia_result_build'
     or v_authoritative_result.job_id is distinct from v_expected_build_id
     or v_authoritative_result.worker_job_id is distinct from v_job.id
     or v_authoritative_result.snapshot_id is distinct from p_snapshot_id
     or private.portal_lcia_json_object_has_keys_v1(
       p_result_artifact_ref,
       array[
         'artifactUrl', 'artifactSha256', 'artifactByteSize', 'artifactFormat'
       ]
     ) is not true
     or p_result_artifact_ref is distinct from
          v_expected_result_artifact_ref
     or p_package_result_hash is distinct from
          v_authoritative_result.artifact_sha256
     or p_package_result_hash is distinct from
          v_projection.result_artifact_sha256
     or v_expected_default_impact is distinct from
          v_restart_default_impact then
    if v_preexisting_package then
      return api.lcia_result_error(
        'package_conflict', 409,
        'LCIA result package already exists for this build or package version'
      );
    end if;
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  if private.portal_lcia_json_object_has_keys_v1(
       p_query_artifact_ref,
       array[
         'artifactUrl', 'artifactSha256', 'artifactByteSize', 'artifactFormat'
       ]
     ) is not true then
    if v_preexisting_package then
      return api.lcia_result_error(
        'package_conflict', 409,
        'LCIA result package already exists for this build or package version'
      );
    end if;
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;
  if p_latest_all_unit_result_id is not null then
    select latest.* into v_authoritative_latest
    from private.lca_latest_all_unit_results as latest
    where latest.id = p_latest_all_unit_result_id;
    v_expected_query_artifact_ref := jsonb_build_object(
      'artifactUrl', v_authoritative_latest.query_artifact_url,
      'artifactSha256', v_authoritative_latest.query_artifact_sha256,
      'artifactByteSize', v_authoritative_latest.query_artifact_byte_size,
      'artifactFormat', v_authoritative_latest.query_artifact_format
    );
    if v_authoritative_latest.id is null
       or v_authoritative_latest.job_id is distinct from v_expected_build_id
       or v_authoritative_latest.worker_job_id is distinct from v_job.id
       or v_authoritative_latest.snapshot_id is distinct from p_snapshot_id
       or v_authoritative_latest.result_id is distinct from p_result_id
       or v_authoritative_latest.status <> 'ready'
       or p_query_artifact_ref is distinct from
            v_expected_query_artifact_ref then
      if v_preexisting_package then
        return api.lcia_result_error(
          'package_conflict', 409,
          'LCIA result package already exists for this build or package version'
        );
      end if;
      return jsonb_build_object(
        'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
      );
    end if;
  end if;

  begin
  -- The established insert trigger applies its exact certificate binding only
  -- to request.v2.  A row lock and transaction-local compatibility value let
  -- this V3-only wrapper reuse that unchanged trigger and legacy insert helper;
  -- no observer can see the temporary value and V1/V2 definitions/ACLs remain
  -- byte-stable.
  update private.worker_jobs
  set payload_schema_version = 'lcia_result.package_build.request.v2'
  where id = v_job.id;
  begin
    v_result := private.cmd_lcia_result_package_mark_ready_without_closure_recheck(
      p_build_worker_job_id,
      p_package_version,
      p_snapshot_id,
      p_result_id,
      p_latest_all_unit_result_id,
      p_result_artifact_ref,
      p_query_artifact_ref,
      p_artifact_manifest,
      p_available_impact_categories,
      p_default_impact_category,
      p_package_result_hash,
      p_audit
    );
  exception when others then
    update private.worker_jobs
    set payload_schema_version = 'lcia_result.package_build.request.v3'
    where id = v_job.id;
    raise;
  end;
  update private.worker_jobs
  set payload_schema_version = 'lcia_result.package_build.request.v3'
  where id = v_job.id;

  if coalesce((v_result ->> 'ok')::boolean, false) is true then
    begin
      v_package_id := nullif(v_result -> 'data' ->> 'packageId', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'portal_lcia_package_post_insert_validation_failed'
        using errcode = 'P5271';
    end;
    select package.* into v_package
    from private.lcia_result_packages as package
    where package.id = v_package_id
    for share;
  elsif v_result ->> 'ok' = 'false'
        and v_result ->> 'code' = 'package_conflict'
        and v_result ->> 'status' = '409' then
    -- A unique violation is ambiguous to the Worker: a prior identical call
    -- may have committed before its response was lost, or an unrelated package
    -- may own one of the unique keys.  Only the exact build/job-version pair is
    -- eligible for reconciliation; all other conflicts remain unchanged.
    v_reused := true;
    select package.* into v_package
    from private.lcia_result_packages as package
    where package.build_worker_job_id = v_job.id
      and package.package_version = p_package_version
    for share;
    if v_package.id is null then
      return v_result;
    end if;
  else
    return v_result;
  end if;

  if private.portal_lcia_projection_package_binding_valid_v1(
       v_package.id, v_job.id, v_projection.id
     ) is not true
     or v_expected_default_impact is distinct from v_restart_default_impact
     or v_package.id is null
     or v_package.build_id is distinct from v_expected_build_id
     or v_package.build_id is distinct from v_job.subject_id
     or v_job.subject_type <> 'lcia_result_build'
     or v_package.build_worker_job_id is distinct from v_job.id
     or v_package.package_version is distinct from p_package_version
     or v_package.coverage_mode is distinct from
          (v_job.payload_json ->> 'coverage_mode')
     or v_package.input_status_filter is distinct from coalesce(
          v_job.payload_json -> 'input_status_filter',
          '{"state_code":{"between":[100,199]}}'::jsonb
        )
     or v_package.eligibility_definition is distinct from coalesce(
          v_job.payload_json -> 'eligibility_definition', '{}'::jsonb
        )
     or v_package.eligibility_resolved_at is distinct from
          v_expected_eligibility_resolved_at
     or v_package.eligible_input_count is distinct from
          v_expected_eligible_input_count
     or v_package.included_input_count is distinct from
          v_expected_included_input_count
     or v_package.input_manifest_hash is distinct from nullif(
          v_job.payload_json ->> 'input_manifest_hash', ''
        )
     or v_package.input_manifest is distinct from coalesce(
          v_job.payload_json -> 'input_manifest', '{}'::jsonb
        )
     or v_package.snapshot_id is distinct from p_snapshot_id
     or v_package.result_id is distinct from p_result_id
     or v_package.latest_all_unit_result_id is distinct from
          p_latest_all_unit_result_id
     or v_package.result_artifact_ref is distinct from p_result_artifact_ref
     or v_package.query_artifact_ref is distinct from p_query_artifact_ref
     or v_package.artifact_manifest is distinct from p_artifact_manifest
     or v_package.package_result_hash is distinct from p_package_result_hash
     or v_package.lcia_method_set is distinct from coalesce(
          v_job.payload_json -> 'lcia_method_set', '[]'::jsonb
        )
     or v_package.available_impact_categories is distinct from
          p_available_impact_categories
     or v_package.postprocess_manifest is distinct from coalesce(
          v_job.payload_json -> 'postprocess_manifest',
          '{"postprocess_mode":"skipped"}'::jsonb
        )
     or v_package.default_impact_category is distinct from
          v_expected_default_impact
     or v_package.closure_check_id is distinct from
          v_expected_closure_check_id
     or v_package.closure_certificate_hash is distinct from
          (v_job.payload_json ->> 'closure_certificate_hash')
     or v_package.closure_certificate_hash is distinct from
          v_projection.closure_certificate_hash
     or v_package.closure_snapshot_hash is distinct from
          (v_job.payload_json ->> 'snapshot_hash')
     or v_package.closure_snapshot_hash is distinct from
          v_projection.snapshot_hash
     or v_package.status <> 'preview_ready'
     or v_package.created_by is distinct from v_job.requested_by then
    if v_reused then
      return v_result;
    end if;
    raise exception 'portal_lcia_package_post_insert_validation_failed'
      using errcode = 'P5271';
  end if;

  return jsonb_build_object(
    'ok', true,
    'reused', v_reused,
    'data', jsonb_build_object(
      'packageId', v_package.id,
      'packageVersion', v_package.package_version,
      'status', v_package.status,
      'buildWorkerJobId', v_package.build_worker_job_id,
      'includedInputCount', v_package.included_input_count,
      'projection', jsonb_build_object(
        'projectionId', v_projection.id,
        'contentHash', v_projection.content_hash,
        'hashContractVersion',
          'portal.lcia-projection.int32be-frame-sha256.v1'
      )
    )
  );
  exception when sqlstate 'P5271' then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_package_binding_invalid', 'status', 409
    );
  end;
end
$_$;


ALTER FUNCTION private.svc_portal_lcia_projection_package_mark_ready_v1(p_projection_id uuid, p_build_worker_job_id uuid, p_lease_token uuid, p_package_version text, p_snapshot_id uuid, p_result_id uuid, p_latest_all_unit_result_id uuid, p_result_artifact_ref jsonb, p_query_artifact_ref jsonb, p_artifact_manifest jsonb, p_available_impact_categories jsonb, p_default_impact_category text, p_package_result_hash text, p_audit jsonb) OWNER TO postgres;

--
-- Name: svc_portal_lcia_projection_package_ready_readback_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_portal_lcia_projection_package_ready_readback_v1(p_build_worker_job_id uuid, p_current_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_package private.lcia_result_packages%rowtype;
  v_projection private.portal_lcia_projection_headers%rowtype;
  v_projection_id uuid;
  v_projection_content_hash text;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false, 'code', 'service_role_required', 'status', 403
    );
  end if;
  if private.portal_lcia_projection_v3_job_binding_valid_v1(
       p_build_worker_job_id, p_current_lease_token
     ) is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_lease_invalid', 'status', 409
    );
  end if;

  select package.* into v_package
  from private.lcia_result_packages as package
  where package.build_worker_job_id = p_build_worker_job_id;
  if v_package.id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_package_not_found', 'status', 404
    );
  end if;

  begin
    v_projection_id := nullif(
      v_package.artifact_manifest ->> 'portalProjectionId', ''
    )::uuid;
  exception when invalid_text_representation then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_package_binding_invalid', 'status', 409
    );
  end;
  v_projection_content_hash := nullif(
    v_package.artifact_manifest ->> 'portalProjectionContentHash', ''
  );

  select projection.* into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.id = v_projection_id
    and projection.build_worker_job_id = p_build_worker_job_id
    and projection.status = 'prepared'
    and projection.content_hash = v_projection_content_hash;
  if v_projection.id is null
     or private.portal_lcia_projection_package_binding_valid_v1(
       v_package.id, p_build_worker_job_id, v_projection.id
     ) is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_package_binding_invalid', 'status', 409
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'reused', true,
    'data', jsonb_build_object(
      'packageId', v_package.id,
      'packageVersion', v_package.package_version,
      'status', v_package.status,
      'buildWorkerJobId', v_package.build_worker_job_id,
      'includedInputCount', v_package.included_input_count,
      'projection', jsonb_build_object(
        'projectionId', v_projection.id,
        'contentHash', v_projection.content_hash,
        'hashContractVersion',
          'portal.lcia-projection.int32be-frame-sha256.v1'
      )
    )
  );
end
$$;


ALTER FUNCTION private.svc_portal_lcia_projection_package_ready_readback_v1(p_build_worker_job_id uuid, p_current_lease_token uuid) OWNER TO postgres;

--
-- Name: svc_portal_lcia_projection_stage_begin_v1(uuid, uuid, integer, integer, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_portal_lcia_projection_stage_begin_v1(p_build_worker_job_id uuid, p_stage_lease_token uuid, p_process_count integer, p_impact_count integer, p_source jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_job private.worker_jobs%rowtype;
  v_projection private.portal_lcia_projection_headers%rowtype;
  v_expected_process_count integer;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false, 'code', 'service_role_required', 'status', 403
    );
  end if;

  if p_build_worker_job_id is null
     or p_stage_lease_token is null
     or p_process_count is null
     or p_impact_count is null
     or p_process_count not between 1 and 1000000
     or p_impact_count not between 1 and 10000
     or p_process_count::bigint * p_impact_count::bigint > 100000000
     or private.portal_lcia_json_object_has_keys_v1(
       p_source,
       array[
         'schemaVersion',
         'bundleContentHash',
         'bundleManifestSha256',
         'lciaChunkSetSha256',
         'resultArtifactSha256',
         'queryArtifactSha256'
       ]
     ) is not true
     or jsonb_typeof(p_source -> 'schemaVersion') <> 'string'
     or jsonb_typeof(p_source -> 'bundleContentHash') <> 'string'
     or jsonb_typeof(p_source -> 'bundleManifestSha256') <> 'string'
     or jsonb_typeof(p_source -> 'lciaChunkSetSha256') <> 'string'
     or jsonb_typeof(p_source -> 'resultArtifactSha256') <> 'string'
     or jsonb_typeof(p_source -> 'queryArtifactSha256') <> 'string'
     or p_source ->> 'schemaVersion' <> 'portal.lcia-projection.source.v1'
     or coalesce(p_source ->> 'bundleContentHash', '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source ->> 'bundleManifestSha256', '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source ->> 'lciaChunkSetSha256', '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source ->> 'resultArtifactSha256', '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source ->> 'queryArtifactSha256', '') !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_projection_request', 'status', 400
    );
  end if;

  select job.*
  into v_job
  from private.worker_jobs as job
  where job.id = p_build_worker_job_id
  for update;

  if v_job.id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_job_not_found', 'status', 404
    );
  end if;
  if v_job.job_kind <> 'lcia_result.package_build'
     or v_job.payload_schema_version <> 'lcia_result.package_build.request.v3'
     or v_job.payload_json ->> 'portalProjectionContractVersion'
          <> 'portal.lcia-projection.v1'
     or jsonb_typeof(v_job.payload_json -> 'input_manifest' -> 'processes')
          <> 'array'
     or jsonb_typeof(v_job.payload_json -> 'lcia_method_set') <> 'array'
     or coalesce(v_job.payload_json ->> 'input_manifest_hash', '')
          !~ '^[0-9a-f]{64}$'
     or coalesce(v_job.payload_json ->> 'closure_certificate_hash', '')
          !~ '^[0-9a-f]{64}$'
     or coalesce(v_job.payload_json ->> 'snapshot_hash', '')
          !~ '^[0-9a-f]{64}$'
     or coalesce(v_job.payload_json ->> 'closure_bundle_hash', '')
          !~ '^[0-9a-f]{64}$'
     or coalesce(v_job.payload_json ->> 'snapshot_index_sha256', '')
          !~ '^[0-9a-f]{64}$'
     or coalesce(v_job.payload_json ->> 'snapshot_build_contract_hash', '')
          !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_job_contract_invalid', 'status', 409
    );
  end if;

  if v_job.status <> 'running'
     or v_job.lease_token is distinct from p_stage_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at <= clock_timestamp() then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_lease_invalid', 'status', 409
    );
  end if;

  v_expected_process_count := jsonb_array_length(
    v_job.payload_json -> 'input_manifest' -> 'processes'
  );
  if v_expected_process_count <> p_process_count then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_process_count_mismatch', 'status', 409
    );
  end if;
  if jsonb_array_length(v_job.payload_json -> 'lcia_method_set')
       <> p_impact_count then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_impact_count_mismatch', 'status', 409
    );
  end if;

  select projection.*
  into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.build_worker_job_id = p_build_worker_job_id
    and projection.stage_lease_token = p_stage_lease_token
  for update;

  if v_projection.id is not null then
    if v_projection.process_count <> p_process_count
       or v_projection.impact_count <> p_impact_count
       or v_projection.bundle_content_hash
            <> p_source ->> 'bundleContentHash'
       or v_projection.bundle_manifest_sha256
            <> p_source ->> 'bundleManifestSha256'
       or v_projection.lcia_chunk_set_sha256
            <> p_source ->> 'lciaChunkSetSha256'
       or v_projection.result_artifact_sha256
            <> p_source ->> 'resultArtifactSha256'
       or v_projection.query_artifact_sha256
            <> p_source ->> 'queryArtifactSha256' then
      return jsonb_build_object(
        'ok', false, 'code', 'projection_conflict', 'status', 409
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'idempotentReplay', true,
      'data', jsonb_build_object(
        'projectionId', v_projection.id,
        'buildWorkerJobId', v_projection.build_worker_job_id,
        'status', v_projection.status,
        'processCount', v_projection.process_count,
        'impactCount', v_projection.impact_count,
        'expectedValueCount', v_projection.expected_value_count,
        'hashContractVersion', 'portal.lcia-projection.int32be-frame-sha256.v1'
      )
    );
  end if;

  insert into private.portal_lcia_projection_headers (
    build_worker_job_id,
    stage_lease_token,
    projection_contract_version,
    process_count,
    impact_count,
    input_manifest_hash,
    closure_certificate_hash,
    snapshot_hash,
    closure_bundle_hash,
    snapshot_index_sha256,
    snapshot_build_contract_hash,
    bundle_content_hash,
    bundle_manifest_sha256,
    lcia_chunk_set_sha256,
    result_artifact_sha256,
    query_artifact_sha256
  ) values (
    v_job.id,
    p_stage_lease_token,
    'portal.lcia-projection.v1',
    p_process_count,
    p_impact_count,
    v_job.payload_json ->> 'input_manifest_hash',
    v_job.payload_json ->> 'closure_certificate_hash',
    v_job.payload_json ->> 'snapshot_hash',
    v_job.payload_json ->> 'closure_bundle_hash',
    v_job.payload_json ->> 'snapshot_index_sha256',
    v_job.payload_json ->> 'snapshot_build_contract_hash',
    p_source ->> 'bundleContentHash',
    p_source ->> 'bundleManifestSha256',
    p_source ->> 'lciaChunkSetSha256',
    p_source ->> 'resultArtifactSha256',
    p_source ->> 'queryArtifactSha256'
  )
  returning * into v_projection;

  return jsonb_build_object(
    'ok', true,
    'idempotentReplay', false,
    'data', jsonb_build_object(
      'projectionId', v_projection.id,
      'buildWorkerJobId', v_projection.build_worker_job_id,
      'status', v_projection.status,
      'processCount', v_projection.process_count,
      'impactCount', v_projection.impact_count,
      'expectedValueCount', v_projection.expected_value_count,
      'hashContractVersion', 'portal.lcia-projection.int32be-frame-sha256.v1'
    )
  );
exception
  when unique_violation then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_conflict', 'status', 409
    );
end
$_$;


ALTER FUNCTION private.svc_portal_lcia_projection_stage_begin_v1(p_build_worker_job_id uuid, p_stage_lease_token uuid, p_process_count integer, p_impact_count integer, p_source jsonb) OWNER TO postgres;

--
-- Name: FUNCTION svc_portal_lcia_projection_stage_begin_v1(p_build_worker_job_id uuid, p_stage_lease_token uuid, p_process_count integer, p_impact_count integer, p_source jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_portal_lcia_projection_stage_begin_v1(p_build_worker_job_id uuid, p_stage_lease_token uuid, p_process_count integer, p_impact_count integer, p_source jsonb) IS 'Begins one V3 Worker lease-fenced, locator-free Portal LCIA projection attempt.';


--
-- Name: svc_portal_lcia_projection_stage_fail_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_portal_lcia_projection_stage_fail_v1(p_projection_id uuid, p_stage_lease_token uuid, p_code text, p_message text, p_audit jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_projection private.portal_lcia_projection_headers%rowtype;
  v_job private.worker_jobs%rowtype;
  v_code text := btrim(coalesce(p_code, ''));
  v_message text := nullif(btrim(coalesce(p_message, '')), '');
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false, 'code', 'service_role_required', 'status', 403
    );
  end if;
  if length(v_code) not between 1 and 128
     or v_code !~ '^[a-z0-9_]+$'
     or (
       v_message is not null
       and private.portal_lcia_public_text_valid_v1(v_message, 2000)
             is not true
     )
     or private.portal_lcia_safe_audit_v1(p_audit) is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_projection_request', 'status', 400
    );
  end if;
  select projection.* into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.id = p_projection_id
  for update;
  if v_projection.id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_found', 'status', 404
    );
  end if;
  select job.* into v_job
  from private.worker_jobs as job
  where job.id = v_projection.build_worker_job_id
  for share;
  if v_projection.stage_lease_token is distinct from p_stage_lease_token
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_stage_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at <= clock_timestamp() then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_lease_invalid', 'status', 409
    );
  end if;
  if v_projection.status = 'failed'
     and v_projection.failure_code = v_code
     and v_projection.failure_message is not distinct from v_message then
    return jsonb_build_object(
      'ok', true, 'idempotentReplay', true,
      'data', jsonb_build_object(
        'projectionId', v_projection.id, 'status', v_projection.status
      )
    );
  end if;
  if v_projection.status <> 'staging' then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_staging', 'status', 409
    );
  end if;

  update private.portal_lcia_projection_headers
  set status = 'failed',
      failure_code = v_code,
      failure_message = v_message,
      failed_at = clock_timestamp()
  where id = v_projection.id
  returning * into v_projection;

  insert into private.command_audit_log (
    command, actor_user_id, target_table, target_id, target_version, payload
  ) values (
    'svc_portal_lcia_projection_stage_fail_v1',
    v_job.requested_by,
    'portal_lcia_projection_headers',
    v_projection.id,
    v_projection.projection_contract_version,
    coalesce(p_audit, '{}'::jsonb) || jsonb_build_object(
      'buildWorkerJobId', v_projection.build_worker_job_id,
      'failureCode', v_code,
      'failureMessage', v_message
    )
  );

  return jsonb_build_object(
    'ok', true, 'idempotentReplay', false,
    'data', jsonb_build_object(
      'projectionId', v_projection.id, 'status', v_projection.status
    )
  );
end
$_$;


ALTER FUNCTION private.svc_portal_lcia_projection_stage_fail_v1(p_projection_id uuid, p_stage_lease_token uuid, p_code text, p_message text, p_audit jsonb) OWNER TO postgres;

--
-- Name: svc_portal_lcia_projection_stage_register_batch_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_portal_lcia_projection_stage_register_batch_v1(p_projection_id uuid, p_stage_lease_token uuid, p_batch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_projection private.portal_lcia_projection_headers%rowtype;
  v_job private.worker_jobs%rowtype;
  v_record jsonb;
  v_expected_process jsonb;
  v_expected_method jsonb;
  v_process private.portal_lcia_projection_process_axis%rowtype;
  v_impact private.portal_lcia_projection_impact_axis%rowtype;
  v_value private.portal_lcia_projection_values%rowtype;
  v_process_index integer;
  v_impact_index integer;
  v_ordinal bigint;
  v_decimal text;
  v_record_hash text;
  v_inserted integer := 0;
  v_row_count integer := 0;
  v_batch_count integer;
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false, 'code', 'service_role_required', 'status', 403
    );
  end if;

  if p_projection_id is null
     or p_stage_lease_token is null
     or pg_catalog.octet_length(
       pg_catalog.convert_to(p_batch::text, 'UTF8')
     ) > 1048576
     or private.portal_lcia_json_object_has_keys_v1(
       p_batch,
       array['schemaVersion', 'processes', 'impacts', 'values']
     ) is not true
     or p_batch ->> 'schemaVersion' <> 'portal.lcia-projection.batch.v1'
     or jsonb_typeof(p_batch -> 'processes') <> 'array'
     or jsonb_typeof(p_batch -> 'impacts') <> 'array'
     or jsonb_typeof(p_batch -> 'values') <> 'array' then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_projection_batch', 'status', 400
    );
  end if;

  v_batch_count := jsonb_array_length(p_batch -> 'processes')
    + jsonb_array_length(p_batch -> 'impacts')
    + jsonb_array_length(p_batch -> 'values');
  if v_batch_count < 1 or v_batch_count > 500
     or exists (
       select 1
       from jsonb_array_elements(p_batch -> 'processes') as item(value)
       group by item.value ->> 'processIndex'
       having count(*) > 1
     )
     or exists (
       select 1
       from jsonb_array_elements(p_batch -> 'impacts') as item(value)
       group by item.value ->> 'impactIndex'
       having count(*) > 1
     )
     or exists (
       select 1
       from jsonb_array_elements(p_batch -> 'values') as item(value)
       group by item.value ->> 'ordinal'
       having count(*) > 1
     ) then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_projection_batch', 'status', 400
    );
  end if;

  select projection.*
  into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.id = p_projection_id
  for update;
  if v_projection.id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_found', 'status', 404
    );
  end if;

  select job.*
  into v_job
  from private.worker_jobs as job
  where job.id = v_projection.build_worker_job_id
  for share;
  if v_projection.stage_lease_token is distinct from p_stage_lease_token
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_stage_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at <= clock_timestamp() then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_lease_invalid', 'status', 409
    );
  end if;
  if v_projection.status <> 'staging' then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_staging', 'status', 409
    );
  end if;

  begin
    for v_record in
      select item.value
      from jsonb_array_elements(p_batch -> 'processes') as item(value)
    loop
      if private.portal_lcia_json_object_has_keys_v1(
        v_record,
        array[
          'processIndex', 'processId', 'processVersion',
          'referenceFlowId', 'referenceFlowVersion',
          'referenceExchangeInternalId', 'referenceFlowAmount',
          'referenceFlowDirection', 'functionalUnitAmount',
          'functionalUnitUnit', 'functionalUnitDescription',
          'geographyCode', 'geographyPrecision', 'referenceYear',
          'processDocumentSha256'
        ]
      ) is not true then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;
      if jsonb_typeof(v_record -> 'processIndex') <> 'number'
         or jsonb_typeof(v_record -> 'referenceYear') <> 'number'
         or jsonb_typeof(v_record -> 'processId') <> 'string'
         or jsonb_typeof(v_record -> 'processVersion') <> 'string'
         or jsonb_typeof(v_record -> 'referenceFlowId') <> 'string'
         or jsonb_typeof(v_record -> 'referenceFlowVersion') <> 'string'
         or jsonb_typeof(v_record -> 'referenceExchangeInternalId') <> 'string'
         or jsonb_typeof(v_record -> 'referenceFlowAmount') <> 'string'
         or jsonb_typeof(v_record -> 'referenceFlowDirection') <> 'string'
         or jsonb_typeof(v_record -> 'functionalUnitAmount') <> 'string'
         or jsonb_typeof(v_record -> 'functionalUnitUnit') <> 'string'
         or jsonb_typeof(v_record -> 'geographyCode') <> 'string'
         or jsonb_typeof(v_record -> 'geographyPrecision') <> 'string'
         or jsonb_typeof(v_record -> 'processDocumentSha256') <> 'string' then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;
      begin
        v_process_index := (v_record ->> 'processIndex')::integer;
        v_process.process_id := (v_record ->> 'processId')::uuid;
        v_process.reference_flow_id := (v_record ->> 'referenceFlowId')::uuid;
        v_process.reference_year := (v_record ->> 'referenceYear')::integer;
      exception when others then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end;
      v_decimal := private.portal_canonical_decimal_v1(
        v_record ->> 'functionalUnitAmount'
      );
      v_expected_process := v_job.payload_json
        -> 'input_manifest' -> 'processes' -> v_process_index;
      if v_record ->> 'processIndex' !~ '^(0|[1-9]\d*)$'
         or v_record ->> 'referenceYear' !~ '^(0|[1-9]\d*)$'
         or v_process_index not between 0 and v_projection.process_count - 1
         or v_decimal is distinct from v_record ->> 'functionalUnitAmount'
         or private.portal_canonical_decimal_v1(
              v_record ->> 'referenceFlowAmount'
            ) is distinct from v_record ->> 'referenceFlowAmount'
         or coalesce(v_record ->> 'processVersion', '')
              !~ '^\d{2}\.\d{2}\.\d{3}$'
         or coalesce(v_record ->> 'referenceFlowVersion', '')
              !~ '^\d{2}\.\d{2}\.\d{3}$'
         or coalesce(v_record ->> 'referenceExchangeInternalId', '')
              !~ '^(0|[1-9]\d{0,5})$'
         or v_record ->> 'referenceFlowDirection' not in ('input', 'output')
         or private.portal_lcia_public_text_valid_v1(
              v_record ->> 'functionalUnitUnit', 128
            ) is not true
         or private.portal_lcia_localized_text_valid_v1(
              v_record -> 'functionalUnitDescription'
            ) is not true
         or private.portal_lcia_public_text_valid_v1(
              v_record ->> 'geographyCode', 128
            ) is not true
         or v_record ->> 'geographyPrecision'
              not in ('country', 'province', 'city', 'other', 'unknown')
         or v_process.reference_year not between 0 and 9999
         or coalesce(v_record ->> 'processDocumentSha256', '')
              !~ '^[0-9a-f]{64}$'
         or jsonb_typeof(v_expected_process) <> 'object'
         or v_expected_process ->> 'id'
              is distinct from v_process.process_id::text
         or v_expected_process ->> 'version'
              is distinct from v_record ->> 'processVersion' then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;

      v_record_hash := private.portal_lcia_projection_sha256_fields_v1(
        'portal.lcia-projection.process.v1',
        'portal.lcia-projection.int32be-frame-sha256.v1',
        v_process_index::text,
        v_process.process_id::text,
        v_record ->> 'processVersion',
        v_process.reference_flow_id::text,
        v_record ->> 'referenceFlowVersion',
        v_record ->> 'referenceExchangeInternalId',
        private.portal_canonical_decimal_v1(v_record ->> 'referenceFlowAmount'),
        v_record ->> 'referenceFlowDirection',
        v_decimal,
        btrim(v_record ->> 'functionalUnitUnit'),
        private.portal_lcia_localized_text_frame_hex_v1(
          v_record -> 'functionalUnitDescription'
        ),
        btrim(v_record ->> 'geographyCode'),
        v_record ->> 'geographyPrecision',
        v_process.reference_year::text,
        v_record ->> 'processDocumentSha256'
      );

      insert into private.portal_lcia_projection_process_axis (
        projection_id, process_index, process_id, process_version,
        reference_flow_id, reference_flow_version,
        reference_exchange_internal_id, reference_flow_amount,
        reference_flow_direction, functional_unit_amount,
        functional_unit_unit, functional_unit_description,
        geography_code, geography_precision, reference_year,
        process_document_sha256, record_hash
      ) values (
        v_projection.id, v_process_index, v_process.process_id,
        v_record ->> 'processVersion', v_process.reference_flow_id,
        v_record ->> 'referenceFlowVersion',
        v_record ->> 'referenceExchangeInternalId',
        private.portal_canonical_decimal_v1(v_record ->> 'referenceFlowAmount'),
        v_record ->> 'referenceFlowDirection', v_decimal,
        btrim(v_record ->> 'functionalUnitUnit'),
        v_record -> 'functionalUnitDescription',
        btrim(v_record ->> 'geographyCode'),
        v_record ->> 'geographyPrecision', v_process.reference_year,
        v_record ->> 'processDocumentSha256', v_record_hash
      ) on conflict do nothing;
      get diagnostics v_row_count = row_count;
      v_inserted := v_inserted + v_row_count;

      select row.* into v_process
      from private.portal_lcia_projection_process_axis as row
      where row.projection_id = v_projection.id
        and row.process_index = v_process_index;
      if v_process.record_hash is distinct from v_record_hash then
        raise exception using errcode = 'P2102', message = 'projection batch conflict';
      end if;
    end loop;

    for v_record in
      select item.value
      from jsonb_array_elements(p_batch -> 'impacts') as item(value)
    loop
      if private.portal_lcia_json_object_has_keys_v1(
        v_record,
        array[
          'impactIndex', 'methodId', 'methodVersion', 'impactId',
          'impactName', 'unit', 'methodDocumentSha256'
        ]
      ) is not true then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;
      if jsonb_typeof(v_record -> 'impactIndex') <> 'number'
         or jsonb_typeof(v_record -> 'methodId') <> 'string'
         or jsonb_typeof(v_record -> 'methodVersion') <> 'string'
         or jsonb_typeof(v_record -> 'impactId') <> 'string'
         or jsonb_typeof(v_record -> 'unit') <> 'string'
         or jsonb_typeof(v_record -> 'methodDocumentSha256') <> 'string' then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;
      begin
        v_impact_index := (v_record ->> 'impactIndex')::integer;
        v_impact.method_id := (v_record ->> 'methodId')::uuid;
      exception when others then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end;
      v_expected_method := v_job.payload_json
        -> 'lcia_method_set' -> v_impact_index;
      if v_record ->> 'impactIndex' !~ '^(0|[1-9]\d*)$'
         or v_impact_index not between 0 and v_projection.impact_count - 1
         or coalesce(v_record ->> 'methodVersion', '')
              !~ '^\d{2}\.\d{2}\.\d{3}$'
         or private.portal_lcia_public_text_valid_v1(
              v_record ->> 'impactId', 512
            ) is not true
         or private.portal_lcia_localized_text_valid_v1(
              v_record -> 'impactName'
            ) is not true
         or private.portal_lcia_public_text_valid_v1(
              v_record ->> 'unit', 128
            ) is not true
         or coalesce(v_record ->> 'methodDocumentSha256', '')
              !~ '^[0-9a-f]{64}$'
         or jsonb_typeof(v_expected_method) <> 'object'
         or v_expected_method ->> 'id'
              is distinct from v_impact.method_id::text
         or v_expected_method ->> 'version'
              is distinct from v_record ->> 'methodVersion' then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;

      v_record_hash := private.portal_lcia_projection_sha256_fields_v1(
        'portal.lcia-projection.impact.v1',
        'portal.lcia-projection.int32be-frame-sha256.v1',
        v_impact_index::text,
        v_impact.method_id::text,
        v_record ->> 'methodVersion',
        btrim(v_record ->> 'impactId'),
        private.portal_lcia_localized_text_frame_hex_v1(
          v_record -> 'impactName'
        ),
        btrim(v_record ->> 'unit'),
        v_record ->> 'methodDocumentSha256'
      );
      insert into private.portal_lcia_projection_impact_axis (
        projection_id, impact_index, method_id, method_version,
        impact_id, impact_name, unit, method_document_sha256, record_hash
      ) values (
        v_projection.id, v_impact_index, v_impact.method_id,
        v_record ->> 'methodVersion', btrim(v_record ->> 'impactId'),
        v_record -> 'impactName', btrim(v_record ->> 'unit'),
        v_record ->> 'methodDocumentSha256', v_record_hash
      ) on conflict do nothing;
      get diagnostics v_row_count = row_count;
      v_inserted := v_inserted + v_row_count;

      select row.* into v_impact
      from private.portal_lcia_projection_impact_axis as row
      where row.projection_id = v_projection.id
        and row.impact_index = v_impact_index;
      if v_impact.record_hash is distinct from v_record_hash then
        raise exception using errcode = 'P2102', message = 'projection batch conflict';
      end if;
    end loop;

    for v_record in
      select item.value
      from jsonb_array_elements(p_batch -> 'values') as item(value)
    loop
      if private.portal_lcia_json_object_has_keys_v1(
        v_record,
        array['ordinal', 'processIndex', 'impactIndex', 'value']
      ) is not true then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;
      if jsonb_typeof(v_record -> 'ordinal') <> 'number'
         or jsonb_typeof(v_record -> 'processIndex') <> 'number'
         or jsonb_typeof(v_record -> 'impactIndex') <> 'number'
         or jsonb_typeof(v_record -> 'value') <> 'string' then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;
      begin
        v_ordinal := (v_record ->> 'ordinal')::bigint;
        v_process_index := (v_record ->> 'processIndex')::integer;
        v_impact_index := (v_record ->> 'impactIndex')::integer;
      exception when others then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end;
      v_decimal := private.portal_canonical_decimal_v1(v_record ->> 'value');
      if v_record ->> 'ordinal' !~ '^[1-9]\d*$'
         or v_record ->> 'processIndex' !~ '^(0|[1-9]\d*)$'
         or v_record ->> 'impactIndex' !~ '^(0|[1-9]\d*)$'
         or v_process_index not between 0 and v_projection.process_count - 1
         or v_impact_index not between 0 and v_projection.impact_count - 1
         or v_ordinal < 1
         or v_ordinal <>
              v_process_index::bigint * v_projection.impact_count::bigint
              + v_impact_index::bigint + 1
         or v_decimal is distinct from v_record ->> 'value' then
        raise exception using errcode = 'P2101', message = 'invalid projection batch';
      end if;

      v_record_hash := private.portal_lcia_projection_sha256_fields_v1(
        'portal.lcia-projection.value.v1',
        'portal.lcia-projection.int32be-frame-sha256.v1',
        v_ordinal::text,
        v_process_index::text,
        v_impact_index::text,
        v_decimal
      );
      insert into private.portal_lcia_projection_values (
        projection_id, ordinal, process_index, impact_index,
        value_text, value_numeric, record_hash
      ) values (
        v_projection.id, v_ordinal, v_process_index, v_impact_index,
        v_decimal, v_decimal::numeric, v_record_hash
      ) on conflict do nothing;
      get diagnostics v_row_count = row_count;
      v_inserted := v_inserted + v_row_count;

      select row.* into v_value
      from private.portal_lcia_projection_values as row
      where row.projection_id = v_projection.id
        and row.ordinal = v_ordinal;
      if v_value.record_hash is distinct from v_record_hash then
        raise exception using errcode = 'P2102', message = 'projection batch conflict';
      end if;
    end loop;
  exception
    when sqlstate 'P2101' or invalid_text_representation
      or numeric_value_out_of_range or check_violation
      or foreign_key_violation or not_null_violation then
      return jsonb_build_object(
        'ok', false, 'code', 'invalid_projection_batch', 'status', 400
      );
    when sqlstate 'P2102' or unique_violation then
      return jsonb_build_object(
        'ok', false, 'code', 'projection_batch_conflict', 'status', 409
      );
  end;

  return jsonb_build_object(
    'ok', true,
    'idempotentReplay', v_inserted = 0,
    'data', jsonb_build_object(
      'projectionId', v_projection.id,
      'acceptedRecordCount', v_batch_count,
      'insertedRecordCount', v_inserted
    )
  );
end
$_$;


ALTER FUNCTION private.svc_portal_lcia_projection_stage_register_batch_v1(p_projection_id uuid, p_stage_lease_token uuid, p_batch jsonb) OWNER TO postgres;

--
-- Name: FUNCTION svc_portal_lcia_projection_stage_register_batch_v1(p_projection_id uuid, p_stage_lease_token uuid, p_batch jsonb); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.svc_portal_lcia_projection_stage_register_batch_v1(p_projection_id uuid, p_stage_lease_token uuid, p_batch jsonb) IS 'Registers at most 500 typed records and 1 MiB per exact-replay-safe batch.';


--
-- Name: svc_portal_lcia_projection_stage_seal_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.svc_portal_lcia_projection_stage_seal_v1(p_projection_id uuid, p_stage_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_projection private.portal_lcia_projection_headers%rowtype;
  v_job private.worker_jobs%rowtype;
  v_process_count bigint;
  v_impact_count bigint;
  v_value_count bigint;
  v_bad_count bigint;
  v_process_axis_hash text;
  v_impact_axis_hash text;
  v_value_grid_hash text;
  v_relation_hash text;
  v_content_hash text;
  v_fields text[];
begin
  if not coalesce(util.is_service_request(), false) then
    return jsonb_build_object(
      'ok', false, 'code', 'service_role_required', 'status', 403
    );
  end if;
  select projection.* into v_projection
  from private.portal_lcia_projection_headers as projection
  where projection.id = p_projection_id
  for update;
  if v_projection.id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_found', 'status', 404
    );
  end if;
  select job.* into v_job
  from private.worker_jobs as job
  where job.id = v_projection.build_worker_job_id
  for share;
  if v_projection.stage_lease_token is distinct from p_stage_lease_token
     or v_job.status <> 'running'
     or v_job.lease_token is distinct from p_stage_lease_token
     or v_job.lease_expires_at is null
     or v_job.lease_expires_at <= clock_timestamp() then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_lease_invalid', 'status', 409
    );
  end if;
  if v_projection.status = 'prepared' then
    return jsonb_build_object(
      'ok', true,
      'idempotentReplay', true,
      'data', jsonb_build_object(
        'projectionId', v_projection.id,
        'status', v_projection.status,
        'processCount', v_projection.process_count,
        'impactCount', v_projection.impact_count,
        'valueCount', v_projection.expected_value_count,
        'processAxisHash', v_projection.process_axis_hash,
        'impactAxisHash', v_projection.impact_axis_hash,
        'valueGridHash', v_projection.value_grid_hash,
        'relationHash', v_projection.relation_hash,
        'contentHash', v_projection.content_hash,
        'hashContractVersion', 'portal.lcia-projection.int32be-frame-sha256.v1'
      )
    );
  end if;
  if v_projection.status <> 'staging' then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_not_staging', 'status', 409
    );
  end if;

  select count(*),
         count(*) filter (where process_index between 0 and v_projection.process_count - 1)
  into v_process_count, v_bad_count
  from private.portal_lcia_projection_process_axis
  where projection_id = v_projection.id;
  if v_process_count <> v_projection.process_count
     or v_bad_count <> v_projection.process_count then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_incomplete', 'status', 409
    );
  end if;

  select count(*),
         count(*) filter (where impact_index between 0 and v_projection.impact_count - 1)
  into v_impact_count, v_bad_count
  from private.portal_lcia_projection_impact_axis
  where projection_id = v_projection.id;
  if v_impact_count <> v_projection.impact_count
     or v_bad_count <> v_projection.impact_count then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_incomplete', 'status', 409
    );
  end if;

  select count(*),
         count(*) filter (
           where ordinal = process_index::bigint * v_projection.impact_count::bigint
             + impact_index::bigint + 1
             and ordinal between 1 and v_projection.expected_value_count
         )
  into v_value_count, v_bad_count
  from private.portal_lcia_projection_values
  where projection_id = v_projection.id;
  if v_value_count <> v_projection.expected_value_count
     or v_bad_count <> v_projection.expected_value_count then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_incomplete', 'status', 409
    );
  end if;

  if jsonb_typeof(v_job.payload_json -> 'input_manifest' -> 'processes')
       <> 'array'
     or jsonb_array_length(v_job.payload_json -> 'input_manifest' -> 'processes')
          <> v_projection.process_count
     or jsonb_typeof(v_job.payload_json -> 'lcia_method_set') <> 'array'
     or jsonb_array_length(v_job.payload_json -> 'lcia_method_set')
          <> v_projection.impact_count then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  select count(*) into v_bad_count
  from private.portal_lcia_projection_process_axis as row
  where row.projection_id = v_projection.id
    and (
      v_job.payload_json -> 'input_manifest' -> 'processes' -> row.process_index
        ->> 'id' is distinct from row.process_id::text
      or v_job.payload_json -> 'input_manifest' -> 'processes'
        -> row.process_index ->> 'version' is distinct from row.process_version
    );
  if v_bad_count <> 0 then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  select count(*) into v_bad_count
  from private.portal_lcia_projection_impact_axis as row
  where row.projection_id = v_projection.id
    and (
      v_job.payload_json -> 'lcia_method_set' -> row.impact_index
        ->> 'id' is distinct from row.method_id::text
      or v_job.payload_json -> 'lcia_method_set' -> row.impact_index
        ->> 'version' is distinct from row.method_version
    );
  if v_bad_count <> 0 then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  select count(*) into v_bad_count
  from private.portal_lcia_projection_process_axis as row
  where row.projection_id = v_projection.id
    and row.record_hash is distinct from
      private.portal_lcia_projection_sha256_fields_v1(
        'portal.lcia-projection.process.v1',
        'portal.lcia-projection.int32be-frame-sha256.v1',
        row.process_index::text,
        row.process_id::text,
        row.process_version,
        row.reference_flow_id::text,
        row.reference_flow_version,
        row.reference_exchange_internal_id,
        row.reference_flow_amount,
        row.reference_flow_direction,
        row.functional_unit_amount,
        row.functional_unit_unit,
        private.portal_lcia_localized_text_frame_hex_v1(
          row.functional_unit_description
        ),
        row.geography_code,
        row.geography_precision,
        row.reference_year::text,
        row.process_document_sha256
      );
  if v_bad_count <> 0 then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  select count(*) into v_bad_count
  from private.portal_lcia_projection_impact_axis as row
  where row.projection_id = v_projection.id
    and row.record_hash is distinct from
      private.portal_lcia_projection_sha256_fields_v1(
        'portal.lcia-projection.impact.v1',
        'portal.lcia-projection.int32be-frame-sha256.v1',
        row.impact_index::text,
        row.method_id::text,
        row.method_version,
        row.impact_id,
        private.portal_lcia_localized_text_frame_hex_v1(row.impact_name),
        row.unit,
        row.method_document_sha256
      );
  if v_bad_count <> 0 then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  select count(*) into v_bad_count
  from private.portal_lcia_projection_values as row
  where row.projection_id = v_projection.id
    and row.record_hash is distinct from
      private.portal_lcia_projection_sha256_fields_v1(
        'portal.lcia-projection.value.v1',
        'portal.lcia-projection.int32be-frame-sha256.v1',
        row.ordinal::text,
        row.process_index::text,
        row.impact_index::text,
        row.value_text
      );
  if v_bad_count <> 0 then
    return jsonb_build_object(
      'ok', false, 'code', 'projection_evidence_mismatch', 'status', 409
    );
  end if;

  select array[
    'portal.lcia-projection.relation.v1',
    'portal.lcia-projection.int32be-frame-sha256.v1',
    'process-axis',
    v_projection.process_count::text
  ] || coalesce(
    array_agg(field.value order by row.process_index, field.position),
    '{}'::text[]
  )
  into v_fields
  from private.portal_lcia_projection_process_axis as row
  cross join lateral (
    values (1, (row.process_index + 1)::text), (2, row.record_hash)
  ) as field(position, value)
  where row.projection_id = v_projection.id;
  v_process_axis_hash := private.portal_lcia_projection_sha256_fields_v1(
    variadic v_fields
  );

  select array[
    'portal.lcia-projection.relation.v1',
    'portal.lcia-projection.int32be-frame-sha256.v1',
    'impact-axis',
    v_projection.impact_count::text
  ] || coalesce(
    array_agg(field.value order by row.impact_index, field.position),
    '{}'::text[]
  )
  into v_fields
  from private.portal_lcia_projection_impact_axis as row
  cross join lateral (
    values (1, (row.impact_index + 1)::text), (2, row.record_hash)
  ) as field(position, value)
  where row.projection_id = v_projection.id;
  v_impact_axis_hash := private.portal_lcia_projection_sha256_fields_v1(
    variadic v_fields
  );

  select array[
    'portal.lcia-projection.relation.v1',
    'portal.lcia-projection.int32be-frame-sha256.v1',
    'value-grid',
    v_projection.expected_value_count::text
  ] || coalesce(
    array_agg(field.value order by row.ordinal, field.position),
    '{}'::text[]
  )
  into v_fields
  from private.portal_lcia_projection_values as row
  cross join lateral (
    values (1, row.ordinal::text), (2, row.record_hash)
  ) as field(position, value)
  where row.projection_id = v_projection.id;
  v_value_grid_hash := private.portal_lcia_projection_sha256_fields_v1(
    variadic v_fields
  );

  v_relation_hash := private.portal_lcia_projection_sha256_fields_v1(
    'portal.lcia-projection.grid-relation.v1',
    'portal.lcia-projection.int32be-frame-sha256.v1',
    v_projection.process_count::text,
    v_projection.impact_count::text,
    v_projection.expected_value_count::text,
    'ordinal=processIndex*impactCount+impactIndex+1',
    v_process_axis_hash,
    v_impact_axis_hash,
    v_value_grid_hash
  );
  v_content_hash := private.portal_lcia_projection_sha256_fields_v1(
    'portal.lcia-projection.content.v1',
    'portal.lcia-projection.int32be-frame-sha256.v1',
    v_projection.projection_contract_version,
    v_projection.input_manifest_hash,
    v_projection.closure_certificate_hash,
    v_projection.snapshot_hash,
    v_projection.closure_bundle_hash,
    v_projection.snapshot_index_sha256,
    v_projection.snapshot_build_contract_hash,
    v_projection.bundle_content_hash,
    v_projection.bundle_manifest_sha256,
    v_projection.lcia_chunk_set_sha256,
    v_projection.result_artifact_sha256,
    v_projection.query_artifact_sha256,
    v_projection.process_count::text,
    v_projection.impact_count::text,
    v_projection.expected_value_count::text,
    v_process_axis_hash,
    v_impact_axis_hash,
    v_value_grid_hash,
    v_relation_hash
  );

  update private.portal_lcia_projection_headers
  set status = 'prepared',
      process_axis_hash = v_process_axis_hash,
      impact_axis_hash = v_impact_axis_hash,
      value_grid_hash = v_value_grid_hash,
      relation_hash = v_relation_hash,
      content_hash = v_content_hash,
      prepared_at = clock_timestamp()
  where id = v_projection.id
  returning * into v_projection;

  return jsonb_build_object(
    'ok', true,
    'idempotentReplay', false,
    'data', jsonb_build_object(
      'projectionId', v_projection.id,
      'status', v_projection.status,
      'processCount', v_projection.process_count,
      'impactCount', v_projection.impact_count,
      'valueCount', v_projection.expected_value_count,
      'processAxisHash', v_projection.process_axis_hash,
      'impactAxisHash', v_projection.impact_axis_hash,
      'valueGridHash', v_projection.value_grid_hash,
      'relationHash', v_projection.relation_hash,
      'contentHash', v_projection.content_hash,
      'hashContractVersion', 'portal.lcia-projection.int32be-frame-sha256.v1'
    )
  );
end
$$;


ALTER FUNCTION private.svc_portal_lcia_projection_stage_seal_v1(p_projection_id uuid, p_stage_lease_token uuid) OWNER TO postgres;

