--
-- Name: purge_cron_job_run_details(interval); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.purge_cron_job_run_details(p_retention_window interval DEFAULT '14 days'::interval) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  deleted_count bigint;
begin
  if p_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'cron job run details retention window must be at least 1 day';
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext('util.purge_cron_job_run_details')
  ) then
    return 0;
  end if;

  delete from cron.job_run_details as details
   where details.end_time is not null
     and details.end_time < pg_catalog.now() - p_retention_window
     and coalesce(details.status, '') <> 'running';

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION util.purge_cron_job_run_details(p_retention_window interval) OWNER TO postgres;

--
-- Name: FUNCTION purge_cron_job_run_details(p_retention_window interval); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.purge_cron_job_run_details(p_retention_window interval) IS 'Deletes completed pg_cron run details older than the retention window; open rows and status=running rows are protected.';


--
-- Name: purge_supabase_functions_hooks(interval, integer); Type: FUNCTION; Schema: util; Owner: postgres
--

CREATE FUNCTION util.purge_supabase_functions_hooks(p_retention_window interval DEFAULT '14 days'::interval, p_batch_size integer DEFAULT 50000) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  deleted_count bigint;
begin
  if p_retention_window is null or p_retention_window < interval '1 day' then
    raise exception using
      errcode = '22023',
      message = 'supabase functions hooks retention window must be at least 1 day';
  end if;

  if p_batch_size is null or p_batch_size < 1 or p_batch_size > 100000 then
    raise exception using
      errcode = '22023',
      message = 'supabase functions hooks purge batch size must be between 1 and 100000';
  end if;

  if to_regclass('supabase_functions.hooks') is null then
    return 0;
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext('util.purge_supabase_functions_hooks')
  ) then
    return 0;
  end if;

  with live_responses as materialized (
    select response.id
    from net._http_response as response
  ), candidates as (
    select hooks.id
    from supabase_functions.hooks as hooks
    left join live_responses on live_responses.id = hooks.request_id
    where hooks.created_at < pg_catalog.now() - p_retention_window
      and live_responses.id is null
    order by hooks.created_at, hooks.id
    limit p_batch_size
    for update of hooks skip locked
  )
  delete from supabase_functions.hooks as hooks
  using candidates
  where hooks.id = candidates.id;

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION util.purge_supabase_functions_hooks(p_retention_window interval, p_batch_size integer) OWNER TO postgres;

--
-- Name: FUNCTION purge_supabase_functions_hooks(p_retention_window interval, p_batch_size integer); Type: COMMENT; Schema: util; Owner: postgres
--

COMMENT ON FUNCTION util.purge_supabase_functions_hooks(p_retention_window interval, p_batch_size integer) IS 'Deletes Supabase Functions webhook audit rows older than the retention window in bounded batches while protecting rows still linked to live pg_net responses.';


