--
-- Name: portal_catalog_search_flow_cas_v1_idx; Type: INDEX; Schema: private; Owner: postgres
--

CREATE INDEX portal_catalog_search_flow_cas_v1_idx ON private.portal_catalog_search_rows_v1 USING btree (((card ->> 'casNumber'::text)), id, version DESC, modified_at DESC, state_code DESC) WHERE ((dataset_kind = 'flow'::text) AND (jsonb_typeof((card -> 'casNumber'::text)) = 'string'::text) AND ((card ->> 'casNumber'::text) ~ '^[0-9]{2,7}-[0-9]{2}-[0-9]$'::text) AND ((length((card ->> 'casNumber'::text)) >= 7) AND (length((card ->> 'casNumber'::text)) <= 12)));


--
-- Name: INDEX portal_catalog_search_flow_cas_v1_idx; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON INDEX private.portal_catalog_search_flow_cas_v1_idx IS 'Exact public Flow CAS candidate keys with an explicit 7..12 length discriminator that isolates the index from unconstrained summary selection.';


--
-- Name: portal_catalog_search_flow_document_v1_pgroonga; Type: INDEX; Schema: private; Owner: postgres
--

CREATE INDEX portal_catalog_search_flow_document_v1_pgroonga ON private.portal_catalog_search_rows_v1 USING pgroonga (document) WITH (tokenizer='TokenBigram', normalizer='NormalizerAuto') WHERE (dataset_kind = 'flow'::text);


--
-- Name: portal_catalog_search_process_document_v1_pgroonga; Type: INDEX; Schema: private; Owner: postgres
--

CREATE INDEX portal_catalog_search_process_document_v1_pgroonga ON private.portal_catalog_search_rows_v1 USING pgroonga (document) WITH (tokenizer='TokenBigram', normalizer='NormalizerAuto') WHERE (dataset_kind = 'process'::text);


--
-- Name: portal_catalog_search_process_exact_rank_v1_gin; Type: INDEX; Schema: private; Owner: postgres
--

CREATE INDEX portal_catalog_search_process_exact_rank_v1_gin ON private.portal_catalog_search_rows_v1 USING gin (private.portal_process_rank_name_keys_v1(card), private.portal_process_rank_classification_keys_v1(card)) WHERE (dataset_kind = 'process'::text);


--
-- Name: portal_catalog_search_rows_latest_v1_idx; Type: INDEX; Schema: private; Owner: postgres
--

CREATE INDEX portal_catalog_search_rows_latest_v1_idx ON private.portal_catalog_search_rows_v1 USING btree (dataset_kind, id, version DESC, modified_at DESC, state_code DESC);


--
-- Name: portal_catalog_summary_eligibility_v1_idx; Type: INDEX; Schema: private; Owner: postgres
--

CREATE INDEX portal_catalog_summary_eligibility_v1_idx ON private.portal_catalog_search_rows_v1 USING btree (dataset_kind, id, version DESC, modified_at DESC, state_code DESC) WHERE (((dataset_kind = 'flow'::text) AND (jsonb_typeof((card -> 'casNumber'::text)) = 'string'::text) AND ((card ->> 'casNumber'::text) ~ '^[0-9]{2,7}-[0-9]{2}-[0-9]$'::text)) OR ((jsonb_typeof((card -> 'classifications'::text)) = 'array'::text) AND (jsonb_array_length((card -> 'classifications'::text)) > 0)));


--
-- Name: INDEX portal_catalog_summary_eligibility_v1_idx; Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON INDEX private.portal_catalog_summary_eligibility_v1_idx IS 'Narrow public-card eligibility membership for deterministic Portal CAS/classification examples; stores no card or example value.';


