--
-- Name: reviews Enable insert data access for self; Type: POLICY; Schema: private; Owner: postgres
--

CREATE POLICY "Enable insert data access for self" ON private.reviews FOR INSERT TO authenticated WITH CHECK (((auth.uid() IS NOT NULL) AND (((("json" -> 'user'::text) ->> 'id'::text))::uuid = ( SELECT auth.uid() AS uid))));


--
-- Name: comments Enable insert for review-admin; Type: POLICY; Schema: private; Owner: postgres
--

CREATE POLICY "Enable insert for review-admin" ON private.comments FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM private.roles
  WHERE ((roles.user_id = ( SELECT auth.uid() AS uid)) AND ((roles.role)::text = 'review-admin'::text)))));


--
-- Name: comments; Type: ROW SECURITY; Schema: private; Owner: postgres
--

ALTER TABLE private.comments ENABLE ROW LEVEL SECURITY;

--
-- Name: comments comments select by review participants; Type: POLICY; Schema: private; Owner: postgres
--

CREATE POLICY "comments select by review participants" ON private.comments FOR SELECT TO authenticated USING (((( SELECT auth.uid() AS uid) IS NOT NULL) AND api.policy_review_can_read(review_id, ( SELECT auth.uid() AS uid)) AND (api.cmd_review_is_review_admin(( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM private.reviews r
  WHERE ((r.id = comments.review_id) AND ((((r."json" -> 'user'::text) ->> 'id'::text))::uuid = ( SELECT auth.uid() AS uid))))) OR (reviewer_id = ( SELECT auth.uid() AS uid)))));


--
-- Name: comments comments update by reviewer or review-admin; Type: POLICY; Schema: private; Owner: postgres
--

CREATE POLICY "comments update by reviewer or review-admin" ON private.comments FOR UPDATE TO authenticated USING ((api.policy_is_current_user_in_roles('00000000-0000-0000-0000-000000000000'::uuid, ARRAY['review-admin'::text]) OR (reviewer_id = ( SELECT auth.uid() AS uid)))) WITH CHECK ((api.policy_is_current_user_in_roles('00000000-0000-0000-0000-000000000000'::uuid, ARRAY['review-admin'::text]) OR (reviewer_id = ( SELECT auth.uid() AS uid))));


